/* MathHelper.atan2 in 1.11.2 is a table approximation, not libc atan2. Keep
 * this local to the CPU live game: the CUDA entity spine does not navigate
 * mating animals, and inactive mating never pays the table initialization. */
static double mob_java_math_atan2(double y, double x) {
    static double asine[257];
    static double cosine[257];
    static int initialized;
    const double frac_bias = 17592186044416.0;
    double squared = x * x + y * y;
    uint64_t bits;
    if (isnan(squared)) return NAN;
    if (!initialized) {
        for (int i = 0; i <= 256; ++i) {
            double value = asin((double)i / 256.0);
            asine[i] = value;
            cosine[i] = cos(value);
        }
        initialized = 1;
    }
    int negative_y = y < 0.0;
    if (negative_y) y = -y;
    int negative_x = x < 0.0;
    if (negative_x) x = -x;
    int swapped = y > x;
    if (swapped) {
        double hold = x;
        x = y;
        y = hold;
    }
    double half = 0.5 * squared;
    memcpy(&bits, &squared, sizeof bits);
    bits = UINT64_C(6910469410427058090) - (bits >> 1);
    double inv;
    memcpy(&inv, &bits, sizeof inv);
    inv = inv * (1.5 - half * inv * inv);
    x *= inv;
    y *= inv;
    double biased = frac_bias + y;
    memcpy(&bits, &biased, sizeof bits);
    int index = (int)(uint32_t)bits;
    double table_value = asine[index];
    double quantized = biased - frac_bias;
    double error = y * cosine[index] - x * quantized;
    table_value += (6.0 + error * error) * error
        * 0.16666666666666666;
    if (swapped) table_value = MC_PI / 2.0 - table_value;
    if (negative_x) table_value = MC_PI - table_value;
    if (negative_y) table_value = -table_value;
    return table_value;
}

static float mob_move_helper_yaw(
        float current, double dx, double dz) {
    float target = (float)(
        mob_java_math_atan2(dz, dx) * (180.0 / MC_PI)) - 90.0F;
    float delta = fmodf(target - current, 360.0F);
    if (delta >= 180.0F) delta -= 360.0F;
    if (delta < -180.0F) delta += 360.0F;
    if (delta > 90.0F) delta = 90.0F;
    if (delta < -90.0F) delta = -90.0F;
    float result = current + delta;
    if (result < 0.0F) result += 360.0F;
    else if (result > 360.0F) result -= 360.0F;
    return result;
}

static float animal_mating_movement_speed(int type) {
    if (type == EW_TYPE_COW || type == EW_TYPE_MOOSHROOM)
        return 0.20000000298023224F;
    if (type == EW_TYPE_PIG || type == EW_TYPE_CHICKEN) return 0.25F;
    return 0.23000000417232513F;
}

static EwStore *now_store(GmMobLive *m) { return m->current ? &m->b : &m->a; }
static EwStore *next_store(GmMobLive *m) { return m->current ? &m->a : &m->b; }
static const EwStore *const_store(const GmMobLive *m) { return m->current ? &m->b : &m->a; }

static int xp_slot_limit(const GmMobLive *m) {
    return GM_XP_ORBS + (m ? m->xp_orb_cold_cap : 0);
}

static McOrb *xp_orb_at(GmMobLive *m, int slot) {
    if (!m || slot < 0 || slot >= xp_slot_limit(m)) return NULL;
    return slot < GM_XP_ORBS ? &m->xp_orbs[slot]
        : &m->xp_orb_cold[slot - GM_XP_ORBS].orb;
}

static const McOrb *xp_orb_at_const(const GmMobLive *m, int slot) {
    return xp_orb_at((GmMobLive *)m, slot);
}

static signed char *xp_dimension_at(GmMobLive *m, int slot) {
    if (!m || slot < 0 || slot >= xp_slot_limit(m)) return NULL;
    return slot < GM_XP_ORBS ? &m->orb_dimension[slot]
        : &m->xp_orb_cold[slot - GM_XP_ORBS].dimension;
}

static unsigned int *xp_generation_at(GmMobLive *m, int slot) {
    if (!m || slot < 0 || slot >= xp_slot_limit(m)) return NULL;
    return slot < GM_XP_ORBS ? &m->xp_loaded_generation[slot]
        : &m->xp_orb_cold[slot - GM_XP_ORBS].loaded_generation;
}

static GmXpOrbCold *xp_cold_at(GmMobLive *m, int slot) {
    if (!m || slot < GM_XP_ORBS || slot >= xp_slot_limit(m)) return NULL;
    return &m->xp_orb_cold[slot - GM_XP_ORBS];
}

static unsigned char *xp_uuid_present_at(GmMobLive *m, int slot) {
    if (!m) return NULL;
    GmXpOrbCold *cold = xp_cold_at(m, slot);
    return slot >= 0 && slot < GM_XP_ORBS ? &m->orb_uuid_present[slot]
        : cold ? &cold->uuid_present : NULL;
}

static int64_t *xp_uuid_most_at(GmMobLive *m, int slot) {
    if (!m) return NULL;
    GmXpOrbCold *cold = xp_cold_at(m, slot);
    return slot >= 0 && slot < GM_XP_ORBS ? &m->orb_uuid_most[slot]
        : cold ? &cold->uuid_most : NULL;
}

static int64_t *xp_uuid_least_at(GmMobLive *m, int slot) {
    if (!m) return NULL;
    GmXpOrbCold *cold = xp_cold_at(m, slot);
    return slot >= 0 && slot < GM_XP_ORBS ? &m->orb_uuid_least[slot]
        : cold ? &cold->uuid_least : NULL;
}

static uint64_t *xp_random_seed_at(GmMobLive *m, int slot) {
    if (!m) return NULL;
    GmXpOrbCold *cold = xp_cold_at(m, slot);
    return slot >= 0 && slot < GM_XP_ORBS ? &m->orb_random_seed48[slot]
        : cold ? &cold->random_seed48 : NULL;
}

static int xp_cold_reserve(GmMobLive *m, int need) {
    enum { XP_COLD_SAFETY_MAX = 1048576 };
    GmXpOrbCold *grown;
    int cap;
    if (!m || need < 0 || need > XP_COLD_SAFETY_MAX) return 0;
    if (need <= m->xp_orb_cold_cap) return 1;
    cap = m->xp_orb_cold_cap > 0 ? m->xp_orb_cold_cap : GM_XP_ORBS;
    while (cap < need) {
        if (cap > XP_COLD_SAFETY_MAX / 2) {
            cap = XP_COLD_SAFETY_MAX;
            break;
        }
        cap *= 2;
    }
    grown = (GmXpOrbCold *)realloc(
        m->xp_orb_cold, (size_t)cap * sizeof *grown);
    if (!grown) return 0;
    memset(grown + m->xp_orb_cold_cap, 0,
           (size_t)(cap - m->xp_orb_cold_cap) * sizeof *grown);
    m->xp_orb_cold = grown;
    m->xp_orb_cold_cap = cap;
    return 1;
}

static int xp_free_slot(GmMobLive *m, int allow_growth) {
    int limit = xp_slot_limit(m);
    for (int slot = 0; slot < limit; ++slot) {
        McOrb *orb = xp_orb_at(m, slot);
        if (orb->dead || orb->xpValue <= 0) return slot;
    }
    if (!allow_growth || !xp_cold_reserve(
            m, m->xp_orb_cold_cap + 1)) return -1;
    return limit;
}

static GmMobLoadedRef *loaded_ref_at(GmMobLive *m, int index) {
    if (!m || index < 0
            || index >= GM_MOB_LOADED_ORDER_CAPACITY
                + m->loaded_order_cold_cap)
        return NULL;
    return index < GM_MOB_LOADED_ORDER_CAPACITY
        ? &m->loaded_order[index]
        : &m->loaded_order_cold[index - GM_MOB_LOADED_ORDER_CAPACITY];
}

static const GmMobLoadedRef *loaded_ref_at_const(
        const GmMobLive *m, int index) {
    return loaded_ref_at((GmMobLive *)m, index);
}

static int loaded_order_reserve(GmMobLive *m, int need) {
    enum { LOADED_ORDER_SAFETY_MAX = 1048576 };
    GmMobLoadedRef *grown;
    int cold_need, cap;
    if (!m || need < 0 || need > LOADED_ORDER_SAFETY_MAX) return 0;
    cold_need = need - GM_MOB_LOADED_ORDER_CAPACITY;
    if (cold_need <= 0 || cold_need <= m->loaded_order_cold_cap) return 1;
    cap = m->loaded_order_cold_cap > 0
        ? m->loaded_order_cold_cap : GM_MOB_LOADED_ORDER_CAPACITY;
    while (cap < cold_need) {
        if (cap > LOADED_ORDER_SAFETY_MAX / 2) {
            cap = LOADED_ORDER_SAFETY_MAX;
            break;
        }
        cap *= 2;
    }
    grown = (GmMobLoadedRef *)realloc(
        m->loaded_order_cold, (size_t)cap * sizeof *grown);
    if (!grown) return 0;
    memset(grown + m->loaded_order_cold_cap, 0,
           (size_t)(cap - m->loaded_order_cold_cap) * sizeof *grown);
    m->loaded_order_cold = grown;
    m->loaded_order_cold_cap = cap;
    return 1;
}

static int *tick_order_at(GmMobLive *m, int index) {
    if (!m || index < 0
            || index >= GM_MOB_UPDATE_ORDER_CAPACITY
                + m->tick_update_order_cold_cap)
        return NULL;
    return index < GM_MOB_UPDATE_ORDER_CAPACITY
        ? &m->tick_update_order[index]
        : &m->tick_update_order_cold[index - GM_MOB_UPDATE_ORDER_CAPACITY];
}

static int tick_order_reserve(GmMobLive *m, int need) {
    enum { TICK_ORDER_SAFETY_MAX = 1048576 };
    int *grown;
    int cold_need, cap;
    if (!m || need < 0 || need > TICK_ORDER_SAFETY_MAX) return 0;
    cold_need = need - GM_MOB_UPDATE_ORDER_CAPACITY;
    if (cold_need <= 0 || cold_need <= m->tick_update_order_cold_cap)
        return 1;
    cap = m->tick_update_order_cold_cap > 0
        ? m->tick_update_order_cold_cap : GM_MOB_UPDATE_ORDER_CAPACITY;
    while (cap < cold_need) {
        if (cap > TICK_ORDER_SAFETY_MAX / 2) {
            cap = TICK_ORDER_SAFETY_MAX;
            break;
        }
        cap *= 2;
    }
    grown = (int *)realloc(
        m->tick_update_order_cold, (size_t)cap * sizeof *grown);
    if (!grown) return 0;
    memset(grown + m->tick_update_order_cold_cap, 0,
           (size_t)(cap - m->tick_update_order_cold_cap) * sizeof *grown);
    m->tick_update_order_cold = grown;
    m->tick_update_order_cold_cap = cap;
    return 1;
}

static void tick_order_append(GmMobLive *m, int eid) {
    if (!m || !tick_order_reserve(m, m->tick_update_order_count + 1))
        return;
    *tick_order_at(m, m->tick_update_order_count++) = eid;
}
