static unsigned int loaded_next_generation(unsigned int value) {
    ++value;
    return value ? value : 1U;
}

static int loaded_ref_valid_any(
        const GmMobLive *m, const GmMobLoadedRef *ref) {
    int slot;
    if (!m || !ref) return 0;
    slot = ref->slot;
    if (ref->kind == GM_MOB_LOADED_LIVING) {
        if (slot >= EW_MAX_ENTITIES) {
            int cold_slot = slot - EW_MAX_ENTITIES;
            const GmLivingColdSlot *cold;
            if (cold_slot < 0 || cold_slot >= m->living_cold_count)
                return 0;
            cold = &m->living_cold[cold_slot];
            return cold->store_alive && cold->store_id == ref->eid
                && cold->living_loaded_generation == ref->generation;
        }
        if (slot <= 0
                || ref->generation != m->living_loaded_generation[slot])
            return 0;
        return (m->a.alive[slot] && m->a.id[slot] == ref->eid)
            || (m->b.alive[slot] && m->b.id[slot] == ref->eid);
    }
    if (ref->kind == GM_MOB_LOADED_XP) {
        const McOrb *orb = xp_orb_at_const(m, slot);
        unsigned int *generation = xp_generation_at((GmMobLive *)m, slot);
        if (!orb || !generation || ref->generation != *generation)
            return 0;
        return !orb->dead && orb->xpValue > 0 && orb->eid == ref->eid;
    }
    return 0;
}

static void loaded_order_compact(GmMobLive *m) {
    int out = 0;
    if (!m) return;
    for (int index = 0; index < m->loaded_order_count; ++index) {
        GmMobLoadedRef value = *loaded_ref_at(m, index);
        if (loaded_ref_valid_any(m, &value))
            *loaded_ref_at(m, out++) = value;
    }
    m->loaded_order_count = out;
}

static int loaded_append_living(GmMobLive *m, const EwStore *s, int slot) {
    int cold_slot = slot == GM_MOB_LIVING_STAGE_SLOT
            ? m->living_staged_cold
        : slot == GM_MOB_LIVING_STAGE_SLOT_SECONDARY
            ? m->living_staged_cold_secondary : -1;
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot])
        return 0;
    if (m->loaded_order_count >= GM_MOB_LOADED_ORDER_CAPACITY
            + m->loaded_order_cold_cap)
        loaded_order_compact(m);
    if (!loaded_order_reserve(m, m->loaded_order_count + 1)) return 0;
    m->living_loaded_generation[slot] = loaded_next_generation(
        m->living_loaded_generation[slot]);
    *loaded_ref_at(m, m->loaded_order_count++) = (GmMobLoadedRef){
        .eid = s->id[slot],
        .generation = m->living_loaded_generation[slot],
        .kind = GM_MOB_LOADED_LIVING,
        .slot = (unsigned int)(cold_slot >= 0
            ? EW_MAX_ENTITIES + cold_slot : slot)
    };
    return 1;
}

static int loaded_append_xp(GmMobLive *m, int slot) {
    McOrb *orb = xp_orb_at(m, slot);
    unsigned int *generation = xp_generation_at(m, slot);
    if (!orb || !generation || orb->dead || orb->xpValue <= 0)
        return 0;
    if (m->loaded_order_count >= GM_MOB_LOADED_ORDER_CAPACITY
            + m->loaded_order_cold_cap)
        loaded_order_compact(m);
    if (!loaded_order_reserve(m, m->loaded_order_count + 1)) return 0;
    *generation = loaded_next_generation(*generation);
    *loaded_ref_at(m, m->loaded_order_count++) = (GmMobLoadedRef){
        .eid = orb->eid,
        .generation = *generation,
        .kind = GM_MOB_LOADED_XP,
        .slot = (unsigned int)slot
    };
    return 1;
}

static void loaded_invalidate_living(GmMobLive *m, int slot) {
    if (m && slot > 0 && slot < EW_MAX_ENTITIES)
        m->living_loaded_generation[slot] = loaded_next_generation(
            m->living_loaded_generation[slot]);
}

static void loaded_invalidate_xp(GmMobLive *m, int slot) {
    unsigned int *generation = xp_generation_at(m, slot);
    if (generation) *generation = loaded_next_generation(*generation);
}

static void loaded_order_prepare(GmMobLive *m) {
    if (!m) return;
    loaded_order_compact(m);
    if (m->loaded_order_count != 0) return;
    /* Legacy/cold callers that populate stores without the spawn APIs have no
     * captured Java loaded-list order. Preserve the former deterministic
     * living-then-XP fallback; imported parity states must restore this list. */
    const EwStore *s = const_store(m);
    for (int slot = 1; slot < EW_SPAWN_LIMIT; ++slot)
        if (s->alive[slot]) (void)loaded_append_living(m, s, slot);
    for (int cold_slot = 0; cold_slot < m->living_cold_count; ++cold_slot) {
        GmLivingColdSlot *cold = &m->living_cold[cold_slot];
        if (!cold->store_alive
                || !loaded_order_reserve(m, m->loaded_order_count + 1))
            continue;
        cold->living_loaded_generation = loaded_next_generation(
            cold->living_loaded_generation);
        *loaded_ref_at(m, m->loaded_order_count++) = (GmMobLoadedRef){
            .eid = cold->store_id,
            .generation = cold->living_loaded_generation,
            .kind = GM_MOB_LOADED_LIVING,
            .slot = (unsigned int)(EW_MAX_ENTITIES + cold_slot),
        };
    }
    for (int slot = 0; slot < xp_slot_limit(m); ++slot) {
        const McOrb *orb = xp_orb_at_const(m, slot);
        if (!orb->dead && orb->xpValue > 0)
            (void)loaded_append_xp(m, slot);
    }
}

int gm_mobs_loaded_order_count(const GmMobLive *m) {
    return m ? m->loaded_order_count : 0;
}

int gm_mobs_loaded_order_get(
        const GmMobLive *m, int index, int *eid, int *kind) {
    if (!m || index < 0 || index >= m->loaded_order_count) return 0;
    const GmMobLoadedRef *ref = loaded_ref_at_const(m, index);
    if (eid) *eid = ref->eid;
    if (kind) *kind = ref->kind;
    return 1;
}

int gm_mobs_tick_update_order_get(
        const GmMobLive *m, int index, int *eid) {
    int *value;
    if (!m || index < 0 || index >= m->tick_update_order_count) return 0;
    value = tick_order_at((GmMobLive *)m, index);
    if (!value) return 0;
    if (eid) *eid = *value;
    return 1;
}

int gm_mobs_template_entity_capture(
        const GmMobLive *m, int eid, GmMobTemplateEntity *out) {
    const EwStore *store;
    int slot;
    if (!m || !out || eid < 0) return 0;
    memset(out, 0, sizeof *out);
    store = const_store(m);
    slot = mob_slot_by_eid(m, eid);
    if (slot > 0 && store->alive[slot]
            && m->entity_dimension[slot] == m->active_dimension
            && store->type[slot] == EW_TYPE_BOAT) {
        McAABB box;
        out->kind = GM_TEMPLATE_ENTITY_BOAT;
        out->type = EW_TYPE_BOAT;
        out->x = store->x[slot]; out->y = store->y[slot];
        out->z = store->z[slot];
        out->vx = store->vx[slot]; out->vy = store->vy[slot];
        out->vz = store->vz[slot];
        out->yaw = store->yaw[slot];
        out->pitch = m->entity_pitch[slot];
        out->fall_distance = m->entity_fall_distance[slot];
        out->on_ground = store->on_ground[slot];
        out->air = m->entity_air[slot];
        out->fire_ticks = m->fire_ticks[slot];
        out->portal_cooldown = m->entity_portal_cooldown[slot];
        out->boat_variant = m->boat_variant[slot];
        if (!gm_mobs_entity_aabb(m, eid, &box)) return 0;
        out->box_min_x = box.minX; out->box_min_y = box.minY;
        out->box_min_z = box.minZ; out->box_max_x = box.maxX;
        out->box_max_y = box.maxY; out->box_max_z = box.maxZ;
        return 1;
    }
    if (slot > 0 && store->alive[slot]
            && m->entity_dimension[slot] == m->active_dimension
            && gm_living(store->type[slot])
            && store->type[slot] != EW_TYPE_BOAT) {
        McAABB box;
        out->kind = GM_TEMPLATE_ENTITY_LIVING;
        out->type = store->type[slot];
        out->x = store->x[slot]; out->y = store->y[slot];
        out->z = store->z[slot];
        out->vx = store->vx[slot]; out->vy = store->vy[slot];
        out->vz = store->vz[slot];
        out->yaw = store->yaw[slot];
        out->pitch = m->entity_pitch[slot];
        out->health = store->health[slot];
        out->fall_distance = m->entity_fall_distance[slot];
        out->absorption = m->entity_absorption[slot];
        out->on_ground = store->on_ground[slot];
        out->air = m->entity_air[slot];
        out->fire_ticks = m->fire_ticks[slot];
        out->portal_cooldown = m->entity_portal_cooldown[slot];
        out->no_ai = m->controlled_no_ai[slot];
        out->persistence_required = m->persistence_required[slot];
        out->left_handed = m->entity_left_handed[slot];
        out->can_pick_up_loot = m->entity_can_pick_up_loot[slot];
        out->size = m->size[slot];
        out->growing_age = m->growing_age[slot];
        out->forced_age = m->sheep_forced_age[slot];
        out->forced_age_timer = m->sheep_forced_age_timer[slot];
        out->in_love = m->sheep_in_love[slot];
        out->sheep_data = m->sheep_data[slot];
        out->pig_saddled = m->pig_saddled[slot];
        out->chicken_time_until_next_egg =
            m->chicken_time_until_next_egg[slot];
        out->chicken_jockey = m->chicken_jockey[slot];
        out->villager_profession = m->villager_profession[slot];
        out->villager_willing = m->villager_willing[slot];
        out->creeper_fuse = m->creeper_fuse[slot];
        out->creeper_powered = m->creeper_powered[slot];
        out->anger = m->anger[slot];
        out->bat_hanging = m->bat_hanging[slot];
        out->snowman_pumpkin = m->snowman_pumpkin[slot];
        out->endermite_lifetime = m->endermite_lifetime[slot];
        out->endermite_player_spawned = m->endermite_player_spawned[slot];
        out->tameable_tamed = m->tameable_tamed[slot];
        out->tameable_sitting = m->tameable_sitting[slot];
        out->tameable_owner = m->tameable_owner[slot];
        out->tameable_variant = m->tameable_variant[slot];
        out->wolf_angry = m->wolf_angry[slot];
        out->golem_player_created = m->golem_player_created[slot];
        out->zombie_villager_conversion_time =
            m->zombie_villager_conversion_time[slot];
        out->vex_owner_eid = m->vex_owner_eid[slot];
        out->vex_bound_x = m->vex_bound_x[slot];
        out->vex_bound_y = m->vex_bound_y[slot];
        out->vex_bound_z = m->vex_bound_z[slot];
        out->vex_life_ticks = m->vex_life_ticks[slot];
        out->vex_limited_life = m->vex_limited_life[slot];
        out->effect_count = m->entity_effect_count[slot];
        memcpy(out->effects, m->entity_effects[slot], sizeof out->effects);
        memcpy(out->effect_flags, m->entity_effect_flags[slot],
               sizeof out->effect_flags);
        out->mainhand = m->entity_mainhand[slot];
        memcpy(out->villager_inventory, m->villager_inventory[slot],
               sizeof out->villager_inventory);
        if (gm_mobs_horse_type(out->type)) {
            if (!gm_mobs_get_horse_state(m, eid, &out->horse)) return 0;
            if (out->type == EW_TYPE_LLAMA) {
                out->llama_strength = m->llama_strength[slot];
                out->llama_decor = m->llama_decor[slot];
                out->llama_variant = m->llama_variant[slot];
                out->llama_did_spit = m->llama_did_spit[slot];
            }
        }
        if (!gm_mobs_entity_aabb(m, eid, &box)) return 0;
        out->box_min_x = box.minX; out->box_min_y = box.minY;
        out->box_min_z = box.minZ; out->box_max_x = box.maxX;
        out->box_max_y = box.maxY; out->box_max_z = box.maxZ;
        return 1;
    }
    for (slot = 0; slot < xp_slot_limit(m); ++slot) {
        const McOrb *orb = xp_orb_at_const(m, slot);
        if (orb->dead || orb->xpValue <= 0 || orb->eid != eid
                || *xp_dimension_at((GmMobLive *)m, slot)
                    != m->active_dimension)
            continue;
        out->kind = GM_TEMPLATE_ENTITY_XP;
        out->type = GM_ENTITY_XP_ORB;
        out->x = orb->posX; out->y = orb->posY; out->z = orb->posZ;
        out->vx = orb->motionX; out->vy = orb->motionY;
        out->vz = orb->motionZ;
        out->yaw = orb->yaw;
        out->box_min_x = orb->box.minX;
        out->box_min_y = orb->box.minY;
        out->box_min_z = orb->box.minZ;
        out->box_max_x = orb->box.maxX;
        out->box_max_y = orb->box.maxY;
        out->box_max_z = orb->box.maxZ;
        out->on_ground = orb->onGround;
        out->xp_value = orb->xpValue;
        out->xp_health = orb->health;
        out->xp_age = orb->xpOrbAge;
        /* EntityXPOrb NBT does not serialize these three live counters. */
        out->xp_pickup_delay = 0;
        out->xp_color = 0;
        out->xp_target_color = 0;
        return 1;
    }
    return 0;
}

static int template_stack_valid(ICStack stack) {
    if (stack.item < 0 || stack.item > 4095
            || stack.count < 0 || stack.count > 64
            || stack.meta < 0 || stack.meta > 32767
            || (stack.count == 0) != (stack.item == 0)
            || stack.repair_cost < 0 || stack.custom_name < 0
            || stack.tag_id < 0 || stack.n_enchants < 0
            || stack.n_enchants > IC_MAX_ENCHANTS)
        return 0;
    for (int index = 0; index < stack.n_enchants; ++index)
        if (stack.enchants[index].id < 0
                || stack.enchants[index].level < 0)
            return 0;
    return 1;
}

int gm_mobs_template_entity_valid(const GmMobTemplateEntity *entity) {
    if (!entity || !isfinite(entity->x) || !isfinite(entity->y)
            || !isfinite(entity->z) || !isfinite(entity->vx)
            || !isfinite(entity->vy) || !isfinite(entity->vz)
            || !isfinite(entity->box_min_x)
            || !isfinite(entity->box_min_y)
            || !isfinite(entity->box_min_z)
            || !isfinite(entity->box_max_x)
            || !isfinite(entity->box_max_y)
            || !isfinite(entity->box_max_z)
            || entity->box_min_x > entity->box_max_x
            || entity->box_min_y > entity->box_max_y
            || entity->box_min_z > entity->box_max_z
            || !isfinite(entity->yaw) || !isfinite(entity->pitch))
        return 0;
    if ((entity->kind != GM_TEMPLATE_ENTITY_MINECART
            || entity->minecart_kind != 4)
            && (entity->minecart_spawner_potential_count != 0
                || entity->minecart_spawner_potential_cap != 0
                || entity->minecart_spawner_potentials))
        return 0;
    if (entity->kind == GM_TEMPLATE_ENTITY_ITEM)
        return entity->type == 0
            && !isr_is_empty(&entity->item_stack)
            && entity->item_health > 0
            && entity->item_age >= -32768
            && entity->item_age <= 32767
            && entity->item_pickup_delay >= -32768
            && entity->item_pickup_delay <= 32767
            && entity->fire_ticks >= -1
            && entity->fire_ticks <= 32767
            && entity->air >= -32768 && entity->air <= 32767
            && (entity->on_ground == 0 || entity->on_ground == 1)
            && (entity->item_no_gravity == 0
                || entity->item_no_gravity == 1)
            && isfinite(entity->fall_distance);
    if (entity->kind == GM_TEMPLATE_ENTITY_PRIMED_TNT)
        return entity->type == 0 && entity->tnt_fuse >= -32768
            && entity->tnt_fuse <= 32767
            && (entity->tnt_no_gravity == 0
                || entity->tnt_no_gravity == 1)
            && (entity->on_ground == 0 || entity->on_ground == 1)
            && isfinite(entity->fall_distance);
    if (entity->kind == GM_TEMPLATE_ENTITY_FALLING_BLOCK)
        return entity->type == 0
            && (entity->falling_block == 12
                || entity->falling_block == 13
                || entity->falling_block == 122
                || entity->falling_block == 145)
            && (entity->falling_block == 145
                ? entity->falling_meta >= 0 && entity->falling_meta <= 11
                : entity->falling_meta == 0)
            && entity->falling_time >= 0
            && entity->falling_tile_tag_id >= 0
            && entity->falling_hurt_max >= 0
            && isfinite(entity->falling_hurt_amount)
            && entity->falling_hurt_amount >= 0.0F
            && (entity->falling_should_drop_item == 0
                || entity->falling_should_drop_item == 1)
            && (entity->falling_hurt_entities == 0
                || entity->falling_hurt_entities == 1)
            && (entity->falling_no_gravity == 0
                || entity->falling_no_gravity == 1)
            && (entity->on_ground == 0 || entity->on_ground == 1)
            && isfinite(entity->fall_distance);
    if (entity->kind == GM_TEMPLATE_ENTITY_END_CRYSTAL)
        return entity->type == 0
            && (entity->crystal_show_bottom == 0
                || entity->crystal_show_bottom == 1)
            && (entity->crystal_has_beam == 0
                || entity->crystal_has_beam == 1)
            && (entity->crystal_no_gravity == 0
                || entity->crystal_no_gravity == 1)
            && (entity->on_ground == 0 || entity->on_ground == 1)
            && isfinite(entity->fall_distance);
    if (entity->kind == GM_TEMPLATE_ENTITY_MINECART) {
        int slots = entity->minecart_kind == 1 ? 27
            : entity->minecart_kind == 5 ? 5 : 0;
        if (entity->type != 0
                || entity->minecart_kind < 0
                || entity->minecart_kind > 6
                || (entity->minecart_no_gravity != 0
                    && entity->minecart_no_gravity != 1)
                || (entity->minecart_custom_display != 0
                    && entity->minecart_custom_display != 1)
                || (entity->minecart_hopper_enabled != 0
                    && entity->minecart_hopper_enabled != 1)
                || (entity->on_ground != 0 && entity->on_ground != 1)
                || entity->air < -32768 || entity->air > 32767
                || entity->fire_ticks < -1 || entity->fire_ticks > 32767
                || entity->minecart_fuel < -32768
                || entity->minecart_fuel > 32767
                || !isfinite(entity->fall_distance)
                || !isfinite(entity->minecart_push_x)
                || !isfinite(entity->minecart_push_z))
            return 0;
        if (entity->minecart_kind == 4) {
            if (!gm_living(entity->minecart_spawner_entity_type)
                    || entity->minecart_spawner_delay < -1
                    || entity->minecart_spawner_min_delay < 0
                    || entity->minecart_spawner_max_delay < 0
                    || entity->minecart_spawner_spawn_count < 0
                    || entity->minecart_spawner_max_nearby < 0
                    || entity->minecart_spawner_spawn_range < 0
                    || entity->minecart_spawner_activate_range < 0
                    || entity->minecart_spawner_nbt_tag_id < 0
                    || (entity->minecart_spawner_default_entity_nbt != 0
                        && entity->minecart_spawner_default_entity_nbt != 1)
                    || entity->minecart_spawner_potential_count < 0
                    || entity->minecart_spawner_potential_count
                        > entity->minecart_spawner_potential_cap
                    || entity->minecart_spawner_potential_cap < 0
                    || entity->minecart_spawner_potential_cap > 1048576
                    || (entity->minecart_spawner_potential_cap > 0
                        && !entity->minecart_spawner_potentials)
                    || !isfinite(entity->minecart_spawner_mob_rotation)
                    || !isfinite(entity->minecart_spawner_prev_mob_rotation))
                return 0;
            for (int i = 0;
                    i < entity->minecart_spawner_potential_count; ++i)
                if (!gm_living(
                        entity->minecart_spawner_potentials[i].type)
                        || entity->minecart_spawner_potentials[i].weight <= 0
                        || entity->minecart_spawner_potentials[i].nbt_tag_id < 0
                        || (entity->minecart_spawner_potentials[i].default_entity_nbt
                            != 0
                            && entity->minecart_spawner_potentials[i].default_entity_nbt
                            != 1))
                    return 0;
        }
        if (entity->minecart_kind == 6
                && (entity->minecart_command_tag_id < 0
                    || entity->minecart_command_name_tag_id < 0
                    || entity->minecart_command_last_output_tag_id < 0
                    || (entity->minecart_command_track_output != 0
                        && entity->minecart_command_track_output != 1)))
            return 0;
        if (entity->minecart_custom_display) {
            if (entity->minecart_display_block < 0
                    || entity->minecart_display_block > 255
                    || entity->minecart_display_meta < 0
                    || entity->minecart_display_meta > 15)
                return 0;
        } else if (entity->minecart_display_block != 0
                || entity->minecart_display_meta != 0
                || entity->minecart_display_offset != 0)
            return 0;
        for (int slot = 0; slot < GM_TEMPLATE_MINECART_SLOTS; ++slot)
            if (!template_stack_valid(entity->minecart_slots[slot])
                    || (slot >= slots
                        && !isr_is_empty(&entity->minecart_slots[slot])))
                return 0;
        return 1;
    }
    if (entity->kind == GM_TEMPLATE_ENTITY_XP)
        return entity->type == GM_ENTITY_XP_ORB
            && entity->xp_value > 0 && entity->xp_health > 0
            && entity->xp_age >= 0 && entity->xp_age < 6000
            && entity->xp_pickup_delay == 0
            && entity->xp_color == 0 && entity->xp_target_color == 0;
    if (entity->kind == GM_TEMPLATE_ENTITY_BOAT)
        return entity->type == EW_TYPE_BOAT
            && entity->boat_variant >= 0 && entity->boat_variant <= 5
            && isfinite(entity->fall_distance)
            && (entity->on_ground == 0 || entity->on_ground == 1);
    if (entity->kind != GM_TEMPLATE_ENTITY_LIVING
            || !gm_living(entity->type) || entity->type == EW_TYPE_BOAT
            || !isfinite(entity->health) || entity->health < 0.0F
            || !isfinite(entity->fall_distance)
            || !isfinite(entity->absorption)
            || entity->effect_count < 0
            || entity->effect_count > GM_MOB_EFFECT_CAPACITY)
        return 0;
#define BOOLEAN_FIELD(field) \
    if (entity->field != 0 && entity->field != 1) return 0
    BOOLEAN_FIELD(on_ground);
    BOOLEAN_FIELD(no_ai);
    BOOLEAN_FIELD(persistence_required);
    BOOLEAN_FIELD(left_handed);
    BOOLEAN_FIELD(can_pick_up_loot);
    BOOLEAN_FIELD(pig_saddled);
    BOOLEAN_FIELD(chicken_jockey);
    BOOLEAN_FIELD(villager_willing);
    BOOLEAN_FIELD(creeper_powered);
    BOOLEAN_FIELD(bat_hanging);
    BOOLEAN_FIELD(snowman_pumpkin);
    BOOLEAN_FIELD(endermite_player_spawned);
    BOOLEAN_FIELD(tameable_tamed);
    BOOLEAN_FIELD(tameable_sitting);
    BOOLEAN_FIELD(tameable_owner);
    BOOLEAN_FIELD(wolf_angry);
    BOOLEAN_FIELD(golem_player_created);
    BOOLEAN_FIELD(vex_limited_life);
#undef BOOLEAN_FIELD
    for (int index = 0; index < entity->effect_count; ++index)
        if (entity->effects[index].id <= 0
                || entity->effects[index].duration < 0
                || entity->effects[index].amplifier < 0
                || (entity->effect_flags[index] & ~3u) != 0)
            return 0;
    return 1;
}

int gm_mobs_template_entity_spawn(
        GmMobLive *m, const GmMobTemplateEntity *entity, int new_eid) {
    EwStore *now, *next;
    int slot;
    if (!m || new_eid <= 0 || !gm_mobs_template_entity_valid(entity))
        return -1;
    if (entity->kind == GM_TEMPLATE_ENTITY_XP) {
        if (!gm_mobs_spawn_xp_exact(
                m, entity->x, entity->y, entity->z,
                entity->vx, entity->vy, entity->vz,
                entity->xp_value, new_eid, entity->xp_age,
                0, 0, 0))
            return -1;
        for (slot = 0; slot < xp_slot_limit(m); ++slot) {
            McOrb *orb = xp_orb_at(m, slot);
            if (orb->dead || orb->xpValue <= 0 || orb->eid != new_eid)
                continue;
            orb->health = entity->xp_health;
            orb->onGround = entity->on_ground != 0;
            orb->yaw = entity->yaw;
            /* EntityList creates EntityXPOrb(World), whose constructor uses
             * setSize(0.25F, 0.25F), before reading Template NBT. */
            orb->width = 0.25F;
            orb->height = 0.25F;
            eo_set_position(orb, entity->x, entity->y, entity->z);
            return new_eid;
        }
        return -1;
    }
    if (entity->kind == GM_TEMPLATE_ENTITY_BOAT) {
        slot = gm_mobs_spawn_boat_type_exact(
            m, new_eid, entity->x, entity->y, entity->z,
            entity->yaw, entity->boat_variant);
        if (slot <= 0) return -1;
        now = now_store(m);
        next = next_store(m);
        now->vx[slot] = entity->vx;
        now->vy[slot] = entity->vy;
        now->vz[slot] = entity->vz;
        now->on_ground[slot] = (unsigned char)(entity->on_ground != 0);
        m->entity_pitch[slot] = entity->pitch;
        m->entity_fall_distance[slot] = entity->fall_distance;
        m->entity_server_fall_distance[slot] = entity->fall_distance;
        m->entity_air[slot] = entity->air;
        m->fire_ticks[slot] = entity->fire_ticks;
        m->entity_portal_cooldown[slot] = entity->portal_cooldown;
        ew_store_copy_slot(next, now, slot);
        return new_eid;
    }
    if (entity->kind != GM_TEMPLATE_ENTITY_LIVING)
        return -1;
    if (entity->type == EW_TYPE_LLAMA) {
        slot = gm_mobs_spawn_llama_exact(
            m, new_eid, entity->x, entity->y, entity->z,
            entity->vx, entity->vy, entity->vz,
            entity->yaw, entity->health, entity->no_ai,
            entity->horse.max_health, entity->horse.movement_speed,
            entity->horse.jump_strength, entity->horse.growing_age,
            entity->horse.status, entity->horse.temper,
            entity->llama_variant, entity->llama_strength,
            entity->llama_decor, entity->horse.chested,
            entity->llama_did_spit, 0);
    } else if (gm_mobs_horse_type(entity->type)) {
        slot = gm_mobs_spawn_horse_exact(
            m, entity->type, new_eid,
            entity->x, entity->y, entity->z,
            entity->vx, entity->vy, entity->vz,
            entity->yaw, entity->health, entity->no_ai,
            entity->horse.max_health, entity->horse.movement_speed,
            entity->horse.jump_strength, entity->horse.growing_age,
            entity->horse.status, entity->horse.temper,
            entity->horse.variant, entity->horse.armor,
            entity->horse.chested, entity->horse.trap,
            entity->horse.trap_time);
    } else {
        slot = gm_mobs_spawn_exact_sized(
            m, entity->type, new_eid,
            entity->x, entity->y, entity->z,
            entity->vx, entity->vy, entity->vz,
            entity->yaw, entity->health,
            entity->size > 0 ? entity->size : 1,
            entity->no_ai, 0, 0, 0);
    }
    if (slot <= 0) return -1;
    now = now_store(m);
    next = next_store(m);
    now->on_ground[slot] = (unsigned char)(entity->on_ground != 0);
    m->entity_pitch[slot] = entity->pitch;
    m->entity_fall_distance[slot] = entity->fall_distance;
    m->entity_server_fall_distance[slot] = entity->fall_distance;
    m->entity_absorption[slot] = entity->absorption;
    m->entity_air[slot] = entity->air;
    m->fire_ticks[slot] = entity->fire_ticks;
    m->entity_portal_cooldown[slot] = entity->portal_cooldown;
    m->persistence_required[slot] =
        (unsigned char)(entity->persistence_required != 0);
    m->entity_left_handed[slot] =
        (unsigned char)(entity->left_handed != 0);
    m->entity_can_pick_up_loot[slot] =
        (unsigned char)(entity->can_pick_up_loot != 0);
    m->entity_mainhand[slot] = entity->mainhand;
    m->growing_age[slot] = entity->growing_age;
    m->sheep_forced_age[slot] = entity->forced_age;
    m->sheep_forced_age_timer[slot] = entity->forced_age_timer;
    m->sheep_in_love[slot] = entity->in_love;
    m->sheep_data[slot] = (unsigned char)entity->sheep_data;
    m->pig_saddled[slot] = (unsigned char)(entity->pig_saddled != 0);
    m->chicken_time_until_next_egg[slot] =
        entity->chicken_time_until_next_egg;
    m->chicken_jockey[slot] =
        (unsigned char)(entity->chicken_jockey != 0);
    m->villager_profession[slot] =
        (unsigned char)entity->villager_profession;
    m->villager_willing[slot] =
        (unsigned char)(entity->villager_willing != 0);
    memcpy(m->villager_inventory[slot], entity->villager_inventory,
           sizeof entity->villager_inventory);
    m->creeper_fuse[slot] = entity->creeper_fuse;
    m->creeper_powered[slot] =
        (unsigned char)(entity->creeper_powered != 0);
    m->anger[slot] = entity->anger;
    m->bat_hanging[slot] = (unsigned char)(entity->bat_hanging != 0);
    m->snowman_pumpkin[slot] =
        (unsigned char)(entity->snowman_pumpkin != 0);
    m->endermite_lifetime[slot] = entity->endermite_lifetime;
    m->endermite_player_spawned[slot] =
        (unsigned char)(entity->endermite_player_spawned != 0);
    m->tameable_tamed[slot] =
        (unsigned char)(entity->tameable_tamed != 0);
    m->tameable_sitting[slot] =
        (unsigned char)(entity->tameable_sitting != 0);
    m->tameable_sit_requested[slot] = m->tameable_sitting[slot];
    m->tameable_owner[slot] =
        (unsigned char)(entity->tameable_owner != 0);
    m->tameable_variant[slot] = (unsigned char)entity->tameable_variant;
    m->wolf_angry[slot] = (unsigned char)(entity->wolf_angry != 0);
    m->golem_player_created[slot] =
        (unsigned char)(entity->golem_player_created != 0);
    m->zombie_villager_conversion_time[slot] =
        entity->zombie_villager_conversion_time;
    m->vex_owner_eid[slot] = -1; /* remapped links are a later pass */
    m->vex_bound_x[slot] = entity->vex_bound_x;
    m->vex_bound_y[slot] = entity->vex_bound_y;
    m->vex_bound_z[slot] = entity->vex_bound_z;
    m->vex_life_ticks[slot] = entity->vex_life_ticks;
    m->vex_limited_life[slot] =
        (unsigned char)(entity->vex_limited_life != 0);
    m->entity_effect_count[slot] = (unsigned char)entity->effect_count;
    memcpy(m->entity_effects[slot], entity->effects,
           sizeof entity->effects);
    memcpy(m->entity_effect_flags[slot], entity->effect_flags,
           sizeof entity->effect_flags);
    if (gm_mobs_horse_type(entity->type)) {
        memcpy(m->horse_inventory[slot], entity->horse.inventory,
               sizeof entity->horse.inventory);
        m->horse_owner_present[slot] =
            (unsigned char)(entity->horse.owner_present != 0);
        m->horse_owner_uuid_most[slot] = entity->horse.owner_uuid_most;
        m->horse_owner_uuid_least[slot] = entity->horse.owner_uuid_least;
    }
    (void)gm_mobs_set_no_ai(m, new_eid, entity->no_ai != 0);
    ew_store_copy_slot(next, now, slot);
    return new_eid;
}

