static i64 mob_entity_constructor_seed(
        const GmMobLive *m, const EwStore *s, int slot) {
    u64 key = (u64)m->seed
        ^ (u64)(u32)s->id[slot] * UINT64_C(0x9E3779B97F4A7C15)
        ^ (u64)s->type[slot] * UINT64_C(0xD1B54A32D192ED03);
    return (i64)mc_hash64(key);
}

static void horse_init_attributes(
        GmMobLive *m, EwStore *s, int slot) {
    int type;
    JavaRandom *random;
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !gm_mobs_horse_type(s->type[slot]))
        return;
    type = s->type[slot];
    random = &m->entity_random[slot].random;
    if (type == EW_TYPE_SKELETON_HORSE
            || type == EW_TYPE_ZOMBIE_HORSE) {
        m->horse_max_health[slot] = 15.0;
        m->horse_movement_speed[slot] = 0.20000000298023224;
        m->horse_jump_strength[slot] = 0.4000000059604645
            + jrand_double(random) * 0.2
            + jrand_double(random) * 0.2
            + jrand_double(random) * 0.2;
    } else {
        m->horse_max_health[slot] = 15.0
            + jrand_int_bound(random, 8)
            + jrand_int_bound(random, 9);
        if (type == EW_TYPE_HORSE) {
            m->horse_movement_speed[slot] =
                (0.44999998807907104
                    + jrand_double(random) * 0.3
                    + jrand_double(random) * 0.3
                    + jrand_double(random) * 0.3) * 0.25;
            m->horse_jump_strength[slot] = 0.4000000059604645
                + jrand_double(random) * 0.2
                + jrand_double(random) * 0.2
                + jrand_double(random) * 0.2;
        } else {
            m->horse_movement_speed[slot] = 0.17499999701976776;
            m->horse_jump_strength[slot] = 0.5;
        }
    }
    s->health[slot] = (float)m->horse_max_health[slot];
}

