int gm_mobs_set_villager_front_door(
        GmMobLive *m, int eid, int valid,
        int village_index, int door_index,
        int x, int y, int z, int inside_dx, int inside_dz, int detached) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_VILLAGER
            || (valid != 0 && valid != 1)
            || (detached != 0 && detached != 1)
            || (valid && (village_index < 0 || door_index < 0
                || ((inside_dx == 0) == (inside_dz == 0))
                || (inside_dx != -2 && inside_dx != 0 && inside_dx != 2)
                || (inside_dz != -2 && inside_dz != 0 && inside_dz != 2)))
            || (!valid && (village_index != -1 || door_index != -1
                || x != 0 || y != 0 || z != 0
                || inside_dx != 0 || inside_dz != 0 || detached)))
        return 0;
    m->villager_front_door_valid[slot] = (unsigned char)valid;
    m->villager_front_door_village[slot] = village_index;
    m->villager_front_door_index[slot] = door_index;
    m->villager_front_door_x[slot] = x;
    m->villager_front_door_y[slot] = y;
    m->villager_front_door_z[slot] = z;
    m->villager_front_door_inside_dx[slot] = inside_dx;
    m->villager_front_door_inside_dz[slot] = inside_dz;
    m->villager_front_door_detached[slot] = (unsigned char)detached;
    if (!valid) {
        m->villager_restrict_door_active[slot] = 0;
        m->villager_break_doors[slot] = 1;
        m->villager_enter_doors[slot] = 1;
    }
    return 1;
}

int gm_mobs_set_villager_inventory_slot(
        GmMobLive *m, int eid, int inventory_slot, ICStack stack) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_VILLAGER
            || inventory_slot < 0 || inventory_slot >= 8
            || stack.item < 0 || stack.item > 4095
            || stack.count < 0 || stack.count > 64
            || stack.meta < 0 || stack.meta > 32767
            || stack.n_enchants < 0 || stack.n_enchants > IC_MAX_ENCHANTS
            || ((stack.item == 0) != (stack.count == 0)))
        return 0;
    m->villager_inventory[slot][inventory_slot] = stack;
    return 1;
}

int gm_mobs_get_villager_mating_state(
        const GmMobLive *m, int eid, int *willing, int *mating,
        int *mate_eid, int *timeout) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_VILLAGER)
        return 0;
    if (willing) *willing = m->villager_willing[slot] != 0;
    if (mating) *mating = m->villager_mating[slot] != 0;
    if (mate_eid) *mate_eid = m->villager_mate_eid[slot];
    if (timeout) *timeout = m->villager_mating_timeout[slot];
    return 1;
}

int gm_mobs_take_villager_collection_position(
        GmMobLive *m, int *x, int *y, int *z) {
    if (!m) return 0;
    for (int order = 0; order < m->loaded_order_count; ++order) {
        GmMobLoadedRef ref = *loaded_ref_at(m, order);
        int slot = living_loaded_ref_stage(
            m, &ref, now_store(m));
        if (slot <= 0
                || !m->villager_collection_pending[slot])
            continue;
        m->villager_collection_pending[slot] = 0;
        if (x) *x = m->villager_collection_x[slot];
        if (y) *y = m->villager_collection_y[slot];
        if (z) *z = m->villager_collection_z[slot];
        gm_mobs_living_cold_flush(m);
        return 1;
    }
    gm_mobs_living_cold_flush(m);
    return 0;
}

int gm_mobs_take_villager_birth(
        GmMobLive *m, GmVillagerBirth *birth) {
    if (!m || !birth || m->villager_birth_count <= 0) return 0;
    *birth = m->villager_births[0];
    memmove(&m->villager_births[0], &m->villager_births[1],
            (size_t)(m->villager_birth_count - 1)
                * sizeof m->villager_births[0]);
    --m->villager_birth_count;
    return 1;
}

int gm_mobs_take_villager_harm(
        GmMobLive *m, GmVillagerHarmEvent *event) {
    if (!m || !event || m->villager_harm_count <= 0) return 0;
    *event = m->villager_harm_events[0];
    memmove(&m->villager_harm_events[0], &m->villager_harm_events[1],
            (size_t)(m->villager_harm_count - 1)
                * sizeof m->villager_harm_events[0]);
    --m->villager_harm_count;
    return 1;
}

