static int iron_golem_attack_slot(
        GmMobLive *m, EwStore *s, int golem, int target,
        float *rolled_damage, GmLiveSim *drops,
        const GmMobDeathContext *death_context) {
    if (golem <= 0 || target <= 0 || golem == target || !s
            || s->type[golem] != EW_TYPE_IRON_GOLEM
            || !s->alive[target] || !gm_living(s->type[target])
            || s->type[target] == EW_TYPE_BOAT
            || m->entity_dead[target] || s->health[target] <= 0.0F)
        return 0;
    float damage = (float)(7
        + jrand_int_bound(&m->entity_random[golem].random, 15));
    if (rolled_damage) *rolled_damage = damage;
    m->golem_attack_timer[golem] = 10;
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[golem], 4,
        s->x[golem], s->y[golem], s->z[golem], 0.0F, 0.0F);

    int accepted;
    if (death_context && !m->controlled_no_ai[target]) {
        GmMobDamageEntitySource source = {
            s->x[golem], s->z[golem], death_context,
            s->id[golem], 0, 0, 0, 1,
        };
        int result = s->type[target] == EW_TYPE_WITCH
            ? mob_source_damage_witch_slot_exact(
                m, s, target, damage, drops,
                death_context->math_random_seed48,
                death_context->next_entity_id,
                death_context->do_mob_loot, 0, &source)
            : gm_passive(s->type[target])
            ? mob_source_damage_passive_slot_exact(
                m, s, target, damage, drops,
                death_context->math_random_seed48,
                death_context->next_entity_id,
                death_context->do_mob_loot, 0, 1, 0, &source)
            : mob_source_damage_ordinary_slot_exact(
                m, s, target, damage, drops,
                death_context->math_random_seed48,
                death_context->next_entity_id,
                death_context->do_mob_loot, 0, 1, 0, &source);
        accepted = result > 0;
    } else {
        int fresh = m->entity_hurt_resistant[target] <= 10;
        accepted = fresh || damage > m->entity_last_damage[target];
        if (accepted) {
            float applied = fresh
                ? damage : damage - m->entity_last_damage[target];
            applied = player_attack_after_mob_armor(
                m, target, s->type[target], applied);
            applied = mob_resistance_damage(m, target, applied);
            applied = mob_absorb_damage(m, target, applied);
            m->entity_last_damage[target] = damage;
            if (fresh) {
                m->entity_hurt_resistant[target] = 20;
                m->entity_hurt_time[target] = 10;
                mob_event_append(
                    m, GM_MOB_EVENT_ENTITY_STATUS, s->id[target], 2,
                    s->x[target], s->y[target], s->z[target], 0.0F, 0.0F);
            }
            s->health[target] -= applied;
            if (s->health[target] < 0.0F) s->health[target] = 0.0F;
            if (s->health[target] <= 0.0F) m->entity_dead[target] = 1;
            mark_hurt(m, s, target);
        }
    }
    if (accepted)
        s->vy[target] += 0.4000000059604645D;
    mob_event_append(
        m, GM_MOB_EVENT_SOUND, s->id[golem],
        GM_MOB_SOUND_IRON_GOLEM_ATTACK,
        s->x[golem], s->y[golem], s->z[golem], 1.0F, 1.0F);
    return accepted;
}

static int iron_golem_attack_player_slot(
        GmMobLive *m, EwStore *s, int golem,
        PsvPlayer *player, PvStats *vitals) {
    if (!m || !s || !player || !vitals || golem <= 0
            || s->type[golem] != EW_TYPE_IRON_GOLEM
            || vitals->health <= 0.0F)
        return 0;
    float damage = (float)(7
        + jrand_int_bound(&m->entity_random[golem].random, 15));
    m->golem_attack_timer[golem] = 10;
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[golem], 4,
        s->x[golem], s->y[golem], s->z[golem], 0.0F, 0.0F);
    int accepted = gm_mobs_attack_player(
        m, (struct PvStats *)vitals, &player->inv, damage, 0);
    if (accepted) player->ent.motionY += 0.4000000059604645D;
    player->health = vitals->health;
    mob_event_append(
        m, GM_MOB_EVENT_SOUND, s->id[golem],
        GM_MOB_SOUND_IRON_GOLEM_ATTACK,
        s->x[golem], s->y[golem], s->z[golem], 1.0F, 1.0F);
    return accepted;
}

int gm_mobs_iron_golem_attack(GmMobLive *m, int golem_eid,
        int target_eid, float *rolled_damage) {
    int golem = mob_slot_by_eid(m, golem_eid);
    int target = mob_slot_by_eid(m, target_eid);
    EwStore *s = m ? now_store(m) : NULL;
    int accepted = iron_golem_attack_slot(
        m, s, golem, target, rolled_damage, NULL, NULL);
    if (s && golem > 0 && target > 0)
        ew_store_copy(next_store(m), s);
    return accepted;
}

int gm_mobs_iron_golem_status(GmMobLive *m, int eid, int status) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_IRON_GOLEM)
        return 0;
    if (status == 4) m->golem_attack_timer[slot] = 10;
    else if (status == 11) m->golem_hold_rose_tick[slot] = 400;
    else if (status == 34) m->golem_hold_rose_tick[slot] = 0;
    else return 0;
    return 1;
}

int gm_mobs_iron_golem_state_tick(GmMobLive *m, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_IRON_GOLEM)
        return 0;
    if (m->golem_attack_timer[slot] > 0) --m->golem_attack_timer[slot];
    if (m->golem_hold_rose_tick[slot] > 0) --m->golem_hold_rose_tick[slot];
    if (--m->golem_home_check_timer[slot] <= 0)
        m->golem_home_check_timer[slot] = 70
            + jrand_int_bound(&m->entity_random[slot].random, 50);
    return 1;
}

int gm_mobs_spawn_zombie_villager(GmMobLive *m,
                                  double x, double y, double z,
                                  int profession) {
    if (!m || profession < 0 || profession > 5) return -1;
    int slot = gm_mobs_spawn(
        m, EW_TYPE_ZOMBIE_VILLAGER, x, y, z);
    if (slot < 0) return -1;
    m->villager_profession[slot] = (unsigned char)profession;
    return slot;
}

int gm_mobs_spawn_witch(GmMobLive *m, double x, double y, double z) {
    int slot = gm_mobs_spawn(m, EW_TYPE_WITCH, x, y, z);
    if (slot < 0) return -1;
    /* EntityLiving.onInitialSpawn: random follow-range Gaussian, then the
     * five-percent left-hand roll. The attribute value is not yet consumed by
     * the bounded navigator, but the private cursor and handedness state are. */
    (void)jrand_gaussian_next(&m->entity_random[slot]);
    m->witch_left_handed[slot] =
        (unsigned char)(jrand_float(&m->entity_random[slot].random) < 0.05F);
    m->fire_ticks[slot] = -1;
    return slot;
}

int gm_mobs_spawn_exact(GmMobLive *m, int type, int eid,
                        double x, double y, double z,
                        double vx, double vy, double vz,
                        float yaw, float health, int no_ai,
                        int hurt_time, int death_time,
                        int hurt_resistant_time) {
    return gm_mobs_spawn_exact_sized(
        m, type, eid, x, y, z, vx, vy, vz, yaw, health, 1, no_ai,
        hurt_time, death_time, hurt_resistant_time);
}

int gm_mobs_spawn_exact_sized(GmMobLive *m, int type, int eid,
                        double x, double y, double z,
                        double vx, double vy, double vz,
                        float yaw, float health, int size, int no_ai,
                        int hurt_time, int death_time,
                        int hurt_resistant_time) {
    if (!m || !gm_living(type) || type == EW_TYPE_BOAT
            || eid < 0 || health < 0.0f
            || (gm_is_slimey(type)
                ? (size != 1 && size != 2 && size != 4) : size != 1)
            || health > max_health(type, size)
            || (no_ai != 0 && no_ai != 1)
            || hurt_time < 0 || hurt_time > 10
            || death_time < 0 || death_time >= 20
            || hurt_resistant_time < 0 || hurt_resistant_time > 20)
        return -1;
    EwStore *s = now_store(m);
    int is_cold = 0;
    int slot = living_spawn_slot(
        m, s, type, eid, x, y, z, health, &is_cold);
    if (slot < 0) return -1;
    s->vx[slot] = vx;
    s->vy[slot] = vy;
    s->vz[slot] = vz;
    s->yaw[slot] = yaw;
    m->entity_dimension[slot] = (signed char)m->active_dimension;
    m->size[slot] = (unsigned char)size;
    reset_slot_state_s(m, s, slot);
    s->health[slot] = health;
    /* Both oracle variants are externally locked stationary fixtures. The
     * no_ai=false variant keeps Java's ordinary move/block-collision path but
     * has no tasks or gravity; magma advances its timers in this same bounded
     * controlled list. */
    m->controlled_no_ai[slot] = 1;
    m->controlled_block_collisions[slot] = (unsigned char)!no_ai;
    m->entity_hurt_time[slot] = hurt_time;
    m->entity_death_time[slot] = death_time;
    m->entity_hurt_resistant[slot] = hurt_resistant_time;
    if (m->next_id <= eid) m->next_id = eid + 1;
    return living_spawn_finish(m, s, slot, is_cold, 1);
}

int gm_mobs_spawn_horse_exact(
        GmMobLive *m, int type, int eid,
        double x, double y, double z, double vx, double vy, double vz,
        float yaw, float health, int no_ai,
        double max_health_value, double movement_speed,
        double jump_strength, int growing_age, int status, int temper,
        int variant, int armor, int chested, int trap, int trap_time) {
    int slot;
    float constructor_health;
    if (!m || !gm_mobs_horse_type(type) || type == EW_TYPE_LLAMA
            || !isfinite(max_health_value) || max_health_value <= 0.0
            || max_health_value > 1024.0
            || !isfinite(movement_speed) || movement_speed < 0.0
            || movement_speed > 16.0
            || !isfinite(jump_strength) || jump_strength < 0.0
            || jump_strength > 2.0 || !isfinite(health)
            || health < 0.0F || (double)health > max_health_value
            || status < 0 || status > 127 || temper < 0 || temper > 100
            || variant < 0 || armor < 0 || armor > 3
            || (chested != 0 && chested != 1)
            || (trap != 0 && trap != 1) || trap_time < 0
            || (chested && type != EW_TYPE_DONKEY && type != EW_TYPE_MULE)
            || (armor && type != EW_TYPE_HORSE)
            || (trap && type != EW_TYPE_SKELETON_HORSE))
        return -1;
    /* The common fixture helper validates against the constructor default.
     * A saved horse may legally have a modified MAX_HEALTH base and current
     * health above that default, so restore through a bounded temporary value
     * and install the NBT-backed attribute/current-health pair atomically. */
    constructor_health = health;
    if (constructor_health > max_health(type, 1))
        constructor_health = max_health(type, 1);
    slot = gm_mobs_spawn_exact(
        m, type, eid, x, y, z, vx, vy, vz, yaw, constructor_health, no_ai,
        0, 0, 0);
    if (slot < 0) return -1;
    m->horse_max_health[slot] = max_health_value;
    m->horse_movement_speed[slot] = movement_speed;
    m->horse_jump_strength[slot] = jump_strength;
    m->growing_age[slot] = growing_age;
    m->horse_status[slot] = (unsigned char)status;
    m->horse_temper[slot] = temper;
    m->horse_variant[slot] = variant;
    m->horse_armor[slot] = (unsigned char)armor;
    m->horse_chested[slot] = (unsigned char)chested;
    m->horse_trap[slot] = (unsigned char)trap;
    m->horse_trap_time[slot] = trap_time;
    now_store(m)->health[slot] = health;
    next_store(m)->health[slot] = health;
    return slot;
}

int gm_mobs_spawn_llama_exact(
        GmMobLive *m, int eid,
        double x, double y, double z, double vx, double vy, double vz,
        float yaw, float health, int no_ai,
        double max_health_value, double movement_speed,
        double jump_strength, int growing_age, int status, int temper,
        int variant, int strength, int decor, int chested,
        int did_spit, int leashed) {
    float constructor_health;
    int slot;
    if (!m || !isfinite(max_health_value) || max_health_value <= 0.0
            || max_health_value > 1024.0
            || !isfinite(movement_speed) || movement_speed < 0.0
            || movement_speed > 16.0
            || !isfinite(jump_strength) || jump_strength < 0.0
            || jump_strength > 2.0 || !isfinite(health)
            || health < 0.0F || (double)health > max_health_value
            || status < 0 || status > 127 || temper < 0 || temper > 30
            || variant < 0 || variant > 3 || strength < 1 || strength > 5
            || decor < -1 || decor > 15
            || (chested != 0 && chested != 1)
            || (did_spit != 0 && did_spit != 1)
            || (leashed != 0 && leashed != 1))
        return -1;
    /* Llamas inherit AbstractChestHorse's randomized maximum health but use
     * their own width, inventory columns, decor slot, and no-saddle rules. */
    constructor_health = health;
    if (constructor_health > max_health(EW_TYPE_LLAMA, 1))
        constructor_health = max_health(EW_TYPE_LLAMA, 1);
    slot = gm_mobs_spawn_exact(
        m, EW_TYPE_LLAMA, eid, x, y, z, vx, vy, vz, yaw,
        constructor_health, no_ai, 0, 0, 0);
    if (slot < 0) return -1;
    m->horse_max_health[slot] = max_health_value;
    m->horse_movement_speed[slot] = movement_speed;
    m->horse_jump_strength[slot] = jump_strength;
    m->growing_age[slot] = growing_age;
    m->horse_status[slot] = (unsigned char)(status & ~GM_HORSE_SADDLED);
    m->horse_temper[slot] = temper;
    m->horse_chested[slot] = (unsigned char)chested;
    m->llama_variant[slot] = (unsigned char)variant;
    m->llama_strength[slot] = (unsigned char)strength;
    m->llama_decor[slot] = (signed char)decor;
    m->llama_did_spit[slot] = (unsigned char)did_spit;
    m->llama_leashed[slot] = (unsigned char)leashed;
    now_store(m)->health[slot] = health;
    next_store(m)->health[slot] = health;
    return slot;
}

int gm_mobs_get_horse_state(
        const GmMobLive *m, int eid, GmHorseState *out) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || !out || !gm_mobs_horse_type(s->type[slot]))
        return 0;
    memset(out, 0, sizeof *out);
    out->type = s->type[slot];
    out->eid = eid;
    out->growing_age = m->growing_age[slot];
    out->status = m->horse_status[slot];
    out->variant = m->horse_variant[slot];
    out->armor = m->horse_armor[slot];
    out->temper = m->horse_temper[slot];
    out->owner_present = m->horse_owner_present[slot];
    out->owner_uuid_most = m->horse_owner_uuid_most[slot];
    out->owner_uuid_least = m->horse_owner_uuid_least[slot];
    out->chested = m->horse_chested[slot];
    out->trap = m->horse_trap[slot];
    out->trap_time = m->horse_trap_time[slot];
    out->ridden = m->horse_ride_eid == eid;
    out->horse_jumping = m->horse_jumping[slot];
    out->eating_counter = m->horse_eating_counter[slot];
    out->open_mouth_counter = m->horse_open_mouth_counter[slot];
    out->jump_rearing_counter = m->horse_jump_rearing_counter[slot];
    out->tail_counter = m->horse_tail_counter[slot];
    out->sprint_counter = m->horse_sprint_counter[slot];
    out->gallop_time = m->horse_gallop_time[slot];
    out->health = s->health[slot];
    out->jump_power = m->horse_jump_power[slot];
    out->max_health = m->horse_max_health[slot];
    out->movement_speed = m->horse_movement_speed[slot];
    out->jump_strength = m->horse_jump_strength[slot];
    out->head_lean = m->horse_head_lean[slot];
    out->prev_head_lean = m->horse_prev_head_lean[slot];
    out->rearing_amount = m->horse_rearing_amount[slot];
    out->prev_rearing_amount = m->horse_prev_rearing_amount[slot];
    out->mouth_openness = m->horse_mouth_openness[slot];
    out->prev_mouth_openness = m->horse_prev_mouth_openness[slot];
    memcpy(out->inventory, m->horse_inventory[slot],
           sizeof out->inventory);
    return 1;
}

int gm_mobs_get_llama_state(
        const GmMobLive *m, int eid, GmLlamaState *out) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || !out || s->type[slot] != EW_TYPE_LLAMA)
        return 0;
    memset(out, 0, sizeof *out);
    if (!gm_mobs_get_horse_state(m, eid, &out->horse)) return 0;
    out->strength = m->llama_strength[slot];
    out->decor = m->llama_decor[slot];
    out->variant = m->llama_variant[slot];
    out->did_spit = m->llama_did_spit[slot];
    out->leashed = m->llama_leashed[slot];
    out->leash_holder_kind = m->llama_leash_holder_kind[slot];
    out->leash_holder_eid = m->llama_leash_holder_eid[slot];
    out->caravan_head_eid = m->llama_caravan_head_eid[slot];
    out->caravan_tail_eid = m->llama_caravan_tail_eid[slot];
    out->caravan_speed = m->llama_caravan_speed[slot];
    out->caravan_dist_counter = m->llama_caravan_dist_counter[slot];
    return 1;
}

int gm_mobs_vanilla_leashable_type(int type) {
    return type == EW_TYPE_PIG || type == EW_TYPE_SHEEP
        || type == EW_TYPE_COW || type == EW_TYPE_CHICKEN
        || type == EW_TYPE_SQUID || type == EW_TYPE_WOLF
        || type == EW_TYPE_MOOSHROOM || type == EW_TYPE_SNOWMAN
        || type == EW_TYPE_OCELOT || type == EW_TYPE_IRON_GOLEM
        || type == EW_TYPE_HORSE || type == EW_TYPE_DONKEY
        || type == EW_TYPE_MULE || type == EW_TYPE_RABBIT
        || type == EW_TYPE_POLAR_BEAR || type == EW_TYPE_LLAMA;
}

int gm_mobs_living_can_be_leashed(const GmMobLive *m, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    return slot > 0 && s && s->alive[slot]
        && gm_mobs_vanilla_leashable_type(s->type[slot])
        && !m->llama_leashed[slot]
        && !(s->type[slot] == EW_TYPE_WOLF && m->wolf_angry[slot]);
}

