int gm_mobs_llama_set_leashed(
        GmMobLive *m, int eid, int leashed) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_LLAMA
            || (leashed != 0 && leashed != 1))
        return 0;
    m->llama_leashed[slot] = (unsigned char)leashed;
    if (!leashed) {
        m->llama_leash_holder_kind[slot] = 0;
        m->llama_leash_holder_eid[slot] = -1;
        m->llama_leash_holder_x[slot] = 0.0;
        m->llama_leash_holder_y[slot] = 0.0;
        m->llama_leash_holder_z[slot] = 0.0;
        m->llama_leash_pending[slot] = 0;
        m->llama_leash_pending_x[slot] = 0;
        m->llama_leash_pending_y[slot] = 0;
        m->llama_leash_pending_z[slot] = 0;
    }
    return 1;
}

int gm_mobs_restore_llama_links(
        GmMobLive *m, int eid, int leash_holder_kind,
        int leash_holder_eid, int caravan_head_eid,
        int caravan_tail_eid, double caravan_speed,
        int caravan_dist_counter) {
    int slot = mob_slot_by_eid(m, eid);
    int holder_valid = 1, head_valid = 1, tail_valid = 1;
    const EwStore *s = m ? const_store(m) : NULL;
    if (leash_holder_kind == 2) {
        int holder = mob_slot_by_eid(m, leash_holder_eid);
        s = m ? const_store(m) : NULL;
        holder_valid = holder > 0 && gm_living(s->type[holder]);
    }
    if (caravan_head_eid >= 0) {
        int head = mob_slot_by_eid(m, caravan_head_eid);
        s = m ? const_store(m) : NULL;
        head_valid = head > 0 && caravan_head_eid != eid
            && s->type[head] == EW_TYPE_LLAMA;
    }
    if (caravan_tail_eid >= 0) {
        int tail = mob_slot_by_eid(m, caravan_tail_eid);
        s = m ? const_store(m) : NULL;
        tail_valid = tail > 0 && caravan_tail_eid != eid
            && s->type[tail] == EW_TYPE_LLAMA;
    }
    slot = mob_slot_by_eid(m, eid);
    s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_LLAMA
            || leash_holder_kind < 0 || leash_holder_kind > 2
            || (leash_holder_kind == 0 && leash_holder_eid != -1)
            || (leash_holder_kind == 1 && leash_holder_eid < 0)
            || (leash_holder_kind == 2 && leash_holder_eid <= 0)
            || !holder_valid || !head_valid || !tail_valid
            || !isfinite(caravan_speed) || caravan_speed <= 0.0
            || caravan_speed > 16.0
            || caravan_dist_counter < 0 || caravan_dist_counter > 40)
        return 0;
    m->llama_leashed[slot] = (unsigned char)(leash_holder_kind != 0);
    m->llama_leash_holder_kind[slot] =
        (unsigned char)leash_holder_kind;
    m->llama_leash_holder_eid[slot] = leash_holder_eid;
    m->llama_leash_holder_x[slot] = 0.0;
    m->llama_leash_holder_y[slot] = 0.0;
    m->llama_leash_holder_z[slot] = 0.0;
    m->llama_leash_pending[slot] = 0;
    m->llama_leash_pending_x[slot] = 0;
    m->llama_leash_pending_y[slot] = 0;
    m->llama_leash_pending_z[slot] = 0;
    m->llama_caravan_head_eid[slot] = caravan_head_eid;
    m->llama_caravan_tail_eid[slot] = caravan_tail_eid;
    m->llama_caravan_speed[slot] = caravan_speed;
    m->llama_caravan_dist_counter[slot] = caravan_dist_counter;
    return 1;
}

int gm_mobs_llama_set_leash_knot(
        GmMobLive *m, int eid, int knot_eid,
        double x, double y, double z) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_LLAMA
            || knot_eid < 0 || !isfinite(x) || !isfinite(y)
            || !isfinite(z))
        return 0;
    m->llama_leashed[slot] = 1;
    m->llama_leash_holder_kind[slot] = 3;
    m->llama_leash_holder_eid[slot] = knot_eid;
    m->llama_leash_holder_x[slot] = x;
    m->llama_leash_holder_y[slot] = y;
    m->llama_leash_holder_z[slot] = z;
    m->llama_leash_pending[slot] = 0;
    m->llama_leash_pending_x[slot] = 0;
    m->llama_leash_pending_y[slot] = 0;
    m->llama_leash_pending_z[slot] = 0;
    return 1;
}

int gm_mobs_llama_set_leash_pending(
        GmMobLive *m, int eid, int x, int y, int z) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_LLAMA
            || y < 0 || y > 255)
        return 0;
    m->llama_leashed[slot] = 1;
    m->llama_leash_holder_kind[slot] = 0;
    m->llama_leash_holder_eid[slot] = -1;
    m->llama_leash_holder_x[slot] = 0.0;
    m->llama_leash_holder_y[slot] = 0.0;
    m->llama_leash_holder_z[slot] = 0.0;
    m->llama_leash_pending[slot] = 1;
    m->llama_leash_pending_x[slot] = x;
    m->llama_leash_pending_y[slot] = y;
    m->llama_leash_pending_z[slot] = z;
    return 1;
}

int gm_mobs_llama_invalidate_leash_knot(
        GmMobLive *m, int knot_eid, int creative) {
    const EwStore *s;
    int changed = 0;
    if (!m || knot_eid < 0 || (creative != 0 && creative != 1))
        return 0;
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(m, &cursor)) > 0) {
        s = const_store(m);
        if (!s->alive[slot] || s->type[slot] != EW_TYPE_LLAMA
                || !m->llama_leashed[slot]
                || m->llama_leash_holder_kind[slot] != 3
                || m->llama_leash_holder_eid[slot] != knot_eid)
            continue;
        ++changed;
        if (creative) {
            m->llama_leashed[slot] = 0;
            m->llama_leash_holder_kind[slot] = 0;
        }
        m->llama_leash_holder_eid[slot] = -1;
        m->llama_leash_holder_x[slot] = 0.0;
        m->llama_leash_holder_y[slot] = 0.0;
        m->llama_leash_holder_z[slot] = 0.0;
        m->llama_leash_pending[slot] = 0;
        m->llama_leash_pending_x[slot] = 0;
        m->llama_leash_pending_y[slot] = 0;
        m->llama_leash_pending_z[slot] = 0;
    }
    gm_mobs_living_cold_flush(m);
    return changed;
}

static int living_drop_lead_exact(
        GmMobLive *m, const EwStore *s, int slot,
        uint64_t *math_random_seed48, int *next_entity_id,
        GmLiveSim *drops) {
    JavaRandom generator, entity_random;
    int64_t uuid_most, uuid_least;
    uint64_t entity_cursor, uuid_cursor, math_cursor;
    int eid;
    float hover, yaw;
    double motion_x, motion_z;
    if (!m || !s || slot <= 0 || !math_random_seed48
            || !next_entity_id || !drops
            || !m->active_entity_seed_generator_seed48
            || !m->active_server_uuid_random_seed48
            || *next_entity_id <= 0 || *next_entity_id == INT_MAX)
        return 0;
    entity_cursor = *m->active_entity_seed_generator_seed48;
    uuid_cursor = *m->active_server_uuid_random_seed48;
    math_cursor = *math_random_seed48;
    eid = *next_entity_id;
    jrand_set_seed48(&generator, entity_cursor);
    jrand_set(&entity_random, jrand_long(&generator));
    entity_cursor = generator.seed;
    skeleton_trap_next_uuid(&uuid_cursor, &uuid_most, &uuid_least);
    hover = (float)(mob_math_random_next_double(&math_cursor)
        * (MC_PI * 2.0));
    yaw = (float)(mob_math_random_next_double(&math_cursor) * 360.0);
    motion_x = (double)(float)(mob_math_random_next_double(&math_cursor)
        * 0.20000000298023224D - 0.10000000149011612D);
    motion_z = (double)(float)(mob_math_random_next_double(&math_cursor)
        * 0.20000000298023224D - 0.10000000149011612D);
    if (!gm_live_spawn_item_exact_hover(
            drops, eid, s->x[slot], s->y[slot], s->z[slot],
            motion_x, 0.20000000298023224D, motion_z, yaw, hover,
            420, 1, 0, 0, 10, 0))
        return 0;
    for (int item = 0; item < gm_live_entity_slot_count(drops); ++item) {
        GmLiveEnt *drop = gm_live_entity_mut(drops, item);
        if (!drop) continue;
        if (!drop->active || drop->type != 0 || drop->eid != eid) continue;
        drop->uuid_present = 1;
        drop->uuid_most = uuid_most;
        drop->uuid_least = uuid_least;
        drop->random_seed48 = entity_random.seed;
        break;
    }
    *m->active_entity_seed_generator_seed48 = entity_cursor;
    *m->active_server_uuid_random_seed48 = uuid_cursor;
    *math_random_seed48 = math_cursor;
    *next_entity_id = eid + 1;
    if (m->next_id < *next_entity_id) m->next_id = *next_entity_id;
    if (m->next_orb_id < *next_entity_id)
        m->next_orb_id = *next_entity_id;
    return 1;
}

/* EntityCreature.updateLeashedState runs after super.onUpdate. Anchor-only
 * kind zero is retained for the narrow synthetic caravan fixture; exact
 * restored states always carry a player or living holder. */
static void living_leash_tail(
        GmMobLive *m, EwStore *s, int slot, int dimension,
        double player_x, double player_y, double player_z,
        float player_health, uint64_t *math_random_seed48,
        int *next_entity_id, GmLiveSim *drops) {
    int kind, holder, valid;
    double target_x = 0.0, target_y = 0.0, target_z = 0.0;
    double dx, dy, dz;
    float distance;
    if (!m || !s || slot <= 0
            || !gm_mobs_vanilla_leashable_type(s->type[slot])
            || !m->llama_leashed[slot])
        return;
    kind = m->llama_leash_holder_kind[slot];
    if (kind == 0) return;
    valid = s->alive[slot] && !m->entity_dead[slot]
        && s->health[slot] > 0.0F;
    if (kind == 1) {
        valid = valid && player_health > 0.0F;
        target_x = player_x;
        target_y = player_y;
        target_z = player_z;
    } else if (kind == 2) {
        holder = mob_slot_by_eid(m, m->llama_leash_holder_eid[slot]);
        valid = valid && holder > 0 && s->alive[holder]
            && !m->entity_dead[holder]
            && m->entity_dimension[holder] == dimension;
        if (valid) {
            target_x = s->x[holder];
            target_y = s->y[holder];
            target_z = s->z[holder];
        }
    } else if (kind == 3) {
        valid = valid && m->llama_leash_holder_eid[slot] >= 0;
        target_x = m->llama_leash_holder_x[slot];
        target_y = m->llama_leash_holder_y[slot];
        target_z = m->llama_leash_holder_z[slot];
    } else {
        valid = 0;
    }
    dx = target_x - s->x[slot];
    dy = target_y - s->y[slot];
    dz = target_z - s->z[slot];
    distance = valid ? (float)sqrt(dx * dx + dy * dy + dz * dz)
        : INFINITY;
    if (!valid) {
        living_clear_leash_slot(m, slot);
        (void)living_drop_lead_exact(
            m, s, slot, math_random_seed48, next_entity_id, drops);
        return;
    }
    /* EntitySquid inherits EntityLiving directly: it validates a holder, but
     * has none of EntityCreature's distance, pull, or navigation behavior. */
    if (s->type[slot] == EW_TYPE_SQUID) return;
    /* EntityCreature returns before onLeashDistance and motion for a sitting
     * tameable. Wolf and ocelot are the represented EntityTameable classes. */
    if ((s->type[slot] == EW_TYPE_WOLF
            || s->type[slot] == EW_TYPE_OCELOT)
            && m->tameable_sitting[slot]) {
        if (distance > 10.0F) {
            living_clear_leash_slot(m, slot);
            (void)living_drop_lead_exact(
                m, s, slot, math_random_seed48, next_entity_id, drops);
        }
        return;
    }
    /* AbstractHorse.onLeashDistance runs before the break/pull thresholds. */
    if (gm_mobs_horse_type(s->type[slot]) && distance > 6.0F
            && (m->horse_status[slot] & GM_HORSE_EATING))
        m->horse_status[slot] &= (unsigned char)~GM_HORSE_EATING;
    if (distance > 10.0F) {
        living_clear_leash_slot(m, slot);
        (void)living_drop_lead_exact(
            m, s, slot, math_random_seed48, next_entity_id, drops);
    } else if (distance > 6.0F) {
        double inverse = 1.0D / (double)distance;
        dx *= inverse; dy *= inverse; dz *= inverse;
        s->vx[slot] += dx * fabs(dx) * 0.4D;
        s->vy[slot] += dy * fabs(dy) * 0.4D;
        s->vz[slot] += dz * fabs(dz) * 0.4D;
    } else if (distance > 0.0F) {
        double scale = fmax((double)distance - 2.0D, 0.0D)
            / (double)distance;
        s->path_tx[slot] = s->x[slot] + dx * scale;
        s->path_ty[slot] = s->y[slot] + dy * scale;
        s->path_tz[slot] = s->z[slot] + dz * scale;
        s->path_len[slot] = 1;
        m->passive_nav_speed[slot] =
            s->type[slot] == EW_TYPE_LLAMA ? 2.0D : 1.0D;
    }
}

int gm_mobs_living_leash_step(
        GmMobLive *m, int eid, int dimension,
        double player_x, double player_y, double player_z,
        float player_health, uint64_t *math_random_seed48,
        int *next_entity_id, GmLiveSim *drops) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || !s->alive[slot]
            || !gm_mobs_vanilla_leashable_type(s->type[slot]))
        return 0;
    living_leash_tail(
        m, s, slot, dimension,
        player_x, player_y, player_z, player_health,
        math_random_seed48, next_entity_id, drops);
    ew_store_copy(next_store(m), s);
    return 1;
}

int gm_mobs_llama_caravan_leave(GmMobLive *m, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    int head_eid;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_LLAMA)
        return 0;
    head_eid = m->llama_caravan_head_eid[slot];
    m->llama_caravan_head_eid[slot] = -1;
    gm_mobs_living_cold_flush(m);
    if (head_eid > 0) {
        int head = mob_slot_by_eid(m, head_eid);
        if (head > 0 && m->llama_caravan_tail_eid[head] == eid)
            m->llama_caravan_tail_eid[head] = -1;
    }
    return 1;
}

int gm_mobs_llama_caravan_join(
        GmMobLive *m, int eid, int head_eid) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || eid == head_eid
            || s->type[slot] != EW_TYPE_LLAMA
            || m->llama_caravan_head_eid[slot] > 0)
        return 0;
    gm_mobs_living_cold_flush(m);
    int head = mob_slot_by_eid(m, head_eid);
    s = m ? const_store(m) : NULL;
    if (head <= 0 || !s || s->type[head] != EW_TYPE_LLAMA
            || m->llama_caravan_tail_eid[head] > 0)
        return 0;
    m->llama_caravan_tail_eid[head] = eid;
    gm_mobs_living_cold_flush(m);
    slot = mob_slot_by_eid(m, eid);
    if (slot <= 0) return 0;
    m->llama_caravan_head_eid[slot] = head_eid;
    return 1;
}

static int llama_first_is_leashed(
        GmMobLive *m, int eid, int depth) {
    int slot, head_eid, head;
    const EwStore *s;
    if (!m || depth > 8 || eid <= 0)
        return 0;
    slot = mob_slot_by_eid(m, eid);
    s = const_store(m);
    if (slot <= 0 || !s->alive[slot]
            || s->type[slot] != EW_TYPE_LLAMA)
        return 0;
    head_eid = m->llama_caravan_head_eid[slot];
    if (head_eid <= 0) return 0;
    head = mob_slot_by_eid(m, head_eid);
    s = const_store(m);
    if (head <= 0 || !s->alive[head]
            || s->type[head] != EW_TYPE_LLAMA)
        return 0;
    if (m->llama_leashed[head]) return 1;
    return llama_first_is_leashed(m, head_eid, depth + 1);
}

int gm_mobs_llama_caravan_try_join(GmMobLive *m, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    int candidate_eid = -1;
    double best = HUGE_VAL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_LLAMA
            || m->llama_leashed[slot]
            || m->llama_caravan_head_eid[slot] > 0)
        return 0;
    int dimension = m->entity_dimension[slot];
    double x = s->x[slot], y = s->y[slot], z = s->z[slot];
    for (int pass = 0; pass < 2 && candidate_eid < 0; ++pass) {
        int cursor = 0, other;
        while ((other = living_next_slot_from_store(m, s, &cursor)) > 0) {
            if (s->id[other] == eid || !s->alive[other]
                    || s->type[other] != EW_TYPE_LLAMA
                    || m->entity_dimension[other] != dimension
                    || fabs(s->x[other] - x) >= 9.9D
                    || fabs(s->z[other] - z) >= 9.9D
                    || s->y[other] - y >= 5.87D
                    || s->y[other] - y <= -5.87D
                    || m->llama_caravan_tail_eid[other] > 0)
                continue;
            if (pass == 0 && m->llama_caravan_head_eid[other] <= 0)
                continue;
            if (pass == 1 && !m->llama_leashed[other])
                continue;
            double dx = x - s->x[other];
            double dy = y - s->y[other];
            double dz = z - s->z[other];
            double distance = dx * dx + dy * dy + dz * dz;
            if (distance <= best) {
                best = distance;
                candidate_eid = s->id[other];
            }
        }
        living_cold_flush_one_from_store(
            m, s, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
            &m->living_staged_cold_secondary);
    }
    if (candidate_eid <= 0 || best < 4.0D)
        return 0;
    int candidate = mob_slot_by_eid(m, candidate_eid);
    int candidate_leashed = candidate > 0 && m->llama_leashed[candidate];
    if (!candidate_leashed
            && !llama_first_is_leashed(m, candidate_eid, 1))
        return 0;
    return gm_mobs_llama_caravan_join(m, eid, candidate_eid);
}

int gm_mobs_llama_caravan_step(
        GmMobLive *m, int eid,
        double *target_x, double *target_y, double *target_z,
        double *speed) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    int head;
    double dx, dy, dz, distance_sq;
    int active = 1;
    int accelerated = 0;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_LLAMA)
        return 0;
    int head_eid = m->llama_caravan_head_eid[slot];
    if (head_eid <= 0 || !llama_first_is_leashed(m, eid, 0))
        active = 0;
    slot = mob_slot_by_eid(m, eid);
    head = mob_slot_by_eid(m, head_eid);
    s = m ? now_store(m) : NULL;
    if (slot <= 0 || head <= 0 || !s || !s->alive[head]
            || s->type[head] != EW_TYPE_LLAMA)
        active = 0;
    if (active) {
        dx = s->x[head] - s->x[slot];
        dy = s->y[head] - s->y[slot];
        dz = s->z[head] - s->z[slot];
        distance_sq = dx * dx + dy * dy + dz * dz;
        if (distance_sq > 676.0D) {
            if (m->llama_caravan_speed[slot] <= 3.0D) {
                m->llama_caravan_speed[slot] *= 1.2D;
                m->llama_caravan_dist_counter[slot] = 40;
                accelerated = 1;
            } else if (m->llama_caravan_dist_counter[slot] == 0) {
                active = 0;
            }
        }
        /* EntityAILlamaFollowCaravan.continueExecuting ages this private
         * grace clock on every continuing update, including after the pair
         * returns inside 26 blocks. Only the speed-increase branch returns
         * before the decrement. */
        if (active && !accelerated
                && m->llama_caravan_dist_counter[slot] > 0)
            --m->llama_caravan_dist_counter[slot];
    }
    if (!active) {
        (void)gm_mobs_llama_caravan_leave(m, eid);
        slot = mob_slot_by_eid(m, eid);
        if (slot > 0) m->llama_caravan_speed[slot] = 2.1D;
        /* resetTask restores speed but deliberately retains distCheckCounter
         * in the task instance for a later execution. */
        return 0;
    }
    dx = s->x[head] - s->x[slot];
    dy = s->y[head] - s->y[slot];
    dz = s->z[head] - s->z[slot];
    {
        double norm = (double)(float)sqrt(dx * dx + dy * dy + dz * dz);
        float fdx = (float)(s->x[slot] - s->x[head]);
        float fdy = (float)(s->y[slot] - s->y[head]);
        float fdz = (float)(s->z[slot] - s->z[head]);
        float squared = fdx * fdx + fdy * fdy + fdz * fdz;
        double follow = (double)(float)sqrt((double)squared) - 2.0D;
        if (follow < 0.0D) follow = 0.0D;
        if (norm < 1.0E-4D) {
            dx = dy = dz = 0.0D;
        } else {
            dx = dx / norm * follow;
            dy = dy / norm * follow;
            dz = dz / norm * follow;
        }
    }
    s->path_tx[slot] = s->x[slot] + dx;
    s->path_ty[slot] = s->y[slot] + dy;
    s->path_tz[slot] = s->z[slot] + dz;
    s->path_len[slot] = 1;
    m->passive_nav_speed[slot] = m->llama_caravan_speed[slot];
    if (target_x) *target_x = s->path_tx[slot];
    if (target_y) *target_y = s->path_ty[slot];
    if (target_z) *target_z = s->path_tz[slot];
    if (speed) *speed = m->llama_caravan_speed[slot];
    return 1;
}

int gm_mobs_llama_spit_attack_exact(
        GmMobLive *m, int owner_eid, int target_eid, int spit_eid,
        uint64_t random_seed48, int random_have_gaussian,
        double random_next_gaussian, const McSinTable *sin_table,
        GmLlamaSpit *out) {
    int owner = mob_slot_by_eid(m, owner_eid);
    int target = mob_slot_by_eid(m, target_eid);
    EwStore *s = m ? now_store(m) : NULL;
    GmLlamaSpit spit;
    float owner_width, owner_height, target_width, target_height;
    float angle, horizontal, norm;
    double aim_x, aim_y, aim_z;
    if (owner <= 0 || target <= 0 || owner == target || !s || !sin_table
            || !s->alive[owner] || !s->alive[target]
            || s->type[owner] != EW_TYPE_LLAMA
            || !gm_living(s->type[target]) || spit_eid <= 0
            || random_seed48 >= (UINT64_C(1) << 48)
            || (random_have_gaussian != 0 && random_have_gaussian != 1)
            || !isfinite(random_next_gaussian)
            || !MOB_COLD_RESERVE(
                m, llama_spits, m->llama_spit_count + 1,
                GM_LLAMA_SPITS))
        return 0;
    ehs_size_scaled(
        s->type[owner], m->size[owner], &owner_width, &owner_height);
    ehs_size_scaled(
        s->type[target], m->size[target], &target_width, &target_height);
    (void)target_width;
    memset(&spit, 0, sizeof spit);
    spit.active = 1;
    spit.dimension = m->entity_dimension[owner];
    spit.eid = spit_eid;
    spit.owner_eid = owner_eid;
    spit.owner_uuid_present = m->entity_uuid_present[owner];
    spit.owner_uuid_most = (uint64_t)m->entity_uuid_most[owner];
    spit.owner_uuid_least = (uint64_t)m->entity_uuid_least[owner];
    angle = s->yaw[owner] * 0.017453292F;
    {
        double offset = (double)(owner_width + 1.0F) * 0.5D;
        spit.x = s->x[owner] - offset * (double)mc_sin(sin_table, angle);
        spit.y = s->y[owner] + (double)owner_height
            - 0.10000000149011612D;
        spit.z = s->z[owner] + offset * (double)mc_cos(sin_table, angle);
    }
    aim_x = s->x[target] - s->x[owner];
    aim_y = s->y[target] + (double)(target_height / 3.0F) - spit.y;
    aim_z = s->z[target] - s->z[owner];
    horizontal = (float)sqrt(aim_x * aim_x + aim_z * aim_z);
    aim_y += (double)(horizontal * 0.2F);
    norm = (float)sqrt(aim_x * aim_x + aim_y * aim_y + aim_z * aim_z);
    if (!(norm > 0.0F)) return 0;
    aim_x /= (double)norm;
    aim_y /= (double)norm;
    aim_z /= (double)norm;
    jrand_gaussian_set_state(
        &spit.random, random_seed48,
        random_have_gaussian, random_next_gaussian);
    aim_x += jrand_gaussian_next(&spit.random)
        * 0.007499999832361937D * 10.0D;
    aim_y += jrand_gaussian_next(&spit.random)
        * 0.007499999832361937D * 10.0D;
    aim_z += jrand_gaussian_next(&spit.random)
        * 0.007499999832361937D * 10.0D;
    spit.vx = aim_x * 1.5D;
    spit.vy = aim_y * 1.5D;
    spit.vz = aim_z * 1.5D;
    horizontal = (float)sqrt(spit.vx * spit.vx + spit.vz * spit.vz);
    spit.yaw = (float)(mob_java_math_atan2(spit.vx, spit.vz)
        * (180.0D / MC_PI));
    spit.pitch = (float)(mob_java_math_atan2(
        spit.vy, (double)horizontal) * (180.0D / MC_PI));
    spit.prev_yaw = spit.yaw;
    spit.prev_pitch = spit.pitch;
    m->llama_spits[m->llama_spit_count++] = spit;
    llama_spit_particle_append(m, &spit);
    {
        JavaRandom *owner_random = &m->entity_random[owner].random;
        float pitch = 1.0F
            + (jrand_float(owner_random) - jrand_float(owner_random)) * 0.2F;
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, owner_eid, GM_MOB_SOUND_LLAMA_SPIT,
            s->x[owner], s->y[owner], s->z[owner], 1.0F, pitch);
    }
    m->llama_did_spit[owner] = 1;
    if (m->next_id <= spit_eid) m->next_id = spit_eid + 1;
    if (out) *out = spit;
    return 1;
}

static int llama_spit_attack_live(
        GmMobLive *m, const EwStore *s, const McSinTable *sin_table,
        int owner, double target_x, double target_y, double target_z,
        float target_height, int *next_entity_id) {
    JavaRandom generator;
    GmLlamaSpit spit;
    int64_t uuid_most, uuid_least;
    float owner_width, owner_height, angle, horizontal, norm;
    double aim_x, aim_y, aim_z;
    int spit_eid;
    if (!m || !s || !sin_table || owner <= 0
            || owner >= EW_MAX_ENTITIES || !s->alive[owner]
            || s->type[owner] != EW_TYPE_LLAMA
            || !m->active_entity_seed_generator_seed48
            || !m->active_server_uuid_random_seed48
            || !next_entity_id || *next_entity_id <= 0
            || *next_entity_id == INT_MAX
            || !MOB_COLD_RESERVE(
                m, llama_spits, m->llama_spit_count + 1,
                GM_LLAMA_SPITS))
        return 0;
    spit_eid = *next_entity_id;
    memset(&spit, 0, sizeof spit);
    spit.active = 1;
    spit.dimension = m->entity_dimension[owner];
    spit.eid = spit_eid;
    spit.owner_eid = s->id[owner];
    spit.owner_uuid_present = m->entity_uuid_present[owner];
    spit.owner_uuid_most = (uint64_t)m->entity_uuid_most[owner];
    spit.owner_uuid_least = (uint64_t)m->entity_uuid_least[owner];
    jrand_set_seed48(
        &generator, *m->active_entity_seed_generator_seed48);
    jrand_gaussian_set(&spit.random, jrand_long(&generator));
    *m->active_entity_seed_generator_seed48 = generator.seed;
    skeleton_trap_next_uuid(
        m->active_server_uuid_random_seed48, &uuid_most, &uuid_least);
    spit.uuid_present = 1;
    spit.uuid_most = uuid_most;
    spit.uuid_least = uuid_least;
    ehs_size_scaled(
        s->type[owner], m->size[owner], &owner_width, &owner_height);
    angle = s->yaw[owner] * 0.017453292F;
    {
        double offset = (double)(owner_width + 1.0F) * 0.5D;
        spit.x = s->x[owner]
            - offset * (double)mc_sin(sin_table, angle);
        spit.y = s->y[owner] + (double)owner_height
            - 0.10000000149011612D;
        spit.z = s->z[owner]
            + offset * (double)mc_cos(sin_table, angle);
    }
    aim_x = target_x - s->x[owner];
    aim_y = target_y + (double)(target_height / 3.0F) - spit.y;
    aim_z = target_z - s->z[owner];
    horizontal = (float)sqrt(aim_x * aim_x + aim_z * aim_z);
    aim_y += (double)(horizontal * 0.2F);
    norm = (float)sqrt(aim_x * aim_x + aim_y * aim_y + aim_z * aim_z);
    if (!(norm > 0.0F)) return 0;
    aim_x /= (double)norm;
    aim_y /= (double)norm;
    aim_z /= (double)norm;
    aim_x += jrand_gaussian_next(&spit.random)
        * 0.007499999832361937D * 10.0D;
    aim_y += jrand_gaussian_next(&spit.random)
        * 0.007499999832361937D * 10.0D;
    aim_z += jrand_gaussian_next(&spit.random)
        * 0.007499999832361937D * 10.0D;
    spit.vx = aim_x * 1.5D;
    spit.vy = aim_y * 1.5D;
    spit.vz = aim_z * 1.5D;
    horizontal = (float)sqrt(spit.vx * spit.vx + spit.vz * spit.vz);
    spit.yaw = (float)(mob_java_math_atan2(spit.vx, spit.vz)
        * (180.0D / MC_PI));
    spit.pitch = (float)(mob_java_math_atan2(
        spit.vy, (double)horizontal) * (180.0D / MC_PI));
    spit.prev_yaw = spit.yaw;
    spit.prev_pitch = spit.pitch;
    m->llama_spits[m->llama_spit_count++] = spit;
    llama_spit_particle_append(m, &spit);
    {
        JavaRandom *owner_random = &m->entity_random[owner].random;
        float pitch = 1.0F
            + (jrand_float(owner_random) - jrand_float(owner_random)) * 0.2F;
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[owner],
            GM_MOB_SOUND_LLAMA_SPIT,
            s->x[owner], s->y[owner], s->z[owner], 1.0F, pitch);
    }
    m->llama_did_spit[owner] = 1;
    *next_entity_id = spit_eid + 1;
    if (m->next_id < *next_entity_id) m->next_id = *next_entity_id;
    return 1;
}

/* EntityLlama.AIDefendTarget: the target task gets a setup boundary every
 * three ticks, rolls nextInt(16), searches the nearest untamed wolf in the
 * overridden ten-block target area, then pays canEasilyReach's nextInt(5)
 * retry-delay draw.  The live navigator is direct, so the final-cell test is
 * the represented equivalent of Path.getFinalPathPoint being within 1.5. */
static int llama_defend_wolf_try_acquire(
        GmMobLive *m, GmWorld *w, const EwStore *s,
        int llama, int dimension) {
    int best_eid = -1;
    double best_x = 0.0, best_y = 0.0, best_z = 0.0;
    double llama_x, llama_y, llama_z;
    double best_distance = HUGE_VAL;
    if (!m || !w || !s || llama <= 0 || llama >= EW_MAX_ENTITIES
            || !s->alive[llama] || s->type[llama] != EW_TYPE_LLAMA
            || jrand_int_bound(&m->entity_random[llama].random, 16) != 0)
        return -1;
    llama_x = s->x[llama];
    llama_y = s->y[llama];
    llama_z = s->z[llama];
    loaded_order_prepare(m);
    for (int order = 0; order < m->loaded_order_count; ++order) {
        GmMobLoadedRef ref = *loaded_ref_at(m, order);
        int wolf = living_loaded_ref_stage_secondary(
            m, &ref, (EwStore *)s);
        if (wolf <= 0
                || !s->alive[wolf] || s->type[wolf] != EW_TYPE_WOLF
                || m->entity_dimension[wolf] != dimension
                || m->tameable_tamed[wolf])
            continue;
        double dx = s->x[wolf] - llama_x;
        double dy = s->y[wolf] - llama_y;
        double dz = s->z[wolf] - llama_z;
        if (fabs(dx) >= 10.75D || dy <= -4.85D || dy >= 5.87D
                || fabs(dz) >= 10.75D)
            continue;
        double distance = dx * dx + dy * dy + dz * dz;
        if (distance < best_distance) {
            best_distance = distance;
            best_eid = s->id[wolf];
            best_x = s->x[wolf];
            best_y = s->y[wolf];
            best_z = s->z[wolf];
        }
    }
    if (best_eid <= 0) return -1;
    (void)jrand_int_bound(&m->entity_random[llama].random, 5);
    {
        int x = mc_floor(best_x);
        int y = mc_floor(best_y);
        int z = mc_floor(best_z);
        if (y <= 0 || !solid_id(gm_world_block(w, x, y - 1, z))
                || solid_id(gm_world_block(w, x, y, z))
                || solid_id(gm_world_block(w, x, y + 1, z)))
            return -1;
    }
    return mob_slot_by_eid(m, best_eid);
}

int gm_mobs_take_llama_spit(GmMobLive *m, GmLlamaSpit *out) {
    if (!m || !out || m->llama_spit_count <= 0) return 0;
    *out = m->llama_spits[0];
    --m->llama_spit_count;
    if (m->llama_spit_count > 0)
        memmove(&m->llama_spits[0], &m->llama_spits[1],
            (size_t)m->llama_spit_count * sizeof m->llama_spits[0]);
    memset(&m->llama_spits[m->llama_spit_count], 0,
           sizeof m->llama_spits[0]);
    return 1;
}

int gm_mobs_take_snowman_shot(GmMobLive *m, GmSnowmanShot *out) {
    if (!m || !out || m->snowman_shot_count <= 0) return 0;
    *out = m->snowman_shots[0];
    --m->snowman_shot_count;
    if (m->snowman_shot_count > 0)
        memmove(&m->snowman_shots[0], &m->snowman_shots[1],
            (size_t)m->snowman_shot_count * sizeof m->snowman_shots[0]);
    memset(&m->snowman_shots[m->snowman_shot_count], 0,
           sizeof m->snowman_shots[0]);
    return 1;
}

static int snowman_target_visible(
        GmMobLive *m, GmWorld *w, const EwStore *s,
        int snowman, int target) {
    return los_clear(
        w, s->x[snowman], s->y[snowman] + 1.7D, s->z[snowman],
        s->x[target], s->y[target]
            + (double)mob_eye_height(m, s, target), s->z[target]);
}

static int snowman_target_valid(
        GmMobLive *m, GmWorld *w, const EwStore *s,
        int snowman, int target, int dimension, int acquire) {
    if (target <= 0 || target >= EW_MAX_ENTITIES || target == snowman
            || !s->alive[target] || m->entity_dead[target]
            || s->health[target] <= 0.0F || !gm_hostile(s->type[target])
            || m->entity_dimension[target] != dimension)
        return 0;
    double dx = s->x[target] - s->x[snowman];
    double dy = s->y[target] - s->y[snowman];
    double dz = s->z[target] - s->z[snowman];
    if (dx * dx + dy * dy + dz * dz > 256.0D) return 0;
    if (acquire) {
        float target_width, target_height;
        ehs_size_scaled(
            s->type[target], m->size[target],
            &target_width, &target_height);
        if (fabs(dx) > 16.35D + (double)target_width * 0.5D
                || s->y[target] + (double)target_height
                    < s->y[snowman] - 4.0D
                || s->y[target] > s->y[snowman] + 5.9D
                || fabs(dz) > 16.35D + (double)target_width * 0.5D)
            return 0;
    }
    return !acquire || snowman_target_visible(m, w, s, snowman, target);
}

static int snowman_try_acquire_target(
        GmMobLive *m, GmWorld *w, const EwStore *s,
        int snowman, int dimension) {
    EwStore *completed = (EwStore *)s;
    int best_eid = -1;
    double best_distance = DBL_MAX;
    if (jrand_int_bound(&m->entity_random[snowman].random, 10) != 0)
        return -1;
    double snowman_x = s->x[snowman];
    double snowman_y = s->y[snowman];
    double snowman_z = s->z[snowman];
    int cursor = 0, target;
    while ((target = living_next_slot_from_store(
                m, completed, &cursor)) > 0) {
        if (!snowman_target_valid(
                m, w, s, snowman, target, dimension, 1))
            continue;
        double dx = s->x[target] - snowman_x;
        double dy = s->y[target] - snowman_y;
        double dz = s->z[target] - snowman_z;
        double distance = dx * dx + dy * dy + dz * dz;
        if (distance < best_distance) {
            best_distance = distance;
            best_eid = s->id[target];
        }
    }
    living_cold_flush_one_from_store(
        m, completed, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &m->living_staged_cold_secondary);
    return mob_slot_by_eid(m, best_eid);
}

static int snowman_attack_live(
        GmMobLive *m, const EwStore *s, int owner, int target,
        int *next_entity_id) {
    JavaRandom generator;
    GmSnowmanShot shot;
    int64_t uuid_most, uuid_least;
    double dx, dy, dz, horizontal;
    EbfVector heading;
    if (!m || !s || owner <= 0 || target <= 0
            || owner >= EW_MAX_ENTITIES || target >= EW_MAX_ENTITIES
            || !s->alive[owner] || !s->alive[target]
            || s->type[owner] != EW_TYPE_SNOWMAN
            || !m->active_entity_seed_generator_seed48
            || !m->active_server_uuid_random_seed48
            || !next_entity_id || *next_entity_id <= 0
            || *next_entity_id == INT_MAX
            || !MOB_COLD_RESERVE(
                m, snowman_shots, m->snowman_shot_count + 1,
                GM_SNOWMAN_SHOTS))
        return 0;
    memset(&shot, 0, sizeof shot);
    shot.active = 1;
    shot.dimension = m->entity_dimension[owner];
    shot.eid = *next_entity_id;
    shot.owner_eid = s->id[owner];
    shot.owner_uuid_present = m->entity_uuid_present[owner];
    shot.owner_uuid_most = (uint64_t)m->entity_uuid_most[owner];
    shot.owner_uuid_least = (uint64_t)m->entity_uuid_least[owner];
    jrand_set_seed48(
        &generator, *m->active_entity_seed_generator_seed48);
    jrand_gaussian_set(&shot.random, jrand_long(&generator));
    *m->active_entity_seed_generator_seed48 = generator.seed;
    skeleton_trap_next_uuid(
        m->active_server_uuid_random_seed48, &uuid_most, &uuid_least);
    shot.uuid_present = 1;
    shot.uuid_most = uuid_most;
    shot.uuid_least = uuid_least;
    shot.x = s->x[owner];
    shot.y = s->y[owner] + (double)1.7F - 0.10000000149011612D;
    shot.z = s->z[owner];
    dx = s->x[target] - s->x[owner];
    dy = s->y[target] + (double)mob_eye_height(m, s, target)
        - 1.100000023841858D - shot.y;
    dz = s->z[target] - s->z[owner];
    horizontal = (double)(float)sqrt(dx * dx + dz * dz);
    heading = ebf_throwable_heading(
        &shot.random, dx,
        dy + (double)((float)horizontal * 0.2F), dz, 1.6F, 12.0F);
    shot.vx = heading.x;
    shot.vy = heading.y;
    shot.vz = heading.z;
    horizontal = (double)(float)sqrt(
        shot.vx * shot.vx + shot.vz * shot.vz);
    shot.yaw = (float)(mob_java_math_atan2(
        shot.vx, shot.vz) * (180.0D / MC_PI));
    shot.pitch = (float)(mob_java_math_atan2(
        shot.vy, horizontal) * (180.0D / MC_PI));
    m->snowman_shots[m->snowman_shot_count++] = shot;
    {
        float pitch = 1.0F / (
            jrand_float(&m->entity_random[owner].random) * 0.4F + 0.8F);
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[owner],
            GM_MOB_SOUND_SNOWMAN_SHOOT,
            s->x[owner], s->y[owner], s->z[owner], 1.0F, pitch);
    }
    ++*next_entity_id;
    if (m->next_id < *next_entity_id) m->next_id = *next_entity_id;
    return 1;
}

int gm_mobs_snowman_attack_exact(
        GmMobLive *m, int owner_eid, int target_eid,
        uint64_t *entity_seed_generator_seed48,
        uint64_t *server_uuid_random_seed48,
        int *next_entity_id, GmSnowmanShot *out) {
    int owner = mob_slot_by_eid(m, owner_eid);
    int target = mob_slot_by_eid(m, target_eid);
    const EwStore *s = m ? const_store(m) : NULL;
    uint64_t *old_entity_generator;
    uint64_t *old_uuid_random;
    if (!s || owner <= 0 || target <= 0 || owner == target
            || !entity_seed_generator_seed48
            || !server_uuid_random_seed48 || !next_entity_id
            || *entity_seed_generator_seed48 >= (UINT64_C(1) << 48)
            || *server_uuid_random_seed48 >= (UINT64_C(1) << 48)
            || *next_entity_id <= 0 || *next_entity_id == INT_MAX)
        return 0;
    old_entity_generator = m->active_entity_seed_generator_seed48;
    old_uuid_random = m->active_server_uuid_random_seed48;
    m->active_entity_seed_generator_seed48 =
        entity_seed_generator_seed48;
    m->active_server_uuid_random_seed48 = server_uuid_random_seed48;
    int accepted = snowman_attack_live(
        m, s, owner, target, next_entity_id);
    m->active_entity_seed_generator_seed48 = old_entity_generator;
    m->active_server_uuid_random_seed48 = old_uuid_random;
    if (!accepted) return 0;
    if (out) *out = m->snowman_shots[m->snowman_shot_count - 1];
    return 1;
}

int gm_mobs_llama_spit_hit(
        GmMobLive *m, int slot, int owner_eid,
        GmLiveSim *drops, const GmMobDeathContext *death_context) {
    EwStore *s = m ? now_store(m) : NULL;
    int owner = mob_slot_by_eid(m, owner_eid);
    int result;
    if (!s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot] || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT || m->entity_dead[slot]
            || s->health[slot] <= 0.0F)
        return 0;
    if (death_context && owner > 0 && !m->controlled_no_ai[slot]) {
        GmMobDamageEntitySource source = {
            s->x[owner], s->z[owner], death_context,
            s->id[owner], 0, 0, 0, 1,
        };
        result = s->type[slot] == EW_TYPE_WITCH
            ? mob_source_damage_witch_slot_exact(
                m, s, slot, 1.0F, drops,
                death_context->math_random_seed48,
                death_context->next_entity_id,
                death_context->do_mob_loot, 0, &source)
            : gm_passive(s->type[slot])
            ? mob_source_damage_passive_slot_exact(
                m, s, slot, 1.0F, drops,
                death_context->math_random_seed48,
                death_context->next_entity_id,
                death_context->do_mob_loot, 0, 1, 0, &source)
            : mob_source_damage_ordinary_slot_exact(
                m, s, slot, 1.0F, drops,
                death_context->math_random_seed48,
                death_context->next_entity_id,
                death_context->do_mob_loot, 0, 1, 0, &source);
    } else {
        int fresh = m->entity_hurt_resistant[slot] <= 10;
        if (!fresh && 1.0F <= m->entity_last_damage[slot]) {
            ew_store_copy(next_store(m), s);
            return 1;
        }
        float applied = fresh ? 1.0F : 1.0F - m->entity_last_damage[slot];
        applied = player_attack_after_mob_armor(
            m, slot, s->type[slot], applied);
        applied = mob_resistance_damage(m, slot, applied);
        applied = mob_absorb_damage(m, slot, applied);
        m->entity_last_damage[slot] = 1.0F;
        if (fresh) {
            m->entity_hurt_resistant[slot] = 20;
            m->entity_hurt_time[slot] = 10;
        }
        s->health[slot] -= applied;
        if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
        mark_hurt(m, s, slot);
        result = 1;
    }
    ew_store_copy(next_store(m), s);
    return result < 0 ? 0 : 1;
}

static int horse_inventory_size(const GmMobLive *m, int slot) {
    const EwStore *s = const_store(m);
    if (!m->horse_chested[slot]) return 2;
    return s->type[slot] == EW_TYPE_LLAMA
        ? 2 + 3 * (int)m->llama_strength[slot] : 17;
}

int gm_mobs_set_horse_inventory(
        GmMobLive *m, int eid, int inventory_slot, ICStack stack) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || !gm_mobs_horse_type(s->type[slot])
            || inventory_slot < 0
            || inventory_slot >= horse_inventory_size(m, slot)
            || stack.item < 0 || stack.item > 4095
            || stack.count < 0 || stack.count > 64
            || ((stack.item == 0) != (stack.count == 0))
            || (inventory_slot == 0 && stack.count > 0
                && (s->type[slot] == EW_TYPE_LLAMA || stack.item != 329))
            || (inventory_slot == 1 && stack.count > 0
                && !((s->type[slot] == EW_TYPE_HORSE
                        && stack.item >= 417 && stack.item <= 419)
                    || (s->type[slot] == EW_TYPE_LLAMA
                        && stack.item == 171
                        && stack.meta >= 0 && stack.meta <= 15))))
        return 0;
    int previous_decor = m->llama_decor[slot];
    m->horse_inventory[slot][inventory_slot] = stack;
    if (inventory_slot == 0) {
        if (stack.count > 0 && s->type[slot] != EW_TYPE_LLAMA)
            m->horse_status[slot] |= GM_HORSE_SADDLED;
        else
            m->horse_status[slot] &= (unsigned char)~GM_HORSE_SADDLED;
    } else if (inventory_slot == 1) {
        if (s->type[slot] == EW_TYPE_LLAMA)
            m->llama_decor[slot] = stack.count <= 0
                ? -1 : (signed char)stack.meta;
        else
            m->horse_armor[slot] = stack.count <= 0 ? 0
                : (unsigned char)(stack.item - 416);
    }
    /* EntityLlama.onInventoryChanged samples the prior color around its
     * superclass update, then announces only a newly selected carpet after
     * the first twenty entity ticks. Removal and same-color replacement are
     * silent. Fixture imports normally have ticksExisted below this boundary. */
    if (s->type[slot] == EW_TYPE_LLAMA && inventory_slot == 1
            && m->entity_ticks_existed[slot] > 20
            && m->llama_decor[slot] >= 0
            && m->llama_decor[slot] != previous_decor)
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot], GM_MOB_SOUND_LLAMA_SWAG,
            s->x[slot], s->y[slot], s->z[slot], 0.5F, 1.0F);
    return 1;
}

int gm_mobs_horse_equip_chest(
        GmMobLive *m, int eid, IsrInv *inventory,
        int hand_slot, int creative) {
    int slot, sound;
    float first, second, pitch;
    ICStack held;
    EwStore *s;
    JavaRandom *random;
    if (!m || !inventory || (creative != 0 && creative != 1)) return 0;
    slot = mob_slot_by_eid(m, eid);
    s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s
            || (s->type[slot] != EW_TYPE_DONKEY
                && s->type[slot] != EW_TYPE_MULE
                && s->type[slot] != EW_TYPE_LLAMA)
            || !(m->horse_status[slot] & GM_HORSE_TAME)
            || m->horse_chested[slot])
        return 0;
    held = isr_get_stack(inventory, hand_slot);
    if (held.item != 54 || held.count <= 0) return 0;
    m->horse_chested[slot] = 1;
    if (!creative) (void)isr_decr_stack_size(inventory, hand_slot, 1);
    random = &m->entity_random[slot].random;
    first = jrand_float(random);
    second = jrand_float(random);
    pitch = 1.0F + (first - second) * 0.2F;
    sound = s->type[slot] == EW_TYPE_MULE
        ? GM_MOB_SOUND_MULE_CHEST
        : s->type[slot] == EW_TYPE_LLAMA
        ? GM_MOB_SOUND_LLAMA_CHEST : GM_MOB_SOUND_DONKEY_CHEST;
    mob_event_append(
        m, GM_MOB_EVENT_SOUND, s->id[slot], sound,
        s->x[slot], s->y[slot], s->z[slot], 1.0F, pitch);
    return 1;
}

int gm_mobs_restore_horse_lifecycle(
        GmMobLive *m, int eid, int in_love, int forced_age,
        int forced_age_timer, int eating_counter, int open_mouth_counter,
        int jump_rearing_counter, int tail_counter, int sprint_counter,
        int gallop_time, int horse_jumping, int allow_stand_sliding,
        float jump_power, float head_lean, float prev_head_lean,
        float rearing_amount, float prev_rearing_amount,
        float mouth_openness, float prev_mouth_openness,
        float prev_limb_amount, float limb_amount, float limb_swing) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || !gm_mobs_horse_type(s->type[slot])
            || in_love < 0 || in_love > 600 || forced_age_timer < 0
            || eating_counter < 0 || open_mouth_counter < 0
            || jump_rearing_counter < 0 || tail_counter < 0
            || sprint_counter < 0 || gallop_time < 0
            || (horse_jumping != 0 && horse_jumping != 1)
            || (allow_stand_sliding != 0 && allow_stand_sliding != 1)
            || !isfinite(jump_power) || jump_power < 0.0F
            || jump_power > 1.0F || !isfinite(head_lean)
            || head_lean < 0.0F || head_lean > 1.0F
            || !isfinite(prev_head_lean) || prev_head_lean < 0.0F
            || prev_head_lean > 1.0F || !isfinite(rearing_amount)
            || rearing_amount < 0.0F || rearing_amount > 1.0F
            || !isfinite(prev_rearing_amount)
            || prev_rearing_amount < 0.0F || prev_rearing_amount > 1.0F
            || !isfinite(mouth_openness) || mouth_openness < 0.0F
            || mouth_openness > 1.0F || !isfinite(prev_mouth_openness)
            || prev_mouth_openness < 0.0F || prev_mouth_openness > 1.0F
            || !isfinite(prev_limb_amount) || !isfinite(limb_amount)
            || !isfinite(limb_swing))
        return 0;
    m->sheep_in_love[slot] = in_love;
    m->sheep_forced_age[slot] = forced_age;
    m->sheep_forced_age_timer[slot] = forced_age_timer;
    m->horse_eating_counter[slot] = eating_counter;
    m->horse_open_mouth_counter[slot] = open_mouth_counter;
    m->horse_jump_rearing_counter[slot] = jump_rearing_counter;
    m->horse_tail_counter[slot] = tail_counter;
    m->horse_sprint_counter[slot] = sprint_counter;
    m->horse_gallop_time[slot] = gallop_time;
    m->horse_jumping[slot] = (unsigned char)horse_jumping;
    m->horse_allow_stand_sliding[slot] =
        (unsigned char)allow_stand_sliding;
    m->horse_jump_power[slot] = jump_power;
    m->horse_head_lean[slot] = head_lean;
    m->horse_prev_head_lean[slot] = prev_head_lean;
    m->horse_rearing_amount[slot] = rearing_amount;
    m->horse_prev_rearing_amount[slot] = prev_rearing_amount;
    m->horse_mouth_openness[slot] = mouth_openness;
    m->horse_prev_mouth_openness[slot] = prev_mouth_openness;
    m->horse_prev_limb_amount[slot] = prev_limb_amount;
    m->horse_limb_amount[slot] = limb_amount;
    m->horse_limb_swing[slot] = limb_swing;
    return 1;
}

static void horse_open_mouth(GmMobLive *m, int slot) {
    m->horse_open_mouth_counter[slot] = 1;
    m->horse_status[slot] |= GM_HORSE_MOUTH_OPEN;
}

int gm_mobs_horse_feed(
        GmMobLive *m, int eid, IsrInv *inventory,
        int hand_slot, int creative) {
    int slot, growth = 0, temper = 0, handled = 0;
    float healing = 0.0F;
    ICStack held;
    EwStore *s;
    if (!m || !inventory || (creative != 0 && creative != 1)) return 0;
    slot = mob_slot_by_eid(m, eid);
    s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || !gm_mobs_horse_type(s->type[slot])) return 0;
    held = isr_get_stack(inventory, hand_slot);
    if (held.count <= 0) return 0;
    if (s->type[slot] == EW_TYPE_LLAMA) {
        if (held.item == 296) {
            healing = 2.0F;
            growth = 10;
            temper = 3;
        } else if (held.item == 170) {
            healing = 10.0F;
            growth = 90;
            temper = 6;
        } else {
            return 0;
        }
    } else switch (held.item) {
    case 296: healing = 2.0F; growth = 20; temper = 3; break;
    case 353: healing = 1.0F; growth = 30; temper = 3; break;
    case 170: healing = 20.0F; growth = 180; break;
    case 260: healing = 3.0F; growth = 60; temper = 3; break;
    case 396: healing = 4.0F; growth = 60; temper = 5; break;
    case 322: healing = 10.0F; growth = 240; temper = 10; break;
    default: return 0;
    }
    if (s->health[slot] < (float)m->horse_max_health[slot]) {
        s->health[slot] += healing;
        if (s->health[slot] > (float)m->horse_max_health[slot])
            s->health[slot] = (float)m->horse_max_health[slot];
        handled = 1;
    }
    if (m->growing_age[slot] < 0 && growth > 0) {
        long long age = (long long)m->growing_age[slot]
            + (long long)growth * 20LL;
        m->growing_age[slot] = age > 0 ? 0 : (int)age;
        handled = 1;
    }
    if (((s->type[slot] == EW_TYPE_LLAMA && held.item == 170)
            || (s->type[slot] != EW_TYPE_LLAMA
                && (held.item == 396 || held.item == 322)))
            && (m->horse_status[slot] & GM_HORSE_TAME)
            && m->growing_age[slot] == 0 && m->sheep_in_love[slot] <= 0) {
        m->sheep_in_love[slot] = 600;
        m->sheep_bred_by_player[slot] = 1;
        handled = 1;
    }
    if (temper > 0 && (handled
            || !(m->horse_status[slot] & GM_HORSE_TAME))
            && m->horse_temper[slot]
                < (s->type[slot] == EW_TYPE_LLAMA ? 30 : 100)) {
        m->horse_temper[slot] += temper;
        int max_temper = s->type[slot] == EW_TYPE_LLAMA ? 30 : 100;
        if (m->horse_temper[slot] > max_temper)
            m->horse_temper[slot] = max_temper;
        handled = 1;
    }
    if (!handled) return 0;
    next_store(m)->health[slot] = s->health[slot];
    horse_open_mouth(m, slot);
    if (s->type[slot] == EW_TYPE_LLAMA) {
        JavaRandom *random = &m->entity_random[slot].random;
        float pitch = 1.0F
            + (jrand_float(random) - jrand_float(random)) * 0.2F;
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot], GM_MOB_SOUND_LLAMA_EAT,
            s->x[slot], s->y[slot], s->z[slot], 1.0F, pitch);
    }
    if (!creative) (void)isr_decr_stack_size(inventory, hand_slot, 1);
    return 1;
}

int gm_mobs_horse_mount(GmMobLive *m, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || !gm_mobs_horse_type(s->type[slot])
            || m->growing_age[slot] < 0 || m->horse_ride_eid >= 0
            || ((s->type[slot] == EW_TYPE_SKELETON_HORSE
                    || s->type[slot] == EW_TYPE_ZOMBIE_HORSE)
                && !(m->horse_status[slot] & GM_HORSE_TAME)))
        return 0;
    m->boat_ride_eid = -1;
    m->pig_ride_eid = -1;
    m->horse_ride_eid = eid;
    m->horse_status[slot] &= (unsigned char)~(
        GM_HORSE_EATING | GM_HORSE_REARING);
    return 1;
}

void gm_mobs_set_represented_player_uuid(
        GmMobLive *m, uint64_t uuid_most, uint64_t uuid_least) {
    if (!m) return;
    m->represented_player_uuid_most = uuid_most;
    m->represented_player_uuid_least = uuid_least;
}

void gm_mobs_set_represented_player_primary_hand(
        GmMobLive *m, int primary_right) {
    if (!m || (primary_right != 0 && primary_right != 1)) return;
    m->represented_player_primary_right = (unsigned char)primary_right;
}

int gm_mobs_restore_horse_owner(
        GmMobLive *m, int eid, int present,
        uint64_t uuid_most, uint64_t uuid_least) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || !gm_mobs_horse_type(s->type[slot])
            || (present != 0 && present != 1))
        return 0;
    m->horse_owner_present[slot] = (unsigned char)present;
    m->horse_owner_uuid_most[slot] = present ? uuid_most : 0;
    m->horse_owner_uuid_least[slot] = present ? uuid_least : 0;
    return 1;
}

int gm_mobs_horse_crazy_attempt(GmMobLive *m, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    JavaRandom *random;
    int sound;
    float first, second, pitch;
    if (slot <= 0 || !s || m->horse_ride_eid != eid
            || (s->type[slot] != EW_TYPE_HORSE
                && s->type[slot] != EW_TYPE_DONKEY
                && s->type[slot] != EW_TYPE_MULE
                && s->type[slot] != EW_TYPE_LLAMA)
            || (m->horse_status[slot] & GM_HORSE_TAME))
        return -1;
    random = &m->entity_random[slot].random;
    if (jrand_int_bound(random, 50) != 0)
        return GM_HORSE_TAME_NO_TRIGGER;
    if (jrand_int_bound(random, 100) < m->horse_temper[slot]) {
        m->horse_owner_present[slot] = 1;
        m->horse_owner_uuid_most[slot] =
            m->represented_player_uuid_most;
        m->horse_owner_uuid_least[slot] =
            m->represented_player_uuid_least;
        m->horse_status[slot] |= GM_HORSE_TAME;
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 7,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
        return GM_HORSE_TAME_SUCCEEDED;
    }
    m->horse_temper[slot] += 5;
    int max_temper = s->type[slot] == EW_TYPE_LLAMA ? 30 : 100;
    if (m->horse_temper[slot] > max_temper)
        m->horse_temper[slot] = max_temper;
    /* Vanilla removes the passenger before makeMad(). Consequently
     * setRearing's isBeingRidden guard is false on this boundary. */
    m->horse_ride_eid = -1;
    sound = s->type[slot] == EW_TYPE_HORSE
        ? GM_MOB_SOUND_HORSE_ANGRY
        : s->type[slot] == EW_TYPE_LLAMA
        ? GM_MOB_SOUND_LLAMA_ANGRY : GM_MOB_SOUND_DONKEY_ANGRY;
    first = jrand_float(random);
    second = jrand_float(random);
    pitch = 1.0F + (first - second) * 0.2F;
    mob_event_append(
        m, GM_MOB_EVENT_SOUND, s->id[slot], sound,
        s->x[slot], s->y[slot], s->z[slot], 0.8F, pitch);
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 6,
        s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    return GM_HORSE_TAME_FAILED;
}

static void horse_dismount_player(
        GmWorld *world, const struct Chunk *window,
        const EwStore *s, const McSinTable *sin_table, int slot,
        PsvPlayer *player, int primary_right, int ox, int oz);

void gm_mobs_horse_dismount(GmMobLive *m) {
    if (m) m->horse_ride_eid = -1;
}

void gm_mobs_horse_dismount_explicit(
        GmMobLive *m, GmWorld *world, const struct Chunk *window,
        const struct McSinTable *sin_table_, struct PsvPlayer *player_,
        int ox, int oz) {
    gm_mobs_horse_dismount_explicit_side(
        m, world, window, sin_table_, player_, 1, ox, oz);
}

void gm_mobs_horse_dismount_explicit_side(
        GmMobLive *m, GmWorld *world, const struct Chunk *window,
        const struct McSinTable *sin_table_, struct PsvPlayer *player_,
        int primary_right, int ox, int oz) {
    PsvPlayer *player = (PsvPlayer *)player_;
    const McSinTable *sin_table = (const McSinTable *)sin_table_;
    EwStore *s;
    int slot;
    if (!m || !world || !sin_table || !player
            || (primary_right != 0 && primary_right != 1)
            || !gm_mobs_horse_riding(m, NULL)) return;
    slot = mob_slot_by_eid(m, m->horse_ride_eid);
    s = now_store(m);
    m->horse_ride_eid = -1;
    horse_dismount_player(world, window, s, sin_table, slot,
                          player, primary_right, ox, oz);
}

int gm_mobs_horse_riding(const GmMobLive *m, int *eid) {
    const EwStore *s;
    int slot;
    if (!m || (slot = mob_slot_by_eid(m, m->horse_ride_eid)) <= 0)
        return 0;
    s = const_store(m);
    if (!s->alive[slot] || !gm_mobs_horse_type(s->type[slot])) return 0;
    if (eid) *eid = m->horse_ride_eid;
    return 1;
}

int gm_mobs_horse_set_jump_power(GmMobLive *m, int charge) {
    int slot;
    if (!m || (slot = mob_slot_by_eid(m, m->horse_ride_eid)) <= 0
            || !(m->horse_status[slot] & GM_HORSE_SADDLED))
        return 0;
    if (charge < 0) charge = 0;
    m->horse_allow_stand_sliding[slot] = 1;
    m->horse_jump_rearing_counter[slot] = 1;
    m->horse_status[slot] &= (unsigned char)~GM_HORSE_EATING;
    m->horse_status[slot] |= GM_HORSE_REARING;
    m->horse_jump_power[slot] = charge >= 90 ? 1.0F
        : 0.4F + 0.4F * (float)charge / 90.0F;
    return 1;
}

int gm_mobs_horse_set_trap(
        GmMobLive *m, int eid, int trap, int trap_time) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_SKELETON_HORSE
            || (trap != 0 && trap != 1) || trap_time < 0)
        return 0;
    m->horse_trap[slot] = (unsigned char)trap;
    m->horse_trap_time[slot] = trap_time;
    return 1;
}

static void skeleton_trap_next_uuid(
        uint64_t *seed48, int64_t *most, int64_t *least) {
    JavaRandom random;
    uint64_t raw_most, raw_least;
    jrand_set_seed48(&random, *seed48);
    raw_most = (uint64_t)jrand_long(&random);
    raw_least = (uint64_t)jrand_long(&random);
    *seed48 = random.seed;
    if (most)
        *most = (int64_t)((raw_most & UINT64_C(0xffffffffffff0fff))
            | UINT64_C(0x0000000000004000));
    if (least)
        *least = (int64_t)((raw_least & UINT64_C(0x3fffffffffffffff))
            | UINT64_C(0x8000000000000000));
}

static void skeleton_trap_construct_entity(
        JavaGaussianRandom *random, uint64_t *entity_seed48,
        uint64_t *server_uuid_seed48, uint64_t *math_seed48,
        int64_t *uuid_most, int64_t *uuid_least, float *yaw) {
    JavaRandom generator, math_random;
    jrand_set_seed48(&generator, *entity_seed48);
    jrand_gaussian_set(random, jrand_long(&generator));
    *entity_seed48 = generator.seed;
    skeleton_trap_next_uuid(
        server_uuid_seed48, uuid_most, uuid_least);

    /* EntityLivingBase's three process-global Math.random calls. */
    jrand_set_seed48(&math_random, *math_seed48);
    (void)jrand_double(&math_random);
    (void)jrand_double(&math_random);
    if (yaw)
        *yaw = (float)(jrand_double(&math_random)
            * 6.283185307179586476925286766559);
    else
        (void)jrand_double(&math_random);
    *math_seed48 = math_random.seed;
}

static int skeleton_trap_initial_spawn(
        GmMobLive *m, int slot, uint64_t *server_uuid_seed48,
        int horse) {
    JavaGaussianRandom *random = &m->entity_random[slot];
    m->entity_random_follow_range_bonus[slot] =
        jrand_gaussian_next(random) * 0.05;
    /* AttributeModifier(String, ...) constructs an unretained random UUID. */
    skeleton_trap_next_uuid(server_uuid_seed48, NULL, NULL);
    m->skeleton_trap_left_handed[slot] =
        (unsigned char)(jrand_float(&random->random) < 0.05F);
    if (horse) {
        return jrand_int_bound(&random->random, 5) == 0;
    } else {
        /* EntityLiving equipment gate, held-item enchant gate, then
         * EntitySkeleton's pickup-loot gate at clamped difficulty zero. */
        (void)jrand_float(&random->random);
        m->skeleton_trap_mainhand[slot] = ic_mk(261, 1, 0);
        (void)jrand_float(&random->random);
        m->skeleton_trap_can_pick_up_loot[slot] =
            (unsigned char)(jrand_float(&random->random) < 0.0F);
    }
    return 0;
}

static void skeleton_trap_enchant_stack(
        JavaRandom *random, ICStack *stack, int item_kind, int level) {
    EtData enchants[IC_MAX_ENCHANTS];
    int count = et_build_list(
        random, item_kind, level, 0, enchants, IC_MAX_ENCHANTS);
    stack->n_enchants = count;
    for (int i = 0; i < count; ++i) {
        stack->enchants[i].id = (i16)enchants[i].id;
        stack->enchants[i].level = (i16)enchants[i].level;
    }
    for (int i = count; i < IC_MAX_ENCHANTS; ++i) {
        stack->enchants[i].id = 0;
        stack->enchants[i].level = 0;
    }
}

static int skeleton_trap_spawn_living(
        GmMobLive *m, EwStore *s, int type, int eid,
        double x, double y, double z,
        uint64_t *entity_seed48, uint64_t *server_uuid_seed48,
        uint64_t *math_seed48) {
    int is_cold = 0;
    int slot = living_spawn_slot(
        m, s, type, eid, x, y, z, max_health(type, 1), &is_cold);
    float yaw = 0.0F;
    int64_t uuid_most, uuid_least;
    if (slot < 0) return -1;
    m->entity_dimension[slot] = (signed char)m->active_dimension;
    m->size[slot] = 1;
    reset_slot_state_s(m, s, slot);
    /* Fresh Entity instances begin airborne. ew_store_spawn's grounded
     * default is for ordinary simulator placement, not constructor-exact
     * entities appended during a live World tick. */
    s->on_ground[slot] = 0;
    skeleton_trap_construct_entity(
        &m->entity_random[slot], entity_seed48,
        server_uuid_seed48, math_seed48,
        &uuid_most, &uuid_least, &yaw);
    m->entity_uuid_present[slot] = 1;
    m->entity_uuid_most[slot] = uuid_most;
    m->entity_uuid_least[slot] = uuid_least;
    s->yaw[slot] = yaw;
    if (type == EW_TYPE_SKELETON_HORSE)
        horse_init_attributes(m, s, slot);
    int spawned_child = skeleton_trap_initial_spawn(
        m, slot, server_uuid_seed48,
        type == EW_TYPE_SKELETON_HORSE);
    m->persistence_required[slot] = 1;
    m->entity_hurt_resistant[slot] = 60;
    if (type == EW_TYPE_SKELETON_HORSE) {
        if (spawned_child) {
            /* AbstractHorse.onInitialSpawn can make the new horse a baby.
             * EntityAISkeletonRiders then calls setPosition while it is
             * half-size and immediately setGrowingAge(0). Entity.setSize
             * grows from the old min corner on firstUpdate, so position and
             * AABB center differ by one quarter-width until the first move. */
            float width = 1.3964844F;
            float height = 1.6F;
            float child_half = width * 0.5F / 2.0F;
            m->entity_box_min_x[slot] = x - (double)child_half;
            m->entity_box_min_y[slot] = y;
            m->entity_box_min_z[slot] = z - (double)child_half;
            m->entity_box_max_x[slot] =
                m->entity_box_min_x[slot] + (double)width;
            m->entity_box_max_y[slot] = y + (double)height;
            m->entity_box_max_z[slot] =
                m->entity_box_min_z[slot] + (double)width;
            m->entity_box_valid[slot] = 1;
        }
        m->horse_status[slot] |= GM_HORSE_TAME;
        m->growing_age[slot] = 0;
    } else {
        m->skeleton_trap_first_tick[slot] = 1;
        m->passive_idle_time[slot] = -1;
        m->passive_eat_time[slot] = -1; /* bow strafingTime */
        s->attack_time[slot] = -1; /* EntityAIAttackRangedBow.attackTime */
        int level;
        m->skeleton_trap_head[slot] = ic_mk(306, 1, 0);
        level = (int)(5.0F + 0.0F * (float)jrand_int_bound(
            &m->entity_random[slot].random, 18));
        skeleton_trap_enchant_stack(
            &m->entity_random[slot].random,
            &m->skeleton_trap_mainhand[slot],
            ET_ITEM_GENERIC(1, ET_CAP_BOW), level);
        level = (int)(5.0F + 0.0F * (float)jrand_int_bound(
            &m->entity_random[slot].random, 18));
        skeleton_trap_enchant_stack(
            &m->entity_random[slot].random,
            &m->skeleton_trap_head[slot],
            ET_ITEM_GENERIC(9, ET_CAP_HEAD), level);
    }
    return living_spawn_finish(
        m, s, slot, is_cold, s == now_store(m));
}

static int skeleton_trap_activate_store(
        GmMobLive *m, EwStore *s, int horse_eid,
        float clamped_difficulty,
        uint64_t *entity_seed_generator_seed48,
        uint64_t *server_uuid_random_seed48,
        uint64_t *math_random_seed48, int *next_entity_id) {
    int original;
    int horse_slots[GM_SKELETON_TRAP_PAIRS];
    int rider_slots[GM_SKELETON_TRAP_PAIRS];
    uint64_t entity_cursor, uuid_cursor, math_cursor;
    int next_id;
    double x, y, z;
    JavaRandom generator;
    JavaGaussianRandom lightning_random;
    int64_t ignored_most, ignored_least;
    if (!m || !s || !entity_seed_generator_seed48
            || !server_uuid_random_seed48 || !math_random_seed48
            || !next_entity_id || *next_entity_id <= 0
            || *next_entity_id > INT_MAX - 7
            || clamped_difficulty != 0.0F
            || m->skeleton_trap_lightning_pending)
        return 0;
    original = mob_slot_by_eid(m, horse_eid);
    if (original <= 0 || s->type[original] != EW_TYPE_SKELETON_HORSE
            || !m->horse_trap[original])
        return 0;
    loaded_order_compact(m);
    if (!gm_mobs_living_cold_reserve(m, m->living_cold_count + 7)
            || !loaded_order_reserve(m, m->loaded_order_count + 7))
        return 0;

    entity_cursor = *entity_seed_generator_seed48;
    uuid_cursor = *server_uuid_random_seed48;
    math_cursor = *math_random_seed48;
    next_id = *next_entity_id;
    x = s->x[original]; y = s->y[original]; z = s->z[original];

    /* EntityLightningBolt is a weather effect, so it consumes constructor
     * RNG and an entity ID value but never advances the loaded-entity ID. */
    jrand_set_seed48(&generator, entity_cursor);
    jrand_gaussian_set(&lightning_random, jrand_long(&generator));
    entity_cursor = generator.seed;
    skeleton_trap_next_uuid(
        &uuid_cursor, &ignored_most, &ignored_least);
    m->skeleton_trap_lightning_pending = 1;
    m->skeleton_trap_lightning_eid = next_id;
    m->skeleton_trap_lightning_bolt_vertex =
        jrand_long(&lightning_random.random);
    m->skeleton_trap_lightning_living_time =
        jrand_int_bound(&lightning_random.random, 3) + 1;
    m->skeleton_trap_lightning_random_seed48 =
        lightning_random.random.seed;
    m->skeleton_trap_lightning_x = x;
    m->skeleton_trap_lightning_y = y;
    m->skeleton_trap_lightning_z = z;

    m->horse_trap[original] = 0;
    m->horse_status[original] |= GM_HORSE_TAME;
    m->growing_age[original] = 0;
    horse_slots[0] = original;
    rider_slots[0] = skeleton_trap_spawn_living(
        m, s, EW_TYPE_SKELETON, next_id++, x, y, z,
        &entity_cursor, &uuid_cursor, &math_cursor);
    if (rider_slots[0] < 0) return 0;
    m->skeleton_trap_vehicle_eid[rider_slots[0]] = horse_eid;
    m->skeleton_trap_rider_eid[original] = s->id[rider_slots[0]];

    for (int pair = 1; pair < GM_SKELETON_TRAP_PAIRS; ++pair) {
        int horse_eid = next_id;
        horse_slots[pair] = skeleton_trap_spawn_living(
            m, s, EW_TYPE_SKELETON_HORSE, next_id++, x, y, z,
            &entity_cursor, &uuid_cursor, &math_cursor);
        int rider_eid = next_id;
        rider_slots[pair] = skeleton_trap_spawn_living(
            m, s, EW_TYPE_SKELETON, next_id++, x, y, z,
            &entity_cursor, &uuid_cursor, &math_cursor);
        if (horse_slots[pair] < 0 || rider_slots[pair] < 0) return 0;
        m->skeleton_trap_vehicle_eid[rider_slots[pair]] =
            horse_eid;
        if (horse_slots[pair] >= EW_SPAWN_LIMIT)
            horse_slots[pair] = mob_slot_by_eid(m, horse_eid);
        if (horse_slots[pair] < 0) return 0;
        m->skeleton_trap_rider_eid[horse_slots[pair]] = rider_eid;
        s->vx[horse_slots[pair]] +=
            jrand_gaussian_next(&m->entity_random[original]) * 0.5;
        s->vz[horse_slots[pair]] +=
            jrand_gaussian_next(&m->entity_random[original]) * 0.5;
    }

    *entity_seed_generator_seed48 = entity_cursor;
    *server_uuid_random_seed48 = uuid_cursor;
    *math_random_seed48 = math_cursor;
    *next_entity_id = next_id;
    if (m->next_id < next_id) m->next_id = next_id;
    if (s == now_store(m)) {
        ew_store_copy_slot(next_store(m), s, original);
        for (int pair = 0; pair < GM_SKELETON_TRAP_PAIRS; ++pair) {
            if (horse_slots[pair] != original
                    && horse_slots[pair] < EW_SPAWN_LIMIT)
                ew_store_copy_slot(next_store(m), s, horse_slots[pair]);
            if (rider_slots[pair] < EW_SPAWN_LIMIT)
                ew_store_copy_slot(next_store(m), s, rider_slots[pair]);
        }
    } else {
        for (int pair = 0; pair < GM_SKELETON_TRAP_PAIRS; ++pair) {
            if (horse_slots[pair] != original
                    && horse_slots[pair] < EW_SPAWN_LIMIT)
                ew_store_copy_slot(now_store(m), s, horse_slots[pair]);
            if (rider_slots[pair] < EW_SPAWN_LIMIT)
                ew_store_copy_slot(now_store(m), s, rider_slots[pair]);
        }
    }
    return 7;
}

int gm_mobs_skeleton_trap_activate(
        GmMobLive *m, int horse_eid, float clamped_difficulty,
        uint64_t *entity_seed_generator_seed48,
        uint64_t *server_uuid_random_seed48,
        uint64_t *math_random_seed48, int *next_entity_id) {
    return skeleton_trap_activate_store(
        m, m ? now_store(m) : NULL, horse_eid, clamped_difficulty,
        entity_seed_generator_seed48, server_uuid_random_seed48,
        math_random_seed48, next_entity_id);
}

int gm_mobs_skeleton_trap_entity_state(
        const GmMobLive *m, int eid, GmSkeletonTrapEntityState *out) {
    const EwStore *s;
    int slot;
    if (!m || !out || (slot = mob_slot_by_eid(m, eid)) <= 0)
        return 0;
    s = const_store(m);
    memset(out, 0, sizeof *out);
    out->eid = eid;
    out->type = s->type[slot];
    out->persistent = m->persistence_required[slot];
    out->hurt_resistant_time = m->entity_hurt_resistant[slot];
    out->vehicle_eid = m->skeleton_trap_vehicle_eid[slot];
    out->rider_eid = m->skeleton_trap_rider_eid[slot];
    out->left_handed = m->skeleton_trap_left_handed[slot];
    out->can_pick_up_loot = m->skeleton_trap_can_pick_up_loot[slot];
    out->uuid_present = m->entity_uuid_present[slot];
    out->uuid_most = m->entity_uuid_most[slot];
    out->uuid_least = m->entity_uuid_least[slot];
    out->x = s->x[slot]; out->y = s->y[slot]; out->z = s->z[slot];
    out->vx = s->vx[slot]; out->vy = s->vy[slot]; out->vz = s->vz[slot];
    out->entity_seed48 = m->entity_random[slot].random.seed;
    out->entity_have_gaussian =
        m->entity_random[slot].have_next_next_gaussian;
    out->entity_gaussian = m->entity_random[slot].next_next_gaussian;
    out->mainhand = m->skeleton_trap_mainhand[slot];
    out->head = m->skeleton_trap_head[slot];
    return 1;
}

int gm_mobs_take_skeleton_trap_lightning(
        GmMobLive *m, GmSkeletonTrapLightning *out) {
    if (!m || !out || !m->skeleton_trap_lightning_pending)
        return 0;
    *out = (GmSkeletonTrapLightning){
        m->skeleton_trap_lightning_eid,
        m->skeleton_trap_lightning_living_time,
        m->skeleton_trap_lightning_bolt_vertex,
        m->skeleton_trap_lightning_random_seed48,
        m->skeleton_trap_lightning_x,
        m->skeleton_trap_lightning_y,
        m->skeleton_trap_lightning_z,
    };
    m->skeleton_trap_lightning_pending = 0;
    return 1;
}

int gm_mobs_take_skeleton_trap_shot(
        GmMobLive *m, GmSkeletonTrapShot *out) {
    int slot;
    if (!m || !out || !m->skeleton_trap_shot_count)
        return 0;
    slot = m->skeleton_trap_shot_head;
    *out = m->skeleton_trap_shots[slot];
    m->skeleton_trap_shot_head =
        (slot + 1) % m->skeleton_trap_shots_cap;
    --m->skeleton_trap_shot_count;
    return 1;
}

typedef struct {
    int type;
    int variant;
    double max_health;
    double jump_strength;
    double movement_speed;
} GmHorseChildGenetics;

typedef struct {
    GmHorseChildGenetics horse;
    int strength;
} GmLlamaChildGenetics;

static int horse_mating_type(int type) {
    return type == EW_TYPE_HORSE || type == EW_TYPE_DONKEY;
}

static int horse_mating_pair_types(int first, int second) {
    return (horse_mating_type(first) && horse_mating_type(second))
        || (first == EW_TYPE_LLAMA && second == EW_TYPE_LLAMA);
}

static void horse_compute_offspring_attributes(
        GmMobLive *m, int first, int second,
        GmHorseChildGenetics *out) {
    JavaRandom *random = &m->entity_random[first].random;
    out->max_health = (m->horse_max_health[first]
        + m->horse_max_health[second]
        + 15.0 + jrand_int_bound(random, 8)
        + jrand_int_bound(random, 9)) / 3.0;
    out->jump_strength = (m->horse_jump_strength[first]
        + m->horse_jump_strength[second]
        + 0.4000000059604645 + jrand_double(random) * 0.2
        + jrand_double(random) * 0.2
        + jrand_double(random) * 0.2) / 3.0;
    out->movement_speed = (m->horse_movement_speed[first]
        + m->horse_movement_speed[second]
        + (0.44999998807907104
            + jrand_double(random) * 0.3
            + jrand_double(random) * 0.3
            + jrand_double(random) * 0.3) * 0.25) / 3.0;
}

static int horse_compute_child_genetics(
        GmMobLive *m, const EwStore *s, int first, int second,
        GmHorseChildGenetics *out) {
    JavaRandom *random;
    if (!m || !s || !out || first <= 0 || second <= 0
            || first >= EW_MAX_ENTITIES || second >= EW_MAX_ENTITIES
            || !horse_mating_type(s->type[first])
            || !horse_mating_type(s->type[second]))
        return 0;
    memset(out, 0, sizeof *out);
    out->type = s->type[first] == s->type[second]
        ? s->type[first] : EW_TYPE_MULE;
    random = &m->entity_random[first].random;
    if (out->type == EW_TYPE_HORSE) {
        int coat_roll = jrand_int_bound(random, 9);
        int variant = coat_roll < 4
            ? m->horse_variant[first] & 255
            : coat_roll < 8 ? m->horse_variant[second] & 255
            : jrand_int_bound(random, 7);
        int marking_roll = jrand_int_bound(random, 5);
        variant |= marking_roll < 2
            ? m->horse_variant[first] & 65280
            : marking_roll < 4 ? m->horse_variant[second] & 65280
            : (jrand_int_bound(random, 5) << 8) & 65280;
        out->variant = variant;
    }
    horse_compute_offspring_attributes(m, first, second, out);
    return 1;
}

static int llama_compute_child_genetics(
        GmMobLive *m, const EwStore *s, int first, int second,
        GmLlamaChildGenetics *out) {
    JavaRandom *random;
    int strength;
    if (!m || !s || !out || first <= 0 || second <= 0
            || first >= EW_MAX_ENTITIES || second >= EW_MAX_ENTITIES
            || s->type[first] != EW_TYPE_LLAMA
            || s->type[second] != EW_TYPE_LLAMA)
        return 0;
    memset(out, 0, sizeof *out);
    out->horse.type = EW_TYPE_LLAMA;
    horse_compute_offspring_attributes(m, first, second, &out->horse);
    random = &m->entity_random[first].random;
    strength = jrand_int_bound(
        random, m->llama_strength[first] > m->llama_strength[second]
            ? m->llama_strength[first] : m->llama_strength[second]) + 1;
    if (jrand_float(random) < 0.03F) ++strength;
    if (strength > 5) strength = 5;
    out->strength = strength;
    out->horse.variant = jrand_next(random, 1) != 0
        ? m->llama_variant[first] : m->llama_variant[second];
    return 1;
}

static void horse_apply_child_genetics(
        GmMobLive *m, EwStore *s, int child,
        const GmHorseChildGenetics *genetics) {
    m->horse_variant[child] = genetics->variant;
    m->horse_max_health[child] = genetics->max_health;
    m->horse_jump_strength[child] = genetics->jump_strength;
    m->horse_movement_speed[child] = genetics->movement_speed;
    s->health[child] = (float)genetics->max_health;
}

int gm_mobs_horse_create_child(
        GmMobLive *m, int first_eid, int second_eid, int child_eid,
        GmHorseState *child_state) {
    int first = mob_slot_by_eid(m, first_eid);
    int second = mob_slot_by_eid(m, second_eid);
    EwStore *s = m ? now_store(m) : NULL;
    int first_type, second_type, child, child_is_cold = 0;
    GmHorseChildGenetics genetics;
    if (first <= 0 || second <= 0 || first == second || !s
            || child_eid <= 0 || !s->alive[first] || !s->alive[second]
            || !gm_mobs_horse_type(s->type[first])
            || !gm_mobs_horse_type(s->type[second]))
        return -1;
    first_type = s->type[first];
    second_type = s->type[second];
    if (!((first_type == EW_TYPE_HORSE || first_type == EW_TYPE_DONKEY)
            && (second_type == EW_TYPE_HORSE
                || second_type == EW_TYPE_DONKEY))
            || !(m->horse_status[first] & GM_HORSE_TAME)
            || !(m->horse_status[second] & GM_HORSE_TAME)
            || m->growing_age[first] != 0 || m->growing_age[second] != 0
            || m->sheep_in_love[first] <= 0 || m->sheep_in_love[second] <= 0
            || s->health[first] < (float)m->horse_max_health[first]
            || s->health[second] < (float)m->horse_max_health[second]
            || m->horse_ride_eid == first_eid
            || m->horse_ride_eid == second_eid)
        return -1;
    if (!horse_compute_child_genetics(m, s, first, second, &genetics))
        return -1;
    child = living_spawn_slot(
        m, s, genetics.type, child_eid,
        s->x[first], s->y[first], s->z[first],
        max_health(genetics.type, 1), &child_is_cold);
    if (child < 0) return -1;
    m->entity_dimension[child] = m->entity_dimension[first];
    m->size[child] = 1;
    reset_slot_state_s(m, s, child);
    s->on_ground[child] = 0;
    s->yaw[child] = 0.0F;
    m->growing_age[child] = -24000;
    horse_apply_child_genetics(m, s, child, &genetics);
    m->growing_age[first] = 6000;
    m->growing_age[second] = 6000;
    m->sheep_in_love[first] = 0;
    m->sheep_in_love[second] = 0;
    m->sheep_bred_by_player[first] = 0;
    m->sheep_bred_by_player[second] = 0;
    if (m->next_id <= child_eid) m->next_id = child_eid + 1;
    child = living_spawn_finish(m, s, child, child_is_cold, 1);
    if (child < 0) return -1;
    if (child_state)
        (void)gm_mobs_get_horse_state(m, child_eid, child_state);
    return child;
}

int gm_mobs_llama_create_child(
        GmMobLive *m, int first_eid, int second_eid, int child_eid,
        GmLlamaState *child_state) {
    int first = mob_slot_by_eid(m, first_eid);
    int second = mob_slot_by_eid(m, second_eid);
    EwStore *s = m ? now_store(m) : NULL;
    GmLlamaChildGenetics genetics;
    int child, child_is_cold = 0;
    if (first <= 0 || second <= 0 || first == second || !s
            || child_eid <= 0 || !s->alive[first] || !s->alive[second]
            || s->type[first] != EW_TYPE_LLAMA
            || s->type[second] != EW_TYPE_LLAMA
            || !(m->horse_status[first] & GM_HORSE_TAME)
            || !(m->horse_status[second] & GM_HORSE_TAME)
            || m->growing_age[first] != 0 || m->growing_age[second] != 0
            || m->sheep_in_love[first] <= 0 || m->sheep_in_love[second] <= 0
            || s->health[first] < (float)m->horse_max_health[first]
            || s->health[second] < (float)m->horse_max_health[second]
            || m->horse_ride_eid == first_eid
            || m->horse_ride_eid == second_eid)
        return -1;
    if (!llama_compute_child_genetics(m, s, first, second, &genetics))
        return -1;
    child = living_spawn_slot(
        m, s, EW_TYPE_LLAMA, child_eid,
        s->x[first], s->y[first], s->z[first],
        max_health(EW_TYPE_LLAMA, 1), &child_is_cold);
    if (child < 0) return -1;
    m->entity_dimension[child] = m->entity_dimension[first];
    m->size[child] = 1;
    reset_slot_state_s(m, s, child);
    s->on_ground[child] = 0;
    s->yaw[child] = 0.0F;
    m->growing_age[child] = -24000;
    horse_apply_child_genetics(m, s, child, &genetics.horse);
    m->llama_strength[child] = (unsigned char)genetics.strength;
    m->llama_variant[child] = (unsigned char)genetics.horse.variant;
    m->growing_age[first] = 6000;
    m->growing_age[second] = 6000;
    m->sheep_in_love[first] = 0;
    m->sheep_in_love[second] = 0;
    m->sheep_bred_by_player[first] = 0;
    m->sheep_bred_by_player[second] = 0;
    if (m->next_id <= child_eid) m->next_id = child_eid + 1;
    child = living_spawn_finish(m, s, child, child_is_cold, 1);
    if (child < 0) return -1;
    if (child_state)
        (void)gm_mobs_get_llama_state(m, child_eid, child_state);
    return child;
}

int gm_mobs_place_boat_type(
        GmMobLive *m, double x, double y, double z, float yaw,
        int boat_variant) {
    if (boat_variant < 0 || boat_variant > 5) return -1;
    int slot = gm_mobs_spawn(m, EW_TYPE_BOAT, x, y, z);
    if (slot < 0) return -1;
    now_store(m)->yaw[slot] = yaw;
    next_store(m)->yaw[slot] = yaw;
    if (slot >= 0 && slot < EW_MAX_ENTITIES) {
        m->boat_delta_rotation[slot] = 0.0f;
        m->boat_glide[slot] = 0.0f;
        m->boat_variant[slot] = (unsigned char)boat_variant;
    }
    return slot;
}

int gm_mobs_place_boat(GmMobLive *m, double x, double y, double z, float yaw) {
    return gm_mobs_place_boat_type(m, x, y, z, yaw, 0);
}

int gm_mobs_spawn_boat_exact(GmMobLive *m, int eid,
                             double x, double y, double z, float yaw) {
    if (!m || eid <= 0 || !isfinite(x) || !isfinite(y) || !isfinite(z)
            || !isfinite(yaw))
        return -1;
    EwStore *s = now_store(m);
    int is_cold = 0;
    int slot = living_spawn_slot(
        m, s, EW_TYPE_BOAT, eid, x, y, z, 40.0F, &is_cold);
    if (slot < 0) return -1;
    s->yaw[slot] = yaw;
    m->entity_dimension[slot] = (signed char)m->active_dimension;
    reset_slot_state_s(m, s, slot);
    m->controlled_no_ai[slot] = 1;
    m->controlled_block_collisions[slot] = 1;
    if (m->next_id <= eid) m->next_id = eid + 1;
    return living_spawn_finish(m, s, slot, is_cold, 1);
}

int gm_mobs_spawn_boat_type_exact(GmMobLive *m, int eid,
                                  double x, double y, double z, float yaw,
                                  int boat_variant) {
    int slot;
    if (boat_variant < 0 || boat_variant > 5) return -1;
    slot = gm_mobs_spawn_boat_exact(m, eid, x, y, z, yaw);
    if (slot >= 0) m->boat_variant[slot] = (unsigned char)boat_variant;
    return slot;
}

int gm_mobs_boat_riding(const GmMobLive *m) {
    int slot;
    const EwStore *store;
    if (!m || (slot = mob_slot_by_eid(m, m->boat_ride_eid)) <= 0)
        return 0;
    store = const_store(m);
    return store->alive[slot] && store->type[slot] == EW_TYPE_BOAT;
}

int gm_mobs_boat_set_position_rotation_direct(
        GmMobLive *m, int eid, double x, double y, double z,
        float yaw, float pitch) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *state = m ? now_store(m) : NULL;
    if (!m || slot <= 0 || !state->alive[slot]
            || state->type[slot] != EW_TYPE_BOAT)
        return 0;
    m->boat_lerp_x[slot] = x;
    m->boat_lerp_y[slot] = y;
    m->boat_lerp_z[slot] = z;
    m->boat_lerp_yaw[slot] = (double)yaw;
    m->boat_lerp_pitch[slot] = (double)pitch;
    m->boat_lerp_steps[slot] = 10;
    m->boat_client_remote[slot] = 1;
    ew_store_copy(next_store(m), state);
    return 1;
}

int gm_mobs_boat_reconstruct_portal(
        GmMobLive *m, int slot, int new_eid, int target_dimension,
        double x, double y, double z, double vx, double vy, double vz,
        float yaw, uint64_t constructor_seed48) {
    EwStore *now, *next;
    int variant;
    int64_t uuid_most, uuid_least;
    unsigned char uuid_present;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES || new_eid <= 0
            || (target_dimension != -1 && target_dimension != 0)
            || !isfinite(x) || !isfinite(y) || !isfinite(z)
            || !isfinite(vx) || !isfinite(vy) || !isfinite(vz)
            || !isfinite(yaw))
        return 0;
    now = now_store(m);
    next = next_store(m);
    if (!now->alive[slot] || now->type[slot] != EW_TYPE_BOAT)
        return 0;
    variant = m->boat_variant[slot];
    uuid_present = m->entity_uuid_present[slot];
    uuid_most = m->entity_uuid_most[slot];
    uuid_least = m->entity_uuid_least[slot];
    loaded_invalidate_living(m, slot);
    now->id[slot] = new_eid;
    now->x[slot] = x; now->y[slot] = y; now->z[slot] = z;
    now->vx[slot] = vx; now->vy[slot] = vy; now->vz[slot] = vz;
    now->yaw[slot] = yaw;
    now->on_ground[slot] = 0;
    reset_slot_state_s(m, now, slot);
    m->boat_variant[slot] = (unsigned char)variant;
    m->entity_dimension[slot] = (signed char)target_dimension;
    m->entity_uuid_present[slot] = uuid_present;
    m->entity_uuid_most[slot] = uuid_most;
    m->entity_uuid_least[slot] = uuid_least;
    m->entity_portal_cooldown[slot] = 300;
    jrand_gaussian_set(&m->entity_random[slot],
        (int64_t)constructor_seed48);
    m->entity_server_random[slot] = m->entity_random[slot];
    ew_store_copy_slot(next, now, slot);
    (void)loaded_append_living(m, now, slot);
    if (m->next_id <= new_eid) m->next_id = new_eid + 1;
    return 1;
}

int gm_mobs_boat_mount_living(
        GmMobLive *m, int boat_eid, int living_eid) {
    int boat = mob_slot_by_eid(m, boat_eid);
    int living = mob_slot_by_eid(m, living_eid);
    EwStore *state = m ? now_store(m) : NULL;
    if (!m || boat <= 0 || living <= 0 || boat == living
            || !state->alive[boat] || state->type[boat] != EW_TYPE_BOAT
            || !state->alive[living] || !gm_living(state->type[living])
            || state->type[living] == EW_TYPE_BOAT
            || m->entity_vehicle_eid[living] > 0)
        return 0;
    int passenger = m->boat_passenger_eid[boat][0] == 0
            && m->boat_player_passenger_index[boat] != 0 ? 0
        : m->boat_passenger_eid[boat][1] == 0
            && m->boat_player_passenger_index[boat] != 1 ? 1 : -1;
    if (passenger < 0) return 0;
    m->boat_passenger_eid[boat][passenger] = living_eid;
    m->entity_vehicle_eid[living] = boat_eid;
    ew_store_copy(next_store(m), state);
    return 1;
}

int gm_mobs_boat_collide_nearby(GmMobLive *m, int boat_eid) {
    int boat = mob_slot_by_eid(m, boat_eid);
    EwStore *state = m ? now_store(m) : NULL;
    if (!m || boat <= 0 || !state->alive[boat]
            || state->type[boat] != EW_TYPE_BOAT)
        return 0;
    loaded_order_prepare(m);
    boat_collide_and_mount_nearby(
        m, state, boat, m->entity_dimension[boat]);
    ew_store_copy(next_store(m), state);
    return 1;
}

static void boat_remove_all_passengers(GmMobLive *m, int boat) {
    if (!m || boat <= 0 || boat >= EW_MAX_ENTITIES) return;
    EwStore *state = now_store(m);
    if (ride_is_slot(state, boat, m->boat_ride_eid))
        m->boat_ride_eid = -1;
    m->boat_player_passenger_index[boat] = -1;
    for (int passenger = 0; passenger < 2; ++passenger) {
        int living = mob_slot_by_eid(
            m, m->boat_passenger_eid[boat][passenger]);
        if (living > 0) m->entity_vehicle_eid[living] = -1;
        m->boat_passenger_eid[boat][passenger] = 0;
    }
}

static void boat_update_living_passengers(
        GmMobLive *m, EwStore *state, int boat,
        const McSinTable *sin_table) {
    int count = (m->boat_player_passenger_index[boat] >= 0)
        + (m->boat_passenger_eid[boat][0] != 0)
        + (m->boat_passenger_eid[boat][1] != 0);
    for (int passenger = 0; passenger < 2; ++passenger) {
        int eid = m->boat_passenger_eid[boat][passenger];
        if (eid <= 0) continue;
        int living = mob_slot_by_eid(m, eid);
        if (living <= 0 || !state->alive[living]
                || m->entity_vehicle_eid[living] != state->id[boat]) {
            m->boat_passenger_eid[boat][passenger] = 0;
            continue;
        }
        float offset = 0.0F;
        if (count > 1) offset = passenger == 0 ? 0.2F : -0.6F;
        if (gm_passive(state->type[living]))
            offset = (float)((double)offset + 0.2D);
        float angle = -state->yaw[boat] * 0.017453292F
            - ((float)MC_PI / 2.0F);
        state->x[living] = state->x[boat]
            + (double)offset * (double)mc_cos(sin_table, angle);
        state->y[living] = state->y[boat]
            + (double)(float)(-0.1D + 0.14D);
        state->z[living] = state->z[boat]
            - (double)offset * (double)mc_sin(sin_table, angle);
        state->yaw[living] += m->boat_delta_rotation[boat];
        m->passive_head_yaw[living] += m->boat_delta_rotation[boat];
        m->squid_render_yaw_offset[living] = state->yaw[boat];
        float relative = pai_wrap_degrees(
            state->yaw[living] - state->yaw[boat]);
        float clamped = relative;
        if (clamped > 105.0F) clamped = 105.0F;
        if (clamped < -105.0F) clamped = -105.0F;
        state->yaw[living] += clamped - relative;
        m->passive_head_yaw[living] = state->yaw[living];
        int animal_rotation = (eid & 1) == 0 ? 90 : 270;
        if (gm_passive(state->type[living]) && count > 1) {
            m->squid_render_yaw_offset[living] += (float)animal_rotation;
            m->passive_head_yaw[living] += (float)animal_rotation;
        }
    }
}

int gm_mobs_boat_update_passengers(
        GmMobLive *m, int boat_eid,
        const struct McSinTable *sin_table_) {
    int boat = mob_slot_by_eid(m, boat_eid);
    EwStore *state = m ? now_store(m) : NULL;
    if (!m || boat <= 0 || !state->alive[boat]
            || state->type[boat] != EW_TYPE_BOAT || !sin_table_)
        return 0;
    boat_update_living_passengers(
        m, state, boat, (const McSinTable *)sin_table_);
    ew_store_copy(next_store(m), state);
    return 1;
}

int gm_mobs_boat_mount(GmMobLive *m, struct PsvPlayer *player_, int ox, int oz) {
    if (!m || !player_) return 0;
    PsvPlayer *p = (PsvPlayer *)player_;
    if (m->boat_ride_eid >= 0) return 1;
    EwStore *s;
    double px = p->ent.posX + ox, py = p->ent.posY, pz = p->ent.posZ + oz;
    int best_eid = -1;
    double bd = 2.5 * 2.5;
    int cursor = 0;
    int i;
    while ((i = gm_mobs_living_next_slot(m, &cursor)) > 0) {
        s = now_store(m);
        if (!s->alive[i] || s->type[i] != EW_TYPE_BOAT) continue;
        if (m->entity_dimension[i] != m->active_dimension) continue;
        double dx = s->x[i] - px, dy = s->y[i] - py, dz = s->z[i] - pz;
        double d = dx * dx + dy * dy + dz * dz;
        if (d < bd) { bd = d; best_eid = s->id[i]; }
    }
    gm_mobs_living_cold_flush(m);
    int best = mob_slot_by_eid(m, best_eid);
    if (best < 0) return 0;
    s = now_store(m);
    int passenger = m->boat_passenger_eid[best][0] == 0 ? 0
        : m->boat_passenger_eid[best][1] == 0 ? 1 : -1;
    if (passenger < 0) return 0;
    m->boat_ride_eid = best_eid;
    m->boat_player_passenger_index[best] = (signed char)passenger;
    p->ent.posX = s->x[best] - ox;
    p->ent.posY = s->y[best] + 0.3;
    p->ent.posZ = s->z[best] - oz;
    p->ent.motionX = p->ent.motionY = p->ent.motionZ = 0.0;
    return 1;
}

void gm_mobs_boat_dismount(GmMobLive *m, struct PsvPlayer *player_, int ox, int oz) {
    if (!m || m->boat_ride_eid < 0) return;
    PsvPlayer *p = (PsvPlayer *)player_;
    EwStore *s = now_store(m);
    int i = mob_slot_by_eid(m, m->boat_ride_eid);
    s = now_store(m);
    if (i <= 0) {
        m->boat_ride_eid = -1;
        return;
    }
    if (p && s->alive[i] && s->type[i] == EW_TYPE_BOAT) {
        double yaw = s->yaw[i] * MC_PI / 180.0;
        p->ent.posX = s->x[i] - ox - sin(yaw) * 1.0;
        p->ent.posY = s->y[i] + 0.5;
        p->ent.posZ = s->z[i] - oz + cos(yaw) * 1.0;
    }
    m->boat_player_passenger_index[i] = -1;
    m->boat_ride_eid = -1;
}

static float held_damage(const PsvPlayer *p) {
    int id = isr_get_stack(&p->inv, p->inv.current_item).item;
    if (id == 268 || id == 283) return mc_combat_weapon_raw(1);
    if (id == 272) return mc_combat_weapon_raw(2);
    if (id == 267) return mc_combat_weapon_raw(3);
    if (id == 276) return mc_combat_weapon_raw(4);
    if (id == 271 || id == 286) return 7.0f;
    if (id == 275 || id == 258 || id == 279) return 9.0f;
    if (id == 270 || id == 285) return 2.0f;
    if (id == 274) return 3.0f;
    if (id == 257) return 4.0f;
    if (id == 278) return 5.0f;
    if (id == 269 || id == 284) return 2.5f;
    if (id == 273) return 3.5f;
    if (id == 256) return 4.5f;
    if (id == 277) return 5.5f;
    return mc_combat_weapon_raw(0);
}

static double held_attack_speed(const PsvPlayer *p) {
    int id = isr_get_stack(&p->inv, p->inv.current_item).item;
    if (id == 268 || id == 272 || id == 267 || id == 276 || id == 283)
        return 1.5999999046325684;
    if (id == 271 || id == 275) return 0.7999999523162842;
    if (id == 258) return 0.9000000953674316;
    if (id == 279 || id == 286 || id == 269 || id == 273 || id == 256 || id == 277
            || id == 284)
        return 1.0;
    if (id == 270 || id == 274 || id == 257 || id == 278 || id == 285)
        return 1.2000000476837158;
    if (id == 290 || id == 294) return 1.0;
    if (id == 291) return 2.0;
    if (id == 292) return 3.0;
    return 4.0;
}

static float held_attack_strength(
        const PsvPlayer *p, int ticks, float adjust,
        double attack_speed_multiplier) {
    double speed = held_attack_speed(p) * attack_speed_multiplier;
    if (speed <= 0.0) return 0.0f;
    float period = (float)(1.0 / speed * 20.0);
    float value = ((float)ticks + adjust) / period;
    if (value < 0.0f) return 0.0f;
    return value > 1.0f ? 1.0f : value;
}

static int player_attack_creature(int type) {
    switch (type) {
    case EW_TYPE_ZOMBIE:
    case EW_TYPE_ZOMBIE_VILLAGER:
    case EW_TYPE_GIANT:
    case EW_TYPE_SKELETON:
    case EW_TYPE_PIGMAN:
    case EW_TYPE_WITHER_SKELETON:
        return EDF_CREATURE_UNDEAD;
    case EW_TYPE_SPIDER:
    case EW_TYPE_CAVE_SPIDER:
    case EW_TYPE_SILVERFISH:
    case EW_TYPE_ENDERMITE:
        return EDF_CREATURE_ARTHROPOD;
    case EW_TYPE_VINDICATOR:
    case EW_TYPE_EVOKER:
    case EW_TYPE_VEX:
        return EDF_CREATURE_ILLAGER;
    default:
        return EDF_CREATURE_UNDEFINED;
    }
}

static float held_enchantment_damage(const PsvPlayer *p, int target_type) {
    ICStack held = isr_get_stack(&p->inv, p->inv.current_item);
    int creature = player_attack_creature(target_type);
    float result = 0.0f;
    for (int i = 0; i < held.n_enchants; ++i) {
        int type = held.enchants[i].id == 16 ? EDF_TYPE_SHARPNESS
            : held.enchants[i].id == 17 ? EDF_TYPE_SMITE
            : held.enchants[i].id == 18 ? EDF_TYPE_BANE : -1;
        if (type >= 0)
            result += edf_calc_damage_by_creature(
                type, held.enchants[i].level, creature);
    }
    return result;
}

static int held_enchantment_level(const PsvPlayer *p, int enchantment_id) {
    ICStack held = isr_get_stack(&p->inv, p->inv.current_item);
    int level = 0;
    for (int i = 0; i < held.n_enchants; ++i)
        if (held.enchants[i].id == enchantment_id
                && held.enchants[i].level > level)
            level = held.enchants[i].level;
    return level;
}

static int held_is_sword(const PsvPlayer *p) {
    ICStack held = isr_get_stack(&p->inv, p->inv.current_item);
    return held.item == 267 || held.item == 268 || held.item == 272
        || held.item == 276 || held.item == 283;
}

static int passive_sound_event(int type, int lethal);
static float passive_sound_volume(int type);
static int living_hurt_death_sound_event(
    const GmMobLive *m, int slot, int type, int size, int lethal);
static float living_hurt_death_sound_volume(int type, int size);
static float living_hurt_death_sound_pitch(int type, float pitch);

static void player_attack_knockback(
        GmMobLive *m, EwStore *s, int slot, float strength,
        double ratio_x, double ratio_z) {
    /* All currently represented ordinary living targets retain the vanilla
     * zero knockback-resistance attribute. EntityLivingBase.knockBack still
     * consumes its resistance trial before changing motion. */
    (void)jrand_double(&m->entity_random[slot].random);
    float length = (float)sqrt(ratio_x * ratio_x + ratio_z * ratio_z);
    if (length <= 0.0F) return;
    s->vx[slot] /= 2.0D;
    s->vz[slot] /= 2.0D;
    s->vx[slot] -= ratio_x / (double)length * (double)strength;
    s->vz[slot] -= ratio_z / (double)length * (double)strength;
    if (s->on_ground[slot]) {
        s->vy[slot] /= 2.0D;
        s->vy[slot] += (double)strength;
        if (s->vy[slot] > 0.4000000059604645D)
            s->vy[slot] = 0.4000000059604645D;
    }
}

static float player_attack_primary_knockback(
        GmMobLive *m, EwStore *s, int slot,
        double attacker_x, double attacker_z,
        const GmMobDeathContext *death_context) {
    /* EntityLivingBase.setBeenAttacked performs its own resistance trial
     * before attackEntityFrom calls knockBack for the fresh hurt edge. */
    (void)jrand_double(&m->entity_random[slot].random);
    m->entity_velocity_changed[slot] = 1;
    double ratio_x = attacker_x - s->x[slot];
    double ratio_z = attacker_z - s->z[slot];
    while (ratio_x * ratio_x + ratio_z * ratio_z < 1.0E-4D) {
        if (!death_context || !death_context->math_random_seed48) return 1.0F;
        ratio_x = (mob_math_random_next_double(
                death_context->math_random_seed48)
            - mob_math_random_next_double(
                death_context->math_random_seed48)) * 0.01D;
        ratio_z = (mob_math_random_next_double(
                death_context->math_random_seed48)
            - mob_math_random_next_double(
                death_context->math_random_seed48)) * 0.01D;
    }
    m->entity_attacked_yaw[slot] = (float)(
        mob_java_math_atan2(ratio_z, ratio_x) * (180.0D / MC_PI)
        - (double)s->yaw[slot]);
    player_attack_knockback(m, s, slot, 0.4F, ratio_x, ratio_z);
    /* getSoundPitch follows the primary knockback inside attackEntityFrom. */
    float first = jrand_float(&m->entity_random[slot].random);
    float second = jrand_float(&m->entity_random[slot].random);
    return (first - second) * 0.2F + 1.0F;
}

static void player_attack_fresh_feedback(
        GmMobLive *m, EwStore *s, int slot,
        double attacker_x, double attacker_z,
        const GmMobDeathContext *death_context, int status) {
    m->entity_max_hurt_time[slot] = 10;
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], status,
        s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    float pitch = player_attack_primary_knockback(
        m, s, slot, attacker_x, attacker_z, death_context);
    int sound = living_hurt_death_sound_event(
        m, slot, s->type[slot], m->size[slot],
        s->health[slot] <= 0.0F);
    if (sound)
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot], sound,
            s->x[slot], s->y[slot], s->z[slot],
            living_hurt_death_sound_volume(
                s->type[slot], m->size[slot]),
            living_hurt_death_sound_pitch(s->type[slot], pitch));
}

static void player_attack_extra_knockback(
        GmMobLive *m, EwStore *s, int slot, PsvPlayer *p,
        const McSinTable *sin_table, int level) {
    if (level <= 0 || !sin_table) return;
    float yaw = p->yaw * 0.017453292F;
    player_attack_knockback(
        m, s, slot, (float)level * 0.5F,
        (double)mc_sin(sin_table, yaw),
        (double)-mc_cos(sin_table, yaw));
    p->ent.motionX *= 0.6D;
    p->ent.motionZ *= 0.6D;
    p->sprinting = 0;
}

static float player_attack_after_mob_armor(
        const GmMobLive *m, int slot, int type, float amount) {
    int armor = gm_zombie(type) || type == EW_TYPE_PIGMAN ? 2
        : type == EW_TYPE_MAGMA ? (int)m->size[slot] * 3
        : type == EW_TYPE_RABBIT && m->rabbit_type[slot] == 99 ? 8
        : type == EW_TYPE_HORSE
            ? (m->horse_armor[slot] == 1 ? 5
                : m->horse_armor[slot] == 2 ? 7
                : m->horse_armor[slot] == 3 ? 11 : 0)
        : 0;
    return armor > 0
        ? mc_combat_damage_after_absorb(amount, (float)armor, 0.0f)
        : amount;
}

static int held_hit_durability(int id) {
    if (id == 268 || id == 272 || id == 267 || id == 276 || id == 283
            || (id >= 290 && id <= 294))
        return 1;
    if (id == 256 || id == 257 || id == 258
            || id == 269 || id == 270 || id == 271
            || id == 273 || id == 274 || id == 275
            || id == 277 || id == 278 || id == 279
            || id == 284 || id == 285 || id == 286)
        return 2;
    return 0;
}

static void damage_held_weapon(GmMobLive *m, PsvPlayer *p) {
    int slot = p->inv.current_item;
    ICStack held = isr_get_stack(&p->inv, slot);
    int amount = held_hit_durability(held.item);
    if (amount <= 0) return;
    ITAStack tool = mob_ita_stack(held);
    if (ita_attempt_damage(&tool, amount, &m->player_random)) {
        (void)isr_decr_stack_size(&p->inv, slot, 1);
    } else {
        held.meta = tool.damage;
        isr_set_stack(&p->inv, slot, held);
    }
}

static void slime_split(GmMobLive *m, EwStore *s, int i) {
    int sz = m->size[i];
    int type = s->type[i];
    int source_eid = s->id[i];
    int dimension = m->entity_dimension[i];
    double x = s->x[i], y = s->y[i], z = s->z[i];
    if (sz <= 1) return;
    int child = sz / 2;
    for (int k = 0; k < 2; ++k) {
        u64 h = mc_hash_seed(
            (u64)m->seed, m->tick, i, k, source_eid, 0x53504C54u);
        double ox = ((double)mc_hash_bound(h, 1000) / 1000.0 - 0.5) * (double)sz * 0.5;
        double oz = ((double)mc_hash_bound(mc_hash64(h), 1000) / 1000.0 - 0.5) * (double)sz * 0.5;
        int is_cold = 0;
        int child_eid = m->next_id++;
        int slot = living_spawn_slot(
            m, s, type, child_eid, x + ox, y + 0.5, z + oz,
            max_health(type, child), &is_cold);
        if (slot < 0) break;
        m->entity_dimension[slot] = (signed char)dimension;
        m->size[slot] = (unsigned char)child;
        reset_slot_state_s(m, s, slot);
        (void)living_spawn_finish(m, s, slot, is_cold, 0);
    }
}

static void mob_drop(GmMobLive *m, EwStore *s, int i, GmLiveSim *drops) {
    int item = 0, count = 1, xp = 5;
    int type = s->type[i];
    /* EntityPig.onDeath drops its ordinary loot and optional saddle now, but
     * EntityLivingBase remains in the world until deathTime reaches 20.  Keep
     * the represented rider association and loaded slot during that window;
     * the ordinary product tick owns terminal XP, particles, dismount, and
     * retirement.  Controlled passive deaths already have an exact separate
     * loot boundary and never enter mob_drop. */
    if (type == EW_TYPE_PIG && !m->controlled_no_ai[i]) {
        if (m->entity_dead[i]) return;
        gm_live_spawn_item(
            drops, s->x[i], s->y[i] + 0.25, s->z[i], 319, 1, 0, 10);
        if (m->pig_saddled[i])
            gm_live_spawn_item(
                drops, s->x[i], s->y[i] + 0.25, s->z[i], 329, 1, 0, 10);
        s->health[i] = 0.0F;
        m->entity_dead[i] = 1;
        m->entity_death_time[i] = 0;
        return;
    }
    switch (type) {
    case EW_TYPE_ZOMBIE:
    case EW_TYPE_ZOMBIE_VILLAGER: item = 367; break;
    case EW_TYPE_SKELETON: item = 352; break;
    case EW_TYPE_WITHER_SKELETON:
        item = 352;
        /* wither skeleton skull rare drop skipped; coal possible */
        if ((mc_hash64((u64)m->seed ^ (u64)s->id[i] ^ 0x57495448ULL) & 3ULL) == 0)
            gm_live_spawn_item(drops, s->x[i], s->y[i] + 0.25, s->z[i], 263, 1, 0, 10);
        break;
    case EW_TYPE_CREEPER: item = 289; break;
    case EW_TYPE_SPIDER:
    case EW_TYPE_CAVE_SPIDER: item = 287; break;
    case EW_TYPE_ENDERMAN:
        if ((mc_hash64((u64)m->seed ^ (u64)s->id[i]) & 1ULL) != 0) item = 368;
        break;
    case EW_TYPE_BLAZE:
        if ((mc_hash64((u64)m->seed ^ (u64)s->id[i]) & 1ULL) != 0) item = 369;
        xp = 10; break;
    case EW_TYPE_PIGMAN:
        item = 367; /* rotten flesh */
        if ((mc_hash64((u64)m->seed ^ (u64)s->id[i] ^ 0x474F4C44ULL) & 3ULL) == 0)
            gm_live_spawn_item(drops, s->x[i], s->y[i] + 0.25, s->z[i], 266, 1, 0, 10);
        break;
    case EW_TYPE_GHAST:
        item = 289; /* gunpowder */
        if ((mc_hash64((u64)m->seed ^ (u64)s->id[i] ^ 0x54454152ULL) & 1ULL) != 0)
            gm_live_spawn_item(drops, s->x[i], s->y[i] + 0.25, s->z[i], 370, 1, 0, 10);
        break;
    case EW_TYPE_MAGMA:
        if (m->size[i] > 1 &&
            (mc_hash64((u64)m->seed ^ (u64)s->id[i]) & 1ULL) != 0) item = 378;
        xp = m->size[i];
        slime_split(m, s, i);
        break;
    case EW_TYPE_SLIME:
        if (m->size[i] == 1) item = 341; /* slime ball */
        xp = m->size[i];
        slime_split(m, s, i);
        break;
    case EW_TYPE_SILVERFISH:
        item = 0; xp = 5; break;
    case EW_TYPE_SHEEP:
        item = 35; xp = 1;
        gm_live_spawn_item(drops, s->x[i], s->y[i] + 0.25, s->z[i], 423, 1, 0, 10); break;
    case EW_TYPE_PIG: item = 319; xp = 1; break;
    case EW_TYPE_COW:
    case EW_TYPE_MOOSHROOM:
        item = 363; xp = 1;
        gm_live_spawn_item(drops, s->x[i], s->y[i] + 0.25, s->z[i], 334, 1, 0, 10); break;
    case EW_TYPE_CHICKEN:
        item = 365; xp = 1;
        gm_live_spawn_item(drops, s->x[i], s->y[i] + 0.25, s->z[i], 288, 1, 0, 10); break;
    case EW_TYPE_BOAT:
        /* Items.BOAT is oak; the five later registrations are contiguous. */
        item = m->boat_variant[i] == 0
            ? 333 : 443 + (int)m->boat_variant[i];
        xp = 0; break;
    default: break;
    }
    if (item) gm_live_spawn_item(drops, s->x[i], s->y[i] + 0.25, s->z[i], item, count, 0, 10);
    /* EntityPig.onDeath appends the saddle after ordinary pork loot.  This
     * tail drop is outside the superclass doMobLoot path in Java 1.11.2. */
    if (type == EW_TYPE_PIG && m->pig_saddled[i])
        gm_live_spawn_item(
            drops, s->x[i], s->y[i] + 0.25, s->z[i], 329, 1, 0, 10);
    if (xp > 0) gm_mobs_spawn_xp(m, s->x[i], s->y[i] + 0.25, s->z[i], xp);
    if (type == EW_TYPE_BOAT) boat_remove_all_passengers(m, i);
    else if (ride_is_slot(s, i, m->boat_ride_eid))
        m->boat_ride_eid = -1;
    if (ride_is_slot(s, i, m->pig_ride_eid)) {
        m->pig_ride_eid = -1;
        m->pig_vehicle_server.valid = 0;
    }
    loaded_invalidate_living(m, i);
    s->alive[i] = 0;
    s->type[i] = EW_TYPE_NONE;
}

static McAABB player_attack_entity_box(
        const GmMobLive *m, const EwStore *s, int slot) {
    float width, height;
    ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
    double half = (double)width * 0.5;
    return mc_aabb_make(
        s->x[slot] - half, s->y[slot], s->z[slot] - half,
        s->x[slot] + half, s->y[slot] + (double)height,
        s->z[slot] + half);
}

static void player_attack_target_pre_damage(
        GmMobLive *m, const EwStore *s, int slot) {
    if (s->type[slot] != EW_TYPE_PIGMAN) return;
    /* EntityPigZombie.becomeAngryAt precedes EntityLivingBase damage and
     * consumes both angerLevel and randomSoundDelay draws even if hurt
     * resistance later rejects the hit. */
    m->anger[slot] = GM_PIGMAN_ANGER_BASE
        + jrand_int_bound(&m->entity_random[slot].random, 400);
    (void)jrand_int_bound(&m->entity_random[slot].random, 40);
}

static int player_attack_sweep(
        GmMobLive *m, EwStore *s, int primary,
        const McAABB *primary_box, int ox, int oz,
        PsvPlayer *player, const McSinTable *sin_table,
        float primary_amount, GmLiveSim *drops,
        const GmMobDeathContext *death_context) {
    int level = held_enchantment_level(player, 22);
    float multiplier = level > 0
        ? 1.0F - 1.0F / (float)(level + 1) : 0.0F;
    float amount = 1.0F + multiplier * primary_amount;
    McAABB area = mc_aabb_make(
        primary_box->minX - 1.0, primary_box->minY - 0.25,
        primary_box->minZ - 1.0, primary_box->maxX + 1.0,
        primary_box->maxY + 0.25, primary_box->maxZ + 1.0);
    double player_x = player->ent.posX + ox;
    double player_y = player->ent.posY;
    double player_z = player->ent.posZ + oz;
    float yaw = player->yaw * 0.017453292F;
    double ratio_x = (double)mc_sin(sin_table, yaw);
    double ratio_z = (double)-mc_cos(sin_table, yaw);
    int hits = 0;

    int cursor = 0, slot;
    while ((slot = living_next_slot_from_store(m, s, &cursor)) > 0) {
        if (slot == primary || !s->alive[slot] || m->entity_dead[slot]
                || s->health[slot] <= 0.0F
                || !gm_living(s->type[slot])
                || s->type[slot] == EW_TYPE_BOAT
                || m->entity_dimension[slot] != m->active_dimension)
            continue;
        McAABB box = player_attack_entity_box(m, s, slot);
        if (!(area.minX < box.maxX && area.maxX > box.minX
                && area.minY < box.maxY && area.maxY > box.minY
                && area.minZ < box.maxZ && area.maxZ > box.minZ))
            continue;
        double dx = player_x - s->x[slot];
        double dy = player_y - s->y[slot];
        double dz = player_z - s->z[slot];
        if (dx * dx + dy * dy + dz * dz >= 9.0D)
            continue;

        /* EntityPlayer applies the fixed sweep knockback before damage, even
         * when the secondary target rejects attackEntityFrom. */
        player_attack_knockback(
            m, s, slot, 0.4F, ratio_x, ratio_z);
        player_attack_target_pre_damage(m, s, slot);

        int accepted;
        if ((gm_passive(s->type[slot])
                    || s->type[slot] == EW_TYPE_WITCH
                    || mob_exact_ordinary_death_type(s->type[slot]))
                && !m->controlled_no_ai[slot] && death_context) {
            accepted = gm_passive(s->type[slot])
                ? mob_player_damage_passive_slot_exact(
                    m, s, slot, player_x, player_z,
                    amount, held_enchantment_level(player, 21),
                    drops, death_context, 0) == 2
                : s->type[slot] == EW_TYPE_WITCH
                ? mob_player_damage_witch_slot_exact(
                    m, s, slot, player_x, player_z, amount,
                    held_enchantment_level(player, 21),
                    drops, death_context, 0) == 2
                : mob_player_damage_hostile_slot_exact(
                    m, s, slot, player_x, player_z, amount,
                    held_enchantment_level(player, 21),
                    drops, death_context, 0) == 2;
        } else {
            float applied = amount;
            int fresh = m->entity_hurt_resistant[slot] <= 10;
            accepted = 1;
            if (m->entity_hurt_resistant[slot] > 10) {
                if (amount <= m->entity_last_damage[slot]) {
                    accepted = 0;
                } else {
                    applied = amount - m->entity_last_damage[slot];
                    m->entity_last_damage[slot] = amount;
                }
            } else {
                m->entity_last_damage[slot] = amount;
                m->entity_hurt_resistant[slot] = 20;
                m->entity_hurt_time[slot] = 10;
            }
            if (accepted) {
                int target_eid = s->id[slot];
                applied = player_attack_after_mob_armor(
                    m, slot, s->type[slot], applied);
                applied = mob_resistance_damage(m, slot, applied);
                applied = mob_absorb_damage(m, slot, applied);
                s->health[slot] -= applied;
                if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
                mark_hurt(m, s, slot);
                slot = mob_slot_by_eid(m, target_eid);
                if (slot <= 0) continue;
                villager_player_harm_append(
                    m, s, slot, s->health[slot] <= 0.0F);
                if (fresh)
                    player_attack_fresh_feedback(
                        m, s, slot, player_x, player_z, death_context, 2);
                if (s->type[slot] == EW_TYPE_PIG) {
                    m->entity_recently_hit[slot] = 100;
                    m->entity_attacking_player[slot] = 1;
                }
                if (s->health[slot] <= 0.0F && !m->controlled_no_ai[slot])
                    mob_drop(m, s, slot, drops);
            }
        }
        if (accepted) ++hits;
    }
    living_cold_flush_one_from_store(
        m, s, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &m->living_staged_cold_secondary);
    return hits;
}

int gm_mobs_player_attack_target(
        const GmMobLive *m, const struct PsvPlayer *player_,
        int ox, int oz, int *eid, double *distance) {
    const PsvPlayer *p;
    const EwStore *s;
    double px, py, pz, yr, pr, dx, dy, dz;
    double best_t = 3.0;
    int best_eid = -1;
    GmMobLive *mutable_m = (GmMobLive *)m;
    if (!m || !player_) return 0;
    p = (const PsvPlayer *)player_;
    s = const_store(m);
    px = p->ent.posX + ox;
    py = p->ent.posY + PSV_EYE_HEIGHT;
    pz = p->ent.posZ + oz;
    yr = p->yaw * MC_PI / 180.0;
    pr = p->pitch * MC_PI / 180.0;
    dx = -sin(yr) * cos(pr);
    dy = -sin(pr);
    dz = cos(yr) * cos(pr);
    int cursor = 0, i;
    while ((i = gm_mobs_living_next_slot(mutable_m, &cursor)) > 0) {
        float width, height;
        double cx, cy, cz, vx, vy, vz, t, ex, ey, ez, radius, vtol;
        s = const_store(m);
        if (!s->alive[i] || m->entity_dead[i] || s->health[i] <= 0.0F
                || !gm_living(s->type[i])
                || m->entity_dimension[i] != m->active_dimension)
            continue;
        ehs_size_scaled(s->type[i], m->size[i], &width, &height);
        cx = s->x[i];
        cy = s->y[i] + height * 0.5;
        cz = s->z[i];
        vx = cx - px; vy = cy - py; vz = cz - pz;
        t = vx * dx + vy * dy + vz * dz;
        if (t < 0.0 || t > best_t) continue;
        ex = vx - t * dx; ey = vy - t * dy; ez = vz - t * dz;
        radius = width * 0.5 + 0.25;
        vtol = height * 0.5 + 0.25;
        if (s->type[i] == EW_TYPE_BOAT) vtol = 2.0;
        if (ex * ex + ez * ez <= radius * radius && fabs(ey) <= vtol) {
            best_eid = s->id[i];
            best_t = t;
        }
    }
    gm_mobs_living_cold_flush(mutable_m);
    if (best_eid < 0) return 0;
    if (eid) *eid = best_eid;
    if (distance) *distance = best_t;
    return 1;
}

int gm_mobs_player_attack(GmMobLive *m, const struct PsvPlayer *player_,
                          int ox, int oz,
                          const struct McSinTable *sin_table_,
                          GmLiveSim *drops,
                          float attack_damage_bonus,
                          double attack_speed_multiplier,
                          int on_ladder, int in_water, int riding,
                          const GmMobDeathContext *death_context,
                          float distance_walked_delta,
                          GmPlayerAttackOutcome *outcome) {
    if (outcome) memset(outcome, 0, sizeof *outcome);
    if (!m || !player_) return 0;
    const PsvPlayer *p = (const PsvPlayer *)player_;
    PsvPlayer *mutable_player = (PsvPlayer *)player_;
    const McSinTable *sin_table = (const McSinTable *)sin_table_;
    EwStore *s = now_store(m);
    double px = p->ent.posX + ox, py = p->ent.posY + PSV_EYE_HEIGHT, pz = p->ent.posZ + oz;
    double yr = p->yaw * MC_PI / 180.0, pr = p->pitch * MC_PI / 180.0;
    double dx = -sin(yr) * cos(pr), dy = -sin(pr), dz = cos(yr) * cos(pr);
    int best = -1, best_eid = -1; double best_t = 3.0;
    int cursor = 0, i;
    while ((i = gm_mobs_living_next_slot(m, &cursor)) > 0) {
        s = now_store(m);
        if (s->alive[i]
            && !m->entity_dead[i] && s->health[i] > 0.0F
            && gm_living(s->type[i])) {
        if (m->entity_dimension[i] != m->active_dimension) continue;
        float width, height;
        ehs_size_scaled(s->type[i], m->size[i], &width, &height);
        double cx = s->x[i], cy = s->y[i] + height * 0.5, cz = s->z[i];
        double vx = cx-px, vy = cy-py, vz = cz-pz;
        double t = vx*dx + vy*dy + vz*dz;
        if (t < 0.0 || t > best_t) continue;
        double ex=vx-t*dx, ey=vy-t*dy, ez=vz-t*dz;
        double radius = width * 0.5 + 0.25;
        double vtol = height * 0.5 + 0.25;
        if (s->type[i] == EW_TYPE_BOAT) vtol = 2.0; /* low hull, aim from standing */
        if (ex*ex + ez*ez <= radius*radius && fabs(ey) <= vtol) {
            best_eid=s->id[i]; best_t=t;
        }
        }
    }
    gm_mobs_living_cold_flush(m);
    best = mob_slot_by_eid(m, best_eid);
    s = now_store(m);
    if (best < 0) return 0;
    float target_width, target_height;
    ehs_size_scaled(s->type[best], m->size[best],
                    &target_width, &target_height);
    float target_health_before = s->health[best];
    if (outcome) {
        outcome->targeted = 1;
        outcome->target_eid = s->id[best];
        outcome->target_dimension = m->entity_dimension[best];
        outcome->target_x = s->x[best];
        outcome->target_y = s->y[best];
        outcome->target_z = s->z[best];
        outcome->target_width = target_width;
        outcome->target_height = target_height;
    }
    /* Preserve the primary AABB across lethal damage.  Java builds the sweep
     * query from the target object even when attackEntityFrom kills it. */
    McAABB primary_box = player_attack_entity_box(m, s, best);
    float strength = held_attack_strength(
        p, m->player_ticks_since_last_swing, 0.5f,
        attack_speed_multiplier);
    m->player_ticks_since_last_swing = 0;
    float base_damage = held_damage(p) + attack_damage_bonus;
    if (base_damage < 0.0f) base_damage = 0.0f;
    float amount = base_damage *
        (0.2f + strength * strength * 0.8f);
    float enchantment = held_enchantment_damage(p, s->type[best]) * strength;
    int knockback = held_enchantment_level(p, 19);
    int fire_aspect = held_enchantment_level(p, 20);
    int full_strength = strength > 0.9F;
    int sprint_knockback = p->sprinting && full_strength;
    if (sprint_knockback) ++knockback;
    int critical = strength > 0.9f && p->fall_distance > 0.0f
        && !p->ent.onGround && !on_ladder && !in_water && !p->blindness
        && !riding && !p->sprinting && gm_living(s->type[best]);
    if (critical) amount *= 1.5f;
    amount += enchantment;
    if (amount <= 0.0F) {
        ew_store_copy(next_store(m), s);
        return 1;
    }
    float ai_speed = (float)(
        0.10000000149011612D * p->movement_speed_multiplier);
    int sweep = full_strength && !critical && !sprint_knockback
        && p->ent.onGround && (double)distance_walked_delta < (double)ai_speed
        && held_is_sword(p);
    if (outcome) {
        outcome->attempted = 1;
        outcome->knockback = sprint_knockback;
        outcome->critical = critical;
        outcome->sweep = sweep;
        outcome->enchantment_critical = enchantment > 0.0F;
        if ((s->type[best] == EW_TYPE_GUARDIAN
                    || s->type[best] == EW_TYPE_ELDER_GUARDIAN)
                && !m->guardian_moving[best])
            outcome->thorns_damage = 2.0F;
    }
    if (s->type[best] == EW_TYPE_BOAT) {
        /* EntityBoat.attackEntityFrom stores the actual player attack amount
         * multiplied by ten and breaks only when DAMAGE_TAKEN exceeds 40. */
        m->boat_damage[best] += amount * 10.0F;
        if (m->boat_damage[best] > 40.0F)
            mob_drop(m, s, best, drops);
        if (sweep) {
            int sweep_hits = player_attack_sweep(
                m, s, best, &primary_box, ox, oz,
                mutable_player, sin_table,
                amount, drops, death_context);
            if (outcome) outcome->sweep_hits = sweep_hits;
        }
        if (outcome) outcome->accepted = 1;
        ew_store_copy(next_store(m), s);
        return 1;
    }
    int fire_preignited = 0;
    if (fire_aspect > 0 && m->fire_ticks[best] <= 0) {
        m->fire_ticks[best] = 20;
        fire_preignited = 1;
    }
    player_attack_target_pre_damage(m, s, best);
    if ((gm_passive(s->type[best])
                || s->type[best] == EW_TYPE_WITCH
                || mob_exact_ordinary_death_type(s->type[best]))
            && !m->controlled_no_ai[best] && death_context) {
        int result = gm_passive(s->type[best])
            ? mob_player_damage_passive_slot_exact(
                m, s, best, p->ent.posX + ox, p->ent.posZ + oz,
                amount, held_enchantment_level(p, 21),
                drops, death_context, 0)
            : s->type[best] == EW_TYPE_WITCH
            ? mob_player_damage_witch_slot_exact(
                m, s, best, p->ent.posX + ox, p->ent.posZ + oz,
                amount, held_enchantment_level(p, 21),
                drops, death_context, 0)
            : mob_player_damage_hostile_slot_exact(
                m, s, best, p->ent.posX + ox, p->ent.posZ + oz,
                amount, held_enchantment_level(p, 21),
                drops, death_context, 0);
        if (result == 2) {
            if (fire_aspect > 0) {
                int final_fire = fire_aspect * 4 * 20;
                if (m->fire_ticks[best] < final_fire)
                    m->fire_ticks[best] = final_fire;
            }
            player_attack_extra_knockback(
                m, s, best, mutable_player, sin_table, knockback);
            if (sweep) {
                int sweep_hits = player_attack_sweep(
                    m, s, best, &primary_box, ox, oz,
                    mutable_player, sin_table,
                    amount, drops, death_context);
                if (outcome) outcome->sweep_hits = sweep_hits;
            }
            damage_held_weapon(m, mutable_player);
        } else if (fire_preignited) m->fire_ticks[best] = 0;
        if (outcome) {
            outcome->accepted = result == 2;
            outcome->no_damage = result != 2;
            outcome->strong = result == 2 && !critical && !sweep
                && full_strength;
            outcome->weak = result == 2 && !critical && !sweep
                && !full_strength;
            outcome->damage_dealt = result == 2
                ? target_health_before - s->health[best] : 0.0F;
        }
        ew_store_copy(next_store(m), s);
        return result;
    }
    float applied = amount;
    int accepted = 1;
    int fresh = m->entity_hurt_resistant[best] <= 10;
    if (m->entity_hurt_resistant[best] > 10) {
        if (amount <= m->entity_last_damage[best]) {
            accepted = 0;
        } else {
            applied = amount - m->entity_last_damage[best];
            m->entity_last_damage[best] = amount;
        }
    } else {
        m->entity_last_damage[best] = amount;
        m->entity_hurt_resistant[best] = 20;
        m->entity_hurt_time[best] = 10;
    }
    if (accepted) {
        applied = player_attack_after_mob_armor(
            m, best, s->type[best], applied);
        applied = mob_resistance_damage(m, best, applied);
        applied = mob_absorb_damage(m, best, applied);
        s->health[best] -= applied;
        if (s->health[best] < 0.0f) s->health[best] = 0.0f;
        mark_hurt(m, s, best);
        villager_player_harm_append(
            m, s, best, s->health[best] <= 0.0F);
        if (fresh)
            player_attack_fresh_feedback(
                m, s, best, p->ent.posX + ox, p->ent.posZ + oz,
                death_context, 2);
        player_attack_extra_knockback(
            m, s, best, mutable_player, sin_table, knockback);
        if (fire_aspect > 0) {
            int final_fire = fire_aspect * 4 * 20;
            if (m->fire_ticks[best] < final_fire)
                m->fire_ticks[best] = final_fire;
        }
        if (s->type[best] == EW_TYPE_PIG) {
            m->entity_recently_hit[best] = 100;
            m->entity_attacking_player[best] = 1;
        }
        if (sweep) {
            int sweep_hits = player_attack_sweep(
                m, s, best, &primary_box, ox, oz,
                mutable_player, sin_table,
                amount, drops, death_context);
            if (outcome) outcome->sweep_hits = sweep_hits;
        }
        damage_held_weapon(m, mutable_player);
        if (s->health[best] <= 0.0f && !m->controlled_no_ai[best])
            mob_drop(m, s, best, drops);
    }
    else if (fire_preignited) m->fire_ticks[best] = 0;
    if (outcome) {
        outcome->accepted = accepted;
        outcome->no_damage = !accepted;
        outcome->strong = accepted && !critical && !sweep && full_strength;
        outcome->weak = accepted && !critical && !sweep && !full_strength;
        outcome->damage_dealt = accepted
            ? target_health_before - s->health[best] : 0.0F;
    }
    ew_store_copy(next_store(m), s);
    return accepted ? 2 : 1;
}

void gm_mobs_player_swing(GmMobLive *m) {
    if (m) m->player_ticks_since_last_swing = 0;
}

float gm_mobs_player_attack_strength(
        const GmMobLive *m, const struct PsvPlayer *player_,
        double attack_speed_multiplier) {
    if (!m) return 1.0f;
    const PsvPlayer *p = (const PsvPlayer *)player_;
    if (!p) {
        double speed = 4.0 * attack_speed_multiplier;
        if (speed <= 0.0) return 0.0f;
        float period = (float)(1.0 / speed * 20.0);
        float value = (float)m->player_ticks_since_last_swing / period;
        if (value < 0.0f) return 0.0f;
        return value > 1.0f ? 1.0f : value;
    }
    return held_attack_strength(
        p, m->player_ticks_since_last_swing, 0.0f,
        attack_speed_multiplier);
}

float gm_mobs_player_attack_amount_undefined(
        GmMobLive *m, const struct PsvPlayer *player_,
        float attack_damage_bonus, double attack_speed_multiplier,
        int *full_strength, int *sprint_knockback) {
    const PsvPlayer *player = (const PsvPlayer *)player_;
    float strength, damage, enchantment;
    if (!m || !player) return 0.0F;
    strength = held_attack_strength(
        player, m->player_ticks_since_last_swing, 0.5F,
        attack_speed_multiplier);
    m->player_ticks_since_last_swing = 0;
    damage = held_damage(player) + attack_damage_bonus;
    if (damage < 0.0F) damage = 0.0F;
    damage *= 0.2F + strength * strength * 0.8F;
    enchantment = held_enchantment_damage(
        player, EW_TYPE_CREEPER) * strength;
    damage += enchantment;
    if (full_strength) *full_strength = strength > 0.9F;
    if (sprint_knockback)
        *sprint_knockback = player->sprinting && strength > 0.9F;
    return damage;
}

static McEntity ridden_pig_local_entity(
        const EbLiving *liv, int ox, int oz) {
    McEntity local;
    local.box = liv->base.phys.box;
    local.box.minX -= ox;
    local.box.maxX -= ox;
    local.box.minZ -= oz;
    local.box.maxZ -= oz;
    local.posX = liv->base.phys.posX - ox;
    local.posY = liv->base.phys.posY;
    local.posZ = liv->base.phys.posZ - oz;
    local.motionX = liv->base.phys.motionX;
    local.motionY = liv->base.phys.motionY;
    local.motionZ = liv->base.phys.motionZ;
    local.onGround = liv->base.phys.onGround;
    local.collidedHorizontally = liv->base.phys.collidedHorizontally;
    local.collidedVertically = liv->base.phys.collidedVertically;
    local.isCollided = liv->base.phys.isCollided;
    return local;
}

/* Entity.handleWaterMovement runs before the client-side NoAI .98 damping.
 * Reuse the verified player liquid/current probe in chunk-local coordinates;
 * the material semantics are Entity-level and are identical for a pig. */
static int ridden_pig_handle_water(
        const struct Chunk *window, int ox, int oz, EbLiving *liv) {
    McEntity local = ridden_pig_local_entity(liv, ox, oz);
    if (!psv_in_liquid((const Chunk *)window, &local, 1)) return 0;
    int in_water = psv_handle_water((const Chunk *)window, &local);
    liv->base.phys.motionX = local.motionX;
    liv->base.phys.motionY = local.motionY;
    liv->base.phys.motionZ = local.motionZ;
    if (in_water) liv->base.fallDistance = 0.0F;
    return in_water;
}

/* Entity.isInLava uses a different contracted AABB from water and does not
 * apply a current. Keep water precedence at the caller, matching travel(). */
static int ridden_pig_in_lava(
        const struct Chunk *window, int ox, int oz, const EbLiving *liv) {
    McEntity local = ridden_pig_local_entity(liv, ox, oz);
    return psv_in_liquid((const Chunk *)window, &local, 0);
}

static int mob_slot_world_box(
        const GmMobLive *m, const EwStore *s, int slot, McAABB *out) {
    if (!m || !s || !out || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot])
        return 0;
    if (m->entity_box_valid[slot]) {
        *out = mc_aabb_make(
            m->entity_box_min_x[slot], m->entity_box_min_y[slot],
            m->entity_box_min_z[slot], m->entity_box_max_x[slot],
            m->entity_box_max_y[slot], m->entity_box_max_z[slot]);
        return 1;
    }
    float width, height;
    ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
    if (gm_child_sized(s->type[slot]) && m->growing_age[slot] < 0) {
        width *= 0.5F;
        height *= 0.5F;
    }
    double half = (double)width * 0.5;
    *out = mc_aabb_make(
        s->x[slot] - half, s->y[slot], s->z[slot] - half,
        s->x[slot] + half, s->y[slot] + height,
        s->z[slot] + half);
    return 1;
}

/* Entity.isInLava is World.isMaterialInBB over
 * boundingBox.expand(-0.1, -0.4, -0.1). The liquid surface height is not
 * consulted by that path in 1.11.2. */
static int mob_slot_in_lava(
        const GmMobLive *m, const GmWorld *w,
        const EwStore *s, int slot) {
    McAABB box;
    if (!w || !mob_slot_world_box(m, s, slot, &box)) return 0;
    double x0 = box.minX + 0.1;
    double x1 = box.maxX - 0.1;
    double y0 = box.minY + 0.4;
    double y1 = box.maxY - 0.4;
    double z0 = box.minZ + 0.1;
    double z1 = box.maxZ - 0.1;
    if (y0 > y1) {
        double swap = y0;
        y0 = y1;
        y1 = swap;
    }
    for (int x = mc_floor(x0); x < psv_ceil(x1); ++x)
        for (int y = mc_floor(y0); y < psv_ceil(y1); ++y)
            for (int z = mc_floor(z0); z < psv_ceil(z1); ++z) {
                int block = gm_world_block(w, x, y, z);
                if (block == 10 || block == 11) return 1;
            }
    return 0;
}

/* World.isFlammableWithin(boundingBox.contract(.001)). Vanilla includes fire
 * and both lava blocks; modded Block.isBurning hooks remain outside this
 * bounded 1.11.2 block registry. */
static int mob_slot_in_flammable(
        const GmMobLive *m, const GmWorld *w,
        const EwStore *s, int slot) {
    McAABB box;
    if (!w || !mob_slot_world_box(m, s, slot, &box)) return 0;
    int x0 = mc_floor(box.minX + 0.001);
    int x1 = psv_ceil(box.maxX - 0.001);
    int y0 = mc_floor(box.minY + 0.001);
    int y1 = psv_ceil(box.maxY - 0.001);
    int z0 = mc_floor(box.minZ + 0.001);
    int z1 = psv_ceil(box.maxZ - 0.001);
    for (int x = x0; x < x1; ++x)
        for (int y = y0; y < y1; ++y)
            for (int z = z0; z < z1; ++z) {
                int block = gm_world_block(w, x, y, z);
                if (block == 51 || block == 10 || block == 11) return 1;
            }
    return 0;
}

/* Entity.doBlockCollisions visits every block coordinate inside the entity
 * AABB with a 0.001 inset. BlockCactus applies raw-one CACTUS damage from its
 * callback; its shorter collision box does not narrow this callback scan. */
static int mob_slot_in_cactus_callback(
        const GmMobLive *m, const GmWorld *w,
        const EwStore *s, int slot) {
    McAABB box;
    if (!w || !mob_slot_world_box(m, s, slot, &box)) return 0;
    int x0 = mc_floor(box.minX + 0.001);
    int x1 = mc_floor(box.maxX - 0.001);
    int y0 = mc_floor(box.minY + 0.001);
    int y1 = mc_floor(box.maxY - 0.001);
    int z0 = mc_floor(box.minZ + 0.001);
    int z1 = mc_floor(box.maxZ - 0.001);
    for (int x = x0; x <= x1; ++x)
        for (int y = y0; y <= y1; ++y)
            for (int z = z0; z <= z1; ++z)
                if (gm_world_block(w, x, y, z) == 81) return 1;
    return 0;
}

/* Entity.handleWaterMovement's inWater flag. Rain wetness is owned by the
 * broader weather/entity-contact slice; this locks actual water overlap. */
static int mob_slot_in_water(
        const GmMobLive *m, const GmWorld *w,
        const EwStore *s, int slot) {
    McAABB box;
    if (!w || !mob_slot_world_box(m, s, slot, &box)) return 0;
    double x0 = box.minX + 0.001;
    double x1 = box.maxX - 0.001;
    double y0 = box.minY + 0.401;
    double y1 = box.maxY - 0.401;
    double z0 = box.minZ + 0.001;
    double z1 = box.maxZ - 0.001;
    if (y0 > y1) {
        double swap = y0;
        y0 = y1;
        y1 = swap;
    }
    for (int x = mc_floor(x0); x < psv_ceil(x1); ++x)
        for (int y = mc_floor(y0); y < psv_ceil(y1); ++y)
            for (int z = mc_floor(z0); z < psv_ceil(z1); ++z) {
                int block = gm_world_block(w, x, y, z);
                if (block == 8 || block == 9) return 1;
            }
    return 0;
}

/* Apply Entity.handleMaterialAcceleration through the shared, Java-verified
 * player/pig water-current kernel. The world scan remains authoritative for
 * inWater so direct product tests without a chunk window keep exact still-water
 * semantics; normal runtime ticks provide the synchronized window used for the
 * flow vector. */
int gm_mobs_handle_water_slot(
        GmMobLive *m, const GmWorld *w, const struct Chunk *window,
        int ox, int oz, EwStore *s, int slot) {
    int in_water = mob_slot_in_water(m, w, s, slot);
    if (!in_water || !window) return in_water;
    McAABB box;
    if (!mob_slot_world_box(m, s, slot, &box)) return in_water;
    McEntity local;
    memset(&local, 0, sizeof local);
    local.box = box;
    local.box.minX -= ox;
    local.box.maxX -= ox;
    local.box.minZ -= oz;
    local.box.maxZ -= oz;
    local.posX = s->x[slot] - ox;
    local.posY = s->y[slot];
    local.posZ = s->z[slot] - oz;
    local.motionX = s->vx[slot];
    local.motionY = s->vy[slot];
    local.motionZ = s->vz[slot];
    if (psv_handle_water((const Chunk *)window, &local)) {
        s->vx[slot] = local.motionX;
        s->vy[slot] = local.motionY;
        s->vz[slot] = local.motionZ;
    }
    return in_water;
}

/* Entity.isWet tests the base-phase inWater latch, then rain exposure at the
 * entity's floored feet and full-height positions. */
static int mob_slot_is_wet(
        const GmMobLive *m, const GmWorld *w, const GmWorldClock *clock,
        const EwStore *s, int slot) {
    if (m->entity_in_water[slot]) return 1;
    float width, height;
    ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
    (void)width;
    int x = mc_floor(s->x[slot]);
    int y = mc_floor(s->y[slot]);
    int z = mc_floor(s->z[slot]);
    return gm_world_is_raining_at(w, clock, x, y, z)
        || gm_world_is_raining_at(
            w, clock, x, mc_floor(s->y[slot] + (double)height), z);
}

/* Entity.move's post-collision flammable tail. This occurs after the base
 * phase and timer/death aging, so a fresh lethal IN_FIRE contact retains
 * hurtTime 10, hurtResistantTime 20, and deathTime 0 until the next tick. */
static int tick_exact_mob_fire_contact(
        GmMobLive *m, GmWorld *w, const GmWorldClock *clock,
        EwStore *s, int slot,
        GmLiveSim *drops, int do_mob_loot,
        uint64_t *math_random_seed48, int *next_entity_id) {
    if (m->controlled_no_ai[slot]
            || !mob_exact_environment_type(s->type[slot])
            || !s->alive[slot])
        return 0;
    int flammable = mob_slot_in_flammable(m, w, s, slot);
    if (flammable) {
        if (!mob_fire_immune_type(s->type[slot])
                && !m->entity_dead[slot] && s->health[slot] > 0.0F
                && mob_effect_amplifier(m, slot, 12) < 0) {
            int result = mob_source_damage_environment_slot_exact(
                m, s, slot, 1.0F, drops, math_random_seed48,
                next_entity_id, do_mob_loot, 1, 0);
            if (result < 0) return 1;
        }
        if (!mob_slot_is_wet(m, w, clock, s, slot)) {
            ++m->fire_ticks[slot];
            if (m->fire_ticks[slot] == 0)
                m->fire_ticks[slot] = 8 * 20;
        } else if (m->fire_ticks[slot] > 0) {
            (void)jrand_float(&m->entity_random[slot].random);
            (void)jrand_float(&m->entity_random[slot].random);
            m->fire_ticks[slot] = -1;
        }
    } else if (m->fire_ticks[slot] <= 0) {
        m->fire_ticks[slot] = -1;
    }
    return 0;
}

/* Entity.move dispatches block callbacks before its flammable tail. */
static int tick_exact_mob_cactus_contact(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot,
        GmLiveSim *drops, int do_mob_loot,
        uint64_t *math_random_seed48, int *next_entity_id) {
    if (m->controlled_no_ai[slot]
            || !mob_exact_environment_type(s->type[slot])
            || !s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F
            || !mob_slot_in_cactus_callback(m, w, s, slot))
        return 0;
    return mob_source_damage_environment_slot_exact(
               m, s, slot, 1.0F, drops, math_random_seed48,
               next_entity_id, do_mob_loot, 1, 0) < 0;
}

static int mob_block_fall_sound(int block) {
    int family = 3;
    switch (block) {
    case 5: case 17: case 25: case 26: case 47: case 50: case 53:
    case 54: case 58: case 63: case 64: case 68: case 69: case 72:
    case 75: case 76: case 85: case 86: case 91: case 93: case 94:
    case 96: case 99: case 100: case 103: case 104: case 105: case 107:
    case 125: case 126: case 127: case 134: case 135: case 136:
    case 143: case 146: case 147: case 148: case 149: case 150:
    case 151: case 162: case 163: case 164: case 176: case 177:
    case 178: case 183: case 184: case 185: case 186: case 187:
    case 188: case 189: case 190: case 191: case 192: case 193:
    case 194: case 195: case 196: case 197: case 198: case 199:
    case 200: case 214:
        family = 0; break;
    case 3: case 13: case 60: case 82: family = 1; break;
    case 2: case 6: case 18: case 19: case 31: case 32: case 37:
    case 38: case 39: case 40: case 46: case 59: case 83: case 106:
    case 110: case 111: case 141: case 142: case 161: case 170:
    case 175: case 207: case 208:
        family = 2; break;
    case 27: case 28: case 41: case 42: case 52: case 57: case 66:
    case 71: case 101: case 133: case 152: case 154: case 157:
    case 167:
        family = 4; break;
    case 20: case 79: case 89: case 90: case 95: case 102: case 120:
    case 123: case 124: case 160: case 169: case 174: case 212:
        family = 5; break;
    case 35: case 51: case 81: case 92: case 171: family = 6; break;
    case 12: case 88: family = 7; break;
    case 78: case 80: family = 8; break;
    case 65: family = 9; break;
    case 145: family = 10; break;
    case 165: family = 11; break;
    default: break;
    }
    return GM_MOB_SOUND_BLOCK_WOOD_FALL + family;
}

static int mob_block_step_sound(int block) {
    return GM_MOB_SOUND_BLOCK_WOOD_STEP
        + mob_block_fall_sound(block) - GM_MOB_SOUND_BLOCK_WOOD_FALL;
}

/* EntityLivingBase.updateFallState emits landing dust, delegates the block's
 * fall multiplier, and clears fallDistance inside Entity.move. The collision
 * spine already performed that final clear, so the caller supplies the
 * pre-move value when a downward collision changed onGround. */
static int make_living_landing_particles(
        const GmMobLive *m, const EwStore *s, int slot,
        float fall_distance, int block, int meta,
        GmMobParticleBatch *out) {
    if (!m || !s || !out || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot] || !s->on_ground[slot]
            || fall_distance <= 3.0F || block == 0)
        return 0;
    float height = (float)ceil((double)(fall_distance - 3.0F));
    double spread = fmin((double)(0.2F + height / 15.0F), 2.5D);
    *out = (GmMobParticleBatch){
        .eid = s->id[slot],
        .dimension = m->entity_dimension[slot],
        .particle_id = 38,
        .descriptor_count = (int)(150.0D * spread),
        .x = s->x[slot], .y = s->y[slot], .z = s->z[slot],
        .speed = 0.15000000596046448D,
        .parameter_count = 1,
        .parameters = {block | ((meta & 15) << 12), 0}
    };
    return 1;
}

/* EntityMob supplies hostile fall audio. Blaze and flying/magma entities
 * override fall() to do nothing; slime is hostile in the product taxonomy
 * but inherits EntityLivingBase's generic fall sound rather than EntityMob. */
static int mob_uses_hostile_fall(int type) {
    switch (type) {
    case EW_TYPE_ZOMBIE:
    case EW_TYPE_ZOMBIE_VILLAGER:
    case EW_TYPE_SKELETON:
    case EW_TYPE_WITHER_SKELETON:
    case EW_TYPE_CREEPER:
    case EW_TYPE_SPIDER:
    case EW_TYPE_CAVE_SPIDER:
    case EW_TYPE_PIGMAN:
    case EW_TYPE_SILVERFISH:
    case EW_TYPE_ENDERMITE:
    case EW_TYPE_ENDERMAN:
    case EW_TYPE_VINDICATOR:
    case EW_TYPE_EVOKER:
        return 1;
    default:
        return 0;
    }
}

static int mob_uses_generic_fall(int type) {
    return type == EW_TYPE_SHEEP || type == EW_TYPE_PIG
        || type == EW_TYPE_COW || type == EW_TYPE_MOOSHROOM
        || type == EW_TYPE_VILLAGER
        || gm_mobs_horse_type(type);
}

/* Exact fresh/nonfresh source-less damage for represented passive fall
 * families whose lethal loot lifecycle has not yet been promoted. */
static int mob_source_damage_living_nonlethal_exact(
        GmMobLive *m, EwStore *s, int slot, float damage,
        uint64_t *math_random_seed48, int set_been_attacked) {
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot]
            || (!mob_uses_hostile_fall(s->type[slot])
                && !mob_uses_generic_fall(s->type[slot]))
            || m->controlled_no_ai[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || damage <= 0.0F)
        return 0;
    int fresh = m->entity_hurt_resistant[slot] <= 10;
    if (!fresh && damage <= m->entity_last_damage[slot]) return 0;
    if (fresh && !math_random_seed48) return 0;
    float applied = fresh
        ? damage : damage - m->entity_last_damage[slot];
    applied = mob_resistance_damage(m, slot, applied);
    if (s->health[slot]
            <= mob_preview_absorbed_damage(m, slot, applied))
        return 0;

    applied = mob_absorb_damage(m, slot, applied);
    m->entity_age[slot] = 0;
    m->entity_last_damage[slot] = damage;
    if (fresh) {
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
    }
    s->health[slot] -= applied;
    if (fresh) {
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 2,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
        if (set_been_attacked)
            (void)jrand_double(&m->entity_random[slot].random);
        (void)mob_math_random_next_double(math_random_seed48);
        float first = jrand_float(&m->entity_random[slot].random);
        float second = jrand_float(&m->entity_random[slot].random);
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot],
            living_hurt_death_sound_event(
                m, slot, s->type[slot], m->size[slot], 0),
            s->x[slot], s->y[slot], s->z[slot],
            living_hurt_death_sound_volume(
                s->type[slot], m->size[slot]),
            living_hurt_death_sound_pitch(
                s->type[slot], (first - second) * 0.2F + 1.0F));
    }
    return 1;
}

/* EntityEnderman.attackEntityFrom teleports after an unblockable hit on nine
 * of ten private-RNG outcomes. attemptTeleport scans down to movement-blocking
 * support, rejects collision/liquid targets, consumes the 128 server-side
 * portal spawn descriptors, and clears navigation before either teleport
 * sound is emitted. The mob event stream represents the entity-sourced sound;
 * the source-less previous-position packet belongs to the wider world-audio
 * capture boundary. */
static int mob_attempt_enderman_random_teleport(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot) {
    if (!m || !w || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || s->type[slot] != EW_TYPE_ENDERMAN || !s->alive[slot])
        return 0;

    JavaRandom *random = &m->entity_random[slot].random;
    double target_x = s->x[slot]
        + (jrand_double(random) - 0.5D) * 64.0D;
    double target_y = s->y[slot]
        + (double)(jrand_int_bound(random, 64) - 32);
    double target_z = s->z[slot]
        + (jrand_double(random) - 0.5D) * 64.0D;
    int block_x = mc_floor(target_x);
    int block_y = mc_floor(target_y);
    int block_z = mc_floor(target_z);
    if (gm_world_biome(w, block_x, block_z) < 0) return 0;

    int found_support = 0;
    while (!found_support && block_y > 0) {
        if (solid_id(gm_world_block(w, block_x, block_y - 1, block_z))) {
            found_support = 1;
        } else {
            target_y -= 1.0D;
            --block_y;
        }
    }
    if (!found_support) return 0;

    float width, height;
    ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
    double half_width = (double)width * 0.5D;
    McAABB box = mc_aabb_make(
        target_x - half_width, target_y, target_z - half_width,
        target_x + half_width, target_y + (double)height,
        target_z + half_width);
    int x0 = mc_floor(box.minX), x1 = psv_ceil(box.maxX);
    int y0 = mc_floor(box.minY), y1 = psv_ceil(box.maxY);
    int z0 = mc_floor(box.minZ), z1 = psv_ceil(box.maxZ);
    for (int x = x0; x < x1; ++x)
        for (int y = y0; y < y1; ++y)
            for (int z = z0; z < z1; ++z) {
                int block = gm_world_block(w, x, y, z);
                if (!solid_id(block)
                        && block != 8 && block != 9
                        && block != 10 && block != 11)
                    continue;
                McAABB block_box = mc_aabb_make(
                    (double)x, (double)y, (double)z,
                    (double)x + 1.0D, (double)y + 1.0D,
                    (double)z + 1.0D);
                if (mc_aabb_intersects(&box, &block_box)) return 0;
            }

    s->x[slot] = target_x;
    s->y[slot] = target_y;
    s->z[slot] = target_z;
    m->entity_box_valid[slot] = 0;
    s->path_len[slot] = 0;
    for (int particle = 0; particle < 128; ++particle) {
        (void)jrand_float(random);
        (void)jrand_float(random);
        (void)jrand_float(random);
        (void)jrand_double(random);
        (void)jrand_double(random);
        (void)jrand_double(random);
    }
    mob_event_append(
        m, GM_MOB_EVENT_SOUND, s->id[slot],
        GM_MOB_SOUND_ENDERMAN_TELEPORT,
        s->x[slot], s->y[slot], s->z[slot], 1.0F, 1.0F);
    return 1;
}

static int mob_try_enderman_random_teleport(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot) {
    if (!m || !w || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || s->type[slot] != EW_TYPE_ENDERMAN || !s->alive[slot]
            || jrand_int_bound(&m->entity_random[slot].random, 10) == 0)
        return 0;
    return mob_attempt_enderman_random_teleport(m, w, s, slot);
}

static int tick_nonwitch_fall_landing(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot,
        float fall_distance, GmLiveSim *drops, int do_mob_loot,
        uint64_t *math_random_seed48, int *next_entity_id,
        PsvPlayer *player, PvStats *vitals) {
    if (!m || !w || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot] || s->type[slot] == EW_TYPE_WITCH
            || m->controlled_no_ai[slot] || !s->on_ground[slot]
            || fall_distance <= 0.0F)
        return 0;
    int x = mc_floor(s->x[slot]);
    int y = mc_floor(s->y[slot] - 0.20000000298023224);
    int z = mc_floor(s->z[slot]);
    int block = gm_world_block(w, x, y, z);
    int meta = gm_world_meta(w, x, y, z);
    GmMobParticleBatch landing;
    int has_landing = s->type[slot] == EW_TYPE_IRON_GOLEM ? 0
        : make_living_landing_particles(
            m, s, slot, fall_distance, block, meta, &landing);

    int hostile_fall = mob_uses_hostile_fall(s->type[slot]);
    int generic_fall = mob_uses_generic_fall(s->type[slot]);
    if (hostile_fall || generic_fall) {
        int horse_fall = gm_mobs_horse_type(s->type[slot]);
        float boost = mob_effect_amplifier(m, slot, 8) < 0
            ? 0.0F : (float)(mob_effect_amplifier(m, slot, 8) + 1);
        float multiplier = block == 170
            ? 0.2F : block == 165 ? 0.0F : 1.0F;
        int damage = (int)ceil(
            (double)(((horse_fall ? fall_distance * 0.5F : fall_distance)
                - 3.0F - boost) * multiplier));
        if (horse_fall && s->type[slot] != EW_TYPE_LLAMA
                && fall_distance > 1.0F)
            mob_event_append(
                m, GM_MOB_EVENT_SOUND, s->id[slot],
                GM_MOB_SOUND_HORSE_LAND,
                s->x[slot], s->y[slot], s->z[slot], 0.4F, 1.0F);
        if (damage > 0) {
            int result = 0;
            int fall_sound = horse_fall ? 0 : hostile_fall
                ? damage > 4 ? GM_MOB_SOUND_HOSTILE_BIG_FALL
                             : GM_MOB_SOUND_HOSTILE_SMALL_FALL
                : damage > 4 ? GM_MOB_SOUND_GENERIC_BIG_FALL
                             : GM_MOB_SOUND_GENERIC_SMALL_FALL;
            if (mob_exact_ordinary_death_type(s->type[slot])
                    || gm_passive(s->type[slot])) {
                result = gm_passive(s->type[slot])
                    ? mob_source_damage_passive_slot_exact(
                        m, s, slot, (float)damage, drops,
                        math_random_seed48, next_entity_id,
                        do_mob_loot, fall_sound, 1, 1, NULL)
                    : mob_source_damage_ordinary_slot_exact(
                        m, s, slot, (float)damage, drops,
                        math_random_seed48, next_entity_id,
                        do_mob_loot, fall_sound, 1, 1, NULL);
            } else {
                mob_event_append(
                    m, GM_MOB_EVENT_SOUND, s->id[slot], fall_sound,
                    s->x[slot], s->y[slot], s->z[slot], 1.0F, 1.0F);
                (void)mob_source_damage_living_nonlethal_exact(
                    m, s, slot, (float)damage,
                    math_random_seed48, 1);
            }
            /* AbstractHorse.fall damages its complete passenger tree after
             * damaging the horse. The represented local player is the only
             * non-trap horse passenger in this store. FALL bypasses armor. */
            if (horse_fall && ride_is_slot(s, slot, m->horse_ride_eid)
                    && player && vitals) {
                (void)gm_mobs_attack_player_source(
                    m, (struct PvStats *)vitals,
                    (struct IsrInv *)&player->inv, (float)damage, 1,
                    GM_DAMAGE_SOURCE_FALL);
                player->health = vitals->health;
            }
            if (horse_fall && m->skeleton_trap_rider_eid[slot] >= 0) {
                int rider = mob_slot_by_eid(
                    m, m->skeleton_trap_rider_eid[slot]);
                if (rider > 0)
                    (void)mob_source_damage_living_nonlethal_exact(
                        m, s, rider, (float)damage,
                        math_random_seed48, 1);
            }
            if (result < 0) return 1;
            int teleported = s->type[slot] == EW_TYPE_ENDERMAN
                && mob_try_enderman_random_teleport(m, w, s, slot);
            int support_x = mc_floor(s->x[slot]);
            int support_y = mc_floor(
                s->y[slot] - 0.20000000298023224D);
            int support_z = mc_floor(s->z[slot]);
            int support_block = teleported
                ? gm_world_block(w, support_x, support_y, support_z) : block;
            if (support_block != 0)
                mob_event_append(
                    m, GM_MOB_EVENT_SOUND, s->id[slot],
                    mob_block_fall_sound(support_block),
                    s->x[slot], s->y[slot], s->z[slot],
                    support_block == 145 ? 0.15F : 0.5F,
                    support_block == 42 || support_block == 71
                            || support_block == 101
                            || support_block == 167 ? 1.125F : 0.75F);
            if (teleported && block != 0)
                mob_event_append(
                    m, GM_MOB_EVENT_SOUND, s->id[slot],
                    mob_block_step_sound(block),
                    s->x[slot], s->y[slot], s->z[slot],
                    0.15F, block == 42 || block == 71
                            || block == 101 || block == 167
                        ? 1.5F : 1.0F);
        }
        if (s->type[slot] == EW_TYPE_CREEPER) {
            m->creeper_fuse[slot] = (int)(
                (float)m->creeper_fuse[slot] + fall_distance * 1.5F);
            if (m->creeper_fuse[slot] > 25)
                m->creeper_fuse[slot] = 25;
        }
    }
    if (has_landing) mob_particle_batch_append(m, &landing);
    return 0;
}

static int tick_witch_fall_landing(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot,
        float fall_distance, GmLiveSim *drops, int do_mob_loot,
        int mob_griefing,
        uint64_t *world_random_seed48, uint64_t *math_random_seed48,
        int *next_entity_id) {
    if (!m || !w || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot] || s->type[slot] != EW_TYPE_WITCH
            || m->controlled_no_ai[slot] || !s->on_ground[slot]
            || fall_distance <= 0.0F)
        return 0;
    int x = mc_floor(s->x[slot]);
    int y = mc_floor(s->y[slot] - 0.20000000298023224);
    int z = mc_floor(s->z[slot]);
    int block = gm_world_block(w, x, y, z);
    int meta = gm_world_meta(w, x, y, z);
    GmMobParticleBatch landing = {0};
    int has_landing = make_living_landing_particles(
        m, s, slot, fall_distance, block, meta, &landing);
    int farmland_draw = 0;
    int trample = 0;
    uint64_t staged_world_seed48 = 0;
    /* Entity.canTrample draws World.rand before checking mobGriefing and the
     * Witch's size. An accepted mutation occurs before EntityLivingBase.fall
     * queries the support block's sound. */
    if (block == 60 && world_random_seed48) {
        JavaRandom random = {*world_random_seed48};
        trample = jrand_float(&random) < fall_distance - 0.5F
            && mob_griefing;
        staged_world_seed48 = random.seed;
        farmland_draw = 1;
        if (trample) block = 3;
    }
    float boost = mob_effect_amplifier(m, slot, 8) < 0
        ? 0.0F : (float)(mob_effect_amplifier(m, slot, 8) + 1);
    float multiplier = block == 170 ? 0.2F : block == 165 ? 0.0F : 1.0F;
    int damage = (int)ceil(
        (double)((fall_distance - 3.0F - boost) * multiplier));
    if (damage <= 0) {
        if (farmland_draw) {
            *world_random_seed48 = staged_world_seed48;
            if (trample) gm_world_set_block(w, x, y, z, 3);
        }
        if (has_landing) mob_particle_batch_append(m, &landing);
        return 0;
    }
    int result = mob_source_damage_witch_slot_exact(
        m, s, slot, (float)damage, drops, math_random_seed48,
        next_entity_id, do_mob_loot,
        damage > 4 ? GM_MOB_SOUND_HOSTILE_BIG_FALL
                   : GM_MOB_SOUND_HOSTILE_SMALL_FALL,
        NULL);
    if (result < 0) return 1;
    if (farmland_draw) {
        *world_random_seed48 = staged_world_seed48;
        if (trample) gm_world_set_block(w, x, y, z, 3);
    }
    if (has_landing) mob_particle_batch_append(m, &landing);
    mob_event_append(
        m, GM_MOB_EVENT_SOUND, s->id[slot], mob_block_fall_sound(block),
        s->x[slot], s->y[slot], s->z[slot],
        block == 145 ? 0.15F : 0.5F,
        block == 42 || block == 71 || block == 101 || block == 167
            ? 1.125F : 0.75F);
    return 0;
}

/* Server-side EntityLivingBase.attackEntityFrom for environment fire/lava.
 * The mounted client has a separate Entity instance and RNG stream, so these
 * sound draws stay on the server cursor. */
static int ridden_pig_environment_damage(
        GmMobLive *m, EwStore *s, int slot, float damage, int is_fire_damage,
        double event_x, double event_y, double event_z,
        uint64_t *math_random_seed48) {
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot] || s->health[slot] <= 0.0F
            || damage <= 0.0F)
        return 0;
    m->entity_age[slot] = 0;
    if (!pec_fire_resist_blocks(
            is_fire_damage,
            m->entity_server_fire_resistance_ticks[slot] > 0))
        return 0;
    int fresh = m->entity_hurt_resistant[slot] <= 10;
    if (!fresh && damage <= m->entity_last_damage[slot]) return 0;
    float applied = fresh
        ? damage : damage - m->entity_last_damage[slot];
    m->entity_last_damage[slot] = damage;
    if (fresh) {
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
        m->entity_max_hurt_time[slot] = 10;
    }
    s->health[slot] -= applied;
    if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
    mark_hurt(m, s, slot);
    if (fresh) {
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 2,
            event_x, event_y, event_z, 0.0F, 0.0F);
        (void)jrand_double(&m->entity_server_random[slot].random);
        if (math_random_seed48)
            (void)mob_math_random_next_double(math_random_seed48);
        m->entity_server_living_sound_time[slot] = -80;
        (void)jrand_float(&m->entity_server_random[slot].random);
        (void)jrand_float(&m->entity_server_random[slot].random);
    }
    return 1;
}

/* Entity.onEntityUpdate fire phase followed by lava contact. This is the
 * authoritative-server half of an active ridden pig tick. */
static void tick_ridden_pig_server_fire_lava(
        GmMobLive *m, EwStore *s, int slot, int in_lava,
        double event_x, double event_y, double event_z,
        uint64_t *math_random_seed48) {
    if (m->fire_ticks[slot] > 0) {
        if (m->fire_ticks[slot] % 20 == 0)
            (void)ridden_pig_environment_damage(
                m, s, slot, 1.0F, 1,
                event_x, event_y, event_z, math_random_seed48);
        --m->fire_ticks[slot];
    }
    if (in_lava && s->health[slot] > 0.0F) {
        (void)ridden_pig_environment_damage(
            m, s, slot, 4.0F, 1,
            event_x, event_y, event_z, math_random_seed48);
        if (m->fire_ticks[slot] < 15 * 20)
            m->fire_ticks[slot] = 15 * 20;
        m->entity_server_fall_distance[slot] *= 0.5F;
    }
}

static void tick_ridden_pig_server_ambient(
        GmMobLive *m, const EwStore *s, int slot) {
    if (s->health[slot] > 0.0F
            && jrand_int_bound(
                &m->entity_server_random[slot].random, 1000)
                < m->entity_server_living_sound_time[slot]++) {
        m->entity_server_living_sound_time[slot] = -80;
        (void)jrand_float(&m->entity_server_random[slot].random);
        (void)jrand_float(&m->entity_server_random[slot].random);
    }
}

static int pig_vehicle_box_in_liquid(
        const struct Chunk *window, int ox, int oz,
        const McAABB *box, int water) {
    if (!window || !box) return 0;
    McEntity local;
    memset(&local, 0, sizeof local);
    local.box = *box;
    local.box.minX -= ox;
    local.box.maxX -= ox;
    local.box.minZ -= oz;
    local.box.maxZ -= oz;
    return psv_in_liquid((const Chunk *)window, &local, water ? 1 : 0);
}

static int pig_vehicle_server_in_liquid(
        const struct Chunk *window, int ox, int oz,
        const GmPigVehicleServerState *server, int water) {
    return server && server->valid && pig_vehicle_box_in_liquid(
        window, ox, oz, &server->box, water);
}

static void ridden_pig_water_entry_rng(JavaRandom *random, float width);

static float ridden_pig_slot_width(
        const GmMobLive *m, const EwStore *s, int slot) {
    float width, height;
    ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
    if (gm_passive(s->type[slot]) && m->growing_age[slot] < 0)
        width *= 0.5F;
    return width;
}

/* Authoritative EntityPig base phase after processVehicleMove. The controlling
 * EntityPlayerMP can hold the steering item but is never the local user, so
 * the ridden branch aligns rotation and zeros server motion without running
 * client-predicted travel. Environment probes use the independent server AABB. */
static void tick_ridden_pig_vehicle_server_base(
        GmMobLive *m, EwStore *s, int slot,
        const struct Chunk *window, int ox, int oz,
        int can_be_steered, float rider_yaw, float rider_pitch,
        uint64_t *math_random_seed48) {
    GmPigVehicleServerState *server = &m->pig_vehicle_server;
    if (!server->valid || server->eid != s->id[slot]) return;
    int was_in_water = m->entity_server_in_water[slot] ? 1 : 0;
    m->entity_server_in_water[slot] = (unsigned char)(
        pig_vehicle_server_in_liquid(window, ox, oz, server, 1) ? 1 : 0);
    if (!was_in_water && m->entity_server_in_water[slot]
            && !server->first_update) {
        ridden_pig_water_entry_rng(
            &m->entity_server_random[slot].random,
            ridden_pig_slot_width(m, s, slot));
    }
    if (m->entity_server_in_water[slot]) {
        server->fall_distance = 0.0F;
        m->fire_ticks[slot] = 0;
    }
    m->entity_server_in_lava[slot] = (unsigned char)(
        pig_vehicle_server_in_liquid(window, ox, oz, server, 0) ? 1 : 0);
    m->entity_server_fall_distance[slot] = server->fall_distance;
    tick_ridden_pig_server_fire_lava(
        m, s, slot, m->entity_server_in_lava[slot],
        server->x, server->y, server->z, math_random_seed48);
    server->fall_distance = m->entity_server_fall_distance[slot];
    if (can_be_steered) {
        server->yaw = rider_yaw;
        server->pitch = rider_pitch * 0.5F;
        server->vx = 0.0;
        server->vy = 0.0;
        server->vz = 0.0;
    }
    server->first_update = 0;
    /* NetHandlerPlayServer.update re-seeds both vehicle baselines once per
     * network tick, after the ordinary world entity pass. Packets received
     * during the next tick retain this common epoch origin while accepted
     * packets advance only the secondary baseline. */
    server->lowest_x = server->lowest_x1 = server->x;
    server->lowest_y = server->lowest_y1 = server->y;
    server->lowest_z = server->lowest_z1 = server->z;
}

/* Entity.resetHeight consumes the pig's private RNG when a dry EntityLivingBase
 * enters water during move().  Particle output is outside the simulation
 * contract, but preserving these draws keeps every later gameplay RNG choice
 * aligned with the Java entity. */
static void ridden_pig_water_entry_rng(
        JavaRandom *random, float width) {
    float particle_count = 1.0F + width * 20.0F;
    (void)jrand_float(random);
    (void)jrand_float(random);
    for (int i = 0; (float)i < particle_count; ++i) {
        (void)jrand_float(random);
        (void)jrand_float(random);
        (void)jrand_float(random);
    }
    for (int i = 0; (float)i < particle_count; ++i) {
        (void)jrand_float(random);
        (void)jrand_float(random);
    }
}

/* Entity.move without updateFallState.  EntityLivingBase interposes its
 * post-move water probe before delegating to Entity.updateFallState, so the
 * active ridden land path needs this exact split point. */
static double ridden_pig_move_aabb_before_fall(
        EntBody *body, double x, double y, double z,
        const McAABB *blocks, int nblocks) {
    if (body->phys.isInWeb) {
        body->phys.isInWeb = 0;
        x *= 0.25;
        y *= 0.05000000074505806;
        z *= 0.25;
        body->phys.motionX = 0.0;
        body->phys.motionY = 0.0;
        body->phys.motionZ = 0.0;
    }
    McEntity exact;
    exact.box = body->phys.box;
    exact.posX = body->phys.posX;
    exact.posY = body->phys.posY;
    exact.posZ = body->phys.posZ;
    exact.motionX = body->phys.motionX;
    exact.motionY = body->phys.motionY;
    exact.motionZ = body->phys.motionZ;
    exact.onGround = body->phys.onGround;
    exact.collidedHorizontally = body->phys.collidedHorizontally;
    exact.collidedVertically = body->phys.collidedVertically;
    exact.isCollided = body->phys.isCollided;
    double before_y = exact.posY;
    mc_entity_move_step(
        &exact, x, y, z, blocks, nblocks, body->phys.stepHeight);
    body->phys.box = exact.box;
    body->phys.posX = exact.posX;
    body->phys.posY = exact.posY;
    body->phys.posZ = exact.posZ;
    body->phys.motionX = exact.motionX;
    body->phys.motionY = exact.motionY;
    body->phys.motionZ = exact.motionZ;
    body->phys.onGround = exact.onGround;
    body->phys.collidedHorizontally = exact.collidedHorizontally;
    body->phys.collidedVertically = exact.collidedVertically;
    body->phys.isCollided = exact.isCollided;
    return exact.posY - before_y;
}

/* Bounded client-controlled pig land branch with the
 * EntityLivingBase.updateFallState water interposition point. */
static void tick_ridden_pig_land_water_entry(
        const struct Chunk *window, int ox, int oz,
        const McSinTable *st, GmMobLive *m, int slot, EbLiving *liv,
        float ground_slip, int movement_blocked,
        McAABB *collision_boxes, int nboxes,
        int (*contact_cells)[4], int ncontacts) {
    eb_on_entity_update(&liv->base);
    if (liv->jumpTicks > 0) --liv->jumpTicks;
    if (!liv->isServerWorld) {
        liv->base.phys.motionX *= 0.98;
        liv->base.phys.motionY *= 0.98;
        liv->base.phys.motionZ *= 0.98;
    }
    if (fabs(liv->base.phys.motionX) < 0.003)
        liv->base.phys.motionX = 0.0;
    if (fabs(liv->base.phys.motionY) < 0.003)
        liv->base.phys.motionY = 0.0;
    if (fabs(liv->base.phys.motionZ) < 0.003)
        liv->base.phys.motionZ = 0.0;
    if (movement_blocked) {
        liv->isJumping = 0;
        liv->moveStrafing = 0.0F;
        liv->moveForward = 0.0F;
        liv->randomYawVelocity = 0.0F;
    }
    if (liv->isJumping) {
        if (liv->base.phys.onGround && liv->jumpTicks == 0) {
            elb_jump(liv, st);
            liv->jumpTicks = 10;
        }
    } else {
        liv->jumpTicks = 0;
    }
    liv->moveStrafing *= 0.98F;
    liv->moveForward *= 0.98F;
    liv->randomYawVelocity *= 0.9F;
    if (!liv->isServerWorld) {
        ++liv->base.ticksExisted;
        return;
    }

    int on_ground = liv->base.phys.onGround;
    float f6 = on_ground ? (ground_slip * 0.91F) : 0.91F;
    float f7 = 0.16277136F / (f6 * f6 * f6);
    float f8 = on_ground
        ? liv->landMovementFactor * f7 : liv->jumpMovementFactor;
    eb_move_relative(
        &liv->base, liv->moveStrafing, liv->moveForward, f8, st);
    if (elb_is_on_ladder_contacts(liv, contact_cells, ncontacts)) {
        const double ladder_speed = 0.15000000596046448;
        if (liv->base.phys.motionX < -ladder_speed)
            liv->base.phys.motionX = -ladder_speed;
        if (liv->base.phys.motionX > ladder_speed)
            liv->base.phys.motionX = ladder_speed;
        if (liv->base.phys.motionZ < -ladder_speed)
            liv->base.phys.motionZ = -ladder_speed;
        if (liv->base.phys.motionZ > ladder_speed)
            liv->base.phys.motionZ = ladder_speed;
        liv->base.fallDistance = 0.0F;
        if (liv->base.phys.motionY < -0.15)
            liv->base.phys.motionY = -0.15;
    }
    f6 = on_ground ? (ground_slip * 0.91F) : 0.91F;
    double landing_motion_y = liv->base.phys.isInWeb
        ? 0.0 : liv->base.phys.motionY;
    double resolved_y = ridden_pig_move_aabb_before_fall(
        &liv->base, liv->base.phys.motionX, liv->base.phys.motionY,
        liv->base.phys.motionZ, collision_boxes, nboxes);
    int entered_water = ridden_pig_handle_water(window, ox, oz, liv);
    eb_update_fall_state(&liv->base, resolved_y);
    if (entered_water) {
        m->entity_in_water[slot] = 1;
        ridden_pig_water_entry_rng(
            &m->entity_random[slot].random, liv->base.width);
    }
    elb_apply_landing_contact(
        liv, landing_motion_y, contact_cells, ncontacts);
    elb_apply_block_contacts(liv, contact_cells, ncontacts);
    if (liv->base.phys.collidedHorizontally
            && elb_is_on_ladder_contacts(
                liv, contact_cells, ncontacts))
        liv->base.phys.motionY = 0.2;
    if (!liv->base.hasNoGravity) liv->base.phys.motionY -= 0.08;
    liv->base.phys.motionY *= 0.9800000190734863;
    liv->base.phys.motionX *= (double)f6;
    liv->base.phys.motionZ *= (double)f6;
    ++liv->base.ticksExisted;
}

/* Bounded client-controlled pig water branch. AI swimming and particles are
 * outside this path; collision, callbacks, drag, gravity, and edge climb keep
 * the exact 1.11.2 EntityLivingBase ordering. */
static void tick_ridden_pig_water(
        const struct Chunk *window, int ox, int oz,
        const McSinTable *st, EbLiving *liv, int movement_blocked,
        McAABB *collision_boxes, int (*contact_cells)[4]) {
    eb_on_entity_update(&liv->base);
    if (liv->jumpTicks > 0) --liv->jumpTicks;

    if (fabs(liv->base.phys.motionX) < 0.003)
        liv->base.phys.motionX = 0.0;
    if (fabs(liv->base.phys.motionY) < 0.003)
        liv->base.phys.motionY = 0.0;
    if (fabs(liv->base.phys.motionZ) < 0.003)
        liv->base.phys.motionZ = 0.0;

    if (movement_blocked) {
        liv->isJumping = 0;
        liv->moveStrafing = 0.0F;
        liv->moveForward = 0.0F;
        liv->randomYawVelocity = 0.0F;
    }
    if (liv->isJumping)
        liv->base.phys.motionY += 0.03999999910593033;
    else
        liv->jumpTicks = 0;

    liv->moveStrafing *= 0.98F;
    liv->moveForward *= 0.98F;
    liv->randomYawVelocity *= 0.9F;
    double old_y = liv->base.phys.posY;
    eb_move_relative(
        &liv->base, liv->moveStrafing, liv->moveForward, 0.02F, st);

    McAABB query = mc_aabb_addcoord(
        &liv->base.phys.box, liv->base.phys.motionX,
        liv->base.phys.motionY, liv->base.phys.motionZ);
    query.minY -= liv->base.phys.stepHeight;
    query.maxY += liv->base.phys.stepHeight;
    McAABB local_query = query;
    local_query.minX -= ox;
    local_query.maxX -= ox;
    local_query.minZ -= oz;
    local_query.maxZ -= oz;
    int n = psv_collect_blocks(
        (const Chunk *)window, &local_query,
        collision_boxes, GM_PIG_COLLISION_BOXES);
    for (int box = 0; box < n; ++box) {
        collision_boxes[box].minX += ox;
        collision_boxes[box].maxX += ox;
        collision_boxes[box].minZ += oz;
        collision_boxes[box].maxZ += oz;
    }
    int ncontacts = collect_block_contact_cells(
        window, &query, ox, oz, contact_cells, GM_PIG_COLLISION_BOXES);
    double landing_motion_y = liv->base.phys.isInWeb
        ? 0.0 : liv->base.phys.motionY;
    eb_move_aabb(
        &liv->base, liv->base.phys.motionX, liv->base.phys.motionY,
        liv->base.phys.motionZ, collision_boxes, n);
    elb_apply_landing_contact(
        liv, landing_motion_y, contact_cells, ncontacts);
    elb_apply_block_contacts(liv, contact_cells, ncontacts);

    liv->base.phys.motionX *= (double)0.8F;
    liv->base.phys.motionY *= 0.800000011920929;
    liv->base.phys.motionZ *= (double)0.8F;
    if (!liv->base.hasNoGravity) liv->base.phys.motionY -= 0.02;
    if (liv->base.phys.collidedHorizontally) {
        McEntity local = ridden_pig_local_entity(liv, ox, oz);
        if (psv_offset_in_liquid(
                (const Chunk *)window, &local,
                local.motionX,
                local.motionY + 0.6000000238418579
                    - local.posY + old_y,
                local.motionZ, collision_boxes))
            liv->base.phys.motionY = 0.30000001192092896;
    }
    ++liv->base.ticksExisted;
}

/* Bounded client-controlled pig lava branch. Lava has no current, uses 0.5
 * drag on all axes, and otherwise shares the liquid collision ordering. */
static void tick_ridden_pig_lava(
        const struct Chunk *window, int ox, int oz,
        const McSinTable *st, EbLiving *liv, int movement_blocked,
        McAABB *collision_boxes, int (*contact_cells)[4]) {
    eb_on_entity_update(&liv->base);
    if (liv->jumpTicks > 0) --liv->jumpTicks;

    if (fabs(liv->base.phys.motionX) < 0.003)
        liv->base.phys.motionX = 0.0;
    if (fabs(liv->base.phys.motionY) < 0.003)
        liv->base.phys.motionY = 0.0;
    if (fabs(liv->base.phys.motionZ) < 0.003)
        liv->base.phys.motionZ = 0.0;

    if (movement_blocked) {
        liv->isJumping = 0;
        liv->moveStrafing = 0.0F;
        liv->moveForward = 0.0F;
        liv->randomYawVelocity = 0.0F;
    }
    if (liv->isJumping)
        liv->base.phys.motionY += 0.03999999910593033;
    else
        liv->jumpTicks = 0;

    liv->moveStrafing *= 0.98F;
    liv->moveForward *= 0.98F;
    liv->randomYawVelocity *= 0.9F;
    double old_y = liv->base.phys.posY;
    eb_move_relative(
        &liv->base, liv->moveStrafing, liv->moveForward, 0.02F, st);

    McAABB query = mc_aabb_addcoord(
        &liv->base.phys.box, liv->base.phys.motionX,
        liv->base.phys.motionY, liv->base.phys.motionZ);
    query.minY -= liv->base.phys.stepHeight;
    query.maxY += liv->base.phys.stepHeight;
    McAABB local_query = query;
    local_query.minX -= ox;
    local_query.maxX -= ox;
    local_query.minZ -= oz;
    local_query.maxZ -= oz;
    int n = psv_collect_blocks(
        (const Chunk *)window, &local_query,
        collision_boxes, GM_PIG_COLLISION_BOXES);
    for (int box = 0; box < n; ++box) {
        collision_boxes[box].minX += ox;
        collision_boxes[box].maxX += ox;
        collision_boxes[box].minZ += oz;
        collision_boxes[box].maxZ += oz;
    }
    int ncontacts = collect_block_contact_cells(
        window, &query, ox, oz, contact_cells, GM_PIG_COLLISION_BOXES);
    double landing_motion_y = liv->base.phys.isInWeb
        ? 0.0 : liv->base.phys.motionY;
    eb_move_aabb(
        &liv->base, liv->base.phys.motionX, liv->base.phys.motionY,
        liv->base.phys.motionZ, collision_boxes, n);
    elb_apply_landing_contact(
        liv, landing_motion_y, contact_cells, ncontacts);
    elb_apply_block_contacts(liv, contact_cells, ncontacts);

    liv->base.phys.motionX *= 0.5;
    liv->base.phys.motionY *= 0.5;
    liv->base.phys.motionZ *= 0.5;
    if (!liv->base.hasNoGravity) liv->base.phys.motionY -= 0.02;
    if (liv->base.phys.collidedHorizontally) {
        McEntity local = ridden_pig_local_entity(liv, ox, oz);
        if (psv_offset_in_liquid(
                (const Chunk *)window, &local,
                local.motionX,
                local.motionY + 0.6000000238418579
                    - local.posY + old_y,
                local.motionZ, collision_boxes))
            liv->base.phys.motionY = 0.30000001192092896;
    }
    ++liv->base.ticksExisted;
}

static void move_mob(
        GmWorld *w, const struct Chunk *window, int ox, int oz,
        const McSinTable *st, GmMobLive *m, EwStore *s,
        int i, int moving, int jump, int animal_move_helper,
        int ridden_pig, int steerable,
        float rider_yaw, float rider_pitch, int movement_blocked,
        int swim_jump, double nav_speed) {
    EhsIntent intent;
    EbLiving liv;
    PcfBlock blocks[GM_MOB_BLOCKS];
    double old_x = s->x[i], old_z = s->z[i];
    int exact_box = m->entity_box_valid[i] != 0;
    int ridden_horse = gm_mobs_horse_type(s->type[i])
        && ride_is_slot(s, i, m->horse_ride_eid);
    int steerable_horse = ridden_horse
        && (m->horse_status[i] & GM_HORSE_SADDLED);
    double movement_multiplier = mob_movement_effect_multiplier(m, i);
    ehs_intent_from_ai(s->type[i], s->ai_state[i], moving, s->x[i], s->z[i],
                       s->path_tx[i], s->path_tz[i], s->path_tx[i], s->path_tz[i], &intent);
    if (moving && animal_move_helper) {
        /* EntityMoveHelper.setAIMoveSpeed writes both landMovementFactor and
         * moveForward. With EntityAIMate speed=1 these are the animal's exact
         * MOVEMENT_SPEED attribute, rather than the old unit-forward proxy. */
        intent.moveForward = (float)(
            (gm_mobs_horse_type(s->type[i])
                ? m->horse_movement_speed[i]
                : (double)animal_mating_movement_speed(s->type[i]))
            * (animal_move_helper == 2 ? 1.2D : 1.0D)
            * movement_multiplier);
        intent.yaw = mob_move_helper_yaw(
            s->yaw[i], s->path_tx[i] - s->x[i],
            s->path_tz[i] - s->z[i]);
    }
    if (!moving) intent.yaw = s->yaw[i];
    if (moving && gm_mobs_horse_type(s->type[i])
            && m->skeleton_trap_rider_eid[i] >= 0)
        intent.yaw = mob_move_helper_yaw(
            s->yaw[i], s->path_tx[i] - s->x[i],
            s->path_tz[i] - s->z[i]);
    if (moving && s->type[i] == EW_TYPE_LLAMA && !animal_move_helper)
        intent.yaw = mob_move_helper_yaw(
            s->yaw[i], s->path_tx[i] - s->x[i],
            s->path_tz[i] - s->z[i]);
    if ((gm_passive(s->type[i])
            || (s->type[i] == EW_TYPE_SKELETON
                && m->skeleton_trap_vehicle_eid[i] >= 0))
            && moving)
        intent.yaw = pai_update_rotation(s->yaw[i], intent.yaw, 90.0f);
    if (moving && jump) intent.isJumping = 1;
    if (ridden_pig) {
        /* EntityLivingBase damps its AI inputs by .98 before virtual travel,
         * but EntityPig's steerable override ignores those arguments and
         * calls super.moveEntityWithHeading(0, 1).  Seed the shared spine so
         * its damping produces that exact unit forward input. */
        intent.moveForward = steerable ? (1.0F / 0.98F) : 0.0F;
        intent.moveStrafing = 0.0F;
        intent.isJumping = 0;
        intent.yaw = steerable ? rider_yaw : s->yaw[i];
    }
    if (steerable_horse) {
        float forward = m->horse_input_forward;
        if (forward <= 0.0F) forward *= 0.25F;
        intent.moveForward = forward;
        intent.moveStrafing = m->horse_input_strafe * 0.5F;
        intent.isJumping = 0;
        intent.yaw = rider_yaw;
        s->yaw[i] = rider_yaw;
        m->passive_head_yaw[i] = rider_yaw;
        m->passive_head_pitch[i] = rider_pitch * 0.5F;
    }
    if (s->type[i] == EW_TYPE_SKELETON
            && m->skeleton_trap_vehicle_eid[i] >= 0 && moving) {
        if (m->skeleton_trap_bow_running[i]
                && m->skeleton_trap_target_eid[i] >= 0
                && m->passive_eat_time[i] >= 0) {
            /* Bow strafing uses EntityMoveHelper.STRAFE: raw +/-0.5 inputs,
             * with a separate 0.25*MOVEMENT_SPEED land factor. Its
             * faceEntity call uses MathHelper.atan2 and a 30-degree clamp;
             * libc atan2 can select the adjacent render sine-table entry. */
            float target_yaw = (float)(mob_java_math_atan2(
                s->path_tz[i] - s->z[i],
                s->path_tx[i] - s->x[i])
                * (180.0D / MC_PI)) - 90.0F;
            intent.yaw = pai_update_rotation(
                s->yaw[i], target_yaw, 30.0F);
            intent.moveForward = (m->passive_tasks[i] & (1u << 17))
                ? -0.5F : 0.5F;
            intent.moveStrafing = (m->passive_tasks[i] & (1u << 16))
                ? 0.5F : -0.5F;
        } else {
            /* Navigator MOVE_TO writes the skeleton's 0.25 attribute. */
            intent.moveForward = ehs_land_speed(EW_TYPE_SKELETON);
        }
    }
    if (s->type[i] == EW_TYPE_SKELETON
            && m->skeleton_trap_vehicle_eid[i] >= 0) {
        int bow_strafing = moving
            && m->skeleton_trap_bow_running[i]
            && m->skeleton_trap_target_eid[i] >= 0
            && m->passive_eat_time[i] >= 0;
        /* EntityMoveHelper WAIT and MOVE_TO zero/replace moveForward but do
         * not touch moveStrafing. Its previous damped value therefore
         * survives a bow reset and the following approach phase. */
        if (!bow_strafing)
            intent.moveStrafing = m->passive_move_strafe[i];
        if (!moving)
            intent.moveForward = 0.0F;
    }
    ehs_load_living(&liv, s, i, &intent);
    if (s->type[i] == EW_TYPE_SKELETON
            && m->skeleton_trap_vehicle_eid[i] >= 0
            && m->passive_eat_time[i] >= 0)
        liv.landMovementFactor = 0.0625F;
    liv.jumpBoostAmplifier = mob_effect_amplifier(m, i, 8);
    liv.levitationAmplifier = mob_effect_amplifier(m, i, 25);
    /* AbstractHorse raises EntityLivingBase's constructor default from 0.6
     * to 1.0 for every horse-family entity, not only a player-ridden one. */
    if (gm_mobs_horse_type(s->type[i]))
        liv.base.phys.stepHeight = 1.0F;
    if (steerable_horse) {
        float forward = m->horse_input_forward;
        if (forward <= 0.0F) forward *= 0.25F;
        liv.moveForward = forward;
        liv.moveStrafing = m->horse_input_strafe * 0.5F;
        liv.landMovementFactor = (float)m->horse_movement_speed[i];
        liv.isJumping = 0;
        if (liv.base.phys.onGround) {
            m->horse_jumping[i] = 0;
            if (m->horse_jump_power[i] > 0.0F) {
                float power = m->horse_jump_power[i];
                liv.base.phys.motionY = m->horse_jump_strength[i];
                if (liv.jumpBoostAmplifier >= 0)
                    liv.base.phys.motionY +=
                        0.1D * (double)(liv.jumpBoostAmplifier + 1);
                m->horse_jumping[i] = 1;
                if (forward > 0.0F) {
                    float radians = rider_yaw * 0.017453292F;
                    liv.base.phys.motionX += (double)(
                        -0.4F * mc_sin(st, radians) * power);
                    liv.base.phys.motionZ += (double)(
                        0.4F * mc_cos(st, radians) * power);
                }
                mob_event_append(
                    m, GM_MOB_EVENT_SOUND, s->id[i],
                    GM_MOB_SOUND_HORSE_JUMP,
                    s->x[i], s->y[i], s->z[i], 0.4F, 1.0F);
                m->horse_jump_power[i] = 0.0F;
            }
        }
    }
    if (exact_box) {
        liv.base.phys.box = mc_aabb_make(
            m->entity_box_min_x[i], m->entity_box_min_y[i],
            m->entity_box_min_z[i], m->entity_box_max_x[i],
            m->entity_box_max_y[i], m->entity_box_max_z[i]);
    }
    liv.base.fallDistance = m->entity_fall_distance[i];
    liv.base.phys.collidedHorizontally =
        m->entity_collided_horizontal[i] ? 1 : 0;
    liv.base.phys.collidedVertically =
        m->entity_collided_vertical[i] ? 1 : 0;
    liv.base.phys.isInWeb = m->entity_in_web[i] ? 1 : 0;
    int ridden_in_water = 0;
    int ridden_in_lava = 0;
    if (ridden_pig && window) {
        ridden_in_water = ridden_pig_handle_water(
            window, ox, oz, &liv);
        int is_in_lava = ridden_pig_in_lava(window, ox, oz, &liv);
        ridden_in_lava = !ridden_in_water && is_in_lava;
        m->entity_in_water[i] = (unsigned char)(ridden_in_water ? 1 : 0);
        m->entity_in_lava[i] = (unsigned char)(is_in_lava ? 1 : 0);
    }
    if (moving && animal_move_helper)
        liv.landMovementFactor = intent.moveForward;
    if (ridden_pig) {
        m->pig_step_height[i] = steerable ? 1.0F : 0.5F;
        m->pig_jump_factor[i] = steerable
            ? m->pig_ai_speed[i] * 0.1F : 0.02F;
        liv.base.phys.stepHeight = m->pig_step_height[i];
        liv.jumpMovementFactor = m->pig_jump_factor[i];
        if (steerable) {
            /* The local EntityPlayerSP owns vehicle travel in 1.11.2. Its
             * remote EntityLivingBase branch damps existing motion before
             * EntityPig invokes the steerable super travel call. */
            liv.base.phys.motionX *= 0.98D;
            liv.base.phys.motionY *= 0.98D;
            liv.base.phys.motionZ *= 0.98D;
            float speed = 0.25F * 0.225F;
            m->pig_prev_yaw[i] = rider_yaw;
            m->pig_pitch[i] = rider_pitch * 0.5F;
            m->pig_render_yaw[i] = rider_yaw;
            m->pig_head_yaw[i] = rider_yaw;
            if (m->pig_boosting[i]
                    && m->pig_boost_time[i]++ > m->pig_boost_total[i])
                m->pig_boosting[i] = 0;
            if (m->pig_boosting[i]) {
                float phase = (float)m->pig_boost_time[i]
                    / (float)m->pig_boost_total[i] * (float)MC_PI;
                speed += speed * 1.15F * mc_sin(st, phase);
            }
            m->pig_ai_speed[i] = speed;
            liv.landMovementFactor = speed;
        } else {
            /* Without a carrot-on-a-stick the client-side NoAI pig cannot
             * passenger-steer.  Vanilla only applies the remote .98 motion
             * damping; moveEntityWithHeading returns without travel. */
            liv.isServerWorld = 0;
        }
    }
    if (movement_blocked && s->type[i] == EW_TYPE_PIG) {
        /* EntityPig's non-steerable branch restores these values before its
         * server-side super travel, even for a health-zero body. */
        m->pig_step_height[i] = 0.5F;
        m->pig_jump_factor[i] = 0.02F;
        liv.base.phys.stepHeight = 0.5F;
        liv.jumpMovementFactor = 0.02F;
        liv.isServerWorld = 1;
    }
    if (gm_child_sized(s->type[i]) && m->growing_age[i] < 0) {
        float w, h;
        ehs_size_scaled(s->type[i], m->size[i], &w, &h);
        w *= 0.5F;
        h *= 0.5F;
        liv.base.width = w;
        liv.base.height = h;
        liv.base.phys.box = mc_aabb_make(
            s->x[i] - w * 0.5, s->y[i], s->z[i] - w * 0.5,
            s->x[i] + w * 0.5, s->y[i] + h, s->z[i] + w * 0.5);
    }
    /* Override size for slime/magma. */
    if (gm_is_slimey(s->type[i])) {
        float w, h; ehs_size_scaled(s->type[i], m->size[i], &w, &h);
        liv.base.width = w; liv.base.height = h;
        liv.base.phys.box = mc_aabb_make(s->x[i] - w * 0.5, s->y[i], s->z[i] - w * 0.5,
                                         s->x[i] + w * 0.5, s->y[i] + h, s->z[i] + w * 0.5);
    }
    if (gm_passive(s->type[i]) && !ridden_pig && !steerable_horse) {
        /* EntityMoveHelper MOVE_TO:
         *   setAIMoveSpeed((float)(navigatorSpeed * MOVEMENT_SPEED attr));
         * EntityLiving.setAIMoveSpeed writes that same value to moveForward.
         * EntityLivingBase then damps moveForward by 0.98 before travel. */
        double attribute_speed = gm_mobs_horse_type(s->type[i])
            ? m->horse_movement_speed[i]
            : pai_attribute_speed(s->type[i]);
        float ai_speed = (float)(nav_speed * attribute_speed);
        int trap_horse = gm_mobs_horse_type(s->type[i])
            && m->skeleton_trap_rider_eid[i] >= 0;
        if (trap_horse) {
            /* EntityMoveHelper only writes the fields owned by its current
             * action. In particular MOVE_TO leaves the previous damped
             * moveStrafing value intact. */
            liv.moveForward = m->passive_move_forward[i];
            liv.moveStrafing = m->passive_move_strafe[i];
            if (moving) {
                liv.landMovementFactor = ai_speed;
                liv.moveForward = ai_speed;
            } else {
                liv.moveForward = 0.0F;
            }
        } else {
            liv.landMovementFactor = ai_speed;
            liv.moveForward = moving ? ai_speed : 0.0F;
            liv.moveStrafing = 0.0F;
        }
        if (moving) {
            double dx = s->path_tx[i] - s->x[i];
            double dy = s->path_ty[i] - s->y[i];
            double dz = s->path_tz[i] - s->z[i];
            if (dy > liv.base.phys.stepHeight && dx * dx + dz * dz < fmax(1.0, liv.base.width))
                liv.isJumping = 1;
        }
        if (gm_mobs_horse_type(s->type[i])
                && m->skeleton_trap_rider_eid[i] >= 0
                && !movement_blocked
                && m->skeleton_trap_move_action[i] == 1
                && m->skeleton_trap_move_terminal_ticks[i] > 0) {
            /* PathNavigateGround can finish the shared rider Path without
             * replacing the MOVE_TO helper copied on the preceding rider
             * update. EntityMoveHelper.read clamps that helper's speed to
             * one, so these terminal moves use the horse attribute directly
             * rather than the navigator's forced 1.5 speed. */
            double dx = m->skeleton_trap_move_x[i] - s->x[i];
            double dy = m->skeleton_trap_move_y[i] - s->y[i];
            double dz = m->skeleton_trap_move_z[i] - s->z[i];
            double distance_sq = dx * dx + dy * dy + dz * dz;
            if (distance_sq < 2.500000277905201E-7D) {
                liv.moveForward = 0.0F;
            } else {
                float target_yaw = mob_move_helper_yaw(
                    s->yaw[i], dx, dz);
                liv.base.rotationYaw = pai_update_rotation(
                    s->yaw[i], target_yaw, 90.0F);
                liv.landMovementFactor = (float)(
                    m->skeleton_trap_move_speed[i]
                    * m->horse_movement_speed[i]);
                liv.moveForward = liv.landMovementFactor;
            }
            liv.isJumping = dy > liv.base.phys.stepHeight
                && dx * dx + dz * dz
                    < fmax(1.0, liv.base.width);
            if (--m->skeleton_trap_move_terminal_ticks[i] == 0) {
                m->skeleton_trap_move_action[i] = 0;
                m->skeleton_trap_move_wait_latched[i] = 1;
            }
        }
        if (gm_mobs_horse_type(s->type[i])
                && m->skeleton_trap_rider_eid[i] >= 0
                && !movement_blocked
                && m->skeleton_trap_move_action[i] == 2) {
            /* EntityLiving copies its STRAFE MoveHelper into the unsaddled
             * horse after that horse has already ticked. The empty navigator
             * leaves it intact on the following tick: copied speed clamps to
             * one, then multiplies the horse movement-speed attribute. */
            liv.landMovementFactor = (float)m->horse_movement_speed[i];
            liv.moveForward = m->skeleton_trap_move_forward[i];
            liv.moveStrafing = m->skeleton_trap_move_strafe[i];
            liv.base.rotationYaw = s->yaw[i];
            liv.isJumping = 0;
            m->skeleton_trap_move_action[i] = 0;
        }
        if (trap_horse && movement_blocked) {
            liv.moveForward = 0.0F;
            liv.moveStrafing = 0.0F;
            liv.isJumping = 0;
        }
    }
    if (s->type[i] == EW_TYPE_RABBIT && liv.isJumping
            && liv.base.phys.onGround) {
        /* EntityRabbit replaces LivingBase's 0.42 jump impulse. */
        double dy = s->path_ty[i] - s->y[i];
        liv.base.phys.motionY = dy > 0.5D ? 0.5D
            : m->rabbit_move_speed[i] > 0.6D ? 0.3D : 0.2D;
        if (liv.jumpBoostAmplifier >= 0)
            liv.base.phys.motionY +=
                0.1D * (double)(liv.jumpBoostAmplifier + 1);
        liv.isJumping = 0;
    }
    /* EntityGuardian.moveEntityWithHeading and GuardianMoveHelper. The
     * swimmer applies its sinusoidal steering impulses before fluid travel,
     * then uses the Guardian-specific 0.9 drag and idle sink. */
    if ((s->type[i] == EW_TYPE_GUARDIAN
                || s->type[i] == EW_TYPE_ELDER_GUARDIAN)
            && m->entity_in_water[i]) {
        double dx = s->path_tx[i] - s->x[i];
        double dy = s->path_ty[i] - s->y[i];
        double dz = s->path_tz[i] - s->z[i];
        double len = sqrt(dx * dx + dy * dy + dz * dz);
        float ai_speed = (float)m->passive_nav_speed[i];
        if (moving && len > 1.0E-12) {
            dy /= len;
            float target = (float)(nav_speed
                * ehs_land_speed((u8)s->type[i]));
            ai_speed += (target - ai_speed) * 0.125F;
            m->passive_nav_speed[i] = ai_speed;
            float radians = s->yaw[i] * 0.017453292F;
            double wave = sin(
                (double)(m->entity_ticks_existed[i] + s->id[i]) * 0.5D)
                * 0.05D;
            s->vx[i] += wave * cos((double)radians);
            s->vz[i] += wave * sin((double)radians);
            wave = sin(
                (double)(m->entity_ticks_existed[i] + s->id[i]) * 0.75D)
                * 0.05D;
            s->vy[i] += wave
                * (sin((double)radians) + cos((double)radians)) * 0.25D;
            s->vy[i] += (double)ai_speed * dy * 0.1D;
        } else {
            ai_speed = 0.0F;
            m->passive_nav_speed[i] = 0.0;
        }
        liv.base.phys.motionX = s->vx[i];
        liv.base.phys.motionY = s->vy[i];
        liv.base.phys.motionZ = s->vz[i];
        liv.moveStrafing = 0.0F;
        liv.moveForward = moving ? ai_speed * 0.98F : 0.0F;
        eb_move_relative(
            &liv.base, liv.moveStrafing, liv.moveForward, 0.1F, st);
        McAABB fq = mc_aabb_addcoord(
            &liv.base.phys.box, liv.base.phys.motionX,
            liv.base.phys.motionY, liv.base.phys.motionZ);
        fq.minY -= liv.base.phys.stepHeight;
        fq.maxY += liv.base.phys.stepHeight;
        int fn = collect_blocks(w, &fq, blocks, GM_MOB_BLOCKS);
        eb_move(&liv.base, liv.base.phys.motionX, liv.base.phys.motionY,
                liv.base.phys.motionZ, blocks, fn);
        liv.base.phys.motionX *= 0.8999999761581421D;
        liv.base.phys.motionY *= 0.8999999761581421D;
        liv.base.phys.motionZ *= 0.8999999761581421D;
        if (!moving && m->guardian_target_eid[i] < 0)
            liv.base.phys.motionY -= 0.005D;
        ehs_store_living(s, i, &liv);
        m->entity_fall_distance[i] = 0.0F;
        return;
    }
    /* Vex: noClip during super.onUpdate, then noGravity. AIMoveControl adds
     * acceleration before the aerial travel damping. */
    if (s->type[i] == EW_TYPE_VEX) {
        double dx = s->path_tx[i] - s->x[i];
        double dy = s->path_ty[i] - s->y[i];
        double dz = s->path_tz[i] - s->z[i];
        double len = sqrt(dx * dx + dy * dy + dz * dz);
        if (moving && len < (0.4 + 0.8 + 0.4) / 3.0) {
            s->path_len[i] = 0;
            s->vx[i] *= 0.5;
            s->vy[i] *= 0.5;
            s->vz[i] *= 0.5;
        } else if (moving && len > 0.0) {
            s->vx[i] += dx / len * 0.05 * nav_speed;
            s->vy[i] += dy / len * 0.05 * nav_speed;
            s->vz[i] += dz / len * 0.05 * nav_speed;
        }
        s->x[i] += s->vx[i];
        s->y[i] += s->vy[i];
        s->z[i] += s->vz[i];
        s->vx[i] *= 0.91;
        s->vy[i] *= 0.98;
        s->vz[i] *= 0.91;
        s->on_ground[i] = 0;
        m->entity_fall_distance[i] = 0.0F;
        return;
    }
    /* Ghast: no gravity; fly toward path. */
    if (s->type[i] == EW_TYPE_GHAST) {
        double dx = s->path_tx[i] - s->x[i];
        double dy = s->path_ty[i] - s->y[i];
        double dz = s->path_tz[i] - s->z[i];
        double len = sqrt(dx * dx + dy * dy + dz * dz);
        if (moving && len > 0.01) {
            double sp = 0.1;
            s->vx[i] = dx / len * sp;
            s->vy[i] = dy / len * sp;
            s->vz[i] = dz / len * sp;
        } else {
            s->vx[i] *= 0.9; s->vy[i] *= 0.9; s->vz[i] *= 0.9;
        }
        s->x[i] += s->vx[i]; s->y[i] += s->vy[i]; s->z[i] += s->vz[i];
        s->yaw[i] = intent.yaw;
        s->on_ground[i] = 0;
        return;
    }
    /* EntityBlaze.onLivingUpdate: slow fall (motionY *= 0.6 when falling).
     * Full heightOffset hover from updateAITasks is not ported (needs its own
     * randomized heightOffset timer); fall damping alone is the small half. */
    if (s->type[i] == EW_TYPE_BLAZE && !liv.base.phys.onGround &&
        liv.base.phys.motionY < 0.0)
        liv.base.phys.motionY *= 0.6;

    /* EntityAISwimming only requests a jump; the actual water/lava travel is
     * EntityLivingBase's fluid branch. Keep it here so a passive does not run
     * the land gravity branch while submerged. */
    if (gm_passive(s->type[i]) && !ridden_pig && !steerable_horse &&
        (pai_in_material(w, s, i, 0) || pai_in_material(w, s, i, 1))) {
        int in_water = pai_in_material(w, s, i, 0);
        eb_on_entity_update(&liv.base);
        if (fabs(liv.base.phys.motionX) < 0.003) liv.base.phys.motionX = 0.0;
        if (fabs(liv.base.phys.motionY) < 0.003) liv.base.phys.motionY = 0.0;
        if (fabs(liv.base.phys.motionZ) < 0.003) liv.base.phys.motionZ = 0.0;
        if (swim_jump) liv.base.phys.motionY += 0.03999999910593033;
        liv.moveStrafing *= 0.98f;
        liv.moveForward *= 0.98f;
        eb_move_relative(&liv.base, liv.moveStrafing, liv.moveForward, 0.02f, st);
        McAABB fq = mc_aabb_addcoord(&liv.base.phys.box, liv.base.phys.motionX,
                                     liv.base.phys.motionY, liv.base.phys.motionZ);
        fq.minY -= liv.base.phys.stepHeight; fq.maxY += liv.base.phys.stepHeight;
        int fn = collect_blocks(w, &fq, blocks, GM_MOB_BLOCKS);
        eb_move(&liv.base, liv.base.phys.motionX, liv.base.phys.motionY,
                liv.base.phys.motionZ, blocks, fn);
        double drag = in_water ? 0.800000011920929 : 0.5;
        liv.base.phys.motionX *= drag;
        liv.base.phys.motionY *= drag;
        liv.base.phys.motionZ *= drag;
        if (!liv.base.hasNoGravity) liv.base.phys.motionY -= 0.02;
        ehs_store_living(s, i, &liv);
        if ((gm_mobs_horse_type(s->type[i])
                    && m->skeleton_trap_rider_eid[i] >= 0)
                || (s->type[i] == EW_TYPE_SKELETON
                    && m->skeleton_trap_vehicle_eid[i] >= 0)) {
            m->passive_move_forward[i] = liv.moveForward;
            m->passive_move_strafe[i] = liv.moveStrafing;
        }
        return;
    }
    float slip = 0.6f;
    if (liv.base.phys.onGround) {
        int id = gm_world_block(w, mc_floor(liv.base.phys.posX),
                                mc_floor(liv.base.phys.box.minY)-1,
                                mc_floor(liv.base.phys.posZ));
        if (id == 79 || id == 174 || id == 212) slip = 0.98f;
        if (id == 165) slip = 0.8f;
        if (id == 8 || id == 9) slip = 0.8f; /* water friction for boat handled below */
    }
    /* Angry pigman speed boost +0.05 (AttributeModifier). */
    if (s->type[i] == EW_TYPE_PIGMAN && m->anger[i] > 0)
        liv.landMovementFactor += 0.05f;
    if (!animal_move_helper) {
        double adjusted = (double)liv.landMovementFactor
            * movement_multiplier;
        liv.landMovementFactor = adjusted > 0.0 ? (float)adjusted : 0.0F;
    }
    McAABB q = mc_aabb_addcoord(&liv.base.phys.box, liv.base.phys.motionX,
                                liv.base.phys.motionY, liv.base.phys.motionZ);
    q.minY -= liv.base.phys.stepHeight; q.maxY += liv.base.phys.stepHeight;
    if (ridden_pig && window) {
        McAABB local_query = q;
        McAABB *collision_boxes = m->pig_collision_scratch;
        int (*contact_cells)[4] = m->pig_block_contact_scratch;
        local_query.minX -= ox;
        local_query.maxX -= ox;
        local_query.minZ -= oz;
        local_query.maxZ -= oz;
        int n = psv_collect_blocks(
            (const Chunk *)window, &local_query,
            collision_boxes, GM_PIG_COLLISION_BOXES);
        for (int box = 0; box < n; ++box) {
            collision_boxes[box].minX += ox;
            collision_boxes[box].maxX += ox;
            collision_boxes[box].minZ += oz;
            collision_boxes[box].maxZ += oz;
        }
        int ncontacts = collect_block_contact_cells(
            window, &q, ox, oz, contact_cells, GM_PIG_COLLISION_BOXES);
        if (ridden_in_water && steerable)
            tick_ridden_pig_water(
                window, ox, oz, st, &liv, movement_blocked,
                collision_boxes, contact_cells);
        else if (ridden_in_lava && steerable)
            tick_ridden_pig_lava(
                window, ox, oz, st, &liv, movement_blocked,
                collision_boxes, contact_cells);
        else if (steerable) {
            tick_ridden_pig_land_water_entry(
                window, ox, oz, st, m, i, &liv, slip,
                movement_blocked, collision_boxes, n,
                contact_cells, ncontacts);
        } else {
            eb_tick_living_aabb_contacts(
                &liv, slip, movement_blocked, collision_boxes, n,
                contact_cells, ncontacts, st);
        }
    } else {
        int n = collect_blocks(w, &q, blocks, GM_MOB_BLOCKS);
        int landing_contacts[GM_MOB_LANDING_CONTACTS][4];
        int nlanding = collect_landing_contacts(
            blocks, n, landing_contacts, GM_MOB_LANDING_CONTACTS);
        eb_tick_living_contacts(
            &liv, slip, movement_blocked, blocks, n,
            landing_contacts, nlanding, st);
    }
    ehs_store_living(s, i, &liv);
    if ((gm_mobs_horse_type(s->type[i])
                && m->skeleton_trap_rider_eid[i] >= 0)
            || (s->type[i] == EW_TYPE_SKELETON
                && m->skeleton_trap_vehicle_eid[i] >= 0)) {
        m->passive_move_forward[i] = liv.moveForward;
        m->passive_move_strafe[i] = liv.moveStrafing;
    }
    if (ridden_pig || exact_box || s->type[i] == EW_TYPE_LLAMA
            || s->type[i] == EW_TYPE_BAT) {
        m->entity_box_min_x[i] = liv.base.phys.box.minX;
        m->entity_box_min_y[i] = liv.base.phys.box.minY;
        m->entity_box_min_z[i] = liv.base.phys.box.minZ;
        m->entity_box_max_x[i] = liv.base.phys.box.maxX;
        m->entity_box_max_y[i] = liv.base.phys.box.maxY;
        m->entity_box_max_z[i] = liv.base.phys.box.maxZ;
        m->entity_box_valid[i] = 1;
    }
    m->entity_fall_distance[i] = liv.base.fallDistance;
    m->entity_collided_horizontal[i] =
        (unsigned char)(liv.base.phys.collidedHorizontally ? 1 : 0);
    m->entity_collided_vertical[i] =
        (unsigned char)(liv.base.phys.collidedVertically ? 1 : 0);
    m->entity_in_web[i] = (unsigned char)(liv.base.phys.isInWeb ? 1 : 0);
    if (ridden_pig && window)
        m->entity_in_lava[i] = (unsigned char)(
            ridden_pig_in_lava(window, ox, oz, &liv) ? 1 : 0);
    if (ridden_pig) {
        float moved = (float)sqrt(
            (s->x[i] - old_x) * (s->x[i] - old_x)
                + (s->z[i] - old_z) * (s->z[i] - old_z)) * 4.0F;
        if (moved > 1.0F) moved = 1.0F;
        m->pig_prev_limb_amount[i] = m->pig_limb_amount[i];
        m->pig_limb_amount[i] +=
            (moved - m->pig_limb_amount[i]) * 0.4F;
        m->pig_limb_swing[i] += m->pig_limb_amount[i];
        if (steerable) {
            m->pig_prev_limb_amount[i] = m->pig_limb_amount[i];
            m->pig_limb_amount[i] +=
                (moved - m->pig_limb_amount[i]) * 0.4F;
            m->pig_limb_swing[i] += m->pig_limb_amount[i];
        }
    }
    if (gm_mobs_horse_type(s->type[i])) {
        float moved = (float)sqrt(
            (s->x[i] - old_x) * (s->x[i] - old_x)
                + (s->z[i] - old_z) * (s->z[i] - old_z)) * 4.0F;
        if (moved > 1.0F) moved = 1.0F;
        m->horse_prev_limb_amount[i] = m->horse_limb_amount[i];
        m->horse_limb_amount[i] +=
            (moved - m->horse_limb_amount[i]) * 0.4F;
        m->horse_limb_swing[i] += m->horse_limb_amount[i];
    }
}

static int alive_count(const GmMobLive *m,const EwStore *s) {
    int n=0;
    for (int i=1;i<EW_SPAWN_LIMIT;++i)
        if (s->alive[i] && m->entity_dimension[i]==m->active_dimension &&
            gm_hostile(s->type[i])) ++n;
    for (int i = 0; i < m->living_cold_count; ++i)
        if (m->living_cold[i].store_alive
                && m->living_cold[i].entity_dimension == m->active_dimension
                && gm_hostile(m->living_cold[i].store_type)) ++n;
    return n;
}
static int living_count(const GmMobLive *m,const EwStore *s) {
    int n=0;
    for(int i=1;i<EW_SPAWN_LIMIT;++i)
        if(s->alive[i]&&m->entity_dimension[i]==m->active_dimension&&
           gm_living(s->type[i]))++n;
    for (int i = 0; i < m->living_cold_count; ++i)
        if (m->living_cold[i].store_alive
                && m->living_cold[i].entity_dimension == m->active_dimension
                && gm_living(m->living_cold[i].store_type)) ++n;
    return n;
}
static int passive_count(const GmMobLive *m,const EwStore *s) {
    int n=0;
    for(int i=1;i<EW_SPAWN_LIMIT;++i)
        if(s->alive[i]&&m->entity_dimension[i]==m->active_dimension&&
           gm_passive(s->type[i]))++n;
    for (int i = 0; i < m->living_cold_count; ++i)
        if (m->living_cold[i].store_alive
                && m->living_cold[i].entity_dimension == m->active_dimension
                && gm_passive(m->living_cold[i].store_type)) ++n;
    return n;
}

static int type_count(const GmMobLive *m, const EwStore *s, int type) {
    int n = 0;
    for (int i = 1; i < EW_SPAWN_LIMIT; ++i)
        if (s->alive[i] && m->entity_dimension[i] == m->active_dimension
                && s->type[i] == type) ++n;
    for (int i = 0; i < m->living_cold_count; ++i)
        if (m->living_cold[i].store_alive
                && m->living_cold[i].entity_dimension == m->active_dimension
                && m->living_cold[i].store_type == type) ++n;
    return n;
}

int gm_mobs_living_count(const GmMobLive *m){
    return m?living_count(m,const_store(m)):0;
}

static int collect_orb_blocks(GmWorld *w,const McAABB *q,McAABB *out,int cap){
    int n=0,x0=mc_floor(q->minX)-1,x1=mc_floor(q->maxX)+1;
    int y0=mc_floor(q->minY)-1,y1=mc_floor(q->maxY)+1;
    int z0=mc_floor(q->minZ)-1,z1=mc_floor(q->maxZ)+1;
    if(y0<0)y0=0;
    if(y1>255)y1=255;
    for(int x=x0;x<=x1;++x)for(int y=y0;y<=y1;++y)for(int z=z0;z<=z1;++z){
        if(!solid_id(gm_world_block(w,x,y,z)))continue;
        if(n==cap)return n;
        out[n++]=mc_aabb_make(x,y,z,x+1,y+1,z+1);
    }return n;
}

static McAABB xp_player_collision_box(PsvPlayer *p, int ox, int oz) {
    /* EntityPlayer.onLivingUpdate queries onCollideWithPlayer over
     * playerBox.expand(1.0, 0.5, 1.0). In 1.11.2 expand is directional:
     * positive arguments extend maxX/maxY/maxZ only. */
    McAABB player = mc_aabb_addcoord(&p->ent.box, 1.0, 0.5, 1.0);
    player.minX += ox;
    player.maxX += ox;
    player.minZ += oz;
    player.maxZ += oz;
    return player;
}

static int stack_has_enchantment(ICStack stack, int enchantment_id) {
    for (int i = 0; i < stack.n_enchants; ++i)
        if (stack.enchants[i].id == enchantment_id
                && stack.enchants[i].level > 0)
            return 1;
    return 0;
}

static int xp_apply_mending(GmMobLive *m, PsvPlayer *p, int value) {
    /* EnchantmentMending is registered for EntityEquipmentSlot.values():
     * MAINHAND, OFFHAND, FEET, LEGS, CHEST, HEAD. EnchantmentHelper retains
     * every equipped Mending stack, including undamaged items, then consumes
     * one Entity.rand nextInt even when the candidate count is one. */
    int equipment[6] = {
        p->inv.current_item, ISR_OFFHAND_SLOT,
        ISR_ARMOR_FEET, ISR_ARMOR_LEGS, ISR_ARMOR_CHEST, ISR_ARMOR_HEAD
    };
    int candidates[6], count = 0;
    for (int i = 0; i < 6; ++i) {
        ICStack stack = isr_get_stack(&p->inv, equipment[i]);
        if (stack.item != IC_AIR && stack.count > 0
                && stack_has_enchantment(stack, 70))
            candidates[count++] = equipment[i];
    }
    if (count <= 0) return value;
    int slot = candidates[jrand_int_bound(&m->player_random, count)];
    ICStack selected = isr_get_stack(&p->inv, slot);
    if (selected.meta > 0 && isr_is_damageable(selected.item)) {
        int repair = value > INT_MAX / 2 ? INT_MAX : value * 2;
        if (repair > selected.meta) repair = selected.meta;
        value -= repair / 2;
        selected.meta -= repair;
        isr_set_stack(&p->inv, slot, selected);
    }
    return value;
}

static void tick_xp_orb_slot(
        GmMobLive *m, GmWorld *w, PsvPlayer *p, int ox, int oz,
        const McAABB *player, int i) {
    McOrb *o = xp_orb_at(m, i);
    signed char *dimension = xp_dimension_at(m, i);
    if (!o || !dimension) return;
    if (o->dead || o->xpValue <= 0
            || *dimension != m->active_dimension)
        return;
    McAABB q = mc_aabb_addcoord(
        &o->box, o->motionX, o->motionY, o->motionZ);
    McAABB blocks[64];
    int nb = collect_orb_blocks(w, &q, blocks, 64);
    int ux = mc_floor(o->posX);
    int uy = mc_floor(o->box.minY) - 1;
    int uz = mc_floor(o->posZ);
    if (uy < 0) uy = 0;
    u16 under = mc_state(
        gm_world_block(w, ux, uy, uz), gm_world_meta(w, ux, uy, uz));
    eo_tick(o, p->ent.posX + ox, p->ent.posY, p->ent.posZ + oz,
        PSV_EYE_HEIGHT, 0, blocks, nb, under, 0);
    if (m->xp_collision_count < GM_XP_ORBS)
        m->xp_collision_boxes[m->xp_collision_count++] = o->box;
    else
        ++m->xp_collision_count;
    if (!o->dead && o->delayBeforeCanPickup <= 0
            && m->player_xp_cooldown <= 0
            && mc_aabb_intersects(&o->box, player)) {
        m->player_xp_cooldown = 2;
        int value = xp_apply_mending(m, p, o->xpValue);
        o->xpValue = value;
        if (value > 0) m->xp_total += value;
        o->dead = 1;
    }
    if (o->dead) loaded_invalidate_xp(m, i);
}

static void tick_xp_orbs(GmMobLive *m,GmWorld *w,PsvPlayer *p,int ox,int oz){
    McAABB player = xp_player_collision_box(p, ox, oz);
    m->xp_collision_count = 0;
    for (int i = 0; i < xp_slot_limit(m); ++i)
        tick_xp_orb_slot(m, w, p, ox, oz, &player, i);
}

void gm_mobs_tick_xp(GmMobLive *m, GmWorld *w, struct PsvPlayer *player,
                     int ox, int oz) {
    if (!m || !w || !player) return;
    if (m->player_xp_cooldown > 0) --m->player_xp_cooldown;
    loaded_order_prepare(m);
    tick_xp_orbs(m, w, (PsvPlayer *)player, ox, oz);
    loaded_order_compact(m);
    if (m->player_ticks_since_last_swing < 1000000000)
        ++m->player_ticks_since_last_swing;
}

void gm_mobs_tick_xp_from_eid(
        GmMobLive *m, GmWorld *w, struct PsvPlayer *player,
        int ox, int oz, int first_eid) {
    McAABB box;
    if (!m || !w || !player || first_eid < 0) return;
    box = xp_player_collision_box((PsvPlayer *)player, ox, oz);
    for (int slot = 0; slot < xp_slot_limit(m); ++slot) {
        McOrb *orb = xp_orb_at(m, slot);
        signed char *dimension = xp_dimension_at(m, slot);
        if (!orb->dead && orb->xpValue > 0
                && orb->eid >= first_eid
                && *dimension == m->active_dimension) {
            tick_order_append(m, orb->eid);
            tick_xp_orb_slot(
                m, w, (PsvPlayer *)player, ox, oz, &box, slot);
        }
    }
    loaded_order_compact(m);
}

static void tick_controlled_dead_fire(
        GmMobLive *m, const EwStore *s, int slot) {
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !m->entity_dead[slot]
            || s->health[slot] > 0.0F)
        return;
    /* Entity.onEntityUpdate processes the signed fire counter before
     * EntityLivingBase ages combat/death state. A dead target rejects the
     * periodic ON_FIRE attack, so only the counter changes here. */
    if (m->fire_ticks[slot] > 0)
        --m->fire_ticks[slot];
}

static void terminal_particle_append(
        GmMobLive *m, GmMobTerminalParticles *batch) {
    if (!m || !batch || !mob_ring_linearize(
            (void **)&m->terminal_particles, m->terminal_particles_cap,
            m->terminal_particle_count, &m->terminal_particle_head,
            sizeof *m->terminal_particles)
            || !MOB_COLD_RESERVE(
            m, terminal_particles, m->terminal_particle_count + 1,
            GM_MOB_TERMINAL_PARTICLE_CAPACITY)) {
        if (m) {
            ++m->terminal_particle_dropped;
            ++m->terminal_particle_next_seq;
        }
        return;
    }
    int index = m->terminal_particle_count++;
    batch->seq = m->terminal_particle_next_seq++;
    m->terminal_particles[index] = *batch;
}

int gm_mobs_terminal_particle_count(const GmMobLive *m) {
    return m ? m->terminal_particle_count : 0;
}

int gm_mobs_terminal_particle_get(
        const GmMobLive *m, int index, GmMobTerminalParticles *out) {
    if (!m || !out || index < 0 || index >= m->terminal_particle_count
            || m->terminal_particles_cap <= 0)
        return 0;
    int slot = (m->terminal_particle_head + index)
        % m->terminal_particles_cap;
    *out = m->terminal_particles[slot];
    return 1;
}

static void mob_particle_batch_append(
        GmMobLive *m, const GmMobParticleBatch *batch) {
    int explicit_particles = batch && batch->count >= 1
        && batch->count <= GM_MOB_PARTICLE_BATCH_MAX;
    int descriptor = batch && batch->descriptor_count > 0;
    if (!m || !batch || (!explicit_particles && !descriptor))
        return;
    if (!mob_ring_linearize(
            (void **)&m->particle_batches, m->particle_batches_cap,
            m->particle_batch_count, &m->particle_batch_head,
            sizeof *m->particle_batches)
            || !MOB_COLD_RESERVE(
            m, particle_batches, m->particle_batch_count + 1,
            GM_MOB_PARTICLE_BATCH_CAPACITY)) {
        ++m->particle_batch_dropped;
        ++m->particle_batch_next_seq;
        return;
    }
    int index = m->particle_batch_count++;
    m->particle_batches[index] = *batch;
    m->particle_batches[index].seq = m->particle_batch_next_seq++;
}

/* The client EntityLlamaSpit spawn constructor emits seven SPIT calls.
 * Horizontal motion is scaled 0.4..1.0; Y is deliberately not scaled. */
static void llama_spit_particle_append(
        GmMobLive *m, const GmLlamaSpit *spit) {
    GmMobParticleBatch batch;
    if (!m || !spit) return;
    memset(&batch, 0, sizeof batch);
    batch.eid = spit->eid;
    batch.dimension = spit->dimension;
    batch.particle_id = 48;
    batch.count = 7;
    for (int index = 0; index < 7; ++index) {
        double scale = 0.4D + 0.1D * (double)index;
        batch.particles[index] = (GmTerminalParticle){
            .x = spit->x, .y = spit->y, .z = spit->z,
            .vx = spit->vx * scale,
            .vy = spit->vy,
            .vz = spit->vz * scale,
        };
    }
    mob_particle_batch_append(m, &batch);
}

int gm_mobs_particle_batch_count(const GmMobLive *m) {
    return m ? m->particle_batch_count : 0;
}

int gm_mobs_particle_batch_get(
        const GmMobLive *m, int index, GmMobParticleBatch *out) {
    if (!m || !out || index < 0 || index >= m->particle_batch_count
            || m->particle_batches_cap <= 0)
        return 0;
    *out = m->particle_batches[
        (m->particle_batch_head + index) % m->particle_batches_cap];
    return 1;
}

static int terminal_xp_spawn(
        GmMobLive *m, double x, double y, double z, int dimension,
        uint64_t *world_random_seed48,
        uint64_t *math_random_seed48, int *next_entity_id) {
    if (!m || !world_random_seed48 || !math_random_seed48
            || !next_entity_id || *next_entity_id <= 0
            || *next_entity_id == INT_MAX)
        return 0;
    int free_slot = xp_free_slot(m, 1);
    if (free_slot < 0)
        return 0;

    uint64_t world_cursor = *world_random_seed48;
    uint64_t math_cursor = *math_random_seed48;
    JavaRandom world_random;
    jrand_set_seed48(&world_random, world_cursor);
    int value = 1 + jrand_int_bound(&world_random, 3);
    float yaw = (float)(mob_math_random_next_double(&math_cursor) * 360.0);
    float motion_x_float = (float)(
        mob_math_random_next_double(&math_cursor)
            * 0.20000000298023224 - 0.10000000149011612);
    float motion_y_float = (float)(
        mob_math_random_next_double(&math_cursor) * 0.2);
    float motion_z_float = (float)(
        mob_math_random_next_double(&math_cursor)
            * 0.20000000298023224 - 0.10000000149011612);

    McOrb *orb = xp_orb_at(m, free_slot);
    memset(orb, 0, sizeof *orb);
    orb->motionX = (double)(motion_x_float * 2.0F);
    orb->motionY = (double)(motion_y_float * 2.0F);
    orb->motionZ = (double)(motion_z_float * 2.0F);
    orb->xpValue = value;
    orb->health = 5;
    orb->eid = *next_entity_id;
    orb->yaw = yaw;
    *xp_dimension_at(m, free_slot) = (signed char)dimension;
    eo_set_position(orb, x, y, z);
    if (m->next_orb_id <= orb->eid)
        m->next_orb_id = orb->eid + 1;
    (void)loaded_append_xp(m, free_slot);
    *world_random_seed48 = world_random.seed;
    *math_random_seed48 = math_cursor;
    ++*next_entity_id;
    return 1;
}

static int xp_split_value(int value) {
    static const int thresholds[] = {
        2477, 1237, 617, 307, 149, 73, 37, 17, 7, 3, 1
    };
    for (int i = 0;
            i < (int)(sizeof thresholds / sizeof thresholds[0]); ++i)
        if (value >= thresholds[i]) return thresholds[i];
    return 0;
}

/* EntityLivingBase.onDeathUpdate constructs every split orb before terminal
 * particles. This fixed-pool implementation commits the boundary only when
 * every Java orb and loaded-list append fits, avoiding a partial XP tail. */
int gm_mobs_spawn_xp_split_exact(
        GmMobLive *m, double x, double y, double z, int dimension,
        int total, uint64_t *math_random_seed48, int *next_entity_id) {
    int values[16], slots[16], count = 0;
    int remaining = total;
    while (remaining > 0 && count < (int)(sizeof values / sizeof values[0])) {
        values[count] = xp_split_value(remaining);
        if (values[count] <= 0) return 0;
        remaining -= values[count++];
    }
    if (!m || remaining != 0 || count <= 0 || !math_random_seed48
            || !next_entity_id || *next_entity_id <= 0
            || *next_entity_id > INT_MAX - count)
        return 0;
    int free_count = 0;
    for (int slot = 0; slot < xp_slot_limit(m) && free_count < count; ++slot) {
        McOrb *orb = xp_orb_at(m, slot);
        if (orb->dead || orb->xpValue <= 0)
            slots[free_count++] = slot;
    }
    if (free_count != count) {
        if (!xp_cold_reserve(m, m->xp_orb_cold_cap + count - free_count))
            return 0;
        free_count = 0;
        for (int slot = 0;
                slot < xp_slot_limit(m) && free_count < count; ++slot) {
            McOrb *orb = xp_orb_at(m, slot);
            if (orb->dead || orb->xpValue <= 0)
                slots[free_count++] = slot;
        }
        if (free_count != count) return 0;
    }
    loaded_order_compact(m);
    if (!loaded_order_reserve(m, m->loaded_order_count + count))
        return 0;

    uint64_t math_cursor = *math_random_seed48;
    int first_eid = *next_entity_id;
    for (int i = 0; i < count; ++i) {
        float yaw = (float)(
            mob_math_random_next_double(&math_cursor) * 360.0);
        float motion_x = (float)(
            mob_math_random_next_double(&math_cursor)
                * 0.20000000298023224 - 0.10000000149011612);
        float motion_y = (float)(
            mob_math_random_next_double(&math_cursor) * 0.2);
        float motion_z = (float)(
            mob_math_random_next_double(&math_cursor)
                * 0.20000000298023224 - 0.10000000149011612);
        McOrb *orb = xp_orb_at(m, slots[i]);
        memset(orb, 0, sizeof *orb);
        if (slots[i] < GM_XP_ORBS) {
            m->orb_uuid_present[slots[i]] = 0;
            m->orb_uuid_most[slots[i]] = 0;
            m->orb_uuid_least[slots[i]] = 0;
            m->orb_random_seed48[slots[i]] = 0;
        } else {
            GmXpOrbCold *cold = &m->xp_orb_cold[slots[i] - GM_XP_ORBS];
            cold->uuid_present = 0;
            cold->uuid_most = cold->uuid_least = 0;
            cold->random_seed48 = 0;
        }
        orb->motionX = (double)(motion_x * 2.0F);
        orb->motionY = (double)(motion_y * 2.0F);
        orb->motionZ = (double)(motion_z * 2.0F);
        orb->xpValue = values[i];
        orb->health = 5;
        orb->eid = first_eid + i;
        orb->yaw = yaw;
        *xp_dimension_at(m, slots[i]) = (signed char)dimension;
        eo_set_position(orb, x, y, z);
        (void)loaded_append_xp(m, slots[i]);
    }
    *math_random_seed48 = math_cursor;
    *next_entity_id += count;
    if (m->next_id < *next_entity_id) m->next_id = *next_entity_id;
    if (m->next_orb_id < *next_entity_id)
        m->next_orb_id = *next_entity_id;
    return count;
}

int gm_mobs_spawn_xp_split_constructed_exact(
        GmMobLive *m, double x, double y, double z, int dimension,
        int total, uint64_t *math_random_seed48,
        uint64_t *entity_seed_generator_seed48,
        uint64_t *server_uuid_random_seed48, int *next_entity_id) {
    int first_eid;
    int count;
    uint64_t entity_cursor, uuid_cursor;
    if (!m || !entity_seed_generator_seed48
            || !server_uuid_random_seed48 || !next_entity_id)
        return 0;
    first_eid = *next_entity_id;
    entity_cursor = *entity_seed_generator_seed48;
    uuid_cursor = *server_uuid_random_seed48;
    count = gm_mobs_spawn_xp_split_exact(
        m, x, y, z, dimension, total,
        math_random_seed48, next_entity_id);
    if (!count) return 0;
    for (int eid = first_eid; eid < first_eid + count; ++eid) {
        int slot = -1;
        JavaRandom generator, entity_random, uuid_random;
        for (int candidate = 0; candidate < xp_slot_limit(m); ++candidate) {
            McOrb *orb = xp_orb_at(m, candidate);
            if (!orb->dead && orb->xpValue > 0 && orb->eid == eid) {
                slot = candidate;
                break;
            }
        }
        if (slot < 0) return 0;
        jrand_set_seed48(&generator, entity_cursor);
        jrand_set(&entity_random, jrand_long(&generator));
        entity_cursor = generator.seed;
        jrand_set_seed48(&uuid_random, uuid_cursor);
        *xp_uuid_most_at(m, slot) =
            (jrand_long(&uuid_random) & INT64_C(-61441)) | INT64_C(16384);
        *xp_uuid_least_at(m, slot) =
            (jrand_long(&uuid_random) & INT64_C(4611686018427387903))
                | INT64_MIN;
        uuid_cursor = uuid_random.seed;
        *xp_random_seed_at(m, slot) = entity_random.seed;
        *xp_uuid_present_at(m, slot) = 1;
    }
    *entity_seed_generator_seed48 = entity_cursor;
    *server_uuid_random_seed48 = uuid_cursor;
    return count;
}

static int breeding_xp_spawn(
        GmMobLive *m, double x, double y, double z, int dimension,
        int value, uint64_t *math_random_seed48, int *next_entity_id,
        int *out_slot, int *out_eid) {
    int free_slot;
    uint64_t math_cursor;
    int eid;
    if (!m || value <= 0 || !math_random_seed48 || !next_entity_id
            || *next_entity_id <= 0 || *next_entity_id == INT_MAX)
        return 0;
    if (!loaded_order_reserve(m, m->loaded_order_count + 1)) return 0;
    free_slot = xp_free_slot(m, 1);
    eid = (*next_entity_id)++;
    if (m->next_id <= eid) m->next_id = eid + 1;
    if (m->next_orb_id <= eid) m->next_orb_id = eid + 1;
    math_cursor = *math_random_seed48;
    float yaw = (float)(mob_math_random_next_double(&math_cursor) * 360.0);
    float motion_x_float = (float)(
        mob_math_random_next_double(&math_cursor)
            * 0.20000000298023224 - 0.10000000149011612);
    float motion_y_float = (float)(
        mob_math_random_next_double(&math_cursor) * 0.2);
    float motion_z_float = (float)(
        mob_math_random_next_double(&math_cursor)
            * 0.20000000298023224 - 0.10000000149011612);
    *math_random_seed48 = math_cursor;
    if (out_eid) *out_eid = eid;
    if (out_slot) *out_slot = free_slot;
    if (free_slot < 0) {
        ++m->sheep_breed_xp_dropped;
        return -1;
    }
    McOrb *orb = xp_orb_at(m, free_slot);
    memset(orb, 0, sizeof *orb);
    orb->motionX = (double)(motion_x_float * 2.0F);
    orb->motionY = (double)(motion_y_float * 2.0F);
    orb->motionZ = (double)(motion_z_float * 2.0F);
    orb->xpValue = value;
    orb->health = 5;
    orb->eid = eid;
    orb->yaw = yaw;
    *xp_dimension_at(m, free_slot) = (signed char)dimension;
    eo_set_position(orb, x, y, z);
    if (m->next_orb_id <= eid) m->next_orb_id = eid + 1;
    (void)loaded_append_xp(m, free_slot);
    return 1;
}

static int animal_breed_slots(
        GmMobLive *m, EwStore *s, int initiator_slot, int mate_slot,
        int event_cancelled, int event_child_present,
        uint64_t *world_random_seed48, uint64_t *math_random_seed48,
        int *next_entity_id, int do_mob_loot, GmSheepMateResult *out) {
    JavaRandom world_random;
    int animal_type, child_type, child_eid;
    int child_fleece = -1, child_rabbit_type = -1, child_slot = -1;
    int first_fleece, second_fleece;
    int horse_birth, llama_birth;
    GmHorseChildGenetics horse_genetics;
    GmLlamaChildGenetics llama_genetics;
    if (!m || !s || initiator_slot <= 0 || mate_slot <= 0
            || initiator_slot >= EW_MAX_ENTITIES
            || mate_slot >= EW_MAX_ENTITIES
            || initiator_slot == mate_slot
            || !s->alive[initiator_slot] || !s->alive[mate_slot]
            || !gm_passive(s->type[initiator_slot])
            || (!horse_mating_pair_types(
                    s->type[initiator_slot], s->type[mate_slot])
                && s->type[mate_slot] != s->type[initiator_slot])
            || !world_random_seed48 || !math_random_seed48
            || !next_entity_id || *next_entity_id <= 0
            || *next_entity_id == INT_MAX
            || (event_cancelled != 0 && event_cancelled != 1)
            || (event_child_present != 0 && event_child_present != 1)
            || (do_mob_loot != 0 && do_mob_loot != 1))
        return GM_SHEEP_MATE_NONE;

    animal_type = s->type[initiator_slot];
    horse_birth = horse_mating_type(animal_type)
        && horse_mating_type(s->type[mate_slot]);
    llama_birth = animal_type == EW_TYPE_LLAMA
        && s->type[mate_slot] == EW_TYPE_LLAMA;
    child_type = animal_type;
    if (horse_birth || llama_birth) {
        if (!(m->horse_status[initiator_slot] & GM_HORSE_TAME)
                || !(m->horse_status[mate_slot] & GM_HORSE_TAME)
                || m->growing_age[initiator_slot] != 0
                || m->growing_age[mate_slot] != 0
                || m->sheep_in_love[initiator_slot] <= 0
                || m->sheep_in_love[mate_slot] <= 0
                || s->health[initiator_slot]
                    < (float)m->horse_max_health[initiator_slot]
                || s->health[mate_slot]
                    < (float)m->horse_max_health[mate_slot]
                || ride_is_slot(s, initiator_slot, m->horse_ride_eid)
                || ride_is_slot(s, mate_slot, m->horse_ride_eid))
            return GM_SHEEP_MATE_NONE;
    }
    /* createChild constructs the child and takes its global ID before the
     * EntityLivingBase constructor's three Math.random draws. Sheep alone
     * then performs the crafting/fallback color lookup before the event. */
    child_eid = (*next_entity_id)++;
    if (m->next_id <= child_eid) m->next_id = child_eid + 1;
    if (m->next_orb_id <= child_eid) m->next_orb_id = child_eid + 1;
    (void)mob_math_random_next_double(math_random_seed48);
    (void)mob_math_random_next_double(math_random_seed48);
    (void)mob_math_random_next_double(math_random_seed48);
    if (animal_type == EW_TYPE_SHEEP) {
        first_fleece = m->sheep_data[initiator_slot] & 15;
        second_fleece = m->sheep_data[mate_slot] & 15;
        jrand_set_seed48(&world_random, *world_random_seed48);
        child_fleece = gm_mobs_sheep_child_color(
            &world_random, first_fleece, second_fleece);
        *world_random_seed48 = world_random.seed;
    } else if (animal_type == EW_TYPE_RABBIT) {
        int roll = jrand_int_bound(
            &m->entity_random[initiator_slot].random, 100);
        child_rabbit_type = roll < 50 ? 0 : roll < 90 ? 5 : 2;
        if (jrand_int_bound(
                &m->entity_random[initiator_slot].random, 20) != 0) {
            child_rabbit_type = jrand_next(
                &m->entity_random[initiator_slot].random, 1) != 0
                ? m->rabbit_type[mate_slot]
                : m->rabbit_type[initiator_slot];
        }
    }
    if (horse_birth) {
        if (!horse_compute_child_genetics(
                m, s, initiator_slot, mate_slot, &horse_genetics))
            return GM_SHEEP_MATE_NONE;
        child_type = horse_genetics.type;
    } else if (llama_birth) {
        if (!llama_compute_child_genetics(
                m, s, initiator_slot, mate_slot, &llama_genetics))
            return GM_SHEEP_MATE_NONE;
        child_type = EW_TYPE_LLAMA;
    }
    if (out) {
        out->child_eid = child_eid;
        out->child_type = child_type;
        out->child_fleece = child_fleece;
        out->child_slot = -1;
        out->xp_eid = -1;
        out->xp_slot = -1;
        out->xp_value = 0;
    }

    if (event_cancelled) {
        m->growing_age[initiator_slot] = 6000;
        m->growing_age[mate_slot] = 6000;
        m->sheep_in_love[initiator_slot] = 0;
        m->sheep_in_love[mate_slot] = 0;
        m->sheep_bred_by_player[initiator_slot] = 0;
        m->sheep_bred_by_player[mate_slot] = 0;
        return GM_SHEEP_MATE_CANCELLED;
    }
    if (!event_child_present)
        return GM_SHEEP_MATE_NULL_CHILD;

    m->growing_age[initiator_slot] = 6000;
    m->growing_age[mate_slot] = 6000;
    m->sheep_in_love[initiator_slot] = 0;
    m->sheep_in_love[mate_slot] = 0;
    m->sheep_bred_by_player[initiator_slot] = 0;
    m->sheep_bred_by_player[mate_slot] = 0;

    int child_is_cold = 0;
    child_slot = living_spawn_slot(
        m, s, child_type, child_eid,
        s->x[initiator_slot], s->y[initiator_slot], s->z[initiator_slot],
        max_health(child_type, 1), &child_is_cold);
    if (child_slot >= 0) {
        m->entity_dimension[child_slot] = m->entity_dimension[initiator_slot];
        m->size[child_slot] = 1;
        reset_slot_state_s(m, s, child_slot);
        /* A freshly constructed Java entity is not grounded until its own
         * movement collision resolves a supporting block. */
        s->on_ground[child_slot] = 0;
        if (m->animal_child_state_count > 0) {
            int random_index = m->animal_child_state_head;
            m->entity_random[child_slot] =
                m->animal_child_random_queue[random_index];
            if (child_type == EW_TYPE_CHICKEN)
                m->chicken_time_until_next_egg[child_slot] =
                    m->animal_child_chicken_egg_queue[random_index];
            m->animal_child_state_head = (unsigned char)(
                (random_index + 1) % EW_MAX_ENTITIES);
            --m->animal_child_state_count;
        }
        m->growing_age[child_slot] = -24000;
        if (animal_type == EW_TYPE_SHEEP)
            m->sheep_data[child_slot] = (unsigned char)child_fleece;
        if (animal_type == EW_TYPE_RABBIT)
            m->rabbit_type[child_slot] = (unsigned char)child_rabbit_type;
        if (horse_birth)
            horse_apply_child_genetics(
                m, s, child_slot, &horse_genetics);
        else if (llama_birth) {
            horse_apply_child_genetics(
                m, s, child_slot, &llama_genetics.horse);
            m->llama_strength[child_slot] =
                (unsigned char)llama_genetics.strength;
            m->llama_variant[child_slot] =
                (unsigned char)llama_genetics.horse.variant;
        }
        s->yaw[child_slot] = 0.0F;
        child_slot = living_spawn_finish(
            m, s, child_slot, child_is_cold, 0);
    } else {
        ++m->sheep_birth_dropped;
    }
    if (out) out->child_slot = child_slot;

    GmMobParticleBatch hearts = {
        .eid = s->id[initiator_slot],
        .dimension = m->entity_dimension[initiator_slot],
        .particle_id = 34,
        .count = 7
    };
    float width, height;
    ehs_size_scaled(animal_type, 1, &width, &height);
    for (int particle_index = 0; particle_index < 7; ++particle_index) {
        GmTerminalParticle *particle = &hearts.particles[particle_index];
        particle->vx = jrand_gaussian_next(
            &m->entity_random[initiator_slot]) * 0.02;
        particle->vy = jrand_gaussian_next(
            &m->entity_random[initiator_slot]) * 0.02;
        particle->vz = jrand_gaussian_next(
            &m->entity_random[initiator_slot]) * 0.02;
        double offset_x = jrand_double(
            &m->entity_random[initiator_slot].random)
                * (double)width * 2.0 - (double)width;
        double offset_y = 0.5 + jrand_double(
            &m->entity_random[initiator_slot].random) * (double)height;
        double offset_z = jrand_double(
            &m->entity_random[initiator_slot].random)
                * (double)width * 2.0 - (double)width;
        particle->x = s->x[initiator_slot] + offset_x;
        particle->y = s->y[initiator_slot] + offset_y;
        particle->z = s->z[initiator_slot] + offset_z;
    }
    mob_particle_batch_append(m, &hearts);

    if (do_mob_loot) {
        int value = jrand_int_bound(
            &m->entity_random[initiator_slot].random, 7) + 1;
        int xp_slot = -1, xp_eid = -1;
        (void)breeding_xp_spawn(
            m, s->x[initiator_slot], s->y[initiator_slot],
            s->z[initiator_slot], m->entity_dimension[initiator_slot],
            value, math_random_seed48, next_entity_id,
            &xp_slot, &xp_eid);
        if (out) {
            out->xp_slot = xp_slot;
            out->xp_eid = xp_eid;
            out->xp_value = value;
        }
    }
    return GM_SHEEP_MATE_BORN;
}

static int terminal_slime_split_exact(
        GmMobLive *m, EwStore *s, int slot,
        int *next_entity_id, int *child_slots,
        int *child_count, int child_capacity) {
    if (child_count) *child_count = 0;
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !gm_is_slimey(s->type[slot]) || m->size[slot] <= 1
            || !next_entity_id || *next_entity_id <= 0)
        return 0;
    JavaRandom staged = m->entity_random[slot].random;
    int count = 2 + jrand_int_bound(&staged, 3);
    if (*next_entity_id > INT_MAX - count
            || !child_slots || !child_count || child_capacity < count)
        return 0;
    loaded_order_compact(m);
    if (!gm_mobs_living_cold_reserve(m, m->living_cold_count + count)
            || !loaded_order_reserve(m, m->loaded_order_count + count))
        return 0;

    int size = m->size[slot];
    int child_size = size / 2;
    int first_eid = *next_entity_id;
    int type = s->type[slot];
    int dimension = m->entity_dimension[slot];
    double x = s->x[slot], y = s->y[slot], z = s->z[slot];
    for (int k = 0; k < count; ++k) {
        float offset_x = ((float)(k % 2) - 0.5F)
            * (float)size / 4.0F;
        float offset_z = ((float)(k / 2) - 0.5F)
            * (float)size / 4.0F;
        int is_cold = 0;
        int child = living_spawn_slot(
            m, s, type, first_eid + k,
            x + (double)offset_x, y + 0.5D, z + (double)offset_z,
            max_health(type, child_size), &is_cold);
        if (child <= 0 || child >= EW_MAX_ENTITIES) return 0;
        m->entity_dimension[child] = (signed char)dimension;
        m->size[child] = (unsigned char)child_size;
        reset_slot_state_s(m, s, child);
        s->yaw[child] = jrand_float(&staged) * 360.0F;
        child_slots[k] = living_spawn_finish(
            m, s, child, is_cold, 0);
        if (child_slots[k] < 0) return 0;
    }
    m->entity_random[slot].random = staged;
    *child_count = count;
    *next_entity_id += count;
    if (m->next_id < *next_entity_id) m->next_id = *next_entity_id;
    if (m->next_orb_id < *next_entity_id)
        m->next_orb_id = *next_entity_id;
    return count;
}

static int tick_living_death_progress(
        GmMobLive *m, EwStore *s, int slot, int do_mob_loot,
        uint64_t *world_random_seed48,
        uint64_t *math_random_seed48, int *next_entity_id,
        int *slime_child_slots, int *slime_child_count,
        int slime_child_capacity) {
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !m->entity_dead[slot] || s->health[slot] > 0.0F)
        return 0;
    ++m->entity_death_time[slot];
    if (m->entity_death_time[slot] >= 20) {
        /* EntityLivingBase.onDeathUpdate creates XP before setDead and before
         * terminal particles. Adult EntityAnimal returns
         * 1 + World.rand.nextInt(3), which is one unsplit orb. */
        if (do_mob_loot && m->entity_recently_hit[slot] > 0) {
            if (gm_passive(s->type[slot]))
                (void)terminal_xp_spawn(
                    m, s->x[slot], s->y[slot], s->z[slot],
                    m->entity_dimension[slot], world_random_seed48,
                    math_random_seed48, next_entity_id);
            else if (s->type[slot] == EW_TYPE_WITCH) {
                int equipped = m->witch_drinking[slot]
                    && witch_potion_stack_meta(m->witch_potion[slot]) != 0;
                int total = ewitch_experience_points(
                    &m->entity_random[slot].random, equipped);
                (void)gm_mobs_spawn_xp_split_exact(
                    m, s->x[slot], s->y[slot], s->z[slot],
                    m->entity_dimension[slot], total,
                    math_random_seed48, next_entity_id);
            } else if (mob_exact_ordinary_death_type(s->type[slot])) {
                int total = gm_is_slimey(s->type[slot])
                    ? m->size[slot]
                    : (s->type[slot] == EW_TYPE_VILLAGER
                        || s->type[slot] == EW_TYPE_IRON_GOLEM) ? 0
                    : s->type[slot] == EW_TYPE_ENDERMITE ? 3
                    : s->type[slot] == EW_TYPE_VEX ? 3
                    : s->type[slot] == EW_TYPE_BLAZE
                        || s->type[slot] == EW_TYPE_EVOKER ? 10 : 5;
                if (total > 0)
                    (void)gm_mobs_spawn_xp_split_exact(
                        m, s->x[slot], s->y[slot], s->z[slot],
                        m->entity_dimension[slot], total,
                        math_random_seed48, next_entity_id);
            }
        }
        if (gm_is_slimey(s->type[slot]) && m->size[slot] > 1)
            (void)terminal_slime_split_exact(
                m, s, slot, next_entity_id,
                slime_child_slots, slime_child_count,
                slime_child_capacity);
        GmMobTerminalParticles batch = {
            .eid = s->id[slot],
            .dimension = m->entity_dimension[slot],
            .particle_id = 0,
            .ignore_range = 1,
            .parameter_count = 0
        };
        float width, height;
        ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
        /* EntityLivingBase.onDeathUpdate: three double Gaussian velocities,
         * then three float position draws widened only after multiplication. */
        for (int particle = 0; particle < 20; ++particle) {
            GmTerminalParticle *out = &batch.particles[particle];
            out->vx = jrand_gaussian_next(
                &m->entity_random[slot]) * 0.02;
            out->vy = jrand_gaussian_next(
                &m->entity_random[slot]) * 0.02;
            out->vz = jrand_gaussian_next(
                &m->entity_random[slot]) * 0.02;
            float offset_x = jrand_float(
                &m->entity_random[slot].random) * width * 2.0F;
            float offset_y = jrand_float(
                &m->entity_random[slot].random) * height;
            float offset_z = jrand_float(
                &m->entity_random[slot].random) * width * 2.0F;
            out->x = s->x[slot] + (double)offset_x - (double)width;
            out->y = s->y[slot] + (double)offset_y;
            out->z = s->z[slot] + (double)offset_z - (double)width;
        }
        terminal_particle_append(m, &batch);
        return 2;
    }
    return 1;
}

static int tick_controlled_death(
        GmMobLive *m, EwStore *s, int slot, int do_mob_loot,
        uint64_t *world_random_seed48,
        uint64_t *math_random_seed48, int *next_entity_id) {
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !m->controlled_no_ai[slot] || s->health[slot] > 0.0F)
        return 0;
    m->entity_dead[slot] = 1;
    return tick_living_death_progress(
        m, s, slot, do_mob_loot, world_random_seed48,
        math_random_seed48, next_entity_id, NULL, NULL, 0);
}

static void retire_terminal_living(GmMobLive *m, EwStore *s, int slot) {
    if (ride_is_slot(s, slot, m->pig_ride_eid)) {
        m->pig_ride_eid = -1;
        m->pig_vehicle_server.valid = 0;
    }
    if (ride_is_slot(s, slot, m->horse_ride_eid))
        m->horse_ride_eid = -1;
    /* Entity.setDead removes the entity from World but does not zero its data
     * manager or pig fields.  Slot reset clears these when a later entity
     * actually reuses the storage. */
    loaded_invalidate_living(m, slot);
    s->alive[slot] = 0;
    s->type[slot] = EW_TYPE_NONE;
    m->controlled_no_ai[slot] = 0;
    m->controlled_block_collisions[slot] = 0;
}

static void pig_update_passenger_pose(
        const EwStore *s, int slot, PsvPlayer *player, int ox, int oz) {
    /* Entity.updatePassenger after the ridden player's update:
     * (double)pig.height*.75 + EntityPlayer.getYOffset. */
    player->ent.posX = s->x[slot] - ox;
    player->ent.posY = s->y[slot] + (double)0.9F * 0.75D - 0.35D;
    player->ent.posZ = s->z[slot] - oz;
    player->ent.box = psv_player_box(
        player->ent.posX, player->ent.posY, player->ent.posZ);
    player->ent.motionX = 0.0;
    player->ent.motionY = 0.0;
    player->ent.motionZ = 0.0;
    player->fall_distance = 0.0F;
}

static void horse_update_passenger_pose(
        const GmMobLive *m, const EwStore *s, const McSinTable *sin_table,
        int slot,
        PsvPlayer *player, int ox, int oz) {
    float rearing = m->horse_rearing_amount[slot];
    float radians = s->yaw[slot] * 0.017453292F;
    if (s->type[slot] == EW_TYPE_LLAMA) {
        /* EntityLlama overrides AbstractHorse's rear-dependent pose with a
         * constant 0.3-block lateral offset and height*0.67 mount height. */
        player->ent.posX = s->x[slot]
            + (double)(0.3F * mc_sin(sin_table, radians)) - ox;
        player->ent.posY = s->y[slot] + (double)1.87F * 0.67D - 0.35D;
        player->ent.posZ = s->z[slot]
            - (double)(0.3F * mc_cos(sin_table, radians)) - oz;
        player->ent.box = psv_player_box(
            player->ent.posX, player->ent.posY, player->ent.posZ);
        player->ent.motionX = 0.0D;
        player->ent.motionY = 0.0D;
        player->ent.motionZ = 0.0D;
        player->fall_distance = 0.0F;
        return;
    }
    double offset = rearing > 0.0F ? (double)(0.7F * rearing) : 0.0D;
    player->ent.posX = s->x[slot]
        + offset * (double)mc_sin(sin_table, radians) - ox;
    double chest_offset = (s->type[slot] == EW_TYPE_DONKEY
            || s->type[slot] == EW_TYPE_MULE) ? -0.25D : 0.0D;
    player->ent.posY = s->y[slot] + (double)1.6F * 0.75D + chest_offset - 0.35D
        + (double)(0.15F * rearing);
    player->ent.posZ = s->z[slot]
        - offset * (double)mc_cos(sin_table, radians) - oz;
    player->ent.box = psv_player_box(
        player->ent.posX, player->ent.posY, player->ent.posZ);
    player->ent.motionX = 0.0D;
    player->ent.motionY = 0.0D;
    player->ent.motionZ = 0.0D;
    player->fall_distance = 0.0F;
}

static int pig_dismount_box_clear(
        GmWorld *world, const struct Chunk *window_,
        const McAABB *world_box, int ox, int oz);
static void pig_dismount_set_position(
        PsvPlayer *player, double x, double y, double z);

static void horse_dismount_player(
        GmWorld *world, const struct Chunk *window,
        const EwStore *s, const McSinTable *sin_table, int slot,
        PsvPlayer *player, int primary_right, int ox, int oz) {
    /* EntityLivingBase.dismountEntity's AbstractHorse branch. The represented
     * player's primary hand selects the opposite side of the mount. Keep every
     * intermediate as float where Java does before widening to double. */
    float side = ((float)MC_PI / 2.0F)
        * (primary_right ? -1.0F : 1.0F);
    float angle = -player->yaw * 0.017453292F - (float)MC_PI + side;
    float offset_x = -mc_sin(sin_table, angle);
    float offset_z = -mc_cos(sin_table, angle);
    double distance = (double)(0.6F / 2.0F + 1.3964844F / 2.0F) + 0.4D;
    double divisor = fabsf(offset_x) > fabsf(offset_z)
        ? (double)fabsf(offset_x) : (double)fabsf(offset_z);
    double scale = divisor > 0.0D ? distance / divisor : 0.0D;
    double x = player->ent.posX + (double)ox
        + (double)offset_x * scale;
    double y = s->y[slot] + (double)1.6F + 0.001D;
    double z = player->ent.posZ + (double)oz
        + (double)offset_z * scale;
    pig_dismount_set_position(
        player, x - (double)ox, y, z - (double)oz);
    McAABB world_box = mc_aabb_offset(
        &player->ent.box, (double)ox, 0.0D, (double)oz);
    if (!pig_dismount_box_clear(world, window, &world_box, ox, oz)) {
        y += 1.0D;
        pig_dismount_set_position(
            player, x - (double)ox, y, z - (double)oz);
        world_box = mc_aabb_offset(
            &player->ent.box, (double)ox, 0.0D, (double)oz);
        if (!pig_dismount_box_clear(world, window, &world_box, ox, oz))
            pig_dismount_set_position(
                player, s->x[slot] - (double)ox,
                s->y[slot] + (double)1.8F + 0.001D,
                s->z[slot] - (double)oz);
    }
}

static void chicken_living_tail(
    GmMobLive *m, EwStore *s, int slot,
    uint64_t *math_random_seed48, int *next_entity_id,
    GmLiveSim *drops);

static void iron_golem_living_tail(
    GmMobLive *m, GmWorld *w, EwStore *s, int slot);

static McSinTable s_squid_sin_table;
static double s_squid_asine[257];
static double s_squid_cosine[257];
static int s_squid_math_ready;

static void squid_math_init(void) {
    if (s_squid_math_ready) return;
    mc_sin_table_init(&s_squid_sin_table);
    for (int i = 0; i < 257; ++i) {
        double value = (double)i / 256.0D;
        double angle = asin(value);
        s_squid_asine[i] = angle;
        s_squid_cosine[i] = cos(angle);
    }
    s_squid_math_ready = 1;
}

static double squid_fast_inv_sqrt(double value) {
    union { double d; uint64_t u; } bits;
    double half = 0.5D * value;
    bits.d = value;
    bits.u = UINT64_C(6910469410427058090) - (bits.u >> 1);
    value = bits.d;
    return value * (1.5D - half * value * value);
}

static double squid_atan2(double y, double x) {
    double squared = x * x + y * y;
    if (isnan(squared)) return NAN;
    int negative_y = y < 0.0D;
    int negative_x = x < 0.0D;
    if (negative_y) y = -y;
    if (negative_x) x = -x;
    int swap = y > x;
    if (swap) {
        double temporary = x;
        x = y;
        y = temporary;
    }
    double inverse = squid_fast_inv_sqrt(squared);
    x *= inverse;
    y *= inverse;
    union { double d; uint64_t u; } biased;
    union { double d; uint64_t u; } frac_bias;
    frac_bias.u = UINT64_C(4805340802404319232);
    biased.d = y + frac_bias.d;
    int index = (int)(uint32_t)biased.u;
    double angle = s_squid_asine[index];
    double cosine = s_squid_cosine[index];
    double snapped = biased.d - frac_bias.d;
    double error = y * cosine - x * snapped;
    angle += (6.0D + error * error) * error
        * 0.16666666666666666D;
    if (swap) angle = (MC_PI / 2.0D) - angle;
    if (negative_x) angle = MC_PI - angle;
    if (negative_y) angle = -angle;
    return angle;
}

static float squid_wrap_degrees(float value) {
    value = fmodf(value, 360.0F);
    if (value >= 180.0F) value -= 360.0F;
    if (value < -180.0F) value += 360.0F;
    return value;
}

static void tick_squid(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot, int active) {
    squid_math_init();
    if (!active) {
        s->vx[slot] *= 0.98D;
        s->vy[slot] *= 0.98D;
        s->vz[slot] *= 0.98D;
    }
    if (fabs(s->vx[slot]) < 0.003D) s->vx[slot] = 0.0D;
    if (fabs(s->vy[slot]) < 0.003D) s->vy[slot] = 0.0D;
    if (fabs(s->vz[slot]) < 0.003D) s->vz[slot] = 0.0D;

    if (active) {
        if (m->entity_age[slot] > 100) {
            m->squid_random_motion_x[slot] = 0.0F;
            m->squid_random_motion_y[slot] = 0.0F;
            m->squid_random_motion_z[slot] = 0.0F;
        } else {
            JavaRandom *random = &m->entity_random[slot].random;
            int refresh = jrand_int_bound(random, 50) == 0;
            if (refresh || !m->entity_in_water[slot]
                    || (m->squid_random_motion_x[slot] == 0.0F
                        && m->squid_random_motion_y[slot] == 0.0F
                        && m->squid_random_motion_z[slot] == 0.0F)) {
                float angle = jrand_float(random) * (float)(MC_PI * 2.0D);
                m->squid_random_motion_x[slot] =
                    mc_cos(&s_squid_sin_table, angle) * 0.2F;
                m->squid_random_motion_y[slot] =
                    -0.1F + jrand_float(random) * 0.2F;
                m->squid_random_motion_z[slot] =
                    mc_sin(&s_squid_sin_table, angle) * 0.2F;
            }
        }
    }

    McAABB box = m->entity_box_valid[slot]
        ? mc_aabb_make(
            m->entity_box_min_x[slot], m->entity_box_min_y[slot],
            m->entity_box_min_z[slot], m->entity_box_max_x[slot],
            m->entity_box_max_y[slot], m->entity_box_max_z[slot])
        : mc_aabb_make(
            s->x[slot] - (double)0.8F * 0.5D, s->y[slot],
            s->z[slot] - (double)0.8F * 0.5D,
            s->x[slot] + (double)0.8F * 0.5D,
            s->y[slot] + (double)0.8F,
            s->z[slot] + (double)0.8F * 0.5D);
    McAABB query = mc_aabb_addcoord(
        &box, s->vx[slot], s->vy[slot], s->vz[slot]);
    query.minY -= 0.6F;
    query.maxY += 0.6F;
    PcfBlock blocks[GM_MOB_BLOCKS];
    int block_count = collect_blocks(w, &query, blocks, GM_MOB_BLOCKS);
    McPcfEntity entity = {0};
    entity.box = box;
    entity.posX = s->x[slot];
    entity.posY = s->y[slot];
    entity.posZ = s->z[slot];
    entity.motionX = s->vx[slot];
    entity.motionY = s->vy[slot];
    entity.motionZ = s->vz[slot];
    entity.stepHeight = 0.6F;
    entity.onGround = s->on_ground[slot] ? 1 : 0;
    entity.moverType = PCF_MOVER_SELF;
    double old_x = entity.posX;
    double old_y = entity.posY;
    double old_z = entity.posZ;
    pcf_entity_move(
        &entity, entity.motionX, entity.motionY, entity.motionZ,
        blocks, block_count);
    double moved_y = entity.posY - old_y;
    if (entity.onGround) m->entity_fall_distance[slot] = 0.0F;
    else if (moved_y < 0.0D)
        m->entity_fall_distance[slot] = (float)(
            (double)m->entity_fall_distance[slot] - moved_y);
    s->x[slot] = entity.posX;
    s->y[slot] = entity.posY;
    s->z[slot] = entity.posZ;
    s->vx[slot] = entity.motionX;
    s->vy[slot] = entity.motionY;
    s->vz[slot] = entity.motionZ;
    s->on_ground[slot] = (unsigned char)(entity.onGround ? 1 : 0);
    m->entity_collided_horizontal[slot] =
        (unsigned char)(entity.collidedHorizontally ? 1 : 0);
    m->entity_collided_vertical[slot] =
        (unsigned char)(entity.collidedVertically ? 1 : 0);
    m->entity_box_min_x[slot] = entity.box.minX;
    m->entity_box_min_y[slot] = entity.box.minY;
    m->entity_box_min_z[slot] = entity.box.minZ;
    m->entity_box_max_x[slot] = entity.box.maxX;
    m->entity_box_max_y[slot] = entity.box.maxY;
    m->entity_box_max_z[slot] = entity.box.maxZ;
    m->entity_box_valid[slot] = 1;

    m->squid_prev_pitch[slot] = m->squid_pitch[slot];
    m->squid_prev_yaw[slot] = m->squid_yaw[slot];
    m->squid_prev_rotation[slot] = m->squid_rotation[slot];
    m->squid_last_tentacle_angle[slot] =
        m->squid_tentacle_angle[slot];
    m->squid_rotation[slot] += m->squid_rotation_velocity[slot];
    if ((double)m->squid_rotation[slot] > MC_PI * 2.0D) {
        m->squid_rotation[slot] = (float)(
            (double)m->squid_rotation[slot] - MC_PI * 2.0D);
        if (jrand_int_bound(&m->entity_random[slot].random, 10) == 0)
            m->squid_rotation_velocity[slot] =
                1.0F / (jrand_float(&m->entity_random[slot].random) + 1.0F)
                * 0.2F;
    }
    const float pi = (float)MC_PI;
    if (m->entity_in_water[slot]) {
        if (m->squid_rotation[slot] < pi) {
            float phase = m->squid_rotation[slot] / pi;
            m->squid_tentacle_angle[slot] = mc_sin(
                &s_squid_sin_table, phase * phase * pi) * pi * 0.25F;
            if ((double)phase > 0.75D) {
                m->squid_random_motion_speed[slot] = 1.0F;
                m->squid_rotate_speed[slot] = 1.0F;
            } else {
                m->squid_rotate_speed[slot] *= 0.8F;
            }
        } else {
            m->squid_tentacle_angle[slot] = 0.0F;
            m->squid_random_motion_speed[slot] *= 0.9F;
            m->squid_rotate_speed[slot] *= 0.99F;
        }
        s->vx[slot] = (double)(m->squid_random_motion_x[slot]
            * m->squid_random_motion_speed[slot]);
        s->vy[slot] = (double)(m->squid_random_motion_y[slot]
            * m->squid_random_motion_speed[slot]);
        s->vz[slot] = (double)(m->squid_random_motion_z[slot]
            * m->squid_random_motion_speed[slot]);
        float horizontal = (float)sqrt(
            s->vx[slot] * s->vx[slot] + s->vz[slot] * s->vz[slot]);
        float target_yaw = -((float)squid_atan2(
            s->vx[slot], s->vz[slot])) * (180.0F / pi);
        m->squid_render_yaw_offset[slot] +=
            (target_yaw - m->squid_render_yaw_offset[slot]) * 0.1F;
        s->yaw[slot] = m->squid_render_yaw_offset[slot];
        m->squid_yaw[slot] = (float)(
            (double)m->squid_yaw[slot] + MC_PI
            * (double)m->squid_rotate_speed[slot] * 1.5D);
        float target_pitch = -((float)squid_atan2(
            (double)horizontal, s->vy[slot])) * (180.0F / pi);
        m->squid_pitch[slot] +=
            (target_pitch - m->squid_pitch[slot]) * 0.1F;
    } else {
        m->squid_tentacle_angle[slot] = fabsf(mc_sin(
            &s_squid_sin_table, m->squid_rotation[slot])) * pi * 0.25F;
        s->vx[slot] = 0.0D;
        s->vz[slot] = 0.0D;
        s->vy[slot] -= 0.08D;
        s->vy[slot] *= 0.9800000190734863D;
        m->squid_pitch[slot] = (float)(
            (double)m->squid_pitch[slot]
            + (double)(-90.0F - m->squid_pitch[slot]) * 0.02D);
        if (active)
            m->squid_render_yaw_offset[slot] = s->yaw[slot];
    }

    /* EntitySquid's active subclass update runs after EntityLiving's body
     * helper and owns the final renderYawOffset.  The controlled NoAI lane
     * retains the historical body-helper continuation below. */
    if (active) return;
    (void)old_x;
    (void)old_z;
    living_body_update(m, now_store(m), s, slot);
}

static int snowman_snow_can_place(
        const GmWorld *w, int x, int y, int z) {
    if (!w || y < 1 || gm_world_block(w, x, y, z) != 0) return 0;
    int below = gm_world_block(w, x, y - 1, z);
    int meta = gm_world_meta(w, x, y - 1, z);
    if (below == 79 || below == 174) return 0;
    if (below == 18 || below == 161) return 1;
    if (below == 78 && (meta & 7) == 7) return 1;
    return gm_block_is_fully_opaque_1_11_2(below, meta)
        && gm_block_material_blocks_movement_1_11_2(below, meta);
}

static void tick_snowman_living_tail(
        GmMobLive *m, GmWorld *w, const GmWorldClock *clock,
        EwStore *s, int slot, GmLiveSim *drops, int do_mob_loot,
        uint64_t *math_random_seed48, int *next_entity_id,
        int mob_griefing) {
    if (mob_slot_is_wet(m, w, clock, s, slot))
        (void)mob_source_damage_environment_slot_exact(
            m, s, slot, 1.0F, drops, math_random_seed48,
            next_entity_id, do_mob_loot, 1, 1);
    int base_x = mc_floor(s->x[slot]);
    int base_y = mc_floor(s->y[slot]);
    int base_z = mc_floor(s->z[slot]);
    if (gm_world_temperature(w, base_x, base_y, base_z) > 1.0F)
        (void)mob_source_damage_environment_slot_exact(
            m, s, slot, 1.0F, drops, math_random_seed48,
            next_entity_id, do_mob_loot, 1, 0);
    if (!mob_griefing) return;
    for (int corner = 0; corner < 4; ++corner) {
        int x = mc_floor(s->x[slot] + (double)(
            (float)(corner % 2 * 2 - 1) * 0.25F));
        int z = mc_floor(s->z[slot] + (double)(
            (float)(corner / 2 % 2 * 2 - 1) * 0.25F));
        if (gm_world_temperature(w, x, base_y, z) < 0.8F
                && snowman_snow_can_place(w, x, base_y, z))
            gm_world_set_block_meta(w, x, base_y, z, 78, 0);
    }
}

static void animal_age_love_tail(
        GmMobLive *m, EwStore *s, int slot) {
    if (m->growing_age[slot] < 0) ++m->growing_age[slot];
    else if (m->growing_age[slot] > 0) --m->growing_age[slot];
    /* EntityAnimal.onLivingUpdate follows EntityAgeable's server age step.
     * NoAI suppresses tasks and travel, not these lifecycle fields. */
    if (m->growing_age[slot] != 0) {
        m->sheep_in_love[slot] = 0;
        m->sheep_bred_by_player[slot] = 0;
    } else if (m->sheep_in_love[slot] > 0) {
        --m->sheep_in_love[slot];
        if (m->sheep_in_love[slot] % 10 == 0) {
            GmMobParticleBatch batch = {
                .eid = s->id[slot],
                .dimension = m->entity_dimension[slot],
                .particle_id = 34,
                .count = 1
            };
            GmTerminalParticle *particle = &batch.particles[0];
            float width, height;
            ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
            particle->vx = jrand_gaussian_next(
                &m->entity_random[slot]) * 0.02;
            particle->vy = jrand_gaussian_next(
                &m->entity_random[slot]) * 0.02;
            particle->vz = jrand_gaussian_next(
                &m->entity_random[slot]) * 0.02;
            particle->x = s->x[slot] + (double)(
                jrand_float(&m->entity_random[slot].random)
                    * width * 2.0F) - (double)width;
            particle->y = s->y[slot] + 0.5 + (double)(
                jrand_float(&m->entity_random[slot].random) * height);
            particle->z = s->z[slot] + (double)(
                jrand_float(&m->entity_random[slot].random)
                    * width * 2.0F) - (double)width;
            mob_particle_batch_append(m, &batch);
        }
    }
}

/* AbstractHorse.onLivingUpdate rolls the tail before EntityAnimal advances
 * age/love and emits a heart. Keep that draw on the shared entity cursor. */
static void horse_lifecycle_pre_tick(GmMobLive *m, EwStore *s, int slot) {
    if (!m || !s || !gm_mobs_horse_type(s->type[slot])) return;
    if (jrand_int_bound(&m->entity_random[slot].random, 200) == 0)
        m->horse_tail_counter[slot] = 1;
}

/* The rest of AbstractHorse.onLivingUpdate follows EntityAnimal, then the
 * subclass trap clock and AbstractHorse.onUpdate visual counters run. */
static int horse_lifecycle_post_tick(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot) {
    JavaRandom *random;
    float value;
    if (!m || !w || !s || !gm_mobs_horse_type(s->type[slot])) return 0;
    random = &m->entity_random[slot].random;
    if (jrand_int_bound(random, 900) == 0
            && m->entity_death_time[slot] == 0
            && s->health[slot] > 0.0F) {
        s->health[slot] += 1.0F;
        if (s->health[slot] > (float)m->horse_max_health[slot])
            s->health[slot] = (float)m->horse_max_health[slot];
    }
    if (s->type[slot] != EW_TYPE_LLAMA
            && !(m->horse_status[slot] & GM_HORSE_EATING)
            && !ride_is_slot(s, slot, m->horse_ride_eid)
            && m->skeleton_trap_rider_eid[slot] < 0
            && jrand_int_bound(random, 300) == 0
            && gm_world_block(w, mc_floor(s->x[slot]),
                              mc_floor(s->y[slot]) - 1,
                              mc_floor(s->z[slot])) == 2) {
        m->horse_status[slot] |= GM_HORSE_EATING;
    }
    if (m->horse_status[slot] & GM_HORSE_EATING) {
        if (++m->horse_eating_counter[slot] > 50) {
            m->horse_eating_counter[slot] = 0;
            m->horse_status[slot] &= (unsigned char)~GM_HORSE_EATING;
        }
    }
    if (s->type[slot] == EW_TYPE_SKELETON_HORSE
            && m->horse_trap[slot]
            && m->horse_trap_time[slot]++ >= 18000) {
        if (ride_is_slot(s, slot, m->horse_ride_eid))
            m->horse_ride_eid = -1;
        retire_terminal_living(m, s, slot);
        return 1;
    }
    if (m->horse_open_mouth_counter[slot] > 0
            && ++m->horse_open_mouth_counter[slot] > 30) {
        m->horse_open_mouth_counter[slot] = 0;
        m->horse_status[slot] &= (unsigned char)~GM_HORSE_MOUTH_OPEN;
    }
    if ((ride_is_slot(s, slot, m->horse_ride_eid)
                || m->skeleton_trap_rider_eid[slot] >= 0)
            && m->horse_jump_rearing_counter[slot] > 0
            && ++m->horse_jump_rearing_counter[slot] > 20) {
        m->horse_jump_rearing_counter[slot] = 0;
        m->horse_status[slot] &= (unsigned char)~GM_HORSE_REARING;
    }
    if (m->horse_tail_counter[slot] > 0
            && ++m->horse_tail_counter[slot] > 8)
        m->horse_tail_counter[slot] = 0;
    if (m->horse_sprint_counter[slot] > 0
            && ++m->horse_sprint_counter[slot] > 300)
        m->horse_sprint_counter[slot] = 0;

    m->horse_prev_head_lean[slot] = m->horse_head_lean[slot];
    if (m->horse_status[slot] & GM_HORSE_EATING) {
        float rhs = (1.0F - m->horse_head_lean[slot]) * 0.4F + 0.05F;
        value = m->horse_head_lean[slot] + rhs;
        m->horse_head_lean[slot] = value > 1.0F ? 1.0F : value;
    } else {
        float rhs = (0.0F - m->horse_head_lean[slot]) * 0.4F - 0.05F;
        value = m->horse_head_lean[slot] + rhs;
        m->horse_head_lean[slot] = value < 0.0F ? 0.0F : value;
    }
    m->horse_prev_rearing_amount[slot] =
        m->horse_rearing_amount[slot];
    if (m->horse_status[slot] & GM_HORSE_REARING) {
        m->horse_head_lean[slot] = 0.0F;
        m->horse_prev_head_lean[slot] = 0.0F;
        float rhs = (1.0F - m->horse_rearing_amount[slot])
            * 0.4F + 0.05F;
        value = m->horse_rearing_amount[slot] + rhs;
        m->horse_rearing_amount[slot] = value > 1.0F ? 1.0F : value;
    } else {
        m->horse_allow_stand_sliding[slot] = 0;
        float rhs = (0.8F * m->horse_rearing_amount[slot]
            * m->horse_rearing_amount[slot]
            * m->horse_rearing_amount[slot]
            - m->horse_rearing_amount[slot]) * 0.6F - 0.05F;
        value = m->horse_rearing_amount[slot] + rhs;
        m->horse_rearing_amount[slot] = value < 0.0F ? 0.0F : value;
    }
    m->horse_prev_mouth_openness[slot] =
        m->horse_mouth_openness[slot];
    if (m->horse_status[slot] & GM_HORSE_MOUTH_OPEN) {
        float rhs = (1.0F - m->horse_mouth_openness[slot])
            * 0.7F + 0.05F;
        value = m->horse_mouth_openness[slot] + rhs;
        m->horse_mouth_openness[slot] = value > 1.0F ? 1.0F : value;
    } else {
        float rhs = (0.0F - m->horse_mouth_openness[slot])
            * 0.7F - 0.05F;
        value = m->horse_mouth_openness[slot] + rhs;
        m->horse_mouth_openness[slot] = value < 0.0F ? 0.0F : value;
    }
    return 0;
}

static void tick_no_ai_ghast_flight(GmMobLive *m, EwStore *s, int slot) {
    s->vx[slot] *= 0.98D;
    s->vy[slot] *= 0.98D;
    s->vz[slot] *= 0.98D;
    if (fabs(s->vx[slot]) < 0.003D) s->vx[slot] = 0.0D;
    if (fabs(s->vy[slot]) < 0.003D) s->vy[slot] = 0.0D;
    if (fabs(s->vz[slot]) < 0.003D) s->vz[slot] = 0.0D;
    if (!m->entity_box_valid[slot]) {
        m->entity_box_min_x[slot] = s->x[slot] - 2.0D;
        m->entity_box_min_y[slot] = s->y[slot];
        m->entity_box_min_z[slot] = s->z[slot] - 2.0D;
        m->entity_box_max_x[slot] = s->x[slot] + 2.0D;
        m->entity_box_max_y[slot] = s->y[slot] + 4.0D;
        m->entity_box_max_z[slot] = s->z[slot] + 2.0D;
        m->entity_box_valid[slot] = 1;
    }
    m->entity_box_min_x[slot] += s->vx[slot];
    m->entity_box_max_x[slot] += s->vx[slot];
    m->entity_box_min_y[slot] += s->vy[slot];
    m->entity_box_max_y[slot] += s->vy[slot];
    m->entity_box_min_z[slot] += s->vz[slot];
    m->entity_box_max_z[slot] += s->vz[slot];
    s->x[slot] = (m->entity_box_min_x[slot]
        + m->entity_box_max_x[slot]) * 0.5D;
    s->y[slot] = m->entity_box_min_y[slot];
    s->z[slot] = (m->entity_box_min_z[slot]
        + m->entity_box_max_z[slot]) * 0.5D;
    s->vx[slot] *= (double)0.91F;
    s->vy[slot] *= (double)0.91F;
    s->vz[slot] *= (double)0.91F;
}

void gm_mobs_tick_controlled(GmMobLive *m, GmWorld *w,
                             const struct Chunk *window,
                             struct PsvPlayer *player, int ox, int oz,
                             int dimension, const GmWorldClock *clock,
                             int do_mob_loot, GmLiveSim *drops,
                             uint64_t *world_random_seed48,
                             uint64_t *math_random_seed48,
                             int *next_entity_id) {
    if (!m || !w || !player) return;
    m->active_dimension = dimension;
    EwStore *now = now_store(m), *next = next_store(m);
    ew_store_copy(next, now);
    loaded_order_prepare(m);
    unsigned char ticked_xp[GM_XP_ORBS] = {0};
    McAABB xp_player = xp_player_collision_box(
        (PsvPlayer *)player, ox, oz);
    m->xp_collision_count = 0;
    m->tick_update_order_count = 0;
    int initial_loaded_count = m->loaded_order_count;
    for (int loaded_index = 0;
            loaded_index < initial_loaded_count; ++loaded_index) {
        living_cold_flush_from_store(m, next);
        GmMobLoadedRef ref = *loaded_ref_at(m, loaded_index);
        if (ref.kind == GM_MOB_LOADED_XP) {
            int xp_slot = ref.slot;
            McOrb *orb = xp_orb_at(m, xp_slot);
            unsigned int *generation = xp_generation_at(m, xp_slot);
            signed char *orb_dimension = xp_dimension_at(m, xp_slot);
            if (!orb || !generation || !orb_dimension
                    || ref.generation != *generation
                    || orb->dead || orb->xpValue <= 0
                    || orb->eid != ref.eid || *orb_dimension != dimension)
                continue;
            tick_order_append(m, ref.eid);
            if (xp_slot < GM_XP_ORBS) ticked_xp[xp_slot] = 1;
            tick_xp_orb_slot(
                m, w, (PsvPlayer *)player, ox, oz, &xp_player, xp_slot);
            continue;
        }
        int i = living_loaded_ref_stage(m, &ref, next);
        if (i <= 0 || i >= EW_MAX_ENTITIES
                || ref.generation != m->living_loaded_generation[i]
                || !m->controlled_no_ai[i] || !next->alive[i]
                || next->id[i] != ref.eid
                || m->entity_dimension[i] != dimension)
            continue;
        tick_order_append(m, ref.eid);
        if (gm_is_slimey(next->type[i])) {
            m->squish_factor[i] +=
                (m->squish_amount[i] - m->squish_factor[i]) * 0.5F;
            m->prev_squish_factor[i] = m->squish_factor[i];
        }
        living_entity_base_begin(m, next, i);
        int squid_air_before = m->entity_air[i];
        if (next->type[i] == EW_TYPE_ZOMBIE_VILLAGER
                && zombie_villager_conversion_tick_slot(
                    m, w, next, i, next_entity_id))
            continue;
        tick_controlled_dead_fire(m, next, i);
        if (tick_exact_mob_environment(
                m, w, window, ox, oz, next, i, drops, do_mob_loot,
                math_random_seed48, next_entity_id))
            continue;
        if (mob_exact_environment_type(next->type[i])
                && next->alive[i] && next->health[i] > 0.0F
                && mob_slot_inside_suffocating_block(m, w, next, i)) {
            int source_result = mob_source_damage_environment_slot_exact(
                m, next, i, 1.0F, drops, math_random_seed48,
                next_entity_id, do_mob_loot, 1, 1);
            if (source_result < 0) continue;
            if (next->type[i] == EW_TYPE_ENDERMAN)
                (void)mob_try_enderman_random_teleport(m, w, next, i);
        }
        if (tick_mob_air(
                m, w, next, i, drops, do_mob_loot,
                math_random_seed48, next_entity_id))
            continue;
        if (mob_exact_environment_type(next->type[i])
                && next->alive[i] && next->health[i] > 0.0F
                && mob_slot_is_wet(m, w, clock, next, i))
            m->fire_ticks[i] = 0;
        if (next->type[i] == EW_TYPE_BLAZE)
            next->vy[i] = ebf_blaze_fall_damping(
                now->on_ground[i] ? 1 : 0, next->vy[i]);
        if (m->entity_hurt_time[i] > 0) --m->entity_hurt_time[i];
        if (m->entity_hurt_resistant[i] > 0)
            --m->entity_hurt_resistant[i];
        if (next->type[i] == EW_TYPE_BOAT) {
            if (m->boat_damage[i] > 0.0F) m->boat_damage[i] -= 1.0F;
            tick_boat(
                m, w, next, i, window, NULL,
                (PsvPlayer *)player, ox, oz,
                0.0F, 0.0F, 1, drops);
            continue;
        }
        if (!m->controlled_block_collisions[i]
                && next->type[i] == EW_TYPE_GHAST) {
            /* EntityLiving's NoAI 0.98 damping runs first, then
             * EntityFlying keeps its movement override and 0.91 drag. */
            tick_no_ai_ghast_flight(m, next, i);
        } else if (!m->controlled_block_collisions[i]
                && next->type[i] != EW_TYPE_SQUID) {
            /* EntityLiving with NoAI reports !isServerWorld: onLivingUpdate
             * damps existing motion but its travel branch does not move. */
            next->vx[i] *= 0.98D;
            next->vy[i] *= 0.98D;
            next->vz[i] *= 0.98D;
            if (fabs(next->vx[i]) < 0.003D) next->vx[i] = 0.0D;
            if (fabs(next->vy[i]) < 0.003D) next->vy[i] = 0.0D;
            if (fabs(next->vz[i]) < 0.003D) next->vz[i] = 0.0D;
        }
        if (!m->controlled_block_collisions[i]
                && next->type[i] == EW_TYPE_BAT) {
            if (m->bat_hanging[i]) {
                next->vx[i] = 0.0D;
                next->vy[i] = 0.0D;
                next->vz[i] = 0.0D;
                next->y[i] = floor(next->y[i]) + 1.0D
                    - (double)0.9F;
            } else {
                next->vy[i] *= 0.6000000238418579D;
            }
        }
        int death_state = tick_controlled_death(
            m, next, i, do_mob_loot, world_random_seed48,
            math_random_seed48, next_entity_id);
        if (m->entity_recently_hit[i] > 0)
            --m->entity_recently_hit[i];
        else
            m->entity_attacking_player[i] = 0;
        if (m->entity_effect_count[i] > 0)
            tick_mob_potion_effects(m, next, i, NULL);
        living_entity_ambient(m, next, i);
        if (tick_squid_air_tail(
                m, next, i, squid_air_before, drops, do_mob_loot,
                math_random_seed48, next_entity_id))
            continue;
        if (!m->controlled_block_collisions[i]
                && next->type[i] == EW_TYPE_SQUID)
            tick_squid(m, w, next, i, 0);
        if (!m->controlled_block_collisions[i]
                && next->type[i] == EW_TYPE_SNOWMAN)
            tick_snowman_living_tail(
                m, w, clock, next, i, drops, do_mob_loot,
                math_random_seed48, next_entity_id,
                m->controlled_mob_griefing);
        if (next->type[i] == EW_TYPE_ENDERMITE) {
            if (!m->persistence_required[i])
                ++m->endermite_lifetime[i];
            if (m->endermite_lifetime[i] >= 2400) {
                retire_terminal_living(m, next, i);
                continue;
            }
        }
        if (next->type[i] == EW_TYPE_WITCH)
            (void)witch_self_potion_step_slot(
                m, next, i,
                gm_uw_eye_inside_water(
                    w, next->x[i], next->y[i], next->z[i], 1.62F),
                m->fire_ticks[i] > 0, 0, 0.0);
        if (gm_mobs_vanilla_leashable_type(next->type[i])
                && m->llama_leashed[i]) {
            PsvPlayer *live_player = (PsvPlayer *)player;
            living_leash_tail(
                m, next, i, dimension,
                live_player->ent.posX + (double)ox,
                live_player->ent.posY,
                live_player->ent.posZ + (double)oz,
                live_player->health, math_random_seed48,
                next_entity_id, drops);
        }
        if (death_state == 2) {
            if (next->type[i] == EW_TYPE_PIG
                    && ride_is_slot(next, i, m->pig_ride_eid)) {
                gm_mobs_pig_dismount_explicit(
                    m, w, window, player, ox, oz);
                ((PsvPlayer *)player)->fall_distance = 0.0F;
            }
            retire_terminal_living(m, next, i);
        } else if (death_state == 1
                && next->type[i] == EW_TYPE_PIG
                && ride_is_slot(next, i, m->pig_ride_eid)) {
            pig_update_passenger_pose(
                next, i, (PsvPlayer *)player, ox, oz);
        } else if (death_state == 0) {
            if (gm_mobs_horse_type(next->type[i]))
                horse_lifecycle_pre_tick(m, next, i);
            if (gm_passive(next->type[i]))
                animal_age_love_tail(m, next, i);
            if (gm_mobs_horse_type(next->type[i])
                    && horse_lifecycle_post_tick(m, w, next, i))
                continue;
            if (next->type[i] == EW_TYPE_CHICKEN)
                chicken_living_tail(
                    m, next, i, math_random_seed48,
                    next_entity_id, NULL);
            if (next->type[i] == EW_TYPE_IRON_GOLEM)
                iron_golem_living_tail(m, w, next, i);
        }
        if (gm_is_slimey(next->type[i])) {
            int on_ground = next->on_ground[i] ? 1 : 0;
            if (on_ground && !m->was_on_ground[i])
                m->squish_amount[i] = -0.5F;
            else if (!on_ground && m->was_on_ground[i])
                m->squish_amount[i] = 1.0F;
            m->was_on_ground[i] = (unsigned char)on_ground;
            m->squish_amount[i] *=
                next->type[i] == EW_TYPE_MAGMA ? 0.9F : 0.6F;
        }
    }
    for (int xp_slot = 0; xp_slot < xp_slot_limit(m); ++xp_slot) {
        McOrb *orb = xp_orb_at(m, xp_slot);
        int ticked = xp_slot < GM_XP_ORBS ? ticked_xp[xp_slot] : 0;
        if (xp_slot >= GM_XP_ORBS)
            for (int index = 0; index < initial_loaded_count; ++index)
                if (loaded_ref_at(m, index)->kind == GM_MOB_LOADED_XP
                        && loaded_ref_at(m, index)->slot
                            == (unsigned int)xp_slot) {
                    ticked = 1;
                    break;
                }
        if (!ticked && !orb->dead && orb->xpValue > 0
                && *xp_dimension_at(m, xp_slot) == dimension) {
            tick_order_append(m, orb->eid);
            tick_xp_orb_slot(
                m, w, (PsvPlayer *)player, ox, oz, &xp_player, xp_slot);
        }
    }
    if (m->player_ticks_since_last_swing < 1000000000)
        ++m->player_ticks_since_last_swing;
    living_cold_flush_from_store(m, next);
    ++m->tick;
    m->current ^= 1;
    loaded_order_compact(m);
}

static int spawners_reserve(GmMobLive *m, int need) {
    enum { SAFETY_MAX = 1048576 };
    int cap;
    GmSpawnerTE *grown;
    if (!m || need < 0 || need > SAFETY_MAX) return 0;
    if (need <= m->spawners_cap) return 1;
    cap = m->spawners_cap > 0 ? m->spawners_cap : GM_SPAWNERS;
    while (cap < need) {
        if (cap > SAFETY_MAX / 2) {
            cap = SAFETY_MAX;
            break;
        }
        cap *= 2;
    }
    grown = (GmSpawnerTE *)realloc(
        m->spawners, (size_t)cap * sizeof *grown);
    if (!grown) return 0;
    memset(grown + m->spawners_cap, 0,
           (size_t)(cap - m->spawners_cap) * sizeof *grown);
    m->spawners = grown;
    m->spawners_cap = cap;
    return 1;
}

int gm_spawner_potentials_reserve(
        GmSpawnerPotential **potentials, int *capacity, int need) {
    enum { INITIAL_CAPACITY = 16, SAFETY_MAX = 1048576 };
    GmSpawnerPotential *grown;
    int cap;
    if (!potentials || !capacity || *capacity < 0
            || need < 0 || need > SAFETY_MAX)
        return 0;
    if (need <= *capacity) return 1;
    cap = *capacity > 0 ? *capacity : INITIAL_CAPACITY;
    while (cap < need) {
        if (cap > SAFETY_MAX / 2) {
            cap = SAFETY_MAX;
            break;
        }
        cap *= 2;
    }
    grown = (GmSpawnerPotential *)realloc(
        *potentials, (size_t)cap * sizeof *grown);
    if (!grown) return 0;
    memset(grown + *capacity, 0,
           (size_t)(cap - *capacity) * sizeof *grown);
    *potentials = grown;
    *capacity = cap;
    return 1;
}

int gm_mobs_register_spawner(GmMobLive *m, int x, int y, int z, int entity_type) {
    if (!m || !entity_type) return -1;
    for (int i = 0; i < m->spawners_cap; ++i) {
        if (m->spawners[i].active && m->spawners[i].x == x &&
            m->spawners[i].y == y && m->spawners[i].z == z &&
            m->spawners[i].dimension == m->active_dimension) {
            m->spawners[i].entity_type = entity_type;
            return i;
        }
    }
    for (int i = 0; i < m->spawners_cap; ++i) {
        if (m->spawners[i].active) continue;
        m->spawners[i].active = 1;
        m->spawners[i].dimension = m->active_dimension;
        m->spawners[i].x = x; m->spawners[i].y = y; m->spawners[i].z = z;
        m->spawners[i].entity_type = entity_type;
        m->spawners[i].delay = 20;
        m->spawners[i].min_delay = 200;
        m->spawners[i].max_delay = 800;
        m->spawners[i].spawn_count = 4;
        m->spawners[i].max_nearby = 6;
        m->spawners[i].spawn_range = 4;
        m->spawners[i].activate_range = 16;
        m->spawners[i].entity_nbt_tag_id = 0;
        m->spawners[i].default_entity_nbt = 1;
        m->spawners[i].mob_rotation = 0.0D;
        m->spawners[i].prev_mob_rotation = 0.0D;
        m->spawners[i].potential_count = 0;
        return i;
    }
    {
        int slot = m->spawners_cap;
        if (!spawners_reserve(m, slot + 1)) return -1;
        m->spawners[slot].active = 1;
        m->spawners[slot].dimension = m->active_dimension;
        m->spawners[slot].x = x;
        m->spawners[slot].y = y;
        m->spawners[slot].z = z;
        m->spawners[slot].entity_type = entity_type;
        m->spawners[slot].delay = 20;
        m->spawners[slot].min_delay = 200;
        m->spawners[slot].max_delay = 800;
        m->spawners[slot].spawn_count = 4;
        m->spawners[slot].max_nearby = 6;
        m->spawners[slot].spawn_range = 4;
        m->spawners[slot].activate_range = 16;
        m->spawners[slot].default_entity_nbt = 1;
        return slot;
    }
}

static int spawner_find(const GmMobLive *m, int x, int y, int z) {
    if (!m) return -1;
    for (int i = 0; i < m->spawners_cap; ++i)
        if (m->spawners[i].active
                && m->spawners[i].dimension == m->active_dimension
                && m->spawners[i].x == x && m->spawners[i].y == y
                && m->spawners[i].z == z)
            return i;
    return -1;
}

int gm_mobs_spawner_set_state(
        GmMobLive *m, int x, int y, int z, int entity_type,
        int delay, int min_delay, int max_delay, int spawn_count,
        int max_nearby, int activate_range, int spawn_range) {
    if (!m || !gm_living(entity_type)) return 0;
    int slot = gm_mobs_register_spawner(m, x, y, z, entity_type);
    if (slot < 0 || delay < -1 || min_delay < 0 || max_delay < 0
            || spawn_count < 0 || max_nearby < 0
            || activate_range < 0 || spawn_range < 0)
        return 0;
    GmSpawnerTE *sp = &m->spawners[slot];
    sp->delay = delay;
    sp->min_delay = min_delay;
    sp->max_delay = max_delay;
    sp->spawn_count = spawn_count;
    sp->max_nearby = max_nearby;
    sp->activate_range = activate_range;
    sp->spawn_range = spawn_range;
    sp->entity_nbt_tag_id = 0;
    sp->default_entity_nbt = 1;
    sp->mob_rotation = 0.0D;
    sp->prev_mob_rotation = 0.0D;
    sp->potential_count = 0;
    return 1;
}

int gm_mobs_spawner_add_potential(
        GmMobLive *m, int x, int y, int z, int entity_type, int weight) {
    int slot = spawner_find(m, x, y, z);
    if (slot < 0 || !gm_living(entity_type) || weight <= 0)
        return 0;
    GmSpawnerTE *sp = &m->spawners[slot];
    if (!gm_spawner_potentials_reserve(
            &sp->potentials, &sp->potential_cap,
            sp->potential_count + 1))
        return 0;
    int total = 0;
    for (int i = 0; i < sp->potential_count; ++i) {
        if (total > INT_MAX - sp->potentials[i].weight) return 0;
        total += sp->potentials[i].weight;
    }
    if (total > INT_MAX - weight) return 0;
    int index = sp->potential_count++;
    sp->potentials[index].type = entity_type;
    sp->potentials[index].weight = weight;
    sp->potentials[index].nbt_tag_id = 0;
    sp->potentials[index].default_entity_nbt = 1;
    return 1;
}

static int spawner_class_matches(int candidate, int existing) {
    if (candidate == existing) return 1;
    if (candidate == EW_TYPE_ZOMBIE)
        return existing == EW_TYPE_ZOMBIE_VILLAGER
            || existing == EW_TYPE_HUSK || existing == EW_TYPE_PIGMAN;
    if (candidate == EW_TYPE_SKELETON)
        return existing == EW_TYPE_WITHER_SKELETON
            || existing == EW_TYPE_STRAY;
    if (candidate == EW_TYPE_SPIDER)
        return existing == EW_TYPE_CAVE_SPIDER;
    if (candidate == EW_TYPE_GUARDIAN)
        return existing == EW_TYPE_ELDER_GUARDIAN;
    if (candidate == EW_TYPE_SLIME)
        return existing == EW_TYPE_MAGMA;
    return 0;
}

static int spawner_nearby_count(
        const GmMobLive *m, const EwStore *s,
        int candidate, const GmSpawnerTE *sp) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)s;
    const double range = (double)sp->spawn_range;
    const McAABB query = mc_aabb_make(
        sp->x - range, sp->y - range, sp->z - range,
        sp->x + 1.0 + range, sp->y + 1.0 + range,
        sp->z + 1.0 + range);
    int count = 0, cursor = 0, slot;
    while ((slot = living_next_slot_from_store(
                mutable_m, completed, &cursor)) > 0) {
        float width, height;
        McAABB box;
        if (!s->alive[slot]
                || m->entity_dimension[slot] != sp->dimension
                || !spawner_class_matches(candidate, s->type[slot]))
            continue;
        ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
        box = mc_aabb_make(
            s->x[slot] - (double)width * 0.5, s->y[slot],
            s->z[slot] - (double)width * 0.5,
            s->x[slot] + (double)width * 0.5,
            s->y[slot] + (double)height,
            s->z[slot] + (double)width * 0.5);
        if (mc_aabb_intersects(&query, &box)) ++count;
    }
    living_cold_flush_one_from_store(
        mutable_m, completed, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &mutable_m->living_staged_cold_secondary);
    return count;
}

static void spawner_reset_timer(
        GmSpawnerTE *sp, uint64_t *world_random_seed48) {
    JavaRandom random = {*world_random_seed48};
    if (sp->max_delay <= sp->min_delay)
        sp->delay = sp->min_delay;
    else
        sp->delay = sp->min_delay + jrand_int_bound(
            &random, sp->max_delay - sp->min_delay);
    if (sp->potential_count > 0) {
        int total = 0;
        for (int i = 0; i < sp->potential_count; ++i)
            total += sp->potentials[i].weight;
        if (total > 0) {
            int choice = jrand_int_bound(&random, total);
            for (int i = 0; i < sp->potential_count; ++i) {
                choice -= sp->potentials[i].weight;
                if (choice < 0) {
                    sp->entity_type = sp->potentials[i].type;
                    sp->entity_nbt_tag_id = sp->potentials[i].nbt_tag_id;
                    sp->default_entity_nbt =
                        sp->potentials[i].default_entity_nbt;
                    break;
                }
            }
        }
    }
    *world_random_seed48 = random.seed;
}

/* Discover block-52 spawners and stamp entity id from dimension/structure. */
static void discover_spawners(GmMobLive *m, GmWorld *w, double px, double py, double pz,
                              int dimension) {
    int pcx = mc_floor(px), pcy = mc_floor(py), pcz = mc_floor(pz);
    for (int x = pcx - 24; x <= pcx + 24; ++x)
        for (int y = pcy - 12; y <= pcy + 12; ++y)
            for (int z = pcz - 24; z <= pcz + 24; ++z) {
                if (y < 0 || y > 255) continue;
                if (gm_world_block(w, x, y, z) != 52) continue;
                int known = 0;
                for (int i = 0; i < m->spawners_cap; ++i)
                    if (m->spawners[i].active && m->spawners[i].x == x &&
                        m->spawners[i].y == y && m->spawners[i].z == z &&
                        m->spawners[i].dimension == dimension) {
                        known = 1; break;
                    }
                if (known) continue;
                int et = 0;
                if (dimension == -1) {
                    /* Fortress spawners are blaze; detect nearby nether brick. */
                    int bricks = 0;
                    for (int dx = -4; dx <= 4 && !bricks; ++dx)
                        for (int dy = -2; dy <= 2 && !bricks; ++dy)
                            for (int dz = -4; dz <= 4; ++dz)
                                if (gm_world_block(w, x + dx, y + dy, z + dz) == 112) {
                                    bricks = 1; break;
                                }
                    et = bricks ? EW_TYPE_BLAZE : 0;
                } else if (dimension == 0) {
                    int dungeon_kind = 0;
                    if (popmc_dungeon_spawner_info(
                            m->seed, x, y, z, &dungeon_kind)) {
                        et = dungeon_kind == POPMC_DUNGEON_MOB_SKELETON
                            ? EW_TYPE_SKELETON
                            : dungeon_kind == POPMC_DUNGEON_MOB_SPIDER
                                ? EW_TYPE_SPIDER : EW_TYPE_ZOMBIE;
                    } else if (popmc_mineshaft_spawner_info(
                                   m->seed, x, y, z)) {
                        et = EW_TYPE_CAVE_SPIDER;
                    } else {
                        /* Stronghold portal-room silverfish spawner. */
                        int frames = 0;
                        for (int dx = -8; dx <= 8; ++dx)
                            for (int dy = -4; dy <= 4; ++dy)
                                for (int dz = -8; dz <= 8; ++dz)
                                    if (gm_world_block(w, x + dx, y + dy, z + dz) == 120) ++frames;
                        et = frames >= 4 ? EW_TYPE_SILVERFISH : EW_TYPE_ZOMBIE;
                    }
                }
                if (et) gm_mobs_register_spawner(m, x, y, z, et);
            }
}

static void spawner_construct_living_candidate(
        JavaGaussianRandom *entity_random,
        uint64_t *entity_seed_generator_seed48,
        uint64_t *server_uuid_random_seed48,
        uint64_t *math_random_seed48,
        int64_t *uuid_most, int64_t *uuid_least) {
    JavaRandom generator;
    jrand_set_seed48(&generator, *entity_seed_generator_seed48);
    jrand_gaussian_set(entity_random, jrand_long(&generator));
    *entity_seed_generator_seed48 = generator.seed;
    skeleton_trap_next_uuid(
        server_uuid_random_seed48, uuid_most, uuid_least);

    /* EntityLivingBase's constructor initializes three cosmetic scalars from
     * Math.random. They are not serialized, but the process cursor is. */
    (void)mob_math_random_next_double(math_random_seed48);
    (void)mob_math_random_next_double(math_random_seed48);
    (void)mob_math_random_next_double(math_random_seed48);
}

static int spawner_candidate_box_clear(
        const GmMobLive *m, GmWorld *world, const EwStore *store, int type,
        double x, double y, double z,
        double player_x, double player_y, double player_z) {
    float width, height;
    ehs_size_scaled((u8)type, 1, &width, &height);
    double half = (double)width * 0.5D;
    McAABB candidate = mc_aabb_make(
        x - half, y, z - half,
        x + half, y + (double)height, z + half);
    PcfBlock blocks[GM_MOB_BLOCKS];
    int block_count = collect_blocks(
        world, &candidate, blocks, GM_MOB_BLOCKS);
    if (!pcf_collision_boxes_empty(&candidate, blocks, block_count))
        return 0;

    int x0 = mc_floor(candidate.minX), x1 = psv_ceil(candidate.maxX);
    int y0 = mc_floor(candidate.minY), y1 = psv_ceil(candidate.maxY);
    int z0 = mc_floor(candidate.minZ), z1 = psv_ceil(candidate.maxZ);
    for (int bx = x0; bx < x1; ++bx)
        for (int by = y0; by < y1; ++by)
            for (int bz = z0; bz < z1; ++bz) {
                int block = gm_world_block(world, bx, by, bz);
                if (block == 8 || block == 9 || block == 10 || block == 11)
                    return 0;
            }

    McAABB player = mc_aabb_make(
        player_x - 0.3D, player_y, player_z - 0.3D,
        player_x + 0.3D, player_y + 1.8D, player_z + 0.3D);
    if (mc_aabb_intersects(&candidate, &player)) return 0;
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)store;
    int clear = 1, cursor = 0, slot;
    while ((slot = living_next_slot_from_store(
                mutable_m, completed, &cursor)) > 0) {
        float other_width, other_height;
        if (!store->alive[slot]
                || m->entity_dimension[slot] != m->active_dimension)
            continue;
        ehs_size_scaled(
            store->type[slot], m->size[slot],
            &other_width, &other_height);
        double other_half = (double)other_width * 0.5D;
        McAABB other = mc_aabb_make(
            store->x[slot] - other_half, store->y[slot],
            store->z[slot] - other_half,
            store->x[slot] + other_half,
            store->y[slot] + (double)other_height,
            store->z[slot] + other_half);
        if (mc_aabb_intersects(&candidate, &other)) {
            clear = 0;
            break;
        }
    }
    living_cold_flush_one_from_store(
        mutable_m, completed, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &mutable_m->living_staged_cold_secondary);
    return clear;
}

static int spawner_grass_animal(int type) {
    switch (type) {
    case EW_TYPE_PIG:
    case EW_TYPE_SHEEP:
    case EW_TYPE_COW:
    case EW_TYPE_CHICKEN:
    case EW_TYPE_RABBIT:
    case EW_TYPE_WOLF:
    case EW_TYPE_HORSE:
    case EW_TYPE_DONKEY:
    case EW_TYPE_MULE:
    case EW_TYPE_SKELETON_HORSE:
    case EW_TYPE_ZOMBIE_HORSE:
    case EW_TYPE_LLAMA:
    case EW_TYPE_POLAR_BEAR:
        return 1;
    default:
        return 0;
    }
}

static int spawner_candidate_can_spawn(
        const GmMobLive *m, GmWorld *world, const EwStore *store, int type,
        double x, double y, double z,
        double player_x, double player_y, double player_z) {
    int bx = mc_floor(x), by = mc_floor(y), bz = mc_floor(z);
    if (spawner_grass_animal(type)) {
        int sky = gm_world_sky_light(world, bx, by, bz);
        int block = gm_world_block_light(world, bx, by, bz);
        if (gm_world_block(world, bx, by - 1, bz) != 2
                || (sky > block ? sky : block) <= 8)
            return 0;
    } else if (type == EW_TYPE_MOOSHROOM) {
        int sky = gm_world_sky_light(world, bx, by, bz);
        int block = gm_world_block_light(world, bx, by, bz);
        if (gm_world_block(world, bx, by - 1, bz) != 110
                || (sky > block ? sky : block) <= 8)
            return 0;
    }
    return spawner_candidate_box_clear(
        m, world, store, type, x, y, z,
        player_x, player_y, player_z);
}

static void spawner_default_living_initial_spawn(
        GmMobLive *m, int slot, int type,
        JavaGaussianRandom *candidate_random,
        uint64_t *world_random_seed48,
        uint64_t *server_uuid_random_seed48) {
    m->entity_random[slot] = *candidate_random;
    m->entity_server_random[slot] = *candidate_random;
    m->entity_random_follow_range_bonus[slot] =
        jrand_gaussian_next(&m->entity_random[slot]) * 0.05D;
    skeleton_trap_next_uuid(server_uuid_random_seed48, NULL, NULL);
    m->entity_left_handed[slot] = (unsigned char)(
        jrand_float(&m->entity_random[slot].random) < 0.05F);
    m->entity_server_random[slot] = m->entity_random[slot];
    if (type == EW_TYPE_SHEEP) {
        JavaRandom world_random = {*world_random_seed48};
        m->sheep_data[slot] = (unsigned char)
            gm_mobs_random_sheep_color(&world_random);
        *world_random_seed48 = world_random.seed;
    }
}

/* EntitySlime.onInitialSpawn precedes EntityLiving.onInitialSpawn. This
 * helper is shared by natural and default-NBT block-spawner births so neither
 * path can accidentally choose size from an outer sampler. */
static int fresh_slime_initial_size_zero(JavaGaussianRandom *random) {
    int power = jrand_int_bound(&random->random, 3);
    if (power < 2)
        (void)jrand_float(&random->random);
    return 1 << power;
}

/* Subclass constructor work that happens after EntityLivingBase's common
 * constructor but before setLocationAndAngles/onInitialSpawn. The generic
 * slot reset uses a deterministic fallback seed; strict births must replace
 * both the stored values and the private cursor with the Java candidate's
 * actual constructor continuation. EntitySquid is exceptional: its own
 * constructor deliberately discards that cursor and reseeds from 1 + EID. */
static void fresh_subclass_constructor_state(
        GmMobLive *m, EwStore *store, int slot, int type, int eid,
        JavaGaussianRandom *candidate_random) {
    if (!m || !store || slot <= 0 || !candidate_random) return;
    m->entity_random[slot] = *candidate_random;
    if (type == EW_TYPE_SQUID) {
        jrand_set(&m->entity_random[slot].random, (i64)(1 + eid));
        m->entity_random[slot].have_next_next_gaussian = 0;
        m->entity_random[slot].next_next_gaussian = 0.0;
        m->squid_rotation_velocity[slot] = 1.0F
            / (jrand_float(&m->entity_random[slot].random) + 1.0F) * 0.2F;
    } else if (type == EW_TYPE_CHICKEN) {
        m->chicken_time_until_next_egg[slot] =
            jrand_int_bound(&m->entity_random[slot].random, 6000) + 6000;
    } else if (type == EW_TYPE_GUARDIAN
            || type == EW_TYPE_ELDER_GUARDIAN) {
        m->guardian_tail_animation[slot] =
            jrand_float(&m->entity_random[slot].random);
    }
    if (gm_mobs_horse_type(type))
        horse_init_attributes(m, store, slot);
    *candidate_random = m->entity_random[slot];
    m->entity_server_random[slot] = m->entity_random[slot];
}

typedef struct {
    unsigned char zombie_set, zombie_child;
    unsigned char rabbit_set, rabbit_type;
    unsigned char horse_set, horse_coat;
    unsigned char llama_set, llama_variant;
    unsigned char polar_set;
} GmNaturalGroupData;

static void fresh_passive_initial_tail(
        GmMobLive *m, int slot, int type, int biome,
        GmNaturalGroupData *group) {
    JavaRandom *private_random;
    if (!m || slot <= 0) return;
    private_random = &m->entity_random[slot].random;
    if (type == EW_TYPE_RABBIT) {
        int roll = jrand_int_bound(private_random, 100);
        int rabbit_type;
        if (biome == 12 || biome == 13 || biome == 140)
            rabbit_type = roll < 80 ? 1 : 3;
        else if (biome == 2 || biome == 17 || biome == 130)
            rabbit_type = 4;
        else
            rabbit_type = roll < 50 ? 0 : (roll < 90 ? 5 : 2);
        if (group && group->rabbit_set) {
            rabbit_type = group->rabbit_type;
            m->growing_age[slot] = -24000;
        } else if (group) {
            group->rabbit_set = 1;
            group->rabbit_type = (unsigned char)rabbit_type;
        }
        m->rabbit_type[slot] = (unsigned char)rabbit_type;
    }
    if (gm_mobs_horse_type(type)) {
        if (jrand_int_bound(private_random, 5) == 0)
            m->growing_age[slot] = -24000;
        if (type == EW_TYPE_HORSE) {
            int coat;
            if (group && group->horse_set) {
                coat = group->horse_coat;
            } else {
                coat = jrand_int_bound(private_random, 7);
                if (group) {
                    group->horse_set = 1;
                    group->horse_coat = (unsigned char)coat;
                }
            }
            int markings = jrand_int_bound(private_random, 5);
            m->horse_variant[slot] = coat | (markings << 8);
        } else if (type == EW_TYPE_LLAMA) {
            int strength_bound = jrand_float(private_random) < 0.04F ? 5 : 3;
            m->llama_strength[slot] = (unsigned char)(
                1 + jrand_int_bound(private_random, strength_bound));
            if (group && group->llama_set) {
                m->llama_variant[slot] = group->llama_variant;
            } else {
                m->llama_variant[slot] = (unsigned char)
                    jrand_int_bound(private_random, 4);
                if (group) {
                    group->llama_set = 1;
                    group->llama_variant = m->llama_variant[slot];
                }
            }
        }
    }
    if (type == EW_TYPE_POLAR_BEAR && group) {
        if (group->polar_set)
            m->growing_age[slot] = -24000;
        else
            group->polar_set = 1;
    }
    m->entity_server_random[slot] = m->entity_random[slot];
}

/* Class-specific onInitialSpawn tail at clamped additional difficulty zero.
 * This is the fresh speedrun branch and is shared by periodic and default-NBT
 * block-spawner births. Constructor-only draws stay at each caller because
 * block spawners must consume them even when a candidate later fails. */
static void fresh_hostile_initial_tail_zero(
        GmMobLive *m, int slot, int type,
        uint64_t *world_random_seed48, GmNaturalGroupData *group) {
    if (gm_zombie(type) || type == EW_TYPE_PIGMAN) {
        JavaRandom *private_random = &m->entity_random[slot].random;
        JavaRandom world_random = {*world_random_seed48};
        if (type == EW_TYPE_ZOMBIE_VILLAGER)
            m->villager_profession[slot] = (unsigned char)
                jrand_int_bound(&world_random, 6);
        m->entity_can_pick_up_loot[slot] = (unsigned char)
            (jrand_float(private_random) < 0.0F);
        int child;
        if (group && group->zombie_set) {
            child = group->zombie_child;
        } else {
            child = jrand_float(&world_random) < 0.05F;
            if (group) {
                group->zombie_set = 1;
                group->zombie_child = (unsigned char)child;
            }
        }
        if (child) {
            m->growing_age[slot] = -24000;
            if (!(jrand_float(&world_random) < 0.05F))
                (void)jrand_float(&world_random);
        }
        *world_random_seed48 = world_random.seed;
        (void)jrand_float(private_random); /* break-doors gate */
        if (type == EW_TYPE_PIGMAN) {
            m->entity_mainhand[slot] = ic_mk(283, 1, 0);
            (void)jrand_float(private_random); /* held-item enchant gate */
        } else {
            (void)jrand_float(private_random); /* armor/equipment gate */
        }
        (void)jrand_double(private_random); /* knockback bonus */
        (void)jrand_double(private_random); /* follow-range bonus */
        (void)jrand_float(private_random);  /* leader gate */
    } else if (type == EW_TYPE_SKELETON || type == EW_TYPE_STRAY
            || type == EW_TYPE_WITHER_SKELETON) {
        JavaRandom *private_random = &m->entity_random[slot].random;
        if (type == EW_TYPE_WITHER_SKELETON) {
            m->entity_mainhand[slot] = ic_mk(272, 1, 0);
        } else {
            (void)jrand_float(private_random); /* armor/equipment gate */
            m->entity_mainhand[slot] = ic_mk(261, 1, 0);
            (void)jrand_float(private_random); /* bow enchant gate */
        }
        m->entity_can_pick_up_loot[slot] = (unsigned char)
            (jrand_float(private_random) < 0.0F);
    } else if (type == EW_TYPE_SPIDER) {
        JavaRandom world_random = {*world_random_seed48};
        (void)jrand_int_bound(&world_random, 100);
        *world_random_seed48 = world_random.seed;
    }
    m->entity_server_random[slot] = m->entity_random[slot];
}

static int spawner_nbt_boolean(
        const GmNbtBlob *nbt, const char *key, int fallback) {
    double value;
    if (!nbt || !gm_nbt_blob_find_number(nbt, key, &value, NULL))
        return fallback;
    return (int8_t)(int64_t)value != 0;
}

static int spawner_nbt_integer(
        const GmNbtBlob *nbt, const char *key, int fallback) {
    double value;
    if (!nbt || !gm_nbt_blob_find_number(nbt, key, &value, NULL))
        return fallback;
    if (value < (double)INT_MIN) return INT_MIN;
    if (value > (double)INT_MAX) return INT_MAX;
    return (int)value;
}

/* EntityList.createEntityFromNBT applies these represented Entity,
 * EntityLivingBase, EntityLiving, EntityAgeable, EntityAnimal, and pig fields
 * before MobSpawnerBaseLogic chooses its random yaw. Missing primitive tags
 * deliberately become Java's zero values; Health is the one conditional
 * living field and therefore retains the constructor maximum when absent. */
static void spawner_apply_custom_living_nbt(
        GmMobLive *m, int slot, int eid, const GmNbtBlob *nbt,
        const JavaGaussianRandom *candidate_random) {
    EwStore *now = now_store(m);
    EwStore *next = next_store(m);
    double value;
    double motion[3] = {0.0, 0.0, 0.0};
    size_t motion_count = 0;
    int element_type = 0;
    if (!m || !now || !next || slot <= 0 || !nbt || !candidate_random)
        return;
    {
        float width, height;
        double half;
        ehs_size_scaled(now->type[slot], m->size[slot], &width, &height);
        half = (double)width * 0.5D;
        m->entity_box_min_x[slot] = now->x[slot] - half;
        m->entity_box_min_y[slot] = now->y[slot];
        m->entity_box_min_z[slot] = now->z[slot] - half;
        m->entity_box_max_x[slot] = now->x[slot] + half;
        m->entity_box_max_y[slot] = now->y[slot] + (double)height;
        m->entity_box_max_z[slot] = now->z[slot] + half;
        m->entity_box_valid[slot] = 1;
    }
    m->entity_random[slot] = *candidate_random;
    m->entity_server_random[slot] = *candidate_random;
    (void)gm_nbt_blob_find_numeric_list(
        nbt, "Motion", motion, 3, &motion_count, &element_type);
    (void)element_type;
    for (int axis = 0; axis < 3; ++axis)
        if ((size_t)axis >= motion_count || fabs(motion[axis]) > 10.0D)
            motion[axis] = 0.0D;
    now->vx[slot] = motion[0];
    now->vy[slot] = motion[1];
    now->vz[slot] = motion[2];
    next->vx[slot] = motion[0];
    next->vy[slot] = motion[1];
    next->vz[slot] = motion[2];
    m->entity_fall_distance[slot] = 0.0F;
    if (gm_nbt_blob_find_number(nbt, "FallDistance", &value, NULL))
        m->entity_fall_distance[slot] = (float)value;
    m->entity_server_fall_distance[slot] =
        m->entity_fall_distance[slot];
    m->fire_ticks[slot] = (int16_t)spawner_nbt_integer(
        nbt, "Fire", 0);
    m->entity_air[slot] = (int16_t)spawner_nbt_integer(
        nbt, "Air", 0);
    now->on_ground[slot] = (unsigned char)spawner_nbt_boolean(
        nbt, "OnGround", 0);
    next->on_ground[slot] = now->on_ground[slot];
    m->entity_portal_cooldown[slot] = spawner_nbt_integer(
        nbt, "PortalCooldown", 0);
    m->entity_absorption[slot] = 0.0F;
    if (gm_nbt_blob_find_number(nbt, "AbsorptionAmount", &value, NULL))
        m->entity_absorption[slot] = (float)value;
    if (gm_nbt_blob_find_number(nbt, "Health", &value, NULL)) {
        float health = (float)value;
        float maximum = gm_mobs_max_health(m, slot);
        if (health < 0.0F) health = 0.0F;
        if (health > maximum) health = maximum;
        now->health[slot] = health;
        next->health[slot] = health;
    }
    m->entity_hurt_time[slot] = (int16_t)spawner_nbt_integer(
        nbt, "HurtTime", 0);
    m->entity_death_time[slot] = (int16_t)spawner_nbt_integer(
        nbt, "DeathTime", 0);
    m->persistence_required[slot] = (unsigned char)spawner_nbt_boolean(
        nbt, "PersistenceRequired", 0);
    m->entity_left_handed[slot] = (unsigned char)spawner_nbt_boolean(
        nbt, "LeftHanded", 0);
    if (gm_nbt_blob_find_number(nbt, "CanPickUpLoot", &value, NULL))
        m->entity_can_pick_up_loot[slot] =
            (unsigned char)((int8_t)(int64_t)value != 0);
    m->growing_age[slot] = spawner_nbt_integer(nbt, "Age", 0);
    m->sheep_forced_age[slot] = spawner_nbt_integer(
        nbt, "ForcedAge", 0);
    m->sheep_in_love[slot] = spawner_nbt_integer(nbt, "InLove", 0);
    if (now->type[slot] == EW_TYPE_SHEEP) {
        int color = spawner_nbt_integer(nbt, "Color", 0) & 15;
        int sheared = spawner_nbt_boolean(nbt, "Sheared", 0);
        m->sheep_data[slot] = (unsigned char)(color | (sheared ? 16 : 0));
        m->passive_sheared[slot] = (unsigned char)sheared;
    } else if (now->type[slot] == EW_TYPE_RABBIT) {
        int rabbit_type = spawner_nbt_integer(nbt, "RabbitType", 0);
        if (rabbit_type < 0) rabbit_type = 0;
        if (rabbit_type > 255) rabbit_type = 255;
        m->rabbit_type[slot] = (unsigned char)rabbit_type;
        m->rabbit_carrot_ticks[slot] = spawner_nbt_integer(
            nbt, "MoreCarrotTicks", 0);
    } else if (now->type[slot] == EW_TYPE_VILLAGER) {
        int profession = spawner_nbt_integer(nbt, "Profession", 0);
        if (profession < 0 || profession > 5) profession = 0;
        m->villager_profession[slot] = (unsigned char)profession;
        m->villager_willing[slot] = (unsigned char)spawner_nbt_boolean(
            nbt, "Willing", 0);
        m->entity_can_pick_up_loot[slot] = 1;
    } else if (now->type[slot] == EW_TYPE_CREEPER) {
        m->creeper_powered[slot] = (unsigned char)spawner_nbt_boolean(
            nbt, "powered", 0);
        if (spawner_nbt_boolean(nbt, "ignited", 0))
            m->creeper_fuse[slot] = 1;
    } else if (now->type[slot] == EW_TYPE_PIGMAN) {
        m->anger[slot] = spawner_nbt_integer(nbt, "Anger", 0);
    } else if (now->type[slot] == EW_TYPE_BAT) {
        m->bat_hanging[slot] = (unsigned char)(
            spawner_nbt_integer(nbt, "BatFlags", 0) & 1);
    } else if (now->type[slot] == EW_TYPE_SNOWMAN) {
        m->snowman_pumpkin[slot] = (unsigned char)spawner_nbt_boolean(
            nbt, "Pumpkin", 1);
    } else if (now->type[slot] == EW_TYPE_ENDERMITE) {
        m->endermite_lifetime[slot] = spawner_nbt_integer(
            nbt, "Lifetime", 0);
        m->endermite_player_spawned[slot] = (unsigned char)
            spawner_nbt_boolean(nbt, "PlayerSpawned", 0);
    } else if (now->type[slot] == EW_TYPE_IRON_GOLEM) {
        m->golem_player_created[slot] = (unsigned char)
            spawner_nbt_boolean(nbt, "PlayerCreated", 0);
    } else if (now->type[slot] == EW_TYPE_ZOMBIE_VILLAGER) {
        int conversion = spawner_nbt_integer(nbt, "ConversionTime", -1);
        m->zombie_villager_conversion_time[slot] = conversion > -1
            ? conversion : -1;
    } else if (now->type[slot] == EW_TYPE_SLIME
            || now->type[slot] == EW_TYPE_MAGMA) {
        int serialized_size = spawner_nbt_integer(nbt, "Size", 0);
        int size;
        if (serialized_size < 0) serialized_size = 0;
        size = serialized_size < 254 ? serialized_size + 1 : 255;
        m->size[slot] = (unsigned char)size;
        /* EntitySlime.readEntityFromNBT calls setSlimeSize(size,false): max
         * health and collision size change after the common Health tag, but
         * current health is deliberately not refilled. */
        {
            float width, height;
            double half;
            ehs_size_scaled(now->type[slot], size, &width, &height);
            half = (double)width * 0.5D;
            m->entity_box_min_x[slot] = now->x[slot] - half;
            m->entity_box_min_y[slot] = now->y[slot];
            m->entity_box_min_z[slot] = now->z[slot] - half;
            m->entity_box_max_x[slot] = now->x[slot] + half;
            m->entity_box_max_y[slot] = now->y[slot] + (double)height;
            m->entity_box_max_z[slot] = now->z[slot] + half;
            m->entity_box_valid[slot] = 1;
        }
    } else if (now->type[slot] == EW_TYPE_WOLF
            || now->type[slot] == EW_TYPE_OCELOT) {
        char owner[64];
        int owned = gm_nbt_blob_find_string(
            nbt, "OwnerUUID", owner, sizeof owner) && owner[0];
        m->tameable_tamed[slot] = (unsigned char)owned;
        m->tameable_owner[slot] = (unsigned char)owned;
        m->tameable_sitting[slot] = (unsigned char)spawner_nbt_boolean(
            nbt, "Sitting", 0);
        m->tameable_sit_requested[slot] = m->tameable_sitting[slot];
        if (now->type[slot] == EW_TYPE_WOLF) {
            m->wolf_angry[slot] = (unsigned char)spawner_nbt_boolean(
                nbt, "Angry", 0);
            m->tameable_variant[slot] = (unsigned char)(
                spawner_nbt_integer(nbt, "CollarColor", 14) & 15);
        } else {
            m->tameable_variant[slot] = (unsigned char)(
                spawner_nbt_integer(nbt, "CatType", 0) & 255);
        }
    } else if (gm_mobs_horse_type(now->type[slot])) {
        int temper = spawner_nbt_integer(nbt, "Temper", 0);
        int tame = spawner_nbt_boolean(nbt, "Tame", 0);
        if (temper < 0) temper = 0;
        if (temper > 100) temper = 100;
        m->horse_temper[slot] = temper;
        if (tame) m->horse_status[slot] |= GM_HORSE_TAME;
        else m->horse_status[slot] &= (unsigned char)~GM_HORSE_TAME;
        if (spawner_nbt_boolean(nbt, "EatingHaystack", 0))
            m->horse_status[slot] |= GM_HORSE_EATING;
        else m->horse_status[slot] &= (unsigned char)~GM_HORSE_EATING;
        if (now->type[slot] == EW_TYPE_HORSE)
            m->horse_variant[slot] = spawner_nbt_integer(
                nbt, "Variant", 0);
        if (now->type[slot] == EW_TYPE_LLAMA) {
            int strength = spawner_nbt_integer(nbt, "Strength", 0);
            if (strength < 1) strength = 1;
            if (strength > 5) strength = 5;
            m->llama_strength[slot] = (unsigned char)strength;
            m->llama_variant[slot] = (unsigned char)(
                spawner_nbt_integer(nbt, "Variant", 0) & 3);
        }
    }
    {
        size_t effect_count = 0;
        int effect_type = 0;
        GmNbtBlob effect = {0};
        m->entity_effect_count[slot] = 0;
        memset(m->entity_effects[slot], 0, sizeof m->entity_effects[slot]);
        memset(m->entity_effect_flags[slot], 0,
               sizeof m->entity_effect_flags[slot]);
        if (gm_nbt_blob_find_list_info(
                nbt, "ActiveEffects", &effect_count, &effect_type)
                && effect_type == 10) {
            for (size_t index = 0; index < effect_count
                    && m->entity_effect_count[slot]
                        < GM_MOB_EFFECT_CAPACITY; ++index) {
                int id, amplifier, duration, ambient, show_particles;
                int out = m->entity_effect_count[slot];
                if (!gm_nbt_blob_extract_compound_list_element(
                        nbt, "ActiveEffects", index, &effect))
                    break;
                id = spawner_nbt_integer(&effect, "Id", 0) & 255;
                amplifier = spawner_nbt_integer(
                    &effect, "Amplifier", 0) & 255;
                duration = spawner_nbt_integer(&effect, "Duration", 0);
                ambient = spawner_nbt_boolean(&effect, "Ambient", 0);
                show_particles = spawner_nbt_boolean(
                    &effect, "ShowParticles", 1);
                if (id > 0 && id <= 27 && duration > 0) {
                    m->entity_effects[slot][out] = (PtMobEffect){
                        id, duration, amplifier
                    };
                    m->entity_effect_flags[slot][out] = (unsigned char)(
                        (ambient ? 1 : 0) | (show_particles ? 0 : 2));
                    m->entity_effect_count[slot] = (unsigned char)(out + 1);
                }
                gm_nbt_blob_clear(&effect);
            }
        }
        gm_nbt_blob_clear(&effect);
    }
    if (now->type[slot] == EW_TYPE_PIG)
        m->pig_saddled[slot] = (unsigned char)spawner_nbt_boolean(
            nbt, "Saddle", 0);
    (void)gm_mobs_set_no_ai(
        m, eid, spawner_nbt_boolean(nbt, "NoAI", 0));
}

static void spawner_client_rotation_tick(GmSpawnerTE *sp, int activated) {
    if (!sp) return;
    sp->prev_mob_rotation = sp->mob_rotation;
    if (!activated) return;
    sp->mob_rotation = fmod(
        sp->mob_rotation + (double)(1000.0F / ((float)sp->delay + 200.0F)),
        360.0D);
}

int gm_mobs_spawn_spawner_candidate(
        GmMobLive *m, GmWorld *world, int entity_type,
        int origin_x, int origin_y, int origin_z,
        int spawn_range, int max_nearby,
        double x, double y, double z,
        double player_x, double player_y, double player_z,
        uint64_t *world_random_seed48, uint64_t *math_random_seed48,
        uint64_t *entity_seed_generator_seed48,
        uint64_t *server_uuid_random_seed48, int *next_entity_id,
        const GmNbtBlob *entity_nbt, int default_entity_nbt) {
    GmSpawnerTE query = {0};
    JavaGaussianRandom candidate_random;
    JavaRandom random;
    int64_t uuid_most, uuid_least;
    const EwStore *current;
    int eid, slot;
    float yaw;
    if (!m || !world || !gm_living(entity_type)
            || spawn_range < 0 || max_nearby < 0
            || !world_random_seed48 || !math_random_seed48
            || !entity_seed_generator_seed48
            || !server_uuid_random_seed48 || !next_entity_id
            || (default_entity_nbt != 0 && default_entity_nbt != 1))
        return 0;
    query.x = origin_x;
    query.y = origin_y;
    query.z = origin_z;
    query.dimension = m->active_dimension;
    query.spawn_range = spawn_range;
    spawner_construct_living_candidate(
        &candidate_random, entity_seed_generator_seed48,
        server_uuid_random_seed48, math_random_seed48,
        &uuid_most, &uuid_least);
    if (gm_zombie(entity_type) || entity_type == EW_TYPE_PIGMAN)
        (void)jrand_double(&candidate_random.random);
    current = now_store(m);
    if (spawner_nearby_count(m, current, entity_type, &query)
            >= max_nearby)
        return -1;
    random.seed = *world_random_seed48;
    yaw = jrand_float(&random) * 360.0F;
    *world_random_seed48 = random.seed;
    if (!spawner_candidate_can_spawn(
            m, world, current, entity_type, x, y, z,
            player_x, player_y, player_z))
        return 0;
    eid = *next_entity_id;
    slot = gm_mobs_spawn_natural_eid(m, entity_type, eid, x, y, z);
    if (slot < 0) return 0;
    ++*next_entity_id;
    if (m->next_id < *next_entity_id) m->next_id = *next_entity_id;
    m->entity_uuid_present[slot] = 1;
    m->entity_uuid_most[slot] = uuid_most;
    m->entity_uuid_least[slot] = uuid_least;
    if (default_entity_nbt) {
        fresh_subclass_constructor_state(
            m, now_store(m), slot, entity_type, eid, &candidate_random);
        if (entity_type == EW_TYPE_SLIME || entity_type == EW_TYPE_MAGMA) {
            int size = fresh_slime_initial_size_zero(&candidate_random);
            m->size[slot] = (unsigned char)size;
            now_store(m)->health[slot] = max_health(entity_type, size);
            next_store(m)->health[slot] = max_health(entity_type, size);
        }
        /* EntityPolarBear.onInitialSpawn intentionally does not delegate to
         * EntityLiving.onInitialSpawn in 1.11.2. */
        if (entity_type != EW_TYPE_POLAR_BEAR)
            spawner_default_living_initial_spawn(
                m, slot, entity_type, &candidate_random,
                world_random_seed48, server_uuid_random_seed48);
        fresh_hostile_initial_tail_zero(
            m, slot, entity_type, world_random_seed48, NULL);
        fresh_passive_initial_tail(
            m, slot, entity_type,
            gm_world_biome(world, mc_floor(x), mc_floor(z)), NULL);
    } else {
        spawner_apply_custom_living_nbt(
            m, slot, eid, entity_nbt, &candidate_random);
    }
    now_store(m)->yaw[slot] = yaw;
    next_store(m)->yaw[slot] = yaw;
    return 1;
}

int gm_mobs_tick_spawner_at(
        GmMobLive *m, GmWorld *w, int x, int y, int z,
        double px, double py, double pz,
        uint64_t *world_random_seed48, uint64_t *math_random_seed48,
        uint64_t *entity_seed_generator_seed48,
        uint64_t *server_uuid_random_seed48, int *next_entity_id,
        const GmNbtBlob *spawn_data) {
    int index = spawner_find(m, x, y, z);
    if (index < 0) return -1;
    GmSpawnerTE *sp = &m->spawners[index];
    if (!w || !world_random_seed48 || !math_random_seed48
            || !entity_seed_generator_seed48
            || !server_uuid_random_seed48 || !next_entity_id)
        return 0;
    if (gm_world_block(w, x, y, z) != 52) {
        sp->active = 0;
        return 0;
    }
    double dx = px - (x + 0.5), dy = py - (y + 0.5),
           dz = pz - (z + 0.5);
    double range = (double)sp->activate_range;
    if (dx * dx + dy * dy + dz * dz >= range * range) {
        spawner_client_rotation_tick(sp, 0);
        return 0;
    }
    if (sp->delay == -1)
        spawner_reset_timer(sp, world_random_seed48);
    if (sp->delay > 0) {
        --sp->delay;
        spawner_client_rotation_tick(sp, 1);
        return 0;
    }
    int spawned = 0;
    for (int attempt = 0; attempt < sp->spawn_count; ++attempt) {
        JavaRandom random = {*world_random_seed48};
        double position[3] = {0.0, 0.0, 0.0};
        size_t position_count = 0;
        int position_type = 0;
        if (spawn_data)
            (void)gm_nbt_blob_find_numeric_list(
                spawn_data, "Pos", position, 3,
                &position_count, &position_type);
        (void)position_type;
        double sx = position_count >= 1 ? position[0]
            : x + (jrand_double(&random) - jrand_double(&random))
                * (double)sp->spawn_range + 0.5;
        double sy = position_count >= 2 ? position[1]
            : y + jrand_int_bound(&random, 3) - 1;
        double sz = position_count >= 3 ? position[2]
            : z + (jrand_double(&random) - jrand_double(&random))
                * (double)sp->spawn_range + 0.5;
        *world_random_seed48 = random.seed;

        /* readWorldEntityPos constructs the candidate before the class-AABB
         * cap query. The parked oracle splits constructor RNG/UUID/Math from
         * the client, while assigning its continuation EID only on join. */
        int result = gm_mobs_spawn_spawner_candidate(
            m, w, sp->entity_type, sp->x, sp->y, sp->z,
            sp->spawn_range, sp->max_nearby,
            sx, sy, sz, px, py, pz,
            world_random_seed48, math_random_seed48,
            entity_seed_generator_seed48, server_uuid_random_seed48,
            next_entity_id, spawn_data, sp->default_entity_nbt);
        if (result < 0) {
            spawner_reset_timer(sp, world_random_seed48);
            spawner_client_rotation_tick(sp, 1);
            return spawned;
        }
        spawned += result;
    }
    if (spawned > 0) spawner_reset_timer(sp, world_random_seed48);
    spawner_client_rotation_tick(sp, 1);
    return spawned;
}

static int in_fortress_bricks(GmWorld *w, int x, int y, int z) {
    for (int dx = -8; dx <= 8; ++dx)
        for (int dy = -4; dy <= 4; ++dy)
            for (int dz = -8; dz <= 8; ++dz)
                if (gm_world_block(w, x + dx, y + dy, z + dz) == 112) return 1;
    return 0;
}

static int natural_spawn_one(
        GmMobLive *m, EwStore *s, int type, int size,
        double x, double y, double z, int biome,
        uint64_t *world_random_seed48, uint64_t *math_random_seed48,
        GmNaturalGroupData *group);

static void passive_spawn(GmMobLive *m, GmWorld *w, EwStore *s,
                          double px, double py, double pz,
                          long long world_time,
                          uint64_t *world_random_seed48,
                          uint64_t *math_random_seed48) {
    /* WorldServer passes spawnOnSetTickRate only once per 400 world ticks.
     * It is independent of daylight: the old day-only/200-tick shortcut made
     * peaceful packs appear twice as often and stopped them entirely at night. */
    if (m->tick == 0 || (world_time % 400LL) ||
        passive_count(m,s) > GM_NATURAL_PASSIVE_CAP) return;
    for (int a = 0; a < 8; ++a) {
        u64 h = mc_hash_seed((u64)m->seed, m->tick, a, 0, 0, 0x50415353u);
        int dx = 24 + mc_hash_bound(h, 97);
        int dz = (int)mc_hash_bound(mc_hash64(h), 241) - 120;
        if (h & 1ULL) dx = -dx;
        int x = mc_floor(px) + dx, z = mc_floor(pz) + dz;
        if (gm_world_biome(w, x, z) < 0) continue;
        int y = gm_world_surface_y(w, x, z);
        double vx = x + 0.5 - px, vy = y - py, vz = z + 0.5 - pz;
        if (vx * vx + vy * vy + vz * vz < 24.0 * 24.0 || gm_world_block(w, x, y - 1, z) != 2 ||
            gm_world_block(w, x, y, z) || gm_world_block(w, x, y + 1, z)) continue;
        int biome = gm_world_biome(w, x, z);
        int roll, total = 0, count = 0;
        int types[12], weights[12];
#define PASSIVE_ADD(t, weight) do { \
    types[count] = (t); weights[count] = (weight); \
    total += (weight); ++count; \
} while (0)
        int type = EW_TYPE_NONE;
        /* This is the complete vanilla Biome CREATURE roster. Pack traversal
         * is still approximate below, but biome identity and weights must not
         * invent land animals in oceans or omit route-visible species. */
        if (biome == 2 || biome == 17 || biome == 130) {
            PASSIVE_ADD(EW_TYPE_RABBIT, 4);
        } else if (biome == 12 || biome == 13 || biome == 140) {
            PASSIVE_ADD(EW_TYPE_RABBIT, 10);
            PASSIVE_ADD(EW_TYPE_POLAR_BEAR, 1);
        } else if (biome == 14 || biome == 15) {
            PASSIVE_ADD(EW_TYPE_MOOSHROOM, 8);
        } else if (!(biome == 0 || biome == 7 || biome == 8 || biome == 9
                || biome == 10 || biome == 11 || biome == 16 || biome == 24
                || biome == 25 || biome == 26 || biome == 37 || biome == 38
                || biome == 39 || biome == 127 || biome == 165
                || biome == 166 || biome == 167)) {
            PASSIVE_ADD(EW_TYPE_SHEEP, 12);
            PASSIVE_ADD(EW_TYPE_PIG, 10);
            PASSIVE_ADD(EW_TYPE_CHICKEN, 10);
            PASSIVE_ADD(EW_TYPE_COW, 8);
            if (biome == 3 || biome == 20 || biome == 34
                    || biome == 131 || biome == 162)
                PASSIVE_ADD(EW_TYPE_LLAMA, 5);
            if (biome == 1 || biome == 129) {
                PASSIVE_ADD(EW_TYPE_HORSE, 5);
                PASSIVE_ADD(EW_TYPE_DONKEY, 1);
            }
            if (biome == 4 || biome == 18)
                PASSIVE_ADD(EW_TYPE_WOLF, 5);
            if (biome == 5 || biome == 19 || biome == 30 || biome == 31
                    || biome == 32 || biome == 33 || biome == 133
                    || biome == 158 || biome == 160 || biome == 161) {
                PASSIVE_ADD(EW_TYPE_WOLF, 8);
                PASSIVE_ADD(EW_TYPE_RABBIT, 4);
            }
            if (biome == 132) PASSIVE_ADD(EW_TYPE_RABBIT, 4);
            if (biome == 21 || biome == 22 || biome == 23
                    || biome == 149 || biome == 151)
                PASSIVE_ADD(EW_TYPE_CHICKEN, 10);
            if (biome == 35 || biome == 36 || biome == 163 || biome == 164) {
                PASSIVE_ADD(EW_TYPE_HORSE, 1);
                PASSIVE_ADD(EW_TYPE_DONKEY, 1);
                if (biome == 36) PASSIVE_ADD(EW_TYPE_LLAMA, 8);
            }
        }
        if (total <= 0) continue;
        roll = (int)mc_hash_bound(mc_hash64(h + 1), (unsigned)total);
        for (int entry = 0; entry < count; ++entry) {
            roll -= weights[entry];
            if (roll < 0) { type = types[entry]; break; }
        }
#undef PASSIVE_ADD
        if (type == EW_TYPE_NONE) continue;
        /* WorldEntitySpawner shares IEntityLivingData across one inner pack.
         * Its member count comes from the isolated server Math.random stream,
         * while every candidate walk (including the two nextInt(1) calls)
         * consumes World.rand. The outer eligible-chunk/shuffle traversal is
         * still approximate, but births within the selected pack now preserve
         * Java's causal global/private RNG and group-state boundary. */
        GmNaturalGroupData group = {0};
        int members = (int)ceil(
            mob_math_random_next_double(math_random_seed48) * 4.0D);
        int sx = x, sy = y, sz = z;
        for (int member = 0; member < members; ++member) {
            JavaRandom world_random = {*world_random_seed48};
            sx += jrand_int_bound(&world_random, 6)
                - jrand_int_bound(&world_random, 6);
            sy += jrand_int_bound(&world_random, 1)
                - jrand_int_bound(&world_random, 1);
            sz += jrand_int_bound(&world_random, 6)
                - jrand_int_bound(&world_random, 6);
            *world_random_seed48 = world_random.seed;
            double ddx = sx + 0.5 - px, ddy = sy - py, ddz = sz + 0.5 - pz;
            if (ddx * ddx + ddy * ddy + ddz * ddz < 24.0 * 24.0
                    || gm_world_block(w, sx, sy - 1, sz) != 2
                    || gm_world_block(w, sx, sy, sz) != 0
                    || gm_world_block(w, sx, sy + 1, sz) != 0)
                continue;
            int member_biome = gm_world_biome(w, sx, sz);
            if (member_biome < 0) continue;
            (void)natural_spawn_one(
                m, s, type, 1, sx + 0.5, sy, sz + 0.5, member_biome,
                world_random_seed48, math_random_seed48, &group);
        }
        return;
    }
}

static void nether_natural_spawn(GmMobLive *m, GmWorld *w, EwStore *s,
                                 double px, double py, double pz,
                                 uint64_t *world_random_seed48,
                                 uint64_t *math_random_seed48) {
    /* WorldEntitySpawner runs MONSTER every server tick. The former 40-tick
     * throttle made fortress/blaze availability qualitatively unlike Java. */
    if (alive_count(m,s) > GM_NATURAL_HOSTILE_CAP) return;
    for (int a = 0; a < 6; ++a) {
        u64 h = mc_hash_seed((u64)m->seed, m->tick, a, 0, 0, 0x4E455448u);
        int dx = 24 + mc_hash_bound(h, 97);
        int dz = (int)mc_hash_bound(mc_hash64(h), 241) - 120;
        if (h & 1ULL) dx = -dx;
        int x = mc_floor(px) + dx, z = mc_floor(pz) + dz;
        if (gm_world_biome(w, x, z) < 0) continue;
        int y = mc_floor(py) + (int)mc_hash_bound(mc_hash64(h + 2), 9) - 4;
        if (y < 5) y = 5;
        if (y > 120) y = 120;
        if (solid_id(gm_world_block(w, x, y, z)) || solid_id(gm_world_block(w, x, y + 1, z)))
            continue;
        if (!solid_id(gm_world_block(w, x, y - 1, z))) continue;
        double ddx = x + 0.5 - px, ddy = y - py, ddz = z + 0.5 - pz;
        double ds = ddx * ddx + ddy * ddy + ddz * ddz;
        if (ds < 24.0 * 24.0) continue;

        int type;
        int fortress = in_fortress_bricks(w, x, y, z);
        if (fortress) {
            /* MapGenNetherBridge spawn list weights: blaze 10, pigman 5,
             * wither skeleton 8, skeleton 2, magma 3. Total 28. */
            int roll = (int)mc_hash_bound(mc_hash64(h + 3), 28);
            if (roll < 10) type = EW_TYPE_BLAZE;
            else if (roll < 15) type = EW_TYPE_PIGMAN;
            else if (roll < 23) type = EW_TYPE_WITHER_SKELETON;
            else if (roll < 25) type = EW_TYPE_SKELETON;
            else type = EW_TYPE_MAGMA;
        } else {
            /* BiomeHell: ghast 50, pigman 100, magma 2, enderman 1. Total 153. */
            int roll = (int)mc_hash_bound(mc_hash64(h + 3), 153);
            if (roll < 50) type = EW_TYPE_GHAST;
            else if (roll < 150) type = EW_TYPE_PIGMAN;
            else if (roll < 152) type = EW_TYPE_MAGMA;
            else type = EW_TYPE_ENDERMAN;
        }
        /* One selected SpawnListEntry is retained for the whole inner pack.
         * Like the Overworld path, Math.random owns the 1..4 attempt count,
         * World.rand owns every candidate walk, and IEntityLivingData is
         * shared only across successful births in this pack. This matters in
         * fortresses: one selected blaze entry can produce multiple blazes,
         * instead of the former hard maximum of one per server tick. */
        GmNaturalGroupData group = {0};
        int members = (int)ceil(
            mob_math_random_next_double(math_random_seed48) * 4.0D);
        int sx = x, sy = y, sz = z;
        for (int member = 0; member < members; ++member) {
            JavaRandom world_random = {*world_random_seed48};
            sx += jrand_int_bound(&world_random, 6)
                - jrand_int_bound(&world_random, 6);
            sy += jrand_int_bound(&world_random, 1)
                - jrand_int_bound(&world_random, 1);
            sz += jrand_int_bound(&world_random, 6)
                - jrand_int_bound(&world_random, 6);
            *world_random_seed48 = world_random.seed;
            double member_dx = sx + 0.5 - px;
            double member_dy = sy - py;
            double member_dz = sz + 0.5 - pz;
            if (member_dx * member_dx + member_dy * member_dy
                        + member_dz * member_dz < 24.0 * 24.0
                    || !solid_id(gm_world_block(w, sx, sy - 1, sz))
                    || solid_id(gm_world_block(w, sx, sy, sz))
                    || solid_id(gm_world_block(w, sx, sy + 1, sz)))
                continue;
            int member_biome = gm_world_biome(w, sx, sz);
            if (member_biome < 0) continue;
            /* Ghast.getCanSpawnHere consumes one private nextInt(20), but
             * exact large-AABB admission is still tracked separately. Keep
             * the established vertical clearance approximation for now. */
            int spawn_y = sy + (type == EW_TYPE_GHAST ? 4 : 0);
            int slot = natural_spawn_one(
                m, s, type, 1, sx + 0.5, spawn_y, sz + 0.5,
                member_biome, world_random_seed48, math_random_seed48,
                &group);
            if (slot >= 0) {
                s->cx[slot] = sx >> 4;
                s->cz[slot] = sz >> 4;
                /* EntityGhast.getMaxSpawnedInChunk is one. */
                if (type == EW_TYPE_GHAST) break;
            }
        }
        return;
    }
}

static void slime_spawn(GmMobLive *m, GmWorld *w, EwStore *s,
                        double px, double py, double pz,
                        uint64_t *world_random_seed48,
                        uint64_t *math_random_seed48) {
    if ((m->tick % 80) || alive_count(m,s) > GM_NATURAL_HOSTILE_CAP) return;
    for (int a = 0; a < 4; ++a) {
        u64 h = mc_hash_seed((u64)m->seed, m->tick, a, 0, 0, 0x534C494Du);
        int dx = 24 + mc_hash_bound(h, 97);
        int dz = (int)mc_hash_bound(mc_hash64(h), 241) - 120;
        if (h & 1ULL) dx = -dx;
        int x = mc_floor(px) + dx, z = mc_floor(pz) + dz;
        double player_dx = x + 0.5 - px;
        double player_dz = z + 0.5 - pz;
        if (player_dx * player_dx + player_dz * player_dz
                < 24.0 * 24.0) continue;
        int cx = x >> 4, cz = z >> 4;
        int biome = gm_world_biome(w, x, z);
        if (biome < 0) continue;
        int y;
        int ok = 0;
        if (biome == B_SWAMP) {
            /* Swamp slime: y 50..70, light-gated. */
            y = 50 + (int)mc_hash_bound(mc_hash64(h + 1), 21);
            if (y < 50 || y > 70) continue;
            if (gm_world_block_light(w, x, y, z) > 7) continue;
            if (!solid_id(gm_world_block(w, x, y - 1, z))) continue;
            if (solid_id(gm_world_block(w, x, y, z))) continue;
            ok = 1;
        } else if (is_slime_chunk(m->seed, cx, cz)) {
            /* Slime chunk: y < 40, 1/10 of spawn attempts already in vanilla
             * via chunk RNG; we already gated by is_slime_chunk. */
            y = 5 + (int)mc_hash_bound(mc_hash64(h + 1), 35);
            if (y >= 40) continue;
            if (!solid_id(gm_world_block(w, x, y - 1, z))) continue;
            if (solid_id(gm_world_block(w, x, y, z)) || solid_id(gm_world_block(w, x, y + 1, z)))
                continue;
            ok = 1;
        }
        if (!ok) continue;
        int sz = (int[]){1, 2, 4}[mc_hash_bound(mc_hash64(h + 2), 3)];
        (void)natural_spawn_one(
            m, s, EW_TYPE_SLIME, sz, x + 0.5, y, z + 0.5, biome,
            world_random_seed48, math_random_seed48, NULL);
        return;
    }
}

/* Route-roster weighted pick — NOT Java-exact WorldEntitySpawner pack loop.
 * Approximate biome monster weights for supported types only (zombie 95,
 * skeleton/creeper/spider 100, enderman 10). Full pack enumeration, chunk
 * RNG order, and type-specific EntityAITasks remain open (OPEN_DIVERGENCES). */
static int overworld_hostile_weighted(JavaRandom *r, int biome) {
    /* Biome's exact inherited MONSTER weights total 515. Desert substitutes
     * husks for 80/100 of the zombie family; snowy biomes substitute strays
     * for 80/100 of skeletons. Swamp appends one extra slime weight. */
    int jungle_ocelot = biome == 21 || biome == 22 || biome == 149;
    int total = 515 + (biome == B_SWAMP) + 2 * jungle_ocelot;
    int roll = jrand_int_bound(r, total);
    if (roll < 100) return EW_TYPE_SPIDER;
    roll -= 100;
    if (biome == 2 || biome == 17 || biome == 130) {
        if (roll < 19) return EW_TYPE_ZOMBIE;
        if (roll < 20) return EW_TYPE_ZOMBIE_VILLAGER;
        if (roll < 100) return EW_TYPE_HUSK;
    } else {
        if (roll < 95) return EW_TYPE_ZOMBIE;
        if (roll < 100) return EW_TYPE_ZOMBIE_VILLAGER;
    }
    roll -= 100;
    if (biome == 12 || biome == 13 || biome == 140) {
        if (roll < 20) return EW_TYPE_SKELETON;
        if (roll < 100) return EW_TYPE_STRAY;
    } else if (roll < 100) return EW_TYPE_SKELETON;
    roll -= 100;
    if (roll < 100) return EW_TYPE_CREEPER;
    roll -= 100;
    if (roll < 100) return EW_TYPE_SLIME;
    roll -= 100;
    if (roll < 10) return EW_TYPE_ENDERMAN;
    roll -= 10;
    if (roll < 5) return EW_TYPE_WITCH;
    roll -= 5;
    if (biome == B_SWAMP && roll-- == 0) return EW_TYPE_SLIME;
    if (jungle_ocelot && roll < 2) return EW_TYPE_OCELOT;
    return EW_TYPE_WITCH;
}

static int passive_weighted(JavaRandom *r, int biome) {
    int types[12], weights[12], count = 0, total = 0;
#define ADD_PASSIVE(t, weight) do { \
    types[count] = (t); weights[count] = (weight); \
    total += (weight); ++count; \
} while (0)
    if (biome == 2 || biome == 17 || biome == 130) {
        ADD_PASSIVE(EW_TYPE_RABBIT, 4);
    } else if (biome == 12 || biome == 13 || biome == 140) {
        ADD_PASSIVE(EW_TYPE_RABBIT, 10);
        ADD_PASSIVE(EW_TYPE_POLAR_BEAR, 1);
    } else if (biome == 14 || biome == 15) {
        ADD_PASSIVE(EW_TYPE_MOOSHROOM, 8);
    } else if (!(biome == 0 || biome == 7 || biome == 8 || biome == 9
            || biome == 10 || biome == 11 || biome == 16 || biome == 24
            || biome == 25 || biome == 26 || biome == 37 || biome == 38
            || biome == 39 || biome == 127 || biome == 165
            || biome == 166 || biome == 167)) {
        ADD_PASSIVE(EW_TYPE_SHEEP, 12);
        ADD_PASSIVE(EW_TYPE_PIG, 10);
        ADD_PASSIVE(EW_TYPE_CHICKEN, 10);
        ADD_PASSIVE(EW_TYPE_COW, 8);
        if (biome == 3 || biome == 20 || biome == 34
                || biome == 131 || biome == 162)
            ADD_PASSIVE(EW_TYPE_LLAMA, 5);
        if (biome == 1 || biome == 129) {
            ADD_PASSIVE(EW_TYPE_HORSE, 5);
            ADD_PASSIVE(EW_TYPE_DONKEY, 1);
        }
        if (biome == 4 || biome == 18)
            ADD_PASSIVE(EW_TYPE_WOLF, 5);
        if (biome == 5 || biome == 19 || biome == 30 || biome == 31
                || biome == 32 || biome == 33 || biome == 133
                || biome == 158 || biome == 160 || biome == 161) {
            ADD_PASSIVE(EW_TYPE_WOLF, 8);
            ADD_PASSIVE(EW_TYPE_RABBIT, 4);
        }
        if (biome == 132) ADD_PASSIVE(EW_TYPE_RABBIT, 4);
        if (biome == 21 || biome == 22 || biome == 23
                || biome == 149 || biome == 151)
            ADD_PASSIVE(EW_TYPE_CHICKEN, 10);
        if (biome == 35 || biome == 36 || biome == 163 || biome == 164) {
            ADD_PASSIVE(EW_TYPE_HORSE, 1);
            ADD_PASSIVE(EW_TYPE_DONKEY, 1);
            if (biome == 36) ADD_PASSIVE(EW_TYPE_LLAMA, 8);
        }
    }
    if (!total) return EW_TYPE_NONE;
    int roll = jrand_int_bound(r, total);
    for (int index = 0; index < count; ++index) {
        roll -= weights[index];
        if (roll < 0) return types[index];
    }
#undef ADD_PASSIVE
    return EW_TYPE_NONE;
}

enum {
    NATURAL_MONSTER = 0,
    NATURAL_CREATURE = 1,
    NATURAL_AMBIENT = 2,
    NATURAL_WATER = 3
};

static int natural_category_count(
        const GmMobLive *m, const EwStore *s, int category) {
    if (category == NATURAL_MONSTER) return alive_count(m, s);
    if (category == NATURAL_CREATURE) return passive_count(m, s);
    if (category == NATURAL_AMBIENT) return type_count(m, s, EW_TYPE_BAT);
    return type_count(m, s, EW_TYPE_SQUID);
}

static int natural_chunk_loaded(
        const GmNaturalSpawnContext *context, int chunk_x, int chunk_z) {
    for (int index = 0; index < context->loaded_chunk_count; ++index)
        if (context->loaded_chunks[index].chunk_x == chunk_x
                && context->loaded_chunks[index].chunk_z == chunk_z)
            return 1;
    return 0;
}

static uint32_t natural_chunk_hash(int chunk_x, int chunk_z) {
    uint32_t x = UINT32_C(1664525) * (uint32_t)chunk_x
        + UINT32_C(1013904223);
    uint32_t z = UINT32_C(1664525)
        * ((uint32_t)chunk_z ^ UINT32_C(0xdeadbeef))
        + UINT32_C(1013904223);
    uint32_t hash = x ^ z;
    return hash ^ (hash >> 16);
}

static int natural_eligible_chunks(
        int player_cx, int player_cz,
        const GmNaturalSpawnContext *context,
        GmNaturalSpawnChunk out[225]) {
    GmNaturalSpawnChunk insertion[225];
    uint32_t hashes[225];
    int count = 0;
    for (int dx = -8; dx <= 8; ++dx)
        for (int dz = -8; dz <= 8; ++dz) {
            if (dx == -8 || dx == 8 || dz == -8 || dz == 8)
                continue;
            int chunk_x = player_cx + dx;
            int chunk_z = player_cz + dz;
            if (!natural_chunk_loaded(context, chunk_x, chunk_z)) continue;
            insertion[count] = (GmNaturalSpawnChunk){chunk_x, chunk_z};
            hashes[count] = natural_chunk_hash(chunk_x, chunk_z);
            ++count;
        }
    /* HashSet is backed by Java 8 HashMap. Resizes preserve relative order
     * within each final bucket, so bucket-major/insertion-minor is exactly
     * the ArrayList order seen by Collections.shuffle. */
    int capacity = 16;
    while (count > capacity * 3 / 4) capacity <<= 1;
    int output = 0;
    for (int bucket = 0; bucket < capacity; ++bucket)
        for (int index = 0; index < count; ++index)
            if ((int)(hashes[index] & (uint32_t)(capacity - 1)) == bucket)
                out[output++] = insertion[index];
    return output;
}

static void natural_shuffle_chunks(
        GmNaturalSpawnChunk *chunks, int count, uint64_t *seed48) {
    JavaRandom random = {*seed48};
    for (int index = count; index > 1; --index) {
        int other = jrand_int_bound(&random, index);
        GmNaturalSpawnChunk temporary = chunks[index - 1];
        chunks[index - 1] = chunks[other];
        chunks[other] = temporary;
    }
    *seed48 = random.seed;
}

int gm_mobs_natural_chunk_order(
        int player_chunk_x, int player_chunk_z,
        const GmNaturalSpawnContext *context, uint64_t *collections_seed48,
        GmNaturalSpawnChunk *out, int capacity) {
    GmNaturalSpawnChunk values[225];
    if (!context || !collections_seed48 || !out || capacity < 0
            || context->loaded_chunk_count < 0
            || context->loaded_chunk_count > 225)
        return -1;
    int count = natural_eligible_chunks(
        player_chunk_x, player_chunk_z, context, values);
    natural_shuffle_chunks(values, count, collections_seed48);
    int written = count < capacity ? count : capacity;
    if (written > 0)
        memcpy(out, values, (size_t)written * sizeof out[0]);
    return count;
}

static int natural_type_for(
        GmMobLive *m, GmWorld *w, JavaRandom *world_random,
        int dimension, int category, int x, int y, int z) {
    int biome = gm_world_biome(w, x, z);
    if (biome < 0) return EW_TYPE_NONE;
    if (category == NATURAL_AMBIENT)
        return dimension == 0 ? EW_TYPE_BAT : EW_TYPE_NONE;
    if (category == NATURAL_WATER)
        return dimension == 0 ? EW_TYPE_SQUID : EW_TYPE_NONE;
    if (category == NATURAL_CREATURE)
        return dimension == 0 ? passive_weighted(world_random, biome)
                              : EW_TYPE_NONE;
    if (dimension == 1) return EW_TYPE_ENDERMAN;
    if (dimension == -1) {
        if (in_fortress_bricks(w, x, y, z)) {
            int roll = jrand_int_bound(world_random, 28);
            if (roll < 10) return EW_TYPE_BLAZE;
            if (roll < 15) return EW_TYPE_PIGMAN;
            if (roll < 23) return EW_TYPE_WITHER_SKELETON;
            if (roll < 25) return EW_TYPE_SKELETON;
            return EW_TYPE_MAGMA;
        }
        int roll = jrand_int_bound(world_random, 153);
        if (roll < 50) return EW_TYPE_GHAST;
        if (roll < 150) return EW_TYPE_PIGMAN;
        if (roll < 152) return EW_TYPE_MAGMA;
        return EW_TYPE_ENDERMAN;
    }
    (void)m;
    return overworld_hostile_weighted(world_random, biome);
}

static int natural_type_available(
        GmMobLive *m, GmWorld *w, int dimension, int category,
        int type, int selected_biome, int selected_fortress,
        int x, int y, int z) {
    int biome = gm_world_biome(w, x, z);
    /* SpawnListEntry does not override equals: List.contains compares the
     * exact entry object selected at the first candidate.  Every Biome
     * singleton owns distinct entry objects, so a walked pack crossing even
     * two biomes with the same entity class must be rejected. */
    if (dimension != -1)
        return biome >= 0 && biome == selected_biome;
    if (dimension == -1) {
        int fortress = in_fortress_bricks(w, x, y, z);
        if (fortress != selected_fortress) return 0;
        if (fortress)
            return type == EW_TYPE_BLAZE || type == EW_TYPE_PIGMAN
                || type == EW_TYPE_WITHER_SKELETON
                || type == EW_TYPE_SKELETON || type == EW_TYPE_MAGMA;
        return type == EW_TYPE_GHAST || type == EW_TYPE_PIGMAN
            || type == EW_TYPE_MAGMA || type == EW_TYPE_ENDERMAN;
    }
    (void)m;
    (void)category;
    return 0;
}

static int natural_placement_valid(
        GmWorld *w, int category, int x, int y, int z) {
    int here = gm_world_block(w, x, y, z);
    int below = gm_world_block(w, x, y - 1, z);
    int above = gm_world_block(w, x, y + 1, z);
    if (category == NATURAL_WATER)
        return (here == 8 || here == 9)
            && (below == 8 || below == 9) && !solid_id(above);
    if (!solid_id(below) || below == 7 || below == 166) return 0;
    return here == 0 && above == 0;
}

static int natural_simple_can_spawn(
        GmMobLive *m, GmWorld *w, int category, int type,
        int x, int y, int z, double px, double py, double pz) {
    (void)m;
    double dx = x + 0.5 - px, dy = y - py, dz = z + 0.5 - pz;
    if (dx * dx + dy * dy + dz * dz < 24.0 * 24.0) return 0;
    if (!natural_placement_valid(w, category, x, y, z)) return 0;
    if (type == EW_TYPE_SQUID) return y > 45 && y < 63;
    if (type == EW_TYPE_BAT)
        return y < 63 && gm_world_block_light(w, x, y, z) <= 4;
    if (category == NATURAL_CREATURE)
        return gm_world_block(w, x, y - 1, z) == 2
            && gm_world_sky_light(w, x, y, z) > 8;
    if (type == EW_TYPE_OCELOT) {
        int below = gm_world_block(w, x, y - 1, z);
        return y >= 63 && (below == 2 || below == 18 || below == 161);
    }
    if (type == EW_TYPE_SLIME || type == EW_TYPE_MAGMA) {
        int biome = gm_world_biome(w, x, z);
        if (type == EW_TYPE_MAGMA) return 1;
        return (biome == B_SWAMP && y > 50 && y < 70)
            || (y < 40 && is_slime_chunk(m->seed, x >> 4, z >> 4));
    }
    return gm_world_block_light(w, x, y, z) <= 7;
}

static int natural_max_pack(int type) {
    if (type == EW_TYPE_GHAST) return 1;
    if (gm_mobs_horse_type(type)) return 6;
    if (type == EW_TYPE_WOLF) return 8;
    return 4;
}

static void exact_natural_spawn(
        GmMobLive *m, GmWorld *w, EwStore *s,
        double px, double py, double pz, int dimension,
        long long world_time, uint64_t *world_random_seed48,
        uint64_t *math_random_seed48,
        const GmNaturalSpawnContext *context) {
    GmNaturalSpawnChunk base[225], shuffled[225];
    int player_cx = mc_floor(px) >> 4;
    int player_cz = mc_floor(pz) >> 4;
    int count = natural_eligible_chunks(player_cx, player_cz, context, base);
    static const int caps[4] = {70, 10, 15, 5};
    for (int category = NATURAL_MONSTER;
            category <= NATURAL_WATER; ++category) {
        if (category == NATURAL_CREATURE && world_time % 400LL != 0)
            continue;
        if (natural_category_count(m, s, category) > caps[category])
            continue;
        memcpy(shuffled, base, (size_t)count * sizeof shuffled[0]);
        natural_shuffle_chunks(
            shuffled, count, context->collections_random_seed48);
        int stop_category = 0;
        for (int chunk_index = 0;
                chunk_index < count && !stop_category; ++chunk_index) {
            JavaRandom world_random = {*world_random_seed48};
            int x = shuffled[chunk_index].chunk_x * 16
                + jrand_int_bound(&world_random, 16);
            int z = shuffled[chunk_index].chunk_z * 16
                + jrand_int_bound(&world_random, 16);
            int height = gm_world_height(w, x, z) + 1;
            int bound = ((height + 15) / 16) * 16;
            if (bound <= 0) bound = 1;
            if (bound > 256) bound = 256;
            int y = jrand_int_bound(&world_random, bound);
            *world_random_seed48 = world_random.seed;
            if (solid_id(gm_world_block(w, x, y, z))) continue;
            int spawned_in_chunk = 0;
            for (int outer = 0; outer < 3 && !stop_category; ++outer) {
                int sx = x, sy = y, sz = z;
                int selected_type = EW_TYPE_NONE;
                int selected_biome = -1;
                int selected_fortress = 0;
                GmNaturalGroupData group = {0};
                int members = (int)ceil(
                    mob_math_random_next_double(math_random_seed48) * 4.0D);
                for (int member = 0; member < members; ++member) {
                    world_random.seed = *world_random_seed48;
                    sx += jrand_int_bound(&world_random, 6)
                        - jrand_int_bound(&world_random, 6);
                    sy += jrand_int_bound(&world_random, 1)
                        - jrand_int_bound(&world_random, 1);
                    sz += jrand_int_bound(&world_random, 6)
                        - jrand_int_bound(&world_random, 6);
                    *world_random_seed48 = world_random.seed;
                    double fx = sx + 0.5, fz = sz + 0.5;
                    double player_dx = fx - px, player_dy = sy - py;
                    double player_dz = fz - pz;
                    double spawn_dx = fx - context->world_spawn_x;
                    double spawn_dy = sy - context->world_spawn_y;
                    double spawn_dz = fz - context->world_spawn_z;
                    if (player_dx * player_dx + player_dy * player_dy
                                + player_dz * player_dz < 576.0
                            || spawn_dx * spawn_dx + spawn_dy * spawn_dy
                                + spawn_dz * spawn_dz < 576.0)
                        continue;
                    if (selected_type == EW_TYPE_NONE) {
                        world_random.seed = *world_random_seed48;
                        selected_type = natural_type_for(
                            m, w, &world_random, dimension, category,
                            sx, sy, sz);
                        *world_random_seed48 = world_random.seed;
                        if (selected_type == EW_TYPE_NONE) break;
                        selected_biome = gm_world_biome(w, sx, sz);
                        selected_fortress = dimension == -1
                            && in_fortress_bricks(w, sx, sy, sz);
                    }
                    if (!natural_type_available(
                            m, w, dimension, category, selected_type,
                            selected_biome, selected_fortress, sx, sy, sz)
                            || !natural_simple_can_spawn(
                                m, w, category, selected_type,
                                sx, sy, sz, px, py, pz))
                        continue;
                    if (selected_type == EW_TYPE_OCELOT) {
                        world_random.seed = *world_random_seed48;
                        int accepted = jrand_int_bound(&world_random, 3) != 0;
                        *world_random_seed48 = world_random.seed;
                        if (!accepted) continue;
                    }
                    int spawn_y = sy
                        + (selected_type == EW_TYPE_GHAST ? 4 : 0);
                    int slot = natural_spawn_one(
                        m, s, selected_type, 1, fx, spawn_y, fz,
                        gm_world_biome(w, sx, sz), world_random_seed48,
                        math_random_seed48, &group);
                    if (slot < 0) continue;
                    s->cx[slot] = sx >> 4;
                    s->cz[slot] = sz >> 4;
                    if (++spawned_in_chunk >= natural_max_pack(selected_type))
                        stop_category = 1;
                }
            }
        }
    }
}

static int natural_spawn_one(
        GmMobLive *m, EwStore *s, int type, int size,
        double x, double y, double z, int biome,
        uint64_t *world_random_seed48, uint64_t *math_random_seed48,
        GmNaturalGroupData *group) {
    JavaGaussianRandom candidate_random;
    int64_t uuid_most = 0, uuid_least = 0;
    int is_cold = 0;
    int eid = m->next_id++;
    int initialized = world_random_seed48 && math_random_seed48
        && m->active_entity_seed_generator_seed48
        && m->active_server_uuid_random_seed48;
    if (initialized)
        spawner_construct_living_candidate(
            &candidate_random,
            m->active_entity_seed_generator_seed48,
            m->active_server_uuid_random_seed48,
            math_random_seed48, &uuid_most, &uuid_least);
    /* EntityZombie.applyEntityAttributes runs during construction, before
     * setLocationAndAngles/onInitialSpawn. PigZombie, Husk, and
     * ZombieVillager all retain this superclass draw. */
    if (initialized && (gm_zombie(type) || type == EW_TYPE_PIGMAN))
        (void)jrand_double(&candidate_random.random);
    int slot = living_spawn_slot(
        m, s, type, eid, x, y, z, max_health(type, size), &is_cold);
    if (slot < 0 || slot >= EW_MAX_ENTITIES) return -1;
    m->entity_dimension[slot] = (signed char)m->active_dimension;
    m->size[slot] = (unsigned char)(size > 0 ? size : 1);
    reset_slot_state_s(m, s, slot);
    if (initialized) {
        JavaRandom world_random = {*world_random_seed48};
        m->entity_uuid_present[slot] = 1;
        m->entity_uuid_most[slot] = uuid_most;
        m->entity_uuid_least[slot] = uuid_least;
        fresh_subclass_constructor_state(
            m, s, slot, type, eid, &candidate_random);
        /* EntitySlime.onInitialSpawn owns size selection and invokes
         * EntityLiving.onInitialSpawn only afterwards. The prior outer hash
         * choice got both size and every later private-RNG draw wrong. At
         * fresh-world clamped difficulty zero, the conditional promotion can
         * never accept but its nextFloat is still evaluated for i < 2. */
        if (type == EW_TYPE_SLIME || type == EW_TYPE_MAGMA) {
            m->size[slot] = (unsigned char)
                fresh_slime_initial_size_zero(&m->entity_random[slot]);
            s->health[slot] = max_health(type, m->size[slot]);
        }
        candidate_random = m->entity_random[slot];
        world_random.seed = *world_random_seed48;
        s->yaw[slot] = jrand_float(&world_random) * 360.0F;
        *world_random_seed48 = world_random.seed;
        if (type != EW_TYPE_POLAR_BEAR)
            spawner_default_living_initial_spawn(
                m, slot, type, &candidate_random,
                world_random_seed48,
                m->active_server_uuid_random_seed48);
        /* Speedrun-time DifficultyInstance has clamped additional difficulty
         * zero (inhabitedTime is zero and total world time is below 72000).
         * Preserve every unconditional class draw and the visible equipment
         * selected by onInitialSpawn at that value. This is the exact branch
         * exercised by a fresh 1.11.2 Easy/Normal random-seed run. */
        fresh_hostile_initial_tail_zero(
            m, slot, type, world_random_seed48, group);
        fresh_passive_initial_tail(m, slot, type, biome, group);
    }
    return living_spawn_finish(m, s, slot, is_cold, 0);
}

static void ambient_and_water_spawn(
        GmMobLive *m, GmWorld *w, EwStore *s,
        double px, double py, double pz,
        uint64_t *world_random_seed48, uint64_t *math_random_seed48) {
    if (type_count(m, s, EW_TYPE_SQUID) <= 5) {
        for (int attempt = 0; attempt < 4; ++attempt) {
            u64 h = mc_hash_seed(
                (u64)m->seed, m->tick, attempt, 0, 0, 0x53515549u);
            int x = mc_floor(px) + (int)mc_hash_bound(h, 241) - 120;
            int z = mc_floor(pz)
                + (int)mc_hash_bound(mc_hash64(h), 241) - 120;
            if (gm_world_biome(w, x, z) < 0) continue;
            int y = 45 + (int)mc_hash_bound(mc_hash64(h + 1), 19);
            int here = gm_world_block(w, x, y, z);
            int below = gm_world_block(w, x, y - 1, z);
            int above = gm_world_block(w, x, y + 1, z);
            if (!((here == 8 || here == 9)
                    && (below == 8 || below == 9)
                    && !solid_id(above))) continue;
            double dx = x + 0.5 - px, dy = y - py, dz = z + 0.5 - pz;
            if (dx * dx + dy * dy + dz * dz < 24.0 * 24.0) continue;
            if (natural_spawn_one(
                    m, s, EW_TYPE_SQUID, 1, x + 0.5, y, z + 0.5,
                    gm_world_biome(w, x, z), world_random_seed48,
                    math_random_seed48, NULL) >= 0)
                break;
        }
    }
    if (type_count(m, s, EW_TYPE_BAT) <= 15) {
        for (int attempt = 0; attempt < 4; ++attempt) {
            u64 h = mc_hash_seed(
                (u64)m->seed, m->tick, attempt, 0, 0, 0x42415453u);
            int x = mc_floor(px) + (int)mc_hash_bound(h, 241) - 120;
            int z = mc_floor(pz)
                + (int)mc_hash_bound(mc_hash64(h), 241) - 120;
            int loaded_height = gm_world_height(w, x, z);
            if (loaded_height < 0) continue;
            int y = 1 + (int)mc_hash_bound(
                mc_hash64(h + 1), (unsigned)(loaded_height < 63
                    ? loaded_height : 63));
            if (!solid_id(gm_world_block(w, x, y - 1, z))
                    || gm_world_block(w, x, y, z) != 0
                    || gm_world_block(w, x, y + 1, z) != 0
                    || gm_world_block_light(w, x, y, z) > 7) continue;
            double dx = x + 0.5 - px, dy = y - py, dz = z + 0.5 - pz;
            if (dx * dx + dy * dy + dz * dz < 24.0 * 24.0) continue;
            if (natural_spawn_one(
                    m, s, EW_TYPE_BAT, 1, x + 0.5, y, z + 0.5,
                    gm_world_biome(w, x, z), world_random_seed48,
                    math_random_seed48, NULL) >= 0)
                break;
        }
    }
}

static void natural_spawn(GmMobLive *m, GmWorld *w, EwStore *s,
                          double px, double py, double pz, int dimension,
                          long long world_time,
                          uint64_t *world_random_seed48,
                          uint64_t *math_random_seed48,
                          const GmNaturalSpawnContext *spawn_context) {
    discover_spawners(m, w, px, py, pz, dimension);

    if (spawn_context && spawn_context->collections_random_seed48
            && spawn_context->loaded_chunks
            && spawn_context->loaded_chunk_count > 0) {
        exact_natural_spawn(
            m, w, s, px, py, pz, dimension, world_time,
            world_random_seed48, math_random_seed48, spawn_context);
        return;
    }

    if (dimension == -1) {
        nether_natural_spawn(
            m, w, s, px, py, pz,
            world_random_seed48, math_random_seed48);
        return;
    }
    if (dimension != 0) return;

    /* Simplified natural spawn (not Java WorldEntitySpawner call-order parity):
     * slime pocket, then day creature / night monster attempt. */
    slime_spawn(
        m, w, s, px, py, pz,
        world_random_seed48, math_random_seed48);

    passive_spawn(m, w, s, px, py, pz, world_time,
                  world_random_seed48, math_random_seed48);
    ambient_and_water_spawn(
        m, w, s, px, py, pz, world_random_seed48, math_random_seed48);
    if (alive_count(m,s) > GM_NATURAL_HOSTILE_CAP) return;
    int tod = (int)(world_time % 24000LL); if (tod < 0) tod += 24000;
    int daylight = tod < 13000 || tod > 23000;
    JavaRandom rng;
    jrand_set(&rng, (i64)m->seed ^ ((i64)m->tick * 6364136223846793005LL) ^ 0x4d4f4253LL);
    for (int a = 0; a < 8; ++a) {
        /* Eligible chunks span the interior of Java's 17x17 player square.
         * Sampling the former 24..32 block strip omitted nearly all caves. */
        int dx = jrand_int_bound(&rng, 241) - 120;
        int dz = jrand_int_bound(&rng, 241) - 120;
        if (dx * dx + dz * dz < 24 * 24) continue;
        int x = mc_floor(px) + dx, z = mc_floor(pz) + dz;
        int loaded_height = gm_world_height(w, x, z);
        if (loaded_height < 0) continue;
        int height = loaded_height + 1;
        int bound = ((height + 15) / 16) * 16;
        if (bound < 1) bound = 1;
        if (bound > 256) bound = 256;
        int y = jrand_int_bound(&rng, bound);
        int surface = gm_world_surface_y(w, x, z);
        double ddx = (x + 0.5) - px, ddy = y - py, ddz = (z + 0.5) - pz;
        double ds = ddx * ddx + ddy * ddy + ddz * ddz;
        if (ds < 24.0 * 24.0
                || !solid_id(gm_world_block(w, x, y - 1, z))
                || gm_world_block(w, x, y, z) != 0
                || gm_world_block(w, x, y + 1, z) != 0)
            continue;
        int biome = gm_world_biome(w, x, z);
        int type = overworld_hostile_weighted(&rng, biome);
        if (type == EW_TYPE_OCELOT) {
            int below = gm_world_block(w, x, y - 1, z);
            /* EntityOcelot is deliberately registered in the jungle MONSTER
             * list, but its own acceptance is bright surface grass/leaves,
             * sea-level height, and a 2/3 World.rand gate. The gate belongs
             * to each walked pack candidate below. */
            if (y < 63 || (below != 2 && below != 18 && below != 161))
                continue;
        } else if ((daylight && y >= surface)
                || gm_world_block_light(w, x, y, z) > 7) {
            continue;
        }
        if (type == EW_TYPE_SLIME && biome != B_SWAMP
                && !is_slime_chunk(m->seed, x >> 4, z >> 4)) continue;
        GmNaturalGroupData group = {0};
        int members = (int)ceil(
            mob_math_random_next_double(math_random_seed48) * 4.0D);
        int sx = x, sy = y, sz = z;
        for (int member = 0; member < members; ++member) {
            JavaRandom world_random = {*world_random_seed48};
            sx += jrand_int_bound(&world_random, 6)
                - jrand_int_bound(&world_random, 6);
            sy += jrand_int_bound(&world_random, 1)
                - jrand_int_bound(&world_random, 1);
            sz += jrand_int_bound(&world_random, 6)
                - jrand_int_bound(&world_random, 6);
            *world_random_seed48 = world_random.seed;
            double member_dx = sx + 0.5 - px;
            double member_dy = sy - py;
            double member_dz = sz + 0.5 - pz;
            if (member_dx * member_dx + member_dy * member_dy
                        + member_dz * member_dz < 24.0 * 24.0
                    || !solid_id(gm_world_block(w, sx, sy - 1, sz))
                    || gm_world_block(w, sx, sy, sz) != 0
                    || gm_world_block(w, sx, sy + 1, sz) != 0)
                continue;
            int member_biome = gm_world_biome(w, sx, sz);
            if (member_biome < 0) continue;
            if (type == EW_TYPE_OCELOT) {
                int below = gm_world_block(w, sx, sy - 1, sz);
                JavaRandom ocelot_random = {*world_random_seed48};
                int accepted = jrand_int_bound(&ocelot_random, 3) != 0;
                *world_random_seed48 = ocelot_random.seed;
                if (sy < 63 || (below != 2 && below != 18 && below != 161)
                        || !accepted)
                    continue;
            } else {
                int member_surface = gm_world_surface_y(w, sx, sz);
                if ((daylight && sy >= member_surface)
                        || gm_world_block_light(w, sx, sy, sz) > 7)
                    continue;
            }
            if (type == EW_TYPE_SLIME && member_biome != B_SWAMP
                    && !is_slime_chunk(m->seed, sx >> 4, sz >> 4))
                continue;
            int slot = natural_spawn_one(
                m, s, type, 1, sx + 0.5, sy, sz + 0.5, member_biome,
                world_random_seed48, math_random_seed48, &group);
            if (slot >= 0) {
                s->cx[slot] = sx >> 4;
                s->cz[slot] = sz >> 4;
            }
        }
        return;
    }
}

/* Exact EntityBoat.Status ordinal order from Java 1.11.2. */
enum {
    BOAT_IN_WATER = 0,
    BOAT_UNDER_WATER = 1,
    BOAT_UNDER_FLOWING_WATER = 2,
    BOAT_ON_LAND = 3,
    BOAT_IN_AIR = 4
};

static int boat_is_water(int id) { return id == 8 || id == 9; }

static float boat_liquid_height(
        GmWorld *w, int x, int y, int z, int meta) {
    if ((meta & 7) == 0 && boat_is_water(gm_world_block(w, x, y + 1, z)))
        return 1.0F;
    if (meta >= 8) meta = 0;
    return 1.0F - (float)(meta + 1) / 9.0F;
}

static double boat_liquid_height_world(
        GmWorld *w, int x, int y, int z) {
    return (double)((float)y + boat_liquid_height(
        w, x, y, z, gm_world_meta(w, x, y, z)));
}

static int boat_underwater_status(
        GmWorld *w, double x, double y, double z) {
    const double half = (double)1.375F * 0.5;
    const double top = y + (double)0.5625F;
    const double probe_top = top + 0.001D;
    int min_x = mc_floor(x - half), max_x = (int)ceil(x + half);
    int min_y = mc_floor(top), max_y = (int)ceil(probe_top);
    int min_z = mc_floor(z - half), max_z = (int)ceil(z + half);
    int source = 0;
    for (int bx = min_x; bx < max_x; ++bx)
        for (int by = min_y; by < max_y; ++by)
            for (int bz = min_z; bz < max_z; ++bz) {
                if (!boat_is_water(gm_world_block(w, bx, by, bz))
                        || probe_top >= boat_liquid_height_world(
                            w, bx, by, bz))
                    continue;
                if (gm_world_meta(w, bx, by, bz) != 0)
                    return BOAT_UNDER_FLOWING_WATER;
                source = 1;
            }
    return source ? BOAT_UNDER_WATER : -1;
}

static int boat_check_in_water(
        GmWorld *w, double x, double y, double z, double *water_level) {
    const double half = (double)1.375F * 0.5;
    int min_x = mc_floor(x - half), max_x = (int)ceil(x + half);
    int min_y = mc_floor(y), max_y = (int)ceil(y + 0.001D);
    int min_z = mc_floor(z - half), max_z = (int)ceil(z + half);
    int found = 0;
    /* java.lang.Double.MIN_VALUE is the least positive subnormal, unlike
     * C's DBL_MIN (the least positive normal). */
    *water_level = 0x0.0000000000001p-1022;
    for (int bx = min_x; bx < max_x; ++bx)
        for (int by = min_y; by < max_y; ++by)
            for (int bz = min_z; bz < max_z; ++bz) {
                if (!boat_is_water(gm_world_block(w, bx, by, bz)))
                    continue;
                double height = boat_liquid_height_world(w, bx, by, bz);
                if (height > *water_level) *water_level = height;
                found |= y < height;
            }
    return found;
}

static float boat_land_glide(
        GmWorld *w, const struct Chunk *window, int ox, int oz,
        double x, double y, double z) {
    const double half = (double)1.375F * 0.5;
    const double min_y = y - 0.001D;
    int min_x = mc_floor(x - half) - 1;
    int max_x = (int)ceil(x + half) + 1;
    int first_y = mc_floor(min_y) - 1;
    int last_y = (int)ceil(y) + 1;
    int min_z = mc_floor(z - half) - 1;
    int max_z = (int)ceil(z + half) + 1;
    float total = 0.0F;
    int count = 0;
    McAABB collision_boxes[GM_MOB_BLOCKS];
    int collision_count = 0;
    McAABB contact = mc_aabb_make(
        x - half - ox, min_y, z - half - oz,
        x + half - ox, y, z + half - oz);
    if (window)
        collision_count = psv_collect_blocks(
            (const Chunk *)window, &contact,
            collision_boxes, GM_MOB_BLOCKS);
    for (int bx = min_x; bx < max_x; ++bx)
        for (int bz = min_z; bz < max_z; ++bz) {
            int edge = (bx == min_x || bx == max_x - 1)
                + (bz == min_z || bz == max_z - 1);
            if (edge == 2) continue;
            for (int by = first_y; by < last_y; ++by) {
                if (edge > 0 && (by == first_y || by == last_y - 1))
                    continue;
                int id = gm_world_block(w, bx, by, bz);
                int intersects = 0;
                if (window) {
                    int local_x = bx - ox, local_z = bz - oz;
                    for (int box = 0; box < collision_count; ++box) {
                        const McAABB *shape = &collision_boxes[box];
                        if (mc_floor((shape->minX + shape->maxX) * 0.5)
                                    == local_x
                                && mc_floor((shape->minY + shape->maxY) * 0.5)
                                    == by
                                && mc_floor((shape->minZ + shape->maxZ) * 0.5)
                                    == local_z
                                && mc_aabb_intersects(&contact, shape)) {
                            intersects = 1;
                            break;
                        }
                    }
                } else {
                    intersects = solid_id(id)
                        && x + half > bx && x - half < bx + 1.0
                        && y > by && min_y < by + 1.0
                        && z + half > bz && z - half < bz + 1.0;
                }
                if (!intersects) continue;
                total += (id == 79 || id == 174 || id == 212) ? 0.98F
                    : id == 165 ? 0.8F : 0.6F;
                ++count;
            }
        }
    return count ? total / (float)count : 0.0F;
}

static int boat_status(
        GmMobLive *m, GmWorld *w, const struct Chunk *window,
        int ox, int oz, EwStore *s, int slot) {
    int status = boat_underwater_status(
        w, s->x[slot], s->y[slot], s->z[slot]);
    if (status >= 0) {
        m->boat_water_level[slot] = s->y[slot] + (double)0.5625F;
        return status;
    }
    if (boat_check_in_water(
            w, s->x[slot], s->y[slot], s->z[slot],
            &m->boat_water_level[slot]))
        return BOAT_IN_WATER;
    m->boat_glide[slot] = boat_land_glide(
        w, window, ox, oz, s->x[slot], s->y[slot], s->z[slot]);
    return m->boat_glide[slot] > 0.0F ? BOAT_ON_LAND : BOAT_IN_AIR;
}

static float boat_water_level_above(
        GmWorld *w, double x, double y, double z, double last_yd) {
    const double half = (double)1.375F * 0.5;
    double top = y + (double)0.5625F;
    int min_x = mc_floor(x - half), max_x = (int)ceil(x + half);
    int min_y = mc_floor(top), max_y = (int)ceil(top - last_yd);
    int min_z = mc_floor(z - half), max_z = (int)ceil(z + half);
    for (int by = min_y; by < max_y; ++by) {
        float height = 0.0F;
        for (int bx = min_x; bx < max_x; ++bx) {
            for (int bz = min_z; bz < max_z; ++bz) {
                if (!boat_is_water(gm_world_block(w, bx, by, bz)))
                    continue;
                float local = boat_liquid_height(
                    w, bx, by, bz, gm_world_meta(w, bx, by, bz));
                if (local > height) height = local;
            }
            if (height >= 1.0F) break;
        }
        if (height < 1.0F) return (float)by + height;
    }
    return (float)(max_y + 1);
}

static int boat_has_living_passenger(
        const GmMobLive *m, int boat, int living_eid) {
    return m->boat_passenger_eid[boat][0] == living_eid
        || m->boat_passenger_eid[boat][1] == living_eid;
}

/* EntityBoat's post-move expanded-AABB pass. This deliberately scans the
 * live loaded order rather than slot order: World.getEntitiesInAABBexcluding
 * returns the world's loadedEntityList order, and first/second automatic
 * passenger assignment is observable. */
static void boat_collide_and_mount_nearby(
        GmMobLive *m, EwStore *state, int boat, int dimension) {
    const double boat_width = 1.375D;
    const double boat_height = 0.5625D;
    double min_x = state->x[boat] - boat_width * 0.5D
        - 0.20000000298023224D;
    double max_x = state->x[boat] + boat_width * 0.5D
        + 0.20000000298023224D;
    double min_y = state->y[boat];
    double max_y = state->y[boat] + boat_height
        - 0.009999999776482582D;
    double min_z = state->z[boat] - boat_width * 0.5D
        - 0.20000000298023224D;
    double max_z = state->z[boat] + boat_width * 0.5D
        + 0.20000000298023224D;
    int automatic = !m->boat_client_remote[boat]
        && m->boat_player_passenger_index[boat] != 0;

    for (int loaded = 0; loaded < m->loaded_order_count; ++loaded) {
        GmMobLoadedRef ref = *loaded_ref_at(m, loaded);
        int other = living_loaded_ref_stage_secondary(
            m, &ref, state);
        if (other <= 0 || state->id[other] == state->id[boat]
                || m->entity_dimension[other] != dimension
                || m->entity_dead[other]
                || boat_has_living_passenger(m, boat, state->id[other]))
            continue;
        double width, height;
        living_entity_size(m, state, other, &width, &height);
        double half = width * 0.5D;
        if (!(state->x[other] + half > min_x
                && state->x[other] - half < max_x
                && state->y[other] + height > min_y
                && state->y[other] < max_y
                && state->z[other] + half > min_z
                && state->z[other] - half < max_z))
            continue;

        int passengers = (m->boat_player_passenger_index[boat] >= 0)
            + (m->boat_passenger_eid[boat][0] != 0)
            + (m->boat_passenger_eid[boat][1] != 0);
        /* EntityWaterMob is squid in the 1.11.2 registry. Guardians inherit
         * EntityMob and are therefore eligible, despite their aquatic AI. */
        if (automatic && passengers < 2
                && m->entity_vehicle_eid[other] <= 0
                && width < boat_width
                && gm_living(state->type[other])
                && state->type[other] != EW_TYPE_BOAT
                && state->type[other] != EW_TYPE_SQUID) {
            int passenger = m->boat_passenger_eid[boat][0] == 0
                    && m->boat_player_passenger_index[boat] != 0 ? 0
                : m->boat_passenger_eid[boat][1] == 0
                    && m->boat_player_passenger_index[boat] != 1 ? 1 : -1;
            if (passenger >= 0) {
                m->boat_passenger_eid[boat][passenger] = state->id[other];
                m->entity_vehicle_eid[other] = state->id[boat];
                continue;
            }
        }

        double other_min_y = state->y[other];
        if ((state->type[other] == EW_TYPE_BOAT
                    && !(other_min_y < state->y[boat] + boat_height))
                || (state->type[other] != EW_TYPE_BOAT
                    && !(other_min_y <= state->y[boat])))
            continue;
        double dx = state->x[other] - state->x[boat];
        double dz = state->z[other] - state->z[boat];
        double magnitude = fmax(fabs(dx), fabs(dz));
        if (magnitude < 0.009999999776482582D) continue;
        double root = (double)(float)sqrt(magnitude);
        dx /= root;
        dz /= root;
        double scale = 1.0D / root;
        if (scale > 1.0D) scale = 1.0D;
        dx *= scale;
        dz *= scale;
        dx *= 0.05000000074505806D;
        dz *= 0.05000000074505806D;
        if (m->boat_player_passenger_index[boat] < 0
                && m->boat_passenger_eid[boat][0] == 0
                && m->boat_passenger_eid[boat][1] == 0) {
            state->vx[boat] -= dx;
            state->vz[boat] -= dz;
        }
        int other_ridden = state->type[other] == EW_TYPE_BOAT
            ? (m->boat_player_passenger_index[other] >= 0
                || m->boat_passenger_eid[other][0] != 0
                || m->boat_passenger_eid[other][1] != 0)
            : m->entity_rider_eid[other] >= 0
                || ride_is_slot(state, other, m->horse_ride_eid)
                || ride_is_slot(state, other, m->pig_ride_eid);
        if (!other_ridden) {
            state->vx[other] += dx;
            state->vz[other] += dz;
        }
    }
}

static void tick_boat(GmMobLive *m, GmWorld *w, EwStore *nx, int i,
                      const struct Chunk *window,
                      const McSinTable *sin_table,
                      PsvPlayer *p, int ox, int oz, float forward,
                      float strafe, int no_gravity, GmLiveSim *drops) {
    /* Boat half-extents for AABB collision (1.375 wide, 0.5625 tall). */
    const double half_w = 1.375 * 0.5;
    const double height = 0.5625;
    int window_valid = window
        && nx->x[i] - half_w - fabs(nx->vx[i]) - ox >= -16.0
        && nx->x[i] + half_w + fabs(nx->vx[i]) - ox < 32.0
        && nx->z[i] - half_w - fabs(nx->vz[i]) - oz >= -16.0
        && nx->z[i] + half_w + fabs(nx->vz[i]) - oz < 32.0;
    m->boat_previous_status[i] = m->boat_status[i];
    m->boat_status[i] = (signed char)boat_status(
        m, w, window_valid ? window : NULL, ox, oz, nx, i);
    int status = m->boat_status[i];
    if (status == BOAT_UNDER_WATER
            || status == BOAT_UNDER_FLOWING_WATER)
        m->boat_out_of_control[i] += 1.0F;
    else
        m->boat_out_of_control[i] = 0.0F;
    if (m->boat_out_of_control[i] >= 60.0F
            && ride_is_slot(nx, i, m->boat_ride_eid)) {
        boat_remove_all_passengers(m, i);
    } else if (m->boat_out_of_control[i] >= 60.0F
            && (m->boat_passenger_eid[i][0] != 0
                || m->boat_passenger_eid[i][1] != 0)) {
        boat_remove_all_passengers(m, i);
    }
    if (m->boat_client_remote[i]
            && !ride_is_slot(nx, i, m->boat_ride_eid)) {
        int steps = m->boat_lerp_steps[i];
        if (steps > 0) {
            nx->x[i] += (m->boat_lerp_x[i] - nx->x[i]) / (double)steps;
            nx->y[i] += (m->boat_lerp_y[i] - nx->y[i]) / (double)steps;
            nx->z[i] += (m->boat_lerp_z[i] - nx->z[i]) / (double)steps;
            double delta = fmod(
                m->boat_lerp_yaw[i] - (double)nx->yaw[i], 360.0D);
            if (delta >= 180.0D) delta -= 360.0D;
            if (delta < -180.0D) delta += 360.0D;
            nx->yaw[i] = (float)(
                (double)nx->yaw[i] + delta / (double)steps);
            m->entity_pitch[i] = (float)(
                (double)m->entity_pitch[i]
                + (m->boat_lerp_pitch[i] - (double)m->entity_pitch[i])
                    / (double)steps);
            m->boat_lerp_steps[i] = steps - 1;
        }
        nx->vx[i] = nx->vy[i] = nx->vz[i] = 0.0D;
        m->boat_paddle_state[i][0] = 0;
        m->boat_paddle_state[i][1] = 0;
        m->boat_paddle_position[i][0] = 0.0F;
        m->boat_paddle_position[i][1] = 0.0F;
        return;
    }
    float momentum = 0.05f;
    double d1 = no_gravity ? 0.0 : -0.03999999910593033; /* gravity */
    double d2 = 0.0;                  /* buoyancy factor */
    int transitioned_from_air = 0;

    if (m->boat_previous_status[i] == BOAT_IN_AIR
            && status != BOAT_IN_AIR && status != BOAT_ON_LAND) {
        m->boat_water_level[i] = nx->y[i] + height;
        nx->y[i] = (double)(boat_water_level_above(
            w, nx->x[i], nx->y[i], nx->z[i], m->boat_last_yd[i])
            - (float)height) + 0.101D;
        nx->vy[i] = 0.0D;
        m->boat_last_yd[i] = 0.0D;
        m->boat_status[i] = BOAT_IN_WATER;
        status = BOAT_IN_WATER;
        momentum = 0.05F;
        d1 = 0.0D;
        transitioned_from_air = 1;
    } else if (status == BOAT_IN_WATER) {
        momentum = 0.9f;
        d2 = (m->boat_water_level[i] - nx->y[i]) / height;
    } else if (status == BOAT_UNDER_FLOWING_WATER) {
        d1 = -7.0E-4D;
        momentum = 0.9F;
    } else if (status == BOAT_UNDER_WATER) {
        d2 = 0.009999999776482582D;
        momentum = 0.45F;
    } else if (status == BOAT_ON_LAND) {
        momentum = m->boat_glide[i];
        if (ride_is_slot(nx, i, m->boat_ride_eid))
            m->boat_glide[i] /= 2.0F;
    } else {
        momentum = 0.9f;
    }
    m->boat_momentum[i] = momentum;

    /* The air-to-water snap is EntityBoat.updateMotion's first branch and
     * deliberately skips every damping/gravity operation below. */
    if (!transitioned_from_air) {
        nx->vx[i] *= (double)momentum;
        nx->vz[i] *= (double)momentum;
        m->boat_delta_rotation[i] *= momentum;
        nx->vy[i] += d1;
        if (d2 > 0.0) {
            nx->vy[i] += d2 * 0.06153846016296973;
            nx->vy[i] *= 0.75;
        }
    }

    /* controlBoat when ridden: no auto-thrust without forward/back input. */
    if (ride_is_slot(nx, i, m->boat_ride_eid) && p) {
        int left = strafe < -0.01f, right = strafe > 0.01f;
        int fwd = forward > 0.01f, back = forward < -0.01f;
        float f = 0.0f;
        if (left) m->boat_delta_rotation[i] += -1.0f;
        if (right) m->boat_delta_rotation[i] += 1.0f;
        if (left != right && !fwd && !back) f += 0.005f;
        nx->yaw[i] += m->boat_delta_rotation[i];
        if (fwd) f += 0.04f;
        if (back) f -= 0.005f;
        if (f != 0.0F) {
            float radians = nx->yaw[i] * 0.017453292F;
            nx->vx[i] += (double)(mc_sin(sin_table, -radians) * f);
            nx->vz[i] += (double)(mc_cos(sin_table, radians) * f);
        }
        m->boat_paddle_state[i][0] =
            (unsigned char)((right && !left) || fwd);
        m->boat_paddle_state[i][1] =
            (unsigned char)((left && !right) || fwd);
        p->ent.motionX = p->ent.motionY = p->ent.motionZ = 0.0;
        p->ent.onGround = (status == BOAT_ON_LAND);
    } else {
        m->boat_paddle_state[i][0] = 0;
        m->boat_paddle_state[i][1] = 0;
    }

    m->boat_last_yd[i] = nx->vy[i];

    /* Entity.move over the shared exact 1.11.2 block collision shapes. The
     * runtime physics window is local to ox/oz, while boat state is world
     * space, so only the AABB/position crosses that integer translation. */
    if (window_valid) {
        McEntity entity;
        McAABB blocks[GM_MOB_BLOCKS];
        memset(&entity, 0, sizeof entity);
        entity.posX = nx->x[i] - ox;
        entity.posY = nx->y[i];
        entity.posZ = nx->z[i] - oz;
        entity.motionX = nx->vx[i];
        entity.motionY = nx->vy[i];
        entity.motionZ = nx->vz[i];
        entity.onGround = nx->on_ground[i] ? 1 : 0;
        double old_y = entity.posY;
        double requested_y = entity.motionY;
        entity.box = mc_aabb_make(
            entity.posX - half_w, entity.posY, entity.posZ - half_w,
            entity.posX + half_w, entity.posY + height,
            entity.posZ + half_w);
        McAABB query = mc_aabb_addcoord(
            &entity.box, entity.motionX, entity.motionY, entity.motionZ);
        int nblocks = psv_collect_blocks(
            (const Chunk *)window, &query, blocks, GM_MOB_BLOCKS);
        mc_entity_move(
            &entity, entity.motionX, entity.motionY, entity.motionZ,
            blocks, nblocks);
        if (requested_y != entity.posY - old_y
                && gm_world_block(
                    w, mc_floor(entity.posX + ox),
                    mc_floor(entity.posY - 0.20000000298023224D),
                    mc_floor(entity.posZ + oz)) == 165)
            entity.motionY = -requested_y * 0.8D;
        nx->x[i] = entity.posX + ox;
        nx->y[i] = entity.posY;
        nx->z[i] = entity.posZ + oz;
        nx->vx[i] = entity.motionX;
        nx->vy[i] = entity.motionY;
        nx->vz[i] = entity.motionZ;
        nx->on_ground[i] = (unsigned char)(entity.onGround ? 1 : 0);
    } else {
        /* Narrow component callers without a runtime window retain the old
         * full-cube fallback. Production always supplies the window. */
        double try_x = nx->x[i] + nx->vx[i];
        double try_z = nx->z[i] + nx->vz[i];
        double try_y = nx->y[i] + nx->vy[i];
        int blocked_xz = 0;
        int mid_y = mc_floor(nx->y[i] + height * 0.5);
        double corners[4][2] = {
            { try_x - half_w, try_z - half_w },
            { try_x + half_w, try_z - half_w },
            { try_x - half_w, try_z + half_w },
            { try_x + half_w, try_z + half_w }
        };
        for (int c = 0; c < 4; ++c) {
            if (solid_id(gm_world_block(w, mc_floor(corners[c][0]), mid_y,
                                        mc_floor(corners[c][1])))) {
                blocked_xz = 1; break;
            }
        }
        if (!blocked_xz) {
            /* Entity.move offsets both AABB faces and then recenters from
             * their average. This is observably one ulp different from a
             * direct position += motion for several negative directions. */
            double min_x = nx->x[i] - half_w + nx->vx[i];
            double max_x = nx->x[i] + half_w + nx->vx[i];
            double min_z = nx->z[i] - half_w + nx->vz[i];
            double max_z = nx->z[i] + half_w + nx->vz[i];
            nx->x[i] = (min_x + max_x) * 0.5D;
            nx->z[i] = (min_z + max_z) * 0.5D;
        } else {
            nx->vx[i] = nx->vz[i] = 0.0;
        }
        {
            int foot = mc_floor(try_y);
            int head = mc_floor(try_y + height);
            int bx = mc_floor(nx->x[i]), bz = mc_floor(nx->z[i]);
            if (!solid_id(gm_world_block(w, bx, foot, bz)) &&
                !solid_id(gm_world_block(w, bx, head, bz))) {
                nx->y[i] = try_y;
                nx->on_ground[i] = 0;
            } else if (nx->vy[i] < 0) {
                nx->vy[i] = 0;
                nx->on_ground[i] = 1;
                nx->y[i] = (double)foot + 1.0;
            } else {
                nx->vy[i] = 0;
            }
        }
    }
    if (nx->on_ground[i] && m->entity_fall_distance[i] > 3.0F
            && status == BOAT_ON_LAND) {
        if (m->do_entity_drops && drops) {
            for (int drop = 0; drop < 3; ++drop)
                gm_live_spawn_item(
                    drops, nx->x[i], nx->y[i], nx->z[i],
                    5, 1, m->boat_variant[i], 10);
            for (int drop = 0; drop < 2; ++drop)
                gm_live_spawn_item(
                    drops, nx->x[i], nx->y[i], nx->z[i],
                    280, 1, 0, 10);
        }
        m->entity_fall_distance[i] = 0.0F;
        boat_remove_all_passengers(m, i);
        loaded_invalidate_living(m, i);
        nx->alive[i] = 0;
        nx->type[i] = EW_TYPE_NONE;
        return;
    }
    if (nx->on_ground[i]) {
        m->entity_fall_distance[i] = 0.0F;
    } else if (nx->vy[i] < 0.0D
            && !boat_is_water(gm_world_block(
                w, mc_floor(nx->x[i]), mc_floor(nx->y[i]) - 1,
                mc_floor(nx->z[i])))) {
        m->entity_fall_distance[i] = (float)(
            (double)m->entity_fall_distance[i] - nx->vy[i]);
    }
    boat_collide_and_mount_nearby(m, nx, i, m->entity_dimension[i]);
    for (int paddle = 0; paddle < 2; ++paddle) {
        if (m->boat_paddle_state[i][paddle])
            m->boat_paddle_position[i][paddle] = (float)(
                (double)m->boat_paddle_position[i][paddle] + 0.01D);
        else
            m->boat_paddle_position[i][paddle] = 0.0F;
    }
    if (ride_is_slot(nx, i, m->boat_ride_eid) && p) {
        int passenger_count = 1
            + (m->boat_passenger_eid[i][0] != 0)
            + (m->boat_passenger_eid[i][1] != 0);
        int passenger = m->boat_player_passenger_index[i];
        float offset = passenger_count > 1
            ? (passenger == 0 ? 0.2F : -0.6F) : 0.0F;
        double offset_x = 0.0D, offset_z = 0.0D;
        if (offset != 0.0F && sin_table) {
            float angle = -nx->yaw[i] * 0.017453292F
                - ((float)MC_PI / 2.0F);
            offset_x = (double)offset
                * (double)mc_cos(sin_table, angle);
            offset_z = -(double)offset
                * (double)mc_sin(sin_table, angle);
        }
        p->ent.posX = nx->x[i] + offset_x - ox;
        p->ent.posY = nx->y[i] - 0.44999998807907104D;
        p->ent.posZ = nx->z[i] + offset_z - oz;
        p->yaw += m->boat_delta_rotation[i];
        float relative = pai_wrap_degrees(p->yaw - nx->yaw[i]);
        float clamped = relative;
        if (clamped > 105.0F) clamped = 105.0F;
        if (clamped < -105.0F) clamped = -105.0F;
        p->yaw += clamped - relative;
    }
    if (sin_table)
        boat_update_living_passengers(m, nx, i, sin_table);
}

static int animal_mate_compatible(
        const GmMobLive *m, const EwStore *s, int first, int second) {
    if (!m || !s || first <= 0 || second <= 0 || first == second
            || first >= EW_MAX_ENTITIES || second >= EW_MAX_ENTITIES
            || !s->alive[first] || !s->alive[second]
            || !gm_passive(s->type[first])
            || m->sheep_in_love[first] <= 0
            || m->sheep_in_love[second] <= 0)
        return 0;
    if (horse_mating_type(s->type[first])
            || horse_mating_type(s->type[second])
            || s->type[first] == EW_TYPE_LLAMA
            || s->type[second] == EW_TYPE_LLAMA)
        return horse_mating_pair_types(s->type[first], s->type[second])
            && (m->horse_status[first] & GM_HORSE_TAME)
            && (m->horse_status[second] & GM_HORSE_TAME)
            && m->growing_age[first] == 0
            && m->growing_age[second] == 0
            && s->health[first] >= (float)m->horse_max_health[first]
            && s->health[second] >= (float)m->horse_max_health[second]
            && !ride_is_slot(s, first, m->horse_ride_eid)
            && !ride_is_slot(s, second, m->horse_ride_eid);
    return s->type[first] == s->type[second];
}

static int animal_nearest_mate_slot(
        const GmMobLive *m, const EwStore *s, int initiator, int dimension) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)s;
    int best_eid = -1;
    double best_distance = HUGE_VAL;
    if (!m || !s || initiator <= 0 || initiator >= EW_MAX_ENTITIES
            || !s->alive[initiator] || !gm_passive(s->type[initiator])
            || m->sheep_in_love[initiator] <= 0)
        return -1;
    int initiator_eid = s->id[initiator];
    double initiator_x = s->x[initiator];
    double initiator_y = s->y[initiator];
    double initiator_z = s->z[initiator];
    int cursor = 0, slot;
    while ((slot = living_next_slot_from_store(
                mutable_m, completed, &cursor)) > 0) {
        if (s->id[slot] == initiator_eid || !s->alive[slot]
                || m->entity_dimension[slot] != dimension
                || !animal_mate_compatible(m, s, initiator, slot))
            continue;
        double dx = s->x[slot] - initiator_x;
        double dy = s->y[slot] - initiator_y;
        double dz = s->z[slot] - initiator_z;
        if (fabs(dx) >= 8.9 || fabs(dy) >= 9.3 || fabs(dz) >= 8.9)
            continue;
        double distance = dx * dx + dy * dy + dz * dz;
        if (distance < best_distance) {
            best_eid = s->id[slot];
            best_distance = distance;
        }
    }
    living_cold_flush_one_from_store(
        mutable_m, completed, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &mutable_m->living_staged_cold_secondary);
    return mob_slot_by_eid(m, best_eid);
}

/* Negative lower-priority animal task path. EntityAITasks evaluates wander,
 * watch-player, and idle-look in that order after mate/follow decline (and,
 * for sheep, after grazing also declines).
 * The accepted task effects remain owned by their later feature slices; this
 * helper preserves the exact cursor whenever those rolls decline. */
static void animal_declined_lower_task_rng(
        GmMobLive *m, int slot, double player_distance_sq) {
    JavaRandom *random = &m->entity_random[slot].random;
    if (jrand_int_bound(random, 120) == 0)
        return;
    if (jrand_float(random) < 0.02F && player_distance_sq <= 36.0) {
        (void)jrand_int_bound(random, 40);
        return;
    }
    if (jrand_float(random) < 0.02F) {
        (void)jrand_double(random);
        (void)jrand_int_bound(random, 20);
    }
}

/* Exact lower-priority goal pass for a mounted skeleton-trap horse. The
 * rider clears the horse navigator later in the same loaded-list boundary,
 * but the horse has already consumed this RNG and moved once by then. */
static int skeleton_trap_horse_lower_tasks(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot,
        double player_distance_sq) {
    unsigned int lower = PAI_BIT(PAI_WATCH) | PAI_BIT(PAI_IDLE);
    if (m->passive_tasks[slot] & lower) {
        /* A skeleton passenger disables look/move control flags every five
         * ticks. EntityAITasks still permits a start while its executing set
         * is empty, then rejects and resets that task on the next setup pass. */
        m->passive_tasks[slot] &= ~lower;
        return 0;
    }
    JavaRandom *random = &m->entity_random[slot].random;
    if (jrand_int_bound(random, 120) != 0) {
        if (jrand_float(random) < 0.02F && player_distance_sq <= 36.0) {
            m->passive_watch_time[slot] =
                40 + jrand_int_bound(random, 40) - 1;
            m->passive_tasks[slot] |= PAI_BIT(PAI_WATCH);
            return 0;
        }
        if (jrand_float(random) < 0.02F) {
            double angle = MC_PI * 2.0 * jrand_double(random);
            m->passive_idle_x[slot] = cos(angle);
            m->passive_idle_z[slot] = sin(angle);
            m->passive_idle_time[slot] =
                20 + jrand_int_bound(random, 20) - 1;
            m->passive_tasks[slot] |= PAI_BIT(PAI_IDLE);
        }
        return 0;
    }

    double target_x = 0.0D, target_y = 0.0D, target_z = 0.0D;
    int found;
    if (m->entity_in_water[slot]) {
        found = animal_random_position_exact(
            m, w, s, slot, 15, 7, 1,
            &target_x, &target_y, &target_z);
        if (!found)
            found = animal_random_position_exact(
                m, w, s, slot, 10, 7, 0,
                &target_x, &target_y, &target_z);
    } else {
        int land = jrand_float(random) >= 0.001F;
        found = animal_random_position_exact(
            m, w, s, slot, 10, 7, land,
            &target_x, &target_y, &target_z);
    }
    if (!found) {
        if (jrand_float(random) < 0.02F && player_distance_sq <= 36.0) {
            m->passive_watch_time[slot] =
                40 + jrand_int_bound(random, 40) - 1;
            m->passive_tasks[slot] |= PAI_BIT(PAI_WATCH);
            return 0;
        }
        if (jrand_float(random) < 0.02F) {
            double angle = MC_PI * 2.0 * jrand_double(random);
            m->passive_idle_x[slot] = cos(angle);
            m->passive_idle_z[slot] = sin(angle);
            m->passive_idle_time[slot] =
                20 + jrand_int_bound(random, 20) - 1;
            m->passive_tasks[slot] |= PAI_BIT(PAI_IDLE);
        }
        return 0;
    }

    int bx = mc_floor(target_x);
    int by = animal_navigation_surface_y(
        w, bx, mc_floor(target_y), mc_floor(target_z));
    int bz = mc_floor(target_z);
    s->path_len[slot] = skeleton_trap_horse_wander_target(
        w, s, slot, target_x, target_y, target_z,
        &s->path_tx[slot], &s->path_ty[slot], &s->path_tz[slot]);
    if (!s->path_len[slot]) {
        /* Allocation failure keeps the former direct standability fallback. */
        s->path_tx[slot] = bx + 1.0D;
        s->path_ty[slot] = by;
        s->path_tz[slot] = bz + 1.0D;
        s->path_len[slot] = by > 0 && by < 256
            && solid_id(gm_world_block(w, bx, by - 1, bz))
            && !solid_id(gm_world_block(w, bx, by, bz))
            && !solid_id(gm_world_block(w, bx, by + 1, bz));
    }
    m->passive_nav_speed[slot] = 0.7D;
    m->passive_tasks[slot] |= PAI_BIT(PAI_WANDER);
    m->skeleton_trap_move_wait_latched[slot] = 0;
    m->skeleton_trap_move_terminal_ticks[slot] = 0;
    m->skeleton_trap_move_action[slot] = s->path_len[slot] ? 1 : 0;

    /* The accepted priority-six wander prevents both lower selector entries
     * on this boundary in the 1.11.2 trap trace. */
    return s->path_len[slot] != 0;
}

/* EntityChicken.onLivingUpdate runs after the complete EntityAnimal tail, so
 * it observes post-collision onGround/motionY and the already-updated age. */
static void chicken_living_tail(
        GmMobLive *m, EwStore *s, int slot,
        uint64_t *math_random_seed48, int *next_entity_id,
        GmLiveSim *drops) {
    m->chicken_old_flap[slot] = m->chicken_wing_rotation[slot];
    m->chicken_old_flap_speed[slot] = m->chicken_dest_pos[slot];
    m->chicken_dest_pos[slot] = (float)(
        (double)m->chicken_dest_pos[slot]
            + (double)(s->on_ground[slot] ? -1 : 4) * 0.3);
    if (m->chicken_dest_pos[slot] < 0.0F)
        m->chicken_dest_pos[slot] = 0.0F;
    else if (m->chicken_dest_pos[slot] > 1.0F)
        m->chicken_dest_pos[slot] = 1.0F;
    if (!s->on_ground[slot] && m->chicken_wing_rot_delta[slot] < 1.0F)
        m->chicken_wing_rot_delta[slot] = 1.0F;
    m->chicken_wing_rot_delta[slot] = (float)(
        (double)m->chicken_wing_rot_delta[slot] * 0.9);
    if (!s->on_ground[slot] && s->vy[slot] < 0.0)
        s->vy[slot] *= 0.6;
    m->chicken_wing_rotation[slot] +=
        m->chicken_wing_rot_delta[slot] * 2.0F;

    if (m->growing_age[slot] >= 0 && !m->chicken_jockey[slot]
            && --m->chicken_time_until_next_egg[slot] <= 0) {
        float pitch_first = jrand_float(&m->entity_random[slot].random);
        float pitch_second = jrand_float(&m->entity_random[slot].random);
        float pitch = (pitch_first - pitch_second) * 0.2F + 1.0F;
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot],
            GM_MOB_SOUND_CHICKEN_EGG,
            s->x[slot], s->y[slot], s->z[slot], 1.0F, pitch);
        if (math_random_seed48 && next_entity_id && drops
                && *next_entity_id > 0 && *next_entity_id < INT_MAX) {
            int eid = (*next_entity_id)++;
            if (m->next_id <= eid) m->next_id = eid + 1;
            if (m->next_orb_id <= eid) m->next_orb_id = eid + 1;
            float hover_start = (float)(
                mob_math_random_next_double(math_random_seed48)
                    * (MC_PI * 2.0));
            float yaw = (float)(
                mob_math_random_next_double(math_random_seed48) * 360.0);
            double motion_x = (double)(float)(
                mob_math_random_next_double(math_random_seed48)
                    * 0.20000000298023224 - 0.10000000149011612);
            double motion_z = (double)(float)(
                mob_math_random_next_double(math_random_seed48)
                    * 0.20000000298023224 - 0.10000000149011612);
            /* Items.EGG is numeric item id 344 in the 1.11.2 registry. */
            if (!gm_live_spawn_item_exact_hover(
                drops, eid, s->x[slot], s->y[slot], s->z[slot],
                motion_x, 0.20000000298023224, motion_z,
                yaw, hover_start, 344, 1, 0, 0, 10, 0))
                ++drops->spawn_fail_count;
        }
        m->chicken_time_until_next_egg[slot] =
            jrand_int_bound(&m->entity_random[slot].random, 6000) + 6000;
    }
}

static void living_entity_size(
        const GmMobLive *m, const EwStore *s, int slot,
        double *width, double *height) {
    float w, h;
    ehs_size_scaled(s->type[slot], m->size[slot], &w, &h);
    if (gm_child_sized(s->type[slot]) && m->growing_age[slot] < 0) {
        w *= 0.5F;
        h *= 0.5F;
    }
    *width = (double)w;
    *height = (double)h;
}

static int iron_golem_target_eligible(
        const GmMobLive *m, const EwStore *s,
        int golem, int target, int dimension, int village_defense) {
    if (!m || !s || golem <= 0 || target <= 0 || golem == target
            || !s->alive[target] || m->entity_dead[target]
            || s->health[target] <= 0.0F
            || m->entity_dimension[target] != dimension
            || (!village_defense && !gm_hostile(s->type[target]))
            || s->type[target] == EW_TYPE_CREEPER
            || (!village_defense && s->type[target] == EW_TYPE_GHAST))
        return 0;
    return 1;
}

static int iron_golem_target_valid(
        const GmMobLive *m, const EwStore *s,
        int golem, int target, int dimension, int village_defense) {
    if (!iron_golem_target_eligible(
            m, s, golem, target, dimension, village_defense))
        return 0;
    double dx = s->x[target] - s->x[golem];
    double dy = s->y[target] - s->y[golem];
    double dz = s->z[target] - s->z[golem];
    return dx * dx + dy * dy + dz * dz <= 256.0D;
}

static int iron_golem_slot_by_eid(
        const GmMobLive *m, const EwStore *s, int eid) {
    (void)s;
    return mob_slot_by_eid(m, eid);
}

static int iron_golem_nearest_target(
        const GmMobLive *m, const EwStore *s,
        int golem, int dimension) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)s;
    int best_eid = -1;
    double best_distance = 256.0D;
    double golem_x = s->x[golem], golem_y = s->y[golem];
    double golem_z = s->z[golem];
    int cursor = 0, target;
    while ((target = living_next_slot_from_store(
                mutable_m, completed, &cursor)) > 0) {
        if (!iron_golem_target_eligible(
                m, s, golem, target, dimension, 0))
            continue;
        double dy = s->y[target] - golem_y;
        double dx = s->x[target] - golem_x;
        double dz = s->z[target] - golem_z;
        if (dx < -16.0D || dx > 16.0D
                || dy < -4.0D || dy > 4.0D
                || dz < -16.0D || dz > 16.0D)
            continue;
        double distance = dx * dx + dy * dy + dz * dz;
        if (best_eid < 0 || distance < best_distance) {
            best_eid = s->id[target];
            best_distance = distance;
        }
    }
    living_cold_flush_one_from_store(
        mutable_m, completed, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &mutable_m->living_staged_cold_secondary);
    return mob_slot_by_eid(m, best_eid);
}

static void iron_golem_move_animation_and_step(
        GmMobLive *m, GmWorld *w,
        const EwStore *before, EwStore *after, int slot) {
    double dx = after->x[slot] - before->x[slot];
    double dz = after->z[slot] - before->z[slot];
    float amount = (float)sqrt(dx * dx + dz * dz) * 4.0F;
    if (amount > 1.0F) amount = 1.0F;
    m->golem_limb_amount[slot] +=
        (amount - m->golem_limb_amount[slot]) * 0.4F;
    m->golem_limb_swing[slot] += m->golem_limb_amount[slot];

    if (!after->on_ground[slot]) return;
    float walked = (float)((double)m->golem_step_distance[slot]
        + sqrt(dx * dx + dz * dz) * 0.6D);
    m->golem_step_distance[slot] = walked;
    int bx = mc_floor(after->x[slot]);
    int by = mc_floor(after->y[slot] - 0.20000000298023224D);
    int bz = mc_floor(after->z[slot]);
    if (walked > (float)m->golem_next_step_distance[slot]
            && gm_world_block(w, bx, by, bz) != 0) {
        m->golem_next_step_distance[slot] = (int)walked + 1;
        if (!m->entity_in_water[slot])
            mob_event_append(
                m, GM_MOB_EVENT_SOUND, after->id[slot],
                GM_MOB_SOUND_IRON_GOLEM_STEP,
                after->x[slot], after->y[slot], after->z[slot],
                1.0F, 1.0F);
    }
}

static void llama_step_sound(
        GmMobLive *m, GmWorld *w,
        const EwStore *before, EwStore *after, int slot) {
    double dx = after->x[slot] - before->x[slot];
    double dz = after->z[slot] - before->z[slot];
    float walked = (float)((double)m->llama_step_distance[slot]
        + sqrt(dx * dx + dz * dz) * 0.6D);
    m->llama_step_distance[slot] = walked;
    int bx = mc_floor(after->x[slot]);
    int by = mc_floor(after->y[slot] - 0.20000000298023224D);
    int bz = mc_floor(after->z[slot]);
    if (walked > (float)m->llama_next_step_distance[slot]
            && gm_world_block(w, bx, by, bz) != 0) {
        m->llama_next_step_distance[slot] = (int)walked + 1;
        if (!m->entity_in_water[slot])
            mob_event_append(
                m, GM_MOB_EVENT_SOUND, after->id[slot],
                GM_MOB_SOUND_LLAMA_STEP,
                after->x[slot], after->y[slot], after->z[slot],
                0.15F, 1.0F);
    }
}

static void iron_golem_living_tail(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot) {
    if (m->golem_attack_timer[slot] > 0)
        --m->golem_attack_timer[slot];
    if (m->golem_hold_rose_tick[slot] > 0)
        --m->golem_hold_rose_tick[slot];
    if (s->vx[slot] * s->vx[slot] + s->vz[slot] * s->vz[slot]
            > 2.500000277905201E-7D
            && jrand_int_bound(&m->entity_random[slot].random, 5) == 0) {
        int bx = mc_floor(s->x[slot]);
        int by = mc_floor(s->y[slot] - 0.20000000298023224D);
        int bz = mc_floor(s->z[slot]);
        int block = gm_world_block(w, bx, by, bz);
        int meta = gm_world_meta(w, bx, by, bz);
        if (block != 0) {
            float width = 1.4F;
            float px = jrand_float(&m->entity_random[slot].random);
            float pz = jrand_float(&m->entity_random[slot].random);
            float vx = jrand_float(&m->entity_random[slot].random);
            float vz = jrand_float(&m->entity_random[slot].random);
            GmMobParticleBatch batch = {
                .eid = s->id[slot],
                .dimension = m->entity_dimension[slot],
                .particle_id = 37,
                .count = 1,
                .parameter_count = 1,
                .parameters = {block | ((meta & 15) << 12), 0}
            };
            batch.particles[0] = (GmTerminalParticle){
                s->x[slot] + ((double)px - 0.5D) * (double)width,
                s->y[slot] + 0.1D,
                s->z[slot] + ((double)pz - 0.5D) * (double)width,
                4.0D * ((double)vx - 0.5D), 0.5D,
                ((double)vz - 0.5D) * 4.0D
            };
            mob_particle_batch_append(m, &batch);
        }
    }
}

static int villager_has_enough_food(
        const GmMobLive *m, int slot) {
    int farmer = m->villager_profession[slot] == 0;
    for (int i = 0; i < 8; ++i) {
        const ICStack *stack = &m->villager_inventory[slot][i];
        if ((stack->item == 297 && stack->count >= 3)
                || (stack->item == 392 && stack->count >= 12)
                || (stack->item == 391 && stack->count >= 12)
                || (stack->item == 434 && stack->count >= 12)
                || (farmer && stack->item == 296
                    && stack->count >= 9))
            return 1;
    }
    return 0;
}

static int villager_update_willing(
        GmMobLive *m, EwStore *s, int slot, int update_first) {
    if (m->villager_willing[slot] || !update_first
            || !villager_has_enough_food(m, slot))
        return m->villager_willing[slot] != 0;
    for (int i = 0; i < 8; ++i) {
        ICStack *stack = &m->villager_inventory[slot][i];
        int consume = stack->item == 297 && stack->count >= 3 ? 3
            : ((stack->item == 392 || stack->item == 391)
                && stack->count >= 12 ? 12 : 0);
        if (!consume) continue;
        stack->count -= consume;
        if (stack->count <= 0) *stack = ic_empty();
        m->villager_willing[slot] = 1;
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 18,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
        break;
    }
    return m->villager_willing[slot] != 0;
}

static int villager_sufficient_doors(
        const GmMobLive *m, int slot) {
    if (!m->villager_village_valid[slot]
            || !m->villager_village_mating[slot])
        return 0;
    int limit = (int)((double)((float)
        m->villager_village_doors[slot]) * 0.35D);
    return m->villager_village_population[slot] < limit;
}

static int villager_nearest_mate_slot(
        const GmMobLive *m, const EwStore *s,
        int self, int dimension) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)s;
    int best_eid = -1;
    double best_distance = HUGE_VAL;
    double self_width, self_height;
    living_entity_size(m, s, self, &self_width, &self_height);
    double min_x = s->x[self] - self_width * 0.5D - 8.0D;
    double max_x = s->x[self] + self_width * 0.5D + 8.0D;
    double min_y = s->y[self] - 3.0D;
    double max_y = s->y[self] + self_height + 3.0D;
    double min_z = s->z[self] - self_width * 0.5D - 8.0D;
    double max_z = s->z[self] + self_width * 0.5D + 8.0D;
    int self_eid = s->id[self];
    double self_x = s->x[self], self_y = s->y[self], self_z = s->z[self];
    int cursor = 0, slot;
    while ((slot = living_next_slot_from_store(
                mutable_m, completed, &cursor)) > 0) {
        double width, height, distance, dx, dy, dz;
        if (s->id[slot] == self_eid || !s->alive[slot]
                || s->type[slot] != EW_TYPE_VILLAGER
                || m->entity_dimension[slot] != dimension
                || m->entity_dead[slot] || s->health[slot] <= 0.0F)
            continue;
        living_entity_size(m, s, slot, &width, &height);
        if (!(s->x[slot] + width * 0.5D > min_x
                && s->x[slot] - width * 0.5D < max_x
                && s->y[slot] + height > min_y
                && s->y[slot] < max_y
                && s->z[slot] + width * 0.5D > min_z
                && s->z[slot] - width * 0.5D < max_z))
            continue;
        dx = s->x[slot] - self_x;
        dy = s->y[slot] - self_y;
        dz = s->z[slot] - self_z;
        distance = dx * dx + dy * dy + dz * dz;
        if (distance < best_distance) {
            best_eid = s->id[slot];
            best_distance = distance;
        }
    }
    living_cold_flush_one_from_store(
        mutable_m, completed, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &mutable_m->living_staged_cold_secondary);
    return mob_slot_by_eid(m, best_eid);
}

static int villager_rose_golem_slot(
        const GmMobLive *m, const EwStore *s,
        int self, int dimension) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)s;
    double self_width, self_height;
    living_entity_size(m, s, self, &self_width, &self_height);
    double query_min_x = s->x[self] - self_width * 0.5D - 6.0D;
    double query_max_x = s->x[self] + self_width * 0.5D + 6.0D;
    double query_min_y = s->y[self] - 2.0D;
    double query_max_y = s->y[self] + self_height + 2.0D;
    double query_min_z = s->z[self] - self_width * 0.5D - 6.0D;
    double query_max_z = s->z[self] + self_width * 0.5D + 6.0D;
    /* World.getEntitiesWithinAABB preserves loadedEntityList order. */
    for (int order = 0; order < m->loaded_order_count; ++order) {
        const GmMobLoadedRef *ref = loaded_ref_at_const(m, order);
        int slot = living_loaded_ref_stage_secondary(
            mutable_m, ref, completed);
        if (slot <= 0
                || s->type[slot] != EW_TYPE_IRON_GOLEM
                || m->entity_dimension[slot] != dimension
                || m->entity_dead[slot] || s->health[slot] <= 0.0F)
            continue;
        double width, height;
        living_entity_size(m, s, slot, &width, &height);
        if (s->x[slot] + width * 0.5D > query_min_x
                && s->x[slot] - width * 0.5D < query_max_x
                && s->y[slot] + height > query_min_y
                && s->y[slot] < query_max_y
                && s->z[slot] + width * 0.5D > query_min_z
                && s->z[slot] - width * 0.5D < query_max_z
                && m->golem_hold_rose_tick[slot] > 0)
            return slot;
    }
    return -1;
}

static void villager_follow_golem_reset(
        GmMobLive *m, EwStore *s, int slot) {
    m->villager_follow_golem_active[slot] = 0;
    m->villager_took_golem_rose[slot] = 0;
    m->villager_follow_golem_eid[slot] = -1;
    m->villager_take_golem_rose_tick[slot] = 0;
    s->path_len[slot] = 0;
}

static int villager_follow_golem_start(
        GmMobLive *m, EwStore *s, int slot, int dimension, int day) {
    int golem;
    if (m->growing_age[slot] >= 0 || !day) return 0;
    golem = villager_rose_golem_slot(m, s, slot, dimension);
    if (golem <= 0) return 0;
    m->villager_follow_golem_active[slot] = 1;
    m->villager_took_golem_rose[slot] = 0;
    m->villager_follow_golem_eid[slot] = s->id[golem];
    m->villager_take_golem_rose_tick[slot] = jrand_int_bound(
        &m->entity_random[slot].random, 320);
    /* EntityAIFollowGolem.startExecuting clears the golem navigator. */
    s->path_len[golem] = 0;
    return 1;
}

static void villager_follow_golem_update(
        GmMobLive *m, EwStore *s, int slot, int dimension) {
    int golem = iron_golem_slot_by_eid(
        m, s, m->villager_follow_golem_eid[slot]);
    if (golem <= 0 || !s->alive[golem]
            || s->type[golem] != EW_TYPE_IRON_GOLEM
            || m->entity_dimension[golem] != dimension
            || m->golem_hold_rose_tick[golem] <= 0) {
        villager_follow_golem_reset(m, s, slot);
        return;
    }
    double dx = s->x[golem] - s->x[slot];
    double dy = s->y[golem] - s->y[slot];
    double dz = s->z[golem] - s->z[slot];
    s->yaw[slot] = ehs_yaw_toward(dx, dz);
    if (m->golem_hold_rose_tick[golem]
            == m->villager_take_golem_rose_tick[slot]) {
        s->path_tx[slot] = s->x[golem];
        s->path_ty[slot] = s->y[golem];
        s->path_tz[slot] = s->z[golem];
        s->path_len[slot] = 1;
        m->villager_took_golem_rose[slot] = 1;
    }
    if (m->villager_took_golem_rose[slot]
            && dx * dx + dy * dy + dz * dz < 4.0D) {
        m->golem_hold_rose_tick[golem] = 0;
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[golem], 34,
            s->x[golem], s->y[golem], s->z[golem], 0.0F, 0.0F);
        s->path_len[slot] = 0;
    }
}

int gm_mobs_villager_follow_golem_task(
        GmMobLive *m, int eid, int day, int setup_tick) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_VILLAGER
            || (day != 0 && day != 1)
            || (setup_tick != 0 && setup_tick != 1))
        return 0;
    loaded_order_prepare(m);
    if (m->villager_follow_golem_active[slot]) {
        int golem = iron_golem_slot_by_eid(
            m, s, m->villager_follow_golem_eid[slot]);
        if (golem <= 0 || !s->alive[golem]
                || s->type[golem] != EW_TYPE_IRON_GOLEM
                || m->entity_dimension[golem]
                    != m->entity_dimension[slot]
                || m->golem_hold_rose_tick[golem] <= 0)
            villager_follow_golem_reset(m, s, slot);
    }
    if (!m->villager_follow_golem_active[slot] && setup_tick)
        (void)villager_follow_golem_start(
            m, s, slot, m->entity_dimension[slot], day);
    if (m->villager_follow_golem_active[slot])
        villager_follow_golem_update(
            m, s, slot, m->entity_dimension[slot]);
    ew_store_copy(next_store(m), s);
    if (!m->villager_follow_golem_active[slot]) return 0;
    int golem = iron_golem_slot_by_eid(
        m, s, m->villager_follow_golem_eid[slot]);
    return golem > 0 && m->golem_hold_rose_tick[golem] > 0 ? 1 : 0;
}

static int villager_front_door_inside_side(
        const GmMobLive *m, const EwStore *s, int slot) {
    int pos_x = mc_floor(s->x[slot]);
    int pos_z = mc_floor(s->z[slot]);
    int delta_x = pos_x - m->villager_front_door_x[slot];
    /* This is the literal 1.11.2 VillageDoorInfo implementation: its second
     * subtraction uses doorBlockPos.getY(), not getZ(). */
    int delta_z = pos_z - m->villager_front_door_y[slot];
    return delta_x * (m->villager_front_door_inside_dx[slot] / 2)
        + delta_z * (m->villager_front_door_inside_dz[slot] / 2) >= 0;
}

static void villager_restrict_door_tick(
        GmMobLive *m, const EwStore *s, int slot,
        int day, int setup_tick) {
    if (m->villager_restrict_door_active[slot]
            && (day || !m->villager_front_door_valid[slot]
                || m->villager_front_door_detached[slot]
                || !villager_front_door_inside_side(m, s, slot))) {
        m->villager_restrict_door_active[slot] = 0;
        m->villager_break_doors[slot] = 1;
        m->villager_enter_doors[slot] = 1;
    }
    if (!m->villager_restrict_door_active[slot]
            && setup_tick && !day
            && m->villager_front_door_valid[slot]) {
        int inside_x = m->villager_front_door_x[slot]
            + m->villager_front_door_inside_dx[slot];
        int inside_y = m->villager_front_door_y[slot];
        int inside_z = m->villager_front_door_z[slot]
            + m->villager_front_door_inside_dz[slot];
        int pos_x = mc_floor(s->x[slot]);
        int pos_y = mc_floor(s->y[slot]);
        int pos_z = mc_floor(s->z[slot]);
        int dx = inside_x - pos_x;
        int dy = inside_y - pos_y;
        int dz = inside_z - pos_z;
        if ((double)(dx * dx + dy * dy + dz * dz) < 2.25D) {
            m->villager_restrict_door_active[slot] = 1;
            m->villager_break_doors[slot] = 0;
            m->villager_enter_doors[slot] = 0;
        }
    }
    if (m->villager_restrict_door_active[slot])
        m->villager_door_restriction_pending[slot] = 1;
}

int gm_mobs_villager_restrict_door_task(
        GmMobLive *m, int eid, int day, int setup_tick) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_VILLAGER
            || (day != 0 && day != 1)
            || (setup_tick != 0 && setup_tick != 1))
        return 0;
    villager_restrict_door_tick(m, s, slot, day, setup_tick);
    return m->villager_restrict_door_active[slot] ? 1 : 0;
}

static int villager_wood_door_at(
        const GmWorld *w, int x, int y, int z) {
    int id = gm_world_block(w, x, y, z);
    return id == 64 || (id >= 193 && id <= 197);
}

static void villager_toggle_door(
        GmMobLive *m, GmWorld *w, int slot, int open) {
    int x = m->villager_open_door_x[slot];
    int y = m->villager_open_door_y[slot];
    int z = m->villager_open_door_z[slot];
    if (!villager_wood_door_at(w, x, y, z)) return;
    int id = gm_world_block(w, x, y, z);
    int meta = gm_world_meta(w, x, y, z);
    int lower_y = (meta & 8) ? y - 1 : y;
    if (gm_world_block(w, x, lower_y, z) != id) return;
    int lower_meta = gm_world_meta(w, x, lower_y, z);
    int was_open = (lower_meta & 4) != 0;
    if (was_open == open) return;
    gm_world_set_block_meta(
        w, x, lower_y, z, id,
        open ? lower_meta | 4 : lower_meta & ~4);
    mob_event_append(
        m, GM_MOB_EVENT_WORLD_EVENT, 0, open ? 1006 : 1012,
        (double)x, (double)y, (double)z, 0.0F, 0.0F);
}

static void villager_open_door_reset(
        GmMobLive *m, GmWorld *w, int slot) {
    villager_toggle_door(m, w, slot, 0);
    m->villager_open_door_active[slot] = 0;
    m->villager_stopped_door_interaction[slot] = 0;
    m->villager_close_door_timer[slot] = 0;
}

static int villager_open_door_should_start(
        GmMobLive *m, GmWorld *w, const EwStore *s, int slot) {
    if (!m->entity_collided_horizontal[slot]
            || !m->villager_enter_doors[slot])
        return 0;
    int x = 0, y = 0, z = 0, found = 0;
    if (s->path_len[slot] == 1) {
        x = mc_floor(s->path_tx[slot]);
        y = mc_floor(s->path_ty[slot]) + 1;
        z = mc_floor(s->path_tz[slot]);
        double dx = (double)x - s->x[slot];
        double dz = (double)z - s->z[slot];
        found = dx * dx + dz * dz <= 2.25D
            && villager_wood_door_at(w, x, y, z);
    }
    if (!found) {
        x = mc_floor(s->x[slot]);
        y = mc_floor(s->y[slot]) + 1;
        z = mc_floor(s->z[slot]);
        found = villager_wood_door_at(w, x, y, z);
    }
    if (!found) return 0;
    m->villager_open_door_x[slot] = x;
    m->villager_open_door_y[slot] = y;
    m->villager_open_door_z[slot] = z;
    return 1;
}

static void villager_open_door_start(
        GmMobLive *m, GmWorld *w, const EwStore *s, int slot) {
    int x = m->villager_open_door_x[slot];
    int z = m->villager_open_door_z[slot];
    m->villager_open_door_active[slot] = 1;
    m->villager_stopped_door_interaction[slot] = 0;
    m->villager_close_door_timer[slot] = 20;
    m->villager_door_start_x[slot] = (float)(
        (double)((float)x + 0.5F) - s->x[slot]);
    m->villager_door_start_z[slot] = (float)(
        (double)((float)z + 0.5F) - s->z[slot]);
    villager_toggle_door(m, w, slot, 1);
}

static void villager_open_door_tick(
        GmMobLive *m, GmWorld *w, const EwStore *s,
        int slot, int setup_tick) {
    if (m->villager_open_door_active[slot]
            && (m->villager_close_door_timer[slot] <= 0
                || m->villager_stopped_door_interaction[slot]))
        villager_open_door_reset(m, w, slot);
    if (!m->villager_open_door_active[slot] && setup_tick
            && villager_open_door_should_start(m, w, s, slot))
        villager_open_door_start(m, w, s, slot);
    if (!m->villager_open_door_active[slot]) return;
    --m->villager_close_door_timer[slot];
    float dx = (float)(
        (double)((float)m->villager_open_door_x[slot] + 0.5F)
            - s->x[slot]);
    float dz = (float)(
        (double)((float)m->villager_open_door_z[slot] + 0.5F)
            - s->z[slot]);
    if (m->villager_door_start_x[slot] * dx
            + m->villager_door_start_z[slot] * dz < 0.0F)
        m->villager_stopped_door_interaction[slot] = 1;
}

int gm_mobs_villager_open_door_task(
        GmMobLive *m, GmWorld *world, int eid, int setup_tick) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || !world
            || s->type[slot] != EW_TYPE_VILLAGER
            || (setup_tick != 0 && setup_tick != 1))
        return 0;
    villager_open_door_tick(m, world, s, slot, setup_tick);
    return m->villager_open_door_active[slot]
        && m->villager_close_door_timer[slot] > 0
        && !m->villager_stopped_door_interaction[slot];
}

int gm_mobs_set_villager_indoors_context(
        GmMobLive *m, int eid, int door_valid,
        int door_x, int door_y, int door_z, int inside_dx, int inside_dz,
        int home_valid, int home_x, int home_y, int home_z,
        int home_radius) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_VILLAGER
            || (door_valid != 0 && door_valid != 1)
            || (home_valid != 0 && home_valid != 1)
            || (door_valid && (((inside_dx == 0) == (inside_dz == 0))
                || (inside_dx != -2 && inside_dx != 0 && inside_dx != 2)
                || (inside_dz != -2 && inside_dz != 0 && inside_dz != 2)))
            || (!door_valid && (door_x != 0 || door_y != 0 || door_z != 0
                || inside_dx != 0 || inside_dz != 0))
            || (home_valid && home_radius < 0)
            || (!home_valid && (home_x != 0 || home_y != 0 || home_z != 0
                || home_radius != 0)))
        return 0;
    m->villager_indoors_door_valid[slot] = (unsigned char)door_valid;
    m->villager_indoors_door_x[slot] = door_x;
    m->villager_indoors_door_y[slot] = door_y;
    m->villager_indoors_door_z[slot] = door_z;
    m->villager_indoors_inside_dx[slot] = inside_dx;
    m->villager_indoors_inside_dz[slot] = inside_dz;
    m->villager_home_valid[slot] = (unsigned char)home_valid;
    m->villager_home_x[slot] = home_x;
    m->villager_home_y[slot] = home_y;
    m->villager_home_z[slot] = home_z;
    m->villager_home_radius[slot] = home_radius;
    return 1;
}

static int villager_random_target_towards(
        GmMobLive *m, const GmWorld *w, EwStore *s, int slot,
        int xz, int y, int has_direction, int avoid_water,
        double target_x, double target_z,
        double *result_x, double *result_y, double *result_z) {
    JavaRandom *random = &m->entity_random[slot].random;
    double direction_x = target_x - s->x[slot];
    double direction_z = target_z - s->z[slot];
    int constrain_home = 0;
    int found = 0;
    if (m->villager_home_valid[slot]) {
        double hx = (double)m->villager_home_x[slot]
            - (double)mc_floor(s->x[slot]);
        double hy = (double)m->villager_home_y[slot]
            - (double)mc_floor(s->y[slot]);
        double hz = (double)m->villager_home_z[slot]
            - (double)mc_floor(s->z[slot]);
        double reach = (double)(m->villager_home_radius[slot] + xz);
        constrain_home = hx * hx + hy * hy + hz * hz + 4.0D
            < reach * reach;
    }
    for (int candidate = 0; candidate < 10; ++candidate) {
        int dx = jrand_int_bound(random, 2 * xz + 1) - xz;
        int dy = jrand_int_bound(random, 2 * y + 1) - y;
        int dz = jrand_int_bound(random, 2 * xz + 1) - xz;
        if (has_direction
                && (double)dx * direction_x
                    + (double)dz * direction_z < 0.0D)
            continue;
        if (m->villager_home_valid[slot] && xz > 1) {
            if (s->x[slot] > (double)m->villager_home_x[slot])
                dx -= jrand_int_bound(random, xz / 2);
            else
                dx += jrand_int_bound(random, xz / 2);
            if (s->z[slot] > (double)m->villager_home_z[slot])
                dz -= jrand_int_bound(random, xz / 2);
            else
                dz += jrand_int_bound(random, xz / 2);
        }
        int bx = mc_floor((double)dx + s->x[slot]);
        int by = mc_floor((double)dy + s->y[slot]);
        int bz = mc_floor((double)dz + s->z[slot]);
        if (constrain_home) {
            double hx = (double)m->villager_home_x[slot] - bx;
            double hy = (double)m->villager_home_y[slot] - by;
            double hz = (double)m->villager_home_z[slot] - bz;
            double radius = (double)m->villager_home_radius[slot];
            if (hx * hx + hy * hy + hz * hz >= radius * radius)
                continue;
        }
        int below_id = gm_world_block(w, bx, by - 1, bz);
        int below_meta = gm_world_meta(w, bx, by - 1, bz);
        if (!gm_block_is_full_cube_1_11_2(below_id, below_meta))
            continue;
        if (avoid_water) {
            int surface_y = by;
            while (surface_y < 256) {
                int id = gm_world_block(w, bx, surface_y, bz);
                int meta = gm_world_meta(w, bx, surface_y, bz);
                if (!gm_block_is_full_cube_1_11_2(id, meta)) break;
                ++surface_y;
            }
            int id = gm_world_block(w, bx, surface_y, bz);
            if (id == 8 || id == 9) continue;
        }
        /* EntityCreature.getBlockPathWeight is exactly 0.0F. The first
         * valid candidate wins, but Java still consumes all ten samples. */
        if (!found) {
            *result_x = (double)dx + s->x[slot];
            *result_y = (double)dy + s->y[slot];
            *result_z = (double)dz + s->z[slot];
            found = 1;
        }
    }
    return found;
}

static int villager_move_indoors_tick(
        GmMobLive *m, GmWorld *w, EwStore *s,
        int slot, int nighttime_or_snow_shelter, int setup_tick) {
    if (m->villager_move_indoors_active[slot]
            && s->path_len[slot] == 0) {
        m->villager_move_indoors_active[slot] = 0;
        m->villager_last_inside_x[slot] =
            m->villager_indoors_door_x[slot]
                + m->villager_indoors_inside_dx[slot];
        m->villager_last_inside_z[slot] =
            m->villager_indoors_door_z[slot]
                + m->villager_indoors_inside_dz[slot];
    }
    if (!m->villager_move_indoors_active[slot]
            && setup_tick && nighttime_or_snow_shelter) {
        if (jrand_int_bound(&m->entity_random[slot].random, 50) == 0) {
            int recently_inside = 0;
            if (m->villager_last_inside_x[slot] != -1) {
                double dx = s->x[slot]
                    - (double)m->villager_last_inside_x[slot];
                double dz = s->z[slot]
                    - (double)m->villager_last_inside_z[slot];
                recently_inside = dx * dx + dz * dz < 4.0D;
            }
            if (!recently_inside
                    && m->villager_indoors_door_valid[slot]) {
                int inside_x = m->villager_indoors_door_x[slot]
                    + m->villager_indoors_inside_dx[slot];
                int inside_y = m->villager_indoors_door_y[slot];
                int inside_z = m->villager_indoors_door_z[slot]
                    + m->villager_indoors_inside_dz[slot];
                m->villager_last_inside_x[slot] = -1;
                m->villager_move_indoors_active[slot] = 1;
                double dx = s->x[slot] - (double)inside_x;
                double dy = s->y[slot] - (double)inside_y;
                double dz = s->z[slot] - (double)inside_z;
                if (dx * dx + dy * dy + dz * dz > 256.0D) {
                    if (!villager_random_target_towards(
                            m, w, s, slot,
                            14, 3, 1, 0,
                            (double)inside_x + 0.5D,
                            (double)inside_z + 0.5D,
                            &s->path_tx[slot], &s->path_ty[slot],
                            &s->path_tz[slot]))
                        s->path_len[slot] = 0;
                    else
                        s->path_len[slot] = 1;
                } else {
                    s->path_tx[slot] = (double)inside_x + 0.5D;
                    s->path_ty[slot] = (double)inside_y;
                    s->path_tz[slot] = (double)inside_z + 0.5D;
                    s->path_len[slot] = 1;
                }
            }
        }
    }
    return m->villager_move_indoors_active[slot] ? 1 : 0;
}

int gm_mobs_villager_move_indoors_task(
        GmMobLive *m, GmWorld *world, int eid,
        int nighttime_or_snow_shelter, int setup_tick) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || !world
            || s->type[slot] != EW_TYPE_VILLAGER
            || (nighttime_or_snow_shelter != 0
                && nighttime_or_snow_shelter != 1)
            || (setup_tick != 0 && setup_tick != 1))
        return 0;
    int active = villager_move_indoors_tick(
        m, world, s, slot, nighttime_or_snow_shelter, setup_tick);
    ew_store_copy(next_store(m), s);
    return active;
}

static int villager_within_home(
        const GmMobLive *m, const EwStore *s, int slot) {
    if (!m->villager_home_valid[slot]) return 1;
    double dx = (double)m->villager_home_x[slot]
        - (double)mc_floor(s->x[slot]);
    double dy = (double)m->villager_home_y[slot]
        - (double)mc_floor(s->y[slot]);
    double dz = (double)m->villager_home_z[slot]
        - (double)mc_floor(s->z[slot]);
    double radius = (double)m->villager_home_radius[slot];
    return dx * dx + dy * dy + dz * dz < radius * radius;
}

static int villager_move_restriction_tick(
        GmMobLive *m, GmWorld *w, EwStore *s,
        int slot, int setup_tick) {
    if (m->villager_move_restriction_active[slot]
            && s->path_len[slot] == 0)
        m->villager_move_restriction_active[slot] = 0;
    if (!m->villager_move_restriction_active[slot] && setup_tick
            && m->villager_home_valid[slot]
            && !villager_within_home(m, s, slot)) {
        double x, y, z;
        if (villager_random_target_towards(
                m, w, s, slot, 16, 7, 1, 0,
                (double)m->villager_home_x[slot],
                (double)m->villager_home_z[slot], &x, &y, &z)) {
            m->villager_move_restriction_active[slot] = 1;
            s->path_tx[slot] = x;
            s->path_ty[slot] = y;
            s->path_tz[slot] = z;
            s->path_len[slot] = 1;
        }
    }
    return m->villager_move_restriction_active[slot] != 0;
}

int gm_mobs_villager_move_restriction_task(
        GmMobLive *m, GmWorld *world, int eid, int setup_tick) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || !world
            || s->type[slot] != EW_TYPE_VILLAGER
            || (setup_tick != 0 && setup_tick != 1))
        return 0;
    int active = villager_move_restriction_tick(
        m, world, s, slot, setup_tick);
    ew_store_copy(next_store(m), s);
    return active;
}

static int villager_avoid_class_matches(int task, int type) {
    if (task == 0)
        return type == EW_TYPE_ZOMBIE
            || type == EW_TYPE_ZOMBIE_VILLAGER
            || type == EW_TYPE_PIGMAN;
    if (task == 1) return type == EW_TYPE_EVOKER;
    if (task == 2) return type == EW_TYPE_VINDICATOR;
    return task == 3 && type == EW_TYPE_VEX;
}

static int villager_avoid_first_target(
        const GmMobLive *m, GmWorld *w, const EwStore *s,
        int self, int dimension, int task, double distance) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)s;
    double self_width, self_height;
    living_entity_size(m, s, self, &self_width, &self_height);
    double min_x = s->x[self] - self_width * 0.5D - distance;
    double max_x = s->x[self] + self_width * 0.5D + distance;
    double min_y = s->y[self] - 3.0D;
    double max_y = s->y[self] + self_height + 3.0D;
    double min_z = s->z[self] - self_width * 0.5D - distance;
    double max_z = s->z[self] + self_width * 0.5D + distance;
    double self_eye = m->growing_age[self] < 0 ? 0.81D : 1.62D;
    for (int order = 0; order < m->loaded_order_count; ++order) {
        const GmMobLoadedRef *ref = loaded_ref_at_const(m, order);
        int target = living_loaded_ref_stage_secondary(
            mutable_m, ref, completed);
        if (target <= 0 || s->id[target] == s->id[self]
                || m->entity_dimension[target] != dimension
                || m->entity_dead[target] || s->health[target] <= 0.0F
                || !villager_avoid_class_matches(task, s->type[target]))
            continue;
        double width, height;
        living_entity_size(m, s, target, &width, &height);
        if (!(s->x[target] + width * 0.5D > min_x
                && s->x[target] - width * 0.5D < max_x
                && s->y[target] + height > min_y && s->y[target] < max_y
                && s->z[target] + width * 0.5D > min_z
                && s->z[target] - width * 0.5D < max_z))
            continue;
        if (los_clear(
                w, s->x[self], s->y[self] + self_eye, s->z[self],
                s->x[target], s->y[target] + height * 0.85D,
                s->z[target]))
            return target;
    }
    return -1;
}

static int villager_avoid_tick(
        GmMobLive *m, GmWorld *w, EwStore *s,
        int slot, int dimension, int setup_tick) {
    if (m->villager_avoid_active[slot] && s->path_len[slot] == 0) {
        m->villager_avoid_active[slot] = 0;
        m->villager_avoid_target_eid[slot] = -1;
    }
    if (!m->villager_avoid_active[slot] && setup_tick) {
        static const double radius[4] = {8.0D, 12.0D, 8.0D, 8.0D};
        static const float speed[4] = {0.6F, 0.8F, 0.8F, 0.6F};
        for (int task = 0; task < 4; ++task) {
            int target = villager_avoid_first_target(
                m, w, s, slot, dimension, task, radius[task]);
            if (target <= 0) continue;
            double x, y, z;
            if (!villager_random_target_towards(
                    m, w, s, slot, 16, 7, 1, 0,
                    2.0D * s->x[slot] - s->x[target],
                    2.0D * s->z[slot] - s->z[target],
                    &x, &y, &z))
                continue;
            double old_dx = s->x[slot] - s->x[target];
            double old_dy = s->y[slot] - s->y[target];
            double old_dz = s->z[slot] - s->z[target];
            double new_dx = x - s->x[target];
            double new_dy = y - s->y[target];
            double new_dz = z - s->z[target];
            if (new_dx * new_dx + new_dy * new_dy + new_dz * new_dz
                    < old_dx * old_dx + old_dy * old_dy + old_dz * old_dz)
                continue;
            m->villager_avoid_active[slot] = 1;
            m->villager_avoid_target_eid[slot] = s->id[target];
            m->villager_avoid_speed[slot] = speed[task];
            s->path_tx[slot] = x;
            s->path_ty[slot] = y;
            s->path_tz[slot] = z;
            s->path_len[slot] = 1;
            break;
        }
    }
    return m->villager_avoid_active[slot] != 0;
}

int gm_mobs_villager_avoid_task(
        GmMobLive *m, GmWorld *world, int eid, int setup_tick) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || !world
            || s->type[slot] != EW_TYPE_VILLAGER
            || (setup_tick != 0 && setup_tick != 1))
        return 0;
    int active = villager_avoid_tick(
        m, world, s, slot, m->entity_dimension[slot], setup_tick);
    ew_store_copy(next_store(m), s);
    return active;
}

static void villager_play_reset(
        GmMobLive *m, EwStore *s, int slot) {
    m->villager_play_active[slot] = 0;
    m->villager_playing[slot] = 0;
    m->villager_play_target_eid[slot] = -1;
    m->villager_play_time[slot] = 0;
    s->path_len[slot] = 0;
}

static int villager_play_target(
        const GmMobLive *m, const EwStore *s,
        int self, int dimension) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)s;
    double self_width, self_height;
    double best = HUGE_VAL;
    int selected_eid = -1;
    living_entity_size(m, s, self, &self_width, &self_height);
    double min_x = s->x[self] - self_width * 0.5D - 6.0D;
    double max_x = s->x[self] + self_width * 0.5D + 6.0D;
    double min_y = s->y[self] - 3.0D;
    double max_y = s->y[self] + self_height + 3.0D;
    double min_z = s->z[self] - self_width * 0.5D - 6.0D;
    double max_z = s->z[self] + self_width * 0.5D + 6.0D;
    for (int order = 0; order < m->loaded_order_count; ++order) {
        const GmMobLoadedRef *ref = loaded_ref_at_const(m, order);
        int slot = living_loaded_ref_stage_secondary(
            mutable_m, ref, completed);
        if (slot <= 0 || s->id[slot] == s->id[self]
                || s->type[slot] != EW_TYPE_VILLAGER
                || m->entity_dimension[slot] != dimension
                || m->entity_dead[slot] || s->health[slot] <= 0.0F
                || m->growing_age[slot] >= 0
                || m->villager_playing[slot])
            continue;
        double width, height;
        living_entity_size(m, s, slot, &width, &height);
        if (!(s->x[slot] + width * 0.5D > min_x
                && s->x[slot] - width * 0.5D < max_x
                && s->y[slot] + height > min_y && s->y[slot] < max_y
                && s->z[slot] + width * 0.5D > min_z
                && s->z[slot] - width * 0.5D < max_z))
            continue;
        double dx = s->x[slot] - s->x[self];
        double dy = s->y[slot] - s->y[self];
        double dz = s->z[slot] - s->z[self];
        double distance = dx * dx + dy * dy + dz * dz;
        if (distance <= best) {
            best = distance;
            selected_eid = s->id[slot];
        }
    }
    return mob_slot_by_eid(m, selected_eid);
}

static int villager_play_tick(
        GmMobLive *m, GmWorld *w, EwStore *s,
        int slot, int dimension, int setup_tick) {
    if (m->villager_play_active[slot]
            && m->villager_play_time[slot] <= 0)
        villager_play_reset(m, s, slot);
    if (!m->villager_play_active[slot] && setup_tick
            && m->growing_age[slot] < 0
            && jrand_int_bound(
                &m->entity_random[slot].random, 400) == 0) {
        int target = villager_play_target(m, s, slot, dimension);
        if (target > 0) {
            m->villager_play_target_eid[slot] = s->id[target];
        } else {
            double x, y, z;
            if (!villager_random_target_towards(
                    m, w, s, slot, 16, 3, 0, 0, 0.0D, 0.0D,
                    &x, &y, &z))
                return 0;
            m->villager_play_target_eid[slot] = -1;
        }
        m->villager_play_active[slot] = 1;
        m->villager_playing[slot] = target > 0;
        m->villager_play_time[slot] = 1000;
    }
    if (!m->villager_play_active[slot]) return 0;
    --m->villager_play_time[slot];
    int target = iron_golem_slot_by_eid(
        m, s, m->villager_play_target_eid[slot]);
    if (target > 0 && s->alive[target]
            && s->type[target] == EW_TYPE_VILLAGER) {
        double dx = s->x[target] - s->x[slot];
        double dy = s->y[target] - s->y[slot];
        double dz = s->z[target] - s->z[slot];
        if (dx * dx + dy * dy + dz * dz > 4.0D) {
            s->path_tx[slot] = s->x[target];
            s->path_ty[slot] = s->y[target];
            s->path_tz[slot] = s->z[target];
            s->path_len[slot] = 1;
        }
    } else if (m->villager_play_target_eid[slot] < 0
            && s->path_len[slot] == 0) {
        double x, y, z;
        if (villager_random_target_towards(
                m, w, s, slot, 16, 3, 0, 0, 0.0D, 0.0D,
                &x, &y, &z)) {
            s->path_tx[slot] = x;
            s->path_ty[slot] = y;
            s->path_tz[slot] = z;
            s->path_len[slot] = 1;
        }
    }
    return 1;
}

int gm_mobs_villager_play_task(
        GmMobLive *m, GmWorld *world, int eid, int setup_tick) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || !world
            || s->type[slot] != EW_TYPE_VILLAGER
            || (setup_tick != 0 && setup_tick != 1))
        return 0;
    int active = villager_play_tick(
        m, world, s, slot, m->entity_dimension[slot], setup_tick);
    ew_store_copy(next_store(m), s);
    return active;
}

static int villager_has_farm_item(const GmMobLive *m, int slot) {
    for (int i = 0; i < 8; ++i) {
        int item = m->villager_inventory[slot][i].item;
        if (m->villager_inventory[slot][i].count > 0
                && (item == 295 || item == 392
                    || item == 391 || item == 435))
            return 1;
    }
    return 0;
}

static int villager_has_enough_items(
        const GmMobLive *m, int slot, int multiplier) {
    int farmer = m->villager_profession[slot] == 0;
    for (int i = 0; i < 8; ++i) {
        const ICStack *stack = &m->villager_inventory[slot][i];
        if (stack->count <= 0) continue;
        if ((stack->item == 297 && stack->count >= 3 * multiplier)
                || (stack->item == 392
                    && stack->count >= 12 * multiplier)
                || (stack->item == 391
                    && stack->count >= 12 * multiplier)
                || (stack->item == 434
                    && stack->count >= 12 * multiplier)
                || (farmer && stack->item == 296
                    && stack->count >= 9 * multiplier))
            return 1;
    }
    return 0;
}

static int villager_wants_more_food(const GmMobLive *m, int slot) {
    return !villager_has_enough_items(
        m, slot, m->villager_profession[slot] == 0 ? 5 : 1);
}

static int villager_crop_mature(int id, int meta) {
    return (id == 59 && meta == 7)
        || (id == 141 && meta == 7)
        || (id == 142 && meta == 7)
        || (id == 207 && meta == 3);
}

static int villager_harvest_candidate(
        GmMobLive *m, GmWorld *w, int slot, int x, int y, int z) {
    if (gm_world_block(w, x, y, z) != 60) return 0;
    int crop = gm_world_block(w, x, y + 1, z);
    int meta = gm_world_meta(w, x, y + 1, z);
    if (villager_crop_mature(crop, meta)
            && m->villager_harvest_wants_reap[slot]
            && (m->villager_harvest_current_task[slot] == 0
                || m->villager_harvest_current_task[slot] < 0)) {
        m->villager_harvest_current_task[slot] = 0;
        return 1;
    }
    if (crop == 0 && m->villager_harvest_has_item[slot]
            && (m->villager_harvest_current_task[slot] == 1
                || m->villager_harvest_current_task[slot] < 0)) {
        m->villager_harvest_current_task[slot] = 1;
        return 1;
    }
    return 0;
}

static int villager_harvest_search(
        GmMobLive *m, GmWorld *w, const EwStore *s,
        int slot) {
    int base_x = mc_floor(s->x[slot]);
    int base_y = mc_floor(s->y[slot]);
    int base_z = mc_floor(s->z[slot]);
    for (int k = 0; k <= 1; k = k > 0 ? -k : 1 - k)
        for (int distance = 0; distance < 16; ++distance)
            for (int dx = 0; dx <= distance;
                    dx = dx > 0 ? -dx : 1 - dx)
                for (int dz = dx < distance && dx > -distance
                            ? distance : 0;
                        dz <= distance;
                        dz = dz > 0 ? -dz : 1 - dz) {
                    int x = base_x + dx;
                    int y = base_y + k - 1;
                    int z = base_z + dz;
                    if (m->villager_home_valid[slot]) {
                        double hx = (double)m->villager_home_x[slot] - x;
                        double hy = (double)m->villager_home_y[slot] - y;
                        double hz = (double)m->villager_home_z[slot] - z;
                        double radius =
                            (double)m->villager_home_radius[slot];
                        if (hx * hx + hy * hy + hz * hz
                                >= radius * radius)
                            continue;
                    }
                    if (villager_harvest_candidate(
                            m, w, slot, x, y, z)) {
                        m->villager_harvest_x[slot] = x;
                        m->villager_harvest_y[slot] = y;
                        m->villager_harvest_z[slot] = z;
                        return 1;
                    }
                }
    return 0;
}

static int villager_seed_next_int(uint64_t *seed48, int bound) {
    JavaRandom random = {*seed48};
    int value = jrand_int_bound(&random, bound);
    *seed48 = random.seed;
    return value;
}

static float villager_seed_next_float(uint64_t *seed48) {
    JavaRandom random = {*seed48};
    float value = jrand_float(&random);
    *seed48 = random.seed;
    return value;
}

static int villager_spawn_crop_item(
        uint64_t *world_random_seed48, uint64_t *math_random_seed48,
        int *next_entity_id, GmLiveSim *drops,
        int x, int y, int z, int item) {
    if (!world_random_seed48 || !math_random_seed48 || !next_entity_id
            || !drops || !mob_live_reserve_item_slots(drops, 1)
            || *next_entity_id <= 0 || *next_entity_id == INT_MAX)
        return 0;
    (void)villager_seed_next_float(world_random_seed48);
    double spawn_x = (double)x
        + (double)(villager_seed_next_float(world_random_seed48) * 0.5F)
        + 0.25D;
    double spawn_y = (double)y
        + (double)(villager_seed_next_float(world_random_seed48) * 0.5F)
        + 0.25D;
    double spawn_z = (double)z
        + (double)(villager_seed_next_float(world_random_seed48) * 0.5F)
        + 0.25D;
    float hover = (float)(mob_math_random_next_double(math_random_seed48)
        * (MC_PI * 2.0));
    float yaw = (float)(mob_math_random_next_double(math_random_seed48)
        * 360.0);
    double motion_x = (double)(float)(
        mob_math_random_next_double(math_random_seed48)
            * 0.20000000298023224 - 0.10000000149011612);
    double motion_z = (double)(float)(
        mob_math_random_next_double(math_random_seed48)
            * 0.20000000298023224 - 0.10000000149011612);
    int eid = (*next_entity_id)++;
    return gm_live_spawn_item_exact_hover(
        drops, eid, spawn_x, spawn_y, spawn_z,
        motion_x, 0.20000000298023224, motion_z, yaw, hover,
        item, 1, 0, 0, 10, 0);
}

static void villager_destroy_mature_crop(
        GmMobLive *m, GmWorld *w, const EwStore *s, int slot,
        uint64_t *world_random_seed48, uint64_t *math_random_seed48,
        int *next_entity_id, GmLiveSim *drops) {
    int x = m->villager_harvest_x[slot];
    int y = m->villager_harvest_y[slot] + 1;
    int z = m->villager_harvest_z[slot];
    int id = gm_world_block(w, x, y, z);
    int meta = gm_world_meta(w, x, y, z);
    if (!villager_crop_mature(id, meta)) return;
    int base_item = id == 59 ? 296 : id == 141 ? 391
        : id == 142 ? 392 : 434;
    int seed_item = id == 59 ? 295 : id == 207 ? 435 : base_item;
    int bonus_bound = id == 207 ? 6 : 14;
    int mature_age = id == 207 ? 3 : 7;
    int bonus = 0;
    for (int draw = 0; draw < 3; ++draw)
        if (villager_seed_next_int(
                world_random_seed48, bonus_bound) <= mature_age)
            ++bonus;
    int poison = id == 142 && m->active_block_random_seed48
        && villager_seed_next_int(m->active_block_random_seed48, 50) == 0;
    gm_world_set_block_meta(w, x, y, z, 0, 0);
    mob_event_append(
        m, GM_MOB_EVENT_WORLD_EVENT, s->id[slot], 2001,
        (double)x, (double)y, (double)z,
        (float)(id | ((meta & 15) << 12)), 0.0F);
    (void)villager_spawn_crop_item(
        world_random_seed48, math_random_seed48, next_entity_id,
        drops, x, y, z, base_item);
    for (int stack = 0; stack < bonus; ++stack)
        (void)villager_spawn_crop_item(
            world_random_seed48, math_random_seed48, next_entity_id,
            drops, x, y, z, seed_item);
    if (poison)
        (void)villager_spawn_crop_item(
            world_random_seed48, math_random_seed48, next_entity_id,
            drops, x, y, z, 394);
}

static int villager_harvest_continue(
        GmMobLive *m, GmWorld *w, int slot) {
    return m->villager_harvest_current_task[slot] >= 0
        && m->villager_harvest_timeout[slot]
            >= -m->villager_harvest_max_stay[slot]
        && m->villager_harvest_timeout[slot] <= 1200
        && villager_harvest_candidate(
            m, w, slot,
            m->villager_harvest_x[slot],
            m->villager_harvest_y[slot],
            m->villager_harvest_z[slot]);
}

static int villager_harvest_tick(
        GmMobLive *m, GmWorld *w, EwStore *s,
        int slot, int setup_tick, int mob_griefing,
        uint64_t *world_random_seed48, uint64_t *math_random_seed48,
        int *next_entity_id, GmLiveSim *drops) {
    if (m->villager_harvest_active[slot]
            && !villager_harvest_continue(m, w, slot))
        m->villager_harvest_active[slot] = 0;
    if (!m->villager_harvest_active[slot] && setup_tick) {
        if (m->villager_harvest_run_delay[slot] <= 0) {
            if (!mob_griefing) return 0;
            m->villager_harvest_current_task[slot] = -1;
            m->villager_harvest_has_item[slot] =
                villager_has_farm_item(m, slot);
            m->villager_harvest_wants_reap[slot] =
                villager_wants_more_food(m, slot);
        }
        if (m->villager_harvest_run_delay[slot] > 0) {
            --m->villager_harvest_run_delay[slot];
            return 0;
        }
        m->villager_harvest_run_delay[slot] = 200
            + jrand_int_bound(&m->entity_random[slot].random, 200);
        if (!villager_harvest_search(m, w, s, slot)) return 0;
        m->villager_harvest_active[slot] = 1;
        s->path_tx[slot] =
            (double)((float)m->villager_harvest_x[slot]) + 0.5D;
        s->path_ty[slot] =
            (double)(m->villager_harvest_y[slot] + 1);
        s->path_tz[slot] =
            (double)((float)m->villager_harvest_z[slot]) + 0.5D;
        s->path_len[slot] = 1;
        m->villager_harvest_timeout[slot] = 0;
        int inner = jrand_int_bound(
            &m->entity_random[slot].random, 1200) + 1200;
        m->villager_harvest_max_stay[slot] =
            jrand_int_bound(&m->entity_random[slot].random, inner) + 1200;
    }
    if (!m->villager_harvest_active[slot]) return 0;
    double dx = s->x[slot]
        - ((double)m->villager_harvest_x[slot] + 0.5D);
    double dy = s->y[slot]
        - ((double)m->villager_harvest_y[slot] + 1.5D);
    double dz = s->z[slot]
        - ((double)m->villager_harvest_z[slot] + 0.5D);
    if (dx * dx + dy * dy + dz * dz > 1.0D) {
        m->villager_harvest_above[slot] = 0;
        ++m->villager_harvest_timeout[slot];
        if (m->villager_harvest_timeout[slot] % 40 == 0) {
            s->path_tx[slot] =
                (double)((float)m->villager_harvest_x[slot]) + 0.5D;
            s->path_ty[slot] =
                (double)(m->villager_harvest_y[slot] + 1);
            s->path_tz[slot] =
                (double)((float)m->villager_harvest_z[slot]) + 0.5D;
            s->path_len[slot] = 1;
        }
    } else {
        m->villager_harvest_above[slot] = 1;
        --m->villager_harvest_timeout[slot];
    }
    if (m->villager_harvest_above[slot]) {
        int crop_y = m->villager_harvest_y[slot] + 1;
        if (m->villager_harvest_current_task[slot] == 0) {
            villager_destroy_mature_crop(
                m, w, s, slot, world_random_seed48,
                math_random_seed48, next_entity_id, drops);
        } else if (m->villager_harvest_current_task[slot] == 1
                && gm_world_block(
                    w, m->villager_harvest_x[slot], crop_y,
                    m->villager_harvest_z[slot]) == 0) {
            for (int inventory_slot = 0;
                    inventory_slot < 8; ++inventory_slot) {
                ICStack *stack =
                    &m->villager_inventory[slot][inventory_slot];
                int block = stack->item == 295 ? 59
                    : stack->item == 392 ? 142
                    : stack->item == 391 ? 141
                    : stack->item == 435 ? 207 : 0;
                if (!block || stack->count <= 0) continue;
                gm_world_set_block_meta(
                    w, m->villager_harvest_x[slot], crop_y,
                    m->villager_harvest_z[slot], block, 0);
                --stack->count;
                if (stack->count <= 0) *stack = ic_empty();
                break;
            }
        }
        m->villager_harvest_current_task[slot] = -1;
        m->villager_harvest_run_delay[slot] = 10;
    }
    return 1;
}

int gm_mobs_villager_harvest_task(
        GmMobLive *m, GmWorld *world, int eid,
        int setup_tick, int mob_griefing) {
    uint64_t world_seed = 0, math_seed = 0;
    uint64_t block_seed = 0;
    int next_id = m ? m->next_id : 1;
    GmLiveSim drops;
    memset(&drops, 0, sizeof drops);
    return gm_mobs_villager_harvest_task_exact(
        m, world, eid, setup_tick, mob_griefing,
        &world_seed, &block_seed, &math_seed, &next_id, &drops);
}

int gm_mobs_villager_harvest_task_exact(
        GmMobLive *m, GmWorld *world, int eid,
        int setup_tick, int mob_griefing,
        uint64_t *world_random_seed48, uint64_t *block_random_seed48,
        uint64_t *math_random_seed48, int *next_entity_id,
        GmLiveSim *drops) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || !world
            || s->type[slot] != EW_TYPE_VILLAGER
            || (setup_tick != 0 && setup_tick != 1)
            || (mob_griefing != 0 && mob_griefing != 1)
            || !world_random_seed48 || !block_random_seed48
            || !math_random_seed48 || !next_entity_id || !drops)
        return 0;
    uint64_t *saved_block_random = m->active_block_random_seed48;
    m->active_block_random_seed48 = block_random_seed48;
    int active = villager_harvest_tick(
        m, world, s, slot, setup_tick, mob_griefing,
        world_random_seed48, math_random_seed48, next_entity_id, drops);
    m->active_block_random_seed48 = saved_block_random;
    ew_store_copy(next_store(m), s);
    return active;
}

static int villager_interact_nearest(
        const GmMobLive *m, const EwStore *s,
        int self, int dimension) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)s;
    double self_width, self_height;
    double best = HUGE_VAL;
    int selected_eid = -1;
    living_entity_size(m, s, self, &self_width, &self_height);
    double min_x = s->x[self] - self_width * 0.5D - 3.0D;
    double max_x = s->x[self] + self_width * 0.5D + 3.0D;
    double min_y = s->y[self] - 3.0D;
    double max_y = s->y[self] + self_height + 3.0D;
    double min_z = s->z[self] - self_width * 0.5D - 3.0D;
    double max_z = s->z[self] + self_width * 0.5D + 3.0D;
    for (int order = 0; order < m->loaded_order_count; ++order) {
        const GmMobLoadedRef *ref = loaded_ref_at_const(m, order);
        int slot = living_loaded_ref_stage_secondary(
            mutable_m, ref, completed);
        if (slot <= 0 || s->id[slot] == s->id[self]
                || s->type[slot] != EW_TYPE_VILLAGER
                || m->entity_dimension[slot] != dimension
                || m->entity_dead[slot] || s->health[slot] <= 0.0F)
            continue;
        double width, height;
        living_entity_size(m, s, slot, &width, &height);
        if (!(s->x[slot] + width * 0.5D > min_x
                && s->x[slot] - width * 0.5D < max_x
                && s->y[slot] + height > min_y && s->y[slot] < max_y
                && s->z[slot] + width * 0.5D > min_z
                && s->z[slot] - width * 0.5D < max_z))
            continue;
        double dx = s->x[slot] - s->x[self];
        double dy = s->y[slot] - s->y[self];
        double dz = s->z[slot] - s->z[self];
        double distance = dx * dx + dy * dy + dz * dz;
        if (distance <= best) {
            best = distance;
            selected_eid = s->id[slot];
        }
    }
    return mob_slot_by_eid(m, selected_eid);
}

static void villager_look_position(
        GmMobLive *m, const EwStore *s, int self,
        double target_x, double target_y, double target_z) {
    double dx = target_x - s->x[self];
    double dz = target_z - s->z[self];
    double self_eye = (double)(m->growing_age[self] < 0 ? 0.81F : 1.62F);
    double dy = target_y - (s->y[self] + self_eye);
    double horizontal = sqrt(dx * dx + dz * dz);
    float target_yaw = (float)(atan2(dz, dx) * (180.0D / MC_PI)) - 90.0F;
    float target_pitch = (float)(-atan2(dy, horizontal)
        * (180.0D / MC_PI));
    m->passive_head_yaw[self] = living_update_rotation_exact(
        m->passive_head_yaw[self], target_yaw, 10.0F);
    m->passive_head_pitch[self] = living_update_rotation_exact(
        m->passive_head_pitch[self], target_pitch, 40.0F);
}

static double villager_target_eye_height(
        const GmMobLive *m, const EwStore *s, int target) {
    if (s->type[target] == EW_TYPE_VILLAGER)
        return (double)(m->growing_age[target] < 0 ? 0.81F : 1.62F);
    double width, height;
    living_entity_size(m, s, target, &width, &height);
    (void)width;
    return (double)((float)height * 0.85F);
}

static void villager_look_at(
        GmMobLive *m, const EwStore *s, int self, int target) {
    villager_look_position(
        m, s, self, s->x[target],
        s->y[target] + villager_target_eye_height(m, s, target),
        s->z[target]);
}

static int villager_share_item(
        GmMobLive *m, const EwStore *s, int slot,
        const McSinTable *sin_table, uint64_t *math_random_seed48,
        int *next_entity_id, GmLiveSim *drops) {
    int output_item = 0, output_count = 0, output_meta = 0;
    int inventory_slot = -1, consumed = 0;
    for (int i = 0; i < 8; ++i) {
        ICStack *stack = &m->villager_inventory[slot][i];
        if (stack->count <= 0) continue;
        if ((stack->item == 297 || stack->item == 392
                || stack->item == 391 || stack->item == 434)
                && stack->count > 3) {
            output_item = stack->item;
            output_count = stack->count / 2;
            output_meta = stack->meta;
            consumed = output_count;
            inventory_slot = i;
        } else if (stack->item == 296 && stack->count > 5) {
            consumed = stack->count / 2 / 3 * 3;
            output_item = 297;
            output_count = consumed / 3;
            inventory_slot = i;
        }
        if (output_count > 0) break;
    }
    if (inventory_slot < 0) return 0;
    if (!sin_table || !math_random_seed48 || !next_entity_id || !drops
            || *next_entity_id <= 0 || *next_entity_id >= INT_MAX
            || !mob_live_reserve_item_slots(drops, 1))
        return -1;
    ICStack *source = &m->villager_inventory[slot][inventory_slot];
    source->count -= consumed;
    if (source->count <= 0) *source = ic_empty();
    int item_eid = (*next_entity_id)++;
    float hover = (float)(mob_math_random_next_double(math_random_seed48)
        * (MC_PI * 2.0));
    float yaw = (float)(mob_math_random_next_double(math_random_seed48)
        * 360.0D);
    (void)mob_math_random_next_double(math_random_seed48);
    (void)mob_math_random_next_double(math_random_seed48);
    float head_yaw = m->passive_head_yaw[slot] * 0.017453292F;
    float pitch = m->passive_head_pitch[slot] * 0.017453292F;
    float speed = 0.3F;
    double motion_x = (double)(
        -mc_sin(sin_table, head_yaw) * mc_cos(sin_table, pitch) * speed);
    double motion_z = (double)(
        mc_cos(sin_table, head_yaw) * mc_cos(sin_table, pitch) * speed);
    double motion_y = (double)(-mc_sin(sin_table, pitch) * speed + 0.1F);
    double eye = (double)(m->growing_age[slot] < 0 ? 0.81F : 1.62F);
    if (!gm_live_spawn_item_exact_hover(
            drops, item_eid, s->x[slot],
            s->y[slot] - 0.30000001192092896D + eye, s->z[slot],
            motion_x, motion_y, motion_z, yaw, hover,
            output_item, output_count, output_meta, 0, 10, 0))
        return -1;
    if (m->next_id <= item_eid) m->next_id = item_eid + 1;
    if (m->next_orb_id <= item_eid) m->next_orb_id = item_eid + 1;
    return 1;
}

static int villager_interact_tick(
        GmMobLive *m, EwStore *s, int slot, int dimension, int setup_tick,
        const McSinTable *sin_table, uint64_t *math_random_seed48,
        int *next_entity_id, GmLiveSim *drops) {
    int target = iron_golem_slot_by_eid(
        m, s, m->villager_interact_target_eid[slot]);
    if (m->villager_interact_active[slot]) {
        double distance = target > 0
            ? (s->x[target] - s->x[slot]) * (s->x[target] - s->x[slot])
                + (s->y[target] - s->y[slot])
                    * (s->y[target] - s->y[slot])
                + (s->z[target] - s->z[slot])
                    * (s->z[target] - s->z[slot])
            : HUGE_VAL;
        if (target <= 0 || !s->alive[target]
                || s->type[target] != EW_TYPE_VILLAGER
                || m->entity_dimension[target] != dimension
                || s->health[target] <= 0.0F || distance > 9.0D
                || m->villager_interact_look_time[slot] <= 0) {
            m->villager_interact_active[slot] = 0;
            m->villager_interact_target_eid[slot] = -1;
            m->villager_interact_look_time[slot] = 0;
            m->villager_interaction_delay[slot] = 0;
            target = -1;
        }
    }
    if (!m->villager_interact_active[slot] && setup_tick
            && jrand_float(&m->entity_random[slot].random) < 0.02F) {
        target = villager_interact_nearest(m, s, slot, dimension);
        if (target > 0) {
            m->villager_interact_active[slot] = 1;
            m->villager_interact_target_eid[slot] = s->id[target];
            m->villager_interact_look_time[slot] = 40
                + jrand_int_bound(&m->entity_random[slot].random, 40);
            m->villager_interaction_delay[slot] =
                villager_has_enough_items(m, slot, 2)
                    && villager_wants_more_food(m, target) ? 10 : 0;
        }
    }
    if (!m->villager_interact_active[slot]) return 0;
    --m->villager_interact_look_time[slot];
    if (m->villager_interaction_delay[slot] > 0
            && --m->villager_interaction_delay[slot] == 0)
        (void)villager_share_item(
            m, s, slot, sin_table, math_random_seed48,
            next_entity_id, drops);
    villager_look_at(m, s, slot, target);
    return 1;
}

static void villager_interact_reset(GmMobLive *m, int slot) {
    m->villager_interact_active[slot] = 0;
    m->villager_interact_target_eid[slot] = -1;
    m->villager_interact_look_time[slot] = 0;
    m->villager_interaction_delay[slot] = 0;
}

int gm_mobs_villager_interact_task_exact(
        GmMobLive *m, int eid, int setup_tick,
        const McSinTable *sin_table, uint64_t *math_random_seed48,
        int *next_entity_id, GmLiveSim *drops) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_VILLAGER
            || (setup_tick != 0 && setup_tick != 1)
            || !sin_table || !math_random_seed48
            || !next_entity_id || !drops)
        return 0;
    int active = villager_interact_tick(
        m, s, slot, m->entity_dimension[slot], setup_tick,
        sin_table, math_random_seed48, next_entity_id, drops);
    ew_store_copy(next_store(m), s);
    return active;
}

void gm_mobs_set_active_villager_customer(GmMobLive *m, int eid) {
    if (m) m->active_villager_customer_eid = eid > 0 ? eid : -1;
}

int gm_mobs_active_villager_customer(const GmMobLive *m) {
    return m ? m->active_villager_customer_eid : -1;
}

static int villager_player_distance_valid(
        const EwStore *s, int slot, double px, double py, double pz,
        double distance_sq) {
    double dx = px - s->x[slot];
    double dy = py - s->y[slot];
    double dz = pz - s->z[slot];
    return dx * dx + dy * dy + dz * dz <= distance_sq;
}

static int villager_trade_tick(
        GmMobLive *m, EwStore *s, int slot, int setup_tick,
        int player_alive, double px, double py, double pz) {
    int customer = m->active_villager_customer_eid == s->id[slot];
    int valid = s->alive[slot] && s->health[slot] > 0.0F
        && !m->entity_in_water[slot] && s->on_ground[slot]
        && customer && player_alive
        && villager_player_distance_valid(s, slot, px, py, pz, 16.0D);
    if (m->villager_trade_active[slot] && !valid) {
        m->villager_trade_active[slot] = 0;
        if (customer) m->active_villager_customer_eid = -1;
    }
    if (!m->villager_trade_active[slot] && setup_tick && valid) {
        m->villager_trade_active[slot] = 1;
        s->path_len[slot] = 0;
    }
    return m->villager_trade_active[slot] != 0;
}

static int villager_trade_look_tick(
        GmMobLive *m, const EwStore *s, int slot, int setup_tick,
        int player_alive, double px, double py, double pz) {
    if (m->villager_trade_look_active[slot]
            && (!player_alive
                || !villager_player_distance_valid(
                    s, slot, px, py, pz, 64.0D)
                || m->villager_trade_look_time[slot] <= 0)) {
        m->villager_trade_look_active[slot] = 0;
        m->villager_trade_look_time[slot] = 0;
    }
    if (!m->villager_trade_look_active[slot] && setup_tick
            && m->active_villager_customer_eid == s->id[slot]) {
        m->villager_trade_look_active[slot] = 1;
        m->villager_trade_look_time[slot] = 40
            + jrand_int_bound(&m->entity_random[slot].random, 40);
    }
    if (!m->villager_trade_look_active[slot]) return 0;
    villager_look_position(
        m, s, slot, px, py + (double)PSV_EYE_HEIGHT, pz);
    --m->villager_trade_look_time[slot];
    return 1;
}

static int villager_watch_player_tick(
        GmMobLive *m, const EwStore *s, int slot, int setup_tick,
        int can_start, int player_alive,
        double px, double py, double pz) {
    if (m->villager_watch_player_active[slot]
            && (!player_alive
                || !villager_player_distance_valid(
                    s, slot, px, py, pz, 9.0D)
                || m->villager_watch_player_time[slot] <= 0)) {
        m->villager_watch_player_active[slot] = 0;
        m->villager_watch_player_time[slot] = 0;
    }
    if (!m->villager_watch_player_active[slot]
            && setup_tick && can_start
            && jrand_float(&m->entity_random[slot].random) < 1.0F
            && player_alive
            && villager_player_distance_valid(
                s, slot, px, py, pz, 9.0D)) {
        m->villager_watch_player_active[slot] = 1;
        m->villager_watch_player_time[slot] = 40
            + jrand_int_bound(&m->entity_random[slot].random, 40);
    }
    if (!m->villager_watch_player_active[slot]) return 0;
    villager_look_position(
        m, s, slot, px, py + (double)PSV_EYE_HEIGHT, pz);
    --m->villager_watch_player_time[slot];
    return 1;
}

static int villager_nearest_living(
        const GmMobLive *m, const EwStore *s,
        int self, int dimension) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)s;
    double self_width, self_height;
    double best = HUGE_VAL;
    int selected_eid = -1;
    living_entity_size(m, s, self, &self_width, &self_height);
    double min_x = s->x[self] - self_width * 0.5D - 8.0D;
    double max_x = s->x[self] + self_width * 0.5D + 8.0D;
    double min_y = s->y[self] - 3.0D;
    double max_y = s->y[self] + self_height + 3.0D;
    double min_z = s->z[self] - self_width * 0.5D - 8.0D;
    double max_z = s->z[self] + self_width * 0.5D + 8.0D;
    for (int order = 0; order < m->loaded_order_count; ++order) {
        const GmMobLoadedRef *ref = loaded_ref_at_const(m, order);
        int target = living_loaded_ref_stage_secondary(
            mutable_m, ref, completed);
        if (target <= 0 || s->id[target] == s->id[self]
                || !gm_living(s->type[target])
                || m->entity_dimension[target] != dimension
                || m->entity_dead[target] || s->health[target] <= 0.0F)
            continue;
        double width, height;
        living_entity_size(m, s, target, &width, &height);
        if (!(s->x[target] + width * 0.5D > min_x
                && s->x[target] - width * 0.5D < max_x
                && s->y[target] + height > min_y && s->y[target] < max_y
                && s->z[target] + width * 0.5D > min_z
                && s->z[target] - width * 0.5D < max_z))
            continue;
        double dx = s->x[target] - s->x[self];
        double dy = s->y[target] - s->y[self];
        double dz = s->z[target] - s->z[self];
        double distance = dx * dx + dy * dy + dz * dz;
        if (distance <= best) {
            best = distance;
            selected_eid = s->id[target];
        }
    }
    return mob_slot_by_eid(m, selected_eid);
}

static void villager_watch_living_reset(GmMobLive *m, int slot) {
    m->villager_watch_living_active[slot] = 0;
    m->villager_watch_living_target_eid[slot] = -1;
    m->villager_watch_living_time[slot] = 0;
}

static int villager_watch_living_tick(
        GmMobLive *m, const EwStore *s, int slot, int dimension,
        int setup_tick, int can_start) {
    int target = iron_golem_slot_by_eid(
        m, s, m->villager_watch_living_target_eid[slot]);
    if (m->villager_watch_living_active[slot]) {
        double distance = target > 0
            ? (s->x[target] - s->x[slot]) * (s->x[target] - s->x[slot])
                + (s->y[target] - s->y[slot])
                    * (s->y[target] - s->y[slot])
                + (s->z[target] - s->z[slot])
                    * (s->z[target] - s->z[slot])
            : HUGE_VAL;
        if (target <= 0 || !s->alive[target]
                || m->entity_dimension[target] != dimension
                || s->health[target] <= 0.0F || distance > 64.0D
                || m->villager_watch_living_time[slot] <= 0) {
            villager_watch_living_reset(m, slot);
            target = -1;
        }
    }
    if (!m->villager_watch_living_active[slot]
            && setup_tick && can_start
            && jrand_float(&m->entity_random[slot].random) < 0.02F) {
        target = villager_nearest_living(m, s, slot, dimension);
        if (target > 0) {
            m->villager_watch_living_active[slot] = 1;
            m->villager_watch_living_target_eid[slot] = s->id[target];
            m->villager_watch_living_time[slot] = 40
                + jrand_int_bound(&m->entity_random[slot].random, 40);
        }
    }
    if (!m->villager_watch_living_active[slot]) return 0;
    villager_look_at(m, s, slot, target);
    --m->villager_watch_living_time[slot];
    return 1;
}

static int villager_wander_tick(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot,
        int setup_tick, int can_start) {
    if (m->villager_wander_active[slot] && s->path_len[slot] == 0)
        m->villager_wander_active[slot] = 0;
    if (!m->villager_wander_active[slot]
            && setup_tick && can_start && m->entity_age[slot] < 100
            && jrand_int_bound(&m->entity_random[slot].random, 120) == 0) {
        double x, y, z;
        int found;
        if (m->entity_in_water[slot]) {
            found = villager_random_target_towards(
                m, w, s, slot, 15, 7, 0, 1, 0.0D, 0.0D,
                &x, &y, &z);
            if (!found)
                found = villager_random_target_towards(
                    m, w, s, slot, 10, 7, 0, 0, 0.0D, 0.0D,
                    &x, &y, &z);
        } else if (jrand_float(
                &m->entity_random[slot].random) >= 0.001F) {
            found = villager_random_target_towards(
                m, w, s, slot, 10, 7, 0, 1, 0.0D, 0.0D,
                &x, &y, &z);
        } else {
            found = villager_random_target_towards(
                m, w, s, slot, 10, 7, 0, 0, 0.0D, 0.0D,
                &x, &y, &z);
        }
        if (found) {
            m->villager_wander_active[slot] = 1;
            s->path_tx[slot] = x;
            s->path_ty[slot] = y;
            s->path_tz[slot] = z;
            s->path_len[slot] = 1;
            m->passive_nav_speed[slot] = 0.6D;
        }
    }
    return m->villager_wander_active[slot] != 0;
}

static void villager_reset_mate(GmMobLive *m, int slot) {
    m->villager_mate_active[slot] = 0;
    m->villager_mating[slot] = 0;
    m->villager_mate_eid[slot] = -1;
    m->villager_mating_timeout[slot] = 0;
}

static int villager_breed_slots(
        GmMobLive *m, EwStore *s, int self, int mate,
        uint64_t *world_random_seed48,
        uint64_t *math_random_seed48, int *next_entity_id,
        int *child_slot_out) {
    JavaRandom world_random;
    GmVillagerTrade child_trade;
    int child_eid, child_slot, profession, child_is_cold = 0;
    int dimension;
    double child_x, child_y, child_z;
    if (child_slot_out) *child_slot_out = -1;
    if (!m || !s || self <= 0 || mate <= 0 || self == mate
            || !s->alive[self] || !s->alive[mate]
            || s->type[self] != EW_TYPE_VILLAGER
            || s->type[mate] != EW_TYPE_VILLAGER
            || !world_random_seed48 || !math_random_seed48
            || !next_entity_id || *next_entity_id <= 0
            || *next_entity_id == INT_MAX
            || m->villager_birth_count >= EW_MAX_ENTITIES)
        return 0;
    if (*next_entity_id < m->next_id)
        *next_entity_id = m->next_id;
    child_eid = (*next_entity_id)++;
    if (m->next_id <= child_eid) m->next_id = child_eid + 1;
    if (m->next_orb_id <= child_eid) m->next_orb_id = child_eid + 1;
    (void)mob_math_random_next_double(math_random_seed48);
    (void)mob_math_random_next_double(math_random_seed48);
    (void)mob_math_random_next_double(math_random_seed48);
    jrand_set_seed48(&world_random, *world_random_seed48);
    profession = jrand_int_bound(&world_random, 6);
    *world_random_seed48 = world_random.seed;
    child_x = s->x[self];
    child_y = s->y[self];
    child_z = s->z[self];
    dimension = m->entity_dimension[self];

    child_slot = living_spawn_slot(
        m, s, EW_TYPE_VILLAGER, child_eid,
        child_x, child_y, child_z,
        max_health(EW_TYPE_VILLAGER, 1), &child_is_cold);
    if (child_slot < 0) return 0;
    m->entity_dimension[child_slot] = (signed char)dimension;
    m->size[child_slot] = 1;
    reset_slot_state_s(m, s, child_slot);
    s->on_ground[child_slot] = 0;
    if (m->animal_child_state_count > 0) {
        int random_index = m->animal_child_state_head;
        m->entity_random[child_slot] =
            m->animal_child_random_queue[random_index];
        m->animal_child_state_head = (unsigned char)(
            (random_index + 1) % EW_MAX_ENTITIES);
        --m->animal_child_state_count;
    }
    m->villager_profession[child_slot] = (unsigned char)profession;
    gm_villager_trade_init(
        &child_trade, profession,
        &m->entity_random[child_slot].random);
    m->growing_age[child_slot] = -24000;
    s->yaw[child_slot] = 0.0F;
    child_slot = living_spawn_finish(
        m, s, child_slot, child_is_cold, 0);
    if (child_slot < 0) return 0;

    m->growing_age[self] = 6000;
    m->growing_age[mate] = 6000;
    m->villager_willing[self] = 0;
    m->villager_willing[mate] = 0;
    GmVillagerBirth *birth =
        &m->villager_births[m->villager_birth_count++];
    *birth = (GmVillagerBirth){
        .eid = child_eid,
        .profession = profession,
        .x = child_x, .y = child_y, .z = child_z,
        .trade = child_trade
    };
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, child_eid, 12,
        child_x, child_y, child_z, 0.0F, 0.0F);
    if (child_slot_out) *child_slot_out = child_slot;
    return 1;
}

int gm_mobs_villager_mate_start(GmMobLive *m, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    int mate;
    if (slot <= 0 || !s || !s->alive[slot]
            || s->type[slot] != EW_TYPE_VILLAGER
            || m->growing_age[slot] != 0
            || jrand_int_bound(
                &m->entity_random[slot].random, 500) != 0
            || !villager_sufficient_doors(m, slot)
            || !villager_update_willing(m, s, slot, 1))
        return 0;
    mate = villager_nearest_mate_slot(
        m, s, slot, m->entity_dimension[slot]);
    if (mate <= 0 || m->growing_age[mate] != 0
            || !villager_update_willing(m, s, mate, 1))
        return 0;
    m->villager_mate_active[slot] = 1;
    m->villager_mating[slot] = 1;
    m->villager_mate_eid[slot] = s->id[mate];
    m->villager_mating_timeout[slot] = 300;
    return 1;
}

int gm_mobs_villager_mate_update(
        GmMobLive *m, int eid, uint64_t *world_random_seed48,
        uint64_t *math_random_seed48, int *next_entity_id) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    int mate, born = 0;
    if (slot <= 0 || !s || !s->alive[slot]
            || s->type[slot] != EW_TYPE_VILLAGER
            || !m->villager_mate_active[slot])
        return 0;
    mate = iron_golem_slot_by_eid(m, s, m->villager_mate_eid[slot]);
    if (mate <= 0 || !s->alive[mate]
            || s->type[mate] != EW_TYPE_VILLAGER
            || m->villager_mating_timeout[slot] < 0
            || !villager_sufficient_doors(m, slot)
            || m->growing_age[slot] != 0
            || !m->villager_willing[slot]) {
        villager_reset_mate(m, slot);
        return 0;
    }
    --m->villager_mating_timeout[slot];
    double dx = s->x[mate] - s->x[slot];
    double dy = s->y[mate] - s->y[slot];
    double dz = s->z[mate] - s->z[slot];
    if (dx * dx + dy * dy + dz * dz <= 2.25D
            && m->villager_mating_timeout[slot] == 0
            && m->villager_mating[mate]) {
        int child_slot = -1;
        born = villager_breed_slots(
            m, s, slot, mate, world_random_seed48,
            math_random_seed48, next_entity_id, &child_slot);
        (void)child_slot;
    }
    if (jrand_int_bound(&m->entity_random[slot].random, 35) == 0)
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 12,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    ew_store_copy(next_store(m), s);
    return born ? 2 : 1;
}

/* The push portion of EntityLivingBase.collideWithNearbyEntities followed by
 * Entity.applyEntityCollision. maxEntityCramming damage remains a separate
 * unrepresented boundary. */
static void collide_living_entities(
        GmMobLive *m, EwStore *s, int self, int dimension) {
    double self_width, self_height;
    living_entity_size(m, s, self, &self_width, &self_height);
    double self_half = self_width * 0.5;
    double self_min_x = s->x[self] - self_half;
    double self_max_x = s->x[self] + self_half;
    double self_min_y = s->y[self];
    double self_max_y = s->y[self] + self_height;
    double self_min_z = s->z[self] - self_half;
    double self_max_z = s->z[self] + self_half;

    int cursor = 0;
    int other;
    while ((other = living_next_slot_from_store(m, s, &cursor)) > 0) {
        if (other == self || !s->alive[other]
                || m->entity_dimension[other] != dimension
                || !gm_living(s->type[other])
                || m->entity_dead[other] || s->health[other] <= 0.0F)
            continue;
        if (m->skeleton_trap_vehicle_eid[self] == s->id[other]
                || m->skeleton_trap_rider_eid[self] == s->id[other]
                || m->skeleton_trap_vehicle_eid[other] == s->id[self]
                || m->skeleton_trap_rider_eid[other] == s->id[self])
            continue;
        if (m->entity_vehicle_eid[self] == s->id[other]
                || m->entity_rider_eid[self] == s->id[other]
                || m->entity_vehicle_eid[other] == s->id[self]
                || m->entity_rider_eid[other] == s->id[self])
            continue;
        int other_being_ridden =
            m->skeleton_trap_rider_eid[other] >= 0
            || m->entity_rider_eid[other] >= 0
            || ride_is_slot(s, other, m->horse_ride_eid)
            || ride_is_slot(s, other, m->pig_ride_eid);
        /* EntitySelectors.getTeamCollisionPredicate rejects candidates whose
         * canBePushed() is false. AbstractHorse uniquely returns false while
         * ridden, so rider ticks do not push their occupied vehicles again. */
        if (gm_mobs_horse_type(s->type[other]) && other_being_ridden)
            continue;
        double other_width, other_height;
        living_entity_size(m, s, other, &other_width, &other_height);
        double other_half = other_width * 0.5;
        if (!(s->x[other] + other_half > self_min_x
                && s->x[other] - other_half < self_max_x
                && s->y[other] + other_height > self_min_y
                && s->y[other] < self_max_y
                && s->z[other] + other_half > self_min_z
                && s->z[other] - other_half < self_max_z))
            continue;

        if (s->type[self] == EW_TYPE_IRON_GOLEM
                && gm_hostile(s->type[other])
                && s->type[other] != EW_TYPE_CREEPER
                && s->type[other] != EW_TYPE_GHAST
                && jrand_int_bound(
                    &m->entity_random[self].random, 20) == 0) {
            m->golem_target_eid[self] = s->id[other];
            m->golem_target_player[self] = 0;
            m->golem_target_village_defense[self] = 0;
        }

        double dx = s->x[self] - s->x[other];
        double dz = s->z[self] - s->z[other];
        double magnitude = fmax(fabs(dx), fabs(dz));
        if (magnitude < 0.009999999776482582) continue;
        double root = (double)(float)sqrt(magnitude);
        dx /= root;
        dz /= root;
        double scale = 1.0 / root;
        if (scale > 1.0) scale = 1.0;
        dx *= scale;
        dz *= scale;
        dx *= 0.05000000074505806;
        dz *= 0.05000000074505806;
        int self_being_ridden =
            m->skeleton_trap_rider_eid[self] >= 0
            || m->entity_rider_eid[self] >= 0
            || ride_is_slot(s, self, m->horse_ride_eid)
            || ride_is_slot(s, self, m->pig_ride_eid);
        if (!other_being_ridden) {
            s->vx[other] -= dx;
            s->vz[other] -= dz;
        }
        if (!self_being_ridden) {
            s->vx[self] += dx;
            s->vz[self] += dz;
        }
    }
    living_cold_flush_one_from_store(
        m, s, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &m->living_staged_cold_secondary);
}

/* One player/mob pair from EntityLivingBase.collideWithNearbyEntities. The
 * query is symmetric, but a ridden horse is excluded only when it is a
 * candidate of the player's query. During the horse's own query the player
 * remains eligible and receives the push while the ridden horse does not. */
static void collide_living_with_player(
        GmMobLive *m, EwStore *s, int self, PsvPlayer *player,
        int ox, int oz, int player_query) {
    if (!m || !s || !player || self <= 0 || self >= EW_MAX_ENTITIES
            || !s->alive[self] || !gm_living(s->type[self])
            || m->entity_dead[self] || s->health[self] <= 0.0F)
        return;
    int current_being_ridden =
        m->skeleton_trap_rider_eid[self] >= 0
        || m->entity_rider_eid[self] >= 0
        || ride_is_slot(s, self, m->horse_ride_eid)
        || ride_is_slot(s, self, m->pig_ride_eid);
    if (ride_is_slot(s, self, m->horse_ride_eid)
            || ride_is_slot(s, self, m->pig_ride_eid))
        return;
    if (player_query && gm_mobs_horse_type(s->type[self])
            && current_being_ridden)
        return;

    double width, height;
    living_entity_size(m, s, self, &width, &height);
    double half = width * 0.5D;
    double min_x = s->x[self] - half;
    double max_x = s->x[self] + half;
    double min_y = s->y[self];
    double max_y = s->y[self] + height;
    double min_z = s->z[self] - half;
    double max_z = s->z[self] + half;
    if (m->entity_box_valid[self]) {
        min_x = m->entity_box_min_x[self];
        min_y = m->entity_box_min_y[self];
        min_z = m->entity_box_min_z[self];
        max_x = m->entity_box_max_x[self];
        max_y = m->entity_box_max_y[self];
        max_z = m->entity_box_max_z[self];
    }
    double player_min_x = player->ent.box.minX + (double)ox;
    double player_max_x = player->ent.box.maxX + (double)ox;
    double player_min_y = player->ent.box.minY;
    double player_max_y = player->ent.box.maxY;
    double player_min_z = player->ent.box.minZ + (double)oz;
    double player_max_z = player->ent.box.maxZ + (double)oz;
    if (!(max_x > player_min_x && min_x < player_max_x
            && max_y > player_min_y && min_y < player_max_y
            && max_z > player_min_z && min_z < player_max_z))
        return;

    double player_x = player->ent.posX + (double)ox;
    double player_z = player->ent.posZ + (double)oz;
    double dx = s->x[self] - player_x;
    double dz = s->z[self] - player_z;
    double magnitude = fmax(fabs(dx), fabs(dz));
    if (magnitude < 0.009999999776482582D) return;
    double root = (double)(float)sqrt(magnitude);
    dx /= root;
    dz /= root;
    double scale = 1.0D / root;
    if (scale > 1.0D) scale = 1.0D;
    dx *= scale;
    dz *= scale;
    dx *= 0.05000000074505806D;
    dz *= 0.05000000074505806D;
    player->ent.motionX -= dx;
    player->ent.motionZ -= dz;
    if (!current_being_ridden) {
        s->vx[self] += dx;
        s->vz[self] += dz;
    }
}

void gm_mobs_player_collision_query(
        GmMobLive *m, struct PsvPlayer *player_,
        int ox, int oz, int dimension) {
    if (!m || !player_) return;
    PsvPlayer *player = (PsvPlayer *)player_;
    EwStore *store = now_store(m);
    loaded_order_prepare(m);
    for (int order = 0; order < m->loaded_order_count; ++order) {
        GmMobLoadedRef ref = *loaded_ref_at(m, order);
        int slot = living_loaded_ref_stage(m, &ref, store);
        if (slot <= 0 || m->entity_dimension[slot] != dimension)
            continue;
        collide_living_with_player(
            m, store, slot, player, ox, oz, 1);
    }
    gm_mobs_living_cold_flush(m);
}

/* Target and goal selectors have independent three-tick clocks, both zero at
 * construction. Preserve their shared-random order for the mounted trap
 * skeletons, including a running WatchClosest task suppressing LookIdle. */
static void skeleton_trap_bow_reset(GmMobLive *m, EwStore *s, int slot) {
    m->skeleton_trap_bow_running[slot] = 0;
    m->skeleton_trap_hand_active[slot] = 0;
    m->skeleton_trap_item_use_count[slot] = 0;
    m->witch_see_time[slot] = 0;
    s->attack_time[slot] = -1;
}

static void skeleton_trap_bow_start_lower_rng(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot,
        double player_distance_sq) {
    JavaRandom *random = &m->entity_random[slot].random;
    if (jrand_int_bound(random, 120) == 0) {
        double x, y, z;
        int land = jrand_float(random) >= 0.001F;
        /* A successful priority-five wander suppresses both look tasks,
         * then the later priority-four bow task interrupts the wander. */
        if (animal_random_position_exact(
                m, w, s, slot, 10, 7, land, &x, &y, &z))
            return;
    }
    if (jrand_float(random) < 0.02F && player_distance_sq <= 64.0D) {
        (void)jrand_int_bound(random, 40);
        return;
    }
    if (jrand_float(random) < 0.02F) {
        (void)jrand_double(random);
        (void)jrand_int_bound(random, 20);
    }
}

/* EntityChicken.updatePassenger after a mounted living update. The rider's
 * own motion remains observable, but setPosition replaces its world pose and
 * bounding box from the already-ticked vehicle. */
static void chicken_jockey_update_passenger(
        GmMobLive *m, EwStore *s, const McSinTable *st, int rider) {
    int vehicle = mob_slot_by_eid(m, m->entity_vehicle_eid[rider]);
    if (vehicle <= 0 || s->type[vehicle] != EW_TYPE_CHICKEN
            || m->entity_rider_eid[vehicle] != s->id[rider]) {
        living_cold_flush_one_from_store(
            m, s, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
            &m->living_staged_cold_secondary);
        return;
    }
    float body = m->squid_render_yaw_offset[vehicle];
    float radians = body * 0.017453292F;
    s->x[rider] = s->x[vehicle]
        + (double)(0.1F * mc_sin(st, radians));
    s->y[rider] = s->y[vehicle] + (double)(0.7F * 0.5F);
    s->z[rider] = s->z[vehicle]
        - (double)(0.1F * mc_cos(st, radians));
    m->squid_render_yaw_offset[rider] = body;

    float width, height;
    ehs_size_scaled(s->type[rider], m->size[rider], &width, &height);
    if (gm_child_sized(s->type[rider]) && m->growing_age[rider] < 0) {
        width *= 0.5F;
        height *= 0.5F;
    }
    double half = (double)width * 0.5D;
    m->entity_box_min_x[rider] = s->x[rider] - half;
    m->entity_box_min_y[rider] = s->y[rider];
    m->entity_box_min_z[rider] = s->z[rider] - half;
    m->entity_box_max_x[rider] = s->x[rider] + half;
    m->entity_box_max_y[rider] = s->y[rider] + (double)height;
    m->entity_box_max_z[rider] = s->z[rider] + half;
    m->entity_box_valid[rider] = 1;
    living_cold_flush_one_from_store(
        m, s, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &m->living_staged_cold_secondary);
}

static int skeleton_trap_rider_ai_tick(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot,
        double player_x, double player_y, double player_z) {
    JavaRandom *random;
    double dx, dy, dz, distance_sq;
    int target_player, had_target, setup, wander_active;
    if (!m || !w || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || m->skeleton_trap_vehicle_eid[slot] < 0
            || s->type[slot] != EW_TYPE_SKELETON)
        return m && slot > 0 && slot < EW_MAX_ENTITIES
            ? m->skeleton_trap_target_player[slot] : 0;
    random = &m->entity_random[slot].random;
    dx = player_x - s->x[slot];
    dy = player_y - s->y[slot];
    dz = player_z - s->z[slot];
    distance_sq = dx * dx + dy * dy + dz * dz;
    had_target = m->skeleton_trap_target_eid[slot] >= 0;
    target_player = m->skeleton_trap_target_eid[slot] == 0;
    wander_active = (m->passive_tasks[slot] & PAI_BIT(PAI_WANDER))
        && s->path_len[slot] != 0;
    if (!wander_active)
        m->passive_tasks[slot] &= ~PAI_BIT(PAI_WANDER);
    setup = m->passive_task_tick[slot]++ % 3 == 0;

    /* EntityAIHurtByTarget starts before the running nearest-player target
     * is reset. On that selector boundary the later reset leaves no attack
     * target; continueExecuting restores the revenge target one tick later,
     * while the bow task cannot restart until its own next setup boundary. */
    if (m->skeleton_trap_revenge_eid[slot] > 0) {
        if (m->skeleton_trap_revenge_running[slot]) {
            if (m->skeleton_trap_target_eid[slot] < 0)
                m->skeleton_trap_target_eid[slot] =
                    m->skeleton_trap_revenge_eid[slot];
        } else if (setup) {
            m->skeleton_trap_revenge_running[slot] = 1;
            m->skeleton_trap_target_eid[slot] = -1;
            skeleton_trap_bow_reset(m, s, slot);
        }
        if (setup && m->skeleton_trap_target_eid[slot] > 0
                && !m->skeleton_trap_bow_running[slot]) {
            skeleton_trap_bow_start_lower_rng(
                m, w, s, slot, distance_sq);
            m->skeleton_trap_bow_running[slot] = 1;
        }
        m->skeleton_trap_target_player[slot] =
            m->skeleton_trap_target_eid[slot] == 0;
        m->passive_tasks[slot] &= ~PAI_BIT(PAI_WANDER);
        m->passive_watch_time[slot] = 0;
        m->passive_idle_time[slot] = -1;
        return m->skeleton_trap_target_eid[slot] >= 0;
    }

    if (m->passive_watch_time[slot] > 0
            && (distance_sq > 64.0D || s->health[slot] <= 0.0F))
        m->passive_watch_time[slot] = 0;
    if (!setup) {
        if (m->passive_watch_time[slot] > 0)
            --m->passive_watch_time[slot];
        if (m->passive_idle_time[slot] >= 0)
            --m->passive_idle_time[slot];
        return target_player;
    }

    if (!target_player) {
        target_player = jrand_int_bound(random, 10) == 0;
        if (!target_player) {
            /* Iron-golem selector chance gate, even with no candidate. */
            (void)jrand_int_bound(random, 10);
        } else if (distance_sq > 256.0D
                || !los_clear(
                    w, s->x[slot], s->y[slot] + 1.53D, s->z[slot],
                    player_x, player_y + PSV_EYE_HEIGHT, player_z)) {
            target_player = 0;
        }
    }

    /* A previously running bow task blocks all three lower mutex tasks. On
     * the acquisition boundary they are visited first in LinkedHash order,
     * then the later-added priority-four bow task interrupts them. */
    if (!had_target) {
        if (!wander_active && jrand_int_bound(random, 120) == 0) {
            double target_x = 0.0D;
            double target_y = 0.0D;
            double target_z = 0.0D;
            int found;
            if (m->entity_in_water[slot]) {
                found = animal_random_position_exact(
                    m, w, s, slot, 15, 7, 1,
                    &target_x, &target_y, &target_z);
                if (!found)
                    found = animal_random_position_exact(
                        m, w, s, slot, 10, 7, 0,
                        &target_x, &target_y, &target_z);
            } else {
                int land = jrand_float(random) >= 0.001F;
                found = animal_random_position_exact(
                    m, w, s, slot, 10, 7, land,
                    &target_x, &target_y, &target_z);
            }
            if (found) {
                int bx = mc_floor(target_x);
                int by = animal_navigation_surface_y(
                    w, bx, mc_floor(target_y), mc_floor(target_z));
                int bz = mc_floor(target_z);
                s->path_tx[slot] = bx + 0.5D;
                s->path_ty[slot] = by;
                s->path_tz[slot] = bz + 0.5D;
                s->path_len[slot] = by > 0 && by < 256
                    && solid_id(gm_world_block(w, bx, by - 1, bz))
                    && !solid_id(gm_world_block(w, bx, by, bz))
                    && !solid_id(gm_world_block(w, bx, by + 1, bz));
                if (s->path_len[slot]) {
                    m->passive_nav_speed[slot] = 1.0D;
                    m->passive_tasks[slot] |= PAI_BIT(PAI_WANDER);
                    wander_active = 1;
                }
            }
        }
        if (m->passive_watch_time[slot] <= 0
                && m->passive_idle_time[slot] < 0
                && jrand_float(random) < 0.02F
                && distance_sq <= 64.0D) {
            m->passive_watch_time[slot] =
                40 + jrand_int_bound(random, 40);
        }
        if (m->passive_watch_time[slot] <= 0
                && m->passive_idle_time[slot] < 0
                && !wander_active
                && jrand_float(random) < 0.02F) {
            double angle = MC_PI * 2.0D * jrand_double(random);
            m->passive_idle_x[slot] = cos(angle);
            m->passive_idle_z[slot] = sin(angle);
            m->passive_idle_time[slot] =
                20 + jrand_int_bound(random, 20);
        }
    }
    if (target_player) {
        m->passive_tasks[slot] &= ~PAI_BIT(PAI_WANDER);
        m->passive_watch_time[slot] = 0;
        m->passive_idle_time[slot] = -1;
    } else {
        if (m->passive_watch_time[slot] > 0)
            --m->passive_watch_time[slot];
        if (m->passive_idle_time[slot] >= 0)
            --m->passive_idle_time[slot];
    }
    m->skeleton_trap_target_player[slot] =
        (unsigned char)target_player;
    m->skeleton_trap_target_eid[slot] = target_player ? 0 : -1;
    if (target_player)
        m->skeleton_trap_bow_running[slot] = 1;
    else if (m->skeleton_trap_bow_running[slot])
        skeleton_trap_bow_reset(m, s, slot);
    m->skeleton_trap_first_tick[slot] = 0;
    return m->skeleton_trap_target_eid[slot] >= 0;
}

static int skeleton_trap_rider_queue_shot(
        GmMobLive *m, const EwStore *s, int slot,
        double target_x, double target_y, double target_z,
        float target_height) {
    int tail;
    GmSkeletonTrapShot *shot;
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !mob_ring_linearize(
                (void **)&m->skeleton_trap_shots,
                m->skeleton_trap_shots_cap,
                m->skeleton_trap_shot_count,
                &m->skeleton_trap_shot_head,
                sizeof *m->skeleton_trap_shots)
            || !MOB_COLD_RESERVE(
                m, skeleton_trap_shots,
                m->skeleton_trap_shot_count + 1,
                GM_SKELETON_TRAP_SHOTS))
        return 0;
    tail = (m->skeleton_trap_shot_head
        + m->skeleton_trap_shot_count) % m->skeleton_trap_shots_cap;
    shot = &m->skeleton_trap_shots[tail];
    *shot = (GmSkeletonTrapShot){
        .shooter_eid = s->id[slot],
        .x = s->x[slot],
        .y = s->y[slot] + (double)1.74F
            - 0.10000000149011612D,
        .z = s->z[slot],
        .vx = s->vx[slot],
        .vy = s->vy[slot],
        .vz = s->vz[slot],
        .target_x = target_x,
        .target_y = target_y + (double)(target_height / 3.0F),
        .target_z = target_z,
        .on_ground = s->on_ground[slot] != 0,
        .power = ic_enchantment_level(
            &m->skeleton_trap_mainhand[slot], 48),
        .punch = ic_enchantment_level(
            &m->skeleton_trap_mainhand[slot], 49),
        .flame = ic_enchantment_level(
            &m->skeleton_trap_mainhand[slot], 50),
    };
    shot->sound_pitch = 1.0F / (
        jrand_float(&m->entity_random[slot].random) * 0.4F + 0.8F);
    ++m->skeleton_trap_shot_count;
    return 1;
}

int gm_mobs_skeleton_trap_shoot_exact(
        GmMobLive *m, int shooter_eid,
        double target_x, double target_y, double target_z,
        float target_height) {
    int slot = mob_slot_by_eid(m, shooter_eid);
    const EwStore *store = m ? const_store(m) : NULL;
    if (!store || slot <= 0 || !store->alive[slot]
            || store->type[slot] != EW_TYPE_SKELETON)
        return 0;
    return skeleton_trap_rider_queue_shot(
        m, store, slot, target_x, target_y, target_z, target_height);
}

static void skeleton_trap_rider_sunlight_tick(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot, int day) {
    if (!m || !w || !s || !day || slot <= 0
            || slot >= EW_MAX_ENTITIES
            || m->skeleton_trap_vehicle_eid[slot] < 0
            || s->type[slot] != EW_TYPE_SKELETON)
        return;
    JavaRandom *random = &m->entity_random[slot].random;
    /* AbstractSkeleton.onLivingUpdate performs this draw every clear-day
     * tick, before target/goal scheduling. The iron helmet suppresses fire. */
    float sunlight = jrand_float(random);
    if (sunlight < 0.04F
            && sky_exposed(w, s->x[slot], s->y[slot], s->z[slot])) {
        if (m->skeleton_trap_head[slot].count > 0)
            m->skeleton_trap_head[slot].meta +=
                jrand_int_bound(random, 2);
        else
            m->fire_ticks[slot] = GM_MOB_FIRE_TICKS;
    }
}

static void animal_tick_newborn_same_boundary(
        GmMobLive *m, GmWorld *w, const McSinTable *st, EwStore *s,
        int slot, double player_x, double player_y, double player_z,
        int mob_griefing) {
    if (slot <= 0 || slot >= EW_MAX_ENTITIES || !s->alive[slot]
            || !gm_passive(s->type[slot]))
        return;
    living_entity_base_begin(m, s, slot);
    living_entity_ambient(m, s, slot);
    double dx = player_x - s->x[slot];
    double dy = player_y - s->y[slot];
    double dz = player_z - s->z[slot];
    double player_distance_sq = dx * dx + dy * dy + dz * dz;
    ++m->entity_age[slot];
    if (player_distance_sq < 1024.0)
        m->entity_age[slot] = 0;
    int setup_tick = m->sheep_ai_tick_count[slot]++ % 3 == 0;
    if (setup_tick) {
        if (s->type[slot] == EW_TYPE_SHEEP
                && sheep_graze_begin_slot(m, w, s, slot)) {
            (void)sheep_graze_update_slot(
                m, w, s, slot, mob_griefing != 0);
        } else {
            animal_declined_lower_task_rng(
                m, slot, player_distance_sq);
        }
    }
    move_mob(
        w, NULL, 0, 0, st, m, s, slot,
        0, 0, 0, 0, 0, 0.0F, 0.0F, 0, 0, 1.0);
    collide_living_entities(m, s, slot, m->active_dimension);
    if (gm_mobs_horse_type(s->type[slot]))
        horse_lifecycle_pre_tick(m, s, slot);
    if (m->growing_age[slot] < 0) ++m->growing_age[slot];
    else if (m->growing_age[slot] > 0) --m->growing_age[slot];
    if (m->growing_age[slot] != 0) {
        m->sheep_in_love[slot] = 0;
        m->sheep_bred_by_player[slot] = 0;
    }
    if (gm_mobs_horse_type(s->type[slot]))
        (void)horse_lifecycle_post_tick(m, w, s, slot);
    if (s->type[slot] == EW_TYPE_CHICKEN)
        chicken_living_tail(m, s, slot, NULL, NULL, NULL);
}

static void villager_tick_newborn_same_boundary(
        GmMobLive *m, GmWorld *w, const McSinTable *st,
        EwStore *s, int slot) {
    if (slot <= 0 || slot >= EW_MAX_ENTITIES || !s->alive[slot]
            || s->type[slot] != EW_TYPE_VILLAGER)
        return;
    living_entity_base_begin(m, s, slot);
    living_entity_ambient(m, s, slot);
    ++m->entity_age[slot];
    ++m->villager_ai_tick_count[slot];
    move_mob(
        w, NULL, 0, 0, st, m, s, slot,
        0, 0, 0, 0, 0, 0.0F, 0.0F, 0, 0, 0.6D);
    collide_living_entities(m, s, slot, m->active_dimension);
    if (m->growing_age[slot] < 0) ++m->growing_age[slot];
    else if (m->growing_age[slot] > 0) --m->growing_age[slot];
    if (--m->villager_random_tick_divider[slot] <= 0) {
        m->villager_collection_pending[slot] = 1;
        m->villager_collection_x[slot] = mc_floor(s->x[slot]);
        m->villager_collection_y[slot] = mc_floor(s->y[slot]);
        m->villager_collection_z[slot] = mc_floor(s->z[slot]);
        m->villager_random_tick_divider[slot] = 70
            + jrand_int_bound(&m->entity_random[slot].random, 50);
    }
}

static void mob_melee_apply_player_thorns(
        GmMobLive *m, EwStore *s, int slot, PsvPlayer *player,
        double player_x, double player_z, int accepted,
        GmLiveSim *drops, uint64_t *math_random_seed48,
        int *next_entity_id, int do_mob_loot) {
    GmPlayerThornsOutcome outcome;
    GmMobDeathContext death_context;
    if (!accepted || !m || !s || !player || slot <= 0
            || slot >= EW_MAX_ENTITIES)
        return;
    (void)gm_mobs_player_thorns_roll(m, &player->inv, &outcome);
    if (outcome.hit_count <= 0) return;
    death_context.do_mob_loot = do_mob_loot;
    death_context.math_random_seed48 = math_random_seed48;
    death_context.next_entity_id = next_entity_id;
    int looting = held_enchantment_level(player, 21);
    for (int hit = 0; hit < outcome.hit_count; ++hit) {
        int damage = outcome.damage[hit];
        if (gm_passive(s->type[slot]))
            (void)mob_player_damage_passive_slot_exact(
                m, s, slot, player_x, player_z, (float)damage,
                looting, drops, &death_context, 1);
        else if (s->type[slot] == EW_TYPE_WITCH)
            (void)mob_player_damage_witch_slot_exact(
                m, s, slot, player_x, player_z, (float)damage,
                looting, drops, &death_context, 1);
        else
            (void)mob_player_damage_hostile_slot_exact(
                m, s, slot, player_x, player_z, (float)damage,
                looting, drops, &death_context, 1);
    }
}

enum {
    GM_SAME_TICK_ANIMAL = 1,
    GM_SAME_TICK_XP = 2,
    GM_SAME_TICK_VILLAGER = 3
};

typedef struct {
    unsigned char kind;
    int slot;
} GmSameTickSpawn;

/* EntityEvokerFangs server update. The spike status is sent on the first
 * negative warmup boundary, damage is the fixed -8 boundary, and lifeTicks
 * is decremented only after activation. This keeps the warmup-0 fixture alive
 * for 22 updates and retires it on update 23, exactly like 1.11.2. */
static void tick_evoker_fangs(
        GmMobLive *m, EwStore *store, PsvPlayer *player, PvStats *vitals,
        int ox, int oz, int dimension) {
    if (!m || !store || !player || !vitals) return;
    McAABB player_box = mc_aabb_offset(
        &player->ent.box, (double)ox, 0.0, (double)oz);
    for (int index = 0; index < m->evoker_fang_count; ++index) {
        GmEvokerFang *fang = &m->evoker_fangs[index];
        if (!fang->active || fang->dimension != dimension) continue;
        if (--fang->warmup >= 0) continue;
        if (fang->warmup == -8) {
            McAABB attack = mc_aabb_make(
                fang->x - 0.45, fang->y, fang->z - 0.45,
                fang->x + 0.45, fang->y + 0.8, fang->z + 0.45);
            if (mc_aabb_intersects(&attack, &player_box)) {
                (void)gm_mobs_attack_player_source(
                    m, (struct PvStats *)vitals, &player->inv,
                    6.0F, 1, GM_DAMAGE_SOURCE_GENERIC);
                player->health = vitals->health;
            }
            int cursor = 0, slot;
            while ((slot = living_next_slot_from_store(
                        m, store, &cursor)) > 0) {
                if (!store->alive[slot] || m->entity_dead[slot]
                        || m->entity_dimension[slot] != dimension
                        || store->id[slot] == fang->caster_eid
                        || store->type[slot] == EW_TYPE_VINDICATOR
                        || store->type[slot] == EW_TYPE_EVOKER
                        || store->type[slot] == EW_TYPE_VEX)
                    continue;
                McAABB target;
                if (!mob_slot_world_box(m, store, slot, &target)
                        || !mc_aabb_intersects(&attack, &target))
                    continue;
                if (mob_effect_magic_damage(m, store, slot, 6.0F)
                        && store->health[slot] <= 0.0F) {
                    m->entity_dead[slot] = 1;
                    m->entity_death_time[slot] = 0;
                }
            }
            living_cold_flush_one_from_store(
                m, store, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
                &m->living_staged_cold_secondary);
        }
        if (!fang->sent_spike) {
            fang->sent_spike = 1;
            mob_event_append(
                m, GM_MOB_EVENT_ENTITY_STATUS, fang->eid, 4,
                fang->x, fang->y, fang->z, 0.0F, 0.0F);
            mob_event_append(
                m, GM_MOB_EVENT_SOUND, fang->eid,
                GM_MOB_SOUND_EVOKER_FANGS,
                fang->x, fang->y, fang->z, 1.0F, 0.95F);
        }
        if (--fang->life_ticks < 0) fang->active = 0;
    }
    while (m->evoker_fang_count > 0
            && !m->evoker_fangs[m->evoker_fang_count - 1].active)
        --m->evoker_fang_count;
}

static int evoker_vex_count_near(
        const GmMobLive *m, const EwStore *store, int evoker_slot) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    EwStore *completed = (EwStore *)store;
    int dimension = m->entity_dimension[evoker_slot];
    double x = store->x[evoker_slot], y = store->y[evoker_slot];
    double z = store->z[evoker_slot];
    int count = 0, cursor = 0, slot;
    while ((slot = living_next_slot_from_store(
                mutable_m, completed, &cursor)) > 0) {
        if (!store->alive[slot] || store->type[slot] != EW_TYPE_VEX
                || m->entity_dimension[slot] != dimension)
            continue;
        if (fabs(store->x[slot] - x) <= 16.5
                && fabs(store->y[slot] - y) <= 17.0
                && fabs(store->z[slot] - z) <= 16.5)
            ++count;
    }
    living_cold_flush_one_from_store(
        mutable_m, completed, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &mutable_m->living_staged_cold_secondary);
    return count;
}

static int evoker_summon_into_store(
        GmMobLive *m, EwStore *store, int evoker_slot) {
    int count = 0;
    int owner_eid = store->id[evoker_slot];
    int dimension = m->entity_dimension[evoker_slot];
    double owner_x = store->x[evoker_slot];
    double owner_y = store->y[evoker_slot];
    double owner_z = store->z[evoker_slot];
    JavaRandom random = m->entity_random[evoker_slot].random;
    for (int summon = 0; summon < 3; ++summon) {
        int bx = mc_floor(owner_x) - 2 + jrand_int_bound(&random, 5);
        int by = mc_floor(owner_y) + 1;
        int bz = mc_floor(owner_z) - 2 + jrand_int_bound(&random, 5);
        int life_ticks = 20 * (30 + jrand_int_bound(&random, 90));
        int eid = m->next_id++;
        int is_cold = 0;
        int slot = living_spawn_slot(
            m, store, EW_TYPE_VEX, eid,
            bx + 0.5, by, bz + 0.5, 14.0F, &is_cold);
        if (slot < 0) continue;
        m->entity_dimension[slot] = (signed char)dimension;
        m->size[slot] = 1;
        reset_slot_state_s(m, store, slot);
        m->vex_owner_eid[slot] = owner_eid;
        m->vex_bound_x[slot] = bx;
        m->vex_bound_y[slot] = by;
        m->vex_bound_z[slot] = bz;
        m->vex_limited_life[slot] = 1;
        m->vex_life_ticks[slot] = life_ticks;
        (void)living_spawn_finish(m, store, slot, is_cold, 0);
        ++count;
    }
    evoker_slot = mob_slot_by_eid(m, owner_eid);
    if (evoker_slot > 0)
        m->entity_random[evoker_slot].random = random;
    return count;
}

static int evoker_pick_blue_sheep(
        GmMobLive *m, const EwStore *store, int evoker_slot) {
    EwStore *completed = (EwStore *)store;
    int evoker_eid = store->id[evoker_slot];
    int dimension = m->entity_dimension[evoker_slot];
    double x = store->x[evoker_slot], y = store->y[evoker_slot];
    double z = store->z[evoker_slot];
    JavaRandom random = m->entity_random[evoker_slot].random;
    int count = 0, cursor = 0, slot;
    while ((slot = living_next_slot_from_store(
                m, completed, &cursor)) > 0) {
        if (!store->alive[slot] || store->type[slot] != EW_TYPE_SHEEP
                || m->entity_dimension[slot] != dimension
                || (m->sheep_data[slot] & 15) != 11)
            continue;
        if (fabs(store->x[slot] - x) <= 16.0
                && fabs(store->y[slot] - y) <= 4.0
                && fabs(store->z[slot] - z) <= 16.0)
            ++count;
    }
    living_cold_flush_one_from_store(
        m, completed, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &m->living_staged_cold_secondary);
    if (!count) return -1;
    int selected = jrand_int_bound(&random, count);
    int target_eid = -1;
    cursor = 0;
    while ((slot = living_next_slot_from_store(
                m, completed, &cursor)) > 0) {
        if (!store->alive[slot] || store->type[slot] != EW_TYPE_SHEEP
                || m->entity_dimension[slot] != dimension
                || (m->sheep_data[slot] & 15) != 11
                || fabs(store->x[slot] - x) > 16.0
                || fabs(store->y[slot] - y) > 4.0
                || fabs(store->z[slot] - z) > 16.0)
            continue;
        if (selected-- == 0) {
            target_eid = store->id[slot];
            break;
        }
    }
    living_cold_flush_one_from_store(
        m, completed, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
        &m->living_staged_cold_secondary);
    evoker_slot = mob_slot_by_eid(m, evoker_eid);
    if (evoker_slot > 0) m->entity_random[evoker_slot].random = random;
    return mob_slot_by_eid(m, target_eid);
}

static void evoker_start_spell(
        GmMobLive *m, const EwStore *store, int slot,
        int spell, int warmup, int casting_ticks, int prepare_sound) {
    m->evoker_spell_id[slot] = spell;
    m->evoker_spell_warmup[slot] = warmup;
    m->evoker_spell_ticks[slot] = casting_ticks;
    mob_event_append(
        m, GM_MOB_EVENT_SOUND, store->id[slot], prepare_sound,
        store->x[slot], store->y[slot], store->z[slot], 1.0F, 1.0F);
}

/* Goal priorities and cooldowns from EntityEvoker.initEntityAI. Returns true
 * while AICastingSpell owns the movement/look mutex. */
static int tick_evoker_spells(
        GmMobLive *m, GmWorld *world, const McSinTable *sin_table,
        EwStore *store, int slot, int aggro,
        double target_x, double target_y, double target_z,
        int mob_griefing) {
    if (m->evoker_spell_ticks[slot] > 0
            && --m->evoker_spell_ticks[slot] == 0)
        m->evoker_spell_id[slot] = 0;
    if (m->evoker_spell_warmup[slot] > 0) {
        int valid = m->evoker_spell_id[slot] == 3
            ? mob_slot_by_eid(m, m->evoker_wololo_target[slot]) > 0
            : aggro;
        if (!valid) {
            m->evoker_spell_warmup[slot] = 0;
            m->evoker_wololo_target[slot] = -1;
        } else if (--m->evoker_spell_warmup[slot] == 0) {
            if (m->evoker_spell_id[slot] == 1)
                (void)evoker_summon_into_store(m, store, slot);
            else if (m->evoker_spell_id[slot] == 2)
                (void)evoker_cast_attack_slot(
                    m, world, sin_table, store, slot,
                    target_x, target_y, target_z);
            else {
                int sheep = mob_slot_by_eid(
                    m, m->evoker_wololo_target[slot]);
                if (sheep > 0 && store->alive[sheep]
                        && store->type[sheep] == EW_TYPE_SHEEP)
                    m->sheep_data[sheep] = (unsigned char)(
                        (m->sheep_data[sheep] & 0xf0) | 14);
                m->evoker_wololo_target[slot] = -1;
            }
            mob_event_append(
                m, GM_MOB_EVENT_SOUND, store->id[slot],
                GM_MOB_SOUND_EVOKER_CAST,
                store->x[slot], store->y[slot], store->z[slot],
                1.0F, 1.0F);
        }
    }
    if (m->evoker_spell_ticks[slot] > 0) return 1;

    int age = m->entity_ticks_existed[slot];
    if (aggro && age >= m->evoker_summon_next[slot]) {
        int vexes = evoker_vex_count_near(m, store, slot);
        if (jrand_int_bound(&m->entity_random[slot].random, 8) + 1 > vexes) {
            m->evoker_summon_next[slot] = age + 340;
            evoker_start_spell(
                m, store, slot, 1, 20, 100,
                GM_MOB_SOUND_EVOKER_PREPARE_SUMMON);
        }
    }
    if (aggro && !m->evoker_spell_ticks[slot]
            && age >= m->evoker_attack_next[slot]) {
        m->evoker_attack_next[slot] = age + 100;
        evoker_start_spell(
            m, store, slot, 2, 20, 40,
            GM_MOB_SOUND_EVOKER_PREPARE_ATTACK);
    }
    if (!aggro && !m->evoker_spell_ticks[slot] && mob_griefing
            && age >= m->evoker_wololo_next[slot]) {
        int sheep = evoker_pick_blue_sheep(m, store, slot);
        if (sheep > 0) {
            m->evoker_wololo_target[slot] = store->id[sheep];
            m->evoker_wololo_next[slot] = age + 140;
            evoker_start_spell(
                m, store, slot, 3, 40, 60,
                GM_MOB_SOUND_EVOKER_PREPARE_WOLOLO);
        }
    }
    /* EntityAITasks updates newly started goals on their start boundary. */
    if (m->evoker_spell_warmup[slot] > 0)
        --m->evoker_spell_warmup[slot];
    return m->evoker_spell_ticks[slot] > 0;
}

/* EntityLiving.updateEntityActionState increments entityAge before its
 * despawn test. Forge's default event result is inert, so the represented
 * single-player boundary reduces to vanilla's persistence reset, hard range,
 * and ordered soft-lottery draw. Return true after setDead; Bat still runs its
 * private AI once on that boundary before World retires it. */
static int bat_despawn_entity(
        GmMobLive *m, const EwStore *s, int slot,
        double player_x, double player_y, double player_z) {
    int despawn = 0;
    double dx, dy, dz, distance_sq;
    m->entity_age[slot] = m->entity_age[slot] == INT_MAX
        ? INT_MIN : m->entity_age[slot] + 1;
    if (m->persistence_required[slot]) {
        m->entity_age[slot] = 0;
        return 0;
    }
    dx = player_x - s->x[slot];
    dy = player_y - s->y[slot];
    dz = player_z - s->z[slot];
    distance_sq = dx * dx + dy * dy + dz * dz;
    if (distance_sq > 16384.0D)
        despawn = 1;
    if (m->entity_age[slot] > 600
            && jrand_int_bound(&m->entity_random[slot].random, 800) == 0
            && distance_sq > 1024.0D)
        despawn = 1;
    else if (distance_sq < 1024.0D)
        m->entity_age[slot] = 0;
    return despawn;
}

/* EntityBat.updateAITasks. Bat has no goal-selector tasks; this private
 * ceiling/flight state machine runs after the empty navigator and before
 * EntityMoveHelper WAIT clears moveForward. */
static void bat_update_ai_tasks(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot,
        double player_x, double player_y, double player_z,
        int player_alive) {
    JavaRandom *random = &m->entity_random[slot].random;
    int block_x = mc_floor(s->x[slot]);
    int block_y = mc_floor(s->y[slot]);
    int block_z = mc_floor(s->z[slot]);
    int above_id = gm_world_block(w, block_x, block_y + 1, block_z);
    int above_meta = gm_world_meta(w, block_x, block_y + 1, block_z);
    int above_normal = gm_block_is_normal_cube_1_11_2(
        above_id, above_meta);

    if (m->bat_hanging[slot]) {
        if (above_normal) {
            if (jrand_int_bound(random, 200) == 0)
                m->passive_head_yaw[slot] =
                    (float)jrand_int_bound(random, 360);
            double dx = player_x - s->x[slot];
            double dy = player_y - s->y[slot];
            double dz = player_z - s->z[slot];
            if (player_alive && !m->player_creative
                    && dx * dx + dy * dy + dz * dz <= 16.0D) {
                m->bat_hanging[slot] = 0;
                mob_event_append(
                    m, GM_MOB_EVENT_WORLD_EVENT, 0, 1025,
                    (double)block_x, (double)block_y, (double)block_z,
                    0.0F, 0.0F);
            }
        } else {
            m->bat_hanging[slot] = 0;
            mob_event_append(
                m, GM_MOB_EVENT_WORLD_EVENT, 0, 1025,
                (double)block_x, (double)block_y, (double)block_z,
                0.0F, 0.0F);
        }
        return;
    }

    if (m->bat_spawn_position_valid[slot]
            && (gm_world_block(
                    w, m->bat_spawn_x[slot], m->bat_spawn_y[slot],
                    m->bat_spawn_z[slot]) != 0
                || m->bat_spawn_y[slot] < 1))
        m->bat_spawn_position_valid[slot] = 0;

    int choose_position = !m->bat_spawn_position_valid[slot];
    if (!choose_position) {
        int retarget = jrand_int_bound(random, 30) == 0;
        double dx = (double)m->bat_spawn_x[slot] - (double)(int)s->x[slot];
        double dy = (double)m->bat_spawn_y[slot] - (double)(int)s->y[slot];
        double dz = (double)m->bat_spawn_z[slot] - (double)(int)s->z[slot];
        choose_position = retarget || dx * dx + dy * dy + dz * dz < 4.0D;
    }
    if (choose_position) {
        m->bat_spawn_x[slot] = (int)s->x[slot]
            + jrand_int_bound(random, 7) - jrand_int_bound(random, 7);
        m->bat_spawn_y[slot] = (int)s->y[slot]
            + jrand_int_bound(random, 6) - 2;
        m->bat_spawn_z[slot] = (int)s->z[slot]
            + jrand_int_bound(random, 7) - jrand_int_bound(random, 7);
        m->bat_spawn_position_valid[slot] = 1;
    }

    double dx = (double)m->bat_spawn_x[slot] + 0.5D - s->x[slot];
    double dy = (double)m->bat_spawn_y[slot] + 0.1D - s->y[slot];
    double dz = (double)m->bat_spawn_z[slot] + 0.5D - s->z[slot];
    double sign_x = dx > 0.0D ? 1.0D : dx < 0.0D ? -1.0D : 0.0D;
    double sign_y = dy > 0.0D ? 1.0D : dy < 0.0D ? -1.0D : 0.0D;
    double sign_z = dz > 0.0D ? 1.0D : dz < 0.0D ? -1.0D : 0.0D;
    s->vx[slot] += (sign_x * 0.5D - s->vx[slot])
        * 0.10000000149011612D;
    s->vy[slot] += (sign_y * 0.699999988079071D - s->vy[slot])
        * 0.10000000149011612D;
    s->vz[slot] += (sign_z * 0.5D - s->vz[slot])
        * 0.10000000149011612D;
    float target_yaw = (float)(
        mob_java_math_atan2(s->vz[slot], s->vx[slot])
            * (180.0D / MC_PI)) - 90.0F;
    s->yaw[slot] += pai_wrap_degrees(target_yaw - s->yaw[slot]);

    if (jrand_int_bound(random, 100) == 0 && above_normal)
        m->bat_hanging[slot] = 1;
}

void gm_mobs_tick_spawn_context(
                  GmMobLive *m, GmWorld *w, const struct Chunk *window,
                  const struct McSinTable *st_,
                  struct PsvPlayer *player_, struct PvStats *vitals_,
                  int ox, int oz, int dimension, long long world_time,
                  const GmWorldClock *clock,
                  int mob_griefing, uint64_t *world_random_seed48,
                  uint64_t *math_random_seed48, int *next_entity_id,
                  const GmNaturalSpawnContext *spawn_context,
                  int do_mob_loot,
                  GmLiveSim *drops,
                  float boat_forward, float boat_strafe) {
    if (!m || !w || !player_ || !vitals_) return;
    m->active_dimension=dimension;
    PsvPlayer *p=(PsvPlayer *)player_; PvStats *v=(PvStats *)vitals_;
    const McSinTable *st=(const McSinTable *)st_;
    /* World.getDifficultyForLocation on the runtime's pinned NORMAL
     * difficulty. Chunks do not yet accumulate inhabitedTime, so that term
     * is exactly zero; world age and moon phase still cross the Java int-cast
     * boundary from a 140- to a 280-tick Husk effect. */
    static const float moon_phase[] = {
        1.0F, 0.75F, 0.5F, 0.25F, 0.0F, 0.25F, 0.5F, 0.75F
    };
    float age = ((float)world_time - 72000.0F) / 1440000.0F;
    if (age < 0.0F) age = 0.0F;
    if (age > 1.0F) age = 1.0F;
    age *= 0.25F;
    long long day_index = world_time / 24000LL;
    int phase = (int)(day_index % 8LL);
    if (phase < 0) phase += 8;
    float moon = moon_phase[phase] * 0.25F;
    if (moon > age) moon = age;
    int husk_hunger_duration = 140 * (int)(2.0F * (0.75F + age + moon));
    EwStore *now=now_store(m), *nx=next_store(m); ew_store_copy(nx,now);
    /* Entity.onEntityUpdate calls outOfWorld below Y=-64 before the living
     * update.  Without this, entities that fell through an unloaded/cut
     * collision edge survived forever at increasingly negative Y, occupied
     * the natural-spawn cap, and eventually prevented all replacement food
     * animals in long ordinary-input replays.  Cull both buffers before the
     * spawn count and invalidate the loaded-order generation. */
    for (int i = 1; i < now->count; ++i) {
        if (!now->alive[i] || now->y[i] >= -64.0D) continue;
        loaded_invalidate_living(m, i);
        now->alive[i] = nx->alive[i] = 0;
        now->type[i] = nx->type[i] = EW_TYPE_NONE;
    }
    for (int i = 0; i < m->living_cold_count; ++i) {
        GmLivingColdSlot *cold = &m->living_cold[i];
        if (!cold->store_alive || cold->store_y >= -64.0D) continue;
        cold->living_loaded_generation = loaded_next_generation(
            cold->living_loaded_generation);
        cold->store_alive = 0;
        cold->store_type = EW_TYPE_NONE;
    }
    tick_evoker_fangs(m, nx, p, v, ox, oz, dimension);
    loaded_order_prepare(m);
    if (m->player_xp_cooldown > 0) --m->player_xp_cooldown;
    if (m->player_wither_ticks > 0) {
        /* DamageSource.WITHER is unblockable. */
        if (m->player_wither_ticks % 40 == 0)
            (void)gm_mobs_attack_player(m, (struct PvStats *)v,
                                        &p->inv, 1.0f, 1);
        --m->player_wither_ticks;
        p->health = v->health;
    }
    if (m->player_hunger_ticks > 0) {
        /* MobEffects.HUNGER is ready every tick at amplifier zero. The Husk
         * adds the effect during its update, after the player has already
         * ticked, so the first exhaustion pulse belongs to the next tick. */
        pv_add_exhaustion(v, 0.005F);
        --m->player_hunger_ticks;
    }
    if (m->player_ticks_since_last_swing < 1000000000)
        ++m->player_ticks_since_last_swing;
    double px=p->ent.posX+ox, py=p->ent.posY, pz=p->ent.posZ+oz;
    if (m->natural_spawning_enabled)
        natural_spawn(
            m,w,nx,px,py,pz,dimension,world_time,
            world_random_seed48,math_random_seed48,spawn_context);
    int tod=(int)(world_time%24000LL); if(tod<0)tod+=24000;
    int day=dimension==0&&tod<12000;
    float boat_fwd = m->boat_ride_eid >= 0 ? boat_forward : 0.0f;
    float boat_str = m->boat_ride_eid >= 0 ? boat_strafe : 0.0f;
    m->horse_input_forward = m->horse_ride_eid >= 0 ? boat_forward : 0.0F;
    m->horse_input_strafe = m->horse_ride_eid >= 0 ? boat_strafe : 0.0F;
    GmSameTickSpawn same_tick_spawns[EW_MAX_ENTITIES * 2];
    int same_tick_spawn_count = 0;
    unsigned char spawned_xp[GM_XP_ORBS] = {0};
    unsigned char ticked_xp[GM_XP_ORBS] = {0};
    McAABB xp_player = xp_player_collision_box(p, ox, oz);
    m->xp_collision_count = 0;
    m->tick_update_order_count = 0;

    int initial_loaded_count = m->loaded_order_count;
    for (int loaded_index = 0;
            loaded_index < initial_loaded_count; ++loaded_index) {
        living_cold_flush_from_store(m, nx);
        GmMobLoadedRef ref = *loaded_ref_at(m, loaded_index);
        if (ref.kind == GM_MOB_LOADED_XP) {
            int xp_slot = ref.slot;
            McOrb *orb = xp_orb_at(m, xp_slot);
            unsigned int *generation = xp_generation_at(m, xp_slot);
            signed char *orb_dimension = xp_dimension_at(m, xp_slot);
            if (!orb || !generation || !orb_dimension
                    || ref.generation != *generation
                    || orb->dead || orb->xpValue <= 0
                    || orb->eid != ref.eid || *orb_dimension != dimension)
                continue;
            tick_order_append(m, ref.eid);
            if (xp_slot < GM_XP_ORBS) ticked_xp[xp_slot] = 1;
            tick_xp_orb_slot(m, w, p, ox, oz, &xp_player, xp_slot);
            continue;
        }
        int i = living_loaded_ref_stage(m, &ref, nx);
        if (i <= 0 || i >= EW_MAX_ENTITIES
                || ref.generation != m->living_loaded_generation[i]
                || !now->alive[i] || now->id[i] != ref.eid
                || m->entity_dimension[i] != dimension
                || !gm_living(now->type[i]))
            continue;
        tick_order_append(m, now->id[i]);
        if (m->entity_portal_cooldown[i] > 0)
            --m->entity_portal_cooldown[i];
        int type=now->type[i];
        int passive = gm_passive(type);
        int horse_pre_ticked = 0;
        int trap_rider = m->skeleton_trap_vehicle_eid[i] >= 0;
        int generic_rider = m->entity_vehicle_eid[i] >= 0;
        int horse_movement_blocked = gm_mobs_horse_type(type)
            && (m->horse_status[i]
                & (GM_HORSE_EATING | GM_HORSE_REARING));
        int trap_should_activate = 0;
        if (type == EW_TYPE_SKELETON_HORSE && m->horse_trap[i]
                && !m->controlled_no_ai[i]
                && m->active_entity_seed_generator_seed48
                && m->active_server_uuid_random_seed48
                && math_random_seed48 && next_entity_id) {
            double trap_dx = px - now->x[i];
            double trap_dy = py - now->y[i];
            double trap_dz = pz - now->z[i];
            if (trap_dx * trap_dx + trap_dy * trap_dy
                    + trap_dz * trap_dz <= 100.0D) {
                /* AbstractHorse rolls its tail before EntityLiving reaches
                 * the priority-one skeleton-rider task. */
                horse_lifecycle_pre_tick(m, nx, i);
                horse_pre_ticked = 1;
                trap_should_activate = 1;
            }
        }
        /* World.updateEntity calls updateRidden for a mounted skeleton. */
        if (trap_rider || generic_rider)
            nx->vx[i] = nx->vy[i] = nx->vz[i] = 0.0D;
        int exact_base_tick = m->controlled_no_ai[i]
            || passive || trap_rider || generic_rider
            || gm_npc(type) || type == EW_TYPE_WITCH
            || type == EW_TYPE_VINDICATOR || type == EW_TYPE_EVOKER
            || type == EW_TYPE_VEX || type == EW_TYPE_GUARDIAN
            || type == EW_TYPE_ELDER_GUARDIAN
            || type == EW_TYPE_IRON_GOLEM || type == EW_TYPE_BAT
            || type == EW_TYPE_SQUID || type == EW_TYPE_SNOWMAN;
        if (exact_base_tick) living_entity_base_begin(m, now, i);
        int squid_air_before = m->entity_air[i];
        if (type == EW_TYPE_ZOMBIE_VILLAGER
                && zombie_villager_conversion_tick_slot(
                    m, w, nx, i, next_entity_id))
            continue;
        int sheep_grazing = 0, animal_mating = 0, horse_crazy = 0;
        int llama_caravan = 0, llama_ranged = 0, llama_ranged_move = 0;
        int polar_aggro = 0, rabbit_killer = 0, rabbit_raiding = 0;
        int rabbit_carrot_x = 0, rabbit_carrot_y = 0, rabbit_carrot_z = 0;
        int llama_follow_parent_move = 0;
        int llama_target_slot = -1;
        int snowman_ranged = 0;
        int snowman_target_slot = -1;
        double llama_caravan_x = 0.0, llama_caravan_y = 0.0;
        double llama_caravan_z = 0.0, llama_caravan_speed = 0.0;
        double llama_follow_parent_x = 0.0;
        double llama_follow_parent_y = 0.0;
        double llama_follow_parent_z = 0.0;
        int horse_wandering_exact = 0;
        int sheep_lower_rng = 0;
        int villager_mating = 0, villager_following = 0;
        int villager_moving_indoors = 0;
        int villager_moving_restriction = 0;
        int villager_avoiding = 0;
        int villager_playing_task = 0;
        int villager_harvesting = 0;
        int villager_swim_jump = 0;
        int villager_trading = 0;
        int villager_trade_looking = 0;
        int villager_wandering = 0;
        int ridden_pig = type == EW_TYPE_PIG
            && ride_is_slot(nx, i, m->pig_ride_eid);
        int exact_ridden_server_tick = ridden_pig && window;
        ICStack pig_main = isr_get_stack(
            &p->inv, p->inv.current_item);
        ICStack pig_off = isr_get_stack(&p->inv, ISR_OFFHAND_SLOT);
        int pig_steerable = ridden_pig
            && ((pig_main.item == 398 && pig_main.count > 0)
                || (pig_off.item == 398 && pig_off.count > 0));
        if (exact_ridden_server_tick) {
            tick_ridden_pig_vehicle_server_base(
                m, nx, i, window, ox, oz, pig_steerable,
                p->yaw, p->pitch, math_random_seed48);
        }
        tick_controlled_dead_fire(m, nx, i);
        if (tick_exact_mob_environment(
                m, w, window, ox, oz, nx, i, drops, do_mob_loot,
                math_random_seed48, next_entity_id))
            continue;
        /* EntityLivingBase.onEntityUpdate applies IN_WALL after Entity's
         * water/fire/lava phase and before air, wetness, and timer aging. */
        if (type != EW_TYPE_VEX && mob_exact_environment_type(type)
                && nx->alive[i] && nx->health[i] > 0.0F
                && mob_slot_inside_suffocating_block(m, w, nx, i)) {
            int source_result = mob_source_damage_environment_slot_exact(
                m, nx, i, 1.0F, drops, math_random_seed48,
                next_entity_id, do_mob_loot, 1, 1);
            if (source_result < 0) continue;
            if (type == EW_TYPE_ENDERMAN)
                (void)mob_try_enderman_random_teleport(m, w, nx, i);
        }
        if (tick_mob_air(
                m, w, nx, i, drops, do_mob_loot,
                math_random_seed48, next_entity_id))
            continue;
        /* EntityLiving.onEntityUpdate calls the LivingBase implementation
         * first. Its ambient roll therefore observes a same-boundary
         * drowning death and short-circuits when isEntityAlive is false. */
        /* EntityLivingBase.onUpdate extinguishes a living wet entity after
         * air work and before combat-timer/death aging. Water already cleared
         * fire in Entity.onEntityUpdate; this is the rain-wet phase. */
        if (mob_exact_environment_type(type)
                && nx->alive[i] && nx->health[i] > 0.0F
                && mob_slot_is_wet(m, w, clock, nx, i))
            m->fire_ticks[i] = 0;
        if (type == EW_TYPE_BLAZE)
            nx->vy[i] = ebf_blaze_fall_damping(
                now->on_ground[i] ? 1 : 0, nx->vy[i]);
        /* EntityLivingBase.onUpdate ages both combat timers for every living
         * entity, not only deterministic NoAI oracle fixtures. Without this,
         * a normal mob's first accepted hit left hurtResistantTime at 20
         * forever and all equal-strength follow-up hits were rejected. */
        if (m->entity_hurt_time[i] > 0) --m->entity_hurt_time[i];
        if (m->entity_hurt_resistant[i] > 0)
            --m->entity_hurt_resistant[i];
        if (type == EW_TYPE_POLAR_BEAR) {
            if (m->polar_warning_sound_ticks[i] > 0)
                --m->polar_warning_sound_ticks[i];
            m->polar_stand_animation0[i] =
                m->polar_stand_animation[i];
            if (m->polar_standing[i]) {
                if (m->polar_stand_animation[i] < 6.0F)
                    m->polar_stand_animation[i] += 1.0F;
            } else if (m->polar_stand_animation[i] > 0.0F) {
                m->polar_stand_animation[i] -= 1.0F;
            }
        }
        if (type == EW_TYPE_RABBIT) {
            if (m->rabbit_jump_duration[i] != 0
                    && ++m->rabbit_jump_ticks[i]
                        >= m->rabbit_jump_duration[i]) {
                m->rabbit_jump_ticks[i] = 0;
                m->rabbit_jump_duration[i] = 0;
            }
            if (m->rabbit_carrot_ticks[i] > 0) {
                m->rabbit_carrot_ticks[i] -= jrand_int_bound(
                    &m->entity_random[i].random, 3);
                if (m->rabbit_carrot_ticks[i] < 0)
                    m->rabbit_carrot_ticks[i] = 0;
            }
        }
        if (exact_ridden_server_tick) {
            if (m->entity_server_fire_resistance_ticks[i] > 0)
                --m->entity_server_fire_resistance_ticks[i];
            tick_ridden_pig_server_ambient(m, nx, i);
        }
        /* A controlled living target can be killed by an earlier entity in
         * this same loaded-entity boundary (for example, a falling anvil).
         * EntityLivingBase.onUpdate then advances onDeathUpdate before any
         * living AI/travel work. Loot is an earlier onDeath concern and is
         * intentionally outside this no-loot controlled path. */
        int controlled_death_state = tick_controlled_death(
            m, nx, i, 0, NULL, NULL, NULL);
        int ordinary_death_state = 0;
        int terminal_slime_slots[4];
        int terminal_slime_count = 0;
        if (!controlled_death_state
                && mob_exact_environment_type(type)
                && !m->controlled_no_ai[i] && m->entity_dead[i]
                && nx->health[i] <= 0.0F)
            ordinary_death_state = tick_living_death_progress(
                m, nx, i, do_mob_loot, world_random_seed48,
                math_random_seed48, next_entity_id,
                terminal_slime_slots, &terminal_slime_count,
                (int)(sizeof terminal_slime_slots
                    / sizeof terminal_slime_slots[0]));
        (void)terminal_slime_count;
        if (m->entity_recently_hit[i] > 0)
            --m->entity_recently_hit[i];
        else
            m->entity_attacking_player[i] = 0;
        if (m->entity_effect_count[i] > 0)
            tick_mob_potion_effects(m, nx, i, drops);
        if (exact_base_tick) living_entity_ambient(m, nx, i);
        if (exact_base_tick && tick_squid_air_tail(
                m, nx, i, squid_air_before, drops, do_mob_loot,
                math_random_seed48, next_entity_id))
            continue;
        if (generic_rider && type == EW_TYPE_PIGMAN
                && m->sheep_ai_tick_count[i]++ % 3 == 0) {
            double task_dx = px - nx->x[i];
            double task_dy = py - nx->y[i];
            double task_dz = pz - nx->z[i];
            skeleton_trap_bow_start_lower_rng(
                m, w, nx, i,
                task_dx * task_dx + task_dy * task_dy
                    + task_dz * task_dz);
        }
        horse_movement_blocked = gm_mobs_horse_type(type)
            && (m->horse_status[i]
                & (GM_HORSE_EATING | GM_HORSE_REARING));
        if (!nx->alive[i]) continue;
        /* AbstractHorse.onLivingUpdate makes its tail roll before calling
         * EntityAnimal/EntityLivingBase, whose server branch runs goals and
         * navigation. This ordering matters when a wander chance accepts. */
        if (gm_mobs_horse_type(type) && !horse_pre_ticked
                && !m->entity_dead[i] && nx->health[i] > 0.0F) {
            horse_lifecycle_pre_tick(m, nx, i);
            horse_pre_ticked = 1;
        }
        if (!ordinary_death_state
                && mob_exact_environment_type(type)
                && !m->controlled_no_ai[i] && m->entity_dead[i]
                && nx->health[i] <= 0.0F)
            ordinary_death_state = 1;
        int death_state = controlled_death_state
            ? controlled_death_state : ordinary_death_state;
        if (ordinary_death_state) {
            /* onDeathUpdate runs before onLivingUpdate. A normal-AI dead
             * living entity blocks AI inputs but Witch.onLivingUpdate still
             * advances its drink/status phase before ordinary server travel. */
            if (type == EW_TYPE_WITCH)
                (void)witch_self_potion_step_slot(
                    m, nx, i,
                    gm_uw_eye_inside_water(
                        w, nx->x[i], nx->y[i], nx->z[i], 1.62F),
                    m->fire_ticks[i] > 0, 0, 0.0);
            move_mob(
                w, window, ox, oz, st, m, nx, i, 0, 0, 0,
                0, 0, p->yaw, p->pitch, 1, 0, 1.0);
            if (tick_exact_mob_cactus_contact(
                    m, w, nx, i, drops, do_mob_loot,
                    math_random_seed48, next_entity_id))
                continue;
            if (tick_exact_mob_fire_contact(
                    m, w, clock, nx, i, drops, do_mob_loot,
                    math_random_seed48, next_entity_id))
                continue;
            collide_living_with_player(
                m, nx, i, p, ox, oz, 0);
            collide_living_entities(m, nx, i, dimension);
        }
        if (death_state == 2) {
            if (ridden_pig) {
                gm_mobs_pig_dismount_explicit(
                    m, w, window, player_, ox, oz);
                p->fall_distance = 0.0F;
            }
            retire_terminal_living(m, nx, i);
            continue;
        }
        if (death_state == 1) {
            if (ridden_pig) pig_update_passenger_pose(nx, i, p, ox, oz);
            if (ride_is_slot(nx, i, m->horse_ride_eid))
                horse_update_passenger_pose(m, nx, st, i, p, ox, oz);
            if (type != EW_TYPE_SQUID) continue;
        }
        if (m->controlled_no_ai[i]
                && (!m->controlled_block_collisions[i]
                    || (death_state == 1 && type == EW_TYPE_SQUID))
                && type == EW_TYPE_GHAST) {
            /* EntityLiving applies NoAI damping before EntityFlying keeps
             * moving and applies its float 0.91 flight drag. */
            tick_no_ai_ghast_flight(m, nx, i);
            collide_living_with_player(m, nx, i, p, ox, oz, 0);
            collide_living_entities(m, nx, i, dimension);
            living_body_update(m, now, nx, i);
            continue;
        }
        if (m->controlled_no_ai[i]
                && (!m->controlled_block_collisions[i]
                    || (death_state == 1 && type == EW_TYPE_SQUID))) {
            /* EntityLiving reports !isServerWorld while NoAI is set. Its
             * travel branch damps motion but does not call move(). */
            if (gm_is_slimey(type)) {
                m->squish_factor[i] +=
                    (m->squish_amount[i] - m->squish_factor[i]) * 0.5F;
                m->prev_squish_factor[i] = m->squish_factor[i];
            }
            if (type == EW_TYPE_SQUID) {
                tick_squid(m, w, nx, i, 0);
            } else {
                nx->vx[i] *= 0.98D;
                nx->vy[i] *= 0.98D;
                nx->vz[i] *= 0.98D;
                if (fabs(nx->vx[i]) < 0.003D) nx->vx[i] = 0.0D;
                if (fabs(nx->vy[i]) < 0.003D) nx->vy[i] = 0.0D;
                if (fabs(nx->vz[i]) < 0.003D) nx->vz[i] = 0.0D;
            }
            if (gm_mobs_horse_type(type) && !horse_pre_ticked)
                horse_lifecycle_pre_tick(m, nx, i);
            if (passive) animal_age_love_tail(m, nx, i);
            if (gm_mobs_horse_type(type)
                    && horse_lifecycle_post_tick(m, w, nx, i))
                continue;
            if (type == EW_TYPE_VILLAGER) {
                if (m->growing_age[i] < 0) ++m->growing_age[i];
                else if (m->growing_age[i] > 0) --m->growing_age[i];
            }
            if (type == EW_TYPE_CHICKEN)
                chicken_living_tail(
                    m, nx, i, math_random_seed48, next_entity_id, drops);
            if (type == EW_TYPE_IRON_GOLEM)
                iron_golem_living_tail(m, w, nx, i);
            if (gm_mobs_vanilla_leashable_type(type)
                    && m->llama_leashed[i])
                living_leash_tail(
                    m, nx, i, dimension, px, py, pz, v->health,
                    math_random_seed48, next_entity_id, drops);
            if (type == EW_TYPE_WITCH)
                (void)witch_self_potion_step_slot(
                    m, nx, i,
                    gm_uw_eye_inside_water(
                        w, nx->x[i], nx->y[i], nx->z[i], 1.62F),
                    m->fire_ticks[i] > 0, 0, 0.0);
            if (type != EW_TYPE_BAT) {
                collide_living_with_player(m, nx, i, p, ox, oz, 0);
                collide_living_entities(m, nx, i, dimension);
            }
            if (type != EW_TYPE_SQUID)
                living_body_update(m, now, nx, i);
            if (type == EW_TYPE_ENDERMITE) {
                if (!m->persistence_required[i])
                    ++m->endermite_lifetime[i];
                if (m->endermite_lifetime[i] >= 2400) {
                    retire_terminal_living(m, nx, i);
                    continue;
                }
            }
            if (gm_is_slimey(type)) {
                int on_ground = nx->on_ground[i] ? 1 : 0;
                if (on_ground && !m->was_on_ground[i])
                    m->squish_amount[i] = -0.5F;
                else if (!on_ground && m->was_on_ground[i])
                    m->squish_amount[i] = 1.0F;
                m->was_on_ground[i] = (unsigned char)on_ground;
                m->squish_amount[i] *=
                    type == EW_TYPE_MAGMA ? 0.9F : 0.6F;
            }
            continue;
        }
        if (type == EW_TYPE_SQUID) {
            int despawn = bat_despawn_entity(
                m, nx, i, px, py, pz);
            if (despawn) {
                retire_terminal_living(m, nx, i);
                continue;
            }
            tick_squid(m, w, nx, i, 1);
            if (tick_exact_mob_cactus_contact(
                    m, w, nx, i, drops, do_mob_loot,
                    math_random_seed48, next_entity_id))
                continue;
            if (tick_exact_mob_fire_contact(
                    m, w, clock, nx, i, drops, do_mob_loot,
                    math_random_seed48, next_entity_id))
                continue;
            collide_living_with_player(m, nx, i, p, ox, oz, 0);
            collide_living_entities(m, nx, i, dimension);
            continue;
        }
        if (passive && !m->controlled_no_ai[i]
                && !horse_movement_blocked) {
            double animal_dx = px - now->x[i];
            double animal_dy = py - now->y[i];
            double animal_dz = pz - now->z[i];
            double animal_player_distance_sq =
                animal_dx * animal_dx + animal_dy * animal_dy
                    + animal_dz * animal_dz;
            ++m->entity_age[i];
            if (animal_player_distance_sq < 1024.0)
                m->entity_age[i] = 0;
            int setup_tick = m->sheep_ai_tick_count[i]++ % 3 == 0;
            if (type == EW_TYPE_LLAMA) {
                if (m->llama_did_spit[i]
                        && m->llama_attack_target_kind[i] != 2) {
                    m->llama_did_spit[i] = 0;
                    m->llama_attack_target_eid[i] = -1;
                    m->llama_attack_target_kind[i] = 0;
                    m->llama_ranged_attack_time[i] = -1;
                    m->llama_ranged_see_time[i] = 0;
                }
                if (m->llama_attack_target_eid[i] == 0
                        && v->health > 0.0F
                        && animal_player_distance_sq <= 1600.0D)
                    llama_ranged = 1;
                else if (m->llama_attack_target_eid[i] == 0) {
                    m->llama_attack_target_eid[i] = -1;
                    m->llama_attack_target_kind[i] = 0;
                    m->llama_ranged_attack_time[i] = -1;
                    m->llama_ranged_see_time[i] = 0;
                }
                if (m->llama_attack_target_eid[i] > 0) {
                    llama_target_slot = mob_slot_by_eid(
                        m, m->llama_attack_target_eid[i]);
                    if (llama_target_slot <= 0
                            || !nx->alive[llama_target_slot]
                            || nx->type[llama_target_slot] != EW_TYPE_WOLF
                            || m->tameable_tamed[llama_target_slot]
                            || m->entity_dimension[llama_target_slot]
                                != dimension) {
                        llama_target_slot = -1;
                    } else {
                        double tdx = nx->x[llama_target_slot] - nx->x[i];
                        double tdy = nx->y[llama_target_slot] - nx->y[i];
                        double tdz = nx->z[llama_target_slot] - nx->z[i];
                        if (tdx * tdx + tdy * tdy + tdz * tdz > 100.0D)
                            llama_target_slot = -1;
                    }
                    if (llama_target_slot > 0) {
                        llama_ranged = 1;
                    } else {
                        m->llama_attack_target_eid[i] = -1;
                        m->llama_attack_target_kind[i] = 0;
                        m->llama_ranged_attack_time[i] = -1;
                        m->llama_ranged_see_time[i] = 0;
                    }
                }
                if (!llama_ranged && m->llama_attack_target_eid[i] < 0
                        && setup_tick) {
                    llama_target_slot = llama_defend_wolf_try_acquire(
                        m, w, nx, i, dimension);
                    if (llama_target_slot > 0) {
                        m->llama_attack_target_eid[i] =
                            nx->id[llama_target_slot];
                        m->llama_attack_target_kind[i] = 2;
                        llama_ranged = 1;
                    }
                }
                if (m->llama_caravan_head_eid[i] > 0
                        || (setup_tick
                            && gm_mobs_llama_caravan_try_join(
                                m, nx->id[i])))
                    llama_caravan = gm_mobs_llama_caravan_step(
                        m, nx->id[i],
                        &llama_caravan_x, &llama_caravan_y,
                        &llama_caravan_z, &llama_caravan_speed);
            }
            if (gm_mobs_horse_type(type)
                    && m->skeleton_trap_rider_eid[i] >= 0
                    && (m->passive_tasks[i] & PAI_BIT(PAI_WANDER))
                    && !nx->path_len[i])
                m->passive_tasks[i] &= ~PAI_BIT(PAI_WANDER);
            int mate_reset_this_tick = 0;
            int crazy_reset_this_tick = 0;
            if (gm_mobs_horse_type(type) && m->horse_crazy_active[i]
                    && (!ride_is_slot(nx, i, m->horse_ride_eid)
                        || !nx->path_len[i]
                        || pai_path_done(w, nx, i))) {
                m->horse_crazy_active[i] = 0;
                nx->path_len[i] = 0;
                crazy_reset_this_tick = 1;
            }
            if (llama_caravan || llama_ranged) {
                m->sheep_mate_active[i] = 0;
                m->sheep_mate_eid[i] = -1;
                m->sheep_mate_delay[i] = 0;
            } else if (m->panic_ticks[i] > 0) {
                m->horse_crazy_active[i] = 0;
                m->sheep_mate_active[i] = 0;
                m->sheep_mate_eid[i] = -1;
                m->sheep_mate_delay[i] = 0;
                if (m->sheep_eat_timer[i] > 0)
                    m->sheep_eat_timer[i] = 0;
            } else {
                if (gm_mobs_horse_type(type)
                        && (type == EW_TYPE_HORSE
                            || type == EW_TYPE_DONKEY
                            || type == EW_TYPE_MULE)
                        && !m->horse_crazy_active[i]
                        && !crazy_reset_this_tick && setup_tick
                        && ride_is_slot(nx, i, m->horse_ride_eid)
                        && !(m->horse_status[i] & GM_HORSE_TAME)) {
                    double target_x, target_y, target_z;
                    if (horse_crazy_random_position(
                            m, w, nx, i,
                            &target_x, &target_y, &target_z)) {
                        int bx = mc_floor(target_x);
                        int by = mc_floor(target_y);
                        int bz = mc_floor(target_z);
                        m->horse_crazy_active[i] = 1;
                        nx->path_tx[i] = bx + 1.0D;
                        nx->path_ty[i] = by;
                        nx->path_tz[i] = bz + 1.0D;
                        nx->path_len[i] = by > 0
                            && solid_id(gm_world_block(w, bx, by - 1, bz))
                            && !solid_id(gm_world_block(w, bx, by, bz))
                            && !solid_id(gm_world_block(w, bx, by + 1, bz));
                        m->passive_nav_speed[i] = 1.2D;
                    }
                }
                if (m->horse_crazy_active[i]) {
                    horse_crazy = 1;
                    m->sheep_mate_active[i] = 0;
                    m->sheep_mate_eid[i] = -1;
                    m->sheep_mate_delay[i] = 0;
                    if (gm_mobs_horse_crazy_attempt(m, nx->id[i])
                            == GM_HORSE_TAME_FAILED)
                        horse_dismount_player(
                            w, window, nx, st, i, p,
                            m->represented_player_primary_right, ox, oz);
                }
                if (!horse_crazy) {
                int mate_slot = mob_slot_by_eid(
                    m, m->sheep_mate_eid[i]);
                if (m->sheep_mate_active[i]
                        && (mate_slot <= 0 || mate_slot >= EW_MAX_ENTITIES
                            || !nx->alive[mate_slot]
                            || m->entity_dimension[mate_slot] != dimension
                            || !animal_mate_compatible(
                                m, nx, i, mate_slot)
                            || m->sheep_mate_delay[i] >= 60)) {
                    m->sheep_mate_active[i] = 0;
                    m->sheep_mate_eid[i] = -1;
                    m->sheep_mate_delay[i] = 0;
                    mate_reset_this_tick = 1;
                }
                if (!m->sheep_mate_active[i] && !mate_reset_this_tick
                        && setup_tick
                        && m->sheep_in_love[i] > 0) {
                    mate_slot = animal_nearest_mate_slot(m, nx, i, dimension);
                    if (mate_slot >= 0) {
                        m->sheep_mate_active[i] = 1;
                        m->sheep_mate_eid[i] = nx->id[mate_slot];
                        m->sheep_mate_delay[i] = 0;
                        /* Higher-priority EntityAIMate conflicts with and
                         * resets a running EntityAIEatGrass task. */
                        if (type == EW_TYPE_SHEEP)
                            m->sheep_eat_timer[i] = 0;
                    }
                }
                if (m->sheep_mate_active[i]) {
                    mate_slot = mob_slot_by_eid(
                        m, m->sheep_mate_eid[i]);
                    animal_mating = 1;
                    ++m->sheep_mate_delay[i];
                    double mdx = nx->x[i] - nx->x[mate_slot];
                    double mdy = nx->y[i] - nx->y[mate_slot];
                    double mdz = nx->z[i] - nx->z[mate_slot];
                    if (m->sheep_mate_delay[i] >= 60
                            && mdx * mdx + mdy * mdy + mdz * mdz < 9.0) {
                        /* The standalone runtime's event cursor is lazy.
                         * Reconcile it only on this causal spawn boundary, so
                         * inactive breeding adds no global tick mutation. */
                        if (next_entity_id
                                && *next_entity_id < m->next_id)
                            *next_entity_id = m->next_id;
                        GmSheepMateResult birth;
                        int birth_result = animal_breed_slots(
                            m, nx, i, mate_slot, 0, 1,
                            world_random_seed48, math_random_seed48,
                            next_entity_id, do_mob_loot, &birth);
                        if (birth_result == GM_SHEEP_MATE_BORN) {
                            if (birth.child_slot >= 0
                                    && same_tick_spawn_count
                                        < EW_MAX_ENTITIES * 2)
                                same_tick_spawns[same_tick_spawn_count++] =
                                    (GmSameTickSpawn){
                                        GM_SAME_TICK_ANIMAL, birth.child_slot};
                            if (birth.xp_slot >= 0
                                    && birth.xp_slot < xp_slot_limit(m)
                                    && same_tick_spawn_count
                                        < EW_MAX_ENTITIES * 2) {
                                if (birth.xp_slot < GM_XP_ORBS)
                                    spawned_xp[birth.xp_slot] = 1;
                                same_tick_spawns[same_tick_spawn_count++] =
                                    (GmSameTickSpawn){
                                        GM_SAME_TICK_XP, birth.xp_slot};
                            }
                        }
                    }
                } else if (type == EW_TYPE_SHEEP
                        && m->sheep_eat_timer[i] > 0) {
                    (void)sheep_graze_update_slot(
                        m, w, nx, i, mob_griefing != 0);
                    sheep_grazing = 1;
                } else if (type == EW_TYPE_SHEEP && setup_tick) {
                    if (sheep_graze_begin_slot(m, w, nx, i)) {
                        /* EntityAITasks calls updateTask on the start tick. */
                        (void)sheep_graze_update_slot(
                            m, w, nx, i, mob_griefing != 0);
                        sheep_grazing = 1;
                    } else {
                        sheep_lower_rng = 1;
                    }
                }
                if (sheep_lower_rng)
                    animal_declined_lower_task_rng(
                        m, i, animal_player_distance_sq);
                else if (type != EW_TYPE_SHEEP && setup_tick
                        && !m->sheep_mate_active[i]) {
                    if (type == EW_TYPE_LLAMA) {
                        /* Its runnable lower goals consume the entity's real
                         * java.util.Random in pai_tick below. */
                    } else if (gm_mobs_horse_type(type)
                            && m->skeleton_trap_rider_eid[i] >= 0)
                        horse_wandering_exact =
                            skeleton_trap_horse_lower_tasks(
                                m, w, nx, i,
                                animal_player_distance_sq);
                    else
                        animal_declined_lower_task_rng(
                            m, i, animal_player_distance_sq);
                }
                }
            }
            if (type == EW_TYPE_LLAMA)
                llama_follow_parent_move = llama_follow_parent_tick(
                    m, nx, i, dimension, setup_tick,
                    &llama_follow_parent_x, &llama_follow_parent_y,
                    &llama_follow_parent_z);
        }
        if (trap_should_activate
                && skeleton_trap_activate_store(
                    m, nx, now->id[i], 0.0F,
                    m->active_entity_seed_generator_seed48,
                    m->active_server_uuid_random_seed48,
                    math_random_seed48, next_entity_id) == 7)
            initial_loaded_count = m->loaded_order_count;
        if (type == EW_TYPE_VILLAGER && !m->controlled_no_ai[i]) {
            int setup_tick = m->villager_ai_tick_count[i]++ % 3 == 0;
            int liquid = m->entity_in_water[i] || m->entity_in_lava[i];
            int mate = iron_golem_slot_by_eid(
                m, nx, m->villager_mate_eid[i]);
            ++m->entity_age[i];
            if (villager_player_distance_valid(
                    nx, i, px, py, pz, 1024.0D))
                m->entity_age[i] = 0;
            if (m->villager_swim_active[i] && !liquid)
                m->villager_swim_active[i] = 0;
            if (!m->villager_swim_active[i] && setup_tick && liquid)
                m->villager_swim_active[i] = 1;
            if (m->villager_swim_active[i]
                    && jrand_float(
                        &m->entity_random[i].random) < 0.8F)
                villager_swim_jump = 1;
            if (nx->path_len[i]
                    && fabs(nx->x[i] - nx->path_tx[i]) < 0.45D
                    && fabs(nx->y[i] - nx->path_ty[i]) < 1.0D
                    && fabs(nx->z[i] - nx->path_tz[i]) < 0.45D)
                nx->path_len[i] = 0;
            if (m->villager_trade_active[i]
                    && !m->villager_swim_active[i])
                villager_trading = villager_trade_tick(
                    m, nx, i, setup_tick, v->health > 0.0F,
                    px, py, pz);
            if (!villager_trading)
                villager_avoiding = villager_avoid_tick(
                    m, w, nx, i, dimension, setup_tick);
            if (!villager_avoiding && !m->villager_swim_active[i])
                villager_trading = villager_trade_tick(
                    m, nx, i, setup_tick, v->health > 0.0F,
                    px, py, pz);
            else if (m->villager_trade_active[i]) {
                m->villager_trade_active[i] = 0;
                if (m->active_villager_customer_eid == nx->id[i])
                    m->active_villager_customer_eid = -1;
            }
            villager_trade_looking = villager_trade_look_tick(
                m, nx, i, setup_tick, v->health > 0.0F,
                px, py, pz);
            if (villager_trading) {
                m->villager_move_indoors_active[i] = 0;
                m->villager_move_restriction_active[i] = 0;
                m->villager_harvest_active[i] = 0;
                if (m->villager_mate_active[i]) villager_reset_mate(m, i);
                if (m->villager_follow_golem_active[i])
                    villager_follow_golem_reset(m, nx, i);
                if (m->villager_play_active[i])
                    villager_play_reset(m, nx, i);
                mate = -1;
            }
            if (villager_trade_looking) {
                if (m->villager_mate_active[i]) villager_reset_mate(m, i);
                if (m->villager_follow_golem_active[i])
                    villager_follow_golem_reset(m, nx, i);
                mate = -1;
            }
            if (villager_avoiding) {
                m->villager_move_indoors_active[i] = 0;
                m->villager_move_restriction_active[i] = 0;
                m->villager_harvest_active[i] = 0;
                if (m->villager_mate_active[i]) villager_reset_mate(m, i);
                if (m->villager_follow_golem_active[i])
                    villager_follow_golem_reset(m, nx, i);
                if (m->villager_play_active[i])
                    villager_play_reset(m, nx, i);
                mate = -1;
            } else if (!villager_trading) {
                villager_moving_indoors = villager_move_indoors_tick(
                    m, w, nx, i, !day, setup_tick);
            }
            if (villager_moving_indoors) {
                m->villager_move_restriction_active[i] = 0;
                m->villager_harvest_active[i] = 0;
                if (m->villager_mate_active[i]) villager_reset_mate(m, i);
                if (m->villager_follow_golem_active[i])
                    villager_follow_golem_reset(m, nx, i);
                mate = -1;
            }
            villager_restrict_door_tick(m, nx, i, day, setup_tick);
            villager_open_door_tick(m, w, nx, i, setup_tick);
            if (!villager_avoiding && !villager_trading
                    && !villager_moving_indoors)
                villager_moving_restriction =
                    villager_move_restriction_tick(
                        m, w, nx, i, setup_tick);
            if (villager_moving_restriction) {
                m->villager_harvest_active[i] = 0;
                if (m->villager_mate_active[i]) villager_reset_mate(m, i);
                if (m->villager_follow_golem_active[i])
                    villager_follow_golem_reset(m, nx, i);
                mate = -1;
            }
            if (m->villager_follow_golem_active[i]) {
                int golem = iron_golem_slot_by_eid(
                    m, nx, m->villager_follow_golem_eid[i]);
                if (golem <= 0 || !nx->alive[golem]
                        || nx->type[golem] != EW_TYPE_IRON_GOLEM
                        || m->entity_dimension[golem] != dimension
                        || m->golem_hold_rose_tick[golem] <= 0)
                    villager_follow_golem_reset(m, nx, i);
            }
            if (m->villager_mate_active[i]
                    && (mate <= 0 || !nx->alive[mate]
                        || nx->type[mate] != EW_TYPE_VILLAGER
                        || m->entity_dimension[mate] != dimension
                        || m->villager_mating_timeout[i] < 0
                        || !villager_sufficient_doors(m, i)
                        || m->growing_age[i] != 0
                        || !m->villager_willing[i])) {
                villager_reset_mate(m, i);
                mate = -1;
            }
            if (!villager_avoiding && !villager_trading
                    && !villager_moving_indoors && !villager_moving_restriction
                    && !villager_trade_looking
                    && !m->villager_mate_active[i] && setup_tick
                    && m->growing_age[i] == 0
                    && jrand_int_bound(
                        &m->entity_random[i].random, 500) == 0
                    && villager_sufficient_doors(m, i)
                    && villager_update_willing(m, nx, i, 1)) {
                mate = villager_nearest_mate_slot(m, nx, i, dimension);
                if (mate > 0 && m->growing_age[mate] == 0
                        && villager_update_willing(m, nx, mate, 1)) {
                    m->villager_mate_active[i] = 1;
                    m->villager_mating[i] = 1;
                    m->villager_mate_eid[i] = nx->id[mate];
                    m->villager_mating_timeout[i] = 300;
                }
            }
            if (m->villager_mate_active[i]) {
                m->villager_harvest_active[i] = 0;
                mate = iron_golem_slot_by_eid(
                    m, nx, m->villager_mate_eid[i]);
                --m->villager_mating_timeout[i];
                if (mate > 0) {
                    double mdx = nx->x[mate] - now->x[i];
                    double mdy = nx->y[mate] - now->y[i];
                    double mdz = nx->z[mate] - now->z[i];
                    double distance = mdx * mdx + mdy * mdy + mdz * mdz;
                    nx->yaw[i] = ehs_yaw_toward(mdx, mdz);
                    if (distance > 2.25D) {
                        villager_mating = 1;
                    } else if (m->villager_mating_timeout[i] == 0
                            && m->villager_mating[mate]) {
                        int child_slot = -1;
                        if (villager_breed_slots(
                                m, nx, i, mate,
                                world_random_seed48,
                                math_random_seed48,
                                next_entity_id, &child_slot)
                                && child_slot > 0
                                && same_tick_spawn_count
                                    < EW_MAX_ENTITIES * 2)
                            same_tick_spawns[same_tick_spawn_count++] =
                                (GmSameTickSpawn){
                                    GM_SAME_TICK_VILLAGER, child_slot};
                    }
                }
                if (jrand_int_bound(
                        &m->entity_random[i].random, 35) == 0)
                    mob_event_append(
                        m, GM_MOB_EVENT_ENTITY_STATUS, nx->id[i], 12,
                        nx->x[i], nx->y[i], nx->z[i], 0.0F, 0.0F);
            }
            if (!villager_avoiding && !villager_trading
                    && !villager_moving_indoors && !villager_moving_restriction
                    && !m->villager_mate_active[i]
                    && m->growing_age[i] >= 0
                    && m->villager_profession[i] == 0)
                villager_harvesting = villager_harvest_tick(
                    m, w, nx, i, setup_tick, mob_griefing,
                    world_random_seed48, math_random_seed48,
                    next_entity_id, drops);
            if (m->villager_mate_active[i]) {
                if (m->villager_follow_golem_active[i])
                    villager_follow_golem_reset(m, nx, i);
            } else if (!villager_avoiding && !villager_trading
                    && !villager_moving_indoors
                    && !villager_moving_restriction
                    && !villager_harvesting) {
                if (!m->villager_follow_golem_active[i] && setup_tick)
                    (void)villager_follow_golem_start(
                        m, nx, i, dimension, day);
                if (m->villager_follow_golem_active[i]) {
                    villager_follow_golem_update(m, nx, i, dimension);
                    villager_following =
                        m->villager_follow_golem_active[i] != 0;
                }
            }
            if (villager_avoiding || villager_trading
                    || villager_moving_indoors
                    || villager_moving_restriction
                    || m->villager_mate_active[i]
                    || m->villager_follow_golem_active[i]
                    || villager_harvesting) {
                if (m->villager_play_active[i])
                    villager_play_reset(m, nx, i);
                if (m->villager_interact_active[i])
                    villager_interact_reset(m, i);
            } else {
                villager_playing_task = villager_play_tick(
                    m, w, nx, i, dimension, setup_tick);
                if (villager_playing_task) {
                    if (m->villager_interact_active[i])
                        villager_interact_reset(m, i);
                }
            }
            {
                int tail_blocked = villager_avoiding || villager_trading
                    || villager_trade_looking || villager_moving_indoors
                    || villager_moving_restriction
                    || m->villager_mate_active[i]
                    || m->villager_follow_golem_active[i]
                    || villager_harvesting || villager_playing_task;
                if (tail_blocked) {
                    m->villager_watch_player_active[i] = 0;
                    m->villager_watch_player_time[i] = 0;
                    if (m->villager_interact_active[i])
                        villager_interact_reset(m, i);
                    m->villager_wander_active[i] = 0;
                } else {
                    int player_watch = villager_watch_player_tick(
                        m, nx, i, setup_tick,
                        !m->villager_interact_active[i]
                            && !m->villager_wander_active[i],
                        v->health > 0.0F, px, py, pz);
                    if (player_watch) {
                        if (m->villager_interact_active[i])
                            villager_interact_reset(m, i);
                        m->villager_wander_active[i] = 0;
                    } else if (!m->villager_wander_active[i]) {
                        (void)villager_interact_tick(
                            m, nx, i, dimension, setup_tick, st,
                            math_random_seed48, next_entity_id, drops);
                    }
                    if (!m->villager_watch_player_active[i]
                            && !m->villager_interact_active[i])
                        villager_wandering = villager_wander_tick(
                            m, w, nx, i, setup_tick, 1);
                }
                int living_watch_blocked = villager_trade_looking
                    || m->villager_mate_active[i]
                    || m->villager_follow_golem_active[i]
                    || m->villager_watch_player_active[i]
                    || m->villager_interact_active[i];
                if (living_watch_blocked) {
                    if (m->villager_watch_living_active[i])
                        villager_watch_living_reset(m, i);
                } else {
                    (void)villager_watch_living_tick(
                        m, nx, i, dimension, setup_tick, 1);
                }
            }
        }
        if (type == EW_TYPE_BOAT) {
            if (m->boat_damage[i] > 0.0F) m->boat_damage[i] -= 1.0F;
            tick_boat(
                m, w, nx, i, window, st,
                p, ox, oz, boat_fwd, boat_str, 0, drops);
            continue;
        }
        if (type == EW_TYPE_SNOWMAN) {
            if (m->snowman_target_eid[i] > 0) {
                snowman_target_slot = mob_slot_by_eid(
                    m, m->snowman_target_eid[i]);
                if (!snowman_target_valid(
                        m, w, nx, i, snowman_target_slot,
                        dimension, 0)) {
                    snowman_target_slot = -1;
                } else if (snowman_target_visible(
                        m, w, nx, i, snowman_target_slot)) {
                    m->snowman_target_unseen_ticks[i] = 0;
                } else if (++m->snowman_target_unseen_ticks[i] > 60) {
                    snowman_target_slot = -1;
                }
                if (snowman_target_slot <= 0) {
                    m->snowman_target_eid[i] = -1;
                    m->snowman_target_unseen_ticks[i] = 0;
                    m->snowman_ranged_attack_time[i] = -1;
                    m->snowman_ranged_see_time[i] = 0;
                    nx->path_len[i] = 0;
                }
            }
            int target_setup = m->snowman_target_task_tick[i]++ % 3 == 0;
            if (snowman_target_slot <= 0 && target_setup) {
                snowman_target_slot = snowman_try_acquire_target(
                    m, w, nx, i, dimension);
                if (snowman_target_slot > 0) {
                    m->snowman_target_eid[i] = nx->id[snowman_target_slot];
                    m->snowman_target_unseen_ticks[i] = 0;
                }
            }
            snowman_ranged = snowman_target_slot > 0;
        }
        int hostile=gm_hostile(type);
        if(type!=EW_TYPE_BLAZE && !trap_rider
                && nx->attack_time[i]>0)
            --nx->attack_time[i];
        if (type == EW_TYPE_PIGMAN && m->anger[i] > 0) --m->anger[i];
        double target_x = px, target_y = py, target_z = pz;
        float target_height = 1.8F;
        float target_eye_height = PSV_EYE_HEIGHT;
        double dx=px-now->x[i],dy=py-now->y[i],dz=pz-now->z[i];
        double d=sqrt(dx*dx+dy*dy+dz*dz), xz=sqrt(dx*dx+dz*dz);
        if (type == EW_TYPE_LLAMA && llama_ranged
                && llama_target_slot > 0) {
            float target_width;
            target_x = nx->x[llama_target_slot];
            target_y = nx->y[llama_target_slot];
            target_z = nx->z[llama_target_slot];
            ehs_size_scaled(
                nx->type[llama_target_slot], m->size[llama_target_slot],
                &target_width, &target_height);
            (void)target_width;
            target_eye_height = target_height * 0.85F;
            dx = target_x - now->x[i];
            dy = target_y - now->y[i];
            dz = target_z - now->z[i];
            d = sqrt(dx * dx + dy * dy + dz * dz);
            xz = sqrt(dx * dx + dz * dz);
        }
        if (type == EW_TYPE_SNOWMAN && snowman_ranged) {
            target_x = nx->x[snowman_target_slot];
            target_y = nx->y[snowman_target_slot];
            target_z = nx->z[snowman_target_slot];
            target_eye_height = mob_eye_height(
                m, nx, snowman_target_slot);
            {
                float target_width;
                ehs_size_scaled(
                    nx->type[snowman_target_slot],
                    m->size[snowman_target_slot],
                    &target_width, &target_height);
                (void)target_width;
            }
            dx = target_x - now->x[i];
            dy = target_y - now->y[i];
            dz = target_z - now->z[i];
            d = sqrt(dx * dx + dy * dy + dz * dz);
            xz = sqrt(dx * dx + dz * dz);
        }
        if (type == EW_TYPE_ELDER_GUARDIAN
                && (m->entity_ticks_existed[i] + nx->id[i]) % 1200 == 0
                && d * d < 2500.0
                && m->guardian_curse_pending_eid == 0)
            m->guardian_curse_pending_eid = nx->id[i];
        if(hostile && !m->persistence_required[i]){
            if(d>GM_MOB_DESPAWN_HARD){
                loaded_invalidate_living(m, i);
                nx->alive[i]=0;nx->type[i]=EW_TYPE_NONE;continue;
            }
            if(d>GM_MOB_DESPAWN_SOFT){
                if(++m->despawn_ticks[i]>=GM_MOB_DESPAWN_DELAY){
                    loaded_invalidate_living(m, i);
                    nx->alive[i]=0;nx->type[i]=EW_TYPE_NONE;continue;
                }
            }else m->despawn_ticks[i]=0;
        }
        if (trap_rider)
            skeleton_trap_rider_sunlight_tick(
                m, w, nx, i, day);
        if (trap_rider && m->skeleton_trap_hand_active[i]
                && m->skeleton_trap_item_use_count[i] < UCHAR_MAX)
            ++m->skeleton_trap_item_use_count[i];
        if (trap_rider)
            (void)skeleton_trap_rider_ai_tick(
                m, w, nx, i, px, py, pz);
        if (trap_rider && m->skeleton_trap_target_eid[i] > 0) {
            int target_slot = mob_slot_by_eid(
                m, m->skeleton_trap_target_eid[i]);
            if (target_slot > 0 && nx->alive[target_slot]) {
                target_x = nx->x[target_slot];
                target_y = nx->y[target_slot];
                target_z = nx->z[target_slot];
                if (nx->type[target_slot] == EW_TYPE_SKELETON) {
                    target_height = 1.99F;
                    target_eye_height = 1.74F;
                } else {
                    float target_width;
                    ehs_size_scaled(
                        nx->type[target_slot], m->size[target_slot],
                        &target_width, &target_height);
                    (void)target_width;
                    target_eye_height = target_height * 0.85F;
                }
                dx = target_x - now->x[i];
                dy = target_y - now->y[i];
                dz = target_z - now->z[i];
                d = sqrt(dx * dx + dy * dy + dz * dz);
                xz = sqrt(dx * dx + dz * dz);
            }
        }
        if(day&&((gm_zombie(type)&&type!=EW_TYPE_HUSK)
                    ||type==EW_TYPE_SKELETON||type==EW_TYPE_STRAY)
                && !trap_rider&&
           m->fire_ticks[i]<=0&&sky_exposed(w,now->x[i],now->y[i],now->z[i]))
            m->fire_ticks[i]=GM_MOB_FIRE_TICKS;
        /* Entity.setOnFireFromLava calls setFire(15). The live damage model is
         * coarser, but preserving the 300-tick burning state is what makes
         * EntityAIPanic's burning trigger and water search reachable. */
        if(!exact_ridden_server_tick&&type!=EW_TYPE_WITCH
                &&!mob_exact_environment_type(type)
                &&m->fire_ticks[i]>0){
            --m->fire_ticks[i];
            if(m->fire_ticks[i]%20==0
                    && !m->entity_fire_resistance_this_tick[i]){
                float applied = mob_resistance_damage(m, i, 1.0F);
                applied = mob_absorb_damage(m, i, applied);
                mark_hurt(m, nx, i);
                nx->health[i]-=applied;
                if(nx->health[i]<=0.0f){mob_drop(m,nx,i,drops);continue;}
            }
        }
        int aggro=0, witch_visible=0;
        if(hostile){
            int wants=1;
            if(type==EW_TYPE_GIANT)wants=0;
            else if(type==EW_TYPE_ENDERMAN)wants=m->hurt_aggro[i];
            else if(gm_spider(type))wants=!day||m->hurt_aggro[i];
            else if(type==EW_TYPE_PIGMAN)wants=m->anger[i]>0;
            else if(type==EW_TYPE_SLIME)wants=m->size[i]>1;
            else if(type==EW_TYPE_GUARDIAN
                    || type==EW_TYPE_ELDER_GUARDIAN)
                wants=d*d>9.0;
            if(wants&&d<=follow_range(type)){
                float mw,mh;ehs_size_scaled((u8)type,m->size[i],&mw,&mh);
                if(type==EW_TYPE_GHAST)
                    aggro=1; /* ghast doesn't need tight LOS for targeting */
                else {
                    int visible = los_clear(
                        w,now->x[i],now->y[i]+mh*0.85,now->z[i],
                        px,py+PSV_EYE_HEIGHT,pz);
                    if (type == EW_TYPE_WITCH) {
                        witch_visible = visible;
                        aggro = 1;
                    } else {
                        aggro = visible;
                    }
                }
            }
        }
        if (trap_rider)
            aggro = m->skeleton_trap_bow_running[i]
                && m->skeleton_trap_target_eid[i] >= 0;
        if (type == EW_TYPE_POLAR_BEAR && m->growing_age[i] >= 0
                && v->health > 0.0F) {
            double distance_sq = dx * dx + dy * dy + dz * dz;
            if (m->polar_player_target[i]) {
                if (distance_sq <= 400.0D)
                    polar_aggro = 1;
                else
                    m->polar_player_target[i] = 0;
            } else if (distance_sq <= 100.0D) {
                double bear_x = nx->x[i], bear_y = nx->y[i];
                double bear_z = nx->z[i];
                int cursor = 0, child;
                while ((child = living_next_slot_from_store(
                            m, nx, &cursor)) > 0) {
                    if (!nx->alive[child]
                            || nx->type[child] != EW_TYPE_POLAR_BEAR
                            || m->growing_age[child] >= 0
                            || m->entity_dimension[child] != dimension)
                        continue;
                    double child_dx = nx->x[child] - bear_x;
                    double child_dy = nx->y[child] - bear_y;
                    double child_dz = nx->z[child] - bear_z;
                    if (fabs(child_dx) <= 8.0D
                            && fabs(child_dy) <= 4.0D
                            && fabs(child_dz) <= 8.0D) {
                        m->polar_player_target[i] = 1;
                        polar_aggro = 1;
                        break;
                    }
                }
                living_cold_flush_one_from_store(
                    m, nx, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
                    &m->living_staged_cold_secondary);
            }
        }
        if (type == EW_TYPE_RABBIT && m->rabbit_type[i] == 99
                && v->health > 0.0F && d * d <= 256.0D)
            rabbit_killer = 1;
        if (type == EW_TYPE_RABBIT && !rabbit_killer && mob_griefing
                && m->rabbit_carrot_ticks[i] == 0) {
            double best = 1.0e30;
            int cx = mc_floor(now->x[i]);
            int cy = mc_floor(now->y[i]);
            int cz = mc_floor(now->z[i]);
            if (m->rabbit_raid_valid[i]
                    && gm_world_block(
                        w, m->rabbit_raid_x[i], m->rabbit_raid_y[i],
                        m->rabbit_raid_z[i]) == 141
                    && gm_world_meta(
                        w, m->rabbit_raid_x[i], m->rabbit_raid_y[i],
                        m->rabbit_raid_z[i]) == 7) {
                rabbit_raiding = 1;
                rabbit_carrot_x = m->rabbit_raid_x[i];
                rabbit_carrot_y = m->rabbit_raid_y[i];
                rabbit_carrot_z = m->rabbit_raid_z[i];
            } else {
                m->rabbit_raid_valid[i] = 0;
            }
            if (!rabbit_raiding
                    && m->entity_ticks_existed[i] % 10 == 1)
            for (int oy = -1; oy <= 1; ++oy)
                for (int ox2 = -16; ox2 <= 16; ++ox2)
                    for (int oz2 = -16; oz2 <= 16; ++oz2) {
                        int bx = cx + ox2, by = cy + oy, bz = cz + oz2;
                        if (gm_world_block(w, bx, by, bz) != 141
                                || gm_world_meta(w, bx, by, bz) != 7
                                || gm_world_block(w, bx, by - 1, bz) != 60)
                            continue;
                        double rx = bx + 0.5D - now->x[i];
                        double ry = by - now->y[i];
                        double rz = bz + 0.5D - now->z[i];
                        double distance = rx * rx + ry * ry + rz * rz;
                        if (distance < best) {
                            best = distance;
                            rabbit_raiding = 1;
                            rabbit_carrot_x = bx;
                            rabbit_carrot_y = by;
                            rabbit_carrot_z = bz;
                        }
                    }
            if (rabbit_raiding) {
                m->rabbit_raid_valid[i] = 1;
                m->rabbit_raid_x[i] = rabbit_carrot_x;
                m->rabbit_raid_y[i] = rabbit_carrot_y;
                m->rabbit_raid_z[i] = rabbit_carrot_z;
            }
        }
        if (type == EW_TYPE_WITCH)
            (void)witch_self_potion_step_slot(
                m, nx, i,
                gm_uw_eye_inside_water(
                    w, nx->x[i], nx->y[i], nx->z[i], 1.62F),
                m->fire_ticks[i] > 0, aggro, d * d);
        int evoker_casting = type == EW_TYPE_EVOKER
            && tick_evoker_spells(
                m, w, st, nx, i, aggro, px, py, pz, mob_griefing);
        int moving=0,jump=0,wandering=0,swim_jump=0;
        int llama_lower_ready = 0;
        int llama_lower_moving = 0, llama_lower_jump = 0;
        int llama_lower_wandering = 0;
        int llama_panic_active = 0;
        double llama_lower_nav_speed = 0.0D;
        int pet_sitting = 0, pet_following = 0;
        double nav_speed=1.0;
        if (type == EW_TYPE_VILLAGER)
            swim_jump = villager_swim_jump;
        if (type == EW_TYPE_LLAMA && passive
                && !horse_movement_blocked) {
            int external_priority = 99;
            int external_mutex = 0;
            if (llama_caravan) {
                external_priority = 2;
                external_mutex = 1;
            } else if (llama_ranged) {
                external_priority = 3;
                external_mutex = 3;
            } else if (animal_mating) {
                external_priority = 4;
                external_mutex = 3;
            }
            pai_tick(
                m, w, nx, i, px, py, pz, mob_griefing,
                &llama_lower_moving, &llama_lower_jump,
                &llama_lower_wandering, &swim_jump,
                &llama_lower_nav_speed,
                external_priority, external_mutex, 1);
            llama_panic_active =
                (m->passive_tasks[i] & PAI_BIT(PAI_PANIC)) != 0;
            if (llama_panic_active && m->sheep_mate_active[i]) {
                m->sheep_mate_active[i] = 0;
                m->sheep_mate_eid[i] = -1;
                m->sheep_mate_delay[i] = 0;
                animal_mating = 0;
            }
            llama_lower_ready = 1;
        }
        if (tameable_type(type)) {
            m->tameable_sitting[i] = m->tameable_sit_requested[i];
            pet_sitting = m->tameable_sitting[i] != 0;
            if (pet_sitting) {
                m->tameable_following[i] = 0;
                nx->path_len[i] = 0;
            } else {
                pet_following = tameable_follow_tick(
                    m, w, nx, i, px, py, pz, d * d, &nav_speed);
            }
        }
        /* AIFireballAttack.resetTask: clear ON_FIRE when no target. */
        if(!aggro&&type==EW_TYPE_BLAZE){
            m->blaze_on_fire[i]=0;
            m->charge[i]=0;
            m->blaze_attacking[i]=0;
            m->blaze_charged[i]=0;
        }

        if (type == EW_TYPE_VILLAGER && villager_trading) {
            nx->ai_state[i] = EW_AI_IDLE;
            nx->path_len[i] = 0;
        }else if (type == EW_TYPE_VILLAGER && villager_avoiding) {
            nx->ai_state[i] = EW_AI_CHASE;
            nav_speed = m->villager_avoid_speed[i];
            m->passive_nav_speed[i] = nav_speed;
            moving = nx->path_len[i] == 1;
        }else if (type == EW_TYPE_VILLAGER && villager_moving_indoors) {
            nx->ai_state[i] = EW_AI_CHASE;
            nav_speed = 1.0D;
            m->passive_nav_speed[i] = nav_speed;
            moving = nx->path_len[i] == 1;
        }else if (type == EW_TYPE_VILLAGER
                && villager_moving_restriction) {
            nx->ai_state[i] = EW_AI_CHASE;
            nav_speed = 0.6D;
            m->passive_nav_speed[i] = nav_speed;
            moving = nx->path_len[i] == 1;
        }else if (type == EW_TYPE_VILLAGER && villager_mating) {
            int mate = iron_golem_slot_by_eid(
                m, nx, m->villager_mate_eid[i]);
            if (mate > 0) {
                nx->path_tx[i] = nx->x[mate];
                nx->path_ty[i] = nx->y[mate];
                nx->path_tz[i] = nx->z[mate];
                nx->path_len[i] = 1;
                nx->ai_state[i] = EW_AI_CHASE;
                nav_speed = 0.25D;
                m->passive_nav_speed[i] = nav_speed;
                moving = 1;
            }
        }else if (type == EW_TYPE_VILLAGER && villager_harvesting){
            nx->ai_state[i] = nx->path_len[i] == 1
                ? EW_AI_CHASE : EW_AI_IDLE;
            if (nx->path_len[i] == 1) {
                nav_speed = 0.6D;
                m->passive_nav_speed[i] = nav_speed;
                moving = 1;
            }
        }else if(type == EW_TYPE_VILLAGER && villager_following){
            nx->ai_state[i] = nx->path_len[i] == 1
                ? EW_AI_CHASE : EW_AI_IDLE;
            if (nx->path_len[i] == 1) {
                nav_speed = 0.5D;
                m->passive_nav_speed[i] = nav_speed;
                moving = 1;
            }
        }else if(type == EW_TYPE_VILLAGER && villager_playing_task){
            nx->ai_state[i] = nx->path_len[i] == 1
                ? EW_AI_CHASE : EW_AI_IDLE;
            if (nx->path_len[i] == 1) {
                nav_speed = 0.32D;
                m->passive_nav_speed[i] = nav_speed;
                moving = 1;
            }
        }else if(type == EW_TYPE_VILLAGER && villager_wandering){
            nx->ai_state[i] = nx->path_len[i] == 1
                ? EW_AI_CHASE : EW_AI_IDLE;
            nav_speed = 0.6D;
            m->passive_nav_speed[i] = nav_speed;
            moving = nx->path_len[i] == 1;
        }else if(type == EW_TYPE_VILLAGER){
            nx->ai_state[i] = nx->path_len[i] == 1
                ? EW_AI_CHASE : EW_AI_IDLE;
            nav_speed = m->passive_nav_speed[i] > 0.0
                ? m->passive_nav_speed[i] : 0.6D;
            moving = nx->path_len[i] == 1;
        }else if(type == EW_TYPE_BAT){
            int despawn = bat_despawn_entity(
                m, nx, i, px, py, pz);
            nx->path_len[i] = 0;
            nx->ai_state[i] = EW_AI_IDLE;
            bat_update_ai_tasks(
                m, w, nx, i, px, py, pz, v->health > 0.0F);
            /* EntityMoveHelper WAIT clears the value assigned by Bat AI,
             * then EntityLookHelper turns the head toward the current body. */
            m->passive_move_forward[i] = 0.0F;
            m->passive_move_strafe[i] = 0.0F;
            m->entity_pitch[i] = 0.0F;
            m->passive_head_pitch[i] = 0.0F;
            m->passive_head_yaw[i] = living_update_rotation_exact(
                m->passive_head_yaw[i],
                m->squid_render_yaw_offset[i], 10.0F);
            if (despawn) {
                retire_terminal_living(m, nx, i);
                continue;
            }
        }else if(trap_rider
                && (m->passive_tasks[i] & PAI_BIT(PAI_WANDER))){
            /* updateRidden overwrites the passenger position from its mount
             * after onUpdate, but its own travel still produces observable
             * motion and MoveHelper state. Keep the shared Path intact while
             * applying that travel; the horse advances the path index. */
            nx->ai_state[i] = EW_AI_CHASE;
            nav_speed = m->passive_nav_speed[i];
            moving = nx->path_len[i] != 0;
        }else if(llama_caravan){
            nx->path_len[i] = llama_caravan_navigation_target(
                m, w, now, i,
                llama_caravan_x, llama_caravan_y, llama_caravan_z,
                clock ? clock->total_time : world_time, 1, 0,
                &nx->path_tx[i], &nx->path_ty[i], &nx->path_tz[i]);
            nx->ai_state[i] = EW_AI_CHASE;
            nav_speed = llama_caravan_speed;
            m->passive_nav_speed[i] = nav_speed;
            moving = nx->path_len[i] != 0;
        }else if(snowman_ranged){
            double target_distance_sq = dx * dx + dy * dy + dz * dz;
            int visible = snowman_target_visible(
                m, w, now, i, snowman_target_slot);
            if (visible) ++m->snowman_ranged_see_time[i];
            else m->snowman_ranged_see_time[i] = 0;
            if (target_distance_sq <= 100.0D
                    && m->snowman_ranged_see_time[i] >= 20) {
                nx->path_len[i] = 0;
                nx->ai_state[i] = EW_AI_ATTACK;
            } else {
                nx->path_tx[i] = target_x;
                nx->path_ty[i] = target_y;
                nx->path_tz[i] = target_z;
                nx->path_len[i] = 1;
                nx->ai_state[i] = EW_AI_CHASE;
                nav_speed = 1.25D;
                m->passive_nav_speed[i] = nav_speed;
                moving = 1;
            }
            if (--m->snowman_ranged_attack_time[i] == 0) {
                if (visible && snowman_attack_live(
                        m, now, i, snowman_target_slot,
                        next_entity_id))
                    m->snowman_ranged_attack_time[i] = 20;
            } else if (m->snowman_ranged_attack_time[i] < 0) {
                m->snowman_ranged_attack_time[i] = 20;
            }
        }else if(llama_ranged){
            double target_distance_sq = dx * dx + dy * dy + dz * dz;
            int visible = los_clear(
                w, now->x[i], now->y[i] + 1.87D, now->z[i],
                target_x, target_y + (double)target_eye_height, target_z);
            if (visible) ++m->llama_ranged_see_time[i];
            else m->llama_ranged_see_time[i] = 0;
            if (target_distance_sq <= 400.0D
                    && m->llama_ranged_see_time[i] >= 20) {
                llama_navigation_clear_entity(m, w, now, i);
                m->llama_nav_goal_valid[i] = 0;
                m->llama_nav_goal_pending[i] = 0;
                nx->path_len[i] = 0;
                nx->ai_state[i] = EW_AI_ATTACK;
            } else {
                m->llama_nav_goal_valid[i] = 1;
                m->llama_nav_goal_pending[i] = 1;
                m->llama_nav_goal_x[i] = target_x;
                m->llama_nav_goal_y[i] = target_y;
                m->llama_nav_goal_z[i] = target_z;
                nx->ai_state[i] = EW_AI_CHASE;
                nav_speed = 1.25D;
                m->passive_nav_speed[i] = nav_speed;
                llama_ranged_move = 1;
            }
            if (--m->llama_ranged_attack_time[i] == 0) {
                if (visible && llama_spit_attack_live(
                        m, now, st, i,
                        target_x, target_y, target_z, target_height,
                        next_entity_id))
                    m->llama_ranged_attack_time[i] = 40;
            } else if (m->llama_ranged_attack_time[i] < 0) {
                m->llama_ranged_attack_time[i] = 40;
            }
        }else if(passive && horse_movement_blocked){
            /* EntityLivingBase skips goals, navigation, and controls while
             * AbstractHorse reports eating/rearing as movement-blocking.
             * Keep the copied rider Path and MoveHelper action intact. */
            nx->ai_state[i] = EW_AI_IDLE;
            moving = 0;
        }else if(passive && m->skeleton_trap_rider_eid[i] >= 0){
            /* A mounted EntityLiving rider copies its path into the vehicle
             * after the horse's own update. It becomes visible here on the
             * following loaded-list tick at the forced 1.5 speed. */
            if (m->skeleton_trap_move_wait_latched[i])
                nx->path_len[i] = 0;
            if (nx->path_len[i]
                    && !m->skeleton_trap_move_wait_latched[i]
                    && m->skeleton_trap_move_terminal_ticks[i] == 0) {
                int rider = mob_slot_by_eid(
                    m, m->skeleton_trap_rider_eid[i]);
                if (rider > 0
                        && (m->passive_tasks[rider]
                            & PAI_BIT(PAI_WANDER))) {
                    float waypoint = 1.3964844F * 0.5F;
                    /* PathNavigate.pathFollow compares against PathPoint
                     * center (+0.5), while Path.getPosition(horse) later
                     * feeds MoveHelper with the wider horse's +1 center. */
                    double final_x = nx->path_tx[i] - 0.5D;
                    double final_z = nx->path_tz[i] - 0.5D;
                    if (fabs(nx->x[i] - final_x) < waypoint
                            && fabs(nx->z[i] - final_z) < waypoint
                            && fabs(nx->y[i] - nx->path_ty[i]) < 1.0D) {
                        nx->path_len[i] = 0;
                        nx->path_len[rider] = 0;
                        m->skeleton_trap_move_terminal_ticks[i] = 1;
                        m->skeleton_trap_move_action[i] = 1;
                    }
                }
            }
            if (nx->path_len[i]
                    && !m->skeleton_trap_move_wait_latched[i]
                    && m->skeleton_trap_move_terminal_ticks[i] == 0) {
                double terminal_dx = nx->path_tx[i] - nx->x[i];
                double terminal_dz = nx->path_tz[i] - nx->z[i];
                if (terminal_dx * terminal_dx
                        + terminal_dz * terminal_dz < 0.0025D) {
                    /* The copied Path is at its final point. On the measured
                     * flat-arena path, the shared path index is consumed on
                     * this boundary and the copied helper remains live for
                     * this update and the following one. */
                    nx->path_len[i] = 0;
                    m->skeleton_trap_move_terminal_ticks[i] = 2;
                    m->skeleton_trap_move_action[i] = 1;
                }
            }
            moving = nx->path_len[i] != 0
                || m->skeleton_trap_move_action[i] != 0;
            nx->ai_state[i] = moving ? EW_AI_CHASE : EW_AI_IDLE;
            nav_speed = m->passive_nav_speed[i] > 0.0D
                ? m->passive_nav_speed[i] : 1.5D;
            wandering = horse_wandering_exact;
        }else if(type == EW_TYPE_LLAMA && llama_lower_ready
                && !pet_sitting && !pet_following
                && !animal_mating && !horse_crazy && !sheep_grazing
                && !llama_caravan && !llama_ranged) {
            moving = llama_lower_moving;
            jump = llama_lower_jump;
            wandering = llama_lower_wandering;
            nav_speed = llama_lower_nav_speed;
        }else if(rabbit_raiding){
            double tx = rabbit_carrot_x + 0.5D;
            double ty = rabbit_carrot_y;
            double tz = rabbit_carrot_z + 0.5D;
            double rdx = tx - now->x[i];
            double rdy = ty - now->y[i];
            double rdz = tz - now->z[i];
            nx->yaw[i] = ehs_yaw_toward(rdx, rdz);
            nx->path_tx[i] = tx;
            nx->path_ty[i] = ty;
            nx->path_tz[i] = tz;
            nav_speed = 0.7D;
            if (rdx * rdx + rdy * rdy + rdz * rdz <= 1.5D) {
                int age = gm_world_meta(
                    w, rabbit_carrot_x, rabbit_carrot_y, rabbit_carrot_z);
                if (age <= 0)
                    gm_world_set_block(
                        w, rabbit_carrot_x, rabbit_carrot_y,
                        rabbit_carrot_z, 0);
                else
                    gm_world_set_block_meta(
                        w, rabbit_carrot_x, rabbit_carrot_y,
                        rabbit_carrot_z, 141, age - 1);
                m->rabbit_carrot_ticks[i] = 40;
                m->rabbit_raid_valid[i] = 0;
                nx->path_len[i] = 0;
                nx->ai_state[i] = EW_AI_IDLE;
            } else {
                nx->path_len[i] = 1;
                nx->ai_state[i] = EW_AI_CHASE;
                moving = 1;
            }
        }else if(passive && type != EW_TYPE_LLAMA
                && !(type == EW_TYPE_POLAR_BEAR && polar_aggro)
                && !rabbit_killer
                && !pet_sitting && !pet_following
                && m->panic_ticks[i]<=0
                && !animal_mating && !horse_crazy && !sheep_grazing
                && !llama_caravan && !llama_ranged){
            pai_tick(m,w,nx,i,px,py,pz,mob_griefing,
                     &moving,&jump,&wandering,&swim_jump,&nav_speed,
                     99, 0, 1);
        }else if(rabbit_killer){
            double distance_sq = dx * dx + dy * dy + dz * dz;
            nx->yaw[i] = ehs_yaw_toward(dx, dz);
            nx->path_tx[i] = px;
            nx->path_ty[i] = py;
            nx->path_tz[i] = pz;
            nav_speed = 1.4D;
            if (distance_sq <= 4.6D) {
                nx->path_len[i] = 0;
                nx->ai_state[i] = EW_AI_ATTACK;
                if (nx->attack_time[i] <= 0) {
                    nx->attack_time[i] = 20;
                    mob_event_append(
                        m, GM_MOB_EVENT_SOUND, nx->id[i],
                        GM_MOB_SOUND_RABBIT_ATTACK,
                        nx->x[i], nx->y[i], nx->z[i], 1.0F, 1.0F);
                    int hit = gm_mobs_attack_player(
                        m, (struct PvStats *)v, &p->inv, 8.0F, 0);
                    p->health = v->health;
                    mob_melee_apply_player_thorns(
                        m, nx, i, p, px, pz, hit, drops,
                        math_random_seed48, next_entity_id, do_mob_loot);
                }
            } else {
                nx->path_len[i] = 1;
                nx->ai_state[i] = EW_AI_CHASE;
                moving = 1;
            }
        }else if(type == EW_TYPE_POLAR_BEAR && polar_aggro){
            double distance_sq = dx * dx + dy * dy + dz * dz;
            double reach_sq = 4.0D + 0.6D;
            nx->yaw[i] = ehs_yaw_toward(dx, dz);
            nx->path_tx[i] = px;
            nx->path_ty[i] = py;
            nx->path_tz[i] = pz;
            nav_speed = 1.25D;
            if (distance_sq <= reach_sq) {
                nx->path_len[i] = 0;
                nx->ai_state[i] = EW_AI_ATTACK;
                if (nx->attack_time[i] <= 0) {
                    nx->attack_time[i] = 20;
                    m->polar_standing[i] = 0;
                    int hit = gm_mobs_attack_player(
                        m, (struct PvStats *)v, &p->inv,
                        mob_melee_damage(m, i, type, m->size[i]), 0);
                    p->health = v->health;
                    mob_melee_apply_player_thorns(
                        m, nx, i, p, px, pz, hit,
                        drops, math_random_seed48,
                        next_entity_id, do_mob_loot);
                }
            } else {
                nx->path_len[i] = 1;
                nx->ai_state[i] = EW_AI_CHASE;
                moving = 1;
                if (distance_sq <= reach_sq * 2.0D) {
                    if (nx->attack_time[i] <= 0) {
                        m->polar_standing[i] = 0;
                        nx->attack_time[i] = 20;
                    }
                    if (nx->attack_time[i] <= 10) {
                        m->polar_standing[i] = 1;
                        if (m->polar_warning_sound_ticks[i] <= 0) {
                            m->polar_warning_sound_ticks[i] = 40;
                            mob_event_append(
                                m, GM_MOB_EVENT_SOUND, nx->id[i],
                                GM_MOB_SOUND_POLAR_BEAR_WARNING,
                                nx->x[i], nx->y[i], nx->z[i],
                                1.0F, 1.0F);
                        }
                    }
                } else {
                    nx->attack_time[i] = 20;
                    m->polar_standing[i] = 0;
                }
            }
        }else if(type==EW_TYPE_IRON_GOLEM){
            int target_player = m->golem_target_player[i] != 0;
            int target = iron_golem_slot_by_eid(
                m, nx, m->golem_target_eid[i]);
            int target_valid = target_player
                ? !m->golem_player_created[i] && v->health > 0.0F
                    && (px - nx->x[i]) * (px - nx->x[i])
                        + (py - nx->y[i]) * (py - nx->y[i])
                        + (pz - nx->z[i]) * (pz - nx->z[i]) <= 256.0D
                : iron_golem_target_valid(
                    m, nx, i, target, dimension,
                    m->golem_target_village_defense[i]);
            if (!target_valid) {
                target = -1;
                target_player = 0;
                m->golem_target_eid[i] = -1;
                m->golem_target_player[i] = 0;
                m->golem_target_village_defense[i] = 0;
                nx->path_len[i] = 0;
            }
            int target_setup = m->golem_target_task_tick[i]++ % 3 == 0;
            if (target < 0 && !target_player && target_setup) {
                int village = m->golem_village_index[i];
                int aggressor_eid =
                    m->golem_village_aggressor_eid[i];
                int defense_selected = 0;
                if (village >= 0 && aggressor_eid >= 0) {
                    if (aggressor_eid == 0) {
                        if (!m->golem_player_created[i]
                                && v->health > 0.0F) {
                            target_player = 1;
                            defense_selected = 1;
                        } else if (m->golem_player_created[i]) {
                            /* DefendVillage first rejects the aggressor through
                             * EntityIronGolem.canAttackClass, then still takes
                             * its 1-in-20 low-reputation fallback draw. That
                             * fallback rejects the same player a second time. */
                            (void)jrand_int_bound(
                                &m->entity_random[i].random, 20);
                        }
                    } else {
                        int candidate = iron_golem_slot_by_eid(
                            m, nx, aggressor_eid);
                        if (iron_golem_target_eligible(
                                m, nx, i, candidate, dimension, 1)) {
                            target = candidate;
                            defense_selected = 1;
                        } else if (candidate <= 0
                                || nx->type[candidate]
                                    != EW_TYPE_CREEPER) {
                            if (!m->golem_player_created[i]
                                    && jrand_int_bound(
                                        &m->entity_random[i].random, 20) == 0
                                    && m->golem_village_low_reputation_player[i]
                                    && v->health > 0.0F) {
                                target_player = 1;
                                defense_selected = 1;
                            }
                        }
                    }
                } else if (village >= 0 && !m->golem_player_created[i]
                        && jrand_int_bound(
                            &m->entity_random[i].random, 20) == 0
                        && m->golem_village_low_reputation_player[i]
                        && v->health > 0.0F) {
                    target_player = 1;
                    defense_selected = 1;
                }
                if (!defense_selected
                        && jrand_int_bound(
                            &m->entity_random[i].random, 10) == 0)
                    target = iron_golem_nearest_target(
                        m, nx, i, dimension);
                if (target > 0 || target_player) {
                    /* EntityAITarget.canEasilyReach initializes its private
                     * retry delay even when the first path succeeds. */
                    (void)jrand_int_bound(
                        &m->entity_random[i].random, 5);
                    m->golem_target_eid[i] =
                        target > 0 ? nx->id[target] : -1;
                    m->golem_target_player[i] = target_player != 0;
                    m->golem_target_village_defense[i] =
                        defense_selected != 0;
                }
            }
            if (target > 0 || target_player) {
                double tx = target_player ? px : nx->x[target];
                double ty = target_player ? py : nx->y[target];
                double tz = target_player ? pz : nx->z[target];
                double tdx = tx - now->x[i];
                double tdy = ty - now->y[i];
                double tdz = tz - now->z[i];
                double target_distance_sq =
                    tdx * tdx + tdy * tdy + tdz * tdz;
                nx->yaw[i] = ehs_yaw_toward(tdx, tdz);
                nx->path_tx[i] = tx;
                nx->path_ty[i] = ty;
                nx->path_tz[i] = tz;
                nx->path_len[i] = 1;
                nx->ai_state[i] = EW_AI_CHASE;
                nav_speed = 1.0D;
                moving = 1;

                --m->golem_path_delay[i];
                if (m->golem_path_delay[i] <= 0) {
                    double cache_dx = tx - m->golem_path_target_x[i];
                    double cache_dy = ty - m->golem_path_target_y[i];
                    double cache_dz = tz - m->golem_path_target_z[i];
                    int empty_cache = m->golem_path_target_x[i] == 0.0D
                        && m->golem_path_target_y[i] == 0.0D
                        && m->golem_path_target_z[i] == 0.0D;
                    if (empty_cache
                            || cache_dx * cache_dx + cache_dy * cache_dy
                                + cache_dz * cache_dz >= 1.0D
                            || jrand_float(
                                &m->entity_random[i].random) < 0.05F) {
                        m->golem_path_target_x[i] = tx;
                        m->golem_path_target_y[i] = ty;
                        m->golem_path_target_z[i] = tz;
                        m->golem_path_delay[i] = 4 + jrand_int_bound(
                            &m->entity_random[i].random, 7);
                        if (target_distance_sq > 1024.0D)
                            m->golem_path_delay[i] += 10;
                        else if (target_distance_sq > 256.0D)
                            m->golem_path_delay[i] += 5;
                    }
                }

                double target_width = 0.6D, target_height = 1.8D;
                if (!target_player)
                    living_entity_size(
                        m, nx, target, &target_width, &target_height);
                (void)target_height;
                float golem_reach = 1.4F * 2.0F;
                double reach_sq = (double)(
                    golem_reach * golem_reach + (float)target_width);
                if (target_distance_sq <= reach_sq
                        && nx->attack_time[i] <= 0) {
                    nx->attack_time[i] = 20;
                    nx->ai_state[i] = EW_AI_ATTACK;
                    GmMobDeathContext golem_death_context = {
                        .do_mob_loot = do_mob_loot,
                        .math_random_seed48 = math_random_seed48,
                        .next_entity_id = next_entity_id,
                    };
                    if (target_player)
                        (void)iron_golem_attack_player_slot(
                            m, nx, i, p, v);
                    else
                        (void)iron_golem_attack_slot(
                            m, nx, i, target, NULL, drops,
                            &golem_death_context);
                }
            } else {
                nx->ai_state[i] = EW_AI_IDLE;
                wandering = 1;
                nav_speed = 0.6D;
                if (nx->repath_timer[i] > 0) --nx->repath_timer[i];
                if (nx->path_len[i] == 1) {
                    double wx = nx->path_tx[i] - now->x[i];
                    double wz = nx->path_tz[i] - now->z[i];
                    if (wx * wx + wz * wz < 1.0D)
                        nx->path_len[i] = 0;
                }
                if (!nx->path_len[i] && nx->repath_timer[i] <= 0) {
                    nx->repath_timer[i] = GM_MOB_WANDER_INTERVAL;
                    u64 h = mc_hash_seed(
                        (u64)m->seed, m->tick, i, 0, 0, 0x474f4c4du);
                    int ddx = mc_hash_bound(
                        h, 2 * GM_MOB_WANDER_RADIUS + 1)
                        - GM_MOB_WANDER_RADIUS;
                    int ddz = mc_hash_bound(
                        mc_hash64(h), 2 * GM_MOB_WANDER_RADIUS + 1)
                        - GM_MOB_WANDER_RADIUS;
                    int ty = wander_ground_y(
                        w, mc_floor(now->x[i]) + ddx,
                        mc_floor(now->y[i]), mc_floor(now->z[i]) + ddz);
                    if ((ddx || ddz) && ty > -999) {
                        nx->path_tx[i] = mc_floor(now->x[i]) + ddx + 0.5D;
                        nx->path_ty[i] = ty;
                        nx->path_tz[i] = mc_floor(now->z[i]) + ddz + 0.5D;
                        nx->path_len[i] = 1;
                    }
                }
                moving = nx->path_len[i] != 0;
            }
        }else if(type==EW_TYPE_VEX){
            /* AIChargeAttack (priority 4), then AIMoveRandom (priority 8).
             * path_len is the EntityMoveHelper MOVE_TO action bit. */
            nav_speed = m->vex_charging[i] ? 1.0 : 0.25;
            nx->yaw[i]=ehs_yaw_toward(dx,dz);
            if (aggro && m->vex_charging[i] && nx->path_len[i]) {
                McAABB vex_box;
                if (mob_slot_world_box(m, nx, i, &vex_box)
                        && mc_aabb_intersects(&vex_box, &xp_player)) {
                    int hit = gm_mobs_attack_player(
                        m, (struct PvStats *)v, &p->inv, 4.0F, 0);
                    p->health = v->health;
                    mob_melee_apply_player_thorns(
                        m, nx, i, p, px, pz, hit, drops,
                        math_random_seed48, next_entity_id, do_mob_loot);
                    m->vex_charging[i] = 0;
                    nx->path_len[i] = 0;
                } else if (d * d < 9.0) {
                    nx->path_tx[i] = px;
                    nx->path_ty[i] = py + psv_player_eye_height(p);
                    nx->path_tz[i] = pz;
                }
            }
            if (aggro && !nx->path_len[i] && d * d > 4.0
                    && jrand_int_bound(
                        &m->entity_random[i].random, 7) == 0) {
                nx->path_tx[i] = px;
                nx->path_ty[i] = py + psv_player_eye_height(p);
                nx->path_tz[i] = pz;
                nx->path_len[i] = 1;
                nav_speed = 1.0;
                m->vex_charging[i] = 1;
                mob_event_append(
                    m, GM_MOB_EVENT_SOUND, nx->id[i],
                    GM_MOB_SOUND_VEX_CHARGE,
                    nx->x[i], nx->y[i], nx->z[i], 1.0F, 1.0F);
            } else if (!nx->path_len[i]
                    && jrand_int_bound(
                        &m->entity_random[i].random, 7) == 0) {
                int bx = m->vex_bound_x[i];
                int by = m->vex_bound_y[i];
                int bz = m->vex_bound_z[i];
                if (m->vex_owner_eid[i] < 0) {
                    bx = mc_floor(nx->x[i]);
                    by = mc_floor(nx->y[i]);
                    bz = mc_floor(nx->z[i]);
                }
                for (int attempt = 0; attempt < 3; ++attempt) {
                    int tx = bx + jrand_int_bound(
                        &m->entity_random[i].random, 15) - 7;
                    int ty = by + jrand_int_bound(
                        &m->entity_random[i].random, 11) - 5;
                    int tz = bz + jrand_int_bound(
                        &m->entity_random[i].random, 15) - 7;
                    if (gm_world_block(w, tx, ty, tz) != 0) continue;
                    nx->path_tx[i] = tx + 0.5;
                    nx->path_ty[i] = ty + 0.5;
                    nx->path_tz[i] = tz + 0.5;
                    nx->path_len[i] = 1;
                    nav_speed = 0.25;
                    break;
                }
            }
            if (!aggro) m->vex_charging[i] = 0;
            moving = nx->path_len[i] != 0;
            nx->ai_state[i] = m->vex_charging[i]
                ? EW_AI_ATTACK : moving ? EW_AI_CHASE : EW_AI_IDLE;
        }else if(type==EW_TYPE_GUARDIAN
                || type==EW_TYPE_ELDER_GUARDIAN){
            int attacking = aggro
                && (type == EW_TYPE_ELDER_GUARDIAN || d * d > 9.0);
            nx->yaw[i] = ehs_yaw_toward(dx, dz);
            if (attacking) {
                nx->path_tx[i] = px;
                nx->path_ty[i] = py + 0.9;
                nx->path_tz[i] = pz;
                nx->path_len[i] = 0;
                nx->ai_state[i] = EW_AI_ATTACK;
                (void)guardian_attack_step_slot(
                    m, nx, i, 1, (struct PvStats *)v, &p->inv);
                p->health = v->health;
            } else {
                if (m->guardian_target_eid[i] >= 0) {
                    m->guardian_target_eid[i] = -1;
                    m->guardian_attack_counter[i] = -10;
                }
                if (aggro) {
                    nx->path_tx[i] = px;
                    nx->path_ty[i] = py + (double)PSV_EYE_HEIGHT * 0.5;
                    nx->path_tz[i] = pz;
                    nx->path_len[i] = 1;
                    nx->ai_state[i] = EW_AI_CHASE;
                    nav_speed = 1.0;
                    moving = 1;
                } else {
                    nx->path_len[i] = 0;
                    nx->ai_state[i] = EW_AI_IDLE;
                }
            }
        /* Ghast AIFireballAttack: charge then fire large fireball. */
        }else if(aggro&&type==EW_TYPE_GHAST){
            nx->path_tx[i]=px;nx->path_ty[i]=py+8.0;nx->path_tz[i]=pz;
            nx->yaw[i]=ehs_yaw_toward(dx,dz);
            nx->ai_state[i]=EW_AI_ATTACK;
            if(d>16.0){moving=1;nx->ai_state[i]=EW_AI_CHASE;}
            ++m->charge[i];
            /* Charge 20 ticks, then reset through a 40-tick cooldown. */
            if(m->charge[i]>=20 && !m->fireball_pending){
                double len=d>0.01?d:1.0;
                m->fireball_pending=5; /* EntityLargeFireball */
                m->fireball_x=now->x[i];m->fireball_y=now->y[i]+1.5;m->fireball_z=now->z[i];
                m->fireball_vx=dx/len*0.5;m->fireball_vy=dy/len*0.5;m->fireball_vz=dz/len*0.5;
                m->charge[i]=-40;
            }
        }else if(aggro&&type==EW_TYPE_BLAZE){
            if(!m->blaze_attacking[i]){
                m->blaze_attacking[i]=1;
                m->blaze_attack_step[i]=0;
            }
            --nx->attack_time[i];
            nx->yaw[i]=ehs_yaw_toward(dx,dz);
            nx->path_tx[i]=px;nx->path_ty[i]=py;nx->path_tz[i]=pz;
            nx->path_len[i]=0;nx->ai_state[i]=EW_AI_ATTACK;
            if(d*d<4.0){
                moving=1;nx->ai_state[i]=EW_AI_CHASE;
                if(nx->attack_time[i]<=0){
                    int hit = gm_mobs_attack_player(
                        m, (struct PvStats *)v, &p->inv,
                        mob_melee_damage(m, i, type, m->size[i]), 0);
                    p->health=v->health;
                    mob_melee_apply_player_thorns(
                        m, nx, i, p, px, pz, hit,
                        drops, math_random_seed48,
                        next_entity_id, do_mob_loot);
                    nx->attack_time[i]=20;
                }
            }else if(nx->attack_time[i]<=0){
                int step=++m->blaze_attack_step[i];
                if(step==1){
                    nx->attack_time[i]=60;
                    m->blaze_charged[i]=1;
                    m->blaze_on_fire[i]=1;
                }else if(step<=4){
                    nx->attack_time[i]=6;
                    EbfVector aim = ebf_blaze_fireball_aim(
                        &m->entity_random[i], dx, dy, dz);
                    if(m->blaze_shots_pending[i]<GM_BLAZE_SHOT_QUEUE){
                        int tail = (m->blaze_shot_head[i]
                            + m->blaze_shots_pending[i])
                            % GM_BLAZE_SHOT_QUEUE;
                        m->blaze_shots[i][tail] = (GmBlazeShot){
                            now->x[i],
                            now->y[i] + (double)(1.8F / 2.0F) + 0.5,
                            now->z[i],
                            aim.x, aim.y, aim.z
                        };
                        ++m->blaze_shots_pending[i];
                    }
                }else{
                    nx->attack_time[i]=100;
                    m->blaze_attack_step[i]=0;
                    m->blaze_charged[i]=0;
                    m->blaze_on_fire[i]=0;
                }
            }
        }else if(aggro&&type==EW_TYPE_WITCH){
            /* EntityAIAttackRanged: visibility has an independent 20-tick
             * cursor, holding starts only inside 10 blocks after that cursor,
             * and a zero cooldown waits at zero until line of sight returns. */
            nx->yaw[i]=ehs_yaw_toward(dx,dz);
            nx->path_tx[i]=px;nx->path_ty[i]=py;nx->path_tz[i]=pz;
            nx->path_len[i]=0;
            if (witch_visible) ++m->witch_see_time[i];
            else m->witch_see_time[i] = 0;
            if(d*d>100.0 || m->witch_see_time[i]<20){
                nx->ai_state[i]=EW_AI_CHASE;moving=1;
            }else{
                nx->ai_state[i]=EW_AI_ATTACK;
            }
            if (nx->attack_time[i] == 0 && witch_visible) {
                (void)witch_ranged_attack_slot(
                    m, now, i, px, py, pz,
                    p->ent.motionX, p->ent.motionZ,
                    psv_player_eye_height(p), v->health);
                nx->attack_time[i] = 60;
            } else if (nx->attack_time[i] < 0) {
                nx->attack_time[i] = 60;
            }
        }else if(type==EW_TYPE_EVOKER&&(aggro||evoker_casting)){
            /* AICastingSpell clears navigation. Outside a cast the Evoker's
             * higher-priority avoid-player task retreats inside eight blocks;
             * it has no melee task. */
            if (m->evoker_spell_id[i] == 3
                    && m->evoker_wololo_target[i] > 0) {
                int sheep = mob_slot_by_eid(
                    m, m->evoker_wololo_target[i]);
                if (sheep > 0)
                    nx->yaw[i] = ehs_yaw_toward(
                        nx->x[sheep] - now->x[i],
                        nx->z[sheep] - now->z[i]);
            } else {
                nx->yaw[i]=ehs_yaw_toward(dx,dz);
            }
            nx->path_ty[i]=now->y[i];nx->path_len[i]=0;
            if(evoker_casting){
                nx->path_tx[i]=now->x[i];
                nx->path_tz[i]=now->z[i];
                nx->ai_state[i]=EW_AI_ATTACK;
            }else if(xz<8.0&&xz>0.01){
                nx->path_tx[i]=now->x[i]-dx/xz*8.0;
                nx->path_tz[i]=now->z[i]-dz/xz*8.0;
                nx->ai_state[i]=EW_AI_CHASE;moving=1;
            }else{
                nx->path_tx[i]=px;nx->path_tz[i]=pz;
                nx->ai_state[i]=EW_AI_ATTACK;
            }
        }else if(aggro&&(type==EW_TYPE_SKELETON||type==EW_TYPE_STRAY)){
            /* EntityAIAttackRangedBow approaches until 20 continuously
             * visible ticks, then clears navigation and begins strafing. */
            if (!trap_rider)
                nx->yaw[i]=ehs_yaw_toward(dx,dz);
            if (trap_rider) {
                int visible = los_clear(
                    w, now->x[i], now->y[i] + 1.74D, now->z[i],
                    target_x, target_y + (double)target_eye_height,
                    target_z);
                int was_visible = m->witch_see_time[i] > 0;
                if (visible != was_visible) m->witch_see_time[i] = 0;
                m->witch_see_time[i] += visible ? 1 : -1;
                double target_distance_sq =
                    dx * dx + (py - now->y[i]) * (py - now->y[i])
                    + dz * dz;
                if (target_distance_sq <= 225.0D
                        && m->witch_see_time[i] >= 20) {
                    m->skeleton_trap_move_wait_latched[i] = 0;
                    nx->path_len[i] = 0;
                    nx->path_tx[i] = target_x;
                    nx->path_ty[i] = target_y;
                    nx->path_tz[i] = target_z;
                    ++m->passive_eat_time[i];
                    if (m->passive_eat_time[i] >= 20) {
                        if ((double)jrand_float(
                                &m->entity_random[i].random) < 0.3D)
                            m->passive_tasks[i] ^= 1u << 16;
                        if ((double)jrand_float(
                                &m->entity_random[i].random) < 0.3D)
                            m->passive_tasks[i] ^= 1u << 17;
                        m->passive_eat_time[i] = 0;
                    }
                    if (target_distance_sq > 168.75D)
                        m->passive_tasks[i] &= ~(1u << 17);
                    else if (target_distance_sq < 56.25D)
                        m->passive_tasks[i] |= 1u << 17;
                    nx->ai_state[i]=EW_AI_CHASE;moving=1;
                } else {
                    nx->path_tx[i] =
                        m->skeleton_trap_target_eid[i] > 0
                        ? (double)mc_floor(target_x) + 0.5D : target_x;
                    nx->path_ty[i]=target_y;
                    nx->path_tz[i] =
                        m->skeleton_trap_target_eid[i] > 0
                        ? (double)mc_floor(target_z) + 0.5D : target_z;
                    nx->path_len[i] =
                        m->skeleton_trap_move_wait_latched[i] ? 0 : 1;
                    nx->ai_state[i]=EW_AI_CHASE;
                    moving = nx->path_len[i] != 0;
                    m->passive_eat_time[i] = -1;
                }
                if (m->skeleton_trap_hand_active[i]) {
                    if (!visible && m->witch_see_time[i] < -60) {
                        m->skeleton_trap_hand_active[i] = 0;
                        m->skeleton_trap_item_use_count[i] = 0;
                    } else if (visible
                            && m->skeleton_trap_item_use_count[i] >= 20
                            && skeleton_trap_rider_queue_shot(
                                m, nx, i,
                                target_x, target_y, target_z,
                                target_height)) {
                        m->skeleton_trap_hand_active[i] = 0;
                        m->skeleton_trap_item_use_count[i] = 0;
                        nx->attack_time[i] = 40;
                    }
                } else if (--nx->attack_time[i] <= 0
                        && m->witch_see_time[i] >= -60) {
                    m->skeleton_trap_hand_active[i] = 1;
                    m->skeleton_trap_item_use_count[i] = 0;
                }
            }else if(xz<6.0&&xz>0.01){
                double ux=dx/xz, uz=dz/xz;
                nx->path_tx[i]=now->x[i]-ux*4.0;nx->path_ty[i]=now->y[i];
                nx->path_tz[i]=now->z[i]-uz*4.0;nx->path_len[i]=0;
                nx->ai_state[i]=EW_AI_CHASE;moving=1;
            }else if(xz>14.0){
                nx->path_tx[i]=px;nx->path_ty[i]=py;nx->path_tz[i]=pz;
                nx->path_len[i]=0;nx->ai_state[i]=EW_AI_CHASE;moving=1;
            }else{
                nx->path_tx[i]=px;nx->path_ty[i]=py;nx->path_tz[i]=pz;nx->path_len[i]=0;
                nx->ai_state[i]=EW_AI_ATTACK;
            }
            if(!trap_rider && nx->attack_time[i]<=0)
                nx->attack_time[i]=attack_cooldown_ticks(type);
        }else if(aggro&&type==EW_TYPE_CREEPER&&xz<=3.0&&fabs(dy)<3.0){
            nx->path_tx[i]=px;nx->path_ty[i]=py;nx->path_tz[i]=pz;nx->path_len[i]=0;
            nx->ai_state[i]=EW_AI_ATTACK;nx->yaw[i]=ehs_yaw_toward(dx,dz);
            if(++m->creeper_fuse[i]>=30){
                loaded_invalidate_living(m, i);
                nx->alive[i]=0;nx->type[i]=EW_TYPE_NONE;m->creeper_fuse[i]=0;m->explosion_pending=1;
                m->explosion_x=now->x[i];m->explosion_y=now->y[i]+0.5;m->explosion_z=now->z[i];
            }
        }else if(aggro&&gm_is_slimey(type)){
            /* Slime hop toward player. Squish edges use wasOnGround after
             * move_mob (EntitySlime.onUpdate order); AI only triggers jumps. */
            nx->path_tx[i]=px;nx->path_ty[i]=py;nx->path_tz[i]=pz;
            nx->yaw[i]=ehs_yaw_toward(dx,dz);
            if(m->jump_delay[i]>0)--m->jump_delay[i];
            if(now->on_ground[i]&&m->jump_delay[i]<=0){
                jump=1;moving=1;
                m->jump_delay[i]=10+m->size[i]*5;
                nx->ai_state[i]=EW_AI_CHASE;
            }else if(!now->on_ground[i]){
                moving=1;nx->ai_state[i]=EW_AI_CHASE;
            }else {
                nx->ai_state[i]=EW_AI_IDLE;
            }
            if(xz<=GM_MOB_REACH*(0.5+m->size[i]*0.25)&&fabs(dy)<(double)m->size[i]+1.0&&
               nx->attack_time[i]<=0){
                float dmg=mob_melee_damage(m,i,type,m->size[i]);
                if(dmg>0.0f){
                    int hit = gm_mobs_attack_player(
                        m, (struct PvStats *)v, &p->inv, dmg, 0);
                    p->health=v->health;
                    mob_melee_apply_player_thorns(
                        m, nx, i, p, px, pz, hit,
                        drops, math_random_seed48,
                        next_entity_id, do_mob_loot);
                }
                nx->attack_time[i]=attack_cooldown_ticks(type);
            }
        }else if(aggro&&xz<=GM_MOB_REACH&&fabs(dy)<3.0){
            nx->path_tx[i]=px;nx->path_ty[i]=py;nx->path_tz[i]=pz;nx->path_len[i]=0;
            nx->ai_state[i]=EW_AI_ATTACK;nx->yaw[i]=ehs_yaw_toward(dx,dz);
            if(nx->attack_time[i]<=0){
                int hit=gm_mobs_attack_player(m,(struct PvStats *)v,
                                              &p->inv,
                                              mob_melee_damage(
                                                  m,i,type,m->size[i]),0);
                p->health=v->health;
                mob_melee_apply_player_thorns(
                    m, nx, i, p, px, pz, hit,
                    drops, math_random_seed48,
                    next_entity_id, do_mob_loot);
                if(hit&&type==EW_TYPE_WITHER_SKELETON)
                    m->player_wither_ticks=200;
                if(hit&&type==EW_TYPE_HUSK
                        && m->entity_mainhand[i].count <= 0
                        && m->player_hunger_ticks < husk_hunger_duration)
                    m->player_hunger_ticks=husk_hunger_duration;
                nx->attack_time[i]=attack_cooldown_ticks(type);
            }
            /* Spider leap (EntityAILeapAtTarget): periodic, not every tick. */
            if(gm_spider(type)&&now->on_ground[i]&&xz>1.5&&xz<8.0&&
               (m->tick % 20)==0)jump=1;
        }else if(aggro){
            nx->path_tx[i]=px;nx->path_ty[i]=py;nx->path_tz[i]=pz;nx->path_len[i]=0;
            nx->ai_state[i]=EW_AI_CHASE;moving=1;
            if(type==EW_TYPE_CREEPER&&m->creeper_fuse[i]>0)--m->creeper_fuse[i];
            if(gm_spider(type)&&now->on_ground[i]&&xz>2.0&&xz<10.0&&
               (m->tick % 20)==0)jump=1;
            /* Silverfish short follow; hop on a 10-tick cadence. */
            if(type==EW_TYPE_SILVERFISH&&now->on_ground[i]&&(m->tick % 10)==0)jump=1;
        }else if(pet_sitting){
            nx->path_len[i]=0;
            nx->ai_state[i]=EW_AI_IDLE;
        }else if(pet_following){
            nx->ai_state[i]=EW_AI_CHASE;
            moving=1;
        }else if(passive && type != EW_TYPE_LLAMA
                && m->panic_ticks[i]>0){
            --m->panic_ticks[i];
            double ux=xz>0.01?dx/xz:1.0, uz=xz>0.01?dz/xz:0.0;
            nx->path_tx[i]=now->x[i]-ux*8.0;nx->path_ty[i]=now->y[i];
            nx->path_tz[i]=now->z[i]-uz*8.0;nx->path_len[i]=0;
            nx->ai_state[i]=EW_AI_IDLE;moving=1;
            nav_speed = type == EW_TYPE_LLAMA
                ? 1.2D : pai_panic_multiplier(type);
        }else if(horse_crazy){
            nx->ai_state[i] = nx->path_len[i]
                ? EW_AI_CHASE : EW_AI_IDLE;
            nav_speed = 1.2D;
            moving = nx->path_len[i] != 0;
        }else if(animal_mating){
            int mate_slot = mob_slot_by_eid(
                m, m->sheep_mate_eid[i]);
            if (mate_slot > 0 && mate_slot < EW_MAX_ENTITIES
                    && nx->alive[mate_slot]) {
                if (type == EW_TYPE_LLAMA) {
                    m->llama_nav_goal_valid[i] = 1;
                    m->llama_nav_goal_pending[i] = 1;
                    m->llama_nav_goal_x[i] = nx->x[mate_slot];
                    m->llama_nav_goal_y[i] = nx->y[mate_slot];
                    m->llama_nav_goal_z[i] = nx->z[mate_slot];
                    m->passive_nav_speed[i] = 1.0D;
                    nx->ai_state[i] = EW_AI_CHASE;
                } else {
                /* Path.getVectorFromIndex centers the integer PathPoint by
                 * (int)(width + 1) * 0.5. Adult sheep width 0.9 gives 0.5. */
                double mate_path_center = gm_mobs_horse_type(type)
                    ? 1.0 : 0.5;
                nx->path_tx[i] = mc_floor(nx->x[mate_slot])
                    + mate_path_center;
                nx->path_ty[i] = nx->y[mate_slot];
                nx->path_tz[i] = mc_floor(nx->z[mate_slot])
                    + mate_path_center;
                nx->path_len[i] = 0;
                nx->ai_state[i] = EW_AI_CHASE;
                double mate_dx = nx->x[mate_slot] - now->x[i];
                double mate_dz = nx->z[mate_slot] - now->z[i];
                /* PathNavigateGround refuses a new path while airborne. */
                if (now->on_ground[i]
                        && mate_dx * mate_dx + mate_dz * mate_dz > 1.0e-12) {
                    moving = 1;
                }
                }
            }
        }else if(sheep_grazing){
            nx->path_len[i]=0;
            nx->ai_state[i]=EW_AI_IDLE;
        }else if(type==EW_TYPE_GIANT){
            /* EntityGiantZombie never installs tasks or targetTasks. */
            nx->path_len[i]=0;
            nx->ai_state[i]=EW_AI_IDLE;
        }else{
            if (type == EW_TYPE_WITCH) {
                m->witch_see_time[i] = 0;
                nx->attack_time[i] = -1;
            }
            nx->ai_state[i]=EW_AI_IDLE;wandering=1;
            if(nx->repath_timer[i]>0)--nx->repath_timer[i];
            int has=nx->path_len[i]==1;
            if(has){
                double wx2=nx->path_tx[i]-now->x[i],wz2=nx->path_tz[i]-now->z[i];
                if(wx2*wx2+wz2*wz2<1.0){nx->path_len[i]=0;has=0;}
            }
            if(!has&&nx->repath_timer[i]<=0){
                nx->repath_timer[i]=GM_MOB_WANDER_INTERVAL;
                u64 h=mc_hash_seed((u64)m->seed,m->tick,i,0,0,0x57414e44u);
                int ddx=mc_hash_bound(h,2*GM_MOB_WANDER_RADIUS+1)-GM_MOB_WANDER_RADIUS;
                int ddz=mc_hash_bound(mc_hash64(h),2*GM_MOB_WANDER_RADIUS+1)-GM_MOB_WANDER_RADIUS;
                if(ddx||ddz){
                    int txc=mc_floor(now->x[i])+ddx,tzc=mc_floor(now->z[i])+ddz;
                    int ty=wander_ground_y(w,txc,mc_floor(now->y[i]),tzc);
                    if(ty>-999){
                        nx->path_tx[i]=txc+0.5;nx->path_ty[i]=ty;nx->path_tz[i]=tzc+0.5;
                        nx->path_len[i]=1;has=1;
                    }
                }
            }
            if(has)moving=1;
            /* Neutral pigman / small slime idle hop. */
            if(gm_is_slimey(type)&&now->on_ground[i]){
                if(m->jump_delay[i]>0)--m->jump_delay[i];
                else if(moving){
                    jump=1;m->jump_delay[i]=20+m->size[i]*10;
                }
            }
        }
        if (type == EW_TYPE_LLAMA && llama_follow_parent_move) {
            m->llama_nav_goal_valid[i] = 1;
            m->llama_nav_goal_pending[i] = 1;
            m->llama_nav_goal_x[i] = llama_follow_parent_x;
            m->llama_nav_goal_y[i] = llama_follow_parent_y;
            m->llama_nav_goal_z[i] = llama_follow_parent_z;
            m->passive_nav_speed[i] = 1.0D;
        }
        if (type == EW_TYPE_LLAMA && m->llama_nav_goal_valid[i]
                && (llama_follow_parent_move || llama_ranged_move
                    || (!llama_caravan && !llama_ranged))) {
            int nav_result = llama_caravan_navigation_target(
                m, w, now, i,
                m->llama_nav_goal_x[i], m->llama_nav_goal_y[i],
                m->llama_nav_goal_z[i],
                clock ? clock->total_time : world_time,
                m->llama_nav_goal_pending[i] != 0,
                animal_mating || llama_follow_parent_move
                    || llama_ranged_move,
                &nx->path_tx[i], &nx->path_ty[i], &nx->path_tz[i]);
            m->llama_nav_goal_pending[i] = 0;
            nx->path_len[i] = nav_result > 0;
            if (nav_result == 0) m->llama_nav_goal_valid[i] = 0;
            nx->ai_state[i] = nx->path_len[i]
                ? EW_AI_CHASE : EW_AI_IDLE;
            nav_speed = m->passive_nav_speed[i];
            moving = nx->path_len[i] != 0;
        }
        /* EntityIronGolem.updateAITasks follows both task selectors and
         * precedes navigation movement. */
        if (type == EW_TYPE_IRON_GOLEM
                && --m->golem_home_check_timer[i] <= 0)
            m->golem_home_check_timer[i] = 70 + jrand_int_bound(
                &m->entity_random[i].random, 50);
        if (type == EW_TYPE_VILLAGER
                && --m->villager_random_tick_divider[i] <= 0) {
            m->villager_collection_pending[i] = 1;
            m->villager_collection_x[i] = mc_floor(now->x[i]);
            m->villager_collection_y[i] = mc_floor(now->y[i]);
            m->villager_collection_z[i] = mc_floor(now->z[i]);
            m->villager_random_tick_divider[i] = 70
                + jrand_int_bound(&m->entity_random[i].random, 50);
        }
        if (type == EW_TYPE_WITCH && m->witch_drinking[i]) moving = 0;
        if (type == EW_TYPE_GUARDIAN
                || type == EW_TYPE_ELDER_GUARDIAN) {
            int in_water = m->entity_in_water[i] != 0;
            m->guardian_moving[i] = moving ? 1 : 0;
            if (!in_water && nx->on_ground[i]) {
                nx->vy[i] += 0.5D;
                nx->vx[i] += (double)(
                    (jrand_float(&m->entity_random[i].random) * 2.0F - 1.0F)
                    * 0.4F);
                nx->vz[i] += (double)(
                    (jrand_float(&m->entity_random[i].random) * 2.0F - 1.0F)
                    * 0.4F);
                nx->yaw[i] =
                    jrand_float(&m->entity_random[i].random) * 360.0F;
                nx->on_ground[i] = 0;
            }
            if (!in_water) {
                m->guardian_tail_speed[i] = 2.0F;
                m->guardian_spikes_animation[i] =
                    jrand_float(&m->entity_random[i].random);
            } else if (moving) {
                if (m->guardian_tail_speed[i] < 0.5F)
                    m->guardian_tail_speed[i] = 4.0F;
                else
                    m->guardian_tail_speed[i] +=
                        (0.5F - m->guardian_tail_speed[i]) * 0.1F;
                m->guardian_spikes_animation[i] +=
                    (0.0F - m->guardian_spikes_animation[i]) * 0.25F;
            } else {
                m->guardian_tail_speed[i] +=
                    (0.125F - m->guardian_tail_speed[i]) * 0.2F;
                m->guardian_spikes_animation[i] +=
                    (1.0F - m->guardian_spikes_animation[i]) * 0.06F;
            }
            m->guardian_tail_animation[i] +=
                m->guardian_tail_speed[i];
        }
        /* EntitySlime.onUpdate: lerp factor first (before physics). */
        if(gm_is_slimey(type)){
            m->squish_factor[i] += (m->squish_amount[i] - m->squish_factor[i]) * 0.5f;
            m->prev_squish_factor[i] = m->squish_factor[i];
        }
        if (type == EW_TYPE_RABBIT) {
            int grounded = now->on_ground[i] != 0;
            if (grounded && !m->rabbit_was_on_ground[i]) {
                m->rabbit_move_duration[i] =
                    m->rabbit_move_speed[i] < 2.2D ? 10 : 1;
                m->rabbit_move_speed[i] = 0.0D;
            }
            if (grounded && m->rabbit_move_duration[i] > 0)
                --m->rabbit_move_duration[i];
            if (grounded && moving && m->rabbit_move_duration[i] <= 0) {
                m->rabbit_move_speed[i] = nav_speed;
                m->rabbit_move_duration[i] = nav_speed < 2.2D ? 10 : 1;
                m->rabbit_jump_duration[i] = 10;
                m->rabbit_jump_ticks[i] = 0;
                jump = 1;
                float first = jrand_float(&m->entity_random[i].random);
                float second = jrand_float(&m->entity_random[i].random);
                mob_event_append(
                    m, GM_MOB_EVENT_SOUND, nx->id[i],
                    GM_MOB_SOUND_RABBIT_JUMP,
                    nx->x[i], nx->y[i], nx->z[i], 0.5F,
                    ((first - second) * 0.2F + 1.0F) * 0.8F);
            } else {
                jump = 0;
            }
            m->rabbit_was_on_ground[i] = (unsigned char)grounded;
        }
        if(moving&&type!=EW_TYPE_GHAST&&type!=EW_TYPE_VEX){
            double mvx=nx->path_tx[i]-now->x[i],mvz=nx->path_tz[i]-now->z[i];
            double len=sqrt(mvx*mvx+mvz*mvz);
            if(len>0.01){
                int ax=mc_floor(now->x[i]+mvx/len*0.9),az=mc_floor(now->z[i]+mvz/len*0.9);
                int fy=mc_floor(now->y[i]);
                if(!gm_mobs_horse_type(type)&&
                   solid_id(gm_world_block(w,ax,fy,az))&&
                   !solid_id(gm_world_block(w,ax,fy+1,az))&&
                   !solid_id(gm_world_block(w,ax,fy+2,az)))jump=1;
                else if(wandering&&!solid_id(gm_world_block(w,ax,fy,az))&&
                        !solid_id(gm_world_block(w,ax,fy-1,az))&&
                        !solid_id(gm_world_block(w,ax,fy-2,az))){
                    moving=0;nx->path_len[i]=0;
                }
            }
        }
        /* EntityBlaze.updateAITasks runs after goalSelector (including the
         * fireball task) and before travel. Its RNG call therefore follows a
         * same-tick shot's two aim Gaussians. */
        if(type==EW_TYPE_BLAZE){
            if(--m->blaze_height_offset_update_time[i]<=0){
                m->blaze_height_offset_update_time[i]=100;
                m->blaze_height_offset[i]=ebf_blaze_height_offset(
                    &m->entity_random[i]);
            }
            if(aggro){
                float blaze_eye = 1.8F * 0.85F;
                nx->vy[i]=ebf_blaze_height_impulse(
                    nx->vy[i], py + (double)1.62F,
                    now->y[i] + (double)blaze_eye,
                m->blaze_height_offset[i]);
            }
        }
        if (generic_rider && type == EW_TYPE_PIGMAN)
            m->passive_head_yaw[i] = living_update_rotation_exact(
                m->passive_head_yaw[i],
                m->squid_render_yaw_offset[i], 10.0F);
        float pre_move_fall_distance = m->entity_fall_distance[i];
        {
            move_mob(
                w, window, ox, oz, st, m, nx, i,
                moving, jump,
                animal_mating ? 1 : horse_crazy ? 2 : 0,
                ridden_pig, pig_steerable, p->yaw, p->pitch,
                horse_movement_blocked,
                swim_jump, nav_speed);
        }
        if (type == EW_TYPE_BAT) {
            m->entity_fall_distance[i] = 0.0F;
            if (m->bat_hanging[i]) {
                nx->vx[i] = 0.0D;
                nx->vy[i] = 0.0D;
                nx->vz[i] = 0.0D;
                nx->y[i] = (double)mc_floor(nx->y[i])
                    + 1.0D - (double)0.9F;
            } else {
                nx->vy[i] *= 0.6000000238418579D;
            }
        }
        if (type == EW_TYPE_IRON_GOLEM)
            iron_golem_move_animation_and_step(m, w, now, nx, i);
        else if (type == EW_TYPE_LLAMA)
            llama_step_sound(m, w, now, nx, i);
        if (type != EW_TYPE_BAT && tick_nonwitch_fall_landing(
                m, w, nx, i, pre_move_fall_distance,
                drops, do_mob_loot, math_random_seed48,
                next_entity_id, p, v))
            continue;
        if (type == EW_TYPE_WITCH
                && tick_witch_fall_landing(
                    m, w, nx, i, pre_move_fall_distance,
                    drops, do_mob_loot, mob_griefing,
                    world_random_seed48, math_random_seed48,
                    next_entity_id))
            continue;
        if (tick_exact_mob_cactus_contact(
                m, w, nx, i, drops, do_mob_loot,
                math_random_seed48, next_entity_id))
            continue;
        if (tick_exact_mob_fire_contact(
                m, w, clock, nx, i, drops, do_mob_loot,
                math_random_seed48, next_entity_id))
            continue;
        if(passive && !horse_movement_blocked) {
            if (living_first_passenger_is_living(m, nx, i))
                mounted_living_look_update(m, nx, i);
            else
                pai_apply_current_look(m,nx,i,px,py,pz);
        }
        if (type != EW_TYPE_BAT) {
            collide_living_with_player(
                m, nx, i, p, ox, oz, 0);
            collide_living_entities(m, nx, i, dimension);
        }
        if (generic_rider || type == EW_TYPE_BAT)
            living_body_update(m, now, nx, i);
        if (generic_rider)
            chicken_jockey_update_passenger(m, nx, st, i);
        if (trap_rider) {
            int vehicle = mob_slot_by_eid(
                m, m->skeleton_trap_vehicle_eid[i]);
            if (vehicle > 0) {
                /* EntityLiving.updateEntityActionState copies a mounted
                 * rider's navigator into its EntityLiving vehicle at speed
                 * 1.5.  The vehicle has already ticked in loaded-list order,
                 * so this path first drives it on the following tick. */
                if (nx->path_len[i]) {
                    /* The Path object was built for the 0.6-wide skeleton,
                     * but Path.getPosition(vehicle) recenters each integer
                     * PathPoint for the 1.396-wide horse. */
                    nx->path_tx[vehicle] =
                        (double)mc_floor(nx->path_tx[i]) + 1.0D;
                    nx->path_ty[vehicle] =
                        (double)mc_floor(nx->path_ty[i]);
                    nx->path_tz[vehicle] =
                        (double)mc_floor(nx->path_tz[i]) + 1.0D;
                    nx->path_len[vehicle] = 1;
                } else {
                    nx->path_len[vehicle] = 0;
                }
                m->passive_nav_speed[vehicle] = 1.5D;
                if (m->skeleton_trap_move_terminal_ticks[vehicle] > 0
                        || m->skeleton_trap_move_wait_latched[vehicle]) {
                    /* The rider has already consumed this boundary's helper.
                     * Its next near-target path request returns no path, just
                     * as the shared Java Path reaches its terminal index. */
                    m->skeleton_trap_move_wait_latched[i] = 1;
                    nx->path_len[i] = 0;
                    nx->path_len[vehicle] = 0;
                }
                if (m->skeleton_trap_bow_running[i]
                        && m->skeleton_trap_target_eid[i] >= 0
                        && m->passive_eat_time[i] >= 0) {
                    m->skeleton_trap_move_wait_latched[vehicle] = 0;
                    m->skeleton_trap_move_terminal_ticks[vehicle] = 0;
                    m->skeleton_trap_move_action[vehicle] = 2;
                    m->skeleton_trap_move_forward[vehicle] =
                        (m->passive_tasks[i] & (1u << 17))
                        ? -0.5F : 0.5F;
                    m->skeleton_trap_move_strafe[vehicle] =
                        (m->passive_tasks[i] & (1u << 16))
                        ? 0.5F : -0.5F;
                } else {
                    int rider_wandering =
                        m->skeleton_trap_target_eid[i] < 0
                        && nx->path_len[i] != 0;
                    m->skeleton_trap_move_x[vehicle] = rider_wandering
                        ? nx->path_tx[i] : target_x;
                    m->skeleton_trap_move_y[vehicle] = rider_wandering
                        ? nx->path_ty[i] : target_y;
                    m->skeleton_trap_move_z[vehicle] = rider_wandering
                        ? nx->path_tz[i] : target_z;
                    m->skeleton_trap_move_speed[vehicle] = 1.0D;
                    if (!m->skeleton_trap_move_wait_latched[vehicle]
                            && m->skeleton_trap_move_terminal_ticks[vehicle]
                                == 0)
                        m->skeleton_trap_move_action[vehicle] =
                            nx->path_len[i] ? 1 : 0;
                    m->skeleton_trap_move_forward[vehicle] = 0.0F;
                    m->skeleton_trap_move_strafe[vehicle] = 0.0F;
                }
                /* AbstractHorse.updatePassenger uses prevRearingAmount after
                 * the vehicle's update, and a living passenger first lends
                 * its renderYawOffset to the horse. A moving trap rider's
                 * render yaw is its rotation yaw on this boundary. */
                float rearing =
                    m->horse_prev_rearing_amount[vehicle];
                float radians = nx->yaw[i] * 0.017453292F;
                float offset = 0.7F * rearing;
                nx->x[i] = nx->x[vehicle]
                    + (double)(offset * mc_sin(st, radians));
                nx->y[i] = nx->y[vehicle]
                    + (double)1.6F * 0.75D - 0.1875D - 0.6D
                    + (double)(0.15F * rearing);
                nx->z[i] = nx->z[vehicle]
                    - (double)(offset * mc_cos(st, radians));
            }
            living_cold_flush_one_from_store(
                m, nx, GM_MOB_LIVING_STAGE_SLOT_SECONDARY,
                &m->living_staged_cold_secondary);
        }
        if (type == EW_TYPE_IRON_GOLEM)
            iron_golem_living_tail(m, w, nx, i);
        if (type == EW_TYPE_SNOWMAN)
            tick_snowman_living_tail(
                m, w, clock, nx, i, drops, do_mob_loot,
                math_random_seed48, next_entity_id, mob_griefing);
        if (type == EW_TYPE_VEX && m->vex_limited_life[i]
                && --m->vex_life_ticks[i] <= 0) {
            m->vex_life_ticks[i] = 20;
            if (mob_effect_magic_damage(m, nx, i, 1.0F)
                    && nx->health[i] <= 0.0F) {
                m->entity_dead[i] = 1;
                m->entity_death_time[i] = 0;
            }
        }
        if (gm_mobs_horse_type(type) && !horse_pre_ticked)
            horse_lifecycle_pre_tick(m, nx, i);
        if (gm_mobs_vanilla_leashable_type(type)
                && m->llama_leashed[i])
            living_leash_tail(
                m, nx, i, dimension, px, py, pz, v->health,
                math_random_seed48, next_entity_id, drops);
        if (passive) {
            animal_age_love_tail(m, nx, i);
            /* forcedAgeTimer is client-only. The authoritative server state
             * stays at 40; a later visual-client slice owns its countdown. */
        }
        if (gm_mobs_horse_type(type)
                && horse_lifecycle_post_tick(m, w, nx, i))
            continue;
        if (type == EW_TYPE_VILLAGER) {
            if (m->growing_age[i] < 0) ++m->growing_age[i];
            else if (m->growing_age[i] > 0) --m->growing_age[i];
        }
        if (type == EW_TYPE_CHICKEN)
            chicken_living_tail(
                m, nx, i, math_random_seed48, next_entity_id, drops);
        if (type == EW_TYPE_PIG
                && ride_is_slot(nx, i, m->pig_ride_eid)) {
            pig_update_passenger_pose(nx, i, p, ox, oz);
        }
        if (gm_mobs_horse_type(type)
                && ride_is_slot(nx, i, m->horse_ride_eid))
            horse_update_passenger_pose(m, nx, st, i, p, ox, oz);
        /* After super.onUpdate/move: wasOnGround edges then alterSquishAmount. */
        if(gm_is_slimey(type)){
            int on = nx->on_ground[i] ? 1 : 0;
            if(on && !m->was_on_ground[i]) m->squish_amount[i] = -0.5f;
            else if(!on && m->was_on_ground[i]) m->squish_amount[i] = 1.0f;
            m->was_on_ground[i] = (unsigned char)on;
            float damp = (type == EW_TYPE_MAGMA) ? 0.9f : 0.6f;
            m->squish_amount[i] *= damp; /* alterSquishAmount */
        }
    }
    /* Catch non-breeding XP spawned by an initial living update. Breeding
     * children and XP retain their exact paired append order in the event tail. */
    for (int xp_slot = 0; xp_slot < xp_slot_limit(m); ++xp_slot) {
        McOrb *orb = xp_orb_at(m, xp_slot);
        int ticked = xp_slot < GM_XP_ORBS ? ticked_xp[xp_slot] : 0;
        int spawned = xp_slot < GM_XP_ORBS ? spawned_xp[xp_slot] : 0;
        if (xp_slot >= GM_XP_ORBS) {
            for (int index = 0; index < initial_loaded_count; ++index)
                if (loaded_ref_at(m, index)->kind == GM_MOB_LOADED_XP
                        && loaded_ref_at(m, index)->slot
                            == (unsigned int)xp_slot) {
                    ticked = 1;
                    break;
                }
            for (int event = 0; event < same_tick_spawn_count; ++event)
                if (same_tick_spawns[event].kind == GM_SAME_TICK_XP
                        && same_tick_spawns[event].slot == xp_slot) {
                    spawned = 1;
                    break;
                }
        }
        if (!ticked && !spawned && !orb->dead && orb->xpValue > 0
                && *xp_dimension_at(m, xp_slot) == m->active_dimension) {
            tick_order_append(m, orb->eid);
            tick_xp_orb_slot(m, w, p, ox, oz, &xp_player, xp_slot);
        }
    }
    for (int event = 0; event < same_tick_spawn_count; ++event) {
        if (same_tick_spawns[event].kind == GM_SAME_TICK_ANIMAL) {
            int slot = same_tick_spawns[event].slot;
            tick_order_append(m, nx->id[slot]);
            animal_tick_newborn_same_boundary(
                m, w, st, nx, slot,
                px, py, pz, mob_griefing);
        } else if (same_tick_spawns[event].kind == GM_SAME_TICK_XP) {
            int slot = same_tick_spawns[event].slot;
            tick_order_append(m, xp_orb_at(m, slot)->eid);
            tick_xp_orb_slot(
                m, w, p, ox, oz, &xp_player,
                slot);
        } else {
            int slot = same_tick_spawns[event].slot;
            tick_order_append(m, nx->id[slot]);
            villager_tick_newborn_same_boundary(m, w, st, nx, slot);
        }
    }
    living_cold_flush_from_store(m, nx);
    ++m->tick;m->current^=1;
    loaded_order_compact(m);
}

void gm_mobs_tick(GmMobLive *m, GmWorld *w, const struct Chunk *window,
                  const struct McSinTable *st,
                  struct PsvPlayer *player, struct PvStats *vitals,
                  int ox, int oz, int dimension, long long world_time,
                  const GmWorldClock *clock,
                  int mob_griefing, uint64_t *world_random_seed48,
                  uint64_t *math_random_seed48, int *next_entity_id,
                  int do_mob_loot, GmLiveSim *drops,
                  float boat_forward, float boat_strafe) {
    gm_mobs_tick_spawn_context(
        m, w, window, st, player, vitals, ox, oz, dimension, world_time,
        clock, mob_griefing, world_random_seed48, math_random_seed48,
        next_entity_id, NULL, do_mob_loot, drops,
        boat_forward, boat_strafe);
}

int gm_mobs_take_guardian_curse(GmMobLive *m, int *elder_eid) {
    if (!m || m->guardian_curse_pending_eid == 0) return 0;
    if (elder_eid) *elder_eid = m->guardian_curse_pending_eid;
    m->guardian_curse_pending_eid = 0;
    return 1;
}

int gm_mobs_fill_views(const GmMobLive *m, GmEntityView *out, int max) {
    if(!m||!out||max<=0)return 0;
    GmMobLive *mutable_m = (GmMobLive *)m;
    const EwStore *s;
    int n=0;
    gm_mobs_living_cold_flush(mutable_m);
    for(int entity=1;
            entity<EW_SPAWN_LIMIT + m->living_cold_count && n<max;
            ++entity) {
        int i = entity < EW_SPAWN_LIMIT
            ? entity
            : living_cold_stage(mutable_m, entity - EW_SPAWN_LIMIT);
        s = const_store(m);
        if(s->alive[i]&&m->entity_dimension[i]==m->active_dimension&&gm_living(s->type[i])){
        out[n]=(GmEntityView){0};
        out[n].type=s->type[i];
        if(s->type[i]==EW_TYPE_STRAY) {
            out[n].type=EW_TYPE_SKELETON;
            out[n].skin=24; /* CR_MOB_STRAY + 1 */
        }
        if(s->type[i]==EW_TYPE_HUSK) {
            out[n].type=EW_TYPE_ZOMBIE;
            out[n].skin=12; /* CR_MOB_HUSK + 1 */
        }
        if(s->type[i]==EW_TYPE_MOOSHROOM) {
            out[n].type=EW_TYPE_COW;
            out[n].skin=16; /* CR_MOB_MOOSHROOM + 1 */
        }
        if(s->type[i]==EW_TYPE_CAVE_SPIDER)
            out[n].skin=4; /* CR_MOB_CAVE_SPIDER + 1 */
        /* Live pigman uses type 15; render as zombie silhouette + pigman skin.
         * Keep type 15 so callers can identify pigmen; entity_render maps it. */
        if(s->type[i]==EW_TYPE_PIGMAN)
            out[n].skin = 18; /* CR_MOB_PIGMAN+1 (atlas index 17) */
        out[n].x=(float)s->x[i];out[n].y=(float)s->y[i];
        out[n].z=(float)s->z[i];out[n].yaw=s->yaw[i];
        out[n].pitch=m->entity_pitch[i];
        out[n].health=s->type[i]==EW_TYPE_BOAT?-1.0f:s->health[i];
        out[n].ent_id=s->id[i];
        out[n].ticks_existed=m->entity_ticks_existed[i];
        out[n].limb_swing_amount=m->entity_limb_swing_amount[i];
        out[n].hurt_time=m->entity_hurt_time[i];
        out[n].death_time=m->entity_death_time[i];
        if(gm_passive(s->type[i]) || s->type[i] == EW_TYPE_BAT){
            out[n].head_yaw=m->passive_head_yaw[i];
            out[n].pitch=m->passive_head_pitch[i];
        }
        if (s->type[i] == EW_TYPE_BAT && m->bat_hanging[i])
            out[n].flags |= GM_ENTITY_FLAG_BAT_HANGING;
        if (s->type[i] == EW_TYPE_SNOWMAN && m->snowman_pumpkin[i])
            out[n].flags |= GM_ENTITY_FLAG_SNOWMAN_PUMPKIN;
        if (s->type[i] == EW_TYPE_SQUID) {
            /* RenderSquid consumes four fields that are unrelated to the
             * generic living head/body pose. Keep the type-local mapping
             * explicit at the simulation-to-render handoff. */
            out[n].yaw = m->squid_render_yaw_offset[i];
            out[n].pitch = m->squid_pitch[i];
            out[n].head_yaw = m->squid_yaw[i];
            out[n].anim_time = m->squid_tentacle_angle[i];
        }
        if (s->type[i] == EW_TYPE_POLAR_BEAR)
            out[n].anim_time = m->polar_stand_animation[i] / 6.0F;
        if (s->type[i] == EW_TYPE_RABBIT) {
            out[n].item_meta = m->rabbit_type[i];
            out[n].anim_time = m->rabbit_jump_duration[i] > 0
                ? (float)m->rabbit_jump_ticks[i]
                    / (float)m->rabbit_jump_duration[i]
                : 0.0F;
        }
        if (s->type[i] == EW_TYPE_VILLAGER
                || s->type[i] == EW_TYPE_ZOMBIE_VILLAGER) {
            out[n].item_id = m->villager_profession[i];
            out[n].head_yaw = m->passive_head_yaw[i];
            out[n].pitch = m->passive_head_pitch[i];
        }
        if (s->type[i] == EW_TYPE_VINDICATOR
                || s->type[i] == EW_TYPE_EVOKER) {
            out[n].head_yaw = s->yaw[i];
            out[n].pitch = m->passive_head_pitch[i];
            if (s->type[i] == EW_TYPE_VINDICATOR
                    && s->ai_state[i] != EW_AI_IDLE) {
                out[n].flags |= 256;
                out[n].item_id = 258; /* iron axe */
            }
            if (s->type[i] == EW_TYPE_EVOKER
                    && m->evoker_spell_ticks[i] > 0)
                out[n].flags |= 512;
        }
        if (s->type[i] == EW_TYPE_VEX) {
            out[n].head_yaw = s->yaw[i];
            out[n].item_id = 267; /* iron sword */
            if (m->vex_charging[i]) out[n].flags |= 1024;
        }
        if (s->type[i] == EW_TYPE_GUARDIAN
                || s->type[i] == EW_TYPE_ELDER_GUARDIAN) {
            out[n].head_yaw = s->yaw[i];
            out[n].anim_time = m->guardian_tail_animation[i];
            out[n].graze_y = m->guardian_spikes_animation[i];
            if (m->guardian_moving[i]) out[n].flags |= 2048;
            if (m->guardian_target_eid[i] > 0) {
                int duration = s->type[i] == EW_TYPE_ELDER_GUARDIAN
                    ? 60 : 80;
                out[n].flags |= 4096;
                out[n].swing_progress =
                    (float)m->guardian_attack_counter[i] / (float)duration;
                if (out[n].swing_progress < 0.0F)
                    out[n].swing_progress = 0.0F;
                if (out[n].swing_progress > 1.0F)
                    out[n].swing_progress = 1.0F;
                out[n].has_heal_beam = 1;
                out[n].heal_x = (float)s->path_tx[i];
                out[n].heal_y = (float)s->path_ty[i];
                out[n].heal_z = (float)s->path_tz[i];
            }
        }
        if (s->type[i] == EW_TYPE_IRON_GOLEM) {
            out[n].head_yaw = s->yaw[i];
            out[n].golem_attack_timer = m->golem_attack_timer[i];
            out[n].golem_rose_timer = m->golem_hold_rose_tick[i];
            out[n].limb_swing = m->golem_limb_swing[i];
            out[n].limb_swing_amount = m->golem_limb_amount[i];
        }
        if (s->type[i] == EW_TYPE_PIG) {
            out[n].pitch = m->pig_pitch[i];
            out[n].head_yaw = m->pig_head_yaw[i] - m->pig_render_yaw[i];
            out[n].limb_swing = m->pig_limb_swing[i];
            out[n].limb_swing_amount = m->pig_limb_amount[i];
        }
        if (tameable_type(s->type[i])) {
            out[n].item_meta = m->tameable_variant[i];
            if (m->tameable_sitting[i]) out[n].flags |= 64;
            if (m->tameable_tamed[i]) out[n].flags |= 128;
        }
        if (s->type[i] == EW_TYPE_WITCH && m->witch_drinking[i]) {
            out[n].item_id = 373;
            out[n].item_count = 1;
            out[n].flags |= 32; /* authoritative Witch drinking state */
        }
        if((s->type[i]==EW_TYPE_BLAZE&&m->blaze_charged[i])||
           (s->type[i]!=EW_TYPE_BLAZE&&m->fire_ticks[i]>0))
            out[n].flags|=1; /* EntityLivingBase.isBurning */
        if (mob_effect_amplifier(m, i, 14) >= 0)
            out[n].flags |= 4; /* EntityLivingBase.isInvisible */
        if (mob_effect_amplifier(m, i, 24) >= 0)
            out[n].flags |= GM_ENTITY_FLAG_GLOWING;
        out[n].item_meta = s->type[i] == EW_TYPE_BOAT
            ? m->boat_variant[i] : m->size[i];
        if (gm_mobs_horse_type(s->type[i])) {
            /* ModelHorse setLivingAnimations at render partial=1. The generic
             * fields are type-local: item/item_meta select the layered skin,
            * graze/swing/squish carry eat/rear/mouth interpolation, and the
            * high flag bits are horse-only visible parts. */
            out[n].tape_pose = 1;
            if (s->type[i] == EW_TYPE_LLAMA) {
                out[n].item_id = m->llama_variant[i];
                out[n].item_meta = m->llama_decor[i] + 1;
            } else {
                out[n].item_id = m->horse_variant[i];
                out[n].item_meta = m->horse_armor[i];
            }
            out[n].graze_y = m->horse_head_lean[i];
            out[n].swing_progress = m->horse_rearing_amount[i];
            out[n].squish = m->horse_mouth_openness[i];
            out[n].limb_swing = m->horse_limb_swing[i];
            out[n].limb_swing_amount = m->horse_limb_amount[i];
            if (m->horse_chested[i]) out[n].flags |= 8192;
            if (m->horse_status[i] & GM_HORSE_SADDLED)
                out[n].flags |= 16384;
            if (ride_is_slot(s, i, m->horse_ride_eid))
                out[n].flags |= 32768;
            if (m->horse_tail_counter[i] != 0) out[n].flags |= 65536;
        }
        if (s->type[i] == EW_TYPE_SHEEP) {
            int timer = m->sheep_eat_timer[i];
            out[n].fleece_color = m->sheep_data[i] & 15;
            out[n].sheared = (m->sheep_data[i] & 16) != 0;
            out[n].flags |= 16; /* live sheep graze fields are authoritative */
            if (timer <= 0) {
                out[n].graze_y = 0.0F;
                out[n].graze_x = 0.0F;
            } else {
                if (timer >= 4 && timer <= 36)
                    out[n].graze_y = 1.0F;
                else if (timer < 4)
                    out[n].graze_y = (float)timer / 4.0F;
                else
                    out[n].graze_y = -(float)(timer - 40) / 4.0F;
                if (timer > 4 && timer <= 36) {
                    float phase = (float)(timer - 4) / 32.0F;
                    out[n].graze_x = (float)(MC_PI / 5.0)
                        + (float)(MC_PI * 7.0 / 100.0)
                            * sinf(phase * 28.7F);
                } else {
                    out[n].graze_x = (float)(MC_PI / 5.0);
                }
            }
        }
        if (m->growing_age[i] < 0)
            out[n].flags |= 8;
        out[n].squish=m->squish_factor[i]; /* EntitySlime.squishFactor */
        out[n].creeper_fuse=m->creeper_fuse[i];
        /* Recorder flags bit 0 is EntityLivingBase.isBurning(). Live state
         * tracks only generic fire ticks and EntityBlaze's charged override. */
        if(m->fire_ticks[i]>0 ||
           (s->type[i]==EW_TYPE_BLAZE && m->blaze_on_fire[i]))
            out[n].flags |= 1;
        ++n;
        }
    }
    gm_mobs_living_cold_flush(mutable_m);
    for (int i = 0; i < m->evoker_fang_count && n < max; ++i) {
        const GmEvokerFang *fang = &m->evoker_fangs[i];
        if (!fang->active || !fang->sent_spike
                || fang->dimension != m->active_dimension)
            continue;
        GmEntityView v;
        memset(&v, 0, sizeof v);
        v.type = GM_VIEW_EVOKER_FANGS;
        v.x = (float)fang->x;
        v.y = (float)fang->y;
        v.z = (float)fang->z;
        v.yaw = fang->yaw + 90.0F;
        v.health = -1.0F;
        v.ent_id = fang->eid;
        v.swing_progress = 1.0F - (float)(fang->life_ticks - 3) / 20.0F;
        if (v.swing_progress < 0.0F) v.swing_progress = 0.0F;
        if (v.swing_progress > 1.0F) v.swing_progress = 1.0F;
        out[n++] = v;
    }
    for(int i=0;i<xp_slot_limit(m)&&n<max;++i){
        const McOrb *o=xp_orb_at_const(m,i);
        if(o->dead||o->xpValue<=0
                ||*xp_dimension_at((GmMobLive *)m,i)!=m->active_dimension)continue;
        GmEntityView v; memset(&v,0,sizeof v);
        v.type=GM_ENTITY_XP_ORB;
        v.x=(float)o->posX;v.y=(float)o->posY;v.z=(float)o->posZ;
        v.health=(float)o->xpValue;   /* legacy field */
        v.item_id=o->xpValue;         /* getTextureByXP */
        v.item_meta=o->xpColor;       /* RenderXPOrb colour phase */
        v.age=o->xpOrbAge;
        out[n++]=v;
    }return n;
}

int gm_mobs_alive(const GmMobLive *m){return m?alive_count(m,const_store(m)):0;}

static int mob_slot_by_eid(const GmMobLive *m, int eid) {
    if (!m || eid < 0) return -1;
    const EwStore *s = const_store(m);
    for (int i = 1; i < EW_SPAWN_LIMIT; ++i)
        if (s->alive[i] && s->id[i] == eid) return i;
    for (int cold = 0; cold < m->living_cold_count; ++cold)
        if (m->living_cold[cold].store_alive
                && m->living_cold[cold].store_id == eid)
            return living_cold_stage((GmMobLive *)m, cold);
    return -1;
}

int gm_mobs_find_slot_by_eid(const GmMobLive *m, int eid) {
    return mob_slot_by_eid(m, eid);
}

int gm_mobs_set_entity_uuid(
        GmMobLive *m, int eid, int64_t uuid_most, int64_t uuid_least) {
    int slot = mob_slot_by_eid(m, eid);
    if (slot > 0) {
        m->entity_uuid_present[slot] = 1;
        m->entity_uuid_most[slot] = uuid_most;
        m->entity_uuid_least[slot] = uuid_least;
        return 1;
    }
    if (!m) return 0;
    for (slot = 0; slot < xp_slot_limit(m); ++slot) {
        McOrb *orb = xp_orb_at(m, slot);
        if (!orb->dead && orb->xpValue > 0 && orb->eid == eid) {
            *xp_uuid_present_at(m, slot) = 1;
            *xp_uuid_most_at(m, slot) = uuid_most;
            *xp_uuid_least_at(m, slot) = uuid_least;
            return 1;
        }
    }
    return 0;
}

int gm_mobs_type_by_eid(const GmMobLive *m, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    return slot < 0 ? EW_TYPE_NONE : const_store(m)->type[slot];
}

static void pig_packet_contact_transition_exact(
        GmMobLive *m, EwStore *s, int slot, int eid,
        int cactus_contact, int flammable_contact, int wet_contact,
        double event_x, double event_y, double event_z, int clear_fall,
        uint64_t *math_random_seed48) {
    if (clear_fall) {
        m->entity_server_fall_distance[slot] = 0.0F;
        if (m->pig_vehicle_server.valid
                && m->pig_vehicle_server.eid == eid)
            m->pig_vehicle_server.fall_distance = 0.0F;
    }
    if (cactus_contact)
        (void)ridden_pig_environment_damage(
            m, s, slot, 1.0F, 0,
            event_x, event_y, event_z, math_random_seed48);
    if (flammable_contact) {
        (void)ridden_pig_environment_damage(
            m, s, slot, 1.0F, 1,
            event_x, event_y, event_z, math_random_seed48);
        if (!wet_contact) {
            ++m->fire_ticks[slot];
            if (m->fire_ticks[slot] == 0)
                m->fire_ticks[slot] = 8 * 20;
        }
    } else if (m->fire_ticks[slot] <= 0) {
        m->fire_ticks[slot] = -1;
    }
    if (wet_contact && m->fire_ticks[slot] > 0) {
        (void)jrand_float(&m->entity_server_random[slot].random);
        (void)jrand_float(&m->entity_server_random[slot].random);
        m->fire_ticks[slot] = -1;
    }
}

static void pig_packet_contact_checkpoint_at(
        GmMobLive *m, const EwStore *s, int slot, int eid,
        double x, double y, double z, const McAABB *box,
        float fall_distance, int in_water, int in_lava,
        const uint64_t *math_random_seed48) {
    uint64_t seq = m->pig_packet_contact_checkpoint.seq + 1;
    m->pig_packet_contact_checkpoint =
        (GmPigPacketContactCheckpoint){
            .seq = seq,
            .valid = 1,
            .eid = eid,
            .x = x,
            .y = y,
            .z = z,
            .box = *box,
            .fall_distance = fall_distance,
            .is_in_water = in_water ? 1 : 0,
            .is_in_lava = in_lava ? 1 : 0,
            .health = s->health[slot],
            .fire_ticks = m->fire_ticks[slot],
            .hurt_time = m->entity_hurt_time[slot],
            .hurt_resistant_time = m->entity_hurt_resistant[slot],
            .fire_resistance_ticks =
                m->entity_server_fire_resistance_ticks[slot],
            .last_damage = m->entity_last_damage[slot],
            .alive = s->alive[slot] ? 1 : 0,
            .entity_seed48 =
                m->entity_server_random[slot].random.seed,
            .math_seed48 = math_random_seed48
                ? *math_random_seed48 : 0
        };
}

int gm_mobs_pig_packet_contact_exact(
        GmMobLive *m, int eid, int cactus_contact, int flammable_contact,
        int wet_contact,
        uint64_t *math_random_seed48) {
    int slot = m ? mob_slot_by_eid(m, m->pig_ride_eid) : -1;
    if (slot <= 0) return 0;
    EwStore *s = now_store(m);
    if (!s->alive[slot] || s->id[slot] != eid
            || s->type[slot] != EW_TYPE_PIG)
        return 0;
    /* NetHandlerPlayServer subtracts 1e-6 from an otherwise stationary packet
     * move. The support collision resolves it to zero and updateFallState
     * clears the authoritative fall ledger before block callbacks. */
    pig_packet_contact_transition_exact(
        m, s, slot, eid, cactus_contact, flammable_contact, wet_contact,
        s->x[slot], s->y[slot], s->z[slot], 1, math_random_seed48);
    McAABB box;
    (void)mob_slot_world_box(m, s, slot, &box);
    pig_packet_contact_checkpoint_at(
        m, s, slot, eid, s->x[slot], s->y[slot], s->z[slot], &box,
        m->entity_server_fall_distance[slot],
        m->entity_server_in_water[slot], m->entity_server_in_lava[slot],
        math_random_seed48);
    return 1;
}

static void pig_packet_contact_flags_at_box(
        const struct Chunk *window, int ox, int oz, const McAABB *box,
        int *cactus_contact, int *flammable_contact) {
    int cactus = 0;
    int x0 = mc_floor(box->minX + 0.001);
    int x1 = mc_floor(box->maxX - 0.001);
    int y0 = mc_floor(box->minY + 0.001);
    int y1 = mc_floor(box->maxY - 0.001);
    int z0 = mc_floor(box->minZ + 0.001);
    int z1 = mc_floor(box->maxZ - 0.001);
    for (int x = x0; x <= x1 && !cactus; ++x)
        for (int y = y0; y <= y1 && !cactus; ++y)
            for (int z = z0; z <= z1; ++z)
                if (psv_get_block(
                        (const Chunk *)window, x - ox, y, z - oz) == 81) {
                    cactus = 1;
                    break;
                }

    int flammable = 0;
    x0 = mc_floor(box->minX + 0.001);
    x1 = psv_ceil(box->maxX - 0.001);
    y0 = mc_floor(box->minY + 0.001);
    y1 = psv_ceil(box->maxY - 0.001);
    z0 = mc_floor(box->minZ + 0.001);
    z1 = psv_ceil(box->maxZ - 0.001);
    for (int x = x0; x < x1 && !flammable; ++x)
        for (int y = y0; y < y1 && !flammable; ++y)
            for (int z = z0; z < z1; ++z) {
                int id = psv_get_block(
                    (const Chunk *)window, x - ox, y, z - oz);
                if (id == 51 || id == 10 || id == 11) {
                    flammable = 1;
                    break;
                }
            }
    *cactus_contact = cactus;
    *flammable_contact = flammable;
}

int gm_mobs_pig_packet_contact_world_exact(
        GmMobLive *m, const struct Chunk *window, int ox, int oz, int eid,
        uint64_t *math_random_seed48) {
    int slot = m ? mob_slot_by_eid(m, m->pig_ride_eid) : -1;
    if (!m || !window || slot <= 0)
        return 0;
    const EwStore *s = const_store(m);
    if (!s->alive[slot] || s->id[slot] != eid
            || s->type[slot] != EW_TYPE_PIG)
        return 0;

    McAABB box;
    if (!mob_slot_world_box(m, s, slot, &box)) return 0;

    int cactus_contact, flammable_contact;
    pig_packet_contact_flags_at_box(
        window, ox, oz, &box, &cactus_contact, &flammable_contact);

    return gm_mobs_pig_packet_contact_exact(
        m, eid, cactus_contact, flammable_contact,
        m->entity_server_in_water[slot] ? 1 : 0,
        math_random_seed48);
}

static int pig_packet_box_clear(
        const struct Chunk *window, int ox, int oz, const McAABB *world_box,
        McAABB *scratch, int capacity) {
    McAABB local = *world_box;
    local.minX -= ox;
    local.maxX -= ox;
    local.minZ -= oz;
    local.maxZ -= oz;
    int count = psv_collect_blocks(
        (const Chunk *)window, &local, scratch, capacity);
    for (int i = 0; i < count; ++i)
        if (mc_aabb_intersects(&local, &scratch[i])) return 0;
    return 1;
}

static McAABB pig_packet_target_box(
        const GmMobLive *m, const EwStore *s, int slot,
        double x, double y, double z) {
    float width, height;
    ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
    if (gm_passive(s->type[slot]) && m->growing_age[slot] < 0) {
        width *= 0.5F;
        height *= 0.5F;
    }
    double half = (double)width * 0.5;
    return mc_aabb_make(
        x - half, y, z - half, x + half, y + height, z + half);
}

static void pig_packet_store_pose(
        GmMobLive *m, EwStore *s, int slot,
        double x, double y, double z, const McAABB *box,
        float yaw, float pitch) {
    s->x[slot] = x;
    s->y[slot] = y;
    s->z[slot] = z;
    s->yaw[slot] = yaw;
    m->pig_pitch[slot] = pitch;
    m->entity_box_min_x[slot] = box->minX;
    m->entity_box_min_y[slot] = box->minY;
    m->entity_box_min_z[slot] = box->minZ;
    m->entity_box_max_x[slot] = box->maxX;
    m->entity_box_max_y[slot] = box->maxY;
    m->entity_box_max_z[slot] = box->maxZ;
    m->entity_box_valid[slot] = 1;
}

int gm_mobs_pig_packet_move_dry_exact(
        GmMobLive *m, const struct Chunk *window, int ox, int oz, int eid,
        double target_x, double target_y, double target_z,
        float target_yaw, float target_pitch,
        GmPigVehicleMoveResult *out) {
    int slot = m ? mob_slot_by_eid(m, m->pig_ride_eid) : -1;
    if (!m || !window || !out || slot <= 0
            || !isfinite(target_x) || !isfinite(target_y)
            || !isfinite(target_z) || !isfinite(target_yaw)
            || !isfinite(target_pitch))
        return 0;
    EwStore *s = now_store(m);
    if (!s->alive[slot] || s->id[slot] != eid
            || s->type[slot] != EW_TYPE_PIG)
        return 0;

    memset(out, 0, sizeof *out);
    double old_x = s->x[slot], old_y = s->y[slot], old_z = s->z[slot];
    float old_yaw = s->yaw[slot], old_pitch = m->pig_pitch[slot];
    McAABB old_box;
    if (!mob_slot_world_box(m, s, slot, &old_box)) return 0;
    out->lowest_x = out->lowest_x1 = old_x;
    out->lowest_y = out->lowest_y1 = old_y;
    out->lowest_z = out->lowest_z1 = old_z;

    double dx = target_x - old_x;
    double dy = target_y - old_y;
    double dz = target_z - old_z;
    double motion_sq = s->vx[slot] * s->vx[slot]
        + s->vy[slot] * s->vy[slot]
        + s->vz[slot] * s->vz[slot];
    if (dx * dx + dy * dy + dz * dz - motion_sq > 100.0) {
        out->result = GM_PIG_VEHICLE_MOVE_CORRECTED_SPEED;
        out->correction_count = 1;
        out->correction_x = old_x;
        out->correction_y = old_y;
        out->correction_z = old_z;
        out->correction_yaw = old_yaw;
        out->correction_pitch = old_pitch;
        return 1;
    }

    McAABB contracted_old = mc_aabb_make(
        old_box.minX + 0.0625, old_box.minY + 0.0625,
        old_box.minZ + 0.0625, old_box.maxX - 0.0625,
        old_box.maxY - 0.0625, old_box.maxZ - 0.0625);
    int old_clear = pig_packet_box_clear(
        window, ox, oz, &contracted_old,
        m->pig_collision_scratch, GM_PIG_COLLISION_BOXES);

    McEntity entity;
    memset(&entity, 0, sizeof entity);
    entity.box = old_box;
    entity.posX = old_x;
    entity.posY = old_y;
    entity.posZ = old_z;
    entity.motionX = s->vx[slot];
    entity.motionY = s->vy[slot];
    entity.motionZ = s->vz[slot];
    entity.onGround = s->on_ground[slot] ? 1 : 0;
    double requested_y = dy - 1.0e-6;
    McAABB query = mc_aabb_addcoord(&old_box, dx, requested_y, dz);
    if (old_box.maxY + 0.6 > query.maxY)
        query.maxY = old_box.maxY + 0.6;
    McAABB local_query = query;
    local_query.minX -= ox;
    local_query.maxX -= ox;
    local_query.minZ -= oz;
    local_query.maxZ -= oz;
    int boxes = psv_collect_blocks(
        (const Chunk *)window, &local_query,
        m->pig_collision_scratch, GM_PIG_COLLISION_BOXES);
    for (int i = 0; i < boxes; ++i) {
        m->pig_collision_scratch[i].minX += ox;
        m->pig_collision_scratch[i].maxX += ox;
        m->pig_collision_scratch[i].minZ += oz;
        m->pig_collision_scratch[i].maxZ += oz;
    }
    mc_entity_move_step(
        &entity, dx, requested_y, dz,
        m->pig_collision_scratch, boxes, 0.6F);
    double moved_y = entity.posY - old_y;
    if (entity.onGround)
        m->entity_server_fall_distance[slot] = 0.0F;
    else if (moved_y < 0.0)
        m->entity_server_fall_distance[slot] -= (float)moved_y;
    s->vx[slot] = entity.motionX;
    s->vy[slot] = entity.motionY;
    s->vz[slot] = entity.motionZ;
    s->on_ground[slot] = (unsigned char)(entity.onGround ? 1 : 0);

    double residual_x = target_x - entity.posX;
    double residual_z = target_z - entity.posZ;
    int wrong = residual_x * residual_x + residual_z * residual_z > 0.0625;
    McAABB target_box = pig_packet_target_box(
        m, s, slot, target_x, target_y, target_z);
    McAABB contracted_target = mc_aabb_make(
        target_box.minX + 0.0625, target_box.minY + 0.0625,
        target_box.minZ + 0.0625, target_box.maxX - 0.0625,
        target_box.maxY - 0.0625, target_box.maxZ - 0.0625);
    int target_clear = pig_packet_box_clear(
        window, ox, oz, &contracted_target,
        m->pig_collision_scratch, GM_PIG_COLLISION_BOXES);
    if (old_clear && (wrong || !target_clear)) {
        pig_packet_store_pose(
            m, s, slot, old_x, old_y, old_z, &old_box,
            target_yaw, target_pitch);
        out->result = GM_PIG_VEHICLE_MOVE_CORRECTED_COLLISION;
        out->correction_count = 1;
        out->correction_x = old_x;
        out->correction_y = old_y;
        out->correction_z = old_z;
        out->correction_yaw = target_yaw;
        out->correction_pitch = target_pitch;
        return 1;
    }

    pig_packet_store_pose(
        m, s, slot, target_x, target_y, target_z, &target_box,
        target_yaw, target_pitch);
    out->result = GM_PIG_VEHICLE_MOVE_ACCEPTED;
    out->lowest_x1 = target_x;
    out->lowest_y1 = target_y;
    out->lowest_z1 = target_z;
    return 1;
}

static void pig_vehicle_runtime_checkpoint(
        GmMobLive *m, double target_x, double target_y, double target_z,
        float target_yaw, float target_pitch,
        uint64_t math_random_seed48) {
    const GmPigVehicleServerState *server = &m->pig_vehicle_server;
    int slot = mob_slot_by_eid(m, m->pig_ride_eid);
    const EwStore *client = const_store(m);
    McAABB client_box;
    (void)mob_slot_world_box(m, client, slot, &client_box);
    m->pig_vehicle_move_checkpoint = (GmPigVehicleMoveCheckpoint){
        .seq = server->packet_seq,
        .valid = 1,
        .eid = server->eid,
        .target_x = target_x,
        .target_y = target_y,
        .target_z = target_z,
        .target_yaw = target_yaw,
        .target_pitch = target_pitch,
        .x = server->x,
        .y = server->y,
        .z = server->z,
        .vx = server->vx,
        .vy = server->vy,
        .vz = server->vz,
        .box = server->box,
        .yaw = server->yaw,
        .pitch = server->pitch,
        .on_ground = server->on_ground,
        .fall_distance = server->fall_distance,
        .is_in_water = m->entity_server_in_water[slot] ? 1 : 0,
        .is_in_lava = m->entity_server_in_lava[slot] ? 1 : 0,
        .health = client->health[slot],
        .fire_ticks = m->fire_ticks[slot],
        .hurt_time = m->entity_hurt_time[slot],
        .hurt_resistant_time = m->entity_hurt_resistant[slot],
        .fire_resistance_ticks =
            m->entity_server_fire_resistance_ticks[slot],
        .last_damage = m->entity_last_damage[slot],
        .alive = client->alive[slot] ? 1 : 0,
        .entity_seed48 = m->entity_server_random[slot].random.seed,
        .math_seed48 = math_random_seed48,
        .client_x = client->x[slot],
        .client_y = client->y[slot],
        .client_z = client->z[slot],
        .client_box = client_box,
        .client_yaw = client->yaw[slot],
        .client_pitch = m->pig_pitch[slot],
        .move = server->last_move
    };
}

int gm_mobs_pig_packet_move_runtime_dry_exact(
        GmMobLive *m, const struct Chunk *window, int ox, int oz, int eid,
        double target_x, double target_y, double target_z,
        float target_yaw, float target_pitch,
        uint64_t *math_random_seed48) {
    int slot = m ? mob_slot_by_eid(m, m->pig_ride_eid) : -1;
    if (!m || !window || slot <= 0
            || !isfinite(target_x) || !isfinite(target_y)
            || !isfinite(target_z) || !isfinite(target_yaw)
            || !isfinite(target_pitch))
        return 0;
    EwStore *shared = now_store(m);
    const EwStore *client = shared;
    GmPigVehicleServerState *server = &m->pig_vehicle_server;
    if (!client->alive[slot] || client->id[slot] != eid
            || client->type[slot] != EW_TYPE_PIG
            || !server->valid || server->eid != eid)
        return 0;

    double old_x = server->x, old_y = server->y, old_z = server->z;
    float old_yaw = server->yaw, old_pitch = server->pitch;
    McAABB old_box = server->box;
    GmPigVehicleMoveResult move;
    memset(&move, 0, sizeof move);
    move.lowest_x = server->lowest_x;
    move.lowest_y = server->lowest_y;
    move.lowest_z = server->lowest_z;
    move.lowest_x1 = server->lowest_x1;
    move.lowest_y1 = server->lowest_y1;
    move.lowest_z1 = server->lowest_z1;
    ++server->packet_seq;

    double dx = target_x - server->lowest_x1;
    double dy = target_y - server->lowest_y1;
    double dz = target_z - server->lowest_z1;
    double speed_dx = target_x - server->lowest_x;
    double speed_dy = target_y - server->lowest_y;
    double speed_dz = target_z - server->lowest_z;
    double motion_sq = server->vx * server->vx
        + server->vy * server->vy + server->vz * server->vz;
    if (speed_dx * speed_dx + speed_dy * speed_dy
            + speed_dz * speed_dz - motion_sq > 100.0) {
        move.result = GM_PIG_VEHICLE_MOVE_CORRECTED_SPEED;
        move.correction_count = 1;
        move.correction_x = old_x;
        move.correction_y = old_y;
        move.correction_z = old_z;
        move.correction_yaw = old_yaw;
        move.correction_pitch = old_pitch;
        server->last_move = move;
        pig_vehicle_runtime_checkpoint(
            m, target_x, target_y, target_z, target_yaw, target_pitch,
            math_random_seed48 ? *math_random_seed48 : 0);
        return 1;
    }

    McAABB contracted_old = mc_aabb_make(
        old_box.minX + 0.0625, old_box.minY + 0.0625,
        old_box.minZ + 0.0625, old_box.maxX - 0.0625,
        old_box.maxY - 0.0625, old_box.maxZ - 0.0625);
    int old_clear = pig_packet_box_clear(
        window, ox, oz, &contracted_old,
        m->pig_collision_scratch, GM_PIG_COLLISION_BOXES);

    McEntity entity;
    memset(&entity, 0, sizeof entity);
    entity.box = old_box;
    entity.posX = old_x;
    entity.posY = old_y;
    entity.posZ = old_z;
    entity.motionX = server->vx;
    entity.motionY = server->vy;
    entity.motionZ = server->vz;
    entity.onGround = server->on_ground;
    double requested_y = dy - 1.0e-6;
    McAABB query = mc_aabb_addcoord(&old_box, dx, requested_y, dz);
    if (old_box.maxY + 0.6 > query.maxY)
        query.maxY = old_box.maxY + 0.6;
    McAABB local_query = query;
    local_query.minX -= ox;
    local_query.maxX -= ox;
    local_query.minZ -= oz;
    local_query.maxZ -= oz;
    int boxes = psv_collect_blocks(
        (const Chunk *)window, &local_query,
        m->pig_collision_scratch, GM_PIG_COLLISION_BOXES);
    for (int i = 0; i < boxes; ++i) {
        m->pig_collision_scratch[i].minX += ox;
        m->pig_collision_scratch[i].maxX += ox;
        m->pig_collision_scratch[i].minZ += oz;
        m->pig_collision_scratch[i].maxZ += oz;
    }
    mc_entity_move_step(
        &entity, dx, requested_y, dz,
        m->pig_collision_scratch, boxes, 0.6F);
    double moved_y = entity.posY - old_y;
    if (entity.onGround)
        server->fall_distance = 0.0F;
    else if (moved_y < 0.0)
        server->fall_distance -= (float)moved_y;
    server->vx = entity.motionX;
    server->vy = entity.motionY;
    server->vz = entity.motionZ;
    server->on_ground = entity.onGround ? 1 : 0;

    /* EntityLivingBase.updateFallState refreshes water only when the prior
     * inWater field is false. Entity.move then dispatches block collisions
     * and its flammable check at this temporary resolved AABB. All of those
     * side effects survive a later processVehicleMove rollback. */
    int persistent_water = m->entity_server_in_water[slot] ? 1 : 0;
    if (!persistent_water && pig_vehicle_box_in_liquid(
            window, ox, oz, &entity.box, 1)) {
        if (!server->first_update) {
            ridden_pig_water_entry_rng(
                &m->entity_server_random[slot].random,
                ridden_pig_slot_width(m, shared, slot));
        }
        persistent_water = 1;
        m->entity_server_in_water[slot] = 1;
        server->fall_distance = 0.0F;
        m->fire_ticks[slot] = 0;
    }
    int cactus_contact, flammable_contact;
    pig_packet_contact_flags_at_box(
        window, ox, oz, &entity.box,
        &cactus_contact, &flammable_contact);
    int temporary_lava = pig_vehicle_box_in_liquid(
        window, ox, oz, &entity.box, 0) ? 1 : 0;
    pig_packet_contact_transition_exact(
        m, shared, slot, eid, cactus_contact, flammable_contact,
        persistent_water, entity.posX, entity.posY, entity.posZ, 0,
        math_random_seed48);
    pig_packet_contact_checkpoint_at(
        m, shared, slot, eid,
        entity.posX, entity.posY, entity.posZ, &entity.box,
        server->fall_distance, persistent_water, temporary_lava,
        math_random_seed48);

    double residual_x = target_x - entity.posX;
    double residual_z = target_z - entity.posZ;
    int wrong = residual_x * residual_x + residual_z * residual_z > 0.0625;
    McAABB target_box = pig_packet_target_box(
        m, client, slot, target_x, target_y, target_z);
    McAABB contracted_target = mc_aabb_make(
        target_box.minX + 0.0625, target_box.minY + 0.0625,
        target_box.minZ + 0.0625, target_box.maxX - 0.0625,
        target_box.maxY - 0.0625, target_box.maxZ - 0.0625);
    int target_clear = pig_packet_box_clear(
        window, ox, oz, &contracted_target,
        m->pig_collision_scratch, GM_PIG_COLLISION_BOXES);
    if (old_clear && (wrong || !target_clear)) {
        server->x = old_x;
        server->y = old_y;
        server->z = old_z;
        server->box = old_box;
        server->yaw = target_yaw;
        server->pitch = target_pitch;
        move.result = GM_PIG_VEHICLE_MOVE_CORRECTED_COLLISION;
        move.correction_count = 1;
        move.correction_x = old_x;
        move.correction_y = old_y;
        move.correction_z = old_z;
        move.correction_yaw = target_yaw;
        move.correction_pitch = target_pitch;
    } else {
        server->x = target_x;
        server->y = target_y;
        server->z = target_z;
        server->box = target_box;
        server->yaw = target_yaw;
        server->pitch = target_pitch;
        server->lowest_x1 = target_x;
        server->lowest_y1 = target_y;
        server->lowest_z1 = target_z;
        move.result = GM_PIG_VEHICLE_MOVE_ACCEPTED;
        move.lowest_x1 = target_x;
        move.lowest_y1 = target_y;
        move.lowest_z1 = target_z;
    }
    m->entity_server_fall_distance[slot] = server->fall_distance;
    m->entity_server_in_lava[slot] = (unsigned char)(
        pig_vehicle_box_in_liquid(
            window, ox, oz, &server->box, 0) ? 1 : 0);
    server->last_move = move;
    pig_vehicle_runtime_checkpoint(
        m, target_x, target_y, target_z, target_yaw, target_pitch,
        math_random_seed48 ? *math_random_seed48 : 0);
    return 1;
}

int gm_mobs_get_pig_client_packet_pose(
        const GmMobLive *m, int *eid, double *x, double *y, double *z,
        float *yaw, float *pitch) {
    int mounted_eid;
    if (!gm_mobs_pig_riding(m, &mounted_eid)) return 0;
    int slot = mob_slot_by_eid(m, m->pig_ride_eid);
    const EwStore *client = const_store(m);
    if (eid) *eid = mounted_eid;
    if (x) *x = client->x[slot];
    if (y) *y = client->y[slot];
    if (z) *z = client->z[slot];
    if (yaw) *yaw = client->yaw[slot];
    if (pitch) *pitch = m->pig_pitch[slot];
    return 1;
}

int gm_mobs_pig_apply_client_vehicle_correction(
        GmMobLive *m, int eid, double x, double y, double z,
        float yaw, float pitch) {
    int slot = m ? mob_slot_by_eid(m, m->pig_ride_eid) : -1;
    if (!m || slot <= 0
            || !isfinite(x) || !isfinite(y) || !isfinite(z)
            || !isfinite(yaw) || !isfinite(pitch))
        return 0;
    EwStore *client = now_store(m);
    if (!client->alive[slot] || client->id[slot] != eid
            || client->type[slot] != EW_TYPE_PIG)
        return 0;
    McAABB box = pig_packet_target_box(m, client, slot, x, y, z);
    pig_packet_store_pose(
        m, client, slot, x, y, z, &box, yaw, pitch);
    return 1;
}

int gm_mobs_get_pig_vehicle_server_state(
        const GmMobLive *m, GmPigVehicleServerState *out) {
    if (!m || !out || !m->pig_vehicle_server.valid) return 0;
    *out = m->pig_vehicle_server;
    return 1;
}

int gm_mobs_get_pig_vehicle_move_checkpoint(
        const GmMobLive *m, GmPigVehicleMoveCheckpoint *out) {
    if (!m || !out || !m->pig_vehicle_move_checkpoint.valid) return 0;
    *out = m->pig_vehicle_move_checkpoint;
    return 1;
}

int gm_mobs_get_pig_packet_contact_checkpoint(
        const GmMobLive *m, GmPigPacketContactCheckpoint *out) {
    if (!m || !out || !m->pig_packet_contact_checkpoint.valid) return 0;
    *out = m->pig_packet_contact_checkpoint;
    return 1;
}

int gm_mobs_take_blaze_shot(GmMobLive *m, int slot, GmBlazeShot *shot) {
    if (!m || !shot || slot <= 0 || slot >= EW_MAX_ENTITIES
            || m->blaze_shots_pending[slot] == 0)
        return 0;
    int head = m->blaze_shot_head[slot] % GM_BLAZE_SHOT_QUEUE;
    *shot = m->blaze_shots[slot][head];
    memset(&m->blaze_shots[slot][head], 0,
           sizeof m->blaze_shots[slot][head]);
    m->blaze_shot_head[slot] =
        (unsigned char)((head + 1) % GM_BLAZE_SHOT_QUEUE);
    --m->blaze_shots_pending[slot];
    return 1;
}

int gm_mobs_take_witch_shot(GmMobLive *m, int slot, GmWitchShot *shot) {
    if (!m || !shot || slot <= 0 || slot >= EW_MAX_ENTITIES
            || m->witch_shots_pending[slot] == 0)
        return 0;
    int head = m->witch_shot_head[slot] % GM_WITCH_SHOT_QUEUE;
    *shot = m->witch_shots[slot][head];
    memset(&m->witch_shots[slot][head], 0,
           sizeof m->witch_shots[slot][head]);
    m->witch_shot_head[slot] =
        (unsigned char)((head + 1) % GM_WITCH_SHOT_QUEUE);
    --m->witch_shots_pending[slot];
    return 1;
}

