int gm_mobs_set_entity_random_state(
        GmMobLive *m, int eid, uint64_t seed48,
        int have_next_gaussian, double next_gaussian) {
    int slot = mob_slot_by_eid(m, eid);
    if (slot < 0 || (have_next_gaussian != 0 && have_next_gaussian != 1))
        return 0;
    jrand_gaussian_set_state(
        &m->entity_random[slot], (u64)seed48,
        have_next_gaussian, next_gaussian);
    jrand_gaussian_set_state(
        &m->entity_server_random[slot], (u64)seed48,
        have_next_gaussian, next_gaussian);
    return 1;
}

int gm_mobs_restore_no_ai_base_state(
        GmMobLive *m, int eid, int air, int fire_ticks, int on_ground,
        float fall_distance, int in_water, int ticks_existed,
        int living_sound_time, float last_damage, uint64_t seed48,
        int have_next_gaussian, double next_gaussian) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *now = m ? now_store(m) : NULL;
    EwStore *next = m ? next_store(m) : NULL;
    if (slot <= 0 || !now || !next || !m->controlled_no_ai[slot]
            || !gm_living(now->type[slot])
            || now->type[slot] == EW_TYPE_BOAT
            || air < -20 || air > 300
            || fire_ticks < -20 || fire_ticks > 32767
            || (on_ground != 0 && on_ground != 1)
            || (in_water != 0 && in_water != 1)
            || !isfinite(fall_distance) || fall_distance < 0.0F
            || ticks_existed < 0
            || living_sound_time < -1000000
            || living_sound_time > 1000000
            || !isfinite(last_damage) || last_damage < 0.0F
            || last_damage > 1000000.0F
            || !gm_mobs_set_entity_random_state(
                m, eid, seed48, have_next_gaussian, next_gaussian))
        return 0;
    m->entity_air[slot] = air;
    m->fire_ticks[slot] = fire_ticks;
    now->on_ground[slot] = (unsigned char)on_ground;
    next->on_ground[slot] = (unsigned char)on_ground;
    m->entity_fall_distance[slot] = fall_distance;
    m->entity_server_fall_distance[slot] = fall_distance;
    m->entity_in_water[slot] = (unsigned char)in_water;
    m->entity_server_in_water[slot] = (unsigned char)in_water;
    m->entity_ticks_existed[slot] = ticks_existed;
    m->entity_living_sound_time[slot] = living_sound_time;
    m->entity_server_living_sound_time[slot] = living_sound_time;
    m->entity_last_damage[slot] = last_damage;
    return 1;
}

int gm_mobs_restore_bat_state(GmMobLive *m, int eid, int hanging) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_BAT
            || !m->controlled_no_ai[slot]
            || (hanging != 0 && hanging != 1))
        return 0;
    m->bat_hanging[slot] = (unsigned char)hanging;
    return 1;
}

int gm_mobs_set_bat_ai_state(
        GmMobLive *m, int eid, int hanging, int spawn_position_valid,
        int spawn_x, int spawn_y, int spawn_z,
        float head_yaw, float render_yaw_offset,
        int body_rotation_tick_counter, float body_prev_head_yaw,
        int entity_age, int persistence_required) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_BAT
            || (hanging != 0 && hanging != 1)
            || (spawn_position_valid != 0 && spawn_position_valid != 1)
            || !isfinite(head_yaw) || !isfinite(render_yaw_offset)
            || body_rotation_tick_counter < 0
            || !isfinite(body_prev_head_yaw)
            || (persistence_required != 0 && persistence_required != 1))
        return 0;
    m->bat_hanging[slot] = (unsigned char)hanging;
    m->bat_spawn_position_valid[slot] =
        (unsigned char)spawn_position_valid;
    m->bat_spawn_x[slot] = spawn_position_valid ? spawn_x : 0;
    m->bat_spawn_y[slot] = spawn_position_valid ? spawn_y : 0;
    m->bat_spawn_z[slot] = spawn_position_valid ? spawn_z : 0;
    m->passive_head_yaw[slot] = head_yaw;
    m->squid_render_yaw_offset[slot] = render_yaw_offset;
    m->body_rotation_tick_counter[slot] = body_rotation_tick_counter;
    m->body_prev_head_yaw[slot] = body_prev_head_yaw;
    m->entity_age[slot] = entity_age;
    m->persistence_required[slot] =
        (unsigned char)persistence_required;
    return 1;
}

