int gm_mobs_restore_no_ai_box(
        GmMobLive *m, int eid, double min_x, double min_y, double min_z,
        double max_x, double max_y, double max_z) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || !m->controlled_no_ai[slot]
            || !isfinite(min_x) || !isfinite(min_y) || !isfinite(min_z)
            || !isfinite(max_x) || !isfinite(max_y) || !isfinite(max_z)
            || min_x > max_x || min_y > max_y || min_z > max_z
            || (min_x + max_x) * 0.5D != s->x[slot]
            || (s->type[slot] != EW_TYPE_BAT && min_y != s->y[slot])
            || (min_z + max_z) * 0.5D != s->z[slot])
        return 0;
    m->entity_box_min_x[slot] = min_x;
    m->entity_box_min_y[slot] = min_y;
    m->entity_box_min_z[slot] = min_z;
    m->entity_box_max_x[slot] = max_x;
    m->entity_box_max_y[slot] = max_y;
    m->entity_box_max_z[slot] = max_z;
    m->entity_box_valid[slot] = 1;
    return 1;
}

int gm_mobs_set_no_ai(GmMobLive *m, int eid, int no_ai) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *now = m ? now_store(m) : NULL;
    EwStore *next = m ? next_store(m) : NULL;
    if (slot <= 0 || !now || !next || !gm_living(now->type[slot])
            || now->type[slot] == EW_TYPE_BOAT
            || (no_ai != 0 && no_ai != 1))
        return 0;

    if (!no_ai && now->type[slot] == EW_TYPE_VILLAGER) {
        /* EntityList.createEntityFromNBT constructs fresh AI task objects.
         * None of their execution state is NBT-backed, so activation after a
         * cold restore starts from these constructor defaults. Persistent
         * villager data (profession, inventory, offers, age, willingness)
         * deliberately remains untouched. */
        m->villager_random_tick_divider[slot] = 0;
        m->villager_ai_tick_count[slot] = 0;
        m->villager_mate_eid[slot] = -1;
        m->villager_mating_timeout[slot] = 0;
        m->villager_mate_active[slot] = 0;
        m->villager_mating[slot] = 0;
        m->villager_follow_golem_active[slot] = 0;
        m->villager_took_golem_rose[slot] = 0;
        m->villager_follow_golem_eid[slot] = -1;
        m->villager_take_golem_rose_tick[slot] = 0;
        m->villager_front_door_valid[slot] = 0;
        m->villager_front_door_village[slot] = -1;
        m->villager_front_door_index[slot] = -1;
        m->villager_front_door_detached[slot] = 0;
        m->villager_restrict_door_active[slot] = 0;
        m->villager_door_restriction_pending[slot] = 0;
        m->villager_enter_doors[slot] = 1;
        m->villager_break_doors[slot] = 1;
        m->villager_open_door_active[slot] = 0;
        m->villager_stopped_door_interaction[slot] = 0;
        m->villager_close_door_timer[slot] = 0;
        m->villager_indoors_door_valid[slot] = 0;
        m->villager_move_indoors_active[slot] = 0;
        m->villager_last_inside_x[slot] = -1;
        m->villager_last_inside_z[slot] = -1;
        m->villager_home_valid[slot] = 0;
        m->villager_move_restriction_active[slot] = 0;
        m->villager_avoid_active[slot] = 0;
        m->villager_avoid_target_eid[slot] = -1;
        m->villager_avoid_speed[slot] = 0.0F;
        m->villager_play_active[slot] = 0;
        m->villager_playing[slot] = 0;
        m->villager_play_target_eid[slot] = -1;
        m->villager_play_time[slot] = 0;
        m->villager_harvest_active[slot] = 0;
        m->villager_harvest_has_item[slot] = 0;
        m->villager_harvest_wants_reap[slot] = 0;
        m->villager_harvest_current_task[slot] = -1;
        m->villager_harvest_run_delay[slot] = 0;
        m->villager_harvest_timeout[slot] = 0;
        m->villager_harvest_max_stay[slot] = 0;
        m->villager_interact_active[slot] = 0;
        m->villager_interact_target_eid[slot] = -1;
        m->villager_interact_look_time[slot] = 0;
        m->villager_interaction_delay[slot] = 0;
        m->villager_swim_active[slot] = 0;
        m->villager_trade_active[slot] = 0;
        m->villager_trade_look_active[slot] = 0;
        m->villager_trade_look_time[slot] = 0;
        m->villager_watch_player_active[slot] = 0;
        m->villager_watch_player_time[slot] = 0;
        m->villager_watch_living_active[slot] = 0;
        m->villager_watch_living_target_eid[slot] = -1;
        m->villager_watch_living_time[slot] = 0;
        m->villager_wander_active[slot] = 0;
        m->villager_village_valid[slot] = 0;
        m->villager_village_index[slot] = -1;
        m->villager_village_mating[slot] = 0;
        m->villager_village_doors[slot] = 0;
        m->villager_village_population[slot] = 0;
        m->villager_collection_pending[slot] = 0;
        now->path_len[slot] = 0;
        next->path_len[slot] = 0;
        m->passive_nav_speed[slot] = 0.0D;
        m->passive_head_yaw[slot] = now->yaw[slot];
        m->passive_head_pitch[slot] = 0.0F;
        if (m->active_villager_customer_eid == eid)
            m->active_villager_customer_eid = -1;
    }
    m->controlled_no_ai[slot] = (unsigned char)no_ai;
    m->controlled_block_collisions[slot] = (unsigned char)!no_ai;
    return 1;
}

int gm_mobs_witch_self_potion_step(
        GmMobLive *m, int eid, int in_water, int burning,
        int has_target, double target_distance_sq) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !isfinite(target_distance_sq)
            || target_distance_sq < 0.0)
        return 0;
    return witch_self_potion_step_slot(
        m, s, slot, in_water, burning,
        has_target, target_distance_sq);
}

int gm_mobs_witch_self_potion_state(
        const GmMobLive *m, int eid, int *drinking, int *timer,
        int *potion, float *drink_pitch) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || s->type[slot] != EW_TYPE_WITCH) return 0;
    if (drinking) *drinking = m->witch_drinking[slot];
    if (timer) *timer = m->witch_attack_timer[slot];
    if (potion) *potion = m->witch_potion[slot];
    if (drink_pitch) *drink_pitch = m->witch_drink_pitch[slot];
    return 1;
}

