static int living_box_at(
        const GmMobLive *m, const EwStore *s, int dimension,
        int slot, McAABB *out) {
    if (!s->alive[slot] || m->entity_dimension[slot] != dimension
            || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0;
    float width, height;
    ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
    if (gm_child_sized(s->type[slot]) && m->growing_age[slot] < 0) {
        width *= 0.5F;
        height *= 0.5F;
    }
    double half = (double)width * 0.5;
    *out = mc_aabb_make(
        s->x[slot] - half, s->y[slot], s->z[slot] - half,
        s->x[slot] + half, s->y[slot] + (double)height,
        s->z[slot] + half);
    return 1;
}

static double mob_math_random_next_double(uint64_t *seed48) {
    const uint64_t mask = (UINT64_C(1) << 48) - UINT64_C(1);
    uint64_t high, low;
    if (!seed48) return 0.0;
    *seed48 = (*seed48 * UINT64_C(0x5DEECE66D) + UINT64_C(0xB)) & mask;
    high = *seed48 >> (48 - 26);
    *seed48 = (*seed48 * UINT64_C(0x5DEECE66D) + UINT64_C(0xB)) & mask;
    low = *seed48 >> (48 - 27);
    return (double)((high << 27) + low)
        / (double)(UINT64_C(1) << 53);
}

static void mob_event_append(
        GmMobLive *m, int kind, int eid, int data,
        double x, double y, double z, float volume, float pitch) {
    if (!m) return;
    if (!mob_ring_linearize(
            (void **)&m->events, m->events_cap,
            m->event_count, &m->event_head, sizeof *m->events)
            || !MOB_COLD_RESERVE(
            m, events, m->event_count + 1, GM_MOB_EVENT_CAPACITY)) {
        ++m->event_dropped;
        ++m->event_next_seq;
        return;
    }
    int index = m->event_count++;
    m->events[index] = (GmMobEvent){
        m->event_next_seq++, kind, eid, data,
        x, y, z, volume, pitch
    };
}

static void villager_player_harm_append(
        GmMobLive *m, const EwStore *s, int slot, int killed) {
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || s->type[slot] != EW_TYPE_VILLAGER)
        return;
    if (m->villager_harm_count < EW_MAX_ENTITIES) {
        GmVillagerHarmEvent *event =
            &m->villager_harm_events[m->villager_harm_count++];
        event->victim_eid = s->id[slot];
        event->village_index = m->villager_village_index[slot];
        event->victim_child = m->growing_age[slot] < 0;
        event->victim_killed = killed != 0;
        event->x = s->x[slot];
        event->y = s->y[slot];
        event->z = s->z[slot];
    }
    /* EntityVillager.setRevengeTarget sends status 13 only while the victim
     * remains alive. Its reputation side effect is drained by GmRuntime. */
    if (!killed)
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 13,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
}

static int tameable_type(int type) {
    return type == EW_TYPE_WOLF || type == EW_TYPE_OCELOT;
}

static int wolf_food_heal(int item) {
    switch (item) {
    case 319: return 3; /* porkchop */
    case 320: return 8; /* cooked porkchop */
    case 363: return 3; /* beef */
    case 364: return 8; /* cooked beef */
    case 365: return 2; /* chicken */
    case 366: return 6; /* cooked chicken */
    case 367: return 4; /* rotten flesh */
    case 411: return 3; /* rabbit */
    case 412: return 5; /* cooked rabbit */
    case 423: return 2; /* mutton */
    case 424: return 6; /* cooked mutton */
    default: return 0;
    }
}

static void tameable_effect(GmMobLive *m, EwStore *s, int slot, int success) {
    GmMobParticleBatch batch = {
        .eid = s->id[slot],
        .dimension = m->entity_dimension[slot],
        .particle_id = success ? 34 : 11,
        .count = 7
    };
    float width, height;
    ehs_size(s->type[slot], &width, &height);
    for (int i = 0; i < 7; ++i) {
        GmTerminalParticle *p = &batch.particles[i];
        p->vx = jrand_gaussian_next(&m->entity_random[slot]) * 0.02;
        p->vy = jrand_gaussian_next(&m->entity_random[slot]) * 0.02;
        p->vz = jrand_gaussian_next(&m->entity_random[slot]) * 0.02;
        p->x = s->x[slot] + (double)(
            jrand_float(&m->entity_random[slot].random) * width * 2.0F - width);
        p->y = s->y[slot] + 0.5 + (double)(
            jrand_float(&m->entity_random[slot].random) * height);
        p->z = s->z[slot] + (double)(
            jrand_float(&m->entity_random[slot].random) * width * 2.0F - width);
    }
    mob_particle_batch_append(m, &batch);
}

int gm_mobs_tameable_interact(
        GmMobLive *m, int eid, IsrInv *inventory, int hand_slot,
        int creative, int owner, JavaRandom *world_random) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !inventory || !s || !tameable_type(s->type[slot])
            || (creative != 0 && creative != 1)
            || (owner != 0 && owner != 1))
        return 0;
    ICStack held = isr_get_stack(inventory, hand_slot);
    if (s->type[slot] == EW_TYPE_WOLF) {
        int heal = wolf_food_heal(held.item);
        if (m->tameable_tamed[slot]) {
            if (heal > 0 && held.count > 0) {
                if (!creative)
                    (void)isr_decr_stack_size(inventory, hand_slot, 1);
                s->health[slot] = fminf(20.0F, s->health[slot] + (float)heal);
                next_store(m)->health[slot] = s->health[slot];
                return 1;
            }
            if (held.item == 351 && held.count > 0
                    && held.meta >= 0 && held.meta <= 15
                    && held.meta != m->tameable_variant[slot]) {
                m->tameable_variant[slot] = (unsigned char)held.meta;
                if (!creative)
                    (void)isr_decr_stack_size(inventory, hand_slot, 1);
                return 1;
            }
            if (owner && held.count > 0 && heal == 0) {
                m->tameable_sit_requested[slot] =
                    (unsigned char)!m->tameable_sitting[slot];
                s->path_len[slot] = 0;
                return 0;
            }
            return 0;
        }
        if (held.item != 352 || held.count <= 0) return 0;
        if (!creative)
            (void)isr_decr_stack_size(inventory, hand_slot, 1);
        int success = jrand_int_bound(
            &m->entity_random[slot].random, 3) == 0;
        if (success) {
            m->tameable_tamed[slot] = 1;
            m->tameable_owner[slot] = 1;
            m->tameable_sit_requested[slot] = 1;
            s->health[slot] = 20.0F;
            next_store(m)->health[slot] = 20.0F;
        }
        tameable_effect(m, s, slot, success);
        mob_event_append(m, GM_MOB_EVENT_ENTITY_STATUS, eid,
            success ? 7 : 6, s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
        return 1;
    }

    if (m->tameable_tamed[slot]) {
        if (owner && held.item != 349) {
            m->tameable_sit_requested[slot] =
                (unsigned char)!m->tameable_sitting[slot];
            s->path_len[slot] = 0;
            return 0;
        }
        return 0;
    }
    if (held.item != 349 || held.count <= 0 || !world_random) return 0;
    if (!creative)
        (void)isr_decr_stack_size(inventory, hand_slot, 1);
    int success = jrand_int_bound(
        &m->entity_random[slot].random, 3) == 0;
    if (success) {
        m->tameable_tamed[slot] = 1;
        m->tameable_owner[slot] = 1;
        m->tameable_sit_requested[slot] = 1;
        m->tameable_variant[slot] =
            (unsigned char)(1 + jrand_int_bound(world_random, 3));
    }
    tameable_effect(m, s, slot, success);
    mob_event_append(m, GM_MOB_EVENT_ENTITY_STATUS, eid,
        success ? 7 : 6, s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    return 1;
}

int gm_mobs_set_tameable_state(
        GmMobLive *m, int eid, int tamed, int sitting, int owner,
        int variant, float health) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || !tameable_type(s->type[slot])
            || (tamed != 0 && tamed != 1)
            || (sitting != 0 && sitting != 1)
            || (owner != 0 && owner != 1) || !isfinite(health)
            || health < 0.0F
            || (s->type[slot] == EW_TYPE_WOLF
                ? variant < 0 || variant > 15 || health > (tamed ? 20.0F : 8.0F)
                : variant < 0 || variant > 3 || health > 10.0F))
        return 0;
    m->tameable_tamed[slot] = (unsigned char)tamed;
    m->tameable_sitting[slot] = (unsigned char)sitting;
    m->tameable_sit_requested[slot] = (unsigned char)sitting;
    m->tameable_owner[slot] = (unsigned char)owner;
    m->tameable_variant[slot] = (unsigned char)variant;
    s->health[slot] = health;
    next_store(m)->health[slot] = health;
    return 1;
}

int gm_mobs_get_tameable_state(
        const GmMobLive *m, int eid, int *tamed, int *sitting, int *owner,
        int *variant, float *health) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || !tameable_type(s->type[slot])) return 0;
    if (tamed) *tamed = m->tameable_tamed[slot];
    if (sitting) *sitting = m->tameable_sitting[slot];
    if (owner) *owner = m->tameable_owner[slot];
    if (variant) *variant = m->tameable_variant[slot];
    if (health) *health = s->health[slot];
    return 1;
}

