int gm_mobs_restore_tameable_state(
        GmMobLive *m, int eid, int tamed, int sitting, int owner,
        int variant, int growing_age, int living_sound_time,
        uint64_t seed48, int have_next_gaussian, double next_gaussian) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (slot <= 0 || !s || !tameable_type(s->type[slot])
            || living_sound_time < -80 || living_sound_time > 1000
            || !gm_mobs_set_tameable_state(
                m, eid, tamed, sitting, owner, variant, s->health[slot])
            || !gm_mobs_set_growing_age(m, eid, growing_age)
            || !gm_mobs_set_entity_random_state(
                m, eid, seed48, have_next_gaussian, next_gaussian))
        return 0;
    m->entity_living_sound_time[slot] = living_sound_time;
    return 1;
}

int gm_mobs_sitting_ocelot_over(
        const GmMobLive *m, int dimension, int x, int y, int z) {
    GmMobLive *mutable_m = (GmMobLive *)m;
    const EwStore *s;
    if (!m) return 0;
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(mutable_m, &cursor)) > 0) {
        s = const_store(m);
        if (!s->alive[slot] || s->type[slot] != EW_TYPE_OCELOT
                || m->entity_dimension[slot] != dimension
                || !m->tameable_sitting[slot])
            continue;
        float width, height;
        ehs_size(EW_TYPE_OCELOT, &width, &height);
        double half = (double)width * 0.5;
        if (s->x[slot] + half > (double)x
                && s->x[slot] - half < (double)(x + 1)
                && s->y[slot] + (double)height > (double)(y + 1)
                && s->y[slot] < (double)(y + 2)
                && s->z[slot] + half > (double)z
                && s->z[slot] - half < (double)(z + 1))
            {
                gm_mobs_living_cold_flush(mutable_m);
                return 1;
            }
    }
    gm_mobs_living_cold_flush(mutable_m);
    return 0;
}

static int animal_breeding_item(int type, int item) {
    switch (type) {
    case EW_TYPE_SHEEP:
    case EW_TYPE_COW:
    case EW_TYPE_MOOSHROOM:
        return item == 296;
    case EW_TYPE_PIG:
        return item == 391 || item == 392 || item == 434;
    case EW_TYPE_CHICKEN:
        return item == 295 || item == 361 || item == 362 || item == 435;
    case EW_TYPE_OCELOT:
        return item == 349;
    case EW_TYPE_RABBIT:
        return item == 391 || item == 396 || item == 37;
    default:
        return 0;
    }
}

int gm_mobs_animal_can_feed(const GmMobLive *m, int eid, int item) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot < 0 || !animal_breeding_item(s->type[slot], item))
        return 0;
    return m->growing_age[slot] < 0
        || (m->growing_age[slot] == 0 && m->sheep_in_love[slot] <= 0);
}

int gm_mobs_sheep_can_feed(const GmMobLive *m, int eid) {
    return gm_mobs_animal_can_feed(m, eid, 296);
}

static int jls_int_from_bits(uint32_t bits) {
    int32_t value;
    memcpy(&value, &bits, sizeof value);
    return (int)value;
}

static int jls_int_add(int left, int right) {
    return jls_int_from_bits(
        (uint32_t)(int32_t)left + (uint32_t)(int32_t)right);
}

static int jls_int_sub(int left, int right) {
    return jls_int_from_bits(
        (uint32_t)(int32_t)left - (uint32_t)(int32_t)right);
}

static int jls_int_mul(int left, int right) {
    return jls_int_from_bits(
        (uint32_t)(int32_t)left * (uint32_t)(int32_t)right);
}

static int jls_int_neg(int value) {
    return jls_int_from_bits(UINT32_C(0) - (uint32_t)(int32_t)value);
}

int gm_mobs_feed_animal(
        GmMobLive *m, int eid, IsrInv *inventory,
        int hand_slot, int creative) {
    int slot, age, old_age, growth_seconds, new_age, delta;
    ICStack held;
    EwStore *s;
    if (!m || !inventory || (creative != 0 && creative != 1))
        return 0;
    slot = mob_slot_by_eid(m, eid);
    if (slot < 0) return 0;
    s = now_store(m);
    held = isr_get_stack(inventory, hand_slot);
    if (!animal_breeding_item(s->type[slot], held.item) || held.count <= 0)
        return 0;

    age = m->growing_age[slot];
    if (age == 0 && m->sheep_in_love[slot] <= 0) {
        if (!creative)
            (void)isr_decr_stack_size(inventory, hand_slot, 1);
        m->sheep_in_love[slot] = 600;
        m->sheep_bred_by_player[slot] = 1;
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, eid, 18,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
        return 1;
    }
    if (age >= 0)
        return 0;

    if (!creative)
        (void)isr_decr_stack_size(inventory, hand_slot, 1);
    /* Java evaluates integer division before widening to float. ageUp then
     * stores the actual tick delta in forcedAge, not the seconds argument. */
    growth_seconds = (int)((float)(jls_int_neg(age) / 20) * 0.1F);
    old_age = age;
    new_age = jls_int_add(old_age, jls_int_mul(growth_seconds, 20));
    if (new_age > 0) new_age = 0;
    delta = jls_int_sub(new_age, old_age);
    m->growing_age[slot] = new_age;
    m->sheep_forced_age[slot] = jls_int_add(
        m->sheep_forced_age[slot], delta);
    if (m->sheep_forced_age_timer[slot] == 0)
        m->sheep_forced_age_timer[slot] = 40;
    if (m->growing_age[slot] == 0)
        m->growing_age[slot] = m->sheep_forced_age[slot];
    return 1;
}

int gm_mobs_saddle_pig(
        GmMobLive *m, int eid, IsrInv *inventory,
        int hand_slot, int creative) {
    int slot;
    ICStack held;
    EwStore *s;
    if (!m || !inventory || (creative != 0 && creative != 1)) return 0;
    slot = mob_slot_by_eid(m, eid);
    if (slot < 0) return 0;
    s = now_store(m);
    held = isr_get_stack(inventory, hand_slot);
    if (s->type[slot] != EW_TYPE_PIG || held.item != 329
            || held.count <= 0)
        return 0;
    /* ItemSaddle returns true for every pig. Mutation is limited to an adult
     * unsaddled pig; creative restoration is performed by interactOn. */
    if (!m->pig_saddled[slot] && m->growing_age[slot] >= 0) {
        m->pig_saddled[slot] = 1;
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, 0, GM_MOB_SOUND_PIG_SADDLE,
            s->x[slot], s->y[slot], s->z[slot], 0.5F, 1.0F);
        if (!creative)
            (void)isr_decr_stack_size(inventory, hand_slot, 1);
    }
    return 1;
}

int gm_mobs_milk_cow(
        GmMobLive *m, int eid, IsrInv *inventory,
        int hand_slot, int creative,
        double player_x, double player_y, double player_z,
        float player_yaw, float player_pitch, double player_eye_height,
        const McSinTable *sin_table, uint64_t *math_random_seed48,
        GmLiveSim *drops, int *next_entity_id) {
    EwStore *s;
    ICStack held;
    int slot, empty_slot = -1, needs_drop;
    if (!m || !inventory || (creative != 0 && creative != 1)) return 0;
    slot = mob_slot_by_eid(m, eid);
    if (slot < 0) return 0;
    s = now_store(m);
    held = isr_get_stack(inventory, hand_slot);
    if ((s->type[slot] != EW_TYPE_COW
            && s->type[slot] != EW_TYPE_MOOSHROOM) || held.item != 325
            || held.count <= 0 || creative || m->growing_age[slot] < 0)
        return 0;

    if (held.count > 1)
        empty_slot = isr_get_first_empty_stack(inventory);
    needs_drop = held.count > 1 && empty_slot < 0;
    if (needs_drop && (!sin_table || !math_random_seed48 || !drops
            || !next_entity_id || *next_entity_id <= 0
            || *next_entity_id >= INT_MAX
            || !mob_live_reserve_item_slots(drops, 1)))
        return -1;

    /* EntityCow calls EntityPlayer.playSound before shrinking the bucket. */
    mob_event_append(
        m, GM_MOB_EVENT_SOUND, 0, GM_MOB_SOUND_COW_MILK,
        player_x, player_y, player_z, 1.0F, 1.0F);
    --held.count;
    if (held.count <= 0) {
        isr_set_stack(inventory, hand_slot, ic_mk(335, 1, 0));
        /* Forge's held-slot replacement resolves one equip sound after the
         * bucket is destroyed, at the same player source and position. */
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, 0,
            GM_MOB_SOUND_ITEM_ARMOR_EQUIP_GENERIC,
            player_x, player_y, player_z, 1.0F, 1.0F);
        return 1;
    }
    isr_set_stack(inventory, hand_slot, held);
    if (empty_slot >= 0) {
        /* Milk buckets are unstackable and InventoryPlayer creates them only
         * in the first empty main-inventory slot, never an empty offhand. */
        isr_set_stack(inventory, empty_slot, ic_mk(335, 1, 0));
        return 1;
    }

    {
        int item_eid = (*next_entity_id)++;
        float hover_start = (float)(
            mob_math_random_next_double(math_random_seed48)
                * (MC_PI * 2.0));
        float item_yaw = (float)(
            mob_math_random_next_double(math_random_seed48) * 360.0);
        /* The constructor consumes these two Math.random values even though
         * EntityPlayer.dropItem(false) immediately overwrites its motion. */
        (void)mob_math_random_next_double(math_random_seed48);
        (void)mob_math_random_next_double(math_random_seed48);
        float yaw = player_yaw * 0.017453292F;
        float pitch = player_pitch * 0.017453292F;
        float speed = 0.3F;
        double motion_x = (double)(
            -mc_sin(sin_table, yaw) * mc_cos(sin_table, pitch) * speed);
        double motion_z = (double)(
            mc_cos(sin_table, yaw) * mc_cos(sin_table, pitch) * speed);
        double motion_y = (double)(-mc_sin(sin_table, pitch) * speed + 0.1F);
        float spread_angle = jrand_float(&m->player_random)
            * ((float)MC_PI * 2.0F);
        float spread = 0.02F * jrand_float(&m->player_random);
        motion_x += cos((double)spread_angle) * (double)spread;
        motion_y += (double)((jrand_float(&m->player_random)
            - jrand_float(&m->player_random)) * 0.1F);
        motion_z += sin((double)spread_angle) * (double)spread;
        if (!gm_live_spawn_item_exact_hover(
                drops, item_eid, player_x,
                player_y - 0.30000001192092896 + player_eye_height,
                player_z, motion_x, motion_y, motion_z,
                item_yaw, hover_start, 335, 1, 0, 0, 40, 0))
            return -1;
        if (m->next_id <= item_eid) m->next_id = item_eid + 1;
        if (m->next_orb_id <= item_eid) m->next_orb_id = item_eid + 1;
    }
    return 1;
}

int gm_mobs_feed_sheep(
        GmMobLive *m, int eid, IsrInv *inventory,
        int hand_slot, int creative) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot < 0 || s->type[slot] != EW_TYPE_SHEEP)
        return 0;
    return gm_mobs_feed_animal(m, eid, inventory, hand_slot, creative);
}

static int sheep_graze_begin_slot(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot) {
    int x, y, z, bound, roll;
    if (!m || !w || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot] || s->type[slot] != EW_TYPE_SHEEP)
        return 0;
    bound = m->growing_age[slot] < 0 ? 50 : 1000;
    roll = jrand_int_bound(&m->entity_random[slot].random, bound);
    if (roll != 0) return 0;
    x = mc_floor(s->x[slot]);
    y = mc_floor(s->y[slot]);
    z = mc_floor(s->z[slot]);
    if (!((gm_world_block(w, x, y, z) == 31
                && gm_world_meta(w, x, y, z) == 1)
            || gm_world_block(w, x, y - 1, z) == 2))
        return 0;
    m->sheep_eat_timer[slot] = 40;
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 10,
        s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    return 1;
}

static int sheep_graze_update_slot(
        GmMobLive *m, GmWorld *w, EwStore *s, int slot,
        int mob_griefing) {
    int x, y, z, event_y, event_data;
    if (!m || !w || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot] || s->type[slot] != EW_TYPE_SHEEP
            || m->sheep_eat_timer[slot] <= 0)
        return 0;
    if (--m->sheep_eat_timer[slot] != 4) return 0;
    x = mc_floor(s->x[slot]);
    y = mc_floor(s->y[slot]);
    z = mc_floor(s->z[slot]);
    event_y = y;
    event_data = 0;
    if (gm_world_block(w, x, y, z) == 31
            && gm_world_meta(w, x, y, z) == 1) {
        if (mob_griefing) {
            /* Block.getStateId(tallgrass[grass]) = id + (meta << 12). */
            event_data = 31 + (1 << 12);
            gm_world_set_block_meta(w, x, y, z, 0, 0);
        }
    } else if (gm_world_block(w, x, y - 1, z) == 2) {
        event_y = y - 1;
        if (mob_griefing) {
            event_data = 2;
            gm_world_set_block_meta(w, x, y - 1, z, 3, 0);
        }
    } else {
        return 0;
    }
    m->sheep_data[slot] &= (unsigned char)~16u;
    if (m->growing_age[slot] < 0) {
        if (m->growing_age[slot] > -1200)
            m->growing_age[slot] = 0;
        else
            m->growing_age[slot] += 1200;
    }
    if (mob_griefing) {
        m->sheep_world_event_pending[slot] = 1;
        m->sheep_world_event_x[slot] = x;
        m->sheep_world_event_y[slot] = event_y;
        m->sheep_world_event_z[slot] = z;
        m->sheep_world_event_data[slot] = event_data;
    }
    return 1;
}

int gm_mobs_sheep_graze_begin(GmMobLive *m, GmWorld *w, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    if (slot < 0) return 0;
    return sheep_graze_begin_slot(m, w, now_store(m), slot);
}

int gm_mobs_sheep_graze_update(
        GmMobLive *m, GmWorld *w, int eid, int mob_griefing) {
    int slot = mob_slot_by_eid(m, eid);
    if (slot < 0) return 0;
    return sheep_graze_update_slot(
        m, w, now_store(m), slot, mob_griefing != 0);
}

int gm_mobs_sheep_eat_timer(const GmMobLive *m, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    return slot < 0 ? -1 : m->sheep_eat_timer[slot];
}

int gm_mobs_take_sheep_world_event(
        GmMobLive *m, int *x, int *y, int *z, int *data) {
    if (!m) return 0;
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(m, &cursor)) > 0) {
        if (!m->sheep_world_event_pending[slot]) continue;
        m->sheep_world_event_pending[slot] = 0;
        if (x) *x = m->sheep_world_event_x[slot];
        if (y) *y = m->sheep_world_event_y[slot];
        if (z) *z = m->sheep_world_event_z[slot];
        if (data) *data = m->sheep_world_event_data[slot];
        gm_mobs_living_cold_flush(m);
        return 1;
    }
    gm_mobs_living_cold_flush(m);
    return 0;
}

int gm_mobs_event_count(const GmMobLive *m) {
    return m ? m->event_count : 0;
}

int gm_mobs_event_get(
        const GmMobLive *m, int index, GmMobEvent *out) {
    if (!m || !out || index < 0 || index >= m->event_count
            || m->events_cap <= 0)
        return 0;
    *out = m->events[(m->event_head + index) % m->events_cap];
    return 1;
}

static double mob_ray_box_hit(
        double ex, double ey, double ez, double dx, double dy, double dz,
        const McAABB *box) {
    const double origin[3] = {ex, ey, ez};
    const double direction[3] = {dx, dy, dz};
    const double low[3] = {box->minX, box->minY, box->minZ};
    const double high[3] = {box->maxX, box->maxY, box->maxZ};
    double enter = 0.0, exit = 1.0e30;
    int inside = 1;
    for (int axis = 0; axis < 3; ++axis) {
        if (!(origin[axis] > low[axis] && origin[axis] < high[axis]))
            inside = 0;
        if (fabs(direction[axis]) < 1.0e-12) {
            if (origin[axis] < low[axis] || origin[axis] > high[axis])
                return -1.0;
            continue;
        }
        double near = (low[axis] - origin[axis]) / direction[axis];
        double far = (high[axis] - origin[axis]) / direction[axis];
        if (near > far) {
            double swap = near;
            near = far;
            far = swap;
        }
        if (near > enter) enter = near;
        if (far < exit) exit = far;
        if (enter > exit) return -1.0;
    }
    if (inside) return 0.0;
    return enter >= 0.0 ? enter : -1.0;
}

int gm_mobs_raycast_entity(
        const GmMobLive *m, int dimension,
        double ex, double ey, double ez, double dx, double dy, double dz,
        double max_distance, int *eid, int *type, double *distance) {
    const EwStore *s;
    double norm, best;
    int best_eid = -1, best_type = EW_TYPE_NONE;
    GmMobLive *mutable_m = (GmMobLive *)m;
    if (!m || max_distance < 0.0) return 0;
    norm = sqrt(dx * dx + dy * dy + dz * dz);
    if (norm <= 0.0) return 0;
    best = max_distance;
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(mutable_m, &cursor)) > 0) {
        float width, height;
        double half, hit, hit_distance;
        McAABB box;
        s = const_store(m);
        if (!s->alive[slot] || !gm_living(s->type[slot])
                || m->entity_dimension[slot] != dimension)
            continue;
        ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
        if (m->growing_age[slot] < 0 && gm_child_sized(s->type[slot])) {
            width *= 0.5F;
            height *= 0.5F;
        }
        half = (double)width * 0.5;
        box = mc_aabb_make(
            s->x[slot] - half - 0.1, s->y[slot] - 0.1,
            s->z[slot] - half - 0.1,
            s->x[slot] + half + 0.1,
            s->y[slot] + (double)height + 0.1,
            s->z[slot] + half + 0.1);
        hit = mob_ray_box_hit(ex, ey, ez, dx, dy, dz, &box);
        if (hit < 0.0) continue;
        hit_distance = hit * norm;
        if (hit_distance <= max_distance
                && (best_eid < 0 || hit_distance < best || best == 0.0)) {
            best = hit_distance;
            best_eid = s->id[slot];
            best_type = s->type[slot];
        }
    }
    gm_mobs_living_cold_flush(mutable_m);
    if (best_eid < 0) return 0;
    if (eid) *eid = best_eid;
    if (type) *type = best_type;
    if (distance) *distance = best;
    return 1;
}

static int mob_live_reserve_item_slots(GmLiveSim *drops, int count) {
    return drops && count >= 0 && gm_live_reserve_plain_spawns(drops, count);
}

int gm_mobs_shear_sheep(
        GmMobLive *m, int eid, IsrInv *inventory, int hand_slot,
        uint64_t *shear_random_seed48, uint64_t *math_random_seed48,
        GmLiveSim *drops, int *next_entity_id) {
    EwStore *s;
    ICStack held;
    JavaRandom preview, shear_random;
    int slot, count;
    if (!m || !inventory) return 0;
    slot = mob_slot_by_eid(m, eid);
    if (slot < 0) return 0;
    s = now_store(m);
    held = isr_get_stack(inventory, hand_slot);
    if (s->type[slot] != EW_TYPE_SHEEP
            || held.item != 359 || held.count <= 0)
        return 0;
    /* IShearable is handled even when its eligibility check is false. */
    if ((m->sheep_data[slot] & 16) || m->growing_age[slot] < 0)
        return 1;
    if (!shear_random_seed48 || !math_random_seed48 || !drops
            || !next_entity_id || *next_entity_id <= 0)
        return -1;

    preview = m->entity_random[slot].random;
    count = 1 + jrand_int_bound(&preview, 3);
    if (*next_entity_id > INT_MAX - count
            || !mob_live_reserve_item_slots(drops, count))
        return -1;

    count = 1 + jrand_int_bound(
        &m->entity_random[slot].random, 3);
    m->sheep_data[slot] |= 16;
    mob_event_append(
        m, GM_MOB_EVENT_SOUND, eid, GM_MOB_SOUND_SHEEP_SHEAR,
        s->x[slot], s->y[slot], s->z[slot], 1.0F, 1.0F);
    jrand_set_seed48(&shear_random, *shear_random_seed48);
    for (int wool = 0; wool < count; ++wool) {
        float hover_start = (float)(
            mob_math_random_next_double(math_random_seed48)
                * (MC_PI * 2.0));
        float yaw = (float)(
            mob_math_random_next_double(math_random_seed48) * 360.0);
        double motion_x = (double)(float)(
            mob_math_random_next_double(math_random_seed48)
                * 0.20000000298023224 - 0.10000000149011612);
        double motion_y = 0.20000000298023224;
        double motion_z = (double)(float)(
            mob_math_random_next_double(math_random_seed48)
                * 0.20000000298023224 - 0.10000000149011612);
        motion_y += (double)(jrand_float(&shear_random) * 0.05F);
        motion_x += (double)(
            (jrand_float(&shear_random) - jrand_float(&shear_random))
                * 0.1F);
        motion_z += (double)(
            (jrand_float(&shear_random) - jrand_float(&shear_random))
                * 0.1F);
        if (!gm_live_spawn_item_exact_hover(
                drops, (*next_entity_id)++,
                s->x[slot], s->y[slot] + 1.0, s->z[slot],
                motion_x, motion_y, motion_z, yaw, hover_start,
                35, 1, m->sheep_data[slot] & 15, 0, 10, 0))
            return -1;
    }
    *shear_random_seed48 = shear_random.seed;
    {
        ITAStack tool = mob_ita_stack(held);
        if (ita_attempt_damage(
                &tool, 1, &m->entity_random[slot].random)) {
            (void)isr_decr_stack_size(inventory, hand_slot, 1);
        } else {
            held.meta = tool.damage;
            isr_set_stack(inventory, hand_slot, held);
        }
    }
    ew_store_copy(next_store(m), s);
    return 2;
}

static int mooshroom_spawn_player_drop(
        GmMobLive *m, int item, double player_x, double player_y,
        double player_z, float player_yaw, float player_pitch,
        double player_eye_height, const McSinTable *sin_table,
        uint64_t *math_random_seed48, GmLiveSim *drops,
        int *next_entity_id) {
    int item_eid = (*next_entity_id)++;
    float hover_start = (float)(
        mob_math_random_next_double(math_random_seed48) * (MC_PI * 2.0));
    float item_yaw = (float)(
        mob_math_random_next_double(math_random_seed48) * 360.0);
    /* EntityItem's constructor motion is overwritten by
     * EntityPlayer.dropItem(false), but both Math.random calls remain causal. */
    (void)mob_math_random_next_double(math_random_seed48);
    (void)mob_math_random_next_double(math_random_seed48);
    float yaw = player_yaw * 0.017453292F;
    float pitch = player_pitch * 0.017453292F;
    float speed = 0.3F;
    double motion_x = (double)(
        -mc_sin(sin_table, yaw) * mc_cos(sin_table, pitch) * speed);
    double motion_z = (double)(
        mc_cos(sin_table, yaw) * mc_cos(sin_table, pitch) * speed);
    double motion_y = (double)(-mc_sin(sin_table, pitch) * speed + 0.1F);
    float spread_angle = jrand_float(&m->player_random)
        * ((float)MC_PI * 2.0F);
    float spread = 0.02F * jrand_float(&m->player_random);
    motion_x += cos((double)spread_angle) * (double)spread;
    motion_y += (double)((jrand_float(&m->player_random)
        - jrand_float(&m->player_random)) * 0.1F);
    motion_z += sin((double)spread_angle) * (double)spread;
    if (!gm_live_spawn_item_exact_hover(
            drops, item_eid, player_x,
            player_y - 0.30000001192092896 + player_eye_height,
            player_z, motion_x, motion_y, motion_z, item_yaw, hover_start,
            item, 1, 0, 0, 40, 0))
        return 0;
    if (m->next_id <= item_eid) m->next_id = item_eid + 1;
    if (m->next_orb_id <= item_eid) m->next_orb_id = item_eid + 1;
    return 1;
}

int gm_mobs_bowl_mooshroom(
        GmMobLive *m, int eid, IsrInv *inventory, int hand_slot,
        int creative, double player_x, double player_y, double player_z,
        float player_yaw, float player_pitch, double player_eye_height,
        const McSinTable *sin_table, uint64_t *math_random_seed48,
        GmLiveSim *drops, int *next_entity_id) {
    int slot, empty_slot = -1;
    ICStack held;
    EwStore *s;
    if (!m || !inventory || (creative != 0 && creative != 1)) return 0;
    slot = mob_slot_by_eid(m, eid);
    if (slot < 0) return 0;
    s = now_store(m);
    held = isr_get_stack(inventory, hand_slot);
    if (s->type[slot] != EW_TYPE_MOOSHROOM || held.item != 281
            || held.count <= 0 || creative || m->growing_age[slot] < 0)
        return 0;
    if (held.count > 1)
        empty_slot = isr_get_first_empty_stack(inventory);
    if (held.count > 1 && empty_slot < 0
            && (!sin_table || !math_random_seed48 || !drops
                || !next_entity_id || *next_entity_id <= 0
                || *next_entity_id >= INT_MAX
                || !mob_live_reserve_item_slots(drops, 1)))
        return -1;

    --held.count;
    if (held.count <= 0) {
        isr_set_stack(inventory, hand_slot, ic_mk(282, 1, 0));
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, 0,
            GM_MOB_SOUND_ITEM_ARMOR_EQUIP_GENERIC,
            player_x, player_y, player_z, 1.0F, 1.0F);
        return 1;
    }
    isr_set_stack(inventory, hand_slot, held);
    if (empty_slot >= 0) {
        isr_set_stack(inventory, empty_slot, ic_mk(282, 1, 0));
        return 1;
    }
    if (!mooshroom_spawn_player_drop(
            m, 282, player_x, player_y, player_z,
            player_yaw, player_pitch, player_eye_height, sin_table,
            math_random_seed48, drops, next_entity_id))
        return -1;
    return 1;
}

int gm_mobs_shear_mooshroom(
        GmMobLive *m, int eid, IsrInv *inventory, int hand_slot,
        uint64_t *shear_random_seed48, uint64_t *math_random_seed48,
        GmLiveSim *drops, int *next_entity_id) {
    EwStore *s;
    ICStack held;
    int slot, dimension, new_slot, cow_eid;
    double x, y, z;
    float yaw, pitch, health, head_yaw, render_yaw;
    JavaGaussianRandom tool_random;
    JavaRandom shear_random;
    if (!m || !inventory) return 0;
    slot = mob_slot_by_eid(m, eid);
    if (slot < 0) return 0;
    s = now_store(m);
    held = isr_get_stack(inventory, hand_slot);
    if (s->type[slot] != EW_TYPE_MOOSHROOM
            || held.item != 359 || held.count <= 0)
        return 0;
    /* Forge ItemShears handles every IShearable target, including children. */
    if (m->growing_age[slot] < 0) return 1;
    if (!shear_random_seed48 || !math_random_seed48 || !drops
            || !next_entity_id || *next_entity_id <= 0
            || *next_entity_id > INT_MAX - 6
            || !mob_live_reserve_item_slots(drops, 5))
        return -1;

    x = s->x[slot]; y = s->y[slot]; z = s->z[slot];
    yaw = s->yaw[slot]; pitch = m->entity_pitch[slot];
    health = s->health[slot];
    head_yaw = m->passive_head_yaw[slot];
    render_yaw = m->squid_render_yaw_offset[slot];
    dimension = m->entity_dimension[slot];
    tool_random = m->entity_random[slot];

    {
        GmMobParticleBatch batch;
        memset(&batch, 0, sizeof batch);
        batch.eid = eid;
        batch.dimension = dimension;
        batch.particle_id = 1; /* EXPLOSION_LARGE */
        batch.descriptor_count = 1;
        batch.x = x; batch.y = y + 0.7; batch.z = z;
        mob_particle_batch_append(m, &batch);
    }

    /* onSheared calls setDead before constructing and appending the cow. */
    retire_terminal_living(m, s, slot);
    cow_eid = (*next_entity_id)++;
    int cow_is_cold = 0;
    new_slot = living_spawn_slot(
        m, s, EW_TYPE_COW, cow_eid, x, y, z, health, &cow_is_cold);
    if (new_slot < 0) return -1;
    s->yaw[new_slot] = yaw;
    m->entity_dimension[new_slot] = (signed char)dimension;
    m->size[new_slot] = 1;
    reset_slot_state_s(m, s, new_slot);
    s->health[new_slot] = health;
    m->entity_pitch[new_slot] = pitch;
    m->passive_head_yaw[new_slot] = head_yaw;
    m->squid_render_yaw_offset[new_slot] = render_yaw;
    new_slot = living_spawn_finish(
        m, s, new_slot, cow_is_cold, 0);
    if (new_slot < 0) return -1;
    if (m->next_id <= cow_eid) m->next_id = cow_eid + 1;

    /* EntityLivingBase's fresh-cow constructor consumes three Math.random
     * doubles before onSheared overwrites its pose and render yaw. */
    (void)mob_math_random_next_double(math_random_seed48);
    (void)mob_math_random_next_double(math_random_seed48);
    (void)mob_math_random_next_double(math_random_seed48);

    mob_event_append(
        m, GM_MOB_EVENT_SOUND, eid, GM_MOB_SOUND_MOOSHROOM_SHEAR,
        x, y, z, 1.0F, 1.0F);
    jrand_set_seed48(&shear_random, *shear_random_seed48);
    for (int mushroom = 0; mushroom < 5; ++mushroom) {
        int item_eid = (*next_entity_id)++;
        float hover_start = (float)(
            mob_math_random_next_double(math_random_seed48)
                * (MC_PI * 2.0));
        float item_yaw = (float)(
            mob_math_random_next_double(math_random_seed48) * 360.0);
        double motion_x = (double)(float)(
            mob_math_random_next_double(math_random_seed48)
                * 0.20000000298023224 - 0.10000000149011612);
        double motion_y = 0.20000000298023224;
        double motion_z = (double)(float)(
            mob_math_random_next_double(math_random_seed48)
                * 0.20000000298023224 - 0.10000000149011612);
        motion_y += (double)(jrand_float(&shear_random) * 0.05F);
        motion_x += (double)((jrand_float(&shear_random)
            - jrand_float(&shear_random)) * 0.1F);
        motion_z += (double)((jrand_float(&shear_random)
            - jrand_float(&shear_random)) * 0.1F);
        if (!gm_live_spawn_item_exact_hover(
                drops, item_eid, x, y + 1.0, z,
                motion_x, motion_y, motion_z, item_yaw, hover_start,
                40, 1, 0, 0, 10, 0))
            return -1;
        if (m->next_id <= item_eid) m->next_id = item_eid + 1;
        if (m->next_orb_id <= item_eid) m->next_orb_id = item_eid + 1;
    }
    *shear_random_seed48 = shear_random.seed;
    {
        ITAStack tool = mob_ita_stack(held);
        if (ita_attempt_damage(&tool, 1, &tool_random.random)) {
            (void)isr_decr_stack_size(inventory, hand_slot, 1);
        } else {
            held.meta = tool.damage;
            isr_set_stack(inventory, hand_slot, held);
        }
    }
    ew_store_copy(next_store(m), s);
    return 2;
}

int gm_mobs_shear_snowman(
        GmMobLive *m, int eid, IsrInv *inventory, int hand_slot) {
    EwStore *s;
    ICStack held;
    int slot;
    if (!m || !inventory) return 0;
    slot = mob_slot_by_eid(m, eid);
    if (slot < 0) return 0;
    s = now_store(m);
    held = isr_get_stack(inventory, hand_slot);
    if (s->type[slot] != EW_TYPE_SNOWMAN
            || held.item != 359 || held.count <= 0)
        return 0;
    /* ItemShears handles the IShearable target even after its pumpkin has
     * already been removed, but only an eligible target damages the tool. */
    if (!m->snowman_pumpkin[slot]) return 1;
    m->snowman_pumpkin[slot] = 0;
    {
        ITAStack tool = mob_ita_stack(held);
        if (ita_attempt_damage(
                &tool, 1, &m->entity_random[slot].random)) {
            (void)isr_decr_stack_size(inventory, hand_slot, 1);
        } else {
            held.meta = tool.damage;
            isr_set_stack(inventory, hand_slot, held);
        }
    }
    ew_store_copy(next_store(m), s);
    return 2;
}

static int passive_sound_event(int type, int lethal) {
    if (type == EW_TYPE_HORSE)
        return lethal ? GM_MOB_SOUND_HORSE_DEATH
            : GM_MOB_SOUND_HORSE_HURT;
    if (type == EW_TYPE_DONKEY)
        return lethal ? GM_MOB_SOUND_DONKEY_DEATH
            : GM_MOB_SOUND_DONKEY_HURT;
    if (type == EW_TYPE_MULE)
        return lethal ? GM_MOB_SOUND_MULE_DEATH : GM_MOB_SOUND_MULE_HURT;
    if (type == EW_TYPE_SKELETON_HORSE)
        return lethal ? GM_MOB_SOUND_SKELETON_HORSE_DEATH
            : GM_MOB_SOUND_SKELETON_HORSE_HURT;
    if (type == EW_TYPE_ZOMBIE_HORSE)
        return lethal ? GM_MOB_SOUND_ZOMBIE_HORSE_DEATH
            : GM_MOB_SOUND_ZOMBIE_HORSE_HURT;
    if (type == EW_TYPE_LLAMA)
        return lethal ? GM_MOB_SOUND_LLAMA_DEATH
            : GM_MOB_SOUND_LLAMA_HURT;
    if (type == EW_TYPE_POLAR_BEAR)
        return lethal ? GM_MOB_SOUND_POLAR_BEAR_DEATH
            : GM_MOB_SOUND_POLAR_BEAR_HURT;
    if (type == EW_TYPE_RABBIT)
        return lethal ? GM_MOB_SOUND_RABBIT_DEATH
            : GM_MOB_SOUND_RABBIT_HURT;
    if (type == EW_TYPE_WOLF)
        return lethal ? GM_MOB_SOUND_WOLF_DEATH : GM_MOB_SOUND_WOLF_HURT;
    if (type == EW_TYPE_OCELOT)
        return lethal ? GM_MOB_SOUND_OCELOT_DEATH
            : GM_MOB_SOUND_OCELOT_HURT;
    if (type == EW_TYPE_CHICKEN)
        return lethal ? GM_MOB_SOUND_CHICKEN_DEATH
            : GM_MOB_SOUND_CHICKEN_HURT;
    if (type == EW_TYPE_PIG)
        return lethal ? GM_MOB_SOUND_PIG_DEATH : GM_MOB_SOUND_PIG_HURT;
    if (type == EW_TYPE_COW || type == EW_TYPE_MOOSHROOM)
        return lethal ? GM_MOB_SOUND_COW_DEATH : GM_MOB_SOUND_COW_HURT;
    return lethal ? GM_MOB_SOUND_SHEEP_DEATH : GM_MOB_SOUND_SHEEP_HURT;
}

static float passive_sound_volume(int type) {
    if (gm_mobs_horse_type(type)) return 0.8F;
    return type == EW_TYPE_COW || type == EW_TYPE_MOOSHROOM
        || tameable_type(type) ? 0.4F : 1.0F;
}

static int living_hurt_death_sound_event(
        const GmMobLive *m, int slot, int type, int size, int lethal) {
    if (gm_passive(type)) return passive_sound_event(type, lethal);
    switch (type) {
    case EW_TYPE_ZOMBIE:
        return lethal ? GM_MOB_SOUND_ZOMBIE_DEATH
            : GM_MOB_SOUND_ZOMBIE_HURT;
    case EW_TYPE_ZOMBIE_VILLAGER:
        return lethal ? GM_MOB_SOUND_ZOMBIE_VILLAGER_DEATH
            : GM_MOB_SOUND_ZOMBIE_VILLAGER_HURT;
    case EW_TYPE_PIGMAN:
        return lethal ? GM_MOB_SOUND_PIGMAN_DEATH
            : GM_MOB_SOUND_PIGMAN_HURT;
    case EW_TYPE_SKELETON:
        return lethal ? GM_MOB_SOUND_SKELETON_DEATH
            : GM_MOB_SOUND_SKELETON_HURT;
    case EW_TYPE_STRAY:
        return lethal ? GM_MOB_SOUND_STRAY_DEATH
            : GM_MOB_SOUND_STRAY_HURT;
    case EW_TYPE_WITHER_SKELETON:
        return lethal ? GM_MOB_SOUND_WITHER_SKELETON_DEATH
            : GM_MOB_SOUND_WITHER_SKELETON_HURT;
    case EW_TYPE_CREEPER:
        return lethal ? GM_MOB_SOUND_CREEPER_DEATH
            : GM_MOB_SOUND_CREEPER_HURT;
    case EW_TYPE_SPIDER:
    case EW_TYPE_CAVE_SPIDER:
        return lethal ? GM_MOB_SOUND_SPIDER_DEATH
            : GM_MOB_SOUND_SPIDER_HURT;
    case EW_TYPE_ENDERMAN:
        return lethal ? GM_MOB_SOUND_ENDERMAN_DEATH
            : GM_MOB_SOUND_ENDERMAN_HURT;
    case EW_TYPE_BLAZE:
        return lethal ? GM_MOB_SOUND_BLAZE_DEATH
            : GM_MOB_SOUND_BLAZE_HURT;
    case EW_TYPE_GHAST:
        return lethal ? GM_MOB_SOUND_GHAST_DEATH
            : GM_MOB_SOUND_GHAST_HURT;
    case EW_TYPE_SLIME:
        if (size <= 1)
            return lethal ? GM_MOB_SOUND_SMALL_SLIME_DEATH
                : GM_MOB_SOUND_SMALL_SLIME_HURT;
        return lethal ? GM_MOB_SOUND_SLIME_DEATH
            : GM_MOB_SOUND_SLIME_HURT;
    case EW_TYPE_MAGMA:
        if (size <= 1)
            return lethal ? GM_MOB_SOUND_SMALL_MAGMA_DEATH
                : GM_MOB_SOUND_SMALL_MAGMA_HURT;
        return lethal ? GM_MOB_SOUND_MAGMA_DEATH
            : GM_MOB_SOUND_MAGMA_HURT;
    case EW_TYPE_SILVERFISH:
        return lethal ? GM_MOB_SOUND_SILVERFISH_DEATH
            : GM_MOB_SOUND_SILVERFISH_HURT;
    case EW_TYPE_VILLAGER:
        return lethal ? GM_MOB_SOUND_VILLAGER_DEATH
            : GM_MOB_SOUND_VILLAGER_HURT;
    case EW_TYPE_WITCH:
        return lethal ? GM_MOB_SOUND_WITCH_DEATH
            : GM_MOB_SOUND_WITCH_HURT;
    case EW_TYPE_VINDICATOR:
        return lethal ? GM_MOB_SOUND_VINDICATOR_DEATH
            : GM_MOB_SOUND_VINDICATOR_HURT;
    case EW_TYPE_EVOKER:
        return lethal ? GM_MOB_SOUND_EVOKER_DEATH
            : GM_MOB_SOUND_EVOKER_HURT;
    case EW_TYPE_VEX:
        return lethal ? GM_MOB_SOUND_VEX_DEATH
            : GM_MOB_SOUND_VEX_HURT;
    case EW_TYPE_GUARDIAN:
        if (m && slot > 0 && m->entity_in_water[slot])
            return lethal ? GM_MOB_SOUND_GUARDIAN_DEATH
                : GM_MOB_SOUND_GUARDIAN_HURT;
        return lethal ? GM_MOB_SOUND_GUARDIAN_DEATH_LAND
            : GM_MOB_SOUND_GUARDIAN_HURT_LAND;
    case EW_TYPE_ELDER_GUARDIAN:
        if (m && slot > 0 && m->entity_in_water[slot])
            return lethal ? GM_MOB_SOUND_ELDER_GUARDIAN_DEATH
                : GM_MOB_SOUND_ELDER_GUARDIAN_HURT;
        return lethal ? GM_MOB_SOUND_ELDER_GUARDIAN_DEATH_LAND
            : GM_MOB_SOUND_ELDER_GUARDIAN_HURT_LAND;
    case EW_TYPE_IRON_GOLEM:
        return lethal ? GM_MOB_SOUND_IRON_GOLEM_DEATH
            : GM_MOB_SOUND_IRON_GOLEM_HURT;
    case EW_TYPE_BAT:
        return lethal ? GM_MOB_SOUND_BAT_DEATH
            : GM_MOB_SOUND_BAT_HURT;
    case EW_TYPE_SNOWMAN:
        return lethal ? GM_MOB_SOUND_SNOWMAN_DEATH
            : GM_MOB_SOUND_SNOWMAN_HURT;
    case EW_TYPE_ENDERMITE:
        return lethal ? GM_MOB_SOUND_ENDERMITE_DEATH
            : GM_MOB_SOUND_ENDERMITE_HURT;
    case EW_TYPE_HUSK:
        return lethal ? GM_MOB_SOUND_HUSK_DEATH
            : GM_MOB_SOUND_HUSK_HURT;
    default:
        return 0;
    }
}

static float living_hurt_death_sound_volume(int type, int size) {
    if (type == EW_TYPE_BAT) return 0.1F;
    if (gm_mobs_horse_type(type)) return 0.8F;
    if (type == EW_TYPE_COW || type == EW_TYPE_MOOSHROOM
            || tameable_type(type))
        return 0.4F;
    if (type == EW_TYPE_GHAST) return 10.0F;
    if (gm_is_slimey(type)) return 0.4F * (float)size;
    return 1.0F;
}

static float living_hurt_death_sound_pitch(int type, float pitch) {
    return type == EW_TYPE_BAT ? pitch * 0.95F : pitch;
}

static int living_talk_interval(int type) {
    if (type == EW_TYPE_GUARDIAN || type == EW_TYPE_ELDER_GUARDIAN)
        return 160;
    if (gm_mobs_horse_type(type)) return 400;
    if (gm_passive(type) || type == EW_TYPE_IRON_GOLEM
            || type == EW_TYPE_SNOWMAN
            || type == EW_TYPE_SQUID)
        return 120;
    return 80;
}

static void hostile_loot_add(
        GmHostileLootOutcome *out, JavaRandom *random,
        int item, int meta, int minimum, int maximum,
        int looting_level) {
    /* Every represented pool has one weight-one entry. LootPool still calls
     * nextInt(1) before its functions, while a constant RandomValueRange does
     * not consume the cursor. */
    (void)jrand_int_bound(random, 1);
    int count = minimum;
    if (maximum > minimum)
        count += jrand_int_bound(random, maximum - minimum + 1);
    if (looting_level > 0) {
        float bonus = (float)looting_level * jrand_float(random);
        count += (int)floorf(bonus + 0.5F);
    }
    if (count <= 0 || out->count >= GM_HOSTILE_LOOT_MAX) return;
    int index = out->count++;
    out->item[index] = item;
    out->quantity[index] = count;
    out->meta[index] = meta;
}

static void hostile_loot_rare(
        GmHostileLootOutcome *out, JavaRandom *random,
        int looting_level, int item_count,
        const int *items, const int *meta) {
    if (jrand_float(random) >= 0.025F + 0.01F * (float)looting_level)
        return;
    int selected = jrand_int_bound(random, item_count);
    if (out->count >= GM_HOSTILE_LOOT_MAX) return;
    int index = out->count++;
    out->item[index] = items[selected];
    out->quantity[index] = 1;
    out->meta[index] = meta ? meta[selected] : 0;
}

static void hostile_loot_append(
        GmHostileLootOutcome *out, int item, int count, int meta) {
    if (count <= 0 || out->count >= GM_HOSTILE_LOOT_MAX) return;
    int index = out->count++;
    out->item[index] = item;
    out->quantity[index] = count;
    out->meta[index] = meta;
}

static void guardian_loot(
        GmHostileLootOutcome *out, JavaRandom *random,
        int elder, int looting, int killed_by_player) {
    /* entities/{guardian,elder_guardian}: shard pool, weighted fish/crystal/
     * empty pool, elder wet sponge, then the nested fishing/fish rare pool. */
    (void)jrand_int_bound(random, 1);
    int shards = jrand_int_bound(random, 3);
    if (looting > 0)
        shards += (int)floorf(
            (float)looting * jrand_float(random) + 0.5F);
    hostile_loot_append(out, 409, shards, 0);

    int second = jrand_int_bound(random, elder ? 6 : 5);
    int fish_weight = elder ? 3 : 2;
    if (second < fish_weight) {
        int count = 1;
        if (looting > 0)
            count += (int)floorf(
                (float)looting * jrand_float(random) + 0.5F);
        hostile_loot_append(out, 349, count, 0);
    } else if (second < fish_weight + 2) {
        int count = 1;
        if (looting > 0)
            count += (int)floorf(
                (float)looting * jrand_float(random) + 0.5F);
        hostile_loot_append(out, 410, count, 0);
    }

    if (elder && killed_by_player) {
        (void)jrand_int_bound(random, 1);
        hostile_loot_append(out, 19, 1, 1);
    }
    if (killed_by_player
            && jrand_float(random) < 0.025F + 0.01F * (float)looting) {
        (void)jrand_int_bound(random, 1);
        int roll = jrand_int_bound(random, 100);
        int meta = roll < 60 ? 0 : roll < 85 ? 1 : roll < 87 ? 2 : 3;
        hostile_loot_append(out, 349, 1, meta);
    }
}

int gm_mobs_generate_hostile_loot(
        int type, int size, uint64_t *entity_seed48,
        int looting_level, int killed_by_player,
        GmHostileLootOutcome *outcome) {
    if (!entity_seed48 || !outcome
            || *entity_seed48 >= (UINT64_C(1) << 48)
            || size < 1 || size > 16
            || looting_level < 0 || looting_level > 10
            || (killed_by_player != 0 && killed_by_player != 1))
        return 0;
    JavaRandom random = {*entity_seed48};
    GmHostileLootOutcome out = {0};
    int looting = killed_by_player ? looting_level : 0;
    switch (type) {
    case EW_TYPE_ZOMBIE:
    case EW_TYPE_ZOMBIE_VILLAGER: {
        static const int rare[] = {265, 391, 392};
        hostile_loot_add(&out, &random, 367, 0, 0, 2, looting);
        if (killed_by_player)
            hostile_loot_rare(
                &out, &random, looting, 3, rare, NULL);
        break;
    }
    case EW_TYPE_HUSK: {
        static const int rare[] = {265, 391, 392};
        hostile_loot_add(&out, &random, 367, 0, 0, 2, looting);
        if (killed_by_player)
            hostile_loot_rare(
                &out, &random, looting, 3, rare, NULL);
        break;
    }
    case EW_TYPE_SKELETON:
        hostile_loot_add(&out, &random, 262, 0, 0, 2, looting);
        hostile_loot_add(&out, &random, 352, 0, 0, 2, looting);
        break;
    case EW_TYPE_STRAY: {
        hostile_loot_add(&out, &random, 262, 0, 0, 2, looting);
        hostile_loot_add(&out, &random, 352, 0, 0, 2, looting);
        if (killed_by_player) {
            (void)jrand_int_bound(&random, 1);
            int count = jrand_int_bound(&random, 2);
            if (looting > 0)
                count += (int)floorf(
                    (float)looting * jrand_float(&random) + 0.5F);
            if (count > 1) count = 1;
            int before = out.count;
            hostile_loot_append(&out, 440, count, 0);
            if (out.count > before)
                out.potion_type[before] =
                    GM_HOSTILE_LOOT_POTION_SLOWNESS;
        }
        break;
    }
    case EW_TYPE_WITHER_SKELETON: {
        static const int rare[] = {397};
        static const int rare_meta[] = {1};
        hostile_loot_add(&out, &random, 263, 0, -1, 1, looting);
        hostile_loot_add(&out, &random, 352, 0, 0, 2, looting);
        if (killed_by_player)
            hostile_loot_rare(
                &out, &random, looting, 1, rare, rare_meta);
        break;
    }
    case EW_TYPE_CREEPER:
        hostile_loot_add(&out, &random, 289, 0, 0, 2, looting);
        break;
    case EW_TYPE_SPIDER:
    case EW_TYPE_CAVE_SPIDER:
        hostile_loot_add(&out, &random, 287, 0, 0, 2, looting);
        if (killed_by_player)
            hostile_loot_add(
                &out, &random, 375, 0, -1, 1, looting);
        break;
    case EW_TYPE_ENDERMAN:
        hostile_loot_add(&out, &random, 368, 0, 0, 1, looting);
        break;
    case EW_TYPE_BLAZE:
        if (killed_by_player)
            hostile_loot_add(
                &out, &random, 369, 0, 0, 1, looting);
        break;
    case EW_TYPE_GHAST:
        hostile_loot_add(&out, &random, 370, 0, 0, 1, looting);
        hostile_loot_add(&out, &random, 289, 0, 0, 2, looting);
        break;
    case EW_TYPE_PIGMAN: {
        static const int rare[] = {266};
        hostile_loot_add(&out, &random, 367, 0, 0, 1, looting);
        hostile_loot_add(&out, &random, 371, 0, 0, 1, looting);
        if (killed_by_player)
            hostile_loot_rare(
                &out, &random, looting, 1, rare, NULL);
        break;
    }
    case EW_TYPE_SLIME:
        if (size == 1)
            hostile_loot_add(
                &out, &random, 341, 0, 0, 2, looting);
        break;
    case EW_TYPE_MAGMA:
        if (size > 1)
            hostile_loot_add(
                &out, &random, 378, 0, -2, 1, looting);
        break;
    case EW_TYPE_SILVERFISH:
    case EW_TYPE_ENDERMITE:
    case EW_TYPE_GIANT:
    case EW_TYPE_VILLAGER:
        break;
    case EW_TYPE_VINDICATOR:
        if (killed_by_player)
            hostile_loot_add(&out, &random, 388, 0, 0, 1, looting);
        break;
    case EW_TYPE_EVOKER:
        hostile_loot_add(&out, &random, 449, 0, 1, 1, 0);
        if (killed_by_player)
            hostile_loot_add(&out, &random, 388, 0, 0, 1, looting);
        break;
    case EW_TYPE_VEX:
        break;
    case EW_TYPE_GUARDIAN:
        guardian_loot(&out, &random, 0, looting, killed_by_player);
        break;
    case EW_TYPE_ELDER_GUARDIAN:
        guardian_loot(&out, &random, 1, looting, killed_by_player);
        break;
    case EW_TYPE_IRON_GOLEM:
        hostile_loot_add(&out, &random, 38, 0, 0, 2, 0);
        hostile_loot_add(&out, &random, 265, 0, 3, 5, 0);
        break;
    case EW_TYPE_SNOWMAN:
        hostile_loot_add(&out, &random, 332, 0, 0, 15, 0);
        break;
    case EW_TYPE_POLAR_BEAR: {
        int meta = jrand_int_bound(&random, 4) < 3 ? 0 : 1;
        int count = jrand_int_bound(&random, 3)
            + passive_looting_bonus(&random, looting);
        hostile_loot_append(&out, 349, count, meta);
        break;
    }
    case EW_TYPE_RABBIT: {
        (void)jrand_int_bound(&random, 1);
        int hide = jrand_int_bound(&random, 2)
            + passive_looting_bonus(&random, looting);
        (void)jrand_int_bound(&random, 1);
        int meat = jrand_int_bound(&random, 2)
            + passive_looting_bonus(&random, looting);
        hostile_loot_append(&out, 415, hide, 0);
        hostile_loot_append(&out, 411, meat, 0);
        if (killed_by_player
                && jrand_float(&random)
                    < 0.1F + 0.03F * (float)looting) {
            (void)jrand_int_bound(&random, 1);
            hostile_loot_append(&out, 414, 1, 0);
        }
        break;
    }
    default:
        return 0;
    }
    *entity_seed48 = random.seed;
    *outcome = out;
    return 1;
}

/* Exact ordinary player damage for represented non-slime hostiles. Their
 * built-in loot tables are generated on the same private cursor immediately
 * after hurt/death feedback, and the corpse remains loaded through deathTime
 * 20 instead of disappearing at the lethal hit. */
static int mob_player_damage_hostile_slot_exact(
        GmMobLive *m, EwStore *s, int slot,
        double attacker_x, double attacker_z, float damage,
        int looting_level, GmLiveSim *drops,
        const GmMobDeathContext *death_context, int thorns) {
    if (!m || !s || !death_context || slot <= 0
            || slot >= EW_MAX_ENTITIES || !s->alive[slot]
            || !mob_exact_ordinary_death_type(s->type[slot])
            || m->controlled_no_ai[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || damage <= 0.0F
            || looting_level < 0)
        return 1;
    int fresh = m->entity_hurt_resistant[slot] <= 10;
    if (!fresh && damage <= m->entity_last_damage[slot]) return 1;
    if (fresh && !death_context->math_random_seed48) return 1;
    float applied = fresh ? damage : damage - m->entity_last_damage[slot];
    applied = player_attack_after_mob_armor(
        m, slot, s->type[slot], applied);
    applied = mob_resistance_damage(m, slot, applied);
    int lethal = s->health[slot]
        <= mob_preview_absorbed_damage(m, slot, applied);
    GmHostileLootOutcome preview = {0};
    if (lethal && death_context->do_mob_loot) {
        uint64_t preview_seed = m->entity_random[slot].random.seed;
        JavaRandom random = {preview_seed};
        if (fresh) {
            (void)jrand_double(&random);
            (void)jrand_double(&random);
            (void)jrand_float(&random);
            (void)jrand_float(&random);
        }
        preview_seed = random.seed;
        if (!gm_mobs_generate_hostile_loot(
                s->type[slot], m->size[slot], &preview_seed,
                looting_level, 1, &preview)
                || !drops || !death_context->next_entity_id
                || *death_context->next_entity_id <= 0
                || *death_context->next_entity_id > INT_MAX - preview.count
                || !mob_live_reserve_item_slots(drops, preview.count))
            return 1;
    }

    applied = mob_absorb_damage(m, slot, applied);
    m->entity_last_damage[slot] = damage;
    if (fresh) {
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
    }
    s->health[slot] -= applied;
    if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
    mark_hurt(m, s, slot);
    m->entity_recently_hit[slot] = 100;
    m->entity_attacking_player[slot] = 1;
    if (fresh)
        player_attack_fresh_feedback(
            m, s, slot, attacker_x, attacker_z, death_context,
            thorns ? 33 : 2);
    if (!lethal) return 2;

    m->entity_dead[slot] = 1;
    m->entity_death_time[slot] = 0;
    if (death_context->do_mob_loot) {
        GmHostileLootOutcome loot;
        uint64_t seed = m->entity_random[slot].random.seed;
        (void)gm_mobs_generate_hostile_loot(
            s->type[slot], m->size[slot], &seed,
            looting_level, 1, &loot);
        m->entity_random[slot].random.seed = seed;
        for (int i = 0; i < loot.count; ++i)
            (void)mob_spawn_passive_loot_item(
                drops, death_context->next_entity_id,
                death_context->math_random_seed48,
                s->x[slot], s->y[slot], s->z[slot],
                loot.item[i], loot.quantity[i], loot.meta[i],
                loot.potion_type[i]);
    }
    if (death_context->next_entity_id) {
        if (m->next_id < *death_context->next_entity_id)
            m->next_id = *death_context->next_entity_id;
        if (m->next_orb_id < *death_context->next_entity_id)
            m->next_orb_id = *death_context->next_entity_id;
    }
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 3,
        s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    return 2;
}

static int mob_spawn_passive_loot_item(
        GmLiveSim *drops, int *next_entity_id,
        uint64_t *math_random_seed48,
        double x, double y, double z, int item, int count, int meta,
        int semantic_potion_type) {
    if (!drops || !next_entity_id || !math_random_seed48
            || *next_entity_id <= 0 || *next_entity_id >= INT_MAX)
        return 0;
    uint64_t staged_math_seed48 = *math_random_seed48;
    int eid = *next_entity_id;
    float hover_start = (float)(
        mob_math_random_next_double(&staged_math_seed48) * (MC_PI * 2.0));
    float yaw = (float)(
        mob_math_random_next_double(&staged_math_seed48) * 360.0);
    double motion_x = (double)(float)(
        mob_math_random_next_double(&staged_math_seed48)
            * 0.20000000298023224 - 0.10000000149011612);
    double motion_z = (double)(float)(
        mob_math_random_next_double(&staged_math_seed48)
            * 0.20000000298023224 - 0.10000000149011612);
    int live_meta = semantic_potion_type
            == GM_HOSTILE_LOOT_POTION_SLOWNESS
        ? 17 : meta;
    if (!gm_live_spawn_item_exact_hover(
        drops, eid, x, y, z,
        motion_x, 0.20000000298023224, motion_z, yaw, hover_start,
        item, count, live_meta, 0, 10, 0))
        return 0;
    if (semantic_potion_type != 0)
        for (int slot = 0; slot < gm_live_entity_slot_count(drops); ++slot) {
            GmLiveEnt *drop = gm_live_entity_mut(drops, slot);
            if (drop && drop->active && drop->eid == eid) {
                drop->semantic_potion_type =
                    semantic_potion_type;
                break;
            }
        }
    *math_random_seed48 = staged_math_seed48;
    *next_entity_id = eid + 1;
    return 1;
}

static int passive_looting_bonus(JavaRandom *random, int looting_level) {
    if (!random || looting_level <= 0) return 0;
    float scaled = (float)looting_level * jrand_float(random);
    return (int)floorf(scaled + 0.5F);
}

static void passive_loot_append(
        GmPassiveLootOutcome *outcome, int item, int count, int meta) {
    if (!outcome || count <= 0 || outcome->count >= GM_PASSIVE_LOOT_MAX)
        return;
    int index = outcome->count++;
    outcome->item[index] = item;
    outcome->quantity[index] = count;
    outcome->meta[index] = meta;
    outcome->stack[index] = ic_mk(item, count, meta);
}

static void passive_loot_append_stack(
        GmPassiveLootOutcome *outcome, ICStack stack) {
    if (!outcome || stack.item <= 0 || stack.count <= 0
            || outcome->count >= GM_PASSIVE_LOOT_MAX)
        return;
    int index = outcome->count++;
    outcome->item[index] = stack.item;
    outcome->quantity[index] = stack.count;
    outcome->meta[index] = stack.meta;
    outcome->stack[index] = stack;
}

/* Built-in 1.11.2 passive loot tables. Constant one-entry pool selection
 * still consumes nextInt(1); fixed numeric ranges do not consume a draw.
 * LootingEnchantBonus reads one nextFloat per stack only when a player
 * killer supplies a positive Looting modifier. EntityPig's saddle is an
 * onDeath tail outside both canDropLoot and the doMobLoot gamerule. */
static int mob_generate_passive_loot(
        const GmMobLive *m, const EwStore *s, int slot,
        JavaRandom *random, int looting_level, int killed_by_player,
        int do_mob_loot, GmPassiveLootOutcome *outcome) {
    if (!m || !s || !random || !outcome || slot <= 0
            || slot >= EW_MAX_ENTITIES || !gm_passive(s->type[slot])
            || looting_level < 0)
        return 0;
    memset(outcome, 0, sizeof *outcome);
    int adult_loot = do_mob_loot && m->growing_age[slot] >= 0;
    int looting = killed_by_player ? looting_level : 0;
    if (adult_loot && s->type[slot] == EW_TYPE_CHICKEN) {
        (void)jrand_int_bound(random, 1);
        int feathers = jrand_int_bound(random, 3)
            + passive_looting_bonus(random, looting);
        (void)jrand_int_bound(random, 1);
        int chicken = 1 + passive_looting_bonus(random, looting);
        passive_loot_append(outcome, 288, feathers, 0);
        passive_loot_append(
            outcome, m->fire_ticks[slot] > 0 ? 366 : 365,
            chicken, 0);
    } else if (adult_loot && s->type[slot] == EW_TYPE_PIG) {
        (void)jrand_int_bound(random, 1);
        int pork = 1 + jrand_int_bound(random, 3)
            + passive_looting_bonus(random, looting);
        passive_loot_append(
            outcome, m->fire_ticks[slot] > 0 ? 320 : 319, pork, 0);
    } else if (adult_loot && (s->type[slot] == EW_TYPE_COW
            || s->type[slot] == EW_TYPE_MOOSHROOM)) {
        (void)jrand_int_bound(random, 1);
        int leather = jrand_int_bound(random, 3)
            + passive_looting_bonus(random, looting);
        (void)jrand_int_bound(random, 1);
        int beef = 1 + jrand_int_bound(random, 3)
            + passive_looting_bonus(random, looting);
        passive_loot_append(outcome, 334, leather, 0);
        passive_loot_append(
            outcome, m->fire_ticks[slot] > 0 ? 364 : 363, beef, 0);
    } else if (adult_loot && s->type[slot] == EW_TYPE_SHEEP) {
        if (!(m->sheep_data[slot] & 16)) {
            (void)jrand_int_bound(random, 1);
            passive_loot_append(
                outcome, 35, 1, m->sheep_data[slot] & 15);
            (void)jrand_int_bound(random, 1);
        }
        (void)jrand_int_bound(random, 1);
        int mutton = 1 + jrand_int_bound(random, 2)
            + passive_looting_bonus(random, looting);
        passive_loot_append(
            outcome, m->fire_ticks[slot] > 0 ? 424 : 423,
            mutton, 0);
    } else if (adult_loot && gm_mobs_horse_type(s->type[slot])) {
        (void)jrand_int_bound(random, 1);
        int item = s->type[slot] == EW_TYPE_SKELETON_HORSE ? 352
            : s->type[slot] == EW_TYPE_ZOMBIE_HORSE ? 367 : 334;
        int count = jrand_int_bound(random, 3)
            + passive_looting_bonus(random, looting);
        passive_loot_append(outcome, item, count, 0);
    } else if (adult_loot && s->type[slot] == EW_TYPE_POLAR_BEAR) {
        int meta = jrand_int_bound(random, 4) < 3 ? 0 : 1;
        int count = jrand_int_bound(random, 3)
            + passive_looting_bonus(random, looting);
        passive_loot_append(outcome, 349, count, meta);
    } else if (adult_loot && s->type[slot] == EW_TYPE_RABBIT) {
        (void)jrand_int_bound(random, 1);
        int hide = jrand_int_bound(random, 2)
            + passive_looting_bonus(random, looting);
        (void)jrand_int_bound(random, 1);
        int meat = jrand_int_bound(random, 2)
            + passive_looting_bonus(random, looting);
        passive_loot_append(outcome, 415, hide, 0);
        passive_loot_append(
            outcome, m->fire_ticks[slot] > 0 ? 412 : 411, meat, 0);
        if (killed_by_player
                && jrand_float(random) < 0.1F + 0.03F * (float)looting) {
            (void)jrand_int_bound(random, 1);
            passive_loot_append(outcome, 414, 1, 0);
        }
    }
    if (s->type[slot] == EW_TYPE_PIG && m->pig_saddled[slot])
        passive_loot_append(outcome, 329, 1, 0);
    if (gm_mobs_horse_type(s->type[slot])) {
        int inventory_size = horse_inventory_size(m, slot);
        for (int inventory_slot = 0;
                inventory_slot < inventory_size; ++inventory_slot)
            passive_loot_append_stack(
                outcome, m->horse_inventory[slot][inventory_slot]);
        if (m->horse_chested[slot])
            passive_loot_append(outcome, 54, 1, 0);
    }
    return 1;
}

static int mob_spawn_passive_loot(
        GmMobLive *m, const EwStore *s, int slot,
        GmLiveSim *drops, uint64_t *math_random_seed48,
        int *next_entity_id, const GmPassiveLootOutcome *loot) {
    if (!m || !s || !loot) return 0;
    for (int item = 0; item < loot->count; ++item) {
        uint64_t staged_math_seed48;
        float hover_start, yaw;
        double motion_x, motion_z;
        int eid;
        if (!drops || !next_entity_id || !math_random_seed48
                || *next_entity_id <= 0 || *next_entity_id >= INT_MAX)
            return 0;
        staged_math_seed48 = *math_random_seed48;
        eid = *next_entity_id;
        hover_start = (float)(mob_math_random_next_double(
            &staged_math_seed48) * (MC_PI * 2.0));
        yaw = (float)(mob_math_random_next_double(
            &staged_math_seed48) * 360.0);
        motion_x = (double)(float)(mob_math_random_next_double(
            &staged_math_seed48) * 0.20000000298023224
            - 0.10000000149011612);
        motion_z = (double)(float)(mob_math_random_next_double(
            &staged_math_seed48) * 0.20000000298023224
            - 0.10000000149011612);
        if (!gm_live_spawn_stack_exact_hover(
                drops, eid, s->x[slot], s->y[slot], s->z[slot],
                motion_x, 0.20000000298023224, motion_z,
                yaw, hover_start, loot->stack[item], 0, 10, 0))
            return 0;
        *math_random_seed48 = staged_math_seed48;
        *next_entity_id = eid + 1;
    }
    if (next_entity_id) {
        if (m->next_id < *next_entity_id)
            m->next_id = *next_entity_id;
        if (m->next_orb_id < *next_entity_id)
            m->next_orb_id = *next_entity_id;
    }
    return 1;
}

/* Exact source-less damage for normal passive ticks and controlled anvil
 * fixtures. EntityAnimal clears love before the superclass can reject a hit.
 * With no source entity, accepted damage does not create a revenge target or
 * panic goal; only fire itself can make EntityAIPanic eligible afterward. */
static int mob_source_damage_passive_slot_exact(
        GmMobLive *m, EwStore *s, int slot, float damage,
        GmLiveSim *drops, uint64_t *math_random_seed48,
        int *next_entity_id, int do_mob_loot, int pre_sound,
        int set_been_attacked, int bypass_armor,
        const GmMobDamageEntitySource *entity_source) {
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot] || !gm_passive(s->type[slot])
            || m->entity_dead[slot] || s->health[slot] <= 0.0F
            || damage <= 0.0F)
        return 0;
    int fresh = m->entity_hurt_resistant[slot] <= 10;
    if (!fresh && damage <= m->entity_last_damage[slot]) {
        m->sheep_in_love[slot] = 0;
        m->sheep_bred_by_player[slot] = 0;
        if (pre_sound)
            mob_event_append(
                m, GM_MOB_EVENT_SOUND, s->id[slot], pre_sound,
                s->x[slot], s->y[slot], s->z[slot], 1.0F, 1.0F);
        return 0;
    }
    if (fresh && !math_random_seed48) return -1;
    int has_owner = entity_source && entity_source->has_owner;
    int killed_by_player = has_owner && entity_source->player_source;
    int looting_level = killed_by_player
        ? entity_source->looting_level : 0;
    float applied = fresh ? damage : damage - m->entity_last_damage[slot];
    if (!bypass_armor)
        applied = player_attack_after_mob_armor(
            m, slot, s->type[slot], applied);
    applied = mob_resistance_damage(m, slot, applied);
    int lethal = s->health[slot]
        <= mob_preview_absorbed_damage(m, slot, applied);
    GmPassiveLootOutcome preview = {0};
    if (lethal) {
        JavaRandom random = m->entity_random[slot].random;
        if (fresh) {
            if (has_owner) {
                (void)jrand_double(&random);
                (void)jrand_double(&random);
            } else if (set_been_attacked) {
                (void)jrand_double(&random);
            }
            (void)jrand_float(&random);
            (void)jrand_float(&random);
        }
        if (!mob_generate_passive_loot(
                m, s, slot, &random, looting_level, killed_by_player,
                do_mob_loot, &preview)
                || (preview.count > 0
                    && (!drops || !math_random_seed48 || !next_entity_id
                        || *next_entity_id <= 0
                        || *next_entity_id > INT_MAX - preview.count
                        || !mob_live_reserve_item_slots(
                            drops, preview.count))))
            return -1;
    }

    m->sheep_in_love[slot] = 0;
    m->sheep_bred_by_player[slot] = 0;
    if (pre_sound)
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot], pre_sound,
            s->x[slot], s->y[slot], s->z[slot], 1.0F, 1.0F);
    applied = mob_absorb_damage(m, slot, applied);
    m->entity_age[slot] = 0;
    m->entity_last_damage[slot] = damage;
    if (has_owner) {
        mark_hurt(m, s, slot);
        if (killed_by_player) {
            m->entity_recently_hit[slot] = 100;
            m->entity_attacking_player[slot] = 1;
            villager_player_harm_append(m, s, slot, lethal);
            if (s->type[slot] == EW_TYPE_LLAMA) {
                m->llama_attack_target_eid[slot] = 0;
                m->llama_attack_target_kind[slot] = 1;
            }
            if (s->type[slot] == EW_TYPE_POLAR_BEAR) {
                if (m->growing_age[slot] >= 0) {
                    m->polar_player_target[slot] = 1;
                } else {
                    for (int adult = 1;
                            adult < EW_MAX_ENTITIES; ++adult) {
                        if (!s->alive[adult]
                                || s->type[adult]
                                    != EW_TYPE_POLAR_BEAR
                                || m->growing_age[adult] < 0
                                || m->entity_dimension[adult]
                                    != m->entity_dimension[slot])
                            continue;
                        double alert_dx = s->x[adult] - s->x[slot];
                        double alert_dy = s->y[adult] - s->y[slot];
                        double alert_dz = s->z[adult] - s->z[slot];
                        if (alert_dx * alert_dx
                                + alert_dy * alert_dy
                                + alert_dz * alert_dz <= 400.0D)
                            m->polar_player_target[adult] = 1;
                    }
                    for (int adult = 0;
                            adult < m->living_cold_count; ++adult) {
                        GmLivingColdSlot *cold = &m->living_cold[adult];
                        if (!cold->store_alive
                                || cold->store_type
                                    != EW_TYPE_POLAR_BEAR
                                || cold->growing_age < 0
                                || cold->entity_dimension
                                    != m->entity_dimension[slot])
                            continue;
                        double alert_dx = cold->store_x - s->x[slot];
                        double alert_dy = cold->store_y - s->y[slot];
                        double alert_dz = cold->store_z - s->z[slot];
                        if (alert_dx * alert_dx
                                + alert_dy * alert_dy
                                + alert_dz * alert_dz <= 400.0D)
                            cold->polar_player_target = 1;
                    }
                }
            }
        }
    }
    if (fresh) {
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
        m->entity_max_hurt_time[slot] = 10;
    }
    s->health[slot] -= applied;
    if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
    if (fresh) {
        float pitch;
        if (!lethal)
            m->entity_living_sound_time[slot] =
                -living_talk_interval(s->type[slot]);
        m->entity_velocity_changed[slot] = 1;
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 2,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
        if (has_owner) {
            pitch = player_attack_primary_knockback(
                m, s, slot, entity_source->x, entity_source->z,
                entity_source->death_context);
        } else {
            if (set_been_attacked)
                (void)jrand_double(&m->entity_random[slot].random);
            double random_yaw = mob_math_random_next_double(
                math_random_seed48);
            m->entity_attacked_yaw[slot] =
                (float)((int)(random_yaw * 2.0D) * 180);
            float first = jrand_float(&m->entity_random[slot].random);
            float second = jrand_float(&m->entity_random[slot].random);
            pitch = (first - second) * 0.2F + 1.0F;
        }
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot],
            passive_sound_event(s->type[slot], lethal),
            s->x[slot], s->y[slot], s->z[slot],
            passive_sound_volume(s->type[slot]),
            pitch);
    }
    if (!lethal) return 1;

    m->entity_dead[slot] = 1;
    m->entity_death_time[slot] = 0;
    GmPassiveLootOutcome loot;
    (void)mob_generate_passive_loot(
        m, s, slot, &m->entity_random[slot].random,
        looting_level, killed_by_player, do_mob_loot, &loot);
    (void)mob_spawn_passive_loot(
        m, s, slot, drops, math_random_seed48,
        next_entity_id, &loot);
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 3,
        s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    return 1;
}

/* Exact source-less damage for promoted ordinary living families. Fall and
 * drowning differ only in the setBeenAttacked resistance draw; both choose
 * attackedAtYaw from Math.random, emit type-specific feedback, and generate
 * non-player loot before retaining the corpse through deathTime 20. */
static int mob_source_damage_ordinary_slot_exact(
        GmMobLive *m, EwStore *s, int slot, float damage,
        GmLiveSim *drops, uint64_t *math_random_seed48,
        int *next_entity_id, int do_mob_loot, int pre_sound,
        int set_been_attacked, int bypass_armor,
        const GmMobDamageEntitySource *entity_source) {
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot]
            || !mob_exact_ordinary_death_type(s->type[slot])
            || s->type[slot] == EW_TYPE_WITCH
            || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || damage <= 0.0F)
        return 0;
    /* EntityBat wakes before EntityLivingBase can reject a same-strength
     * hit through hurtResistantTime. */
    if (s->type[slot] == EW_TYPE_BAT && m->bat_hanging[slot])
        m->bat_hanging[slot] = 0;
    int fresh = m->entity_hurt_resistant[slot] <= 10;
    if (!fresh && damage <= m->entity_last_damage[slot]) {
        if (pre_sound)
            mob_event_append(
                m, GM_MOB_EVENT_SOUND, s->id[slot], pre_sound,
                s->x[slot], s->y[slot], s->z[slot], 1.0F, 1.0F);
        return 0;
    }
    if (fresh && !math_random_seed48) return -1;
    int has_owner = entity_source && entity_source->has_owner;
    int killed_by_player = has_owner && entity_source->player_source;
    int looting_level = killed_by_player
        ? entity_source->looting_level : 0;
    float applied = fresh ? damage : damage - m->entity_last_damage[slot];
    if (!bypass_armor)
        applied = player_attack_after_mob_armor(
            m, slot, s->type[slot], applied);
    applied = mob_resistance_damage(m, slot, applied);
    int lethal = s->health[slot]
        <= mob_preview_absorbed_damage(m, slot, applied);
    GmHostileLootOutcome preview = {0};
    if (lethal && do_mob_loot) {
        JavaRandom random = m->entity_random[slot].random;
        if (fresh) {
            if (has_owner) {
                (void)jrand_double(&random);
                (void)jrand_double(&random);
            } else if (set_been_attacked) {
                (void)jrand_double(&random);
            }
            (void)jrand_float(&random);
            (void)jrand_float(&random);
        }
        uint64_t seed = random.seed;
        if (!gm_mobs_generate_hostile_loot(
                s->type[slot], m->size[slot], &seed,
                looting_level, killed_by_player, &preview)
                || (preview.count > 0
                    && (!drops || !math_random_seed48 || !next_entity_id
                        || *next_entity_id <= 0
                        || *next_entity_id > INT_MAX - preview.count
                        || !mob_live_reserve_item_slots(
                            drops, preview.count))))
            return -1;
    }

    if (pre_sound)
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot], pre_sound,
            s->x[slot], s->y[slot], s->z[slot], 1.0F, 1.0F);
    applied = mob_absorb_damage(m, slot, applied);
    m->entity_age[slot] = 0;
    m->entity_last_damage[slot] = damage;
    if (has_owner) {
        mark_hurt(m, s, slot);
        if (killed_by_player) {
            m->entity_recently_hit[slot] = 100;
            m->entity_attacking_player[slot] = 1;
            villager_player_harm_append(m, s, slot, lethal);
        }
    }
    if (fresh) {
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
        m->entity_max_hurt_time[slot] = 10;
    }
    s->health[slot] -= applied;
    if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
    if (fresh) {
        float pitch;
        if (!lethal)
            m->entity_living_sound_time[slot] =
                -living_talk_interval(s->type[slot]);
        m->entity_velocity_changed[slot] = 1;
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 2,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
        if (has_owner) {
            pitch = player_attack_primary_knockback(
                m, s, slot, entity_source->x, entity_source->z,
                entity_source->death_context);
        } else {
            if (set_been_attacked)
                (void)jrand_double(&m->entity_random[slot].random);
            double random_yaw = mob_math_random_next_double(
                math_random_seed48);
            m->entity_attacked_yaw[slot] =
                (float)((int)(random_yaw * 2.0D) * 180);
            float first = jrand_float(&m->entity_random[slot].random);
            float second = jrand_float(&m->entity_random[slot].random);
            pitch = (first - second) * 0.2F + 1.0F;
        }
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot],
            living_hurt_death_sound_event(
                m, slot, s->type[slot], m->size[slot], lethal),
            s->x[slot], s->y[slot], s->z[slot],
            living_hurt_death_sound_volume(
                s->type[slot], m->size[slot]),
            living_hurt_death_sound_pitch(s->type[slot], pitch));
    }
    if (!lethal) return 1;

    m->entity_dead[slot] = 1;
    m->entity_death_time[slot] = 0;
    if (do_mob_loot) {
        GmHostileLootOutcome loot;
        uint64_t seed = m->entity_random[slot].random.seed;
        (void)gm_mobs_generate_hostile_loot(
            s->type[slot], m->size[slot], &seed,
            looting_level, killed_by_player, &loot);
        m->entity_random[slot].random.seed = seed;
        for (int i = 0; i < loot.count; ++i)
            (void)mob_spawn_passive_loot_item(
                drops, next_entity_id, math_random_seed48,
                s->x[slot], s->y[slot], s->z[slot],
                loot.item[i], loot.quantity[i], loot.meta[i],
                loot.potion_type[i]);
    }
    if (next_entity_id) {
        if (m->next_id < *next_entity_id)
            m->next_id = *next_entity_id;
        if (m->next_orb_id < *next_entity_id)
            m->next_orb_id = *next_entity_id;
    }
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 3,
        s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    return 1;
}

/* Exact fresh source-less Witch damage shared by direct falling-anvil and
 * periodic ON_FIRE routes. A negative return is an atomic fixed-capacity
 * rejection; zero is Java's ordinary hurt-immunity rejection. */
static int mob_source_damage_witch_slot_exact(
        GmMobLive *m, EwStore *s, int slot, float damage,
        GmLiveSim *drops, uint64_t *math_random_seed48,
        int *next_entity_id, int do_mob_loot, int pre_sound,
        const GmMobDamageEntitySource *entity_source) {
    int fresh;
    float applied;
    int lethal;
    EwitchLootOutcome preview_loot = {0};
    if (!m || !s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || !s->alive[slot] || s->type[slot] != EW_TYPE_WITCH
            || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || damage <= 0.0F)
        return 0;
    fresh = m->entity_hurt_resistant[slot] <= 10;
    if (!fresh && damage <= m->entity_last_damage[slot]) {
        if (pre_sound)
            mob_event_append(
                m, GM_MOB_EVENT_SOUND, s->id[slot], pre_sound,
                s->x[slot], s->y[slot], s->z[slot], 1.0F, 1.0F);
        return 0;
    }
    if (fresh && !math_random_seed48) return -1;
    int has_owner = entity_source && entity_source->has_owner;
    int killed_by_player = has_owner && entity_source->player_source;
    int looting_level = killed_by_player
        ? entity_source->looting_level : 0;
    applied = fresh ? damage : damage - m->entity_last_damage[slot];
    applied = mob_resistance_damage(m, slot, applied);
    if (has_owner && entity_source->eid == s->id[slot])
        applied = 0.0F;
    if (entity_source && entity_source->magic_source)
        applied = (float)((double)applied * 0.15D);
    lethal = s->health[slot]
        <= mob_preview_absorbed_damage(m, slot, applied);
    if (lethal && do_mob_loot) {
        JavaRandom preview = m->entity_random[slot].random;
        if (fresh) {
            (void)jrand_double(&preview);
            if (has_owner) (void)jrand_double(&preview);
            (void)jrand_float(&preview);
            (void)jrand_float(&preview);
        }
        ewitch_generate_loot(&preview, looting_level, &preview_loot);
        if (!drops || !next_entity_id || *next_entity_id <= 0
                || *next_entity_id > INT_MAX - preview_loot.count
                || !mob_live_reserve_item_slots(
                    drops, preview_loot.count))
            return -1;
    }

    if (pre_sound)
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot], pre_sound,
            s->x[slot], s->y[slot], s->z[slot], 1.0F, 1.0F);
    applied = mob_absorb_damage(m, slot, applied);
    m->entity_age[slot] = 0;
    m->entity_last_damage[slot] = damage;
    if (fresh) {
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
        m->entity_max_hurt_time[slot] = 10;
    }
    s->health[slot] -= applied;
    if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
    if (has_owner) {
        mark_hurt(m, s, slot);
        if (killed_by_player) {
            m->entity_recently_hit[slot] = 100;
            m->entity_attacking_player[slot] = 1;
        }
    }
    if (fresh) {
        float pitch;
        if (!lethal)
            m->entity_living_sound_time[slot] =
                -living_talk_interval(s->type[slot]);
        m->entity_velocity_changed[slot] = 1;
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 2,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
        if (has_owner) {
            pitch = player_attack_primary_knockback(
                m, s, slot, entity_source->x, entity_source->z,
                entity_source->death_context);
        } else {
            (void)jrand_double(&m->entity_random[slot].random);
            double random_yaw = mob_math_random_next_double(
                math_random_seed48);
            m->entity_attacked_yaw[slot] =
                (float)((int)(random_yaw * 2.0D) * 180);
            float first = jrand_float(&m->entity_random[slot].random);
            float second = jrand_float(&m->entity_random[slot].random);
            pitch = (first - second) * 0.2F + 1.0F;
        }
        mob_event_append(
            m, GM_MOB_EVENT_SOUND, s->id[slot],
            s->health[slot] <= 0.0F
                ? GM_MOB_SOUND_WITCH_DEATH : GM_MOB_SOUND_WITCH_HURT,
            s->x[slot], s->y[slot], s->z[slot],
            1.0F, pitch);
    }
    if (!lethal) return 1;

    m->entity_dead[slot] = 1;
    m->entity_death_time[slot] = 0;
    if (do_mob_loot) {
        EwitchLootOutcome loot;
        ewitch_generate_loot(
            &m->entity_random[slot].random, looting_level, &loot);
        for (int item = 0; item < loot.count; ++item)
            (void)mob_spawn_passive_loot_item(
                drops, next_entity_id, math_random_seed48,
                s->x[slot], s->y[slot], s->z[slot],
                loot.item[item], loot.quantity[item], 0, 0);
    }
    if (next_entity_id) {
        if (m->next_id < *next_entity_id)
            m->next_id = *next_entity_id;
        if (m->next_orb_id < *next_entity_id)
            m->next_orb_id = *next_entity_id;
    }
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 3,
        s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    return 1;
}

static int mob_source_damage_environment_slot_exact(
        GmMobLive *m, EwStore *s, int slot, float damage,
        GmLiveSim *drops, uint64_t *math_random_seed48,
        int *next_entity_id, int do_mob_loot,
        int set_been_attacked, int bypass_armor) {
    if (!s || slot <= 0 || slot >= EW_MAX_ENTITIES) return 0;
    if (s->type[slot] == EW_TYPE_WITCH)
        return mob_source_damage_witch_slot_exact(
            m, s, slot, damage, drops, math_random_seed48,
            next_entity_id, do_mob_loot, 0, NULL);
    if (gm_passive(s->type[slot]))
        return mob_source_damage_passive_slot_exact(
            m, s, slot, damage, drops, math_random_seed48,
            next_entity_id, do_mob_loot, 0,
            set_been_attacked, bypass_armor, NULL);
    return mob_source_damage_ordinary_slot_exact(
        m, s, slot, damage, drops, math_random_seed48,
        next_entity_id, do_mob_loot, 0,
        set_been_attacked, bypass_armor, NULL);
}

static int mob_player_damage_witch_slot_exact(
        GmMobLive *m, EwStore *s, int slot,
        double attacker_x, double attacker_z, float damage,
        int looting_level, GmLiveSim *drops,
        const GmMobDeathContext *death_context, int thorns) {
    float applied;
    int fresh;
    int lethal;
    int equipped;
    int preview_equipment_drop = 0;
    EwitchLootOutcome preview_loot = {0};
    if (!m || !s || !death_context || slot <= 0
            || slot >= EW_MAX_ENTITIES || !s->alive[slot]
            || s->type[slot] != EW_TYPE_WITCH
            || m->controlled_no_ai[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || damage <= 0.0F
            || looting_level < 0)
        return 1;
    fresh = m->entity_hurt_resistant[slot] <= 10;
    if (!fresh && damage <= m->entity_last_damage[slot])
        return 1;
    if (fresh && !death_context->math_random_seed48)
        return 1;
    applied = fresh ? damage : damage - m->entity_last_damage[slot];
    applied = mob_resistance_damage(m, slot, applied);
    if (thorns) applied = (float)((double)applied * 0.15D);
    lethal = s->health[slot]
        <= mob_preview_absorbed_damage(m, slot, applied);
    equipped = m->witch_drinking[slot]
        && witch_potion_stack_meta(m->witch_potion[slot]) != 0;

    if (lethal && death_context->do_mob_loot) {
        JavaRandom preview = m->entity_random[slot].random;
        /* Fresh EntityLivingBase feedback consumes the resistance trials in
         * setBeenAttacked and knockBack, then two sound-pitch floats, before
         * EntityLiving.dropLoot reads this same entity Random. */
        if (fresh) {
            (void)jrand_double(&preview);
            (void)jrand_double(&preview);
            (void)jrand_float(&preview);
            (void)jrand_float(&preview);
        }
        ewitch_generate_loot(&preview, looting_level, &preview_loot);
        if (equipped)
            preview_equipment_drop = ewitch_equipped_drop(
                &preview, looting_level);
        int required_items = preview_loot.count + preview_equipment_drop;
        if (!drops || !death_context->math_random_seed48
                || !death_context->next_entity_id
                || *death_context->next_entity_id <= 0
                || *death_context->next_entity_id
                    > INT_MAX - required_items
                || !mob_live_reserve_item_slots(drops, required_items))
            return 1;
    }

    applied = mob_absorb_damage(m, slot, applied);
    m->entity_last_damage[slot] = damage;
    if (fresh) {
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
    }
    s->health[slot] -= applied;
    if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
    mark_hurt(m, s, slot);
    m->entity_recently_hit[slot] = 100;
    m->entity_attacking_player[slot] = 1;
    if (fresh)
        player_attack_fresh_feedback(
            m, s, slot, attacker_x, attacker_z, death_context,
            thorns ? 33 : 2);

    if (lethal) {
        m->entity_dead[slot] = 1;
        m->entity_death_time[slot] = 0;
        if (death_context->do_mob_loot) {
            EwitchLootOutcome loot;
            ewitch_generate_loot(
                &m->entity_random[slot].random, looting_level, &loot);
            for (int i = 0; i < loot.count; ++i)
                (void)mob_spawn_passive_loot_item(
                    drops, death_context->next_entity_id,
                    death_context->math_random_seed48,
                    s->x[slot], s->y[slot], s->z[slot],
                    loot.item[i], loot.quantity[i], 0, 0);
            if (equipped && ewitch_equipped_drop(
                    &m->entity_random[slot].random, looting_level))
                (void)mob_spawn_passive_loot_item(
                    drops, death_context->next_entity_id,
                    death_context->math_random_seed48,
                    s->x[slot], s->y[slot], s->z[slot],
                    373, 1, witch_potion_stack_meta(
                        m->witch_potion[slot]), 0);
        }
        if (death_context->next_entity_id) {
            if (m->next_id < *death_context->next_entity_id)
                m->next_id = *death_context->next_entity_id;
            if (m->next_orb_id < *death_context->next_entity_id)
                m->next_orb_id = *death_context->next_entity_id;
        }
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 3,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    }
    return 2;
}

static int mob_player_damage_passive_slot_exact(
        GmMobLive *m, EwStore *s, int slot,
        double attacker_x, double attacker_z, float damage,
        int looting_level,
        GmLiveSim *drops, const GmMobDeathContext *death_context,
        int thorns) {
    if (!m || !s || !death_context || slot <= 0
            || slot >= EW_MAX_ENTITIES || !s->alive[slot]
            || !gm_passive(s->type[slot]) || looting_level < 0
            || m->controlled_no_ai[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || damage <= 0.0F)
        return 1;
    int fresh = m->entity_hurt_resistant[slot] <= 10;
    if (!fresh && damage <= m->entity_last_damage[slot]) {
        m->sheep_in_love[slot] = 0;
        m->sheep_bred_by_player[slot] = 0;
        return 1;
    }
    if (fresh && !death_context->math_random_seed48)
        return 1;
    float applied = fresh
        ? damage : damage - m->entity_last_damage[slot];
    applied = player_attack_after_mob_armor(
        m, slot, s->type[slot], applied);
    applied = mob_resistance_damage(m, slot, applied);
    int lethal = s->health[slot]
        <= mob_preview_absorbed_damage(m, slot, applied);
    GmPassiveLootOutcome preview = {0};
    if (lethal) {
        JavaRandom random = m->entity_random[slot].random;
        if (fresh) {
            (void)jrand_double(&random);
            (void)jrand_double(&random);
            (void)jrand_float(&random);
            (void)jrand_float(&random);
        }
        if (!mob_generate_passive_loot(
                m, s, slot, &random, looting_level, 1,
                death_context->do_mob_loot, &preview)
                || (preview.count > 0
                    && (!drops || !death_context->math_random_seed48
                        || !death_context->next_entity_id
                        || *death_context->next_entity_id <= 0
                        || *death_context->next_entity_id
                            > INT_MAX - preview.count
                        || !mob_live_reserve_item_slots(
                            drops, preview.count))))
            return 1;
    }

    m->sheep_in_love[slot] = 0;
    m->sheep_bred_by_player[slot] = 0;
    applied = mob_absorb_damage(m, slot, applied);
    m->entity_last_damage[slot] = damage;
    if (fresh) {
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
    }
    s->health[slot] -= applied;
    if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
    mark_hurt(m, s, slot);
    m->entity_recently_hit[slot] = 100;
    m->entity_attacking_player[slot] = 1;
    if (s->type[slot] == EW_TYPE_LLAMA) {
        m->llama_attack_target_eid[slot] = 0;
        m->llama_attack_target_kind[slot] = 1;
    }

    villager_player_harm_append(m, s, slot, lethal);

    if (fresh)
        player_attack_fresh_feedback(
            m, s, slot, attacker_x, attacker_z, death_context,
            thorns ? 33 : 2);

    if (lethal) {
        m->entity_dead[slot] = 1;
        m->entity_death_time[slot] = 0;
        GmPassiveLootOutcome loot;
        (void)mob_generate_passive_loot(
            m, s, slot, &m->entity_random[slot].random,
            looting_level, 1, death_context->do_mob_loot, &loot);
        (void)mob_spawn_passive_loot(
            m, s, slot, drops, death_context->math_random_seed48,
            death_context->next_entity_id, &loot);
        mob_event_append(
            m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 3,
            s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    }
    return 2;
}

static int mob_player_damage_pig_slot_exact(
        GmMobLive *m, EwStore *s, int slot,
        double attacker_x, double attacker_z, float damage,
        GmLiveSim *drops, const GmMobDeathContext *death_context) {
    if (!s || slot <= 0 || slot >= EW_MAX_ENTITIES
            || s->type[slot] != EW_TYPE_PIG)
        return 1;
    return mob_player_damage_passive_slot_exact(
        m, s, slot, attacker_x, attacker_z,
        damage, 0, drops, death_context, 0);
}

int gm_mobs_player_damage_pig_exact(
        GmMobLive *m, int eid, double attacker_x, double attacker_z,
        float damage, GmLiveSim *drops,
        const GmMobDeathContext *death_context) {
    if (!m || eid <= 0) return 0;
    EwStore *s = now_store(m);
    int slot = mob_slot_by_eid(m, eid);
    if (slot < 0 || s->type[slot] != EW_TYPE_PIG) return 0;
    int result = mob_player_damage_pig_slot_exact(
        m, s, slot, attacker_x, attacker_z,
        damage, drops, death_context);
    ew_store_copy(next_store(m), s);
    return result;
}

int gm_mobs_player_damage_witch_exact(
        GmMobLive *m, int eid, double attacker_x, double attacker_z,
        float damage, int looting_level, GmLiveSim *drops,
        const GmMobDeathContext *death_context) {
    if (!m || eid <= 0) return 0;
    EwStore *s = now_store(m);
    int slot = mob_slot_by_eid(m, eid);
    if (slot < 0 || s->type[slot] != EW_TYPE_WITCH) return 0;
    int result = mob_player_damage_witch_slot_exact(
        m, s, slot, attacker_x, attacker_z, damage,
        looting_level, drops, death_context, 0);
    ew_store_copy(next_store(m), s);
    return result;
}

int gm_mobs_falling_anvil_damage_controlled_passives(
        GmMobLive *m, int dimension, const McAABB *falling_box,
        float damage, uint64_t *math_random_seed48, GmLiveSim *drops,
        int *next_entity_id, int do_mob_loot) {
    EwStore *s;
    int accepted_count = 0;
    if (!m || !falling_box || !math_random_seed48 || damage <= 0.0F
            || (do_mob_loot && (!drops || !next_entity_id
                || *next_entity_id <= 0)))
        return 0;
    s = now_store(m);
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(m, &cursor)) > 0) {
        McAABB target_box;
        int controlled_passive;
        int ordinary_witch;
        s = now_store(m);
        controlled_passive = m->controlled_no_ai[slot]
            && (s->type[slot] == EW_TYPE_SHEEP
                || s->type[slot] == EW_TYPE_PIG
                || s->type[slot] == EW_TYPE_COW
                || s->type[slot] == EW_TYPE_MOOSHROOM
                || s->type[slot] == EW_TYPE_CHICKEN);
        ordinary_witch = !m->controlled_no_ai[slot]
            && s->type[slot] == EW_TYPE_WITCH;
        if ((!controlled_passive && !ordinary_witch)
                || (s->type[slot] != EW_TYPE_SHEEP
                    && s->type[slot] != EW_TYPE_PIG
                    && s->type[slot] != EW_TYPE_COW
                    && s->type[slot] != EW_TYPE_MOOSHROOM
                    && s->type[slot] != EW_TYPE_CHICKEN
                    && s->type[slot] != EW_TYPE_WITCH)
                || m->entity_dead[slot] || s->health[slot] <= 0.0F
                || !living_box_at(m, s, dimension, slot, &target_box)
                || !mc_aabb_intersects(falling_box, &target_box))
            continue;
        if (ordinary_witch) {
            if (mob_source_damage_witch_slot_exact(
                    m, s, slot, damage, drops, math_random_seed48,
                    next_entity_id, do_mob_loot, 0, NULL) > 0)
                ++accepted_count;
            continue;
        }
        if (mob_source_damage_passive_slot_exact(
                m, s, slot, damage, drops, math_random_seed48,
                next_entity_id, do_mob_loot, 0, 1, 0, NULL) > 0)
            ++accepted_count;
    }
    gm_mobs_living_cold_flush(m);
    return accepted_count;
}

static int boat_box_at(
        const GmMobLive *m, const EwStore *s, int dimension,
        int slot, McAABB *out) {
    if (!s->alive[slot] || m->entity_dimension[slot] != dimension
            || s->type[slot] != EW_TYPE_BOAT)
        return 0;
    float width, height;
    ehs_size(EW_TYPE_BOAT, &width, &height);
    double half = (double)width * 0.5;
    *out = mc_aabb_make(
        s->x[slot] - half, s->y[slot], s->z[slot] - half,
        s->x[slot] + half, s->y[slot] + (double)height,
        s->z[slot] + half);
    return 1;
}

int gm_mobs_living_boxes(
        const GmMobLive *m, int dimension, McAABB *out, int capacity) {
    if (!m || !out || capacity <= 0) return 0;
    GmMobLive *mutable_m = (GmMobLive *)m;
    int count = 0;
    int cursor = 0, i;
    while (count < capacity
            && (i = gm_mobs_living_next_slot(mutable_m, &cursor)) > 0)
        if (living_box_at(m, const_store(m), dimension, i, &out[count]))
            ++count;
    gm_mobs_living_cold_flush(mutable_m);
    return count;
}

int gm_mobs_explosion_targets(
        const GmMobLive *m, int dimension,
        GmMobExplosionTarget *out, int capacity) {
    if (!m || !out || capacity <= 0) return 0;
    GmMobLive *mutable_m = (GmMobLive *)m;
    int count = 0;
    int cursor = 0, slot;
    while (count < capacity
            && (slot = gm_mobs_living_next_slot(mutable_m, &cursor)) > 0) {
        const EwStore *s = const_store(m);
        McAABB box;
        float width, height;
        GmMobExplosionTarget *target;
        if (!s->alive[slot] || m->entity_dimension[slot] != dimension
                || !gm_living(s->type[slot]))
            continue;
        if (s->type[slot] == EW_TYPE_BOAT) {
            if (!boat_box_at(m, s, dimension, slot, &box)) continue;
            ehs_size(EW_TYPE_BOAT, &width, &height);
        } else {
            if (!living_box_at(m, s, dimension, slot, &box)) continue;
            ehs_size_scaled(
                s->type[slot], m->size[slot], &width, &height);
        }
        (void)width;
        target = &out[count++];
        memset(target, 0, sizeof *target);
        target->slot = slot;
        target->eid = s->id[slot];
        target->type = s->type[slot];
        target->x = s->x[slot];
        target->y = s->y[slot];
        target->z = s->z[slot];
        target->vx = s->vx[slot];
        target->vy = s->vy[slot];
        target->vz = s->vz[slot];
        target->health = s->health[slot];
        target->eye_height = height * 0.85F;
        target->hurt_time = m->entity_hurt_time[slot];
        target->hurt_resistant_time = m->entity_hurt_resistant[slot];
        target->box = box;
    }
    gm_mobs_living_cold_flush(mutable_m);
    return count;
}

float gm_mobs_eye_height_at(const GmMobLive *m, int slot) {
    const EwStore *s;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES) return 0.0F;
    s = const_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0.0F;
    return mob_eye_height(m, s, slot);
}

int gm_mobs_apply_explosion(
        GmMobLive *m, int slot, float damage,
        double impulse_x, double impulse_y, double impulse_z,
        GmLiveSim *drops) {
    EwStore *s;
    float applied;
    int accepted = 1;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES || damage <= 0.0F
            || !isfinite(impulse_x) || !isfinite(impulse_y)
            || !isfinite(impulse_z))
        return 0;
    s = now_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot]))
        return 0;
    if (s->type[slot] == EW_TYPE_BOAT) {
        m->boat_damage[slot] += damage * 10.0F;
        if (m->boat_damage[slot] > 40.0F)
            mob_drop(m, s, slot, drops);
        if (s->alive[slot]) {
            s->vx[slot] += impulse_x;
            s->vy[slot] += impulse_y;
            s->vz[slot] += impulse_z;
        }
        ew_store_copy(next_store(m), s);
        return 2;
    }
    if (s->type[slot] == EW_TYPE_BAT && m->bat_hanging[slot])
        m->bat_hanging[slot] = 0;
    if (m->entity_hurt_resistant[slot] > 10) {
        if (damage <= m->entity_last_damage[slot]) {
            accepted = 0;
            applied = 0.0F;
        } else {
            applied = damage - m->entity_last_damage[slot];
            m->entity_last_damage[slot] = damage;
        }
    } else {
        applied = damage;
        m->entity_last_damage[slot] = damage;
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
    }
    if (accepted) {
        applied = mob_resistance_damage(m, slot, applied);
        applied = mob_absorb_damage(m, slot, applied);
        s->health[slot] -= applied;
        if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
        mark_hurt(m, s, slot);
        if (s->health[slot] <= 0.0F && !m->controlled_no_ai[slot])
            mob_drop(m, s, slot, drops);
    }
    if (s->alive[slot]) {
        s->vx[slot] += impulse_x;
        s->vy[slot] += impulse_y;
        s->vz[slot] += impulse_z;
    }
    ew_store_copy(next_store(m), s);
    return accepted ? 2 : 1;
}

int gm_mobs_creeper_is_powered(
        const GmMobLive *m, int eid, int *powered) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = const_store(m);
    if (slot < 0 || s->type[slot] != EW_TYPE_CREEPER)
        return 0;
    if (powered) *powered = m->creeper_powered[slot] ? 1 : 0;
    return 1;
}

int gm_mobs_lightning_strike(
        GmMobLive *m, int dimension, const McAABB *box,
        GmLiveSim *drops, int *next_entity_id) {
    int *eids;
    int count = 0;
    EwStore *s;
    if (!m || !box || !next_entity_id)
        return 0;
    eids = (int *)malloc(
        (size_t)(GM_MOB_CAPACITY + m->living_cold_count) * sizeof *eids);
    if (!eids) return 0;
    s = now_store(m);
    /* World.getEntitiesWithinAABBExcludingEntity snapshots before callbacks;
     * a pigman created by a pig callback is not struck by this same flash. */
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(m, &cursor)) > 0) {
        McAABB entity_box;
        s = now_store(m);
        if (living_box_at(m, s, dimension, slot, &entity_box)
                && mc_aabb_intersects(&entity_box, box))
            eids[count++] = s->id[slot];
    }
    gm_mobs_living_cold_flush(m);
    for (int index = 0; index < count; ++index) {
        int slot = mob_slot_by_eid(m, eids[index]);
        int type;
        s = now_store(m);
        if (slot <= 0 || !s->alive[slot]) continue;
        type = s->type[slot];
        if (type == EW_TYPE_PIG) {
            double x = s->x[slot], y = s->y[slot], z = s->z[slot];
            float yaw = s->yaw[slot];
            int no_ai = m->controlled_no_ai[slot];
            int new_eid = (*next_entity_id)++;
            int new_is_cold = 0;
            retire_terminal_living(m, s, slot);
            int new_slot = living_spawn_slot(
                m, s, EW_TYPE_PIGMAN, new_eid, x, y, z,
                max_health(EW_TYPE_PIGMAN, 1), &new_is_cold);
            if (new_slot >= 0) {
                s->yaw[new_slot] = yaw;
                m->entity_dimension[new_slot] = (signed char)dimension;
                m->size[new_slot] = 1;
                reset_slot_state_s(m, s, new_slot);
                m->controlled_no_ai[new_slot] = (unsigned char)no_ai;
                (void)living_spawn_finish(
                    m, s, new_slot, new_is_cold, 0);
                if (m->next_id <= new_eid) m->next_id = new_eid + 1;
            }
            continue;
        }
        if (gm_living(type) && !m->entity_dead[slot]
                && s->health[slot] > 0.0F) {
            if (type == EW_TYPE_BAT && m->bat_hanging[slot])
                m->bat_hanging[slot] = 0;
            float raw = 5.0F;
            float applied;
            int accepted = 1;
            if (m->entity_hurt_resistant[slot] > 10) {
                if (raw <= m->entity_last_damage[slot]) {
                    accepted = 0;
                    applied = 0.0F;
                } else {
                    applied = raw - m->entity_last_damage[slot];
                    m->entity_last_damage[slot] = raw;
                }
            } else {
                applied = raw;
                m->entity_last_damage[slot] = raw;
                m->entity_hurt_resistant[slot] = 20;
                m->entity_hurt_time[slot] = 10;
            }
            if (accepted) {
                applied = player_attack_after_mob_armor(
                    m, slot, type, applied);
                applied = mob_resistance_damage(m, slot, applied);
                applied = mob_absorb_damage(m, slot, applied);
                s->health[slot] -= applied;
                if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
                mark_hurt(m, s, slot);
                if (s->health[slot] <= 0.0F
                        && !m->controlled_no_ai[slot])
                    mob_drop(m, s, slot, drops);
            }
            if (s->alive[slot]) {
                ++m->fire_ticks[slot];
                if (m->fire_ticks[slot] == 0)
                    m->fire_ticks[slot] = 8 * 20;
                if (type == EW_TYPE_CREEPER)
                    m->creeper_powered[slot] = 1;
            }
        }
    }
    free(eids);
    gm_mobs_living_cold_flush(m);
    s = now_store(m);
    ew_store_copy(next_store(m), s);
    return count;
}

static int mob_is_undead(int type) {
    return gm_zombie(type) || type == EW_TYPE_SKELETON
        || type == EW_TYPE_PIGMAN || type == EW_TYPE_WITHER_SKELETON
        || type == EW_TYPE_SKELETON_HORSE
        || type == EW_TYPE_ZOMBIE_HORSE;
}

int gm_mobs_add_potion_effect_flags(
        GmMobLive *m, int slot, int potion_id,
        int amplifier, int duration,
        int ambient, int show_particles) {
    const EwStore *s;
    int count;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES
            || potion_id <= 0 || potion_id > 27
            || amplifier < 0 || amplifier > 255 || duration <= 0
            || (ambient != 0 && ambient != 1)
            || (show_particles != 0 && show_particles != 1))
        return 0;
    s = const_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0;
    if (mob_is_undead(s->type[slot])
            && (potion_id == 10 || potion_id == 19))
        return 0;
    count = m->entity_effect_count[slot];
    for (int i = 0; i < count; ++i)
        if (m->entity_effects[slot][i].id == potion_id) {
            mob_effect_combine_at(
                m, slot, i, duration, amplifier,
                ambient, show_particles);
            if (potion_id == 22) {
                float grant = pt_effect_health_boost(
                    0.0F, m->entity_effects[slot][i].amplifier);
                m->entity_absorption[slot] -= grant;
                if (m->entity_absorption[slot] < 0.0F)
                    m->entity_absorption[slot] = 0.0F;
                m->entity_absorption[slot] += grant;
            }
            return 1;
        }
    if (count >= GM_MOB_EFFECT_CAPACITY) return 0;
    m->entity_effects[slot][count].id = potion_id;
    m->entity_effects[slot][count].duration = duration;
    m->entity_effects[slot][count].amplifier = amplifier;
    m->entity_effect_flags[slot][count] = (unsigned char)(
        (ambient ? 1 : 0) | (show_particles ? 0 : 2));
    m->entity_effect_count[slot] = (unsigned char)(count + 1);
    if (potion_id == 22)
        m->entity_absorption[slot] +=
            pt_effect_health_boost(0.0F, amplifier);
    return 1;
}

int gm_mobs_add_potion_effect(
        GmMobLive *m, int slot, int potion_id,
        int amplifier, int duration) {
    return gm_mobs_add_potion_effect_flags(
        m, slot, potion_id, amplifier, duration, 0, 1);
}

int gm_mobs_apply_potion_effect(
        GmMobLive *m, int slot, int potion_id,
        int amplifier, int duration) {
    if (potion_id == 6 || potion_id == 7) return 0;
    return gm_mobs_add_potion_effect(
        m, slot, potion_id, amplifier, duration);
}

int gm_mobs_potion_effect_count(const GmMobLive *m, int slot) {
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES) return 0;
    return m->entity_effect_count[slot];
}

int gm_mobs_potion_effect_get(
        const GmMobLive *m, int slot, int index, PtMobEffect *out) {
    if (!m || !out || slot <= 0 || slot >= EW_MAX_ENTITIES
            || index < 0 || index >= m->entity_effect_count[slot])
        return 0;
    *out = m->entity_effects[slot][index];
    return 1;
}

int gm_mobs_potion_effect_flags(
        const GmMobLive *m, int slot, int index,
        int *ambient, int *show_particles) {
    unsigned char flags;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES
            || index < 0 || index >= m->entity_effect_count[slot])
        return 0;
    flags = m->entity_effect_flags[slot][index];
    if (ambient) *ambient = (flags & 1u) != 0;
    if (show_particles) *show_particles = (flags & 2u) == 0;
    return 1;
}

float gm_mobs_max_health(const GmMobLive *m, int slot) {
    const EwStore *s;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES) return 0.0F;
    s = const_store(m);
    if (!s->alive[slot] || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0.0F;
    return mob_max_health(m, slot, s->type[slot]);
}

float gm_mobs_absorption(const GmMobLive *m, int slot) {
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES) return 0.0F;
    return m->entity_absorption[slot];
}

int gm_mobs_air(const GmMobLive *m, int slot) {
    const EwStore *s;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES) return 0;
    s = const_store(m);
    if (!s->alive[slot] || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0;
    return m->entity_air[slot];
}

int gm_mobs_set_air(GmMobLive *m, int eid, int air) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (slot <= 0 || !s || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT
            || air < -20 || air > 300)
        return 0;
    m->entity_air[slot] = air;
    return 1;
}

int gm_mobs_apply_instant_potion(
        GmMobLive *m, int slot, int potion_id, int amplifier,
        double factor, GmLiveSim *drops) {
    EwStore *s;
    int delta;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES
            || amplifier < 0 || factor < 0.0 || !isfinite(factor))
        return 0;
    s = now_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0;
    delta = pt_instant_health_delta(
        potion_id, amplifier, factor, mob_is_undead(s->type[slot]));
    if (delta < 0)
        return gm_mobs_apply_explosion(
            m, slot, (float)-delta, 0.0, 0.0, 0.0, drops);
    if (delta > 0) {
        s->health[slot] += (float)delta;
        if (s->health[slot] > mob_max_health(m, slot, s->type[slot]))
            s->health[slot] = mob_max_health(m, slot, s->type[slot]);
        ew_store_copy(next_store(m), s);
    }
    return 2;
}

int gm_mobs_apply_instant_potion_indirect(
        GmMobLive *m, GmWorld *world, int slot,
        int potion_id, int amplifier, double factor,
        const GmMobPotionDamageOwner *owner,
        GmLiveSim *drops, const GmMobDeathContext *death_context) {
    EwStore *s;
    int delta, accepted;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES
            || amplifier < 0 || factor < 0.0 || !isfinite(factor)
            || (owner && (owner->eid < 0
                || (owner->is_player != 0 && owner->is_player != 1)
                || owner->looting_level < 0
                || !isfinite(owner->x) || !isfinite(owner->z))))
        return 0;
    s = now_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0;
    delta = pt_instant_health_delta(
        potion_id, amplifier, factor, mob_is_undead(s->type[slot]));
    if (delta >= 0) {
        if (delta > 0) {
            s->health[slot] += (float)delta;
            if (s->health[slot] > mob_max_health(m, slot, s->type[slot]))
                s->health[slot] = mob_max_health(m, slot, s->type[slot]);
            ew_store_copy(next_store(m), s);
        }
        return 2;
    }
    if (!death_context || !death_context->math_random_seed48)
        return 0;

    /* EntityEnderman intercepts every indirect source before the ordinary
     * living damage path, including ownerless lingering clouds. */
    if (s->type[slot] == EW_TYPE_ENDERMAN) {
        if (!world) return 0;
        for (int attempt = 0; attempt < 64; ++attempt)
            if (mob_attempt_enderman_random_teleport(
                    m, world, s, slot)) {
                ew_store_copy(next_store(m), s);
                return 3;
            }
        ew_store_copy(next_store(m), s);
        return 1;
    }

    /* EntityLivingBase touches these fields before the hurt-immunity return. */
    m->entity_age[slot] = 0;
    m->entity_limb_swing_amount[slot] = 1.5F;
    if (s->type[slot] == EW_TYPE_PIG)
        m->pig_limb_amount[slot] = 1.5F;

    GmMobDamageEntitySource entity_source = {
        owner ? owner->x : 0.0,
        owner ? owner->z : 0.0,
        death_context,
        owner ? owner->eid : -1,
        owner ? owner->is_player : 0,
        owner ? owner->looting_level : 0,
        1,
        owner != NULL,
    };
    const GmMobDamageEntitySource *source = &entity_source;
    accepted = s->type[slot] == EW_TYPE_WITCH
        ? mob_source_damage_witch_slot_exact(
            m, s, slot, (float)-delta, drops,
            death_context->math_random_seed48,
            death_context->next_entity_id,
            death_context->do_mob_loot, 0, source)
        : gm_passive(s->type[slot])
        ? mob_source_damage_passive_slot_exact(
            m, s, slot, (float)-delta, drops,
            death_context->math_random_seed48,
            death_context->next_entity_id,
            death_context->do_mob_loot, 0, 1, 1, source)
        : mob_source_damage_ordinary_slot_exact(
            m, s, slot, (float)-delta, drops,
            death_context->math_random_seed48,
            death_context->next_entity_id,
            death_context->do_mob_loot, 0, 1, 1, source);
    ew_store_copy(next_store(m), s);
    return accepted < 0 ? 0 : accepted ? 2 : 1;
}

int gm_mobs_apply_water_potion(
        GmMobLive *m, GmWorld *w, int slot, GmLiveSim *drops,
        uint64_t *math_random_seed48) {
    EwStore *s;
    if (!m || !w || slot <= 0 || slot >= EW_MAX_ENTITIES) return 0;
    s = now_store(m);
    if (!s->alive[slot] || (s->type[slot] != EW_TYPE_BLAZE
            && s->type[slot] != EW_TYPE_ENDERMAN))
        return 0;
    if (s->type[slot] == EW_TYPE_ENDERMAN) {
        int accepted = mob_source_damage_living_nonlethal_exact(
            m, s, slot, 1.0F, math_random_seed48, 0);
        int teleported = mob_try_enderman_random_teleport(
            m, w, s, slot);
        ew_store_copy(next_store(m), s);
        return accepted || teleported ? 2 : 1;
    }
    return gm_mobs_apply_explosion(
        m, slot, 1.0F, 0.0, 0.0, 0.0, drops);
}

int gm_mobs_zombie_villager_can_cure(
        const GmMobLive *m, int eid, const ICStack *held) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    return slot > 0 && held && held->item == 322 && held->meta == 0
        && held->count > 0 && s->alive[slot]
        && s->type[slot] == EW_TYPE_ZOMBIE_VILLAGER
        && mob_effect_amplifier(m, slot, 18) >= 0;
}

int gm_mobs_cure_zombie_villager(
        GmMobLive *m, int eid, IsrInv *inventory,
        int hand_slot, int creative) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s;
    ICStack held;
    if (!m || !inventory || slot <= 0
            || (creative != 0 && creative != 1))
        return 0;
    s = now_store(m);
    held = isr_get_stack(inventory, hand_slot);
    if (!gm_mobs_zombie_villager_can_cure(m, eid, &held)) return 0;
    if (!creative)
        (void)isr_decr_stack_size(inventory, hand_slot, 1);
    int conversion = jrand_int_bound(
        &m->entity_random[slot].random, 2401) + 3600;
    mob_remove_effect(m, slot, 18);
    (void)witch_queue_effect(m, slot, 5, 0, conversion);
    m->zombie_villager_conversion_time[slot] = conversion;
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 16,
        s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    ew_store_copy(next_store(m), s);
    return 1;
}

int gm_mobs_zombie_villager_cure_audio(
        GmMobLive *m, int eid, double *x, double *y, double *z,
        float *volume, float *pitch) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (!m || slot <= 0 || !s->alive[slot]
            || s->type[slot] != EW_TYPE_ZOMBIE_VILLAGER)
        return 0;
    JavaRandom *random = &m->entity_server_random[slot].random;
    float sound_volume = 1.0F + jrand_float(random);
    float sound_pitch = jrand_float(random) * 0.7F + 0.3F;
    if (x) *x = s->x[slot] + 0.5D;
    if (y) *y = s->y[slot] + 0.5D;
    if (z) *z = s->z[slot] + 0.5D;
    if (volume) *volume = sound_volume;
    if (pitch) *pitch = sound_pitch;
    return 1;
}

int gm_mobs_zombie_villager_conversion_progress(
        GmMobLive *m, GmWorld *w, int eid) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (!m || !w || slot <= 0 || !s->alive[slot]
            || s->type[slot] != EW_TYPE_ZOMBIE_VILLAGER)
        return 0;
    return zombie_villager_conversion_progress_slot(m, w, s, slot);
}

int gm_mobs_zombie_villager_conversion_state(
        const GmMobLive *m, int eid, int *conversion_time) {
    int slot = mob_slot_by_eid(m, eid);
    const EwStore *s = m ? const_store(m) : NULL;
    if (!m || slot <= 0 || !s->alive[slot]
            || s->type[slot] != EW_TYPE_ZOMBIE_VILLAGER)
        return 0;
    if (conversion_time)
        *conversion_time = m->zombie_villager_conversion_time[slot];
    return m->zombie_villager_conversion_time[slot] >= 0;
}

int gm_mobs_zombie_villager_finish_conversion(
        GmMobLive *m, int eid, int *next_entity_id) {
    int slot = mob_slot_by_eid(m, eid);
    EwStore *s = m ? now_store(m) : NULL;
    if (!m || slot <= 0) return 0;
    int new_eid = zombie_villager_finish_slot(
        m, s, slot, next_entity_id);
    if (new_eid > 0) ew_store_copy(next_store(m), s);
    return new_eid;
}

int gm_mobs_take_zombie_villager_world_event(
        GmMobLive *m, int *x, int *y, int *z) {
    if (!m) return 0;
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(m, &cursor)) > 0) {
        if (!m->zombie_villager_world_event_pending[slot]) continue;
        m->zombie_villager_world_event_pending[slot] = 0;
        if (x) *x = m->zombie_villager_world_event_x[slot];
        if (y) *y = m->zombie_villager_world_event_y[slot];
        if (z) *z = m->zombie_villager_world_event_z[slot];
        gm_mobs_living_cold_flush(m);
        return 1;
    }
    gm_mobs_living_cold_flush(m);
    return 0;
}

int gm_mobs_collision_boxes(
        const GmMobLive *m, int dimension, int controlled_only,
        McAABB *out, int capacity) {
    if (!m || !out || capacity <= 0) return 0;
    GmMobLive *mutable_m = (GmMobLive *)m;
    int count = 0;
    int cursor = 0, i;
    while (count < capacity
            && (i = gm_mobs_living_next_slot(mutable_m, &cursor)) > 0) {
        if (controlled_only && !m->controlled_block_collisions[i])
            continue;
        if (living_box_at(m, const_store(m), dimension, i, &out[count]))
            ++count;
    }
    gm_mobs_living_cold_flush(mutable_m);
    return count;
}

int gm_mobs_trigger_collision_boxes(
        const GmMobLive *m, int dimension, int controlled_only,
        McAABB *out, int capacity) {
    if (!m || !out || capacity <= 0) return 0;
    GmMobLive *mutable_m = (GmMobLive *)m;
    int count = 0;
    int cursor = 0, i;
    while (count < capacity
            && (i = gm_mobs_living_next_slot(mutable_m, &cursor)) > 0) {
        if (controlled_only && !m->controlled_block_collisions[i])
            continue;
        if (living_box_at(m, const_store(m), dimension, i, &out[count])
                || boat_box_at(m, const_store(m), dimension, i, &out[count]))
            ++count;
    }
    gm_mobs_living_cold_flush(mutable_m);
    return count;
}

int gm_mobs_living_intersects_aabb(
        const GmMobLive *m, int dimension, const McAABB *box) {
    return gm_mobs_living_count_intersects_aabb(m, dimension, box) > 0;
}

int gm_mobs_living_count_intersects_aabb(
        const GmMobLive *m, int dimension, const McAABB *box) {
    if (!m || !box) return 0;
    GmMobLive *mutable_m = (GmMobLive *)m;
    int count = 0;
    int cursor = 0, i;
    while ((i = gm_mobs_living_next_slot(mutable_m, &cursor)) > 0) {
        McAABB entity;
        if (!living_box_at(m, const_store(m), dimension, i, &entity))
            continue;
        if (entity.maxX > box->minX && entity.minX < box->maxX
                && entity.maxY > box->minY && entity.minY < box->maxY
                && entity.maxZ > box->minZ && entity.minZ < box->maxZ)
            ++count;
    }
    gm_mobs_living_cold_flush(mutable_m);
    return count;
}

int gm_mobs_boat_count_intersects_aabb(
        const GmMobLive *m, int dimension, const McAABB *box) {
    if (!m || !box) return 0;
    GmMobLive *mutable_m = (GmMobLive *)m;
    int count = 0;
    int cursor = 0, i;
    while ((i = gm_mobs_living_next_slot(mutable_m, &cursor)) > 0) {
        McAABB entity;
        if (!boat_box_at(m, const_store(m), dimension, i, &entity))
            continue;
        if (entity.maxX > box->minX && entity.minX < box->maxX
                && entity.maxY > box->minY && entity.minY < box->maxY
                && entity.maxZ > box->minZ && entity.minZ < box->maxZ)
            ++count;
    }
    gm_mobs_living_cold_flush(mutable_m);
    return count;
}

int gm_mobs_xp_collision_boxes(
        const GmMobLive *m, McAABB *out, int capacity) {
    if (!m || !out || capacity <= 0) return 0;
    int count = 0;
    for (int slot = 0;
            slot < xp_slot_limit(m) && count < capacity; ++slot) {
        const McOrb *orb = xp_orb_at_const(m, slot);
        if (orb->dead || orb->xpValue <= 0
                || *xp_dimension_at((GmMobLive *)m, slot)
                    != m->active_dimension)
            continue;
        out[count++] = orb->box;
    }
    return count;
}

int gm_mobs_xp_count_intersects_aabb(
        const GmMobLive *m, int dimension, const McAABB *box) {
    if (!m || !box) return 0;
    int count = 0;
    for (int i = 0; i < xp_slot_limit(m); ++i) {
        const McOrb *orb = xp_orb_at_const(m, i);
        if (orb->dead || orb->xpValue <= 0
                || *xp_dimension_at((GmMobLive *)m, i) != dimension)
            continue;
        if (orb->box.maxX > box->minX && orb->box.minX < box->maxX
                && orb->box.maxY > box->minY && orb->box.minY < box->maxY
                && orb->box.maxZ > box->minZ && orb->box.minZ < box->maxZ)
            ++count;
    }
    return count;
}

int gm_mobs_any_intersects_aabb(
        const GmMobLive *m, int dimension, const McAABB *box) {
    if (!m || !box) return 0;
    if (gm_mobs_living_count_intersects_aabb(m, dimension, box) > 0
            || gm_mobs_boat_count_intersects_aabb(m, dimension, box) > 0
            || gm_mobs_xp_count_intersects_aabb(m, dimension, box) > 0)
        return 1;
    for (int i = 0; i < m->evoker_fang_count; ++i) {
        const GmEvokerFang *fang = &m->evoker_fangs[i];
        McAABB fang_box;
        if (!fang->active || fang->dimension != dimension)
            continue;
        fang_box = mc_aabb_make(
            fang->x - (double)0.25F, fang->y,
            fang->z - (double)0.25F,
            fang->x + (double)0.25F, fang->y + (double)0.8F,
            fang->z + (double)0.25F);
        if (fang_box.maxX > box->minX && fang_box.minX < box->maxX
                && fang_box.maxY > box->minY
                && fang_box.minY < box->maxY
                && fang_box.maxZ > box->minZ
                && fang_box.minZ < box->maxZ)
            return 1;
    }
    return 0;
}

int gm_mobs_farmland_lift_intersecting(
        GmMobLive *m, int dimension, const McAABB *box, double top_y) {
    EwStore *s;
    int count = 0;
    if (!m || !box || !isfinite(top_y)) return 0;
    int cursor = 0, slot;
    while ((slot = gm_mobs_living_next_slot(m, &cursor)) > 0) {
        McAABB entity;
        s = now_store(m);
        if (!s->alive[slot]
                || m->entity_dimension[slot] != dimension
                || !gm_living(s->type[slot])
                || !mob_slot_world_box(m, s, slot, &entity)
                || !(entity.maxX > box->minX
                    && entity.minX < box->maxX
                    && entity.maxY > box->minY
                    && entity.minY < box->maxY
                    && entity.maxZ > box->minZ
                    && entity.minZ < box->maxZ))
            continue;
        s->y[slot] = top_y;
        /* setPosition rebuilds the ordinary size-derived box. A later
         * collision query does the same when this exact-box override is off. */
        m->entity_box_valid[slot] = 0;
        ++count;
    }
    gm_mobs_living_cold_flush(m);
    s = now_store(m);
    ew_store_copy(next_store(m), s);
    for (int slot = 0; slot < xp_slot_limit(m); ++slot) {
        McOrb *orb = xp_orb_at(m, slot);
        if (orb->dead || orb->xpValue <= 0
                || *xp_dimension_at(m, slot) != dimension
                || !(orb->box.maxX > box->minX
                    && orb->box.minX < box->maxX
                    && orb->box.maxY > box->minY
                    && orb->box.minY < box->maxY
                    && orb->box.maxZ > box->minZ
                    && orb->box.minZ < box->maxZ))
            continue;
        eo_set_position(orb, orb->posX, top_y, orb->posZ);
        ++count;
    }
    return count;
}

int gm_mobs_projectile_intercept(
        const GmMobLive *m, int dimension, int shooter_eid,
        int include_shooter, double sx, double sy, double sz,
        double ex, double ey, double ez, int *slot, double *distance_sq) {
    if (!m) return 0;
    GmMobLive *mutable_m = (GmMobLive *)m;
    const EwStore *s;
    const double expand = 0.30000001192092896;
    int cursor = 0;
    int best_eid = -1;
    double best_dist = 0.0;
    int i;
    while ((i = gm_mobs_living_next_slot(mutable_m, &cursor)) > 0) {
        float width, height;
        double half, hx, hy, hz, dx, dy, dz, dist;
        int side;
        McAABB box;
        s = const_store(m);
        if (!s->alive[i] || m->entity_dimension[i] != dimension
                || !gm_living(s->type[i]))
            continue;
        if (!include_shooter && shooter_eid > 0 && s->id[i] == shooter_eid)
            continue;
        ehs_size_scaled(s->type[i], m->size[i], &width, &height);
        half = (double)width * 0.5;
        box = mc_aabb_make(
            s->x[i] - half - expand, s->y[i] - expand,
            s->z[i] - half - expand, s->x[i] + half + expand,
            s->y[i] + (double)height + expand,
            s->z[i] + half + expand);
        if (!pm_aabb_intercept(
                &box, sx, sy, sz, ex, ey, ez,
                &hx, &hy, &hz, &side))
            continue;
        dx = hx - sx; dy = hy - sy; dz = hz - sz;
        dist = dx * dx + dy * dy + dz * dz;
        if (best_eid >= 0 && !(dist < best_dist))
            continue;
        best_eid = s->id[i];
        best_dist = dist;
    }
    gm_mobs_living_cold_flush(mutable_m);
    int best_slot = mob_slot_by_eid(m, best_eid);
    if (best_slot < 0) return 0;
    if (slot) *slot = best_slot;
    if (distance_sq) *distance_sq = best_dist;
    return 1;
}

int gm_mobs_player_arrow_hit(
        GmMobLive *m, GmWorld *world, int slot,
        double shooter_x, double shooter_z, float damage,
        int knockback, double arrow_vx, double arrow_vz, int burning,
        int looting_level, GmLiveSim *drops,
        const GmMobDeathContext *death_context) {
    EwStore *s;
    int accepted;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES || damage <= 0.0F
            || knockback < 0 || looting_level < 0)
        return 0;
    s = now_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0;

    /* EntityEnderman handles an indirect source before EntityLivingBase. It
     * makes up to 64 direct teleport attempts, accepts the hit on the first
     * success, and never receives damage or Flame fire. */
    if (s->type[slot] == EW_TYPE_ENDERMAN) {
        for (int attempt = 0; attempt < 64; ++attempt)
            if (mob_attempt_enderman_random_teleport(
                    m, world, s, slot)) {
                ew_store_copy(next_store(m), s);
                return 3;
            }
        ew_store_copy(next_store(m), s);
        return 1;
    }

    if (burning && m->fire_ticks[slot] < 5 * 20)
        m->fire_ticks[slot] = 5 * 20;
    player_attack_target_pre_damage(m, s, slot);
    if ((gm_passive(s->type[slot])
                || s->type[slot] == EW_TYPE_WITCH
                || mob_exact_ordinary_death_type(s->type[slot]))
            && !m->controlled_no_ai[slot] && death_context) {
        accepted = gm_passive(s->type[slot])
            ? mob_player_damage_passive_slot_exact(
                m, s, slot, shooter_x, shooter_z, damage,
                looting_level, drops, death_context, 0) == 2
            : s->type[slot] == EW_TYPE_WITCH
            ? mob_player_damage_witch_slot_exact(
                m, s, slot, shooter_x, shooter_z, damage,
                looting_level, drops, death_context, 0) == 2
            : mob_player_damage_hostile_slot_exact(
                m, s, slot, shooter_x, shooter_z, damage,
                looting_level, drops, death_context, 0) == 2;
    } else {
        float applied = damage;
        int fresh = m->entity_hurt_resistant[slot] <= 10;
        accepted = 1;
        if (!fresh) {
            if (damage <= m->entity_last_damage[slot]) {
                accepted = 0;
            } else {
                applied -= m->entity_last_damage[slot];
                m->entity_last_damage[slot] = damage;
            }
        } else {
            m->entity_last_damage[slot] = damage;
            m->entity_hurt_resistant[slot] = 20;
            m->entity_hurt_time[slot] = 10;
        }
        if (accepted) {
            applied = player_attack_after_mob_armor(
                m, slot, s->type[slot], applied);
            applied = mob_resistance_damage(m, slot, applied);
            applied = mob_absorb_damage(m, slot, applied);
            s->health[slot] -= applied;
            if (s->health[slot] < 0.0F) s->health[slot] = 0.0F;
            mark_hurt(m, s, slot);
            m->entity_recently_hit[slot] = 100;
            m->entity_attacking_player[slot] = 1;
            if (fresh)
                player_attack_fresh_feedback(
                    m, s, slot, shooter_x, shooter_z,
                    death_context, 2);
            if (s->health[slot] <= 0.0F && !m->controlled_no_ai[slot])
                mob_drop(m, s, slot, drops);
        }
    }
    if (!accepted) {
        ew_store_copy(next_store(m), s);
        return 1;
    }

    ++m->arrow_count[slot];
    if (knockback > 0) {
        float horizontal = (float)sqrt(
            arrow_vx * arrow_vx + arrow_vz * arrow_vz);
        if (horizontal > 0.0F) {
            s->vx[slot] += arrow_vx * (double)knockback
                * 0.6000000238418579D / (double)horizontal;
            s->vy[slot] += 0.1D;
            s->vz[slot] += arrow_vz * (double)knockback
                * 0.6000000238418579D / (double)horizontal;
        }
    }
    ew_store_copy(next_store(m), s);
    return 2;
}

int gm_mobs_player_throwable_hit(
        GmMobLive *m, GmWorld *world, int slot,
        double thrower_x, double thrower_z, float damage,
        GmLiveSim *drops, const GmMobDeathContext *death_context) {
    EwStore *s;
    int result;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES || damage < 0.0F)
        return 0;
    s = now_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0;

    /* EntityEnderman handles an indirect source before EntityLivingBase, so
     * even a zero-damage snowball/egg attempts up to 64 teleports and does
     * not touch ordinary hurt state. */
    if (damage == 0.0F && s->type[slot] == EW_TYPE_ENDERMAN) {
        for (int attempt = 0; attempt < 64; ++attempt)
            if (mob_attempt_enderman_random_teleport(
                    m, world, s, slot)) {
                ew_store_copy(next_store(m), s);
                return 3;
            }
        ew_store_copy(next_store(m), s);
        return 1;
    }

    /* EntityLivingBase resets despawn age before its hurt-resistance gate.
     * The ordinary positive-damage boundary already owns armor, effects,
     * loot, death, feedback, and Enderman behavior. Remove its arrow-only
     * stuck-projectile accounting after a successful thrown hit. */
    m->entity_age[slot] = 0;
    m->entity_limb_swing_amount[slot] = 1.5F;
    if (s->type[slot] == EW_TYPE_PIG)
        m->pig_limb_amount[slot] = 1.5F;
    if (damage > 0.0F) {
        result = gm_mobs_player_arrow_hit(
            m, world, slot, thrower_x, thrower_z, damage,
            0, 0.0, 0.0, 0, 0, drops, death_context);
        if (result == 2 && m->arrow_count[slot] > 0)
            --m->arrow_count[slot];
        return result;
    }

    /* amount==0 still traverses EntityLivingBase.attackEntityFrom. A target
     * in the second half of maxHurtResistantTime rejects it; a fresh target
     * receives the normal status, revenge, knockback, and hurt-sound RNG. */
    player_attack_target_pre_damage(m, s, slot);
    if (m->entity_hurt_resistant[slot] > 10
            && damage <= m->entity_last_damage[slot]) {
        ew_store_copy(next_store(m), s);
        return 1;
    }
    if (!death_context || !death_context->math_random_seed48) {
        ew_store_copy(next_store(m), s);
        return 1;
    }
    m->entity_last_damage[slot] = 0.0F;
    m->entity_hurt_resistant[slot] = 20;
    m->entity_hurt_time[slot] = 10;
    mark_hurt(m, s, slot);
    villager_player_harm_append(m, s, slot, 0);
    m->entity_recently_hit[slot] = 100;
    m->entity_attacking_player[slot] = 1;
    player_attack_fresh_feedback(
        m, s, slot, thrower_x, thrower_z, death_context, 2);
    ew_store_copy(next_store(m), s);
    return 2;
}

static int mob_entity_arrow_hit(
        GmMobLive *m, GmWorld *world, int slot, int shooter_eid,
        double source_x, double source_z, float damage,
        GmLiveSim *drops, const GmMobDeathContext *death_context) {
    EwStore *s;
    int accepted;
    if (!m || !death_context || slot <= 0 || slot >= EW_MAX_ENTITIES
            || damage <= 0.0F)
        return 0;
    s = now_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0;
    if (s->type[slot] == EW_TYPE_ENDERMAN) {
        for (int attempt = 0; attempt < 64; ++attempt)
            if (mob_attempt_enderman_random_teleport(
                    m, world, s, slot)) {
                ew_store_copy(next_store(m), s);
                return 3;
            }
        ew_store_copy(next_store(m), s);
        return 1;
    }
    GmMobDamageEntitySource entity_source = {
        source_x, source_z, death_context,
        shooter_eid, 0, 0, 0, 1,
    };
    accepted = s->type[slot] == EW_TYPE_WITCH
        ? mob_source_damage_witch_slot_exact(
            m, s, slot, damage, drops,
            death_context->math_random_seed48,
            death_context->next_entity_id,
            death_context->do_mob_loot, 0, &entity_source)
        : gm_passive(s->type[slot])
        ? mob_source_damage_passive_slot_exact(
            m, s, slot, damage, drops,
            death_context->math_random_seed48,
            death_context->next_entity_id,
            death_context->do_mob_loot, 0, 1, 0, &entity_source)
        : mob_source_damage_ordinary_slot_exact(
            m, s, slot, damage, drops,
            death_context->math_random_seed48,
            death_context->next_entity_id,
            death_context->do_mob_loot, 0, 1, 0, &entity_source);
    if (accepted <= 0) {
        ew_store_copy(next_store(m), s);
        return accepted < 0 ? 0 : 1;
    }
    ++m->arrow_count[slot];
    if (shooter_eid > 0
            && m->skeleton_trap_vehicle_eid[slot] >= 0) {
        m->skeleton_trap_revenge_eid[slot] = shooter_eid;
        m->skeleton_trap_revenge_running[slot] = 0;
    }
    ew_store_copy(next_store(m), s);
    return 2;
}

int gm_mobs_source_arrow_hit(
        GmMobLive *m, GmWorld *world, int slot,
        double arrow_x, double arrow_z, float damage,
        GmLiveSim *drops, const GmMobDeathContext *death_context) {
    return mob_entity_arrow_hit(
        m, world, slot, -1, arrow_x, arrow_z, damage,
        drops, death_context);
}

int gm_mobs_entity_arrow_hit(
        GmMobLive *m, GmWorld *world, int slot, int shooter_eid,
        double shooter_x, double shooter_z, float damage,
        GmLiveSim *drops, const GmMobDeathContext *death_context) {
    if (shooter_eid <= 0) return 0;
    return mob_entity_arrow_hit(
        m, world, slot, shooter_eid, shooter_x, shooter_z, damage,
        drops, death_context);
}

int gm_mobs_entity_throwable_hit(
        GmMobLive *m, GmWorld *world, int slot, int thrower_eid,
        double thrower_x, double thrower_z, float damage,
        GmLiveSim *drops, const GmMobDeathContext *death_context) {
    EwStore *s;
    int result;
    if (!m || thrower_eid <= 0 || slot <= 0
            || slot >= EW_MAX_ENTITIES || damage < 0.0F)
        return 0;
    s = now_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0;
    m->entity_age[slot] = 0;
    m->entity_limb_swing_amount[slot] = 1.5F;
    if (damage > 0.0F) {
        result = mob_entity_arrow_hit(
            m, world, slot, thrower_eid,
            thrower_x, thrower_z, damage, drops, death_context);
        if (result == 2) {
            if (m->arrow_count[slot] > 0) --m->arrow_count[slot];
            m->hurt_aggro[slot] = 0;
            m->entity_revenge_eid[slot] = thrower_eid;
        }
        return result;
    }
    if (s->type[slot] == EW_TYPE_ENDERMAN) {
        for (int attempt = 0; attempt < 64; ++attempt)
            if (mob_attempt_enderman_random_teleport(
                    m, world, s, slot)) {
                ew_store_copy(next_store(m), s);
                return 3;
            }
        ew_store_copy(next_store(m), s);
        return 1;
    }
    if (m->entity_hurt_resistant[slot] > 10
            && damage <= m->entity_last_damage[slot]) {
        ew_store_copy(next_store(m), s);
        return 1;
    }
    if (!death_context || !death_context->math_random_seed48) {
        ew_store_copy(next_store(m), s);
        return 1;
    }
    m->entity_last_damage[slot] = 0.0F;
    m->entity_hurt_resistant[slot] = 20;
    m->entity_hurt_time[slot] = 10;
    m->entity_max_hurt_time[slot] = 10;
    m->entity_velocity_changed[slot] = 1;
    m->entity_revenge_eid[slot] = thrower_eid;
    mob_event_append(
        m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 2,
        s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
    {
        float pitch = player_attack_primary_knockback(
            m, s, slot, thrower_x, thrower_z, death_context);
        int sound = living_hurt_death_sound_event(
            m, slot, s->type[slot], m->size[slot], 0);
        if (sound)
            mob_event_append(
                m, GM_MOB_EVENT_SOUND, s->id[slot], sound,
                s->x[slot], s->y[slot], s->z[slot],
                living_hurt_death_sound_volume(
                    s->type[slot], m->size[slot]),
                living_hurt_death_sound_pitch(s->type[slot], pitch));
    }
    if (m->skeleton_trap_vehicle_eid[slot] >= 0) {
        m->skeleton_trap_revenge_eid[slot] = thrower_eid;
        m->skeleton_trap_revenge_running[slot] = 0;
    }
    ew_store_copy(next_store(m), s);
    return 2;
}

int gm_mobs_fishing_target_position(
        const GmMobLive *m, int slot, int dimension,
        double *x, double *y, double *z) {
    const EwStore *s;
    float width, height;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES)
        return 0;
    s = const_store(m);
    if (!s->alive[slot] || m->entity_dimension[slot] != dimension
            || !gm_living(s->type[slot]))
        return 0;
    ehs_size_scaled(s->type[slot], m->size[slot], &width, &height);
    (void)width;
    if (x) *x = s->x[slot];
    if (y) *y = s->y[slot] + (double)height * 0.8;
    if (z) *z = s->z[slot];
    return 1;
}

int gm_mobs_fishing_reel(
        GmMobLive *m, int slot, int dimension,
        double angler_x, double angler_y, double angler_z) {
    EwStore *s;
    double dx, dy, dz, distance;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES)
        return 0;
    s = now_store(m);
    if (!s->alive[slot] || m->entity_dimension[slot] != dimension
            || !gm_living(s->type[slot]))
        return 0;
    dx = angler_x - s->x[slot];
    dy = angler_y - s->y[slot];
    dz = angler_z - s->z[slot];
    distance = sqrt(dx * dx + dy * dy + dz * dz);
    s->vx[slot] += dx * 0.1;
    s->vy[slot] += dy * 0.1 + sqrt(distance) * 0.08;
    s->vz[slot] += dz * 0.1;
    return 1;
}

static int mob_fire_immune_type(int type) {
    return type == EW_TYPE_BLAZE || type == EW_TYPE_GHAST
        || type == EW_TYPE_MAGMA || type == EW_TYPE_PIGMAN
        || type == EW_TYPE_WITHER_SKELETON || type == EW_TYPE_VEX;
}

int gm_mobs_small_fireball_hit(
        GmMobLive *m, int slot, float damage, GmLiveSim *drops) {
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES || damage <= 0.0f)
        return 0;
    EwStore *s = now_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot]))
        return 0;
    if (mob_fire_immune_type(s->type[slot])) return 1;
    if (s->type[slot] == EW_TYPE_BOAT) {
        m->boat_damage[slot] += damage * 10.0F;
        if (m->boat_damage[slot] > 40.0F) mob_drop(m, s, slot, drops);
        ew_store_copy(next_store(m), s);
        return 1;
    }
    if (s->type[slot] == EW_TYPE_BAT && m->bat_hanging[slot])
        m->bat_hanging[slot] = 0;
    float applied;
    int accepted = 1;
    if (m->entity_hurt_resistant[slot] > 10) {
        if (damage <= m->entity_last_damage[slot]) {
            accepted = 0;
            applied = 0.0f;
        } else {
            applied = damage - m->entity_last_damage[slot];
            m->entity_last_damage[slot] = damage;
        }
    } else {
        applied = damage;
        m->entity_last_damage[slot] = damage;
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
    }
    if (accepted) {
        applied = mob_resistance_damage(m, slot, applied);
        applied = mob_absorb_damage(m, slot, applied);
        s->health[slot] -= applied;
        mark_hurt(m, s, slot);
        if (m->fire_ticks[slot] < 5 * 20)
            m->fire_ticks[slot] = 5 * 20;
        if (s->health[slot] <= 0.0f) mob_drop(m, s, slot, drops);
    }
    ew_store_copy(next_store(m), s);
    return 1;
}

int gm_mobs_wither_skull_hit(
        GmMobLive *m, int slot, float damage, GmLiveSim *drops) {
    EwStore *s;
    float applied;
    int accepted = 1;
    int fresh;
    if (!m || slot <= 0 || slot >= EW_MAX_ENTITIES || damage <= 0.0F)
        return 0;
    s = now_store(m);
    if (!s->alive[slot] || m->entity_dead[slot]
            || s->health[slot] <= 0.0F || !gm_living(s->type[slot])
            || s->type[slot] == EW_TYPE_BOAT)
        return 0;
    if (s->type[slot] == EW_TYPE_BAT && m->bat_hanging[slot])
        m->bat_hanging[slot] = 0;
    fresh = m->entity_hurt_resistant[slot] <= 10;
    if (!fresh) {
        if (damage <= m->entity_last_damage[slot]) {
            accepted = 0;
            applied = 0.0F;
        } else {
            applied = damage - m->entity_last_damage[slot];
            m->entity_last_damage[slot] = damage;
        }
    } else {
        applied = damage;
        m->entity_last_damage[slot] = damage;
        m->entity_hurt_resistant[slot] = 20;
        m->entity_hurt_time[slot] = 10;
    }
    if (accepted) {
        applied = mob_resistance_damage(m, slot, applied);
        applied = mob_absorb_damage(m, slot, applied);
        s->health[slot] -= applied;
        mark_hurt(m, s, slot);
        if (fresh) {
            JavaRandom *random = &m->entity_random[slot].random;
            int lethal = s->health[slot] <= 0.0F;
            /* EntityLivingBase.setBeenAttacked and knockBack each perform a
             * knockback-resistance trial before EntityLiving.playHurtSound.
             * Runtime explosion geometry owns the already-combined impulse;
             * retain the target's exact private cursor and causal feedback. */
            (void)jrand_double(random);
            (void)jrand_double(random);
            float first = jrand_float(random);
            float second = jrand_float(random);
            m->entity_living_sound_time[slot] =
                -living_talk_interval(s->type[slot]);
            mob_event_append(
                m, GM_MOB_EVENT_ENTITY_STATUS, s->id[slot], 2,
                s->x[slot], s->y[slot], s->z[slot], 0.0F, 0.0F);
            int sound = living_hurt_death_sound_event(
                m, slot, s->type[slot], m->size[slot], lethal);
            if (sound)
                mob_event_append(
                    m, GM_MOB_EVENT_SOUND, s->id[slot], sound,
                    s->x[slot], s->y[slot], s->z[slot],
                    living_hurt_death_sound_volume(
                        s->type[slot], m->size[slot]),
                    living_hurt_death_sound_pitch(
                        s->type[slot],
                        (first - second) * 0.2F + 1.0F));
        }
        if (s->health[slot] <= 0.0F) {
            mob_drop(m, s, slot, drops);
            ew_store_copy(next_store(m), s);
            return 2;
        }
    }
    ew_store_copy(next_store(m), s);
    return 1;
}

int gm_mobs_damage_near(GmMobLive *m,double x,double y,double z,double radius,
                        float damage,GmLiveSim *drops){
    if(!m)return 0;
    EwStore *s=now_store(m);int best=-1,best_eid=-1;double bd=radius*radius;
    int cursor=0,i;
    while((i=gm_mobs_living_next_slot(m,&cursor))>0){
        s=now_store(m);
        if(s->alive[i] && !m->entity_dead[i] && s->health[i] > 0.0F
                && m->entity_dimension[i]==m->active_dimension&&gm_living(s->type[i])&&
                                         s->type[i]!=EW_TYPE_BOAT){
        double dx=s->x[i]-x,dy=(s->y[i]+0.9)-y,dz=s->z[i]-z,d=dx*dx+dy*dy+dz*dz;
        if(d<=bd){bd=d;best_eid=s->id[i];}
        }
    }
    gm_mobs_living_cold_flush(m);
    best=mob_slot_by_eid(m,best_eid);s=now_store(m);
    if(best<0)return 0;
    {
        float applied = mob_resistance_damage(m, best, damage);
        applied = mob_absorb_damage(m, best, applied);
        s->health[best] -= applied;
    }
    mark_hurt(m,s,best);
    if(s->health[best]<=0)mob_drop(m,s,best,drops);
    ew_store_copy(next_store(m),s);return 1;
}

int gm_mobs_take_explosion(GmMobLive *m,double *x,double *y,double *z){
    if(!m||!m->explosion_pending)return 0;
    if(x)*x=m->explosion_x;
    if(y)*y=m->explosion_y;
    if(z)*z=m->explosion_z;
    m->explosion_pending=0;return 1;
}

int gm_mobs_take_fireball(GmMobLive *m,double *x,double *y,double *z,
                          double *vx,double *vy,double *vz){
    /* Returns pending kind: 0=none, 3=small fireball, 5=large fireball. */
    if(!m||!m->fireball_pending)return 0;
    int kind=m->fireball_pending;
    if(x)*x=m->fireball_x;if(y)*y=m->fireball_y;if(z)*z=m->fireball_z;
    if(vx)*vx=m->fireball_vx;if(vy)*vy=m->fireball_vy;if(vz)*vz=m->fireball_vz;
    m->fireball_pending=0;return kind;
}
